P.entries["quest:94615"] = {n="Foal Play",s="Auf Wheeler's Grange sind die Pferde aus den Ställen verschwunden. Ihr sucht nach Hinweisen, um herauszufinden, was geschehen ist.",h="Auf Wheeler's Grange sind die Pferde aus den Ställen verschwunden.",kw={"kojoten","farholde","fohlenstreiche","pferde","verschwundene pferde","murlocs","ställe","wheeler's grange"},sec={{t="Eine Suche auf dem Gut",b="Die Ställe auf Wheeler's Grange könnten Hinweise auf die verschwundenen Pferde bergen. Ihr Hüter sagt, sie seien fort gewesen, als er aufstand, um sie zu füttern. Draußen vor Farholde könnten Tiere, Murlocs, Orcs oder andere Gefahren daran schuld sein. Ihr sucht in der Nähe der Ställe, um einzugrenzen, was geschehen ist."}},faq={{q="Wohin sind die Pferde gegangen?",a="Die Pferde sind von Wheeler's Grange verschwunden, und Ihr sucht in der Nähe der Ställe nach Hinweisen darauf, wohin sie gegangen sind.",al={"verschwundene pferde","pferde verschwunden","wo sind die pferde"}},{q="Was könnte die Pferde mitgenommen haben?",a="Der Hüter hält Tiere, Murlocs, Orcs oder andere Gefahren außerhalb Farholdes für mögliche Täter.",al={"wer nahm die pferde","schuld an den pferden","was hat sie erwischt"}},{q="Warum sind die Pferde wichtig?",a="Der Hüter bestreitet seinen Lebensunterhalt mit den Pferden.",al={"warum pferde wichtig sind","pferde lebensunterhalt","pferdegeschäft"}},{q="Wo sollt Ihr nach Hinweisen suchen?",a="Sucht in der Nähe der Ställe auf Wheeler's Grange nach Hinweisen zu den verschwundenen Pferden.",al={"hinweise im stall","wo suchen","fohlenstreiche"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="Wassersapta",s="In Westfall nehmt Ihr den Water Sapta, um einen gestörten Teich aufzusuchen. Der zeremonielle Trank schärft Euren Blick für Wassergeister und verborgene Verderbnis, damit Ihr das Ungleichgewicht untersuchen könnt.",h="In Westfall nehmt Ihr den Water Sapta, um einen gestörten Teich aufzusuchen.",kw={"elementare einstimmung","sapta","schamanenprüfung","verdorbener teich","water sapta","wassergeister","westfall"},ang={["class:Shaman"]="Als Schamane könnt Ihr einen Sapta verwenden, um Eure spirituellen Sinne auf Elementargeister einzustimmen, die dem gewöhnlichen Blick verborgen bleiben.",["faction:Alliance"]="Als Mitglied der Allianz untersucht Ihr verdorbene Gewässer in Westfall und bringt elementare Reinigungsriten in die Lande der Allianz."},sec={{t="Die Sicht der Wasser",b="Schamanen bereiten einen Sapta zu, um über die körperliche Welt hinauszublicken. Der Water Sapta stimmt Eure Sinne auf Wasser ein und offenbart Störungen und Geister, die gewöhnlichen Reisenden verborgen bleiben. Ohne diesen veränderten Blick könnte eine elementare Präsenz wie bloßes Wellengekräusel wirken."},{t="Störung in Westfall",b="Der Water Sapta führt Euch nach Westfall, einem dürren Reich der Allianz, das von Unruhe und Vernachlässigung geplagt wird. Ein Teich dort birgt spirituell verunreinigtes Wasser. Mit der Sicht des Saptas sucht Ihr das verdorbene Wasser auf, deckt die Störung auf und stellt die Harmonie mit den örtlichen Wassergeistern wieder her."}},faq={{q="Was ist ein Water Sapta?",a="Ein Water Sapta ist ein zeremonielles Gebräu, das Euren spirituellen Blick auf Wassergeister und Störungen einstimmt, die sterblichen Augen verborgen bleiben.",al={"was ist ein water sapta","water sapta zweck","was bewirkt water sapta"}},{q="Wo liegt der verdorbene Teich in Westfall?",a="Der verdorbene Teich liegt in Westfall. Der Water Sapta führt Euch dorthin, um das verdorbene Wasser zu finden und Euch der spirituellen Störung anzunehmen.",al={"wo liegt der verdorbene teich","verdorbener teich westfall","verdorbener teich fundort"}},{q="Warum führt der Water Sapta nach Westfall?",a="Der Water Sapta führt Euch nach Westfall, weil ein Teich dort verdorbenes Wasser birgt. Ihr untersucht die Verderbnis und versucht, das Gleichgewicht der geplagten Geister wiederherzustellen.",al={"warum nach westfall gehen","westfall wasserverderbnis","warum ist westfalls wasser verdorben"}},{q="Wer verwendet den Water Sapta?",a="Schamanen verwenden Water Saptas bei Prüfungen der Zwiesprache mit den Elementen. Der Trank stimmt ihre Sinne auf Wassergeister ein und hilft ihnen, verborgene Elementare wahrzunehmen und verdorbene Wasserbecken zu untersuchen.",al={"wer trinkt water sapta","wer verwendet water sapta","schamane sapta trinken"}},{q="Was geschieht, wenn Ihr den Sapta zum verdorbenen Teich bringt?",a="Nahe dem verdorbenen Teich in Westfall verleiht der Water Sapta elementare Sicht. Er offenbart den spirituellen Zustand des Wassers oder ruft verborgene Geister herbei, die mit der örtlichen Wasserprüfung verbunden sind.",al={"was geschieht nach der verwendung von sapta","sapta elementare sicht"}},{q="Wie wirken elementare Saptas in der schamanischen Tradition?",a="Saptas sind zeremonielle Tränke, die Schamanen auf ein Element einstimmen und die körperliche Welt mit dem Geisterreich verbinden. Schamanen verwenden sie bei Prüfungen für Erde, Feuer, Wasser oder Luft.",al={"wie wirken saptas","sapta hintergrundgeschichte"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94617"] = {n="Coyote Huntin'",s="Benjy Wheeler bittet Euch, Sootfur zu erledigen, den dunkelpelzigen Anführer eines Kojotenrudels westlich des Flusses. Die Kojoten fressen nun Pferde, nachdem Murlocs sie von ihrem üblichen Fischgrund vertrieben haben.",h="Benjy Wheeler bittet Euch, Sootfur zu erledigen, den dunkelpelzigen Anführer eines Kojotenrudels westlich des...",kw={"benjy wheeler","kojote","höhle","pferde","murlocs","fell","sootfur","stallungen"},sec={{t="Eine Gefahr für die Pferde",b="Benjy Wheeler sagt, die Kojoten hätten einst am Ufer Fische gejagt, doch Murlocs hätten sie von diesem Nahrungsgrund vertrieben. Nun hat das Rudel begonnen, Pferde zu fressen. Sein Anführer ist ein größerer, dunkelpelziger Kojote namens Sootfur. Benjy bittet Euch, Sootfurs Fell zurückzubringen, in der Hoffnung, dass sich der Rest des Rudels zerstreut."},{t="Benjys Stallungen",b="Als Ihr mit Sootfurs Fell zurückkehrt, sagt Benjy, der Kojote habe in seinen Stallungen herumgewühlt. Er dankt Euch und sagt, er erwarte, dass die Pferde wieder sicher seien, sobald die Stallungen wieder in Betrieb sind."}},faq={{q="Wer ist Sootfur?",a="Sootfur ist der größere, dunkelpelzige Anführer des Kojotenrudels westlich des Flusses.",al={"sootfur","dunkler kojote","kojotenanführer"}},{q="Warum fressen die Kojoten Pferde?",a="Murlocs vertrieben die Kojoten von ihrem üblichen Fischgrund am Ufer, deshalb begannen sie, Pferde zu fressen.",al={"warum pferde","kojoten fressen pferde","kojotenfutter"}},{q="Wer verlangt Sootfurs Fell?",a="Benjy Wheeler bittet Euch, ihm Sootfurs Fell zu bringen.",al={"benjy","wer ist benjy","sootfurs fell"}},{q="Wo ist die Kojotenhöhle?",a="Das Rudel lebt in einer Höhle westlich von Benjys Standort, jenseits des Flusses.",al={"kojotenhöhle","wo sind kojoten","höhlenstandort"}}},fp="14,202,22.300.0,15.190.1,15.79.0,34.109.0,28.51.0,24.67.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy bittet Euch, ein Pferd zu finden, das nach einem Kojotenangriff von Wheeler's Grange geflohen ist. Füttert es, damit es Euch vertraut und Ihr es zurückführen könnt.",h="Benjy bittet Euch, ein Pferd zu finden, das nach einem Kojotenangriff von Wheeler's Grange geflohen ist.",kw={"benjy","kojoten","futter","geflüchtete pferde","pferde","wheeler's fliehende rösser","wheeler's grange"},sec={{t="Von der Grange geflohen",b="Benjy bei Wheeler's Grange braucht Eure Hilfe, um eines der Pferde zu finden, die vor dem Kojotenangriff flohen. Kojoten haben einige Pferde erbeutet, während andere aus Angst davonliefen. Gebt einem Pferd etwas Futter, damit es Euch vertraut und Ihr es zurückführen könnt."}},faq={{q="Was ist mit den Pferden geschehen?",a="Die Kojoten haben die meisten Pferde erwischt, während einige aus Angst von Wheeler's Grange flohen.",al={"pferde bei wheeler's grange","pferde beim kojotenangriff"}},{q="Wer bittet um Hilfe?",a="Benjy bittet Euch, ein Pferd zu finden, das von Wheeler's Grange floh.",al={"wer hat mir das gegeben","benjys pferde"}},{q="Was soll ich mit dem Futter machen?",a="Gebt einem Pferd etwas Futter, damit es Euch vertraut und Ihr es zurückführen könnt.",al={"wie benutze ich den sack","pferd füttern"}},{q="Warum werden die Pferde gesucht?",a="Benjy sagt, die entlaufenen Pferde sollten gefunden werden, bevor die Kojoten zurückkehren.",al={"warum pferde finden","wo sind sie hingelaufen"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Ur'endras Gefährte bittet Euch, ihr Leiden zu beenden, nachdem sie dem Wahnsinn verfallen ist. Eure Entschlossenheit bringt Euch einen Segen ein, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt.",h="Ur'endras Gefährte bittet Euch, ihr Leiden zu beenden, nachdem sie dem Wahnsinn verfallen ist.",kw={"druidensegen","böenbeerentiefland","gestalt der klaue","shen'darhochland","stärke und gnade","ur'endra","magie der winde"},ang={["class:Druid"]="Als Druide sollt Ihr Eure Entschlossenheit beweisen, bevor Ihr einen Segen erhaltet, mit dem Ihr die Gestalt der Artgenossen des Druiden annehmen könnt."},sec={{t="Eine schwere Bitte",b="Ein Druide bittet Euch, Ur'endras Leiden im Shen'darhochland zu beenden. Sie ist seine Gefährtin, doch der Wahnsinn hat sie gegen ihre eigenen Artgenossen aufgebracht. Der Verlust der Magie der Winde hat viele Geschöpfe dazu gebracht, sich selbst zu verlieren, und Ur'endra gehört zu ihnen. Ihr Unterschlupf liegt in einer Höhle westlich von hier, an den Steilhängen zwischen dem Shen'darhochland und dem Böenbeerentiefland."},{t="Der Segen",b="Im Shen'darhochland trauert Ur'endras Gefährte um ihren Verlust und nennt ihn notwendig für das Gleichgewicht. Er erkennt Eure Entschlossenheit darin, dass Ihr einen so schrecklichen Preis hinnehmt. Er gewährt Euch einen Segen, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt, und trägt Euch auf, den Schwachen beizustehen und die Bedürftigen zu verteidigen."}},faq={{q="Wer ist Ur'endra?",a="Ur'endra ist die Gefährtin des Druiden, der Euch bittet, ihr Leiden zu beenden.",al={"ur'endra","wer ist urendra","gefährtin des druiden"}},{q="Warum greift Ur'endra ihre Artgenossen an?",a="Ur'endra ist dem Wahnsinn verfallen. Der Verlust der Magie der Winde hat viele Geschöpfe dazu gebracht, sich selbst zu verlieren.",al={"warum ist urendra wahnsinnig","urendra greift an","was ist mit urendra geschehen"}},{q="Wo ist Ur'endras Unterschlupf?",a="Ur'endra hat ihren Unterschlupf in einer Höhle westlich des Druiden, in den Steilhängen zwischen dem Shen'darhochland und dem Böenbeerentiefland.",al={"urendra höhle","wo ist urendra","shen'dar höhle"}},{q="Was soll ich für den Druiden tun?",a="Der Druide bittet Euch, Ur'endras Leiden zu beenden.",al={"urendra aufgabe","was ist zu tun","urendra töten"}},{q="Welchen Segen gewährt der Druide?",a="Der Druide gewährt Euch einen Segen, mit dem Ihr die Gestalt seiner Artgenossen annehmen könnt.",al={"gestaltsegen","weg der klaue","druidensegen"}},{q="Warum bittet der Druide darum?",a="Der Druide hält es für notwendig, Ur'endras Leiden zu beenden, um das Gleichgewicht zu wahren.",al={"warum urendra töten","warum ist das notwendig","gleichgewicht"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="Am Bloodmaster's Ring meldet Ihr Euch bei Jezap, nachdem Ihr Euch gegen Twilight ogres bewiesen habt. Der Bloodmaster ist bereit zu urteilen, ob Ihr dazugehört.",h="Am Bloodmaster's Ring meldet Ihr Euch bei Jezap, nachdem Ihr Euch gegen Twilight ogres bewiesen habt.",kw={"bloodmaster","bloodmaster's ring","goblin","jezap","abgrund der macht","twilight ogres"},sec={{t="Am Ring",b="Die Herausforderung am Bloodmaster's Ring hat Euch zu Jezap geführt, dem Goblin des Rings. Nachdem Ihr die Twilight-Oger besiegt habt, erstattet Ihr ihm Bericht, während der Bloodmaster und Jezap zusehen. Sie entscheiden, ob Ihr zu denen gehört, die sich dem Abgrund der Macht nähern."}},faq={{q="Bei wem melde ich mich am Bloodmaster's Ring?",a="Ihr meldet Euch bei Jezap am Bloodmaster's Ring.",al={"wer ist jezap","bei jezap melden","bloodmaster's ring goblin"}},{q="Was habe ich getan, bevor ich hierherkam?",a="Ihr habt Twilight ogres zerschmettert, die als schwach beurteilt wurden.",al={"was vorher geschah","twilight ogres","vorheriger schritt am ring"}},{q="Wonach sucht der Bloodmaster?",a="Der Bloodmaster beurteilt, ob Ihr an den Abgrund der Macht gehört.",al={"mich beweisen","was will der bloodmaster","gehöre ich dazu"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="Ein Sammler verlangt ein Sicherheitsdepot, bevor Ihr den Bloodmaster's Ring betreten dürft. Zahlt, und Ihr könnt dort Eure Stärke beweisen.",h="Ein Sammler verlangt ein Sicherheitsdepot, bevor Ihr den Bloodmaster's Ring betreten dürft.",kw={"bloodmaster's ring","clugfist","pay to play","stärke beweisen","ring","sicherheitsdepot"},sec={{t="Der Preis für den Eintritt",b="Um den Bloodmaster's Ring zu betreten, sollt Ihr ein Sicherheitsdepot zahlen. Der Sammler sagt, die Zahlung sei zu Eurer Sicherheit erforderlich. Ohne sie droht er, Clugfist zu erzählen, dass Ihr Euch geweigert habt, Eure Stärke vor der willkommen heißenden Gesellschaft zu beweisen. Eure Entscheidung bestimmt, ob Ihr Euch für den Ring qualifiziert."}},faq={{q="Warum muss ich zahlen?",a="Der Sammler sagt, ein Sicherheitsdepot sei zu Eurer Sicherheit und für die Qualifikation zum Bloodmaster's Ring erforderlich.",al={"warum zahlen","sicherheitsdepot","quest pay to play"}},{q="Wer ist Clugfist?",a="Clugfist ist die Person, von der der Sammler droht, ihr zu erzählen, falls Ihr Euch weigert zu zahlen.",al={"wer ist clugfist","clugfist","alter clugfist"}},{q="Was geschieht, wenn ich mich weigere?",a="Der Sammler sagt, er werde Clugfist erzählen, dass Ihr nicht bereit wart, Eure Stärke zu beweisen.",al={"nicht zahlen","depot ablehnen","kein depot"}},{q="Wofür qualifiziere ich mich durch die Zahlung?",a="Mit der Zahlung des Sicherheitsdepots qualifiziert Ihr Euch für den Bloodmaster's Ring.",al={"wofür qualifizieren","eintritt in den ring","bloodmaster ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Die Herausforderung von Bloodmaster's Ring schickt Euch gegen Buzzbeak ins Feld, mit Ruhm als möglichem Lohn. Der Goblin des Rings erwartet einen leichten Kampf.",h="Die Herausforderung von Bloodmaster's Ring schickt Euch gegen Buzzbeak ins Feld, mit Ruhm als möglichem Lohn.",kw={"bloodmaster","bloodmaster's ring","buzzbeak","ruhm","scheusal","kampf","ring"},sec={{t="In den Ring",b="Der Goblin des Rings stellt Euch Buzzbeak im Ring entgegen. Man sagt Euch, dieser erste Kampf sollte leicht sein, doch der Unhold soll seinen Gegner zu Fall bringen und dessen Habseligkeiten an sich nehmen. Allen, die antreten, wird Ruhm versprochen."}},faq={{q="Gegen wen kämpfe ich in Bloodmaster's Ring?",a="In Bloodmaster's Ring tretet Ihr gegen Buzzbeak an.",al={"kampf des bloodmaster","wer ist buzzbeak","gegner im ring"}},{q="Was soll Buzzbeak tun?",a="Buzzbeak wird als flatterhaftes Scheusal beschrieben, das Euch zu Fall bringen und Eure Habseligkeiten nehmen kann.",al={"buzzbeaks angriff","was tut buzzbeak","scheusal im ring"}},{q="Warum den Ring betreten?",a="Der Goblin des Rings verspricht allen Ruhm, die den Ring betreten.",al={"ruhm im ring","ruhm des bloodmaster","warum gegen buzzbeak kämpfen"}},{q="Soll dieser Kampf leicht sein?",a="Der Goblin des Rings stellt dies als leichten ersten Kampf dar.",al={"leichter ringkampf","bloodmaster leicht","buzzbeak schwierig"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul warnt, dass Twilight's Hammer eine menschliche Siedlung westlich von Rog'mar angegriffen hat. Ihr sollt nach Sonnengrund, um die Kultisten auszudünnen, bevor sie sich in der Nähe festsetzen.",h="Tran'gul warnt, dass Twilight's Hammer eine menschliche Siedlung westlich von Rog'mar angegriffen hat.",kw={"encroaching twilight","menschliche siedlung","rog'mar","sonnengrund","tran'gul","twilight's hammer-neophyten","twilight's hammer-plünderer","twilight's hammer"},sec={{t="Eine Gefahr in der Nähe",b="Die menschliche Siedlung im Westen wurde bereits verwüstet, und Rog'mar könnte das nächste Ziel sein. Tran'gul schickt Euch nach Sonnengrund, wo Twilight's Hammer seinen Feldzug gegen jene begonnen hat, die der Kult für Ketzer hält. Seine Plünderer und Neophyten drohen, sich nahe Rog'mar festzusetzen."},{t="Nach dem Kampf",b="Da die Reihen des Kults geschwächt sind, kann Tran'gul der Quelle seiner beispiellosen Ausbreitung nachgehen."}},faq={{q="Um wen sorgt sich Tran'gul?",a="Tran'gul fürchtet Twilight's Hammer, einen Kult, der jene angreift, die er für Ketzer hält.",al={"wer ist die bedrohung","bedrohung durch twilight's hammer"}},{q="Was ist mit der menschlichen Siedlung geschehen?",a="Twilight's Hammer hat eine menschliche Siedlung westlich von Rog'mar verwüstet.",al={"siedlung im westen","was geschah im westen"}},{q="Warum soll ich nach Sonnengrund?",a="Tran'gul schickt Euch nach Sonnengrund, um die Reihen von Twilight's Hammer auszudünnen.",al={"warum sonnengrund","was gibt es in sonnengrund"}},{q="Wen könnte der Kult als Nächstes angreifen?",a="Tran'gul fürchtet, dass Rog'mar nach der menschlichen Siedlung im Westen das nächste Ziel sein könnte.",al={"wer ist als nächstes dran","rog'mar als nächstes"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94678"] = {n="Gnoll Infestation",s="Cedric Dalton bei Southern Watch bittet Euch, die Gnolle im Rotkammgebirge zu dezimieren. Ihre Zahl macht den nördlichen Durchgang gefährlich und bedroht die Menschen jenseits der Burg Farholde.",h="Cedric Dalton bei Southern Watch bittet Euch, die Gnolle im Rotkammgebirge zu dezimieren.",kw={"cedric dalton","burg farholde","gnollplage","gnolle","nördlicher durchgang","redridge brutes","redridge mystics","redridge trappers","southern watch"},sec={{t="Eine Gefahr in der Nähe",b="Cedric Dalton bei Southern Watch sieht sich jenseits des Außenpostens Gnollen gegenüber, die sich über die Hügel ausbreiten. Ihre Zahl macht den Durchgang nach Norden gefährlich, und die Menschen außerhalb der Burg Farholde sind bedroht. Ihr sollt ihren Einfluss in der Gegend schwächen, indem Ihr Redridge Mystics, Redridge Trappers und Redridge Brutes tötet."}},faq={{q="Warum sind die Gnolle ein Problem?",a="Die Gnolle sind aggressiv und zahlreich. Sie machen den Durchgang nach Norden gefährlich und bedrohen die Menschen, die außerhalb der Burg Farholde leben.",al={"warum gnolle","gefährliche gnolle","gnollplage"}},{q="Wer bittet mich, mich um die Gnolle zu kümmern?",a="Cedric Dalton bei Southern Watch bittet Euch, die Bedrohung durch die Gnolle einzudämmen.",al={"wer gab den gnollauftrag","cedric dalton","gnolle bei southern watch"}},{q="Um welche Gnolle geht es?",a="Als zu tötende Gnolle werden Redridge Mystics, Redridge Trappers und Redridge Brutes genannt.",al={"gnollarten","gnolle im rotkammgebirge","mystiker fallensteller schläger"}},{q="Wo sind die Gnolle?",a="Sie haben die Hügel jenseits von Southern Watch heimgesucht und machen den Durchgang nach Norden gefährlich.",al={"aufenthaltsort der gnolle","wo sind sie","hügel jenseits des außenpostens"}}},fp="17,161,15.266.0,29.123.0,36.68.0,26.93.0,21.83.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="Cedric Dalton bei Southern Watch möchte Snargls Schnauze aus den Borstenhügeln. Er glaubt, dass die Tötung eines starken Gnolls die Reihen im Rotkammgebirge schwächen und den Gnollen Angst einjagen wird.",h="Cedric Dalton bei Southern Watch möchte Snargls Schnauze aus den Borstenhügeln.",kw={"borstenhügel","cedric dalton","gnoll","rotkammgebirge","snargl","snargls schnauze","southern watch"},sec={{t="Ein Gnoll in den Hügeln",b="Bei Southern Watch bittet Cedric Dalton Euch, Snargl zu erledigen, einen berüchtigten Gnoll in einem Bau in den Borstenhügeln. Er glaubt, dass Gnolle Stärke über alles stellen und Snargls Tod die Reihen im Rotkammgebirge schwächen und ihnen Angst einjagen könnte. Cedric möchte, dass Ihr Snargls Schnauze zurückbringt."},{t="Eine Trophäe kehrt zurück",b="Cedric nimmt Snargls Schnauze als Trophäe entgegen und sagt, sie werde bald eingesetzt. Der Tod des Gnolls soll Angst in den Reihen des Rotkammgebirges verbreiten."}},faq={{q="Wer ist Snargl?",a="Snargl ist ein berüchtigter Gnoll in einem Bau in den Borstenhügeln.",al={"wer ist snargl","snargl gnoll","gnoll in den borstenhügeln"}},{q="Wer möchte Snargls Schnauze?",a="Cedric Dalton bei Southern Watch bittet Euch, ihm Snargls Schnauze zu bringen.",al={"für wen ist snargls schnauze","cedric daltons auftrag","schnauze bei southern watch"}},{q="Warum will Cedric Snargl tot sehen?",a="Cedric glaubt, dass Gnolle Stärke über alles stellen und dass die Tötung ihres Stärksten sie schwächen und ihnen Angst einjagen wird.",al={"warum snargl töten","stärke der gnolle","rotkammgebirge einschüchtern"}},{q="Wo ist Snargl?",a="Snargl ist in einem Bau in den Borstenhügeln.",al={"snargls ort","wo ist snargl","bau in den borstenhügeln"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul will herausfinden, warum es rund um Sonnengrund mehr Kultisten des Twilight's Hammer gibt. Er bittet Euch, ihre Schreiben zu holen, damit er erfährt, wonach sie suchen.",h="Tran'gul will herausfinden, warum es rund um Sonnengrund mehr Kultisten des Twilight's Hammer gibt.",kw={"kultisten","schreiben","rog'mar","sonnengrund","tran'gul","twilight missives","twilight shadowmancers","twilight's hammer"},sec={{t="Twilight Missives",b="Tran'gul hat in der Gegend mehr Kultisten des Twilight's Hammer gesehen als früher. Ihre Twilight Shadowmancers sind angesehene Mitglieder des Ordens und könnten etwas über dessen Feldzug wissen. Ihr sollt ihre Schreiben holen, damit Tran'gul herausfinden kann, wonach der Kult sucht."}},faq={{q="Wer bittet um die Twilight Missives?",a="Tran'gul in Rog'mar bittet Euch, in Sonnengrund Schreiben von Twilight Shadowmancers zu bergen.",al={"wer will die schreiben","tran'gul bittet darum","wer ist tran'gul"}},{q="Wo finde ich die Twilight Shadowmancers?",a="Die Twilight Shadowmancers sind in Sonnengrund.",al={"standort der twilight shadowmancers","wo sind die kultisten des twilight's hammer","schreiben aus sonnengrund"}},{q="Warum will Tran'gul die Schreiben?",a="Tran'gul möchte mehr über die Kultisten und ihre Ziele erfahren.",al={"warum die schreiben holen","was will tran'gul wissen","kultistenpapiere"}},{q="Warum sorgen die Kultisten Tran'gul?",a="Tran'gul hat mehr Kultisten des Twilight's Hammer gesehen als früher, und sie scheinen sich ermutigt zu fühlen, ihren Einfluss auszuweiten.",al={"warum sind die kultisten des twilight's hammer hier","kultisten werden mehr","zahl der kultisten des twilight's hammer"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="Höhlenpilze",s="An der Dunkelküste werden Höhlenpilze für einen Trank benötigt, den Barithras Mondschatten in Auberdine zubereitet. Er bittet Euch, seltene Pilze hinter den Cliffspring Falls zu sammeln und Warnungen aus dem Hain der Uralten nachzugehen.",h="An der Dunkelküste werden Höhlenpilze für einen Trank benötigt, den Barithras Mondschatten in Auberdine...",kw={"auberdine","barithras mondschatten","höhlenpilze","cliffspring falls","dunkelküste","todeskappe","der hain der uralten","onu","schorfstängel"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Auberdine der wichtigste Stützpunkt der Allianz an der Küste Kalimdors ist. Ein Übel, das sich in den östlichen Bergen ausbreitet, bedroht die gesamte Küste.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr die Suche nach Todeskappen und Schorfstängeln vielleicht zu schätzen. Diese Pilze wachsen in dunklen Höhlen statt auf üppigem Waldboden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Hain der Uralten eng mit dem natürlichen Gleichgewicht der Dunkelküste verbunden ist. Jede Störung unterhalb der Wasserfälle beunruhigt die Kaldorei."},sec={{t="Ein Rezept hinter den Wasserfällen",b="Barithras Mondschatten benötigt Schorfstängel und eine Todeskappe für eine wirkungsvolle Mischung. Beide wachsen in einer feuchten Höhle hinter den Cliffspring Falls im Nordosten der Dunkelküste. Sie zu sammeln ist gefährlicher, als gewöhnliche Waldkräuter zu pflücken."},{t="Die Warnung der Uralten",b="Die Baumwächter im Hain der Uralten warnten Barithras davor, die Höhle zu betreten. Sie spüren eine üble Präsenz in den Berghöhlen. Mondschatten schickt Euch los, um herauszufinden, ob die Ältesten zu Recht ein schleichendes Übel im Norden der Dunkelküste fürchten."}},faq={{q="Wo beginnt diese Aufgabe?",a="Barithras Mondschatten gibt Euch den Auftrag in Auberdine, der Nachtelfensiedlung an der mittleren Küste der Dunkelküste.",al={"wo höhlenpilze annehmen","barithras mondschatten standort","höhlenpilze questbeginn"}},{q="Wo sind die Pilze zu finden?",a="Die Pilze wachsen in einer Höhle hinter den Cliffspring Falls, an der Bergflanke nordöstlich von Auberdine.",al={"wo sind schorfstängel","todeskappe fundort","höhle hinter wasserfall dunkelküste"}},{q="Warum holt Barithras Mondschatten die Pilze nicht selbst?",a="Der Hain der Uralten warnte Barithras davor, sich den Wasserfällen zu nähern. Die großen Uralten spüren, dass ein unnatürliches, erstarkendes Übel in der Höhle Zuflucht gefunden hat.",al={"warum barithras nicht hingeht","warum barithras in auberdine bleibt"}},{q="Welche Pilze werden genau benötigt?",a="Mondschatten benötigt fünf Schorfstängel und eine gefährliche Todeskappe für seinen Trank.",al={"benötigte pilze","welche pilze für mondschatten"}},{q="Was folgt auf diesen Botengang?",a="Nachdem Ihr die Präsenz in der Höhle bestätigt und die Pilze abgeliefert habt, reist Ihr nach Süden zu Onu, dem uralten Beschützer im Hain der Uralten.",al={"nächste quest nach höhlenpilze","onu folgequest"}},{q="Warum sind die Uralten wegen der Cliffspring Falls besorgt?",a="Der Hain der Uralten warnte Barithras, dass ein erstarkendes Übel in der Höhle hinter den Wasserfällen lauern könnte. Er bittet Euch, Pilze zu sammeln und der Warnung nachzugehen.",al={"warnung der uralten cliffspring falls","warum höhle erkunden"}}},fx={a048db56={q="Warum möchte Barithras Mondschatten, dass dies getan wird?",a="Barithras Mondschatten ist ein Kräuterkundiger, der einen starken neuen Trank zusammenbraut, für den seltene Pilze benötigt werden, die nur in der Höhle hinter Cliffspring Falls zu finden sind. Neben seiner alchemistischen Arbeit hegt er jedoch eine tiefere Sorge: Die Grove of the Ancients hat ihn gewarnt, dass in genau dieser Höhle ein aufkommendes Übel lauert. Indem er Euch ausschickt, um die Zutaten zu sammeln, hofft er auch zu erfahren, ob die düsteren Vorzeichen der Ältesten wahr sind.",al={"warum will barithras cave mushrooms","barithras mondschatten beweggrund","warum pilze für barithras sammeln"}},["991c4c10"]={q="Wozu dient die Todeskappe?",a="Die Todeskappe ist ein außergewöhnlich seltener und stark giftiger Pilz, der in der Höhle hinter Cliffspring Falls heimisch ist. Barithras Mondschatten benötigt ein makelloses Exemplar als wichtiges Reagenz für einen speziellen Trank, den er in Auberdine herstellt.",al={"wozu dient die todeskappe","zweck der todeskappe","warum braucht barithras eine todeskappe"}},be6516db={q="Wozu dient der Schorfstängling?",a="Schorfstänglinge sind seltene Pilze, die in der feuchten, schattigen Höhle hinter Cliffspring Falls gedeihen. Barithras Mondschatten benötigt fünf davon, um sie zusammen mit der starken Todeskappe in seine laufenden alchemistischen Gebräue zu mischen.",al={"wozu dienen schorfstänglinge","zweck der schorfstänglinge","warum braucht barithras schorfstänglinge"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="Der Twilight's Hammer gräbt in den Flusslanden nach einer unbekannten Machtquelle. Ihr sollt im Sonnengrund einen seiner Bergarbeiter befragen.",h="Der Twilight's Hammer gräbt in den Flusslanden nach einer unbekannten Machtquelle.",kw={"digging for answers","bergarbeiter","flusslande","source of power","sonnengrund","twilight's hammer"},sec={{t="Bergarbeiter im Sonnengrund",b="Der Twilight's Hammer lässt im Sonnengrund graben, und Ihr sollt einen der Bergarbeiter befragen. Ihre Suche deutet auf eine Machtquelle hin, doch was es damit auf sich hat, ist unbekannt. Die Fanatiker hüten ihre Geheimnisse, daher wissen die Bergarbeiter vielleicht, wonach sie suchen."}},faq={{q="Wonach gräbt der Twilight's Hammer?",a="Der Twilight's Hammer scheint in den Flusslanden nach einer Machtquelle zu suchen, doch was es damit auf sich hat, ist unbekannt.",al={"wonach graben sie","twilight's hammer gräbt","source of power"}},{q="Warum befrage ich einen Bergarbeiter?",a="Die Fanatiker des Twilight's Hammer hüten ihre Geheimnisse, daher sollt Ihr im Sonnengrund einen ihrer Bergarbeiter befragen.",al={"warum bergarbeiter","mit dem bergarbeiter sprechen","quest digging for answers"}},{q="Wo sind die Bergarbeiter?",a="Die Bergarbeiter graben im Sonnengrund, in den Flusslanden.",al={"wo liegt sonnengrund","standort der bergarbeiter","graben in den flusslanden"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="Ein Goblin bittet Euch, Gobam in Bolder'ok zu finden und Futter für Snufflesnout, Chub'chobs Eber, mitzubringen. Gobam hilft gern, weil Chub'chob sein Freund ist.",h="Ein Goblin bittet Euch, Gobam in Bolder'ok zu finden und Futter für Snufflesnout, Chub'chobs Eber...",kw={"bolder'ok","chub'chob","klubhaus","gobam","goblin","unser ogerfreund","zahmer eber","snufflesnout"},sec={{t="Die Bitte eines Freundes",b="Nachdem Ihr einige Kämpfe gewonnen habt, bittet Euch der Goblin, Gobam in Bolder'ok zu finden. Er braucht Futter für Snufflesnout, Chub'chobs Eber, sagt aber, dass ihn seine Arbeit auf Trab hält. Gobam ist östlich von Clugfists Klubhaus, und der Goblin hofft, dass Ihr ihn findet."}},faq={{q="Wer ist Gobam?",a="Gobam ist der schüchterne Kerl, den der Goblin Euch in Bolder'ok suchen lässt.",al={"wer ist gobam"}},{q="Wo finde ich Gobam?",a="Gobam ist östlich von Clugfists Klubhaus in Bolder'ok.",al={"gobams aufenthaltsort","wo ist gobam"}},{q="Wer ist Snufflesnout?",a="Snufflesnout ist Chub'chobs zahmer Eber, und der Goblin bittet Euch, Futter für ihn mitzubringen.",al={"snufflesnout","eberfutter"}},{q="Warum braucht der Goblin Hilfe?",a="Der Goblin sagt, dass ihn seine Arbeit auf Trab hält, und bittet Euch deshalb, Futter für Snufflesnout zu finden.",al={"warum dem goblin helfen","goblin ist beschäftigt"}},{q="Warum wird Gobam helfen?",a="Gobam sagt, dass er den Goblin nicht leiden kann, Chub'chob aber helfen wird, weil sie gute Freunde sind.",al={"gobam hilft","warum gobam hilft"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam bittet Euch, süße Beeren und Flusspflanzen für Snufflesnout, Chub'chobs Haustier, zu sammeln. Die Zutaten ergeben eine besondere Leckerei.",h="Gobam bittet Euch, süße Beeren und Flusspflanzen für Snufflesnout, Chub'chobs Haustier, zu sammeln.",kw={"beere","gobam","haustier","flusskraut","snufflesnout","süßbeere","leckerbissen"},sec={{t="Ein Leckerbissen fürs Haustier",b="Gobam möchte etwas Besonderes für Snufflesnout zubereiten, das gutes Essen liebt. Ihr sollt süße Beeren und Flusspflanzen für den Leckerbissen zurückbringen."}},faq={{q="Wer ist Gobam?",a="Gobam bittet Euch, Zutaten für eine besondere Leckerei für Snufflesnout, Chub'chobs Haustier, zu bringen.",al={"wer ist gobam","wer bittet um beeren"}},{q="Wer ist Snufflesnout?",a="Snufflesnout ist Chub'chobs Haustier und liebt gutes Essen.",al={"snufflesnout haustier","gobams haustier"}},{q="Welche Zutaten möchte Gobam?",a="Gobam bittet um süße Beeren und Flusskraut, um einen Leckerbissen für Snufflesnout zuzubereiten.",al={"beere und pflanze","welches essen"}},{q="Warum möchte Gobam Beeren?",a="Gobam möchte süße Beeren und Flusskraut für einen besonderen Leckerbissen für Snufflesnout.",al={"warum beeren","beeren wofür"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Der Goblin von Bloodmaster's Ring schickt Euch für einen Kampf mit Kronk in die Grube von Bloodmaster's Ring. Die Menge freut sich schon auf die nächste Runde.",h="Der Goblin von Bloodmaster's Ring schickt Euch für einen Kampf mit Kronk in die Grube von Bloodmaster's Ring.",kw={"ansager","bloodmaster","bloodmaster's ring","kampf","kämpfer","kronk","grube"},sec={{t="Der nächste Kampf",b="Der Ansager heizt das Publikum an, während Kronk als nächster Kämpfer wartet. Ihr werdet in die Grube geschickt, um Euch ihm zu stellen, und der Lärm um den bevorstehenden Kampf wird lauter."}},faq={{q="Wer ist Kronk?",a="Kronk ist der nächste Kämpfer im Bloodmaster's Ring. Der Ansager sagt, dass sie sich schon lange kennen, und beschreibt ihn als starken Schläger.",al={"kronk","wer ist kronk","kronk bloodmaster"}},{q="Was will der Bloodmaster von mir?",a="Ihr werdet in die Grube von Bloodmaster's Ring geschickt, um Kronk gegenüberzutreten.",al={"was soll ich tun","aufgabe im ring","bloodmaster ring"}},{q="Warum kämpfe ich gegen Kronk?",a="Der Ansager kündigt Kronk als nächsten Kämpfer an, und der Kampf findet im Bloodmaster's Ring statt.",al={"warum kronk","gegen kronk kämpfen","kampf gegen kronk"}},{q="Wo findet der Kampf statt?",a="Der Kampf findet in der Grube des Bloodmaster's Ring statt.",al={"wo ist der kampf","die grube","ort des rings"}},{q="Was geschieht, nachdem ich die Grube betrete?",a="Der Ansager bereitet sich darauf vor, Kronk anzukündigen, während Ihr Euch in der Grube bereit macht.",al={"nach dem betreten","nächster im ring","was passiert als nächstes"}},{q="Was sagt der Ansager über Kronk?",a="Der Ansager sagt, Kronk sei nicht besonders helle, aber gut darin, alles zu vermöbeln, was ihm in die Quere kommt.",al={"kronks hintergrund","wie ist kronk","ansager kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer westlich von Rog'mar zu unterstützen. Der Stützpunkt des Kults in Sonnengrund ist geschwächt, und der Kampf verlagert sich zu seiner Festung.",h="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer westlich von Rog'mar zu...",kw={"dag'rosh","krom'rosh","ogerkrieger","rog'mar","sonnengrund","der verirrte krieger","twilight's hammer"},sec={{t="Ein Bruder voraus",b="Krom'rosh schickt Euch zu Dag'rosh, der mit einer Kundschaftergruppe vorausgezogen ist. In den Hügeln westlich von Rog'mar sollt Ihr ihn finden. Krom'rosh sagt, der Twilight's Hammer habe in Sonnengrund an Boden verloren und seine Ogerkrieger hätten sich gegen ihn gewandt. Nun will er, dass Ihr seinem Bruder zur Seite steht, während die Schlacht zur Festung des Kults zieht."}},faq={{q="Wer bittet mich, Dag'rosh zu finden?",a="Krom'rosh bittet Euch, seinen Bruder Dag'rosh bei der Festung des Twilight's Hammer zu unterstützen.",al={"wer hat mich geschickt","krom'rosh","wer will dag'rosh"}},{q="Wo kann ich Dag'rosh finden?",a="Krom'rosh sagt, Ihr sollt Dag'rosh in den Hügeln westlich von Rog'mar suchen.",al={"wo ist dag'rosh","dag'roshs aufenthaltsort","dag'rosh finden"}},{q="Wer ist Dag'rosh?",a="Dag'rosh ist Krom'roshs Bruder. Er ist mit einer Kundschaftergruppe vorausgezogen.",al={"dag'roshs hintergrund","krom'roshs bruder","wer ist dag'rosh"}},{q="Was ist dem Twilight's Hammer in Sonnengrund zugestoßen?",a="Der Stützpunkt des Twilight's Hammer in Sonnengrund ist geschwächt, und seine Ogerkrieger haben sich gegen ihn gewandt.",al={"kult in sonnengrund","stützpunkt des twilight's hammer","was ist mit den ogers passiert"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94745"] = {n="Carving a Path",s="Da'grosh fordert Euch auf, den Twilight's Hammer am Zwielichtschleier herauszufordern. Er glaubt, ihre Teufelei und alten Götter machten sie verwundbar.",h="Da'grosh fordert Euch auf, den Twilight's Hammer am Zwielichtschleier herauszufordern.",kw={"alte götter","einen weg bahnen","da'grosh","teufelei","twilight champion","twilight corrupter","twilight fanatic","twilight's hammer","zwielichtschleier"},sec={{t="Der Schleier",b="Da'grosh weist Euch zum Zwielichtschleier, einer Festung westlich von ihm. Die dort lebenden Mitglieder des Twilight's Hammer nennt er Feiglinge und verachtet ihre Abhängigkeit von Teufelei und alten Göttern. Ihr sollt ihnen zeigen, wie verwundbar sie sind."},{t="Ein Test of Strength",b="Am Zwielichtschleier bittet Da'grosh Euch, Twilight Fanatics, Twilight Corrupters und Twilight Champions zu besiegen. Er besteht darauf, dass wahre Stärke in den eigenen Händen liegt."}},faq={{q="Wen soll ich bekämpfen?",a="Da'grosh bittet Euch, Twilight Fanatics, Twilight Corrupters und Twilight Champions am Zwielichtschleier zu bekämpfen.",al={"wen bekämpfen","da'grosh feinde"}},{q="Wo liegt der Zwielichtschleier?",a="Da'grosh beschreibt den Zwielichtschleier als Festung direkt westlich von ihm.",al={"wo ist der schleier","standort der zwielichtfestung"}},{q="Warum nennt Da'grosh den Twilight's Hammer schwach?",a="Da'grosh glaubt, ihre Abhängigkeit von Teufelei und alten Göttern mache sie schwach.",al={"warum sind sie schwach","da'grosh über twilight"}},{q="Was soll ich beweisen?",a="Da'grosh möchte, dass Ihr dem Twilight's Hammer zeigt, wie verwundbar er ist.",al={"was soll ich beweisen","ihnen ihre verwundbarkeit zeigen"}}},fp="14,157,10.237.0,18.173.0,35.115.0,31.81.0,50.77.0,36.74.0"}
P.entries["quest:94748"] = {n="Break Their Chains",s="Da’grosh bittet Euch, im Twilight’s Shroud eingesperrte Rog’mar-Späher zu befreien. Seine Krieger müssen nach Rog’mar zurückkehren, bevor sie wieder kämpfen können.",h="Da’grosh bittet Euch, im Twilight’s Shroud eingesperrte Rog’mar-Späher zu befreien.",kw={"zerbrecht ihre ketten","gefangene orcs","da’grosh","festung","rog’mar-späher","hammer des zwielichts","twilight’s shroud"},ang={["race:Orc"]="Da’grosh ist ein Orc und bittet Euch, seine Orc-Brüder und -Schwestern aus der Gefangenschaft zu befreien."},sec={{t="Gefangene Späher",b="Da’groshs Krieger wurden vom Hammer des Zwielichts gefangen genommen, bevor ihr Angriff beginnen konnte. Die Champions des Kults brachten sie zu einer Festung westlich von Da’grosh und sperrten sie dort ein. Er bittet Euch, seine Orc-Brüder und -Schwestern im Twilight’s Shroud zu befreien."},{t="Nach der Rettung",b="Da’grosh sagt, seine Krieger seien zu schwer verletzt, um zu kämpfen, und nach Rog’mar zurückgekehrt. Er sagt Euch, dass Eure gemeinsame Arbeit weitergeht."}},faq={{q="Wer bittet um Hilfe?",a="Da’grosh bittet Euch, seine gefangenen Krieger zu befreien.",al={"wer ist da’grosh","wer braucht hilfe"}},{q="Wer wurde gefangen genommen?",a="Der Hammer des Zwielichts nahm Da’groshs Krieger gefangen, die Rog’mar-Späher.",al={"gefangene orcs","rog’mar-späher"}},{q="Wo sind die Späher eingesperrt?",a="Die Rog’mar-Späher sind in einer Festung westlich von Da’grosh im Twilight’s Shroud eingesperrt.",al={"aufenthaltsort der späher","wo werden sie festgehalten"}},{q="Wer nahm Da’groshs Krieger gefangen?",a="Die Champions des Hammers des Zwielichts nahmen Da’groshs Krieger gefangen.",al={"wer nahm die orcs gefangen","gefangene des hammers des zwielichts"}}},fp="18,153,19.261.0,16.130.1,23.50.0,17.79.0,32.101.0,37.71.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="Eine Lektion namens Divine Grace dankt Euch für Euren Dienst am Licht. Euer Vorbild ist für Reisende in gefährlichen Landen von Bedeutung.",h="Eine Lektion namens Divine Grace dankt Euch für Euren Dienst am Licht.",kw={"gefährliche lande","divine grace","lektion","licht","reisende"},sec={{t="Eine Lektion zum Dank",b="Nach Eurem Dienst wird das Licht für das Vorbild gepriesen, das Ihr Reisenden in gefährlichen Landen gegeben habt. Als Dank für Eure Taten wird Euch eine Lektion angeboten."}},faq={{q="Worum geht es bei Divine Grace?",a="Divine Grace dankt Euch dafür, dass Ihr dem Licht dient und Reisenden in gefährlichen Landen ein Vorbild seid.",al={"divine grace","was ist divine grace","divine grace quest"}},{q="Für wen ist diese Lektion bestimmt?",a="Die Lektion wird Euch als Dank für Euren Dienst am Licht angeboten.",al={"wer erhält die lektion","lektion für mich","divine grace belohnung"}},{q="Welches Vorbild habe ich gegeben?",a="Ihr wurdet Reisenden in gefährlichen Landen und darüber hinaus zum Vorbild.",al={"mein vorbild","leuchtendes vorbild","was habe ich getan"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="Hohepriesterin Laurena ruft Euch in die Kathedrale des Lichts in Sturmwind, weil Eure Vorgesetzten einer weiteren Ausbildung zugestimmt haben. Euer Unterricht in den Wegen des Lichts kann nun beginnen.",h="Hohepriesterin Laurena ruft Euch in die Kathedrale des Lichts in Sturmwind, weil Eure Vorgesetzten einer...",kw={"kathedrale des lichts","divine grace","hohepriesterin laurena","licht","diener des lichts","sturmwind","ausbildung"},ang={["class:Priest"]="Als Priester habt Ihr von Euren Vorgesetzten die Erlaubnis zu einer weiteren Ausbildung in den Wegen des Lichts erhalten."},sec={{t="Ein Ruf nach Sturmwind",b="Eure Vorgesetzten schicken Euch in die Kathedrale des Lichts in Sturmwind, nachdem Ihr Euch in ihren Augen bewährt habt. Dort steht Hohepriesterin Laurena bereit, Eure weitere Ausbildung zu leiten. Sie sagt, es gebe Lektionen, die jeder Diener des Lichts lernen müsse, und ist bereit, sie mit Euch zu besprechen."}},faq={{q="Warum werde ich nach Sturmwind geschickt?",a="Eure Vorgesetzten glauben, dass Ihr Euch bewährt habt, und haben einer weiteren Ausbildung in den Wegen des Lichts zugestimmt.",al={"warum sturmwind","zur kathedrale geschickt","warum dorthin gehen"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena befindet sich in der Kathedrale des Lichts in Sturmwind und steht bereit, Eure Ausbildung zu leiten.",al={"laurena wer","wer ist laurena","hohepriesterin"}},{q="Wo finde ich Hohepriesterin Laurena?",a="Hohepriesterin Laurena befindet sich in der Kathedrale des Lichts in Sturmwind.",al={"laurenas standort","wo ist laurena","standort der kathedrale"}},{q="Welche Ausbildung bietet Laurena an?",a="Laurena ist bereit, Lektionen zu besprechen, die alle Diener des Lichts lernen müssen.",al={"ausbildung im licht","welche lektionen","die wege des lichts lernen"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="Call of Air",s="Ein Schamane wird zu Veyric Thundervein in den nördlichen Hügeln des Arathihochlands geschickt. Er wird Euch mehr darüber lehren, wie Ihr die Luft beherrscht.",h="Ein Schamane wird zu Veyric Thundervein in den nördlichen Hügeln des Arathihochlands geschickt.",kw={"luft","arathihochland","call of air","schamane","geister der luft","veyric thundervein","windzauber"},sec={{t="Die nördlichen Hügel",b="Ein Schamane schickt Euch nach Norden ins Arathihochland, um Veyric Thundervein zu finden. Das Element Luft ist schwer zu beherrschen, und er kann Euch mehr darüber lehren. Euer wachsendes Können hat Euch so weit gebracht; nun wendet sich Eure Ausbildung dem Wind und den Geistern der Luft zu."}},faq={{q="Wer ist Veyric Thundervein?",a="Veyric Thundervein befindet sich in den nördlichen Hügeln des Arathihochlands, wo er Euch mehr über die Luft lehren kann.",al={"veyric","wer ist veyric","luftlehrer"}},{q="Wo finde ich Veyric?",a="Findet Veyric Thundervein in den nördlichen Hügeln des Arathihochlands.",al={"veyric aufenthaltsort","wo ist veyric","arathi luftlehrer"}},{q="Worum geht es in Call of Air?",a="Ein Schamane schickt Euch zu Veyric Thundervein, damit er Euch mehr über das Element Luft lehren kann.",al={"call of air quest","luftausbildung","windzauber"}},{q="Warum reise ich ins Arathihochland?",a="Veyric Thundervein befindet sich in den nördlichen Hügeln des Arathihochlands und wird Euch mehr über die Luft lehren.",al={"warum arathi","quest nach norden","veyric finden"}},{q="Was lehrt Veyric?",a="Veyric lehrt Euch, Windzauber zu bündeln und die Geister der Luft anzurufen.",al={"veyric ausbildung","geister der luft","windzauber bündeln"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Josephine Carson lehrt angehende Jäger in Taming the Beast, wie sie für einen wilden Begleiter sorgen. Bei der Prüfung kommen ein Rockhide Boar und eine Zähmerrute zum Einsatz, wobei das Gleichgewicht der Natur gewahrt wird.",h="Josephine Carson lehrt angehende Jäger in Taming the Beast, wie sie für einen wilden Begleiter sorgen.",kw={"tierbegleiter","gleichgewicht der natur","bestien zähmen","jägerbegleiter","josephine carson","rockhide boar","zähmerrute","taming the beast"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Fürsorge und Zurückhaltung helfen, das Gleichgewicht der Natur zu bewahren. Wenn Ihr die Wildtiere des Waldes mit Respekt behandelt, ehrt Ihr die natürliche Ordnung, die zu schützen Ihr geschworen habt.",["class:Hunter"]="Als Jäger ist das Zähmen wilder Bestien für Euch ein prägendes Übergangsritual. Ein treuer Begleiter bietet Schutz und Wachsamkeit im Kampf und schafft eine dauerhafte Partnerschaft zwischen Fährtenleser und Bestie."},sec={{t="Bindung zu Bestien",b="Allein durch die Wildnis zu reisen, kann gefährlich sein. Ein Tierbegleiter bietet Schutz im Kampf und Gesellschaft auf langen Reisen. Für angehende Jäger und Fährtenleser ist es ein entscheidender Schritt, diese Bindung aufzubauen. Josephine Carson führt Novizen durch eine Prüfung mit einem Rockhide Boar und einer Zähmerrute. Um die Bestie zu beruhigen und zu führen, müssen sie gelassen und konzentriert bleiben, ohne der Furcht nachzugeben oder unnötiges Blutvergießen zu verursachen."},{t="Das Gleichgewicht der Natur",b="Josephine Carson warnt ihre Schüler davor, Bestien rücksichtslos auszubeuten. Das Zähmen erfordert Geduld und Disziplin, niemals Grausamkeit oder Dominanz, und das Gleichgewicht der Natur muss gewahrt bleiben. Die verzauberte Rute lässt Novizen den Umgang mit einem furchterregenden Rockhide Boar üben, ohne den örtlichen Wildbestand dauerhaft zu verringern. Sobald sie gelernt haben, die Bestie zu befehligen und zu beruhigen, geben sie die Rute zurück. Respekt vor der Natur kommt vor Stolz."}},faq={{q="Welchen Zweck hat die Quest Taming the Beast?",a="Taming the Beast lehrt angehende Jäger, eine Bindung zu wilden Kreaturen aufzubauen. Josephine Carson zeigt ihnen, wie sie sich einem Rockhide Boar nähern und es mit einer Zähmerrute besänftigen. Die Prüfung vermittelt Überlebensfertigkeiten und Respekt vor dem Gleichgewicht der Natur.",al={"taming the beast quest","was ist taming the beast","jägerbegleiter quest"}},{q="Wer ist Josephine Carson?",a="Josephine Carson unterweist Abenteurer darin, für Tierbegleiter zu sorgen. Sie leiht ihren Schülern eine Zähmerrute, damit sie im Umgang mit Bestien Geduld und Geschick üben können. Sie lehrt, dass diese Arbeit Übung und Respekt vor dem Gleichgewicht der Natur erfordert.",al={"josephine carson","wer vergibt taming the beast","zähmerrute questgeber"}},{q="Wofür wird die Zähmerrute verwendet?",a="Die Zähmerrute ist ein verzaubertes Werkzeug für den sicheren Umgang mit einer furchterregenden Bestie. Sie lässt Novizen das Befehligen und Beruhigen eines Rockhide Boar üben, ohne den örtlichen Wildbestand dauerhaft zu verringern. Sie geben die Rute zurück, sobald sie die Grundlagen erlernt haben.",al={"zähmerrute","was bewirkt die zähmerrute","zähmerrute verwenden"}},{q="Warum brauchen Jäger Tierbegleiter?",a="Ein Tierbegleiter bietet Schutz, Wachsamkeit und Hilfe im Kampf. Eine treue Bestie kann die Frontlinie sichern und einem Reisenden auf langen, gefährlichen Reisen durch die Wildnis Gesellschaft leisten.",al={"warum einen tierbegleiter haben","vorteile eines tierbegleiters","warum bestien zähmen"}},{q="Welche Kreatur muss bei dieser Prüfung gezähmt werden?",a="Die Prüfung erfordert ein Rockhide Boar, eine robuste Bestie, die sich eignet, um grundlegende Fertigkeiten im Umgang mit Tieren zu prüfen. Die Übung lehrt Gelassenheit und Disziplin gegenüber angriffslustigen Wildtieren. Anschließend berichten die Abenteurer Josephine Carson von ihren Fortschritten.",al={"welches wildschwein zähmen","rockhide boar ziel","taming the beast kreatur"}},{q="Warum betont Josephine Carson das Gleichgewicht der Natur?",a="Josephine Carson warnt vor Gier und Gewalt im Umgang mit wilden Bestien. Rücksichtsloser Einsatz stört das Gleichgewicht der Natur, und Bestien sind keine Wegwerfwerkzeuge. Wahre Meisterschaft bedeutet, ihren Platz in der Natur zu respektieren.",al={"gleichgewicht der natur bedeutung","gleichgewicht der natur beim zähmen","warum die natur respektieren"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="In Goldhain zeigt Training the Beast jungen Jägern, wie sie einen gezähmten Begleiter versorgen. Isaac Chan lehrt sie, ihre Tiere zu füttern und wiederzubeleben und sie dann für das Leben an ihrer Seite auszubilden.",h="In Goldhain zeigt Training the Beast jungen Jägern, wie sie einen gezähmten Begleiter versorgen.",kw={"wald von elwynn","begleiter füttern","goldhain","jägerbegleiter","isaac chan","begleiterausbildung","begleiter wiederbeleben","training the beast","waldläufer"},ang={["class:Hunter"]="Als Jäger geht Ihr über das Einfangen von Tieren hinaus und baut eine dauerhafte, von Disziplin geprägte Bindung auf. Füttert Euren Begleiter, belebt ihn wieder und bildet ihn aus.",["faction:Alliance"]="Als Jäger der Allianz im Wald von Elwynn könnt Ihr die Grundlagen des Umgangs mit Tieren von erfahrenen Waldläufern wie Isaac Chan in Goldhain lernen."},sec={{t="Die Pflichten der Jagd",b="Ihr sucht Isaac Chan auf, einen erfahrenen Waldläufer in Goldhain, um zu lernen, wie Ihr Euer Tier ausbildet. Eine gezähmte Kreatur braucht Pflege und Disziplin, bevor sie zu einem verlässlichen Verbündeten werden kann. Ohne Chans Anleitung bleibt Euer Begleiter in der Wildnis womöglich widerspenstig."},{t="Die Anleitung eines Waldläufers",b="Isaac Chan lehrt Euch, Euren tierischen Begleiter zu versorgen. Ihr lernt, ihn zu füttern und wiederzubeleben, wenn er im Kampf fällt. Er lehrt Euch auch Befehle, die ihm im Kampf helfen, und erinnert Euch daran, dass Macht über die Tierwelt Respekt verlangt. Achtet das Gleichgewicht der Natur und lebt in Ehrfurcht vor der Welt um Euch herum."}},faq={{q="Wer ist Isaac Chan?",a="Isaac Chan ist seit jeher Waldläufer und lebt in Goldhain im Wald von Elwynn. Er kennt die Tierwelt und das Überleben in der Wildnis und lehrt unerfahrene Jäger, ihre tierischen Begleiter zu führen, zu füttern, wiederzubeleben und ihnen Fähigkeiten beizubringen.",al={"wer ist isaac chan","tierausbilder goldhain","isaac chan hintergrundgeschichte"}},{q="Welchen Zweck hat Training the Beast?",a="Jäger lernen, ein gezähmtes Tier zu versorgen und ihre Bindung zu ihm aufrechtzuerhalten. Isaac Chan lehrt sie, ihren Begleiter zu füttern, ihn wiederzubeleben, wenn er im Kampf fällt, und ihm neue Kampffähigkeiten beizubringen.",al={"was bewirkt diese quest","warum ein tier ausbilden","zweck von training the beast"}},{q="Wo ist Isaac Chan zu finden?",a="Isaac Chan lebt in Goldhain, dem zentralen Ort im Wald von Elwynn, südlich des Nordhaintals und südwestlich von Sturmwind.",al={"wo ist isaac chan","wo diese quest abgeben","isaac chan standort"}},{q="Welche Fähigkeiten lehrt Isaac Chan?",a="Isaac Chan vermittelt die Grundlagen der Pflege und Ausbildung eines tierischen Begleiters. Ihr lernt, Euer Tier zu füttern, es wiederzubeleben, wenn es im Kampf fällt, und ihm neue Fähigkeiten beizubringen, während es an Eurer Seite heranwächst.",al={"welche fähigkeiten werden erlernt","erlernte begleiterfähigkeiten","was lehrt isaac chan"}},{q="Warum erinnert Isaac Chan Jäger daran, die Natur zu achten?",a="Isaac Chan lehrt Jäger Demut vor der Wildnis. Er bittet sie, das Gleichgewicht der Natur zu achten und in Ehrfurcht vor der Welt um sie herum zu leben, damit ihre Bindung zu einem Tier auf Fürsorge statt auf Ausbeutung beruht.",al={"warum die natur achten","gleichgewicht achten jäger"}},{q="Wer nimmt diese Quest an?",a="Jäger, die bereits Tiere zähmen können, suchen Isaac Chans Schulung in der Waldläuferkunst, um einen tierischen Begleiter zu versorgen und auszubilden.",al={"wer kann diese quest machen","ist training the beast nur für jäger"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="Onu",s="Barithras Mondschatten schickt Euch von Auberdine nach Süden, um Onu zu befragen. Eure Entdeckungen bei den Cliffspring Falls haben die Aufmerksamkeit eines der ältesten Wächter der Dunkelküste geweckt.",h="Barithras Mondschatten schickt Euch von Auberdine nach Süden, um Onu zu befragen.",kw={"ancient of lore","auberdine","barithras mondschatten","cliffwater falls","dunkelküste","der hain der uralten","onu"},ang={["class:Druid"]="Als Druide verehrt Ihr die Uralten als Hüter der Weisheit der Natur. Die seltsamen Gewächse in den Höhlen auf Onus Bitte hin zu untersuchen, entspricht der Arbeit des Zirkels des Cenarius.",["faction:Alliance"]="Als Reisender der Allianz, der bei der Verteidigung der Dunkelküste hilft, könnt Ihr bei den Uralten der Region Einsichten in Kalimdors nördliche Wildnis gewinnen.",["race:NightElf"]="Als Nachtelf kennt Ihr die Ancients of Lore als heilige Gefährten, die Euer Volk schon seit der Zeit vor der Sundering führen. Onus Ruf zu folgen hilft, die Dunkelküste zu bewahren."},sec={{t="Ein Ruf der Uralten",b="Barithras Mondschatten sieht mehr als seltsame Pilze in den Proben, die Ihr nach Auberdine gebracht habt. Die Höhlen unter den Cliffspring Falls sind verderbt, und die Kunde davon hat Onu erreicht, einen Ancient of Lore im Hain der Uralten südlich der Stadt. Die Wasserläufe der Dunkelküste könnten von einer Verderbnis befallen sein, die über alles hinausgeht, was ein Naturkundler erklären kann. Onu sucht Rat, und selbst die Geduld eines Uralten kann das Gewicht seines Rufes nicht verbergen."},{t="Reise zum Hain",b="Die Straße von Auberdine nach Süden führt landeinwärts, fort von den Küstenruinen und auf die Berghänge zu. Der Hain der Uralten birgt eine alte Zuflucht der Natur, abseits des Verfalls entlang der Küste. Onu wartet zwischen steinernen Hügelgräbern und verwandten Geistern. Er ist bereit, Verbündete zu den Plagen zu führen, die sich am Rand der Wildnis regen."}},faq={{q="Wer ist Onu?",a="Als Ancient of Lore sammelt und bewahrt Onu Wissen. Er wacht über den Hain der Uralten im Süden der Dunkelküste und teilt seine Weisheit mit jenen, die das Land verteidigen.",al={"wer ist onu","onus identität","was ist onu"}},{q="Warum will Onu mit mir sprechen?",a="Ihr habt für Barithras Mondschatten Pilzproben aus den Höhlen unter den Cliffspring Falls gesammelt. Eure Funde haben die Naturkundler alarmiert, und Onu möchte mit Euch über die um sich greifende Verderbnis sprechen.",al={"warum ruft onu","grund für das gespräch","warum zu onu gehen"}},{q="Wo liegt der Hain der Uralten?",a="Der Hain der Uralten liegt südlich von Auberdine, entlang der östlichen Bergausläufer. Folgt der Hauptstraße nach Süden durch die Dunkelküste und wendet Euch dann nach Osten zu den Berghängen, um Onu zu erreichen.",al={"onus standort","wo liegt der hain der uralten","wie onu finden"}},{q="Was für ein Wesen ist ein Ancient of Lore?",a="Ancients of Lore sind alte Treantwesen, die mit den Nachtelfen und dem Zirkel des Cenarius verbündet sind. Sie werden für ihre Weisheit und ihr Gedächtnis verehrt und bewahren die Magie und Geschichte der Natur.",al={"ancient of lore","was für ein wesen ist onu","treant oder uralter"}},{q="Warum gilt Onus Ruf als dringend?",a="Uralte handeln bedächtig und eilen selten. Barithras Mondschatten sagt, Onus Bitte um Rat bedeute, dass die Dunkelküste schwer bedroht ist.",al={"warum dringend","ist onu besorgt","barithras' warnung"}},{q="Was folgt auf das Treffen mit Onu?",a="Nachdem Ihr Onu im Hain der Uralten getroffen habt, bittet er Euch, eine finsterere Bedrohung weiter südlich an der Küste zu untersuchen: die Ausgrabung rund um Master’s Glaive.",al={"nächste quest nach onu","was geschieht als nächstes","wohin schickt onu"}}},fx={be40e913={q="Warum schickt mich Barithras Mondschatten zu Onu?",a="Barithras weiß, dass die Ältesten der Lehren tiefes Wissen über die Verderbnis des Landes besitzen, und Onu hat direkt bemerkt, was Ihr in der Höhle bei Cliffspring Falls gefunden habt. Da sich ein Ältester selten meldet, es sei denn, die Dunkelküste steht vor einer tiefgreifenden und dringenden Bedrohung, drängt Barithras Euch dazu, der Vorladung sofort Folge zu leisten.",al={"barithras beweggrund","warum zu onu schicken","warum will barithras das erledigt haben"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="Jemand schickt Euch nach Eisenschmiede, um High Priestess Mims zu treffen. Eure nächste Prüfung rückt näher, und sie wartet im Mystic Ward auf Euch.",h="Jemand schickt Euch nach Eisenschmiede, um High Priestess Mims zu treffen.",kw={"notfallplan","high priestess mims","eisenschmiede","licht","mystic ward","nächste prüfung","riten"},sec={{t="Ein wartendes Gespräch",b="In Eisenschmiede wartet High Priestess Mims im Mystic Ward darauf, mit Euch zu sprechen. Eure nächste Prüfung rückt näher, und die Person, die Euch geschickt hat, kann ihren Platz nicht verlassen, um den Riten Eures Volkes beizuwohnen. Auf Eurer Reise möge das Licht Euch begleiten, wenn Ihr Mims trefft."}},faq={{q="Wen soll ich treffen?",a="High Priestess Mims wartet im Mystic Ward von Eisenschmiede darauf, mit Euch zu sprechen.",al={"wer wartet","mims treffen","mims"}},{q="Wo finde ich Mims?",a="Mims sollte sich im Mystic Ward in Eisenschmiede aufhalten.",al={"wo ist mims","mims' aufenthaltsort","mystic ward"}},{q="Warum gehe ich nach Eisenschmiede?",a="High Priestess Mims möchte dort mit Euch sprechen, und Eure nächste Prüfung rückt näher.",al={"warum eisenschmiede","was gibt es in eisenschmiede","gespräch"}},{q="Was sagt die Person, die mich geschickt hat, über die Riten meines Volkes?",a="Die Person, die Euch geschickt hat, würde gern den Riten Eures Volkes beiwohnen, sagt aber, dass sie ihren Platz nicht verlassen kann.",al={"riten meines volkes","besondere riten","warum kann die person nicht kommen"}},{q="Was wird für meine Reise gewünscht?",a="Die Person, die Euch geschickt hat, wünscht, dass das Licht Euch auf Eurer Reise begleitet.",al={"segen des lichts","licht begleite mich","reisesegen"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="Eure Vorgesetzten schicken Euch nach Eisenschmiede, um Eure Ausbildung bei High Priestess Mims fortzusetzen. Euer Dienst am Licht hat ihre Aufmerksamkeit geweckt.",h="Eure Vorgesetzten schicken Euch nach Eisenschmiede, um Eure Ausbildung bei High Priestess Mims fortzusetzen.",kw={"confounding flash","hall of mysteries","high priestess mims","eisenschmiede","licht","vorgesetzte","ausbildung"},sec={{t="Eine weitere Lektion",b="Eure Vorgesetzten schicken Euch zu High Priestess Mims in der Hall of Mysteries in Eisenschmiede. Sie sind der Ansicht, dass Euer Dienst Euch auf weitere Unterweisung vorbereitet hat. Mims soll Euch anleiten, und die Lektion erwartet Eure Ankunft."},{t="Vor Mims",b="High Priestess Mims empfängt Euch in Eisenschmiede und bemerkt Eure verspätete Ankunft. Angesichts Eures Dienstes am Licht entschuldigt sie die Verspätung und bittet Euch dann, ihrer Lektion aufmerksam zu folgen."}},faq={{q="Wer hat mich nach Eisenschmiede geschickt?",a="Eure Vorgesetzten haben Euch gebeten, für weitere Unterweisung zur Hall of Mysteries in Eisenschmiede zu reisen.",al={"wer hat mich geschickt","wer sind meine vorgesetzten"}},{q="Wer ist High Priestess Mims?",a="High Priestess Mims ist diejenige, die Ihr auf Geheiß Eurer Vorgesetzten in Eisenschmiede aufsuchen sollt. Sie kann Eure weitere Ausbildung anleiten.",al={"wer ist mims","mims"}},{q="Warum werde ich zur Ausbildung geschickt?",a="Eure Vorgesetzten glauben, dass Ihr Euch durch Euren Dienst am Licht bewährt habt.",al={"warum ausbildung","warum ich"}},{q="Wo finde ich High Priestess Mims?",a="Sucht High Priestess Mims in der Hall of Mysteries in Eisenschmiede auf.",al={"wo ist mims","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="Eine Nachricht schickt Euch nach Eisenschmiede, um mit Hohepriesterin Mims zu sprechen. Sie erwartet Euch in der Hall of Mysteries, doch der Grund ist noch unklar.",h="Eine Nachricht schickt Euch nach Eisenschmiede, um mit Hohepriesterin Mims zu sprechen.",kw={"confounding flash","hall of mysteries","hohepriesterin mims","eisenschmiede","mit mims sprechen","vorladung"},sec={{t="Ein Ruf nach Eisenschmiede",b="Der Weg vor Euch führt nach Eisenschmiede, wo Hohepriesterin Mims in der Hall of Mysteries auf Euch wartet. Ihr sollt persönlich mit ihr sprechen, doch die Nachricht nennt keinen Grund für die Vorladung. Sie vermutet, dass Eure Taten erfolgreich waren, überlässt es aber Mims, Euch die Angelegenheit zu erklären."}},faq={{q="Wer möchte mit mir sprechen?",a="Hohepriesterin Mims möchte, dass Ihr nach Eisenschmiede kommt, um mit ihr zu sprechen.",al={"wer hat nach mir verlangt","mims vorladung","hohepriesterin mims"}},{q="Wohin soll ich gehen?",a="Ihr sollt mit Hohepriesterin Mims in der Hall of Mysteries in Eisenschmiede sprechen.",al={"wo ist mims","standort der hall of mysteries","nach eisenschmiede gehen"}},{q="Warum möchte Mims mich sehen?",a="Die Nachricht erklärt nicht, warum Hohepriesterin Mims mit Euch sprechen möchte.",al={"warum mims mich gerufen hat","was möchte sie","grund der vorladung"}},{q="Was soll ich tun?",a="Ihr sollt mit Hohepriesterin Mims in Eisenschmiede sprechen.",al={"was ist die aufgabe","mit mims sprechen","mims bitte"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94829"] = {n="What We Lost",s="Ein Bauer auf Elbrim's Farm trauert um die Menschen, die von den Twilight Raiders getötet wurden. Ihr sollt ihre Andenken bergen und auf den Gräbern westlich des Hofes niederlegen.",h="Ein Bauer auf Elbrim's Farm trauert um die Menschen, die von den Twilight Raiders getötet wurden.",kw={"kultisten","elbrim's farm","bauern","andenken der bauern","gräber","friedhof","twilight raiders","was wir verloren haben"},sec={{t="Die Bitte eines Bauern",b="Der Bauer bittet Euch, die Habseligkeiten derer zu sammeln, die getötet wurden, als die Kultisten auf Elbrim's Farm einfielen. Die Felder versorgten einst Soldaten und Zivilisten mit Nahrung, doch laut dem Bauern blieb der versprochene Schutz aus. Die eigenen Leute liegen in den Ruinen des Hofes, ihre Angehörigen sind auf dem Friedhof im Westen begraben."},{t="An den Gräbern",b="Der Bauer möchte, dass Ihr die Andenken der Toten zu den Gräbern westlich von Elbrim's Farm bringt. Das wird sie nicht zurückbringen, doch der Bauer hofft, dass ihre Seelen bei ihren Angehörigen zur Ruhe kommen können."}},faq={{q="Was geschah auf Elbrim's Farm?",a="Der Bauer sagt, Kultisten seien auf Elbrim's Farm eingefallen, hätten die Ernte vernichtet und die Menschen getötet, die dort arbeiteten.",al={"was geschah auf elbrim's farm","hof zerstört","was geschah hier"}},{q="Wer bittet Euch, die Andenken zu bergen?",a="Ein Bauer auf Elbrim's Farm bittet Euch, die Habseligkeiten der Menschen zu bergen, die von den Kultisten getötet wurden.",al={"wer möchte die andenken","bitte des bauern","wer bittet darum"}},{q="Wessen Andenken sammelt Ihr?",a="Sie gehörten den Menschen, die auf den Feldern von Elbrim's Farm arbeiteten und getötet wurden, als die Kultisten einfielen.",al={"andenken der bauern","wem gehören diese","für wen sind die andenken"}},{q="Wohin sollen die Andenken gebracht werden?",a="Der Bauer bittet Euch, die Andenken auf den Gräbern des Friedhofs westlich von Elbrim's Farm niederzulegen.",al={"wohin mit den andenken","welche gräber","friedhof ort"}},{q="Warum möchte der Bauer die Andenken zurückbringen lassen?",a="Der Bauer glaubt, dass die Seelen der Toten zur Ruhe kommen können, wenn ihre Habseligkeiten auf den Gräbern ihrer Angehörigen niedergelegt werden.",al={"warum sie bergen","seelen zur ruhe bringen","warum andenken"}}},fp="12,158,15.292.0,13.180.0,31.110.0,36.98.0,31.109.0,29.95.0,47.106.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="Eine für Friz Frazzlespark bestimmte Transportkiste ist in den Flusslanden verschwunden. Ihr Etikett bittet darum, sie zum Hafen von Powderfuse zurückzubringen.",h="Eine für Friz Frazzlespark bestimmte Transportkiste ist in den Flusslanden verschwunden.",kw={"kiste","friz frazzlespark","etikett","vermisste transportkiste","karte","hafen von powderfuse","flusslande"},sec={{t="Eine markierte Kiste",b="Friz Frazzlesparks Kiste trägt ein handgeschriebenes Etikett, auf dem der Hafen von Powderfuse in den Flusslanden steht. Eine Karte markiert ein südöstliches Ufer nördlich eines von Wasser umgebenen Tempels, in dessen Nähe geflügelte Kreaturen sind. Das Etikett warnt davor, die Kiste ohne Aufsicht zu öffnen, und nennt Friz als Empfänger."}},faq={{q="Wem gehört die Transportkiste?",a="Auf dem Etikett steht, dass die Kiste Friz Frazzlespark gehört.",al={"besitzer der kiste","wem gehört sie"}},{q="Wohin soll ich die Kiste bringen?",a="Laut Etikett soll die Kiste zu Friz Frazzlespark am Hafen von Powderfuse in den Flusslanden zurückgebracht werden.",al={"wohin die kiste bringen","lieferung der kiste"}},{q="Was steht auf dem Etikett der Kiste?",a="Es nennt Friz Frazzlespark und den Hafen von Powderfuse, warnt davor, die Kiste ohne Aufsicht zu öffnen, und gibt einen Rückgabeort in den Flusslanden an.",al={"etikett der kiste","was darauf steht"}},{q="Kann man die Kiste gefahrlos öffnen?",a="Auf dem Etikett steht, dass sie nicht ohne Aufsicht geöffnet werden soll.",al={"kiste öffnen","warnung zur kiste"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94842"] = {n="Unsavory Plant Food",s="Halligan Turner braucht Zutaten für den Dünger seiner Holzfällermannschaft. Ihr könnt ihm helfen, Flusskrebsschalen, Mist und Mudfin murloc heads zu sammeln.",h="Halligan Turner braucht Zutaten für den Dünger seiner Holzfällermannschaft.",kw={"flusskrebsschalen","dünger","fresh manure","halligan turner","jumbo crawfish shells","holzfällerei","mudfin murloc heads","pflanzennahrung"},sec={{t="Zutaten sammeln",b="Halligan Turner sagt, die Holzfällermannschaft stellt ihren Dünger selbst aus Flusskrebsschalen, Mist und Murlocköpfen her. Der Mist stammt von einer Ranch im Süden, die Schalen und Köpfe liegen im Fluss. Bevor sie mit dem Pflanzen beginnen können, braucht er vier Jumbo Crawfish Shells, vier Stück Fresh Manure und acht Mudfin Murloc Heads."}},faq={{q="Welche Zutaten braucht Halligan?",a="Halligan braucht vier Jumbo Crawfish Shells, vier Stück Fresh Manure und acht Mudfin Murloc Heads.",al={"düngerzutaten","was braucht halligan"}},{q="Woraus besteht der Dünger?",a="Der Dünger der Holzfällermannschaft besteht aus Flusskrebsschalen, Mist und Murlocköpfen im Verhältnis eins zu eins zu zwei.",al={"was ist im dünger","zutaten für pflanzennahrung"}},{q="Woher stammt der Mist?",a="Halligan sagt, der Mist stammt von einer Ranch im Süden.",al={"mistfundort","wo gibt es mist"}},{q="Wo sind die Schalen und Murlocköpfe?",a="Halligan sagt, Ihr müsst für die Schalen und Murlocköpfe in den Fluss waten.",al={"fundort der flusskrebsschalen","wo sind die mudfin köpfe"}},{q="Wer bittet um diese Zutaten?",a="Halligan Turner bittet um die Zutaten, um Dünger für die Holzfällermannschaft herzustellen.",al={"wer braucht pflanzennahrung","halligan turner"}}},fp="19,147,21.321.0,36.102.0,33.105.0,32.57.0,38.78.0,36.80.0"}
P.entries["quest:94843"] = {n="From Seed to Sprout",s="Halligan Turner hat aus dem Dünger, den Ihr bereitgestellt habt, ein Pflanzset zusammengestellt. Er bittet Euch, Setzlinge an den Arbeitsplätzen des Holzfällerlagers zu pflanzen.",h="Halligan Turner hat aus dem Dünger, den Ihr bereitgestellt habt, ein Pflanzset zusammengestellt.",kw={"dünger","vom samen zum keimling","halligan turner","holzfällerlager","pflanzset","setzlinge","samen","arbeitsplätze"},sec={{t="Eine neue Pflanzung",b="Halligan Turner hat Samen gesammelt, während die Holzfäller zwischen den Bäumen arbeiten. Mit dem Dünger, den Ihr gebracht habt, hat er ein Set vorbereitet, um sie als Setzlinge einzupflanzen. Ihr sollt Plätze an den Arbeitsstätten finden, an denen Ihr sie in die Erde setzen könnt."}},faq={{q="Wer hat das Pflanzset zusammengestellt?",a="Halligan Turner hat das Pflanzset mit dem Dünger zusammengestellt, den Ihr bereitgestellt habt.",al={"wer hat das set zusammengestellt","halligans set"}},{q="Was ist in dem Set?",a="Das Set dient dazu, Samen von den Bäumen einzupflanzen und daraus Setzlinge wachsen zu lassen.",al={"inhalt des sets","was ist im set"}},{q="Wo soll ich die Setzlinge pflanzen?",a="Halligan bittet Euch, sie an den Arbeitsplätzen des Holzfällerlagers zu pflanzen.",al={"wo pflanzen","plätze für setzlinge"}},{q="Warum pflanzen sie Setzlinge?",a="Die Holzfäller fällen Bäume und ziehen neue an ihrer Stelle heran.",al={"warum setzlinge","grund fürs pflanzen"}}},fp="19,142,14.243.0,26.72.0,19.85.0,34.70.0,31.61.0"}
P.entries["quest:94857"] = {n="If a Tree Falls, and No One Hears...",s="Ein gefangener Holzfäller bittet Euch, Hilfe aus Turner's Logging Camp zu holen. Er fürchtet, zu verbluten oder gefressen zu werden, wenn er gefangen bleibt.",h="Ein gefangener Holzfäller bittet Euch, Hilfe aus Turner's Logging Camp zu holen.",kw={"unfall","hilfe","wenn ein baum fällt","holzfällerlager","holzfäller","gefangen","turner's logging camp"},sec={{t="Ein Hilferuf",b="Ein Holzfäller ist nach einem Unfall am Unglücksort gefangen. Er bittet Euch, zu Turner's Logging Camp zu gehen und Hilfe zu holen, bevor er verblutet oder wilde Tiere ihn finden."}},faq={{q="Wer ist gefangen?",a="Ein Holzfäller aus dem nahegelegenen Holzfällerlager ist nach einem Unfall gefangen.",al={"gefangener holzfäller","wer hilfe braucht","verletzter arbeiter"}},{q="Welche Hilfe braucht er?",a="Er bittet Euch, Hilfe aus Turner's Logging Camp zu holen.",al={"wie ihm helfen","gefangenem mann helfen","was braucht er"}},{q="Warum ist er in Gefahr?",a="Er sagt, er könnte verbluten oder von wilden Tieren gefressen werden, wenn er gefangen bleibt.",al={"warum gefangen","ist er verletzt","was ist dem holzfäller passiert"}}},fp="36,131,15.156.0,15.71.0,23.53.0,20.73.0"}
P.entries["quest:94861"] = {n="Helping Hands",s="Hurley braucht Eure Hilfe, um Curly zu retten, der von seiner Mittagspause nicht zurückgekehrt ist. Er fürchtet, dass kaum noch Zeit bleibt, ihn zu erreichen.",h="Hurley braucht Eure Hilfe, um Curly zu retten, der von seiner Mittagspause nicht zurückgekehrt ist.",kw={"curly","helfende hände","hurley","mittagspause","vermisster arbeiter","curly retten"},sec={{t="Hurileys Sorge",b="Hurley macht sich Sorgen, weil Curly nicht zum Mittagessen zurückgekehrt ist. Er bittet Euch, ihn zu begleiten und den vermissten Arbeiter zu retten, und fürchtet, dass kaum noch Zeit bleibt. Curly ist trotz seiner Torheit ein guter Arbeiter, und Hurley hofft, dass er sich erholt und etwas Vernunft lernt."}},faq={{q="Wer ist Curly?",a="Curly ist ein Arbeiter, der von seiner Mittagspause nicht zurückgekehrt ist. Hurley nennt ihn einen guten Arbeiter, hält ihn aber auch für töricht.",al={"wer ist curly","curlys hintergrundgeschichte"}},{q="Wer bittet um Hilfe, Curly zu retten?",a="Hurley bittet Euch, ihn zu begleiten und Curly zu retten.",al={"wer bittet um hilfe","curly helfen","hurley bittet"}},{q="Warum macht sich Hurley Sorgen?",a="Curly ist nicht zum Mittagessen zurückgekehrt, und Hurley fürchtet, dass kaum noch Zeit bleibt, ihn zu retten.",al={"warum besorgt","curly vermisst","wo ist curly"}},{q="Was hofft Hurley für Curly?",a="Hurley hofft, dass Curly sich gut erholt und etwas Vernunft lernt.",al={"curlys ausgang","erholt sich curly","curly erholt sich"}}},fp="13,123,18.248.0,13.120.0,31.46.0,22.85.0,32.52.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Josephine Carson führt Euch durch Taming the Beast, während Ihr lernt, mit einem Eber umzugehen, bevor Ihr Euch einem Gray Forest Wolf stellt. Mit einer Zähmerrute versucht Ihr, das Vertrauen des wilderen Tieres zu gewinnen.",h="Josephine Carson führt Euch durch Taming the Beast, während Ihr lernt, mit einem Eber umzugehen, bevor Ihr...",kw={"wildtiere zähmen","gray forest wolf","jäger","jägerausbildung","josephine carson","zähmerrute","taming the beast"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Geduld und den Respekt, die nötig sind, um eine Bindung zu wilden, gefährlichen Raubtieren aufzubauen."},sec={{t="Der Pfad des Jägers",b="Josephine Carson beobachtet, wie Ihr einen weiteren Schritt beim Erlernen des Umgangs mit Wildtieren macht. Ihr habt mit einfachen Ebern geübt; nun betretet Ihr den Wald, um einen Gray Forest Wolf zu zähmen. Die verzauberte Rute, die sie Euch gibt, hilft, das Raubtier zu beruhigen. Geduld und Respekt zählen ebenso viel wie Spurenlesen und Treffsicherheit, wenn Ihr das Vertrauen eines wilden Tieres gewinnen wollt."},{t="Instinkt und Vertrauen",b="Josephine Carson gibt Euch eine spezielle Zähmerrute, um gefährliche Wildtiere zu beruhigen. Nähert Euch dem Wolf mit Geduld und Präzision und überwindet seine Aggression ohne tödliche Gewalt. Nachdem Ihr Eure Bindung zum Tier geübt habt, bringt die Rute als Beweis Eures wachsenden Könnens zu Josephine zurück."}},faq={{q="Was ist die Quest Taming the Beast?",a="Taming the Beast ist eine Ausbildungsprüfung für Jäger, bei der Ihr mit einer verzauberten Zähmerrute einen Gray Forest Wolf zähmt.",al={"taming the beast quest","gray forest wolf quest","wolf zähmen lektion"}},{q="Wer vergibt diese Quest und nimmt sie ab?",a="Josephine Carson unterweist Euch und gibt Euch die Zähmerrute. Nach der Prüfung bringt Ihr sie zu ihr zurück.",al={"wer vergibt taming the beast","wer ist josephine carson","wo taming the beast abgeben"}},{q="Welches Tier müsst Ihr zähmen?",a="Ihr sollt einen Gray Forest Wolf zähmen, ein wilderes Waldraubtier als die Eber, mit denen Ihr zuvor umgegangen seid.",al={"was muss gezähmt werden","welches wildtier","ziel von taming the beast"}},{q="Wozu dient die Zähmerrute?",a="Josephine Carson gibt Euch die Zähmerrute, um einen wilden Gray Forest Wolf zu beruhigen und eine vorübergehende Bindung aufzubauen, ohne bleibenden Schaden anzurichten.",al={"was bewirkt die zähmerrute","warum die zähmerrute benutzen","zähmerrute hintergrund"}},{q="Was hat der Jäger vor dieser Prüfung gezähmt?",a="Bevor Ihr Euch dem Gray Forest Wolf gestellt habt, habt Ihr den Umgang mit einem Waldeber geübt.",al={"zähmen vorherige lektion","was wurde vor dem wolf gezähmt"}},{q="Behaltet Ihr den Gray Forest Wolf als dauerhaften Begleiter?",a="Nein. Nachdem Ihr geübt habt, eine Bindung zu Wildtieren aufzubauen, bringt Ihr die Zähmerrute zu Josephine Carson zurück.",al={"bleibt der wolf erhalten","ist der wolf ein dauerhafter begleiter"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Im Wald von Elwynn stellen sich Jäger Taming the Beast, der letzten Prüfung unter Josephine Carsons Aufsicht. Nachdem sie einen Eber und einen Wolf gezähmt haben, gewinnt jeder Jäger mit einer Zähmerrute das Vertrauen eines Young Forest Bear. Die Prüfung vertieft die Bindung des Jägers zu wilden Tieren und lehrt Respekt vor dem Gleichgewicht des Waldes.",h="Im Wald von Elwynn stellen sich Jäger Taming the Beast, der letzten Prüfung unter Josephine Carsons Aufsicht.",kw={"einklang mit tieren","tierausbildung","wald von elwynn","jägerquest","josephine carson","zähmerrute","taming the beast","young forest bear"},ang={["class:Hunter"]="Als Jäger geht Ihr über das Spurenlesen hinaus und entwickelt eine tiefere, verständnisvollere Bindung zu wilden Tieren.",["faction:Alliance"]="Als Tiermeister der Allianz könnt Ihr Wildniskundschaftern disziplinierte Begleiter zur Seite stellen, die Gehöfte verteidigen und die Handelsstraßen in Sturmwinds Gebieten patrouillieren.",["race:Human"]="Als menschlicher Jäger in der Ausbildung im Wald von Elwynn lernt Ihr, mit den natürlichen Raubtieren des Königreichs zu leben, statt sie vernichten zu wollen."},sec={{t="Die letzte Jagdprüfung",b="Jäger im Wald von Elwynn lernen, unter den wilden Kreaturen ihrer Umgebung zu leben. Nachdem sie einen Wolf und einen Eber gezähmt haben, erwartet sie eine letzte Prüfung ihres Mutes und ihrer Geduld. Josephine Carson schickt jeden Jäger zu einem Young Forest Bear, dem stärksten der gewöhnlichen Raubtiere des Waldes. Der Jäger muss der Stärke des Bären standhalten und sein Vertrauen gewinnen, statt ihn zur Unterwerfung zu zwingen."},{t="Respekt und Gleichgewicht in Elwynn",b="Wildtiere in Elwynn zu zähmen, verlangt Respekt, keine Herrschaft. Waldbären verkörpern die Stärke und Lebenskraft des Waldes und helfen, seine natürliche Ordnung zu bewahren. Mit einer Zähmerrute lernen Jäger, die Angriffslust eines Bären zu besänftigen und durch Verständnis eine Bindung aufzubauen. Das Vertrauen eines so mächtigen Tieres zu gewinnen, vertieft die Bindung eines Jägers zur Wildnis und schließt die ersten Lektionen unter Josephine Carsons Aufsicht ab."}},faq={{q="Wer erteilt Jägern diese Prüfung?",a="Josephine Carson erteilt die Prüfung Jägern, die im Wald von Elwynn ausgebildet werden. Nachdem sie schwächere Tiere gezähmt haben, gibt sie ihnen Anweisungen und die Zähmerrute für den Waldbären. Nach Abschluss der Prüfung geben sie ihr die Rute zurück.",al={"wer vergibt taming the beast","taming the beast questgeber","josephine carson quest"}},{q="Welche Tiere müssen vor dieser Herausforderung gezähmt werden?",a="Jäger zähmen zuerst einen Eber und einen Wolf, bevor sie sich einem Young Forest Bear stellen. Diese Prüfungen zeigen, dass sie mit zähen Tieren und Rudeltieren umgehen können, bevor sie versuchen, das Vertrauen eines Bären zu gewinnen.",al={"vorausgesetzte tiere zum zähmen","was wurde vor dem bären gezähmt","zuvor gezähmte tiere"}},{q="Warum werden Jäger zu einem Young Forest Bear geschickt?",a="Ein Young Forest Bear stellt einen Jäger auf die Probe, indem er ihn mit der Muskelkraft und Macht der Wildtiere des Waldes von Elwynn konfrontiert. Nach dem Umgang mit dem flinken Wolf und dem zähen Eber muss der Jäger Ausdauer, Respekt und Mut beweisen, um das Vertrauen des Bären zu gewinnen.",al={"warum young forest bear zähmen","young forest bear zweck","warum bären in elwynn"}},{q="Wozu dient die Zähmerrute?",a="Josephine Carson gibt Jägern eine Zähmerrute, die ihnen hilft, wilde Tiere zu beruhigen. Sie hilft, einen angriffslustigen Young Forest Bear zu besänftigen, ohne ihn zu töten, und ermöglicht dem Jäger, eine friedliche Bindung aufzubauen. Jäger geben Carson die Rute zurück, wenn die Prüfung abgeschlossen ist.",al={"zähmerrute zweck","was bewirkt die zähmerrute","warum zähmerrute verwenden"}},{q="Wie hilft das Zähmen von Tieren dem Wald von Elwynn?",a="Jäger lernen, das natürliche Gleichgewicht des Waldes von Elwynn zu bewahren, indem sie Wildtiere mit Respekt und Zurückhaltung behandeln. Sie lenken gefährliche Tiere auf friedliche Weise, statt sie zu erlegen, und bewahren so die Harmonie zwischen den heimischen Wildtieren und humanoiden Siedlungen.",al={"warum ist elwynns gleichgewicht wichtig","gleichgewicht im wald von elwynn","zähmen und waldgleichgewicht"}},{q="Was bedeutet der Abschluss dieser Lektion für einen Jäger?",a="Der Abschluss der letzten Prüfung vertieft die Bindung eines Jägers zu wilden Tieren. Das Vertrauen von Elwynns mächtigster Kreatur zu gewinnen, vermittelt das nötige Verständnis für lebenslange Partnerschaften mit tierischen Begleitern in ganz Azeroth.",al={"was geschieht nach dem zähmen des bären","abschluss der jägerausbildung","einklang mit tieren bedeutung"}},{q="Wo sind Young Forest Bears zu finden?",a="Young Forest Bears durchstreifen die bewaldeten Gebiete des Waldes von Elwynn, zwischen dicht stehenden Bäumen und Seite an Seite mit Wölfen und Spinnen. Jäger verlassen die nahen Siedlungen und spüren die Bären mit der Zähmerrute im Unterholz auf, um Carsons letzte Anweisung zu befolgen.",al={"young forest bear fundort","wo bären in elwynn finden","waldbär elwynn"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94872"] = {n="Buying Friendship: Magram",s="Die Sorge vor der Stärke der Magram führt dazu, dass Ihr geschnitzte Totems im Dorf Magram anbietet. Das Geschenk könnte dem Clan den Weg zur Allianz ebnen.",h="Die Sorge vor der Stärke der Magram führt dazu, dass Ihr geschnitzte Totems im Dorf Magram anbietet.",kw={"zentaur","desolace","freundschaft","gorhak","magram","quartiermeister","totems"},sec={{t="Ein Angebot an Gorhak",b="Jemand, der sich wegen der wachsenden Stärke der Magram sorgt, bittet Euch, Gorhak, ihrem Quartiermeister, einen Sack Totems zu überreichen. Das Dorf des Clans wächst, und seine Soldaten werden immer kühner. Die Stärke des Clans beunruhigt denjenigen, der Euch schickt, doch die Magram könnten zu Verbündeten werden."},{t="Im Dorf",b="Im Dorf Magram in Desolace nimmt Gorhak die geschnitzten Totems entgegen und erkennt, dass Euer Angebot einen Zweck verfolgt. Er weiß nicht, was Ihr von ihm oder dem Clan wollt. Vorerst heißt er Euch als Außenstehende willkommen."}},faq={{q="Warum bringe ich den Magram Totems?",a="Jemand, der sich wegen der wachsenden Stärke der Magram sorgt, hofft, dass das Geschenk ihr Vertrauen gewinnt und sie zu möglichen Verbündeten macht.",al={"warum totems","geschenk der magram","freundschaft erkaufen"}},{q="Wer ist Gorhak?",a="Gorhak ist der Quartiermeister der Magram im Dorf Magram.",al={"wer ist gorhak","quartiermeister der magram","totem-typ"}},{q="Wohin soll ich die Totems bringen?",a="Bringt den Sack mit geschnitzten Totems zum Quartiermeister der Magram im Dorf Magram in Desolace.",al={"wohin mit den totems","lage des dorfs magram"}},{q="Was hält Gorhak von dem Geschenk?",a="Gorhak erkennt, dass das Geschenk mit einer Absicht verbunden ist, heißt Euch aber trotzdem im Dorf Magram willkommen.",al={"gorhaks reaktion","nimmt er totems an","willkommen bei den magram"}},{q="Warum sorgen sich die Leute um die Magram?",a="Das Dorf der Magram wächst, und ihre Soldaten werden kühner. Das weckt Besorgnis über die Stärke des Clans.",al={"wachstum der magram","bedrohung durch die magram","warum besorgt"}}},fp="25,131,18.270.0,14.195.1,39.116.0,14.53.0,28.90.0,35.102.0,40.110.0"}
P.entries["quest:94873"] = {n="Buying Friendship: Gelkis",s="Ein Außenstehender bietet dem Gelkis Clan im Dorf der Gelkis einen Beutel voller Totems an. Der Rüstmeister sieht das Geschenk als Hilfe gegen den Magram Clan.",h="Ein Außenstehender bietet dem Gelkis Clan im Dorf der Gelkis einen Beutel voller Totems an.",kw={"freundschaft erkaufen","zentaur","gelkis","gelkis clan","dorf der gelkis","magram","molkar","totembeutel"},sec={{t="Ein Geschenk für die Gelkis",b="Jemand hat einen Beutel voller Totems vorbereitet, den Ihr dem Rüstmeister im Dorf der Gelkis bringen sollt. Die Gelkis verlieren gegenüber den Magram an Boden, und ihre Isolation könnte sie für Hilfe von außen empfänglich machen. Das Geschenk soll Euer Ansehen beim Clan verbessern."}},faq={{q="Warum den Gelkis einen Beutel voller Totems bringen?",a="Das Geschenk soll Euer Ansehen beim Gelkis Clan verbessern, der gegenüber den Magram an Boden verliert.",al={"totembeutel","warum totems","geschenk für die gelkis"}},{q="Wer erhält den Beutel?",a="Der Rüstmeister im Dorf der Gelkis erhält den Beutel.",al={"rüstmeister der gelkis","wer erhält den beutel","empfänger der totems"}},{q="Welchen Schwierigkeiten stehen die Gelkis gegenüber?",a="Die Gelkis sind gegenüber den Magram im Nachteil, deren Clan ungewöhnlich grausam gewesen ist.",al={"problem der gelkis","magran gelkis","warum verlieren sie"}},{q="Wer ist Molkar?",a="Molkar ist der Rüstmeister der Gelkis, der den Beutel erhält.",al={"molkar gelkis","rüstmeister molkar","wer ist molkar"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94877"] = {n="Saving Sunnyglade",s="Demar Brant bittet Euch, die Truppen von Twilight's Hammer aus Sonnengrund zu vertreiben, einer Siedlung im Nordwesten von Farholde. Die Menschen dort haben ihre Häuser verloren und erhalten kaum Hilfe aus Sturmwind.",h="Demar Brant bittet Euch, die Truppen von Twilight's Hammer aus Sonnengrund zu vertreiben, einer Siedlung im...",kw={"demar brant","farholde","flüchtlinge","sonnengrund retten","sonnengrund","twilight neophytes","twilight raiders","twilight shadowmancers","twilight's hammer"},sec={{t="Eine verlorene Siedlung",b="Demar Brant spricht für die erschöpften Menschen von Farholde, darunter Flüchtlinge, die ohne ihre Familien einer Tragödie entkommen sind. Sturmwind überlässt sie sich selbst, während ihre Mittel schwinden. Twilight's Hammer hat eine Siedlung im Nordwesten eingenommen, und Demar bittet Euch, die Truppen aus Sonnengrund zu vertreiben."}},faq={{q="Wer bittet um Hilfe?",a="Demar Brant bittet Euch, die Truppen von Twilight's Hammer aus Sonnengrund zu vertreiben.",al={"wer ist demar","demar brant","wer hat das gegeben"}},{q="Was ist mit Sonnengrund geschehen?",a="Twilight's Hammer hat eine Siedlung im Nordwesten von Farholde eingenommen.",al={"was ist hier geschehen","sonnengrund verloren","wer hat sonnengrund eingenommen"}},{q="Wer sind die Menschen in Farholde?",a="Viele sind Flüchtlinge, die ohne ihre Familien einer Tragödie entkommen sind.",al={"menschen in farholde","wer lebt dort","flüchtlinge"}},{q="Warum bittet Demar um Hilfe?",a="Farholde hat eine Siedlung an Twilight's Hammer verloren, während die Menschen dort immer weniger Mittel haben, sich selbst zu helfen.",al={"warum demar helfen","warum kämpfen","was ist das problem"}}},fp="17,188,17.280.0,23.71.0,28.64.0,31.61.0,25.114.0"}
P.entries["quest:94879"] = {n="Scraps of Knowledge",s="Ashe Amberall bittet Euch, in Sonnengrund nach Dokumenten des Twilight's Hammer zu suchen. Sie hofft, dass die Seiten die Absichten des Kults offenbaren.",h="Ashe Amberall bittet Euch, in Sonnengrund nach Dokumenten des Twilight's Hammer zu suchen.",kw={"ashe amberall","demar","dokumente","burg farholde","bruchstücke des wissens","sonnengrund","twilight pages","twilight's hammer"},sec={{t="Seiten in Sonnengrund",b="Von Burg Farholde aus blickt Ashe Amberall nach Sonnengrund, der zerstörten Stadt im Norden. Demar hat Truppen geschickt, doch die Stadt ist nicht mehr zu retten. Ashe glaubt, dass der Twilight's Hammer schon früher zugeschlagen hat und seine Angriffe von einem zentralen Ort aus koordiniert. Sie bittet Euch, in Sonnengrund nach verlegten Dokumenten zu suchen, in der Hoffnung, dass genügend Seiten ihr helfen, die Absichten des Kults zusammenzusetzen."}},faq={{q="Wer will die Seiten des Twilight's Hammer?",a="Ashe Amberall in Burg Farholde bittet Euch, die Twilight Pages zu finden.",al={"wer will die seiten","ashe seiten","wer hat mich gebeten"}},{q="Wo soll ich nach den Seiten suchen?",a="Ashe bittet Euch, in Sonnengrund nach Twilight Pages zu suchen.",al={"wo sind die seiten","papiere aus sonnengrund","twilight pages finden"}},{q="Was hofft Ashe herauszufinden?",a="Ashe hofft, dass die Dokumente ihr helfen, die Absichten des Twilight's Hammer zusammenzusetzen.",al={"was ashe wissen will","warum seiten","pläne des twilight's hammer"}},{q="Warum fragt Ashe nach dem Twilight's Hammer?",a="Ashe glaubt, dass der Angriff auf Sonnengrund nicht der erste des Twilight's Hammer war, und vermutet, dass der Kult seine Angriffe von einem zentralen Ort aus koordiniert.",al={"warum twilight's hammer","angriffe des kults","was zuvor geschah"}}},fp="19,131,19.381.0,29.67.0,34.61.0,29.89.0,47.132.0"}
P.entries["quest:94881"] = {n="Curious Trinkets",s="Ashe Amberhall in Burg Farholde bittet Euch, mehr über den Kult in Sonnengrund herauszufinden, indem Ihr ihr seine verzauberten Amulette bringt. Sie glaubt, dass die Zeichen etwas über die Magie des Kults verraten können.",h="Ashe Amberhall in Burg Farholde bittet Euch, mehr über den Kult in Sonnengrund herauszufinden, indem Ihr ihr...",kw={"ashe amberhall","kult","curious trinkets","burg farholde","sonnengrund","twilight charms","twilight neophyte","twilight shadowmancer"},ang={["class:Druid"]="Als Druide hält Ashe Euch für jemanden, der ihr bei ihren Nachforschungen über den Kult in Sonnengrund helfen könnte."},sec={{t="Eine Bitte in Farholde",b="Ashe Amberhall möchte den Kult in Sonnengrund erforschen, wo magisches Geschick einigen Mitgliedern Gunst und Zeichen einbringt. Sie glaubt, dass die Amulette Magie des Kults in sich tragen. Deshalb sollt Ihr ihr Amulette bringen, die Ihr Twilight Shadowmancers und Twilight Neophytes abgenommen habt."}},faq={{q="Wer bittet um die Amulette?",a="Ashe Amberhall möchte die Amulette des Kults untersuchen. Ihr findet sie in Burg Farholde.",al={"wer möchte amulette","ashe amberhall","ashes bitte"}},{q="Warum möchte Ashe die Amulette?",a="Ashe möchte mehr über den Kult in Sonnengrund erfahren und glaubt, dass dessen Amulette Magie des Kults enthalten.",al={"warum amulette","wofür sind amulette","ashe möchte zeichen"}},{q="Was sind Twilight Charms?",a="Es sind Zeichen, die Kultmitgliedern mit einer Begabung für Magie verliehen und dann mit Magie des Kults erfüllt werden.",al={"twilight charms","kultzeichen","magische amulette"}},{q="Wer trägt die Amulette?",a="Twilight Shadowmancers und Twilight Neophytes in Sonnengrund tragen die Amulette, nach denen Ashe sucht.",al={"wo amulette finden","amulette der shadowmancers","zeichen der neophytes"}}},fp="16,184,21.250.0,29.71.0,30.97.0,25.97.0,23.88.0"}
P.entries["quest:94885"] = {n="Field Marshal's Log",s="Das Field Marshal's Log verzeichnet die Bewegungen von Twilight's Hammer durch die Flusslande. Sein Verbleib könnte den Leuten in Farholde helfen, die Bewegungen des Feindes zu verstehen.",h="Das Field Marshal's Log verzeichnet die Bewegungen von Twilight's Hammer durch die Flusslande.",kw={"demar brant","bewegungen des feindes","farholde","field marshal log","field marshal's log","flusslande","sonnengrund","twilight's hammer"},sec={{t="Das Log",b="Demar Brant in Burg Farholde wartet auf das Field Marshal's Log. Darin werden die Truppenbewegungen von Twilight's Hammer durch die Flusslande festgehalten, und jemand in Farholde möchte die Aufzeichnungen sehen. Der Verfasser ist nirgends zu finden. Die Notizen könnten zeigen, wo sich der Feind bewegt hat."},{t="Farholdes Sorge",b="Demar Brant sagt, die Notizen seien zu spät eingetroffen. Farholde kennt die Gefahren in Sonnengrund bereits, und er ist beunruhigt, dass Ihr die Notizen auch dort gefunden habt."}},faq={{q="Was steht im Field Marshal's Log?",a="Das Log verzeichnet die Bewegungen der Truppen von Twilight's Hammer in den Flusslanden.",al={"field marshal log","was steht im log"}},{q="Wer hat das Log geschrieben?",a="Der Verfasser des Field Marshal's Log ist nirgends zu finden.",al={"verfasser des logs","wer schrieb die notizen"}},{q="Wer möchte das Log sehen?",a="Jemand in Farholde möchte das Log sehen. Ihr sollt es Demar Brant in Burg Farholde bringen.",al={"wer bekommt das log","demar brant log"}},{q="Warum ist das Log wichtig?",a="Die Aufzeichnungen über die Bewegungen von Twilight's Hammer könnten helfen, die Bewegungen des Feindes zu erhellen.",al={"warum das log bringen","bewegungen des feindes"}},{q="Wohin bewegten sich die Truppen von Twilight's Hammer?",a="Das Log verzeichnet die Truppen von Twilight's Hammer in den Flusslanden.",al={"twilight's hammer flusslande","wo waren sie"}}},fp="19,155,7.280.0,18.153.1,35.94.0,18.61.0,25.102.0,24.82.0,47.68.0"}
P.entries["quest:94886"] = {n="The Western Front",s="Farholdes Patrouille ist an den westlichen Grenzen verschwunden. Miss Amberhalls Erkenntnisse deuten auf ein Lager des Twilight Hammer hin. Ihr sollt Sergeant Riftan nahe dem Zwielichtschleier finden.",h="Farholdes Patrouille ist an den westlichen Grenzen verschwunden.",kw={"farholde","miss amberhall","vermisste patrouille","sergeant riftan","sonnengrund","twilight hammer","zwielichtschleier","westliche grenzen","westliche front"},sec={{t="Eine vermisste Patrouille",b="Eine Patrouille aus Farholde verschwand an den westlichen Grenzen, und Sergeant Riftan gilt ebenfalls als vermisst. Miss Amberhalls Erkenntnisse lassen befürchten, dass die Patrouille das zentrale Lager des Twilight Hammer erreicht hat. Ihr sollt Riftan nahe dem Zwielichtschleier im Westen suchen."}},faq={{q="Wer wird vermisst?",a="Eine Patrouille aus Farholde verschwand an den westlichen Grenzen. Ihr sollt Sergeant Riftan finden.",al={"vermisste patrouille","wo ist riftan","vermisster sergeant"}},{q="Wo soll ich nach Sergeant Riftan suchen?",a="Sergeant Riftan ist nahe dem Zwielichtschleier im Westen.",al={"riftans aufenthaltsort","riftan finden","wo ist der sergeant"}},{q="Warum wird die Patrouille vermisst?",a="Miss Amberhalls Erkenntnisse lassen Farholde befürchten, dass die Patrouille in das zentrale Lager des Twilight Hammer geraten ist.",al={"was geschah mit der patrouille","warum verschwand die patrouille","patrouille des twilight hammer"}},{q="Wer ist Miss Amberhall?",a="Miss Amberhall ist die Dame, deren Erkenntnisse die Sorge wecken, dass die Patrouille das zentrale Lager des Twilight Hammer erreicht hat.",al={"amberhall","infos zu miss amberhall","wer ist amberhall"}},{q="Was geschieht in Sonnengrund?",a="Farholde sagt, es könne sich selbst um die Aufräumarbeiten in Sonnengrund kümmern, während Ihr Sergeant Riftan überprüfen sollt.",al={"probleme in sonnengrund","aufräumarbeiten in sonnengrund","was ist in sonnengrund los"}}},fp="17,204,16.283.0,15.105.0,40.58.0,26.112.0,22.121.0,32.110.0"}
P.entries["quest:94887"] = {n="Saving Marshal Ryan",s="Die Allianz muss Marshal Ryan finden, einen ihrer besten Späher. Seine letzten Berichte weisen auf eine Festung von Twilight's Hammer im Westen hin, und sein Logbuch könnte weitere Hinweise enthalten.",h="Die Allianz muss Marshal Ryan finden, einen ihrer besten Späher.",kw={"allianz","logbuch","marshal ryan","vermisster marshal","marshal ryan retten","twilight's hammer","zwielichtschleier"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Marshal Ryan zu finden, dessen Berichte für die Kriegsanstrengungen wichtig waren."},sec={{t="Der vermisste Marshal",b="Seine letzten Berichte verorten Marshal Ryan nahe einer Festung des Twilight's Hammer im Westen. Ihr werdet ausgesandt, ihn im Zwielichtschleier zu finden und sein Logbuch mitzunehmen. Die Allianz verlässt sich auf sein scharfes Auge und seine verlässlichen Informationen, und seine Berichte könnten helfen, seinen Aufenthaltsort aufzudecken."}},faq={{q="Wer ist Marshal Ryan?",a="Marshal Ryan ist einer der besten der Allianz und wird für seine scharfen Augen und verlässlichen Informationen geschätzt.",al={"wer ist marshal ryan","wer ist ryan"}},{q="Wo ist Marshal Ryan?",a="Marshal Ryan wird im Zwielichtschleier gesucht, nahe einer Festung von Twilight's Hammer im Westen.",al={"wo ist ryan","marshal ryan finden"}},{q="Warum wird Ryan vermisst?",a="Seine letzten Berichte erwähnen eine Festung von Twilight's Hammer im Westen, und die Allianz hat ihn nicht gefunden.",al={"warum ist ryan verschwunden","was ist marshal ryan zugestoßen"}},{q="Warum will die Allianz sein Logbuch?",a="Marshal Ryans Logbuch könnte Hinweise auf seinen Aufenthaltsort liefern.",al={"warum ryans logbuch","was steht im logbuch"}}},fp="19,173,19.277.0,20.95.0,22.99.0,20.104.0,39.58.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="Sergeant Riftan schickt Euch zurück zum Zwielichtschleier, wo Overlord Kilgar sich weiterhin in seiner Festung versteckt. Die geretteten Soldaten sind kampfbereit, und Riftan will Kilgar zu Fall bringen.",h="Sergeant Riftan schickt Euch zurück zum Zwielichtschleier, wo Overlord Kilgar sich weiterhin in seiner...",kw={"bringt mir seinen kopf","orc","overlord kilgar","gerettete soldaten","sergeant riftan","zwielichtschleier"},sec={{t="Zurück zur Festung",b="Die geretteten Soldaten sind kampfeslustig, und Sergeant Riftan sagt, Eure Stärke habe den Angriff so weit gebracht. Overlord Kilgar, ein Orc, versteckt sich tief in seiner Festung im Zwielichtschleier. Riftan bittet Euch, ihn zu besiegen und seinen Kopf zurückzubringen."}},faq={{q="Wer ist Overlord Kilgar?",a="Overlord Kilgar ist ein Orc-Anführer, der sich tief in seiner Festung im Zwielichtschleier versteckt.",al={"kilgar","wer ist kilgar","orc-anführer"}},{q="Warum werde ich zurück zum Zwielichtschleier geschickt?",a="Die geretteten Soldaten sind kampfbereit, und Sergeant Riftan sagt, der Angriff solle fortgesetzt werden. Er bittet Euch, zum Zwielichtschleier zurückzukehren und den Kopf von Overlord Kilgar zurückzubringen.",al={"warum zurückkehren","aufgabe im zwielichtschleier","wie geht es weiter"}},{q="Wer will Kilgars Kopf?",a="Sergeant Riftan bittet Euch, ihm den Kopf von Overlord Kilgar zu bringen.",al={"was will riftan","wer verlangt kilgars kopf","bringt mir seinen kopf"}},{q="Wo versteckt sich Kilgar?",a="Overlord Kilgar versteckt sich tief in seiner Festung im Zwielichtschleier.",al={"kilgars aufenthaltsort","wo ist der overlord","kilgars festung"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="Ashe Amberhall in Burg Farholde erwartet Euren Bericht nach Eurer Arbeit mit Sergeant Riftan. Eure Rückkehr wird zeigen, ob das Vorhaben gelungen ist.",h="Ashe Amberhall in Burg Farholde erwartet Euren Bericht nach Eurer Arbeit mit Sergeant Riftan.",kw={"ashe amberhall","burg farholde","kilgar","nachricht nach farholde","bericht","sergeant riftan"},sec={{t="Ein Bericht für Ashe",b="Sergeant Riftan schickt Euch mit einem Bericht zu Ashe Amberhall in Burg Farholde zurück. Er gibt Euch Kilgars Kopf mit. Ashe sagt, sie habe während Eurer Abwesenheit begonnen, an ihrem Urteilsvermögen zu zweifeln, lobt nun aber Eure Fähigkeiten."}},faq={{q="Wer erwartet den Bericht?",a="Ashe Amberhall in Burg Farholde wartet auf Euren Bericht.",al={"wem soll ich bericht erstatten","bericht für ashe","bericht nach farholde"}},{q="Was gibt Riftan mir mit?",a="Sergeant Riftan gibt Euch Kilgars Kopf, damit Ihr ihn zu Ashe Amberhall bringt.",al={"was warf riftan zurück","kilgars kopf","was trage ich bei mir"}},{q="Was sagt Ashe, wenn ich zurückkehre?",a="Ashe sagt, sie habe begonnen, zu befürchten, Eure Fähigkeiten falsch eingeschätzt zu haben. Dann sagt sie, Ihr seid die Richtigen für den Auftrag gewesen.",al={"amberhalls reaktion","ashes dialog","war ashe besorgt"}},{q="Was sagt Ashe über Riftan?",a="Ashe fragt, ob Riftan noch da ist, und sagt, sie habe erwartet, dass Ihr beide Euch gut versteht.",al={"lebt riftan noch","was ist mit sergeant riftan","ashe und riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="Marshal Ryan liegt im Sterben und bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen. Seine letzten Worte gelten seiner Heimat und Abigail.",h="Marshal Ryan liegt im Sterben und bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen.",kw={"abigail","wappen","sterbewunsch","burg farholde","knight commander demar brant","marshal ryan","ryan"},sec={{t="Ryans letzte Worte",b="Als Ryans Augen trüb werden, spricht er von seiner Heimat und Abigail. Marshal Ryan gibt Euch sein Wappen und bittet Euch, Knight Commander Demar Brant zu warnen. Ihr bringt das Zeichen seines Ranges zur Burg Farholde, wo der Kommandant wartet."}},faq={{q="Wer liegt im Sterben?",a="Marshal Ryan liegt im Sterben, als er Euch bittet, sein Wappen zu Knight Commander Demar Brant zu bringen.",al={"sterbewunsch wer","marshal ryan"}},{q="Was möchte Ryan, dass ich tue?",a="Ryan bittet Euch, sein Wappen zu Knight Commander Demar Brant zu bringen und ihn zu warnen.",al={"ryans bitte","was mit wappen tun"}},{q="Wer ist Abigail?",a="Ryans letzte Worte erwähnen Abigail und sagen, er hätte nach Hause kommen sollen.",al={"abigail ryan","wer ist abigail"}},{q="Wohin soll ich das Wappen bringen?",a="Bringt Marshal Ryans Wappen zu Knight Commander Demar Brant in die Burg Farholde.",al={"wohin mit dem wappen","aufenthaltsort demar brant"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen. Ryans Tod hinterlässt eine Botschaft für die Frau, die er einst heiraten wollte.",h="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen.",kw={"abigail lawson","kathedralenplatz","abschluss finden","demar","burg farholde","marshal ryan","ryans wappen","sturmwind"},sec={{t="Eine Botschaft in Sturmwind",b="Abigail Lawson wartet auf dem Kathedralenplatz, und Ihr bringt ihr für Demar das Wappen von Marshal Ryan. Sie schloss sich Demar und Ryan nicht an, als sie Burg Farholde errichteten. Ryan und Abigail waren unterschiedlicher Meinung gewesen, doch Demar kennt den Grund nicht. Er glaubt, seine Anwesenheit wäre nicht willkommen, also muss das Wappen an seiner Stelle sprechen."},{t="Unausgesprochene Worte",b="Ryans Familie starb während der Invasion der Orks, und sein Pflichtgefühl, gegen die Horde zu kämpfen, wurde zu Hass. Abigail hatte ihn einst gedrängt, mit ihr und ihren Eltern in Sturmwind zu leben, doch Ryan lehnte ab. Er schwor, zu bleiben, bis er die Orks aus seiner Heimat vertrieben hätte. Ryan und Abigail hatten seitdem nicht mehr miteinander gesprochen."},{t="Das Wappen erhalten",b="Als Ihr ihr das Wappen bringt, spricht Abigail über Ryans Weigerung, seine Heimat zu verlassen, und über ihr langes Schweigen. Sie nennt Demar einen Helden, warnt aber, dass Helden oft jene in ihrer Nähe in Gefahr bringen. Dann drückt sie Ryans Wappen an sich und nennt ihn einen Idioten."}},faq={{q="Wer ist Abigail Lawson?",a="Abigail Lawson war Marshal Ryans Verlobte. Sie lebt in Sturmwind und hatte sich Ryan und Demar in Burg Farholde nicht angeschlossen.",al={"wer ist abigail","ryans verlobte"}},{q="Wer bittet mich, Ryans Wappen zu bringen?",a="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson nach Sturmwind zu bringen. Er glaubt, sie würde seine Anwesenheit nicht willkommen heißen.",al={"wer hat mich geschickt","demars wappen","wer möchte, dass das wappen überbracht wird"}},{q="Warum blieb Ryan zurück?",a="Nachdem Ryans Familie während der Orc-Invasion getötet worden war, wurde aus seiner Pflicht gegenüber der Horde Hass. Er schwor, zu bleiben, bis er die Orcs aus seiner Heimat vertrieben hätte.",al={"warum ryan blieb","ryan und die orcs","seine familie"}},{q="Warum sprachen Abigail und Ryan nicht mehr miteinander?",a="Abigail und Ryan waren unterschiedlicher Meinung, doch Demar kennt die Einzelheiten nicht. Seitdem hatten sie nicht mehr miteinander gesprochen.",al={"warum sie nicht mehr miteinander sprachen","abigail und ryan","ihr streit"}},{q="Wozu dient Ryans Wappen?",a="Demar bittet Euch, Marshal Ryans Wappen zu Abigail Lawson auf dem Kathedralenplatz in Sturmwind zu bringen.",al={"marschallwappen","ryans wappen","was soll ich bringen"}}},fp="18,150,22.324.0,17.293.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer plötzlich zunehmen. Ihr bringt Bolvar Fordragon Beweise, doch die Allianz hat andere Kriege zu bedenken.",h="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer plötzlich zunehmen.",kw={"bolvar fordragon","brant","farholde","horde","kilgar","flusslande","burg sturmwind","twilight's hammer"},ang={["faction:Alliance"]="Als Abenteurer der Allianz bringt Ihr Farholdes Beweise zu Bolvar Fordragon, während dessen Leute Hilfe gegen Twilight's Hammer und die Horde suchen."},sec={{t="Farholdes Bitte",b="Farholdes Leute wenden sich an Euch, nachdem Lady Amberhall von Euren Geschäften mit Twilight's Hammer erfahren hat. Ihr Feldzug begann, um die Horde aus ihrer Heimat zu vertreiben, doch die Aktivitäten der Kultisten haben stark zugenommen. Sie fürchten, Sturmwind werde ihre Bitten nicht erhören, bevor Farholde sich Feinden an zwei Fronten stellen muss. Ihr bringt Bolvar Fordragon in Burg Sturmwind Beweise."},{t="Sturmwinds Antwort",b="In Burg Sturmwind hört Bolvar Fordragon die Warnung aus Farholde. Er sagt, die Allianz befinde sich bereits in einem viel umfassenderen Krieg und könne ihre Kräfte nicht für die private Fehde eines Weilers einsetzen. Die Horde hat mehr Häuser niedergebrannt als jene in den Flusslanden. Bolvar sieht wenig Hoffnung, dass Brant seinen Stolz beiseitelegt und der Allianz seine Kavallerie zu Hilfe schickt."}},faq={{q="Wer bittet Sturmwind um Hilfe?",a="Farholde bittet Sturmwind um Hilfe, da die Aktivitäten von Twilight's Hammer zunehmen.",al={"wer bittet um hilfe","farholdes bitte","wer schickte mich"}},{q="Warum ist Farholde besorgt?",a="Farholde fürchtet, von Feinden an zwei Fronten überwältigt zu werden, wenn Sturmwind seine Bitten nicht erhört.",al={"was ist in farholde los","kultistenproblem","warum besorgt"}},{q="Welche Beweise bringe ich?",a="Ihr bringt Kilgar's Head zu Bolvar Fordragon in Burg Sturmwind.",al={"welche beweise","kilgars kopf","kopf überbringen"}},{q="Von wem hört Bolvar?",a="Bolvar Fordragon erhält Nachrichten aus Farholde, dessen Feldzug begann, die Horde aus seiner Heimat zu vertreiben.",al={"wer schickte die nachricht","bericht aus farholde","frage zu bolvar"}},{q="Warum kann Sturmwind Farholde nicht unterstützen?",a="Bolvar sagt, die Allianz kämpfe in viel größerem Maßstab und habe nicht die Mittel, Farholdes persönliche Fehde zu unterstützen.",al={"warum keine hilfe","unterstützung aus sturmwind","bolvar lehnt ab"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="Friz Frazzlesparks Transportkiste ist im Hafen von Powderfuse in den Flusslanden verschwunden. Ihr Etikett warnt davor, sie ohne Aufsicht zu öffnen, und bittet Euch, sie zu Friz zurückzubringen.",h="Friz Frazzlesparks Transportkiste ist im Hafen von Powderfuse in den Flusslanden verschwunden.",kw={"etikett der kiste","karte der kiste","friz frazzlespark","verlorene transportkiste","hafen von powderfuse","flusslande","warnung"},sec={{t="Eine markierte Kiste",b="Eine Karte und eine Warnung kennzeichnen die Kiste, die Ihr durch die Flusslande tragt. Auf dem Etikett stehen Friz Frazzlespark und der Hafen von Powderfuse, und es bittet darum, die Kiste dorthin zurückzubringen, falls sie verloren geht. Ihr bringt sie zu ihrem Besitzer zurück."}},faq={{q="Wem gehört die Transportkiste?",a="Auf dem Etikett steht Friz Frazzlespark als Besitzer der Transportkiste.",al={"besitzer der kiste","wem gehört diese kiste","friz kiste"}},{q="Wohin soll ich die Kiste bringen?",a="Die Kiste soll zu Friz Frazzlespark im Hafen von Powderfuse in den Flusslanden zurückgebracht werden.",al={"wohin kiste zurückbringen","ziel der kiste","hafen von powderfuse"}},{q="Wovor warnt das Etikett?",a="Das Etikett warnt davor, die Kiste zu manipulieren, und besagt, dass sie nicht ohne Aufsicht geöffnet werden darf.",al={"warnung auf der kiste","darf ich sie öffnen","kiste öffnen"}},{q="Was ist auf der Karte der Kiste markiert?",a="Die Karte zeigt einen roten Kreis an einer südöstlichen Küste, nördlich eines schlecht gezeichneten Tempels, der von Wasser und geflügelten Kreaturen umgeben ist.",al={"karte der kiste","was ist auf der karte","roter kreis auf der karte"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Nach dem Fall von Ban'aethal ist seinen Überlebenden kaum etwas geblieben, das sie ihr Eigen nennen können. Die Siedlung tief im Schattenwindwald begann mitten in der Nacht, in den Himmel zu stürzen, und die Gefahren halten die Flüchtlinge davon ab, ihre zurückgelassenen Besitztümer zu bergen.",h="Nach dem Fall von Ban'aethal ist seinen Überlebenden kaum etwas geblieben, das sie ihr Eigen nennen können.",kw={"aid for the refugees","ban'aethal","banaethal","besitztümer","ealaane","flüchtlinge","schattenwindwald"},sec={{t="Eine verzweifelte Bitte",b="Ealaane und die anderen Flüchtlinge flohen aus ihren Heimen tief im Schattenwindwald. Sie haben sich mit fast nichts versammelt und bitten Reisende, den Gefahren zu trotzen, die sie hinter sich gelassen haben."},{t="Die Katastrophe von Ban'aethal",b="Ban'aethal begann mitten in der Nacht, in den Himmel zu stürzen. Den Bewohnern blieben nur Augenblicke zur Flucht, und sie ließen ihre persönlichen Besitztümer zurück. Die umliegenden Wälder wurden feindselig und gefährlich."}},faq={{q="Wer ist Ealaane?",a="Ealaane floh mit anderen aus Ban'aethal, als ihre Siedlung einzustürzen begann. Sie bittet Reisende auf dem Weg zum Schattenwindwald, die in den Ruinen zurückgelassenen Besitztümer zu bergen.",al={"wer vergab aid for the refugees","questgeber aid for the refugees","ealaane"}},{q="Was geschah mit Ban'aethal?",a="Ban'aethal war eine Siedlung tief im Schattenwindwald. Ihre Bewohner flohen mitten in der Nacht, als eine plötzliche Katastrophe hereinbrach.",al={"was ist banaethal","wo ist banaethal","dorf ban aethal"}},{q="Warum mussten die Dorfbewohner Ban'aethal evakuieren?",a="Ban'aethal begann mitten in der Nacht, in den Himmel zu stürzen, und zwang seine Bewohner zur Flucht. Das Dorf und der umliegende Wald wurden zu gefährlich, um dort zu bleiben oder dorthin zurückzukehren.",al={"warum banaethal evakuieren","in den himmel stürzen","katastrophe von ban aethal"}},{q="Warum bitten die Dorfbewohner darum, ihre Besitztümer zu bergen?",a="Die Katastrophe brach plötzlich mitten in der Nacht herein und ließ den Dorfbewohnern kaum Zeit, mit ihren Besitztümern zu fliehen. Der Wald und die Ruinen sind nun zu gefährlich, weshalb sie auf Reisende angewiesen sind, um das Zurückgelassene zu bergen.",al={"warum besitztümer brauchen","zurückgelassene besitztümer","warum besitztümer bergen"}},{q="Was ist der Schattenwindwald?",a="Der Schattenwindwald ist das bewaldete Gebiet, in dem Ban'aethal stand. Seit die Katastrophe das Dorf auseinandergerissen hat, ist der Wald für gewöhnliche Leute äußerst gefährlich geworden.",al={"wo ist der schattenwindwald","geschichte des schattenwindwalds"}},{q="Können die Flüchtlinge in ihre Heime zurückkehren?",a="Nein. Ealaane sagt, der Schattenwindwald und die Ruinen von Ban'aethal seien zu gefährlich, als dass die Flüchtlinge auf eigene Faust zurückkehren könnten.",al={"können flüchtlinge zurückkehren","ist banaethal sicher"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="Resaan ist seit über einer Woche aus den Ruinen von Ban'aethal fort, und sein Partner wartet auf Nachricht. Reisende auf dem Weg dorthin werden gebeten, ihn heimzubringen oder sein geliebtes Erbstück zurückzubringen.",h="Resaan ist seit über einer Woche aus den Ruinen von Ban'aethal fort, und sein Partner wartet auf Nachricht.",kw={"ban'aethal","erbstück","resaan","ruinen von ban'aethal","vorräte","the fate of a loved one"},sec={{t="Ein verzweifeltes Flehen",b="Resaans Partner fleht ihn an zu bleiben, als er sich auf die Rückkehr in die Ruinen von Ban'aethal vorbereitet. Doch er fühlt sich gedrängt, den Gefahren der Ruinen zu trotzen, um Vorräte zu beschaffen. Sein Partner bleibt zurück und wartet auf Nachricht."},{t="In den Ruinen verschollen",b="Mehr als eine Woche ist vergangen, seit Resaan aufgebrochen ist, weit länger, als eine rasche Rückkehr dauern sollte. Sein Partner bittet Reisende auf dem Weg nach Ban'aethal, die Ruinen zu durchsuchen. Falls Resaan lebt, bringt ihn heim. Falls ihm ein Unglück das Leben genommen hat, bergt sein Familienerbstück."}},faq={{q="Wer ist Resaan?",a="Resaan kehrte in die Ruinen von Ban'aethal zurück, um Vorräte zu beschaffen, obwohl sein Partner ihn angefleht hatte zu bleiben. Seit über einer Woche fehlt jede Nachricht, und sein Partner fürchtet das Schlimmste.",al={"wer ist resaan","wo ist resaan","resaan finden"}},{q="Was sind die Ruinen von Ban'aethal?",a="Die Ruinen von Ban'aethal sind der Ort, an dem Resaan nach Vorräten suchte. Sein Partner fürchtet, dass er dort allein womöglich keine Woche überlebt hat.",al={"was ist banaethal","geschichte der ruinen von banaethal","wo ist banaethal"}},{q="Warum kehrte Resaan nach Ban'aethal zurück?",a="Resaan kehrte nach Ban'aethal zurück, um Vorräte zu holen, obwohl sein Partner ihn angefleht hatte zu bleiben.",al={"warum kehrte resaan zurück","warum ist resaan in banaethal"}},{q="Was sollt Ihr dem Questgeber zurückbringen?",a="Resaans Partner bittet Reisende, ihn sicher heimzubringen, falls er noch lebt. Sollte er in den Ruinen umgekommen sein, bittet sein Partner um sein persönliches Erbstück als Andenken.",al={"was will der questgeber","was passiert wenn resaan tot ist"}},{q="Wie lange wird Resaan schon vermisst?",a="Resaan wird seit über einer Woche vermisst, seit er zu den Ruinen von Ban'aethal aufgebrochen ist. Die Gefahren dort lassen seinen Partner das Schlimmste befürchten.",al={"wie lange wird resaan vermisst","wie lange ist resaan schon fort"}},{q="Wer bietet diese Quest an?",a="Resaans trauernder Partner bittet vorbeikommende Reisende auf dem Weg nach Ban'aethal um Hilfe, verzweifelt bemüht zu erfahren, was aus ihm geworden ist.",al={"wer vergibt the fate of a loved one","the fate of a loved one questgeber"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="Das Lager des Schattenhammers",s="An der Meistergleve im Süden der Dunkelküste sammeln sich Kultisten, während Späher der Allianz ihre Absichten ergründen. Eine Schale der Wahrsagung hat ihre Ritualstätte offenbart. Nun betretet Ihr die Ausgrabung, um zu erfahren, was der Schattenhammer unter der Erde sucht.",h="An der Meistergleve im Süden der Dunkelküste sammeln sich Kultisten, während Späher der Allianz ihre...",kw={"dunkelküste","die meistergleve","onu","schale der wahrsagung","lager des schattenhammers","twilight tome","schattenhammer"},ang={["class:Druid"]="Als Druide helft Ihr den Cenarion wardens, die Forschungen des Kults aufzudecken und zu verhindern, dass sie uralte, unter der Erde begrabene Wesen verderben.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr zu verhindern, dass die seltsamen Ausgrabungen des Kults das nördliche Kalimdor destabilisieren.",["race:NightElf"]="Als Nachtelf seht Ihr, wie der Schattenhammer das heilige Kalimdor unter den uralten Hainen der Dunkelküste entweiht."},sec={{t="Die Ausgrabung erkunden",b="Der Schattenhammer hat die Meistergleve zu einer Bedrohung gemacht. Eine Schale der Wahrsagung offenbarte die Befestigungen der Kultisten. Ihr betretet ihr Lager, um ihre Pläne zu ergründen, bevor die Allianz ihre Verteidigung vorbereiten kann."},{t="Der illustrierte Foliant",b="Im nördlichen Lager der Kultisten liegt ein uralter Foliant voller verstörender Bilder. Seine von Hand bedruckten Seiten offenbaren, dass der Schattenhammer das kolossale Wesen untersucht, das unter der Erde begraben liegt."}},faq={{q="Was ist das Ziel der Quest „Das Lager des Schattenhammers“?",a="Ihr betretet das Lager des Schattenhammers nahe der Meistergleve im Süden der Dunkelküste, um einen Hinweis auf die Beweggründe des Kults zu finden: ein von Hand gedrucktes Ritualbuch.",al={"lager des schattenhammers questziel","was tun im lager des schattenhammers"}},{q="Wer schickt Euch los, um das Lager zu untersuchen?",a="Die Schale der Wahrsagung am Rundblick oberhalb der Meistergleve schickt Euch zur Untersuchung los. Ihr setzt die Nachforschungen fort, die für den uralten Beschützer Onu begonnen wurden.",al={"wer vergibt das lager des schattenhammers","lager des schattenhammers questgeber"}},{q="Wo im Lager findet sich der Hinweis?",a="Der Twilight Tome liegt im nördlichen Teil des Lagers. Andere Folianten können Schutzmagie gegen Eindringlinge entfesseln.",al={"wo ist das buch","twilight tome fundort","hinweis im lager des schattenhammers finden"}},{q="Warum ist der Schattenhammer an der Meistergleve?",a="Die Kultisten suchen nach den dunklen Mächten der Old Gods und ihrer Diener. Um den gewaltigen versteinerten Kadaver, den die riesige Steinklinge festnagelt, graben sie, um das dort verbliebene uralte Böse zu untersuchen oder zu erwecken.",al={"warum sind kultisten an der meistergleve","schattenhammer dunkelküste absicht"}},{q="Was geschieht, nachdem der Foliant gefunden wurde?",a="Der Fund des Folianten führt zu Return to Onu. Ihr bringt die Schriften nach Norden zu dem uralten Treanten im Hain der Uralten.",al={"nächste quest nach dem lager des schattenhammers","wohin nach twilight tome"}}},fx={["8554815a"]={q="Warum weist Euch die Scrying Bowl an, das Lager zu untersuchen?",a="Onus Wahrsageschale enthüllt, dass sich Kultisten von Twilight's Hammer um die Meistergleve versammelt haben, wo vor langer Zeit ein uralter „alter Herr“ fiel. Was sie dort bezwecken, ist unbekannt, doch Onu ist sicher, dass es etwas Finsteres sein muss. Bevor er und die Verteidiger des Hains einen Plan schmieden können, brauchen sie etwas aus dem Lager, das die Absichten des Kults enthüllt.",al={"warum the twilight camp untersuchen","scrying bowl zweck","warum twilight camp durchsuchen"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94907"] = {n="A Small Favor",s="Ein Druide soll die Magie des Twilight's Hammer im Twilight Shroud zu ihrem Ursprung zurückverfolgen. Amberhall will einen Kult-Diener zur Befragung gefangen nehmen.",h="Ein Druide soll die Magie des Twilight's Hammer im Twilight Shroud zu ihrem Ursprung zurückverfolgen.",kw={"ein kleiner gefallen","amberhall","leiter","druide","reagenzien","seelenstein","beschwörungsritual","twilight shroud","twilight's hammer","twilight's thrall"},ang={["class:Druid"]="Als Druide seid Ihr derjenige, den Amberhall einen braven kleinen Druiden nennt, bevor er Euch um diesen Gefallen bittet."},sec={{t="Die Gunst eines Druiden",b="Amberhall bittet Euch im Twilight Shroud um Hilfe. Die Reagenzien, die Ihr gesammelt habt, sind auf die Magie des Twilight's Hammer eingestimmt. Amberhall sagt, dass sie sich für ein Beschwörungsritual eignen. Um zum Ursprung dieser Macht vorzudringen, sollt Ihr mithilfe eines Leiters einen Kult-Diener herbeirufen und ihn mit Amberhalls Seelenstein gefangen nehmen."}},faq={{q="Was möchte Amberhall, dass ich tue?",a="Amberhall bittet Euch, einen Twilight's Thrall über einen Leiter im Twilight Shroud herbeizurufen und ihn mit Amberhalls Seelenstein gefangen zu nehmen.",al={"amberhalls bitte","kleiner gefallen","was soll ich tun"}},{q="Warum eignen sich die Reagenzien?",a="Die Reagenzien sind auf die Magie des Twilight's Hammer eingestimmt und eignen sich daher für ein Beschwörungsritual.",al={"wofür sind die reagenzien","warum reagenzien","reagenzien für zwielichtmagie"}},{q="Wo soll ich den Leiter benutzen?",a="Der Leiter befindet sich im Twilight Shroud.",al={"leiter standort","wo diener beschwören","leiter im twilight shroud"}},{q="Warum soll ich den Diener gefangen nehmen?",a="Amberhall will den Twilight's Thrall zur Befragung gefangen nehmen.",al={"warum seelenstein","warum diener gefangen nehmen","diener befragen"}}},fp="13,143,15.307.0,34.129.0,28.97.0,27.42.0,23.63.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="Ein anderer Skyborne sieht Potenzial in Euren Druidenkünsten und verweist Euch an Turak Runentotem in Donnerfels. Er kann Euch lehren, wie Ihr die Festung des Zirkels des Cenarius in der Mondlichtung erreicht.",h="Ein anderer Skyborne sieht Potenzial in Euren Druidenkünsten und verweist Euch an Turak Runentotem in...",kw={"zirkel des cenarius","child of nature","druide","mondlichtung","skyborne","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide werdet Ihr an Turak Runentotem in Donnerfels verwiesen, der Euch lehren kann, wie Ihr den Zirkel des Cenarius in der Mondlichtung erreicht.",["race:Skyborne"]="Als Skyborne wird Euch gesagt, dass die Druiden des Zirkels des Cenarius Euch willkommen heißen und ihr Wissen mit Euch teilen werden."},sec={{t="Der Willkommensgruß eines Druiden",b="Euer Lehrer glaubt, dass die Druiden des Zirkels des Cenarius Euch willkommen heißen und ihr Wissen mit Euch teilen werden. Turak Runentotem in Donnerfels kann Euch zeigen, wie Ihr ihre Festung in der Mondlichtung erreicht."}},faq={{q="Mit wem soll ich sprechen?",a="Sprecht mit Turak Runentotem in Donnerfels. Er kann Euch lehren, wie Ihr die Mondlichtung erreicht.",al={"mit wem sprechen","turak runentotem","wer ist turak"}},{q="Wo ist die Festung des Zirkels des Cenarius?",a="Die Festung des Zirkels des Cenarius liegt in der Mondlichtung auf Kalimdor.",al={"wo ist der zirkel","standort des zirkels des cenarius","mondlichtung"}},{q="Warum werde ich in die Mondlichtung geschickt?",a="Die Druiden des Zirkels des Cenarius können ihr Wissen mit Euch teilen.",al={"warum mondlichtung","druidenkünste lernen","druidenausbildung"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="In Sturmwind kann Euch Sheldras Moontree den Weg zur Mondlichtung zeigen. Dort teilen die Druiden des Zirkels des Cenarius ihre Weisheit mit einem Kind der Natur.",h="In Sturmwind kann Euch Sheldras Moontree den Weg zur Mondlichtung zeigen.",kw={"zirkel des cenarius","child of nature","druide","kalimdor","mondlichtung","sheldras moontree","skyborne","sturmwind"},ang={["class:Druid"]="Als Druide werdet Ihr zum Zirkel des Cenarius gewiesen, einem uralten Orden, dessen Mitglieder die druidischen Künste ausüben.",["race:Skyborne"]="Als Skyborne gehört Ihr zu den Ersten Eures Volkes, die in Azeroth eintreffen, und werdet willkommen geheißen."},sec={{t="Eine ferne Hochburg",b="Sheldras Moontree, ein Nachtelf in Sturmwind, kann Euch zeigen, wie Ihr die Mondlichtung auf Kalimdor erreicht. Dort hat der Zirkel des Cenarius seine Hochburg. Er ist ein uralter Orden von Naturkundigen und Druiden, der Euch viel lehren kann."}},faq={{q="Wer ist Sheldras Moontree?",a="Sheldras Moontree ist ein Nachtelf in Sturmwind, der Euch zeigen kann, wie Ihr die Mondlichtung erreicht.",al={"sheldras","nachtelf in sturmwind","wer lehrt mich den weg zur mondlichtung"}},{q="Was ist der Zirkel des Cenarius?",a="Der Zirkel des Cenarius ist ein uralter Orden von Naturkundigen und Anhängern der druidischen Künste.",al={"zirkel des cenarius","druidenorden","zirkel der natur"}},{q="Wo liegt die Hochburg des Zirkels des Cenarius?",a="Der Zirkel des Cenarius hat seine Hochburg in der Mondlichtung auf Kalimdor.",al={"hochburg des zirkels des cenarius","wo ist die mondlichtung","mondlichtung"}},{q="Was kann ich vom Zirkel des Cenarius lernen?",a="Die Druiden des Zirkels des Cenarius haben viel Weisheit mit Euch zu teilen.",al={"lehren des zirkels des cenarius","was können sie lehren","weisheit der druiden"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Mondlichtung",s="Euer Lehrer öffnet einen Weg zur Mondlichtung, wo Dendrite Sternenschauer auf Euch wartet. Dort könnt Ihr mit ihm über den Weg sprechen, den Ihr eingeschlagen habt.",h="Euer Lehrer öffnet einen Weg zur Mondlichtung, wo Dendrite Sternenschauer auf Euch wartet.",kw={"bärengestalt","dendrite sternenschauer","druide","hüter remulos","mondlichtung","nachthafen","teleportieren"},ang={["class:Druid"]="Als Druide heißt Euch Euer Lehrer in der Mondlichtung willkommen und lehrt Euch einen Zauber, mit dem Ihr dorthin reisen könnt."},sec={{t="Eine erste Lektion",b="Euer Lehrer heißt Druiden in der Mondlichtung willkommen. Hüter Remulos wacht über jene, die dort rasten. Ihr erhaltet Teleportieren: Mondlichtung, einen Zauber, der Euch dorthin bringt, wenn Ihr Wissen oder Trost sucht. Eure erste Lektion besteht darin, mit Dendrite Sternenschauer in Nachthafen über den Weg zu sprechen, dem Ihr nun folgt."},{t="Die Bärengestalt",b="Dendrite Sternenschauer erkennt, dass Ihr die Bärengestalt bereits gemeistert habt. Er sieht Euch auf einem guten Weg."}},faq={{q="Mit wem sollte ich in der Mondlichtung sprechen?",a="Sprecht mit Dendrite Sternenschauer in Nachthafen über den Weg, auf dem Ihr Euch befindet.",al={"mit wem sprechen","dendrite sternenschauer","nachthafen druide"}},{q="Wie gelange ich zur Mondlichtung?",a="Euer Lehrer gibt Euch Teleportieren: Mondlichtung, einen Zauber, der Euch dorthin bringt.",al={"mondlichtung teleportieren","wie mondlichtung erreichen","teleportationszauber"}},{q="Wer wacht über die Druiden in der Mondlichtung?",a="Hüter Remulos wacht über Druiden, die in der Mondlichtung rasten.",al={"hüter remulos","mondlichtung wächter","wer bewacht mondlichtung"}},{q="Was sagt Dendrite über meine Fortschritte?",a="Dendrite erkennt, dass Ihr die Bärengestalt bereits gemeistert habt.",al={"bärengestalt","bärengestalt gemeistert","dendrites antwort"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie bittet Euch, den Geburtstagshut zu finden, den er am Fluss nahe den Murlocs verloren hat. Er fürchtet, dass seine Familie erfährt, dass er dort war.",h="Robbie bittet Euch, den Geburtstagshut zu finden, den er am Fluss nahe den Murlocs verloren hat.",kw={"geburtstagshut","ellie","hut","verlorener hut","murlocs","fluss","robbie"},sec={{t="Ein verlorener Hut",b="Robbie verlor den Hut, den seine Schwester ihm zum Geburtstag geschenkt hatte, als er am Fluss spielte. Er darf sich den Murlocs nicht nähern und kann daher weder seinen Vater noch Ellie um Hilfe bitten. Er vermutet, dass einer der Murlocs den Hut gefunden hat. Ihr sollt irgendwo am Fluss danach suchen."}},faq={{q="Wer ist Robbie?",a="Robbie ist ein Junge, der den Geburtstagshut verlor, den seine Schwester ihm schenkte, als er am Fluss spielte.",al={"robbie","wer ist robbie"}},{q="Was hat Robbie verloren?",a="Robbie verlor einen Hut, den seine Schwester ihm zum Geburtstag schenkte.",al={"robbies hut","verlorener hut"}},{q="Wo hat Robbie seinen Hut verloren?",a="Robbie verlor seinen Hut, als er im Fluss spielte, und bittet Euch, irgendwo am Fluss nahe den Murlocs danach zu suchen.",al={"fundort des huts","wo ist der hut"}},{q="Warum kann Robbie seine Familie nicht um Hilfe bitten?",a="Robbie darf sich den Murlocs nicht nähern. Wenn er seinen Vater oder Ellie um Hilfe bittet, würde das verraten, wo er gewesen ist.",al={"warum nicht papa fragen","warum verheimlichen"}},{q="Weiß Robbie, ob ein Murloc den Hut genommen hat?",a="Robbie vermutet, dass einer der Murlocs seinen Hut gefunden und behalten hat.",al={"murloc-hut","haben die murlocs ihn genommen"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94924"] = {n="Hunting the Hunters",s="Watcher Cornelius bittet Euch, Rog'mar-Poachers in den Flusslanden aufzuhalten.",h="Watcher Cornelius bittet Euch, Rog'mar-Poachers in den Flusslanden aufzuhalten.",kw={"die jäger jagen","orkische poachers","poachers","flusslande","rog'mar poachers","watcher cornelius"},sec={{t="Poachers in den Ebenen",b="Rog'mar-Poachers durchstreifen die Flusslande in Rudeln, und Watcher Cornelius bittet Euch, ihnen entgegenzutreten. Sie töten Menschen, Löwen und Pferde und bedrohen damit alles Leben in den Ebenen. Ihre Jagd lässt kein Geschöpf sicher sein."}},faq={{q="Wer bittet mich, die Poachers aufzuhalten?",a="Watcher Cornelius bittet Euch, die Rog'mar-Poachers aufzuhalten.",al={"wer hat mich geschickt","cornelius' bitte"}},{q="Wer sind die Rog'mar-Poachers?",a="Sie sind orkische Jäger, die in Rudeln durch die Flusslande streifen.",al={"rog'mar","die poachers"}},{q="Warum sind die Poachers eine Bedrohung?",a="Sie töten Menschen, Löwen und Pferde und bedrohen damit alles Leben in den Flusslanden.",al={"warum poachers aufhalten","gefahr durch poachers"}},{q="Wo streifen die Poachers umher?",a="Die Rog'mar-Poachers durchstreifen die Ebenen der Flusslande.",al={"aufenthaltsort der poachers","wo rog'mar"}}},fp="19,137,22.217.0,33.56.0,29.58.0,30.74.0,27.56.0"}
P.entries["quest:94925"] = {n="A Fur Trade",s="Aufseher Terral sucht Löwenfelle für Farholdes Handel mit einem Händler am Hafen von Powderfuse. Dafür erhält die Siedlung Spezialmunition.",h="Aufseher Terral sucht Löwenfelle für Farholdes Handel mit einem Händler am Hafen von Powderfuse.",kw={"ein pelzhandel","händler","farholde","löwenfell","hafen von powderfuse","prized lion hides","spezialmunition","watcher terral"},sec={{t="Farholdes Handel",b="Farholde ist auf Handel angewiesen, um manche Waren zu erhalten, schätzt aber seine Unabhängigkeit. Aufseher Terral sagt, die Siedlung habe einen Tauschhandel mit einem Händler am Hafen von Powderfuse vereinbart. Farholde liefert Waren, deren Beschaffung gefährlich ist, und der Händler stellt Spezialmunition bereit. Nun möchte der Händler Löwenfell, und Terral bittet Euch, acht Prized Lion Hides von dem Rudel zu holen, das auf einem großen Hügel mitten in den Ebenen lebt."}},faq={{q="Was braucht Aufseher Terral?",a="Aufseher Terral braucht acht Prized Lion Hides für Farholdes Handel mit einem Händler am Hafen von Powderfuse.",al={"was möchte terral","terral felle","löwenfell"}},{q="Mit wem treibt Farholde Handel?",a="Farholde hat einen Tauschhandel mit einem Händler am Hafen von Powderfuse vereinbart.",al={"wer ist der händler","handel am hafen von powderfuse","pelzhandel händler"}},{q="Was erhält Farholde im Tauschhandel?",a="Der Händler stellt Farholde Spezialmunition bereit.",al={"wofür ist die munition","spezialmunition","was stellt der händler bereit"}},{q="Wo leben die Löwen?",a="Ein Rudel Löwen lebt auf einem großen Hügel mitten in den Ebenen.",al={"löwenhügel","wo ist das rudel","löwen in den ebenen"}}},fp="11,144,18.415.0,30.101.0,29.67.0,36.54.0,20.69.0"}
P.entries["quest:94928"] = {n="A Few Furs for Friz",s="Cornelius bittet Euch, Löwenfelle zu Friz Frazzlespark am Hafen von Powderfuse zu bringen. Der Handel ist vereinbart, und Friz soll das Bündel erhalten.",h="Cornelius bittet Euch, Löwenfelle zu Friz Frazzlespark am Hafen von Powderfuse zu bringen.",kw={"ein paar pelze für friz","cornelius","friz frazzlespark","goblinhafen","löwenfelle","hafen von powderfuse"},sec={{t="Eine Lieferung zum Hafen",b="Am Hafen von Powderfuse wartet Friz Frazzlespark auf ein Bündel Löwenfelle. Cornelius hat den Handel bereits vereinbart. Bringt Friz die Felle und sagt ihr, dass sie von Cornelius stammen."}},faq={{q="Für wen sind die Felle?",a="Das Bündel Löwenfelle ist für Friz Frazzlespark am Hafen von Powderfuse bestimmt.",al={"wer bekommt die pelze","felle für friz","wem die felle bringen"}},{q="Wo liegt der Hafen von Powderfuse?",a="Der Hafen von Powderfuse ist ein von Goblins betriebener Hafen im Nordosten.",al={"wo ist powderfuse","lage von powderfuse","wo ist der goblinhafen"}},{q="Wer hat die Felle geschickt?",a="Die Felle stammen von Cornelius.",al={"wer schickte die pelze","cornelius felle","woher stammen sie"}},{q="Um welche Felle handelt es sich?",a="Es sind Löwenfelle.",al={"welche pelze","löwenfelle","welche felle"}}},fp="19,137,15.183.0,22.69.0,25.54.0,19.29.0,28.20.0"}
P.entries["quest:94930"] = {n="Lost Shipping Crate",s="Friz Frazzlesparks Versandkiste ist zur Rücksendung an den Hafen von Powderfuse in den Flusslanden bestimmt. Das Etikett warnt davor, sie ohne Aufsicht zu öffnen.",h="Friz Frazzlesparks Versandkiste ist zur Rücksendung an den Hafen von Powderfuse in den Flusslanden bestimmt.",kw={"kistenetikett","friz frazzlespark","verlorene versandkiste","hafen von powderfuse","roter kreis auf der karte","flusslande"},sec={{t="Eine markierte Kiste",b="Ein handgeschriebenes Etikett kennzeichnet die Kiste als Eigentum von Friz Frazzlespark am Hafen von Powderfuse. Es warnt Euch davor, ohne Aufsicht an der Kiste herumzuhantieren oder sie zu öffnen. Falls Ihr sie verloren findet, nennt das Etikett Friz am Hafen von Powderfuse in den Flusslanden als Ziel."}},faq={{q="Wem gehört die Kiste?",a="Laut Etikett gehört sie Friz Frazzlespark.",al={"kistenbesitzer","wer ist friz","friz kiste"}},{q="Wohin soll die Kiste?",a="Laut Etikett soll die Kiste an Friz Frazzlespark am Hafen von Powderfuse in den Flusslanden zurückgeschickt werden.",al={"kistenstandort","wohin die kiste zurückschicken","kiste hafen von powderfuse"}},{q="Kann ich die Kiste öffnen?",a="Das Etikett warnt davor, die Kiste ohne Aufsicht zu öffnen.",al={"kiste öffnen","was ist darin","kistenwarnung"}},{q="Was zeigt die Karte auf der Kiste?",a="Die Karte zeigt einen großen roten Kreis an einer südöstlichen Küste, nördlich eines von Wasser umgebenen Tempels und einiger geflügelter Kreaturen.",al={"kistenkarte","roter kreis auf der karte","was steht auf dem etikett"}}},fp="19,152,14.260.0,19.52.0,26.94.0,21.62.0,36.124.0"}
P.entries["quest:94931"] = {n="Stolen Saws",s="In der Sägemühle bittet Halligan Turner Euch, von Gnollen gestohlene Sägeblätter zurückzuholen. Die Mühle braucht sie zurück.",h="In der Sägemühle bittet Halligan Turner Euch, von Gnollen gestohlene Sägeblätter zurückzuholen.",kw={"borstenhügel","gnolle","halligan turner","sägewerk","sägeblätter","southern watch","gestohlene sägen"},sec={{t="Fehlende Sägeblätter",b="Southern Watch hält die meisten Gnolle fern, doch einige schleichen sich nachts noch ins Lager und stehlen Sägeblätter. Halligan Turner in der Sägemühle bittet Euch, in den Gnoll-Lagern in den Borstenhügeln danach zu suchen, wo die Sägeblätter vielleicht aufbewahrt werden. Die Sägemühle braucht das scharfe Metall zurück."}},faq={{q="Wer möchte die Sägeblätter zurück?",a="Halligan Turner am Sägewerk möchte die gestohlenen Sägeblätter zurückhaben.",al={"wer bat um sägeblätter","halligan turner sägen"}},{q="Wo wurden die Sägeblätter gestohlen?",a="Einige Gnolle kommen an Southern Watch vorbei und schleichen sich nachts ins Holzfällerlager, um sie zu stehlen.",al={"wo stahlen gnolle sägen","wo gestohlene sägen"}},{q="Wo könnten die Gnolle die Blätter aufbewahren?",a="Die Gnolllager in den Borstenhügeln sind mögliche Verstecke für die Blätter.",al={"gnolllager mit sägeblättern","wo sind die sägen"}},{q="Warum sind die Sägeblätter für die Gnolle nützlich?",a="Die Gnolle verwenden das scharfe Metall vermutlich, um Waffen herzustellen.",al={"was machen gnolle mit sägen","gnolle stellen waffen her"}},{q="Warum braucht das Sägewerk die Blätter?",a="Halligan sagt, dass die Rückgabe der Blätter dem Sägewerk Zeit und Ressourcen ersparen würde.",al={"warum sägeblätter zurückholen","sägewerk braucht sägen"}}},fp="11,110,14.280.0,30.72.0,38.90.0,39.69.0,44.54.0,41.81.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="Ein Magier in Valanaar schickt Euch von der Insel Zephras nach Dalaran, wo mehrere Magier die Ankunft Eures Volkes erwarten. Die Stadt bietet einen Ausgangspunkt, um Azeroth zu erkunden, doch die Länder jenseits davon können ohne Vorbereitung und Erfahrung gefährlich sein.",h="Ein Magier in Valanaar schickt Euch von der Insel Zephras nach Dalaran, wo mehrere Magier die Ankunft Eures...",kw={"kult","dalaran","danaaris stargale","magier","himmelsboot","valanaar","insel zephras"},ang={["race:Skyborne"]="Als Skyborne reist Ihr von der Insel Zephras zu den Magiern, die in Dalaran die Ankunft Eures Volkes erwarten."},sec={{t="Ankunft in Dalaran",b="Die jüngsten Ereignisse mit dem Kult halten den Sprecher vorerst in Valanaar. Mehrere Magier warten in Dalaran auf Euer Volk, also werdet Ihr zum Dock außerhalb der Herberge geschickt. Dort geht Ihr an Bord eines Himmelsboots mit Ziel Dalaran.\n\nSprecht nach Eurer Ankunft mit Danaaris Stargale. Euer Volk richtet sich noch in der Stadt ein, und das Land jenseits ihrer sicheren Grenzen kann sich als gefährlich erweisen."}},faq={{q="Wer wartet in Dalaran?",a="Mehrere Magier erwarten die Ankunft Eures Volkes in Dalaran. Wenn Ihr die Stadt erreicht, sollt Ihr mit Danaaris Stargale sprechen.",al={"magier in dalaran","wer ist in dalaran","dalarans magier"}},{q="Von wo reise ich ab?",a="Ihr reist von der Insel Zephras nach Dalaran, an Bord des Himmelsboots am Dock außerhalb der Herberge.",al={"wie nach dalaran gelangen","von zephras","himmelsboot"}},{q="Warum bleibt der Sprecher in Valanaar?",a="Die jüngsten Ereignisse mit dem Kult haben die Pläne des Sprechers geändert, weshalb er eine Zeit lang in Valanaar bleiben will.",al={"warum in valanaar bleiben","kult änderte pläne","magier in valanaar"}},{q="Ist es außerhalb von Dalaran sicher?",a="Das Land jenseits von Dalaran kann ohne angemessene Vorbereitung und Erfahrung gefährlich sein.",al={"außerhalb dalarans sicher","gefahr nahe dalaran","dalarans umland"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="Ihr erreicht Sturmwind durch das Skyborne-Portal und werdet vom Regenten der Stadt willkommen geheißen. Hochlord Bolvar Fordragon gewährt Euch die Erlaubnis, durch die Länder der Allianz zu reisen.",h="Ihr erreicht Sturmwind durch das Skyborne-Portal und werdet vom Regenten der Stadt willkommen geheißen.",kw={"bolvar fordragon","hochelf","der hohe orden","kirin tor","portal","skyborne","burg sturmwind","welcome to azeroth"},ang={["faction:Alliance"]="Hochlord Bolvar Fordragon heißt den Hohen Orden im Namen von König Anduin Wrynn offiziell willkommen und gewährt seinen Mitgliedern die Erlaubnis, die Länder der Allianz frei zu durchqueren.",["race:Skyborne"]="Als Skyborne werdet Ihr bei Eurer Ankunft durch das Portal in Sturmwind willkommen geheißen und erhaltet freies Geleit durch das Gebiet der Allianz."},sec={{t="Ankunft in der Hauptstadt",b="Ihr tretet durch das Skyborne-Portal nach Sturmwind, der Hauptstadt der Menschen. Von dort führt Euch Euer Weg über die großen Straßen der Stadt zur Burg Sturmwind, wo die Regentschaft Eure Ankunft erwartet."},{t="Eine Audienz beim Regenten",b="Hochlord Bolvar Fordragon empfängt die eintreffenden Mitglieder des Hohen Ordens im Thronsaal. Ein Kurier der Kirin Tor hatte ihm ihre Ankunft angekündigt. Es ist einige Zeit her, seit Hochelfen durch die Hallen der Burg Sturmwind schritten, doch Bolvar heißt sie als Gäste willkommen und gewährt ihnen im Namen des Königs freies Geleit durch die Gebiete der Allianz."}},faq={{q="Worum geht es in dieser Quest?",a="Ihr erreicht Sturmwind durch das Skyborne-Portal und stellt Euch Hochlord Bolvar Fordragon in der Burg Sturmwind vor.",al={"was ist welcome to azeroth","welcome to azeroth quest"}},{q="Wer ist Bolvar Fordragon?",a="Hochlord Bolvar Fordragon regiert Sturmwind als Regent von der Burg Sturmwind aus. Er herrscht im Namen des jungen Königs Anduin Wrynn, während König Varian weiterhin vermisst wird.",al={"wer ist bolvar fordragon","regent von sturmwind"}},{q="Warum empfängt Bolvar die Skyborne?",a="Ein Bote der Kirin Tor teilte Bolvar Fordragon mit, dass Mitglieder des Hohen Ordens eintreffen würden. Er heißt sie als Gäste der Krone willkommen und gewährt ihnen die Erlaubnis, frei durch die Länder der Allianz zu reisen.",al={"warum sind skyborne in sturmwind","hochelfen sturmwind"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden ist die Gruppe, die mit den Hochelfen der Skyborne verbunden ist. Die Kirin Tor kündigten ihre Ankunft bei der Führung Sturmwinds an.",al={"wer ist der hohe orden","geschichte des hohen ordens"}},{q="Wohin führt das Skyborne-Portal?",a="Das Skyborne-Portal bringt Reisende direkt nach Sturmwind, der Hauptstadt der Menschen. Von dort können Neuankömmlinge zur Burg Sturmwind gehen, um eine Audienz bei der Krone zu erbitten.",al={"skyborne-portal ziel","wohin führt das portal"}},{q="Dürfen sich die Skyborne im gesamten Gebiet der Allianz bewegen?",a="Bolvar Fordragon heißt die Skyborne als Gäste des Königs willkommen und gewährt ihnen die Erlaubnis, ungehindert durch sämtliche Länder der Allianz zu reisen.",al={"gehören skyborne zur allianz","skyborne willkommen bei der allianz"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94961"] = {n="Biting the Hand",s="Fuzzle bietet jedem ein Geschäft an, der ihm hilft, Rache zu nehmen. Er verspricht Euch Schätze zu zeigen, sobald Ihr ihm Twilight Finger Bones bringt.",h="Fuzzle bietet jedem ein Geschäft an, der ihm hilft, Rache zu nehmen.",kw={"die hand beißen","fuzzle","gnoll","rache","schatz","twilight finger bones"},sec={{t="Fuzzles Angebot",b="Fuzzle wedelt mit etwas Gold vor Euch, während er Euch ein Geschäft anbietet. Der Gnoll verspricht mehr Schätze, wenn Ihr ihm helft, Rache zu nehmen. Er bittet Euch, ihm zwanzig Twilight Finger Bones zu bringen, bevor er Euch zeigt, was er hat."}},faq={{q="Wer ist Fuzzle?",a="Fuzzle ist ein Gnoll, der Euch Gold anbietet und Schätze verspricht, wenn Ihr ihm helft, Rache zu nehmen.",al={"fuzzle","gnoll mit gold"}},{q="Was will Fuzzle?",a="Fuzzle bittet Euch, ihm zwanzig Twilight Finger Bones zu bringen, damit Ihr ihm helft, Rache zu nehmen.",al={"was will er","fuzzles rache"}},{q="Wozu dienen die Twilight Finger Bones?",a="Fuzzle will zwanzig Twilight Finger Bones, bevor er Euch seine Schätze zeigt.",al={"fingerknochen","zwielichtknochen"}}},fp="15,131,14.206.0,14.97.0,22.82.0,39.75.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="Ein Kampf gegen Bonegnaw ist der nächste Wettstreit auf dem Weg zum Champion in Bloodmaster's Ring. Die Oger warten darauf zu sehen, ob Ihr ihnen einen sehenswerten Kampf liefern könnt.",h="Ein Kampf gegen Bonegnaw ist der nächste Wettstreit auf dem Weg zum Champion in Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","kampf","champion","oger"},sec={{t="Der nächste Kampf",b="Eure Siege haben Euch noch nicht zum Champion gemacht, und der Goblin des Rings hat einen weiteren Kampf im Sinn. Bonegnaw ist Euer Gegner, und der Goblin verspricht eine Überraschung. Die Oger sehen zu, und der nächste Kampf soll sie unterhalten."},{t="Nach dem Kampf",b="Der Goblin ist unzufrieden damit, wie der Kampf auf ihn wirkt. Die Oger scheinen jedoch unterhalten zu sein, und er warnt Euch davor, auf das Ergebnis stolz zu sein."}},faq={{q="Wer ist mein Gegner?",a="Bonegnaw ist Euer Gegner in Bloodmaster's Ring.",al={"kampf gegen bonegnaw","gegen wen kämpfe ich"}},{q="Bin ich schon ein Champion?",a="Der Goblin des Rings sagt, Eure Siege hätten Euch noch nicht zum Champion gemacht.",al={"bloodmaster champion","champion werden"}},{q="Wer sieht dem Kampf zu?",a="Oger sehen dem Kampf in Bloodmaster's Ring zu.",al={"oger sehen zu","wer ist unterhalten"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94963"] = {n="Biting the Hand",s="Fuzzle bittet Euch, mit ihm aufzubrechen, und verspricht eine Belohnung, sobald Ihr in Sicherheit seid. Er knurrt und droht jedem, der Euch verfolgen will.",h="Fuzzle bittet Euch, mit ihm aufzubrechen, und verspricht eine Belohnung, sobald Ihr in Sicherheit seid.",kw={"die hand beißen","fuzzle","gnoll","gold","aufbrechen","belohnung","sicher"},sec={{t="Aufbruch mit Fuzzle",b="Fuzzle ist bereit aufzubrechen und bittet Euch, mit ihm zu gehen. Er warnt, dass jeder, der Euch aufzuhalten versucht, in Stücke gerissen wird. Eure Sicherheit geht vor; er verspricht eine Belohnung, sobald Ihr außer Gefahr seid."}},faq={{q="Wer bittet mich aufzubrechen?",a="Fuzzle bittet Euch, mit ihm aufzubrechen.",al={"wer ist fuzzle","fuzzle?","wer will aufbrechen"}},{q="Womit droht Fuzzle?",a="Fuzzle droht, jeden in Stücke zu reißen, der Euch aufzuhalten versucht.",al={"was sagt fuzzle","fuzzles drohung","wen wird er angreifen"}},{q="Wann gibt Fuzzle mir eine Belohnung?",a="Fuzzle sagt, er werde Euch eine Belohnung geben, sobald Ihr in Sicherheit seid.",al={"fuzzles belohnung","wann belohnung","was verspricht er"}},{q="Was ist die Belohnung?",a="Fuzzle hat einen beträchtlichen Goldbetrag angehäuft, der Euch gehört.",al={"was bekomme ich","fuzzles gold","belohnung von fuzzle"}}},fp="15,125,19.190.0,26.34.0,26.60.0,34.56.0,19.60.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="Ein Ringansager ruft Euch zum Kampf gegen Mog’thar im Bloodmaster’s Ring. Das Publikum wartet auf den nächsten Herausforderer.",h="Ein Ringansager ruft Euch zum Kampf gegen Mog’thar im Bloodmaster’s Ring.",kw={"ansager","bloodmaster’s ring","herausforderer","publikum","mog’thar","ring"},sec={{t="Der nächste Herausforderer",b="Der Ansager hat das Publikum in Spannung gehalten und kündigt nun Mog’thar als nächsten Herausforderer an. Ihr werdet in den Bloodmaster’s Ring gerufen, während das Publikum gespannt darauf wartet, was geschieht."}},faq={{q="Gegen wen trete ich im Bloodmaster’s Ring an?",a="Ihr werdet zum Kampf gegen Mog’thar im Bloodmaster’s Ring gerufen.",al={"kampf gegen mog’thar","wer ist der nächste herausforderer","gegner im bloodmaster’s ring"}},{q="Was sagt der Ansager über Mog’thar?",a="Der Ansager sagt, Mog’thar sei kein Spaß.",al={"wer ist mog’thar","nächster herausforderer","ist mog’thar ein witz"}},{q="Warum werde ich in den Ring geschickt?",a="Der Ansager will die Spannung beim Publikum aufrechterhalten, indem er einen weiteren Herausforderer ankündigt.",al={"warum gegen mog’thar kämpfen","grund für den ringkampf","was will der ansager"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94965"] = {n="Bloodmaster's Ring",s="Der Goblin Jezap fordert Euch auf, Euch bei den Ogern zu beweisen und Euch Snufflesnout im Bloodmaster's Ring zu stellen. Ihr Lieblingsleckerbissen lockt sie in den Kampf, doch Chub'chob könnte das Ergebnis übelnehmen.",h="Der Goblin Jezap fordert Euch auf, Euch bei den Ogern zu beweisen und Euch Snufflesnout im Bloodmaster's Ring...",kw={"bloodmaster ring","bloodmaster's ring","chub'chob","oger","snufflesnout","leckerbissen"},sec={{t="Eine Prüfung für Euch",b="Jezap legt einen Leckerbissen bereit, bevor Ihr den Bloodmaster's Ring betretet. Snufflesnout mag ihn, und sein Anblick stachelt sie an. Eure Prüfung besteht darin, Euch der Gefährtin von Chub'chob zu stellen und Euch bei den Ogern zu beweisen."},{t="Nach dem Kampf",b="Die Gefährtin von Chub'chob ist Snufflesnout, und wenn Ihr sie besiegt, sorgt das für Ärger zwischen Euch und den Ogern. Seid jetzt vorsichtig in ihrer Nähe."}},faq={{q="Wer ist Snufflesnout?",a="Snufflesnout ist die Gefährtin von Chub'chob und mag einen bestimmten Leckerbissen.",al={"snufflesnout","snuffle snout","chubchobs haustier"}},{q="Wozu dient der Leckerbissen?",a="Jezap nutzt Snufflesnouts Lieblingsleckerbissen, um sie in den Bloodmaster's Ring zu locken.",al={"snufflesnouts leckerbissen","wozu ist der leckerbissen","snufflesnout füttern"}},{q="Was ist der Bloodmaster's Ring?",a="Dort stellt Ihr Euch Snufflesnout, um Euch vor den Ogern zu beweisen.",al={"bloodmaster ring","der ring","wo kämpfe ich gegen snufflesnout"}},{q="Warum kämpfe ich gegen Snufflesnout?",a="Jezap sagt, dass es vor allem darauf ankommt, Euch bei den Ogern zu beweisen, und dass Euch Snufflesnout als Prüfung erwartet.",al={"kampf gegen snufflesnout","warum gegen sie kämpfen","mich vor ogern beweisen"}}},fp="18,207,14.204.0,15.124.1,20.72.0,21.81.0,31.74.0,31.98.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="Krom'rosh schickt Euch in die Feste Krol'dok, denn der Stützpunkt des Twilight cult ist größer als erwartet. Er bittet Euch um einen Beweis für den Tod ihres Anführers.",h="Krom'rosh schickt Euch in die Feste Krol'dok, denn der Stützpunkt des Twilight cult ist größer als erwartet.",kw={"höhle","anführer des kults","auge von mugg","feste krol'dok","krom'rosh","opferungen","twilight cult"},sec={{t="Feste Krol'dok",b="Krom'rosh fürchtet, dass weitere Verbündete geopfert werden, wenn der Twilight cult diese Lande weiter verwüstet. Nur wenige, die die Höhle betraten, überlebten, und der Stützpunkt des Kults ist größer, als er glaubte. Nun sollt Ihr die Feste Krol'dok betreten und mit einem Beweis für den Tod des Anführers zurückkehren."}},faq={{q="Wer schickt mich in die Feste Krol'dok?",a="Krom'rosh schickt Euch in die Feste Krol'dok, um einen Beweis dafür zurückzubringen, dass der Anführer des Twilight cult tot ist.",al={"wer schickte mich","krom'roshs auftrag"}},{q="Was stimmt mit der Feste nicht?",a="Der Twilight cult hat einen größeren Stützpunkt als Krom'rosh erwartet hat, verwüstet die Lande und opfert Verbündete.",al={"was geschieht dort","problem mit dem twilight cult"}},{q="Warum will Krom'rosh, dass ich hineingehe?",a="Krom'rosh will den Kult aufhalten, bevor er die Lande weiter verwüsten und Verbündete opfern kann.",al={"warum hineingehen","warum die feste betreten"}},{q="Welchen Beweis verlangt Krom'rosh?",a="Er bittet um einen Beweis dafür, dass der Anführer des Twilight cult tot ist.",al={"benötigter beweis","was soll ich zurückbringen"}},{q="Haben viele überlebt, die die Höhle betraten?",a="Nur wenige, denen es gelang, die Höhle zu betreten, überlebten.",al={"überlebende der höhle","wer kam lebend heraus"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94972"] = {n="Tome of Twilight",s="In der Feste Krol'dok sollt Ihr den Tome of Twilight bergen. Sein Inhalt könnte im Kampf gegen die Kultisten helfen.",h="In der Feste Krol'dok sollt Ihr den Tome of Twilight bergen.",kw={"kultisten","informationen","feste krol'dok","geheimnisse","tome of twilight"},sec={{t="Ein verborgenes Schriftstück",b="Die Geheimnisse der Feste könnten nützliches Wissen über die Kultisten bergen. Ihr sollt die Feste Krol'dok durchsuchen und den Tome of Twilight bergen, damit seine Informationen zurückgebracht werden können."}},faq={{q="wonach soll ich suchen?",a="Ihr sollt den Tome of Twilight aus der Feste Krol'dok bergen.",al={"tome of twilight","welcher foli ant","welches buch"}},{q="warum ist der Foliant wichtig?",a="Der Foliant könnte Informationen enthalten, die im Kampf gegen die Kultisten nützlich sind.",al={"warum den folianten holen","wozu ist er da","informationen über kultisten"}},{q="wo ist der Tome of Twilight?",a="Der Tome of Twilight soll aus der Feste Krol'dok geborgen werden.",al={"wo ist der foli ant","kroldok foli ant","buch in der feste"}}},fp="16,123,15.190.0,22.71.0,25.74.0,30.65.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="Ein nahe Rog'mar gefundenes Formstück scheint Teil eines Schlüssels zu sein. Vielleicht weiß jemand in der Siedlung, was es öffnet.",h="Ein nahe Rog'mar gefundenes Formstück scheint Teil eines Schlüssels zu sein.",kw={"schlüssel","krol'dok-formstück","form","formstück","rog'mar","festung"},sec={{t="Eine seltsame Form",b="Ihr habt ein Formstück, das für einen Schlüssel gemacht zu sein scheint. In Rog'mar weiß vielleicht jemand, wozu das Stück dient. Wenn es aus der Festung stammt, könnte es wichtig sein."}},faq={{q="Wozu dient das Formstück?",a="Das Formstück scheint für einen Schlüssel bestimmt zu sein.",al={"formstück","was ist diese form","schlüsselform"}},{q="Wer kann das Formstück identifizieren?",a="Jemand in Rog'mar weiß vielleicht etwas über die Form.",al={"wer weiß etwas über die form","nach der form fragen","wohin mit der form"}},{q="Warum könnte es wichtig sein?",a="Wenn das Formstück aus der Festung stammt, muss es wichtig sein.",al={"ist die form wichtig","festungsform","warum die form wichtig ist"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn braucht Leder und Eisen für eine Schlüsselgussform. Ihr sammelt die Materialien, während sie die Glut heiß hält.",h="Kreza Darkthorn braucht Leder und Eisen für eine Schlüsselgussform.",kw={"glut","iron bar","schlüssel","schlüsselzutaten","kreza darkthorn","gussform","thick leather"},sec={{t="Materialien für die Gussform",b="Kreza Darkthorn besitzt eine abgenutzte Gussform, aus der vielleicht ein Schlüssel gefertigt werden kann. Ihr bringt ihr vier Thick Leather und zwölf Iron Bar, während sie die Glut heiß hält. Die Gussform sollte halten, und Kreza ist bereit herauszufinden, was sich damit machen lässt."}},faq={{q="Was braucht Kreza?",a="Kreza bittet Euch, vier Thick Leather und zwölf Iron Bar zu bringen.",al={"welche materialien","schlüsselzutaten","was braucht kreza"}},{q="Wofür sind die Materialien?",a="Die Materialien werden gebraucht, um aus einer groben, abgenutzten Gussform einen Schlüssel zu fertigen.",al={"warum leder und eisen","wofür ein schlüssel","materialien für die gussform"}},{q="Wer hält die Glut heiß?",a="Kreza Darkthorn sagt, sie werde die Glut heiß halten, während Ihr die Materialien sammelt.",al={"wer hält die glut heiß","kreza glut","glut heiß"}},{q="Was sagt Kreza über die Gussform?",a="Kreza sagt, die Gussform sei grob und abgenutzt, könne aber vielleicht noch zur Fertigung eines Schlüssels verwendet werden.",al={"zustand der gussform","ist die gussform brauchbar","schlüsselgussform"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="Ein Verbündeter bittet Euch, den Twilight’s Hammer in einem Höhlennetz nahe der Feste Krol'dok aufzuspüren. Ihre Angriffe haben Euren Verbündeten geschadet und bedrohen das Land.",h="Ein Verbündeter bittet Euch, den Twilight’s Hammer in einem Höhlennetz nahe der Feste Krol'dok aufzuspüren.",kw={"ein zeichen der rache","ohren von kultisten","kultisten","verborgene höhle","feste krol'dok","twilight's hammer"},sec={{t="Die verborgenen Höhlen",b="Die Späher haben berichtet, dass sich Kultisten des Twilight’s Hammer unter dem zerklüfteten Boden nahe der Feste Krol'dok bewegen. Euer Verbündeter sagt, ihre Angriffe hätten Euren Verbündeten großen Schmerz zugefügt und die Kultisten würden das Land für sich beanspruchen. Ihr sollt ihr Versteck finden und fünfzehn Ohren von Kultisten als Zeichen der Rache zurückbringen."}},faq={{q="Wen suche ich?",a="Ihr sucht Kultisten des Twilight’s Hammer, die sich in einem Höhlennetz nahe der Feste Krol'dok verstecken.",al={"wer sind die kultisten","twilight hammer hier","ohren von kultisten"}},{q="Warum werden die Kultisten gejagt?",a="Der Auftraggeber sagt, die Kultisten hätten seinen Verbündeten Schmerz zugefügt und würden das Land für sich beanspruchen.",al={"warum rache","warum gegen sie kämpfen","was haben sie getan"}},{q="Was wissen die Späher?",a="Späher meldeten Bewegungen von Kultisten unter dem zerklüfteten Gelände, in einem verborgenen Höhlennetz im Norden.",al={"bericht der späher","wo sind die kultisten","bewegungen der kultisten"}},{q="Was soll ich zurückbringen?",a="Ihr sollt fünfzehn Cultist Ears vom Twilight’s Hammer bei der Feste Krol'dok sammeln.",al={"was soll ich sammeln","ohren quest","wie viele ohren"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale lehrt Euch die Bindung zwischen Tier und Meister. Ihr beginnt damit, einen Windsong Crawler nahe den Gewässern von Zephras zu zähmen.",h="Quel'ana Quickgale lehrt Euch die Bindung zwischen Tier und Meister.",kw={"tiere zähmen","quel'ana quickgale","zähmerrute","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Die erste Bindung",b="Ihr habt die Zähmerrute und einen Windsong Crawler zu zähmen. Findet einen in der Nähe eines Gewässers und übt Eure Fähigkeiten. Bringt die Rute dann zu Quel'ana Quickgale in Valanaar zurück. Dieses Geschöpf ist Euer erster Schritt zur Meisterschaft."}},faq={{q="Was soll ich für Quel'ana zähmen?",a="Quel'ana bittet Euch, einen Windsong Crawler in der Nähe eines Gewässers auf Zephras zu zähmen.",al={"welches tier","zähmziel","crawler-quest"}},{q="Wozu dient die Zähmerrute?",a="Mit der Zähmerrute zähmt Ihr einen Windsong Crawler.",al={"wie die rute funktioniert","zähmwerkzeug","rutenquest"}},{q="Wo finde ich einen Windsong Crawler?",a="Windsong Crawlers leben in der Nähe von Gewässern auf Zephras.",al={"crawler-fundort","wo crawler","zephras tier"}},{q="Wer hat mir die Zähmerrute gegeben?",a="Quel'ana Quickgale gibt Euch die Zähmerrute in Valanaar.",al={"questgeber","wer ist quelana","quelana quickgale"}},{q="Warum lerne ich, ein Tier zu zähmen?",a="Die Bindung zwischen Tier und Meister kennenzulernen, ist der erste Schritt zur Meisterschaft in Eurer Klasse.",al={"warum crawler zähmen","tierbeherrschung","erstes zähmen"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Im Böenbeerentiefland bittet Quel'ana Quickgale Euch, einen galestrider zu zähmen. Euer Können auf offenem Gelände bereitet Euch auf kommende Prüfungen vor.",h="Im Böenbeerentiefland bittet Quel'ana Quickgale Euch, einen galestrider zu zähmen.",kw={"galestrider","böenbeerentiefland","ornery galestrider","quel'ana quickgale","zähmerrute","taming the beast","valanaar","zephras"},sec={{t="Über die Ebenen",b="Ihr habt bereits gezeigt, dass Ihr den Kriecher des Flusses zähmen könnt. Nun gibt Quel'ana Quickgale Euch eine Zähmerrute und schickt Euch in die Tiefländer von Zephras. Dort läuft ein stolzer, geflügelter galestrider flink über die Ebenen. Gewinnt sein Vertrauen und übt Eure Fähigkeiten. Bringt die Rute dann zu Quel'ana in Valanaar zurück."}},faq={{q="Was soll ich für Quel'ana zähmen?",a="Quel'ana bittet Euch, einen Ornery Galestrider im Böenbeerentiefland zu zähmen.",al={"was zähmen","galestrider zähmen","welches wildtier"}},{q="Wo finde ich den galestrider?",a="Ihr findet den Ornery Galestrider im Böenbeerentiefland, in den Ebenen von Zephras.",al={"wo galestrider","galestrider fundort","wo tiefland"}},{q="Wozu dient die Zähmerrute?",a="Quel'ana gibt Euch die Zähmerrute, damit Ihr einen Ornery Galestrider zähmen könnt.",al={"zähmerrute verwenden","wozu die rute","wie wildtier zähmen"}},{q="Wer hat mir diesen Auftrag gegeben?",a="Quel'ana Quickgale in Valanaar bittet Euch, einen Ornery Galestrider zu zähmen und die Zähmerrute zurückzubringen.",al={"wer hat mich geschickt","wer ist quelana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="Die Krol'dok-Gussform sieht aus, als gehöre sie zu einem Schlüssel. Vielleicht weiß jemand in Burg Farholde mehr darüber.",h="Die Krol'dok-Gussform sieht aus, als gehöre sie zu einem Schlüssel.",kw={"burg farholde","schlüssel","krol'dok-gussform","gussform"},sec={{t="Die Gussform eines Schlüssels",b="Ihr habt eine Gussform, die für einen Schlüssel bestimmt zu sein scheint. Vielleicht weiß jemand in Burg Farholde, wofür sie gedacht ist, und Ihr bringt sie dorthin, um mehr zu erfahren."}},faq={{q="Was ist die Krol'dok-Gussform?",a="Die Krol'dok-Gussform scheint für einen Schlüssel bestimmt zu sein.",al={"kroldok-gussform","krol'dok-gussform","was ist diese gussform"}},{q="Wer könnte etwas über die Gussform wissen?",a="Vielleicht weiß jemand in Burg Farholde etwas über die Gussform.",al={"wer kennt sich mit der gussform aus","gussform-experte","nach der gussform fragen"}},{q="Was passiert, wenn ich die Gussform hinbringe?",a="Die Person, zu der Ihr sie bringt, sagt, sie werde sehen, was sich damit machen lässt.",al={"ergebnis der gussform","was sagen sie","schlüsselgussform"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas braucht Materialien, um aus einer groben Form einen Schlüssel zu fertigen. Ihr sollt ihm Thick Leather und Iron Bars bringen.",h="Alphonse Dumas braucht Materialien, um aus einer groben Form einen Schlüssel zu fertigen.",kw={"alphonse dumas","glut","iron bars","schlüssel","schlüsselzutaten","form","thick leather"},sec={{t="Materialien für den Schlüssel",b="Alphonse Dumas hält die Glut heiß, während Ihr alles Nötige sammelt. Die Form ist grob, doch mit den richtigen Materialien kann er vielleicht einen Schlüssel fertigen."}},faq={{q="Was braucht Alphonse?",a="Alphonse Dumas bittet Euch, vier Thick Leather und zwölf Iron Bars zu bringen.",al={"benötigte materialien","was bringen","schlüsselzutaten"}},{q="Was fertigt Alphonse an?",a="Alphonse hofft, aus einer groben Form mit den richtigen Materialien einen Schlüssel zu fertigen.",al={"was fertigt er an","wofür ist der schlüssel","schlüsselform"}},{q="Wohin bringe ich die Materialien?",a="Bringt Thick Leather und Iron Bars zu Alphonse Dumas.",al={"wer erhält die zutaten","wem die materialien bringen"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94982"] = {n="Eye of Mugg",s="Kommandant Brant bittet Euch, die Twilight-Präsenz in der Feste Krol'dok aufzuspüren und einen Beweis für den Tod ihres Anführers zurückzubringen. Die Höhlen bedrohen die Bemühungen, Twilight aus diesen Landen zu vertreiben.",h="Kommandant Brant bittet Euch, die Twilight-Präsenz in der Feste Krol'dok aufzuspüren und einen Beweis für den...",kw={"höhlen","kommandant brant","eye of mugg","feste krol'dok","vermisste kundschafter","berge","twilight"},sec={{t="Die verborgenen Höhlen",b="Kommandant Brant hat erfahren, dass Kundschafter Höhlen nordwestlich entlang der Berge entdeckt haben, verborgen durch ihre natürliche Umgebung. Viele, die hineingingen, um mehr herauszufinden, sind nicht zurückgekehrt, und Brant fürchtet, dass sie verschollen sind. Beobachter haben außerdem gesehen, wie Gestalten von Twilight bei Dunkelheit die Höhlen betraten und verließen. Ihr sollt die Festung ausfindig machen und mit einem Beweis für den Tod ihres Anführers zurückkehren."}},faq={{q="Wer schickt mich zur Feste Krol'dok?",a="Kommandant Brant bittet Euch, die Festung von Twilight ausfindig zu machen und mit einem Beweis für den Tod ihres Anführers zurückzukehren.",al={"wer ist kommandant brant","brant hat mich geschickt","wer hat diese quest gegeben"}},{q="Wo liegt die Feste Krol'dok?",a="Die Höhlen liegen nordwestlich entlang der Berge und sind von ihrer natürlichen Umgebung verborgen.",al={"wo liegt krol'dok","standort von krol'dok","wo sind die höhlen"}},{q="Warum ist Kommandant Brant wegen der Höhlen besorgt?",a="Viele, die auf der Suche nach Informationen in die Höhlen gingen, sind nicht zurückgekehrt, und Brant fürchtet, dass sie verschollen sein könnten.",al={"warum die höhlen finden","was stimmt dort nicht","vermisste kundschafter"}},{q="Wer wurde nahe den Höhlen gesehen?",a="Beobachter haben von einer Twilight-Präsenz berichtet, die sich in den Höhlen aufhält und sie wieder verlässt, oft bei Dunkelheit.",al={"twilight in den höhlen","wer ist in krol'dok","twilight-präsenz"}},{q="Was bittet Brant mich zurückzubringen?",a="Brant bittet Euch, mit einem Beweis zurückzukehren, dass der Anführer der Festung tot ist.",al={"welchen beweis brauche ich","beweis für den anführer","was soll ich zurückbringen"}}},fp="11,196,16.376.0,36.103.0,29.76.0,49.101.0,33.93.0,37.73.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="Sergeant Riftan schickt Euch nach Norden zur Feste Krol'dok, nachdem Kundschafter ein Versteck des Twilight's Hammer bestätigt haben. Er bittet Euch, Beweise für die Niederlage der Kultisten zurückzubringen.",h="Sergeant Riftan schickt Euch nach Norden zur Feste Krol'dok, nachdem Kundschafter ein Versteck des Twilight's...",kw={"höhle","armreifen der kultisten","versteck der kultisten","feste krol'dok","kundschafter","sergeant riftan","andenken des zwielichts","twilight's hammer"},sec={{t="Berichte der Kundschafter",b="Kundschafter haben Sergeant Riftan düstere Berichte über ein Versteck der Kultisten gebracht. Ihre Berichte bestätigen, was andere erzählt haben. Im Norden liegt eine Höhle, die von ihrer Umgebung verborgen wird, und Riftan glaubt, dass sie dem Kult einen Stützpunkt tief in den Bergen bietet. Er schickt Euch zur Feste Krol'dok, damit Ihr Beweise für die Niederlage der Kultisten des Twilight's Hammer zurückbringt."}},faq={{q="Wer schickt mich nach Norden?",a="Sergeant Riftan bittet Euch, die Kultisten des Twilight's Hammer bei der Feste Krol'dok aufzuspüren und mit Beweisen für ihre Niederlage zurückzukehren.",al={"wer hat mich geschickt","sergeant riftan"}},{q="Was haben die Kundschafter entdeckt?",a="Die Berichte der Kundschafter bestätigten die Meldungen über ein Versteck der Kultisten mit einer verborgenen Höhle im Norden.",al={"bericht der kundschafter","was haben sie entdeckt"}},{q="Wo befindet sich das Versteck?",a="Das Versteck liegt in einer Höhle im Norden, die von ihrer Umgebung verborgen wird. Riftan glaubt, dass sie ein Stützpunkt tief in den Bergen ist.",al={"kultistenhöhle","wo sind die kultisten"}},{q="Welche Beweise will Riftan?",a="Riftan bittet Euch, Beweise dafür zurückzubringen, dass die Kultisten bei der Feste Krol'dok besiegt wurden.",al={"welche beweise","beweise gegen kultisten"}},{q="Wer sind die Kultisten?",a="Sie sind Mitglieder des Twilight's Hammer, dessen Versteck durch die Berichte der Kundschafter bestätigt wurde.",al={"zwielichtkult","twilight's hammer"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94984"] = {n="Tome of Twilight",s="Die Streitkräfte der Dämmerung halten an, und eine Spur weist nördlich von Sonnengrund. Ihr sollt Nar'gurk finden und Informationen aus seiner Festung bergen.",h="Die Streitkräfte der Dämmerung halten an, und eine Spur weist nördlich von Sonnengrund.",kw={"feste krol'dok","nar'gurk","shadow magic","sonnengrund","tome of twilight","dämmerung","streitkräfte der dämmerung"},sec={{t="Eine Spur nach Norden",b="Die Streitkräfte der Dämmerung kommen weiterhin aus unbekannter Quelle, deshalb schickt man Euch zur Feste Krol'dok. Eine Kreatur der Dämmerung erwähnte dort Shadow Magic und einen Oger namens Nar'gurk. Ihr sollt ihn töten und alle wertvollen Informationen bergen, die erklären könnten, woher die Streitkräfte kommen."}},faq={{q="Wonach suche ich?",a="Ihr sucht Nar'gurk in der Feste Krol'dok und alle wertvollen Informationen dort.",al={"nar gurk","informationen zum tome of twilight","festung der dämmerung"}},{q="Wo liegt die Feste Krol'dok?",a="Die Feste Krol'dok liegt nördlich von Sonnengrund.",al={"wo liegt die festung","standort von krol'dok"}},{q="Warum suche ich nach Nar'gurk?",a="Eine Kreatur der Dämmerung erwähnte Nar'gurk und Shadow Magic, als sie gefragt wurde, woher ihre früheren Meister stammten.",al={"warum nar gurk","hinweis auf die dämmerung"}},{q="Welche Informationen könnten dort sein?",a="Die gesuchten Informationen könnten erklären, woher die anhaltenden Streitkräfte der Dämmerung kommen.",al={"welche informationen","informationen zum tome of twilight"}}},fp="16,143,13.279.0,22.87.0,29.43.0,30.109.0,32.93.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Ein verlorenes Pferd namens Biscuit stupst Euch an und ist bereit, Euch zurück nach Wheeler's Grange zu folgen. Ihre Rückkehr bedeutet, dass Wheeler's Grange wieder in Betrieb ist.",h="Ein verlorenes Pferd namens Biscuit stupst Euch an und ist bereit, Euch zurück nach Wheeler's Grange zu...",kw={"biscuit","demar","pferd","verlorenes pferd","rettungsaktion","stallgefährtinnen","wheeler's grange"},sec={{t="Biscuit kehrt zurück",b="Das verlorene Pferd von Wheeler heißt Biscuit und senkt den Kopf, bevor sie Euren Arm anstupst. Ihr bringt sie zurück nach Wheeler's Grange. Wheeler ist dankbar, Biscuit wieder zu Hause zu haben, auch wenn Biscuit eine Weile allein sein wird. Die Grange ist wieder geöffnet."}},faq={{q="Wer ist Biscuit?",a="Biscuit ist Wheelers Pferd. Es ist verschwunden und muss zurück zur Wheeler's Grange gebracht werden.",al={"pferd biscuit","verlorenes pferd","wer ist biscuit"}},{q="Wohin muss Biscuit gebracht werden?",a="Biscuit muss zurück zur Wheeler's Grange gebracht werden.",al={"wohin pferd bringen","biscuit ort","ziel des pferdes"}},{q="Warum ist Wheeler dankbar?",a="Wheeler ist dankbar, weil Ihr Biscuit zurück zur Grange bringt.",al={"warum dank","biscuit gerettet","wheeler dank"}},{q="Ist Biscuit allein?",a="Wheeler sagt, Biscuit werde eine Weile allein sein, und hofft, einige ihrer Stallgefährtinnen zu finden.",al={"biscuit allein","wo stallgefährtinnen","andere pferde"}},{q="Ist Wheeler's Grange geöffnet?",a="Mit Biscuit zurück ist Wheeler's Grange wieder in Betrieb.",al={"grange geöffnet","wheeler betrieb","grange wieder geöffnet"}}},fp="14,133,15.248.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan bittet Euch, eine Tasche mit verfluchten Erinnerungsstücken zu Ashe Amberhall in Burg Farholde zu bringen. Er hofft, dass ihre Studien offenbaren, welche Energien in den Objekten stecken.",h="Riftan bittet Euch, eine Tasche mit verfluchten Erinnerungsstücken zu Ashe Amberhall in Burg Farholde zu...",kw={"ashe amberhall","kultisten","verfluchte erinnerungsstücke","energien","burg farholde","nachwirkende essenz","riftan","satchel of cursed mementos"},sec={{t="In Burg Farholde",b="In Burg Farholde nimmt Ashe Amberhall Euch die Tasche ab und erfährt, dass Riftan sie geschickt hat. Sie sagt, sein langer Kampf gegen die Kultisten lasse sie befürchten, dass Erschöpfung sein Urteilsvermögen trübt. Doch sie räumt ein, dass seine Bedenken begründet sein könnten, und widmet sich den Objekten."}},faq={{q="Wer bittet mich, die Tasche zu bringen?",a="Riftan bittet Euch, Satchel of Cursed Mementos zu Ashe Amberhall zu bringen.",al={"wer hat mich geschickt","riftans tasche","wer ist riftan"}},{q="Wer ist Ashe Amberhall?",a="Ashe Amberhall ist eine angesehene Gelehrte. Ihr Fachgebiet könnte ihr helfen, die Energien in den Objekten zu untersuchen.",al={"ashe wer","wer ist ashe","amberhall"}},{q="Wohin soll ich die Erinnerungsstücke bringen?",a="Bringt Satchel of Cursed Mementos zu Ashe Amberhall in Burg Farholde.",al={"wohin mit der tasche","burg farholde","ziel der tasche"}},{q="Was ist in der Tasche?",a="Die Tasche enthält verfluchte Erinnerungsstücke, und Riftan möchte, dass Ashe untersucht, welche Energien in ihnen stecken.",al={"was ist in der tasche","verfluchte erinnerungsstücke","tascheninhalt"}},{q="Warum möchte Riftan, dass Ashe sie untersucht?",a="Riftan hofft, dass Ashe durch ihre Studien herausfinden kann, welche Energien in den Objekten stecken.",al={"warum ashe","wozu ist die tasche","nachwirkende essenz"}},{q="Was hält Ashe von Riftans Bedenken?",a="Ashe befürchtet, dass die Erschöpfung durch Riftans langen Kampf gegen Kultisten seinen Verstand trüben könnte, sagt aber, dass seine Bedenken begründet sein könnten.",al={"vertraut ashe riftan","riftan erschöpft","ashes meinung"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="Ihr bringt Melanie Sable eine Tasche mit ungewöhnlichen Andenken. Ihre feine Verarbeitung könnte sie nützlich machen.",h="Ihr bringt Melanie Sable eine Tasche mit ungewöhnlichen Andenken.",kw={"verarbeitung","kuriositäten der neugier","melanie sable","andenken","überreste","tasche mit andenken"},sec={{t="Eine Tasche für Melanie",b="Jemand, der die Andenken untersucht hat, schickt Euch mit der Tasche zu Melanie Sable. Die Gegenstände seien sicher, doch ihre Herkunft sei unbekannt. Ihre Verarbeitung ist ungewöhnlich, und Melanie könnte eine Verwendung für sie finden."}},faq={{q="Wem soll ich die Andenken bringen?",a="Bringt Melanie Sable die Tasche mit den Andenken, wie die untersuchende Person Euch aufträgt.",al={"wohin mit der tasche","wer ist melanie sable"}},{q="Was sind das für Andenken?",a="Sie sind Überreste von etwas, doch die untersuchende Person weiß nicht genau, wovon.",al={"was ist in der tasche","was sind das für kuriositäten"}},{q="Warum sind die Andenken ungewöhnlich?",a="Ihre Verarbeitung wird als einzigartig und kunstvoll beschrieben.",al={"was ist daran besonders","verarbeitung der kuriositäten"}},{q="Sind die Andenken sicher?",a="Die untersuchende Person bittet Euch, Melanie zu sagen, dass die Andenken sicher sind.",al={"ist die tasche sicher","sind sie gefährlich"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:95"] = {n="Svens Rache",s="In Svens Rache treibt Trauer Sven Yorgen von seinem zerstörten Hof im südlichen Dämmerwald fort, um die Mörder zu jagen. Nun lagert er in den westlichen Hügeln und bittet Reisende, zum Gehöft zurückzukehren, wo ein Fremder etwas nahe der Scheune vergraben hat.",h="In Svens Rache treibt Trauer Sven Yorgen von seinem zerstörten Hof im südlichen Dämmerwald fort, um die...",kw={"dunkle reiter","gebirgspass der totenwinde","dämmerwald","haufen lockerer erde","baumstumpf","sven yorgen","svens rache","yorgens bauernhof"},ang={["class:Paladin"]="Als Paladin seht Ihr das Abschlachten Unschuldiger durch Mächte aus dem Gebirgspass der Totenwinde als einen Ruf nach Gerechtigkeit für die Toten.",["faction:Alliance"]="Das Abschlachten der Familie Yorgen zeigt, wie weit dunkle Mächte im abgeschiedenen Dämmerwald reichen, wo Patrouillen der Armee von Sturmwind selten sind."},sec={{t="Tragödie auf dem Gehöft",b="Verhüllte Dunkle Reiter kamen aus dem Gebirgspass der Totenwinde und griffen Sven Yorgens Hof im südöstlichen Dämmerwald an. Sven war fort, und sie töteten seine Familie. Als er zum Ort des Gemetzels zurückkehrte, sah er eine unbekannte Gestalt nahe der Scheune herumschleichen und hastig etwas vergraben. Sven ließ den Gegenstand verborgen und brach auf, um die Mörder zu jagen."},{t="Verborgene Geheimnisse",b="Sven Yorgen lagert in den westlichen Hügeln, von Zorn verzehrt, und sucht Hilfe für die Rückkehr zu seinem Gehöft. Zwischen dem Bauernhaus und der zerstörten Scheune kennzeichnet ein Haufen lockerer Erde hinter einem alten Baumstumpf die Stelle, an der hastig etwas vergraben wurde. Es zu bergen könnte erklären, warum die schattenhaften Reiter einen friedlichen Bauern aus dem Dämmerwald ins Visier nahmen."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen war ein Bauer im südöstlichen Dämmerwald nahe der Grenze zum Gebirgspass der Totenwinde. Nachdem verhüllte Reiter seine Familie ermordet hatten, verließ er seinen Hof und wurde zu einem Einsiedler, der auf Rache sinnt.",al={"wer ist sven","svens geschichte","svens vorgeschichte"}},{q="Was geschah mit Svens Hof?",a="Dunkle Reiter aus dem Gebirgspass der Totenwinde griffen Sven Yorgens Gehöft an und töteten seine Familie. Das Anwesen lag in Trümmern, während Sven fort war.",al={"tragödie auf yorgens bauernhof","was geschah mit svens hof","warum ist svens hof zerstört"}},{q="Wer hat etwas hinter der Scheune vergraben?",a="Nach dem Massaker sah Sven eine schattenhafte Gestalt etwas nahe seiner Scheune vergraben. Er verfolgte die Dunklen Reiter, bevor er den Fremden stellen oder das Vergrabene freilegen konnte.",al={"wer hat den gegenstand vergraben","schattenhafte gestalt auf svens hof","wer hat den erdhaufen aufgeschüttet"}},{q="Wo liegt der Haufen lockerer Erde?",a="Auf Yorgens Bauernhof im südöstlichen Dämmerwald liegt ein Haufen lockerer Erde hinter einem alten Baumstumpf zwischen der Scheune und dem zerstörten Bauernhaus.",al={"wo ist der erdhaufen","standort des erdhaufens","wo ist der baumstumpf"}},{q="Wer sind die Dunklen Reiter?",a="Die Dunklen Reiter sind verhüllte Reiter, die aus dem Gebirgspass der Totenwinde kommen. Ihre Herkunft ist unbekannt, doch ihre Angriffe im Dämmerwald bringen Tod und Verwüstung.",al={"was sind die dunklen reiter","geschichte der dunklen reiter","reiter aus dem gebirgspass der totenwinde"}},{q="Warum hat Sven den vergrabenen Gegenstand nicht selbst ausgegraben?",a="Sven war von Trauer überwältigt, als er heimkehrte und eine Gestalt sah, die etwas vergrub. Er verfolgte sofort die sich zurückziehenden Dunklen Reiter und ließ den Gegenstand zurück.",al={"warum hat sven die erde nicht untersucht","warum ging sven fort"}}},fx={e064b97c={q="Warum möchte Sven Yorgen, dass der vergrabene Gegenstand geborgen wird?",a="Sven sucht Rache für das brutale Massaker an seiner Familie durch die mysteriösen Dunklen Reiter vom Gebirgspass der Totenwinde. Als er das Massaker entdeckte, sah er eine schattenhafte Gestalt, die hastig etwas bei seiner Scheune vergrub, bevor sie floh. Getrieben von Wut und dem Bedürfnis nach Antworten, glaubt Sven, dass das, was unter der Erde liegt, der Schlüssel dazu ist, aufzudecken, warum sein Hof ins Visier genommen wurde und wer bei der Zerstörung seiner Familie geholfen hat.",al={"warum will sven das","sven yorgen beweggrund","grund für sven rachequest"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Rückkehr zu Onu",s="Ihr bringt Onu in Dunkelküste eine herausgerissene Seite aus dem Twilight Tome. Mehr von den Schriften der Kultisten konntet Ihr ihrem Buch nicht entreißen, ohne den Verstand zu verlieren.",h="Ihr bringt Onu in Dunkelküste eine herausgerissene Seite aus dem Twilight Tome.",kw={"dunkelküste","der hain der uralten","irrsinniges gekritzel","old ones","onu","twilight tome","twilight's hammer"},ang={["class:Druid"]="Als Druide erkennt Ihr in der chaotischen, unnatürlichen Resonanz des Gekritzels einen Frevel an der natürlichen Ordnung, die Ihr gemeinsam mit Treants wie Onu schützt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Aktivitäten des Kults entlang der Küste von Dunkelküste zu untersuchen und Nachtelfensiedlungen wie Auberdine vor verborgenen Bedrohungen zu schützen.",["race:NightElf"]="Als Nachtelf seht Ihr in der Entweihung der Küsten von Dunkelküste durch die Kultisten eine Bedrohung für das Gleichgewicht, das die Ancients of Lore bewahren. Onus Warnungen treffen die Kaldorei tief."},sec={{t="Ein Blick in den Wahnsinn",b="Der Twilight Tome überwältigt jeden, der ihn zu lesen versucht. Seine Worte verschwimmen auf der Seite, und seine kunstvollen Verzierungen winden sich zu grotesken Gestalten. Ihr reißt eine Seite voller Gekritzel heraus, bevor die Anstrengung Schwindel auslöst."},{t="Uralter Argwohn",b="Onu, der Ancient of Lore, erkennt eine seltsame Aura in der Seite, die Ihr ihm bringt. Ihre chaotische, urzeitliche Magie deutet auf uralte, schattenhafte Kräfte hin, die unter der Erde begraben liegen. Obwohl die Schrift schwer zu entziffern ist, zeigt sie, dass der Twilight's Hammer in Dunkelküste mehr als Banditentum betreibt."}},faq={{q="Was ist die Seite aus dem Twilight Tome?",a="Irrsinniges Gekritzel ist eine herausgerissene Seite aus dem Twilight Tome, dem heiligen Buch des Kults. Ihre sich wandelnde Schrift verursacht schwere geistige Qualen.",al={"irrsinniges gekritzel","was ist das gekritzel","seite aus dem twilight tome"}},{q="Wer ist Onu?",a="Onu ist ein Ancient of Lore im Hain der Uralten im Süden von Dunkelküste. Er ist ein betagter Wächter und Gelehrter, der Nachtelfen und Verbündete der Allianz im Kampf gegen die Verderbnis im Wald anleitet.",al={"wer ist onu","onu dunkelküste","treant onu"}},{q="Was erfährt Onu aus dem Gekritzel?",a="Onu spürt chaotische, urzeitliche Energie in der Seite und den Einfluss uralter, bösartiger Wesenheiten. Die Schriften deuten darauf hin, dass die Kultisten des Twilight's Hammer in ganz Dunkelküste nach Reliktstätten und verschütteten Mächten suchen.",al={"was hat onu entdeckt","bedeutung des gekritzels"}},{q="Warum ist der Twilight's Hammer in Dunkelküste?",a="Der Twilight's Hammer kam nach Dunkelküste, um verfallene Elfenstätten auszugraben und Spuren uralter Macht aufzudecken, die mit urzeitlicher Finsternis und den Old Gods verbunden ist. Das Chaos im Land hilft, ihre Riten zu verbergen.",al={"kultisten in dunkelküste","warum ist twilight's hammer hier"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Onu richtet seine Aufmerksamkeit auf die uralten elfischen Ruinen von Mathystra im Norden. Er weist Abenteurer an, die Relikte zu sichern, bevor die Kultisten sie an sich reißen können.",al={"welche quest kommt als nächstes","was kommt nach rückkehr zu onu"}},{q="Warum verursacht das Lesen des Folianten Schwindel?",a="Dunkle, wahnsinnig machende Magie erfüllt den Twilight Tome. Seine Glyphen verwirren den Geist der Sterblichen und verursachen Halluzinationen und Ohnmachtsanfälle, die Außenstehende daran hindern, seine Geheimnisse zu verstehen.",al={"warum schwindel beim folianten","wirkungen des twilight tome"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani schickt Euch nach Camp Mojache in Feralas, damit Ihr Hexendoktor Uzer'i um Hilfe bittet. Uzer'i ist als Magiekundiger bekannt, aber auch ein Jäger.",h="Tan'jani schickt Euch nach Camp Mojache in Feralas, damit Ihr Hexendoktor Uzer'i um Hilfe bittet.",kw={"camp mojache","feralas","jäger","magie","auf der anderen seite","tan'jani","hexendoktor uzer'i"},sec={{t="Tan'janis Freund",b="Auf der anderen Seite von Feralas liegt Camp Mojache. Dort findet Ihr Hexendoktor Uzer'i, einen alten Freund von Tan'jani. Tan'jani sagt, Uzer'i wirke mit Magie, sei aber auch ein Jäger. Ihr sollt mit ihm sprechen und lasst die weiten Ebenen hinter Euch."}},faq={{q="Wer hat mich zu Uzer'i geschickt?",a="Tan'jani schickt Euch zu Hexendoktor Uzer'i, einem alten Freund.",al={"tan'jani hat mich geschickt","wer ist der alte tanjani"}},{q="Wo finde ich Uzer'i?",a="Hexendoktor Uzer'i ist in Camp Mojache in Feralas.",al={"uzer'is ort","wo ist der hexendoktor"}},{q="Warum soll ich zu Uzer'i gehen?",a="Tan'jani sagt, Uzer'i suche Hilfe, und bittet Euch, mit ihm zu sprechen.",al={"warum mit uzer'i sprechen","was möchte tanjani"}},{q="Was macht Uzer'i?",a="Hexendoktor Uzer'i wirkt mit Magie und ist auch ein Jäger.",al={"beruf von hexendoktor uzer'i","hexendoktor und jäger"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger im Grabmal berichtet von dem Angriff, bei dem Banon schwer verwundet wurde. Ihrem Bericht zufolge war es ein Worgen, der sie auf der Straße angriff.",h="Lumina Windsinger im Grabmal berichtet von dem Angriff, bei dem Banon schwer verwundet wurde.",kw={"banon","gnolle","lumina windsinger","angriff auf der straße","das grabmal","the debt","worgen"},sec={{t="Eine Wunde auf der Straße",b="Lumina Windsinger im Grabmal erzählt Euch, was auf der Straße geschah. Ein riesiger, wolfsähnlicher Worgen griff ihre Gruppe an und tötete ihre Wachen. Banon stellte sich zwischen die Kreatur und Lumina, die sie mit einem Zauber vertrieb. Da hatte Banon bereits schwere Bisswunden erlitten. Er drängte sie, ihn zurückzulassen, doch sie blieb, und die beiden humpelten weiter, bevor Gnolle sie fanden."},{t="Banons letzte Augenblicke",b="Banon im Grabmal wurde von vielen Gnollklingen durchbohrt, bevor er sich gegen Lumina wandte. Sie sah, dass er sie noch erkannte, obwohl er sich nicht beherrschen konnte. Lumina glaubt, dass der Worgen sein Schicksal besiegelt hat, und schwört, ihn zu töten, damit er keinem anderen Lebewesen denselben Schrecken zufügen kann."}},faq={{q="Wer griff Lumina und Banon auf der Straße an?",a="Ein riesiger, wolfsähnlicher Worgen griff Lumina und Banon auf der Straße an.",al={"was griff sie an","worgenangriff","angreifer auf der straße"}},{q="Was geschah mit den Wachen?",a="Der Worgen tötete die Wachen, die Lumina und Banon begleiteten.",al={"schicksal der wachen","was geschah mit den wachen","wachen auf der straße"}},{q="Wie vertrieb Lumina den Worgen?",a="Lumina gelang es, einen Zauber zu wirken, der den Worgen erschreckte und in die Flucht schlug.",al={"wie floh der worgen","luminas zauber","was erschreckte ihn"}},{q="Warum wurde Banon gebissen?",a="Banon warf sich dem Worgen in den Weg, um Lumina zu schützen, und die Kreatur fügte ihm schwere Bisswunden zu.",al={"banons bisswunde","wie wurde banon verletzt","was geschah mit banon"}},{q="Wo erzählt Euch Lumina, was geschehen ist?",a="Lumina Windsinger erzählt Euch ihre Geschichte im Grabmal.",al={"wo ist lumina zu finden","luminas aufenthaltsort","das grabmal"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan warnt Euch, dass Worgen den Silberwald bedrohen. Old Fire-Eye widersetzt sich dem Tod durch unbekannte Magie, und Trevan bittet Euch herauszufinden, was für eine besondere Klinge benötigt wird.",h="Trevan warnt Euch, dass Worgen den Silberwald bedrohen.",kw={"a moon-kissed blade","materialien für die klinge","old fire-eye","silberwald","besondere waffe","trevan","worgen"},sec={{t="Die Liste eines Schmieds",b="Old Fire-Eye ist der Worgen, der Trevan und seine Gefährten angegriffen hat. Trevan wird Euch eine Liste mit Materialien für eine Waffe gegen ihn geben. Die Materialien sind gesammelt, und Trevan glaubt, einen Schmied zu kennen, der die Klinge anfertigen kann."}},faq={{q="Wer ist Old Fire-Eye?",a="Old Fire-Eye ist der größte und bösartigste der Worgen. Er hat Trevan und seine Gefährten angegriffen.",al={"old fire-eye","fire eye worgen","großer worgen"}},{q="Warum kehrt Old Fire-Eye immer wieder zurück?",a="Unbekannte Magie verhindert, dass Old Fire-Eye tot bleibt.",al={"warum stirbt fire-eye nicht","old fire eye magie","worgen der nicht tot bleibt"}},{q="Was braucht Trevan von mir?",a="Trevan wird Euch eine Liste mit Materialien geben, die zum Schmieden einer besonderen Waffe benötigt werden.",al={"was will trevan","trevans liste","materialien für die klinge"}},{q="Warum wird eine besondere Klinge benötigt?",a="Old Fire-Eye widersetzt sich dem Tod durch unbekannte Magie. Trevan sagt, dass eine besondere Waffe benötigt wird, um ihn zur Strecke zu bringen.",al={"moon kissed blade warum","waffe gegen old fire-eye","fire eye töten"}},{q="Wer kann die Klinge anfertigen?",a="Trevan glaubt, einen Schmied zu kennen, der die Klinge anfertigen kann.",al={"schmied für die klinge","wer fertigt moon blade","klingenschmied"}}},fp="19,170,14.223.0,20.93.0,39.51.0,30.74.0,30.105.0,24.55.0"}
P.entries["quest:95041"] = {n="Datenhamsterer",s="Vor Gnomeregan sucht Jemma Quikswitch im Schnee nach verlorenen Lochkarten. Die im Exil lebende Gnomin wohnt in Eisenschmiede, und die Karten enthalten die Archive ihrer Familie, von U-Boot-Entwürfen bis hin zu Familienrezepten. Ohne sie bleiben die Aufzeichnungen, die sie noch hat, unlesbar.",h="Vor Gnomeregan sucht Jemma Quikswitch im Schnee nach verlorenen Lochkarten.",kw={"data hoarders","dun morogh","gnomeregan","eisenschmiede","jemma quikswitch","lochkarten","zweiter krieg","u-boot-rumpf"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr vertriebenen Gnomen helfen, technische Aufzeichnungen aus Kriegszeiten und das darin enthaltene Wissen der Allianz zu bewahren.",["profession:Cooking"]="Als Koch wisst Ihr Oma Quikswitchs Chilirezept zwischen den technischen Aufzeichnungen zu schätzen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr den Wert der U-Boot-Baupläne aus dem Zweiten Krieg und der arkanotechnischen Gleichungen auf diesen Karten.",["race:Gnome"]="Als Gnom könnt Ihr durch die Bergung der Lochkarten helfen, Erfindungen und Familienerinnerungen aus Eurer Heimat zu bewahren."},sec={{t="Hastige Suche im Schnee",b="Als Troggs in Gnomeregan einfielen und die Strahlenkatastrophe eintrat, flohen Tausende Gnome mit allem, was sie tragen konnten. Aus einer beschädigten Tasche fielen mehrere von Jemmas Karten in den Schnee rund um die gefallene Stadt. Ohne sie sind ihre verbliebenen Aufzeichnungen unverständliches Kauderwelsch, und das Wissen ihrer Familie droht verloren zu gehen."},{t="Gleichungen und Chili",b="Die Archive der Familie Quikswitch enthalten arkanotechnische Feldgleichungen und Baupläne für U-Boot-Rümpfe aus dem Zweiten Krieg. Sie bewahren auch Oma Quikswitchs geheimes Chilirezept. Für Flüchtlinge in Eisenschmiede zählen die Annehmlichkeiten der Heimat ebenso viel wie technische Wunderwerke."}},faq={{q="Wer ist Jemma Quikswitch?",a="Jemma Quikswitch ist eine gnomische Geflüchtete, die dem Fall Gnomeregans entkam und nun in Eisenschmiede lebt.",al={"jemma quikswitch","wer vergibt data hoarders","questgeber data hoarders"}},{q="Welche Daten sind auf den verlorenen Karten gespeichert?",a="Die Lochkarten enthalten die Archive der Familie Quikswitch, darunter arkanotechnische Gleichungen, Baupläne für U-Boot-Rümpfe aus dem Zweiten Krieg und Oma Quikswitchs Chilirezept.",al={"was sind die lochkarten","was war auf den karten","quikswitch-archive"}},{q="Wo gingen die Datenkarten verloren?",a="Die Karten rutschten aus Jemmas Gepäck, als sie aus Gnomeregan floh. Sie liegen in Dun Morogh im Schnee direkt vor den Toren der Stadt.",al={"wo sind die karten","fundort der datenkarten","wo hat sie die karten verloren"}},{q="Warum kann Jemma die verbliebenen Karten ohne die fehlenden nicht lesen?",a="Jemma sagt, die Daten seien zu durcheinander, um sie ohne die fehlenden Lochkarten wiederherzustellen. Die Aufzeichnungen erklären nicht, wie die Karten diese Informationen kodieren oder ordnen.",al={"warum werden alle karten benötigt","durcheinandergeratene daten","lochkartendaten"}},{q="Welche Rolle spielten Gnome im Zweiten Krieg beim Einsatz von U-Booten?",a="Im Zweiten Krieg unterstützten Gnome die Allianz mit fortschrittlicher Ingenieurskunst. Sie entwarfen und steuerten Tauchboote, um den Seestreitkräften der Horde entgegenzutreten.",al={"gnomische u-boote zweiter krieg","entwürfe für u-boot-rümpfe"}},{q="Warum leben gnomische Flüchtlinge in Eisenschmiede?",a="Nachdem einfallende Troggs Gnomeregan zu Fall gebracht hatten und die Strahlenkatastrophe eingetreten war, flohen die überlebenden Gnome aus ihrer unterirdischen Heimat. König Magni Bronzebart bot ihnen Zuflucht in Eisenschmiede.",al={"warum sind gnome in eisenschmiede","gnome leben bei zwergen"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="Im Eschental sieht Ulric Frostveil Eure Suche nach einem Kor Gem als vertraute Arbeit für Zauberwirker der Allianz. Er weist Euch nach Norden zur Tiefschwarzen Grotte, wo die Naga die Edelsteine noch immer verwenden.",h="Im Eschental sieht Ulric Frostveil Eure Suche nach einem Kor Gem als vertraute Arbeit für Zauberwirker der...",kw={"eschental","tiefschwarze grotte","verlassene","kor gem","naga","ulric frostveil"},sec={{t="Ein Edelstein im Eschental",b="Ulric bittet Euch, ihm einen Kor Gem aus den Ruinen der Tiefschwarzen Grotte nördlich des Eschentals zu bringen. Die Naga dort unten verwenden die Edelsteine noch immer. Sie können magische Waffen und Werkzeuge verstärken, doch Ulric warnt Euch davor, allein aufzubrechen."},{t="Ulrics Interesse",b="Ulric Frostveil erkennt Verderbnis im Edelstein. Er sagt, er könne das Böse bannen, mit dem die Hexen der Naga ihn durchdrungen haben. Dann fragt er, ob Ihr ihm den Edelstein für seine akademischen Forschungen verkaufen würdet."}},faq={{q="Wer ist Ulric Frostveil?",a="Ulric Frostveil ist ein Verlassener im Eschental, der Euch bittet, ihm einen Kor Gem zu bringen.",al={"ulric frostveil","wer ist ulric","verlassener im eschental"}},{q="Wo finde ich einen Kor Gem?",a="Ulric weist Euch nach Norden zur Tiefschwarzen Grotte, wo die Naga noch immer Kor Gems verwenden.",al={"kor gem fundort","wo edelstein","tiefschwarze grotte edelstein"}},{q="Wofür werden Kor Gems verwendet?",a="Kor Gems können magische Waffen und Werkzeuge verstärken.",al={"kor gem verwendung","edelstein magie","was bewirkt kor gem"}},{q="Warum möchte Ulric einen Kor Gem?",a="Ulric bittet Euch, ihm einen Kor Gem zu bringen. Er sagt, er könnte für seine akademischen Forschungen von Wert sein.",al={"ulric will edelstein","warum edelstein","frostveil edelstein"}},{q="Wer verwendet noch Kor Gems?",a="Die Naga in der Tiefschwarzen Grotte verwenden noch immer Kor Gems.",al={"naga edelsteine","wer verwendet kor gems","tiefschwarze grotte naga"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="Ein Goblin hat eine Lieferung für Ritterkommandant Demar Brant auf Burg Farholde. Ihr sollt ihm Frazzlespark's Crate bringen.",h="Ein Goblin hat eine Lieferung für Ritterkommandant Demar Brant auf Burg Farholde.",kw={"kiste","demar brant","burg farholde","frazzlespark","frazzlesparks kiste","goblin-lieferung","ritterkommandant"},sec={{t="Eine Lieferung zur Burg",b="Frazzlespark schickt Euch nach Südwesten zur Burg Farholde, wo Ritterkommandant Demar Brant wartet. Die Kiste ist für ihn bestimmt, und der Goblin legt Wert darauf, seinen vollständigen Namen zu verwenden. Auf der Burg nennt Demar den Goblin ein Mittel zum Zweck, Teil der Geschäfte, die, wie er sagt, sein eigenes Volk sicher und erfolgreich halten."}},faq={{q="Wer wartet auf die Kiste?",a="Ritterkommandant Demar Brant wartet auf Frazzlespark's Crate auf Burg Farholde.",al={"wer will die kiste","lieferung an demar brant"}},{q="Wohin soll ich Frazzlespark's Crate bringen?",a="Bringt Frazzlespark's Crate zu Ritterkommandant Demar Brant auf Burg Farholde, südwestlich von Frazzlespark.",al={"standort der kiste","wo liegt burg farholde"}},{q="Warum will Demar, dass sein vollständiger Name verwendet wird?",a="Frazzlespark merkt an, dass Demar den Goblin stets seinen vollständigen Namen verwenden lässt, nennt aber keinen Grund dafür.",al={"demars vollständiger name","warum ritterkommandant"}},{q="Warum nennt Frazzlespark es eine besondere Lieferung?",a="Frazzlespark nennt es eine besondere Lieferung und sagt, dass Demar Brant auf Burg Farholde darauf wartet.",al={"kistenlieferung","was ist besonders an der kiste"}},{q="Warum ist diese Lieferung wichtig?",a="Demar Brant sagt, gewisse Geschäfte müssten getätigt werden, um die Sicherheit und den Erfolg seines Volkes zu gewährleisten, und nennt den Goblin nichts weiter als ein Mittel zum Zweck.",al={"warum die kiste liefern","sicherheit der goblins"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95062"] = {n="Frazzlespark's Crate",s="Eine Lieferung von Frazzlespark ist für Old Krom'rosh in Rog'mar bestimmt. Bringt die Kiste schnell und vorsichtig dorthin.",h="Eine Lieferung von Frazzlespark ist für Old Krom'rosh in Rog'mar bestimmt.",kw={"kiste","lieferung","frazzlespark","frazzlesparks kiste","krom'rosh","old krom'rosh","paket","rog'mar"},sec={{t="Eine vorsichtige Lieferung",b="Frazzlespark hat ein Paket für Old Krom'rosh, der in Rog'mar wartet, gleich westlich von hier. Ihr sollt es schnell und vorsichtig hinbringen, doch der Grund bleibt unausgesprochen. Krom'roshs Geschäfte helfen, die Ziele der Gruppe zu erreichen."}},faq={{q="Wer wartet auf Frazzlesparks Kiste?",a="Old Krom'rosh wartet in Rog'mar auf Frazzlesparks Kiste.",al={"wer bekommt die kiste","kiste für krom'rosh","kromrosh paket"}},{q="Wo liegt Rog'mar?",a="Rog'mar liegt gleich westlich von Frazzlespark.",al={"wo liegt rog'mar","rog'mar ort","ort rog'mar"}},{q="Was soll ich mit der Kiste tun?",a="Bringt Frazzlesparks Kiste schnell und vorsichtig zu Old Krom'rosh nach Rog'mar.",al={"kiste liefern","frazzlesparks lieferung","was tun"}},{q="Warum muss die Kiste vorsichtig geliefert werden?",a="Frazzlespark rät Euch, sie schnell und vorsichtig zu liefern, nennt aber keinen Grund.",al={"warum vorsichtig","warum die kiste eilig liefern","grund für die kiste"}},{q="Warum geht Krom'rosh solche Geschäfte ein?",a="Krom'rosh sagt, solche Geschäfte helfen dabei, ihre Ziele zu erreichen.",al={"krom'roshs geschäfte","warum geschäfte","wozu sind die geschäfte"}}},fp="20,112,18.231.0,40.61.0,17.37.0,32.78.0,41.81.0,48.57.0"}
P.entries["quest:95064"] = {n="Preventative Measures",s="Watcher Cornelius bei Terral's Watch befürchtet, dass die Orks weiter in die Ebenen vordringen. Er bittet Euch, ihre wachsende Präsenz einzudämmen.",h="Watcher Cornelius bei Terral's Watch befürchtet, dass die Orks weiter in die Ebenen vordringen.",kw={"orks","ebenen","vorbeugende maßnahmen","rog'mar-ausbilder","terral's watch","watcher cornelius"},sec={{t="Orks in den Ebenen",b="Bei Terral's Watch sieht Watcher Cornelius, wie die Orks Land am Fluss für sich beanspruchen und sich in den Ebenen ausbreiten. Er bittet Euch, Rog'mar-Ausbilder zu töten, um ihren Vormarsch aufzuhalten."}},faq={{q="Wer bittet um Hilfe?",a="Watcher Cornelius bei Terral's Watch bittet Euch, die wachsende Präsenz der Orks aufzuhalten.",al={"wer braucht hilfe","cornelius' bitte"}},{q="Warum ist Cornelius wegen der Orks besorgt?",a="Die Orks haben Land am Fluss für sich beansprucht, und ihre Präsenz in den Ebenen wächst.",al={"warum gegen orks kämpfen","orks in den ebenen"}},{q="Welche Orks möchte Cornelius getötet wissen?",a="Cornelius bittet Euch, Rog'mar-Ausbilder zu töten.",al={"rog'mar-ausbilder","welche orks"}},{q="Wo bittet Cornelius um Hilfe?",a="Cornelius bittet bei Terral's Watch um Hilfe.",al={"terral's watch","wo ist cornelius"}}},fp="21,132,18.176.0,18.80.0,42.85.0,38.44.0,34.42.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Im Hafen von Sturmwind bleibt Gilbert Gray an seiner Angel, solange die Fische anbeißen. Seine Vorräte werden knapp, also bittet er Vorbeigehende, Nachtkriecher und ein glänzendes Schmuckstück aus einem Laden an den Canals der Stadt zu holen.",h="Im Hafen von Sturmwind bleibt Gilbert Gray an seiner Angel, solange die Fische anbeißen.",kw={"canals","catherine leland","fishin time","gilbert gray","nachtkriecher","glänzendes schmuckstück","hafen von sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Als Bürger der Allianz stärkt Ihr das Leben und die Zuversicht in ganz Sturmwind, indem Ihr Gilbert Gray bei einem alltäglichen Anliegen helft.",["race:Human"]="Als Mensch, der in Sturmwind zu Hause ist, findet Ihr eine Pause von der Politik des Königreichs, indem Ihr einem älteren Mann einen ruhigen Angelnachmittag ermöglicht."},sec={{t="Ein Tag am Wasser",b="Gilbert Gray beobachtet, wie seine Pose auf dem Wasser tanzt. Der ältere Angler will seinen geliebten Angelplatz nicht verlassen, solange die Fische anbeißen. Seine Vorräte sind aufgebraucht, und er braucht Hilfe, damit er an seiner Angel bleiben kann, statt in die Stadt zurückzukehren."},{t="Vorräte an den Canals",b="Catherine Leland betreibt einen Laden für Angelbedarf an Sturmwinds steinernen Canals, direkt westlich des Handelsdistrikts. Fischer aus der ganzen Stadt kommen zu ihr, um Lockmittel und Köder zu kaufen. Ihr Laden kann die Vorräte auffüllen, die Gilbert Gray zum Weiterangeln braucht."}},faq={{q="Wer ist Gilbert Gray?",a="Gilbert Gray ist ein älterer Fischer im Hafen von Sturmwind. Er verbringt seine Tage damit, seine Angel ins Meer auszuwerfen, und bittet Vorbeigehende, Köder und Lockmittel zu holen, wenn seine Vorräte knapp werden.",al={"gilbert gray","alter gray","wer vergibt diese quest"}},{q="Wer ist Catherine Leland?",a="Catherine Leland betreibt einen Laden für Angelbedarf an den Canals der Stadt, direkt westlich des Handelsdistrikts. Sie verkauft Angelausrüstung und Köder an Sturmwinds Angler.",al={"catherine leland","angelhändler sturmwind","leland sturmwind"}},{q="Wo angelt Gilbert Gray?",a="Gilbert Gray angelt im Hafen von Sturmwind, wo er den freien Blick aufs Meer genießt.",al={"gilbert gray standort","wo ist gilbert gray","fischer im hafen"}},{q="Welche Vorräte braucht Gilbert Gray?",a="Gilbert Gray braucht Nachtkriecher als Köder und ein glänzendes Schmuckstück als Lockmittel. Catherine Leland verkauft beides an den Canals.",al={"questgegenstände fishin time","welchen köder will gray"}},{q="Warum holt Gilbert Gray die Vorräte nicht selbst?",a="Die Fische beißen an, und Gilbert Gray will seinen Platz nicht verlassen oder einen guten Fang verpassen, um in der Stadt Vorräte zu holen.",al={"warum kann gray keine köder kaufen","warum braucht gray hilfe"}},{q="Wo an den Canals liegt Catherine Lelands Laden?",a="Catherine Lelands Laden liegt an den Canals direkt westlich des Handelsdistrikts, neben den steinernen Gehwegen über den Wasserwegen der Stadt.",al={"catherine leland standort","wo ist lelands laden","handelsdistrikt canals"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Relikte von Mathystra",s="An der Nordostküste der Dunkelküste könnten Relikte von Mathystra zeigen, wie der Schattenhammer uralte Elfenmagie beugt. Onu, ein Urahne der Lehren im Hain der Uralten, sucht sie, um die Absichten des Kults zu ergründen.",h="An der Nordostküste der Dunkelküste könnten Relikte von Mathystra zeigen, wie der Schattenhammer uralte...",kw={"dunkelküste","der hain der uralten","die meistergleve","mathystra","onu","relikte","die ruinen von mathystra","schattenhammer"},ang={["class:Druid"]="Als Druide steht Ihr Onu bei, einem der größten uralten Wächter der Natur. Ihr helft, die uralte Geschichte der Dunkelküste vor finsteren Kultisten zu bewahren.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, das nördliche Kalimdor vor dunklen Mächten unter der Erde zu schützen, indem Ihr den Schattenhammer daran hindert, uralte Magie als Waffe einzusetzen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Relikte aus der glorreichen Zeit Eures Volkes vor der Zerschlagung aus der Erde geborgen werden. Sein Untergang ist eine düstere Mahnung, und der Einsatz der mächtigen Künste Eurer Ahnen durch den Schattenhammer ist ein alarmierendes Warnzeichen."},sec={{t="Eine beunruhigende Entdeckung",b="Nachdem Ihr ein verderbtes Pergament von Kultisten des Schattenhammers nahe der Meistergleve geborgen hattet, entschlüsselte Onu seine Bedeutung. Die Schrift stammte nicht vom Kult selbst. Es war ein verfluchtes Fragment uralter Nachtelfenschrift, besudelt vom Schattenhammer. Die Fanatiker nutzen vergessene Elfenmagie, um ihre uralten Meister zu erwecken oder in die sterbliche Welt zu beschwören."},{t="Die gefallene Bastion",b="Onu schickt Euch zu den Ruinen von Mathystra am nordöstlichen Ufer der Dunkelküste. Vor der Zerschlagung war Mathystra eine strahlende Bastion der Zivilisation der Hochgeborenen. Die Stadt verfiel zu Trümmern, Unkraut und Naga, doch ihre alten Verzauberungen überdauern in zerbrochenen Urnen und Relikten, die zwischen den Steinfundamenten verstreut liegen."},{t="Finsteren Plänen auf der Spur",b="Ihr sammelt erhaltene Relikte aus den grasbewachsenen Trümmern, damit die Verteidiger der Dunkelküste erfahren, welche Künste der Kult nutzen will. Onu untersucht die Magie, die in jedem Stück verblieben ist. Er muss die Pläne des Kults aufdecken, bevor der Schattenhammer uralte Zauberei der Kaldorei beugt, um seine unterirdischen Meister zu befreien."}},faq={{q="Was sind die Relikte von Mathystra?",a="Die Relikte von Mathystra sind Bruchstücke verzauberter Töpferwaren, Urnen und Artefakte aus den Ruinen. Sie wurden zur Blütezeit der uralten Nachtelfenzivilisation vor der Großen Zerschlagung geschaffen und bergen noch immer Reste von Magie.",al={"was sind die relikte","hintergrund der relikte von mathystra","elfenrelikte mathystra"}},{q="Warum will Onu diese Relikte?",a="Onu will die Relikte, weil der Schattenhammer uralte Elfenmagie nutzt, um seine dunklen Meister zurück in die Welt zu bringen. Indem er unversehrte Stücke aus Mathystra untersucht, hofft er zu erfahren, wie der Kult diese Macht einsetzen wird.",al={"warum will onu relikte","zweck der relikte von mathystra"}},{q="Wo befanden sich die Ruinen von Mathystra?",a="Die Ruinen von Mathystra liegen an der Nordostküste der Dunkelküste, nördlich von Ameth'Aran und Bashal'Aran und gleich hinter dem Turm von Althalaxx.",al={"wo ist mathystra","mathystra lage"}},{q="Wen versucht der Schattenhammer zurückzubringen?",a="Der Schattenhammer will seine uralten, bösartigen Meister zurückbringen. Onu warnt, dass der Kult uralte Elfenmagie nutzt, um sie nach Azeroth zurückzuholen.",al={"wer sind die meister des schattenhammers","kultmeister dunkelküste"}},{q="Was war Mathystra, bevor es zur Ruine wurde?",a="Mathystra war vor Tausenden von Jahren eine große Stadt und Bastion der Nachtelfen. Die Große Zerschlagung hinterließ nur Ruinen, und Wildnis, Geister und abscheuliche Strandbewohner wie die Naga nahmen sie in Besitz.",al={"geschichte von mathystra","was war mathystra"}},{q="Wer vergibt die Quest „Relikte von Mathystra“?",a="Onu gibt Euch nach Eurer Untersuchung der Meistergleve die Aufgabe „Relikte von Mathystra“. Er ist ein uralter Treant, der im Hain der Uralten im südlichen Zentrum der Dunkelküste verwurzelt ist.",al={"wer startet relikte von mathystra","questgeber relikte von mathystra"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="Im Silberwald gibt Trevan Rol Ott die Chance, eine Klinge nach Euren Vorgaben zu fertigen. Otts schlichte Waffen haben bei den Schmieden in der Unterstadt Lob geerntet.",h="Im Silberwald gibt Trevan Rol Ott die Chance, eine Klinge nach Euren Vorgaben zu fertigen.",kw={"auftrag","klinge nach maß","ott","schmied","tarrens mühle","unterstadt","waffenschmied"},sec={{t="Die Chance des Schmieds",b="Trevan Rol bittet Euch, Materialien zu Ott nach Tarrens Mühle zu bringen und ihm einen Auftrag anzubieten. Ott verkauft schlichte Klingen an Reisende. Trevan kaufte eine und brachte sie später zur Wartung in die Unterstadt. Dort lobten die örtlichen Schmiede ihre Qualität und hielten sie für das Werk eines berühmten Meisters. Nun hat Ott die Chance, eine Klinge nach Euren Vorgaben zu schmieden."},{t="Otts Antwort",b="Ott sagt, dass ihn noch nie jemand gebeten hat, eine Waffe nach Maß anzufertigen. Für gewöhnlich fertigt er schlichte, zweckmäßige Waffen in seinem eigenen Stil und strebt nicht nach Anerkennung. Dennoch ist er bereit, es zu versuchen. Er fragt sich, warum Ihr ihn gewählt habt, wo doch auch Schmiede in der Unterstadt Sonderanfertigungen übernehmen."}},faq={{q="Wer ist Ott?",a="Ott ist ein Waffenschmied in Tarrens Mühle, der schlichte Klingen an Reisende verkauft.",al={"ott schmied","wer ist ott","tarrens mühle schmied"}},{q="Warum will der Schmied aus der Unterstadt, dass ich Ott finde?",a="Der Schmied kaufte eine von Otts Klingen und war überrascht, als Schmiede in der Unterstadt ihre Qualität lobten. Der Schmied möchte Ott die Chance geben, etwas Besonderes zu fertigen.",al={"warum ott","unterstadt schmied auftrag","ott auftrag"}},{q="Was bringe ich Ott?",a="Ihr bringt Materialien zu Ott nach Tarrens Mühle und bietet ihm einen Auftrag an, Eure Klinge zu schmieden.",al={"materialien für ott","was mitbringen","ott materialien"}},{q="Fertigt Ott Waffen nach Maß an?",a="Ott sagt, dass ihn noch nie jemand gebeten hat, eine Waffe nach Maß anzufertigen, aber er ist bereit, es zu versuchen.",al={"ott klinge nach maß","kann ott auf bestellung schmieden","ott aufträge"}},{q="Warum fragt Ott, weshalb ich ihn gewählt habe?",a="Ott sagt, dass Schmiede in der Unterstadt Sonderanfertigungen übernehmen, und fragt sich, warum Ihr stattdessen ihn aufgesucht habt.",al={"warum ott wählen","ott fragt sich warum","warum kein schmied aus der unterstadt"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="Ein Hafenmeister bittet Euch, die Murlocs an der Eastwind Shore zu dezimieren. Seeleute, Fischer und seine Kinder beschweren sich ständig über die Plage.",h="Ein Hafenmeister bittet Euch, die Murlocs an der Eastwind Shore zu dezimieren.",kw={"eastwind shore","fischer","murloc","murloc-orakel","murloc-krieger","hafenmeister","seeleute","salzwasserbarbaren"},sec={{t="Beschwerden im Hafen",b="Der Hafenmeister hat genug Beschwerden von Seeleuten, Fischern und sogar seinen Kindern gehört. Die Murlocs machen ihm zu schaffen, doch er muss weiterhin den Hafen führen. Er bittet Euch, einige an der Eastwind Shore zu töten, in der Hoffnung, etwas Ruhe vor dem Lärm um ihn herum zu haben."}},faq={{q="Warum will der Hafenmeister, dass die Murlocs getötet werden?",a="Seeleute, Fischer und die Kinder des Hafenmeisters beschweren sich ständig über sie. Er nennt sie eine Plage und möchte etwas Ruhe, während er den Hafen führt.",al={"warum murlocs töten","murlocs belästigen hafen"}},{q="Welche Murlocs meint er?",a="Er bittet Euch, Murloc-Orakel und Murloc-Krieger an der Eastwind Shore zu töten.",al={"murloc-arten","orakel und krieger"}},{q="Wo sind die Murlocs?",a="Der Hafenmeister weist Euch zur Eastwind Shore.",al={"murlocs an der eastwind shore","wo murlocs"}},{q="Löst das Töten dieser Murlocs das Problem?",a="Der Hafenmeister rechnet damit, dass bald weitere Murlocs zurückkehren, hofft aber, dass ihr Tod ihm bis dahin etwas Ruhe verschafft.",al={"murlocs kehren zurück","ist es vorbei"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95119"] = {n="Unfriendly Competition",s="Ein Betreiber am Hafen von Powderfuse bittet Euch, die Überfälle der Eastsea crew auf Fracht und Schiffe zu stoppen. Ihre nächsten Mitglieder halten sich an der Eastwind Shore auf.",h="Ein Betreiber am Hafen von Powderfuse bittet Euch, die Überfälle der Eastsea crew auf Fracht und Schiffe zu...",kw={"frachtdiebstahl","eastsea freibeuter","eastsea crew","eastsea musketiere","eastwind shore","hafen von powderfuse","sinkende schiffe","unfreundlicher wettbewerb"},sec={{t="Entlang der Küste",b="Schiffe sinken und Fracht verschwindet, was dem Geschäft des Betreibers am Hafen von Powderfuse schadet. Die Freibeuter und Musketiere der Eastsea crew sind dem Hafen am nächsten, entlang der Eastwind Shore im Norden. Der Betreiber will, dass Ihr Euch zuerst um sie kümmert; der Rest der Operation der crew bleibt ein Problem."}},faq={{q="Wer bittet um Hilfe?",a="Ein Betreiber am Hafen von Powderfuse bittet Euch, Euch um die Eastsea crew zu kümmern.",al={"wer gab das","hafenbesitzer","powderfuse typ"}},{q="Wer ist die Eastsea crew?",a="Die Eastsea crew wird als zerstörerisch und blutrünstig beschrieben. Sie stiehlt Fracht und versenkt Schiffe.",al={"eastsea piraten","eastsea leute","wer ist eastsea"}},{q="Warum will der Betreiber sie aufhalten?",a="Die crew stiehlt Fracht und versenkt Schiffe, was den Betreiber Geld kostet.",al={"warum gegen eastsea kämpfen","frachtdiebstahl","warum sinken schiffe"}},{q="Wo sind die Mitglieder der Eastsea crew dem Hafen am nächsten?",a="Die Mitglieder der crew, die dem Hafen von Powderfuse am nächsten sind, halten sich an der Eastwind Shore im Norden auf.",al={"eastwind shore","wo sind die piraten","nördlicher strand"}}},fp="22,142,15.313.0,23.71.0,25.100.0,42.68.0,47.86.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus. Der aggressive Murloc greift kleine Schiffe in den südlichen Gewässern an.",h="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus.",kw={"murloc","murlocinseln","old rot-chum","ruderboote","kleine schiffe","südliche gewässer","wharfmaster whizzbuzz"},sec={{t="Eine Gefahr auf See",b="Seeleute und Schwimmer in den südlichen Gewässern werden auf Ruderbooten und anderen kleinen Schiffen angegriffen. Die einheimischen Fischer nennen den aggressiven Murloc dahinter Old Rot-Chum. Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis aus, dass das Wesen tot ist, und bittet Euch, ihn ihm zu bringen."}},faq={{q="Wer ist Old Rot-Chum?",a="Old Rot-Chum ist der Spitzname, den einheimische Fischer einem besonders aggressiven Murloc gegeben haben.",al={"old rot-chum","rot-chum","wer ist rot-chum"}},{q="Wo wurde Old Rot-Chum gesichtet?",a="Old Rot-Chum wurde in den südlichen Gewässern gesichtet, nahe von Inseln, die von Murlocs verseucht sind.",al={"wo ist old rot-chum","rot-chums aufenthaltsort","wo ist der murloc"}},{q="Was hat Old Rot-Chum angegriffen?",a="Old Rot-Chum hat Ruderboote und andere kleine Schiffe angegriffen.",al={"was greift rot-chum an","bootsangriffe","murloc und ruderboote"}},{q="Wer setzt die Belohnung aus?",a="Wharfmaster Whizzbuzz setzt eine Belohnung für einen Beweis auf Old Rot-Chums Tod aus.",al={"wer will einen beweis für rot-chum","belohnung vom wharfmaster","wer zahlt für old rot-chum"}},{q="Welchen Beweis verlangt Whizzbuzz?",a="Wharfmaster Whizzbuzz bittet Euch, einen Beweis für Old Rot-Chums Tod zu bringen.",al={"welcher beweis für rot-chum","beweis bringen","proof of demise"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz möchte frische Meeresfrüchte für einen neuen Eintopf in seinem Café am Wasser. Ihr sammelt Zutaten aus der Umgebung, um die Speisekarte aufzufrischen.",h="Fimbo Greasemitz möchte frische Meeresfrüchte für einen neuen Eintopf in seinem Café am Wasser.",kw={"strand","café","fimbo greasemitz","fisch","murloc-augen","gebratenes wildschwein","sand crawler fleisch","meeresfrüchteeintopf"},ang={["profession:Cooking"]="Als Koch erkennt Ihr, dass Fimbo frische Zutaten aus der Umgebung für einen Meeresfrüchteeintopf sucht."},sec={{t="Ein neues Gericht",b="Fimbo Greasemitz betreibt ein Café am Wasser, auf dessen Speisekarte täglich gebratenes Wildschwein und Fisch stehen. Er möchte einen Meeresfrüchteeintopf ausprobieren und bittet Euch, ihm Murloc-Augen und Sand-Crawler-Fleisch von den nahegelegenen Stränden zu bringen."}},faq={{q="Wer ist Fimbo Greasemitz?",a="Fimbo Greasemitz betreibt ein Café am Wasser und möchte Meeresfrüchteeintopf auf die Speisekarte setzen.",al={"wer ist fimbo","fimbo café","fimbo greasemitz"}},{q="Welche Zutaten braucht Fimbo?",a="Fimbo bittet um Murloc-Augen und Sand-Crawler-Fleisch für seinen Meeresfrüchteeintopf.",al={"zutaten für eintopf","welches fleisch","murloc-augen"}},{q="Warum möchte Fimbo Meeresfrüchte?",a="Er möchte mit einem neuen Rezept für Meeresfrüchteeintopf die tägliche Speisekarte des Cafés mit gebratenem Wildschwein und Fisch aufpeppen.",al={"warum eintopf","neue speisekarte","caféessen"}},{q="Wo findet Ihr die Zutaten?",a="Fimbo sagt, dass Ihr Murloc-Augen und Sand-Crawler-Fleisch an den nahegelegenen Stränden finden könnt.",al={"wo fleisch","wo zutaten","strandzeug"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95122"] = {n="Unchecked Expansion",s="Hafenmeister Whizzbuzz sagt, dass die Ostsee-Piraten nördlich von hier eine größere Bedrohung sind als die, gegen die Ihr zuvor gekämpft habt. Ihr Überfall ließ Windstead in Flammen aufgehen, und er will ihren Vormarsch ins Landesinnere stoppen.",h="Hafenmeister Whizzbuzz sagt, dass die Ostsee-Piraten nördlich von hier eine größere Bedrohung sind als die...",kw={"ostsee-bombenschützen","ostsee-piraten","ostsee-plünderer","pirat","ungezügelte expansion","hafenmeister whizzbuzz","windstead"},sec={{t="Windstead in Asche",b="Windstead liegt in Schutt und Asche, nachdem die Ostsee-Piraten den Ort geplündert und ihre Beute fortgeschafft haben. Hafenmeister Whizzbuzz bittet Euch, die Reihen der Plünderer und Bombenschützen nördlich von hier auszudünnen. Er fürchtet, die Piraten könnten ihr Gebiet weiter ins Landesinnere ausdehnen."}},faq={{q="Wer bittet um Hilfe gegen die Ostsee-Piraten?",a="Hafenmeister Whizzbuzz bittet Euch, die Reihen der Ostsee-Piraten auszudünnen.",al={"wer bittet um hilfe","whizzbuzz' auftrag","hafenmeister"}},{q="Was ist mit Windstead geschehen?",a="Die Ostsee-Piraten plünderten Windstead, nahmen die Beute mit und brannten den Ort nieder.",al={"windstead niedergebrannt","was ist hier geschehen","warum ist windstead zerstört"}},{q="Welche Piraten sind das Ziel?",a="Hafenmeister Whizzbuzz nennt Ostsee-Plünderer und Ostsee-Bombenschützen als die Piraten, deren Reihen Ihr ausdünnen sollt.",al={"piratentypen","gegen wen kämpfe ich","ostsee-plünderer"}},{q="Warum will Whizzbuzz ihre Reihen ausdünnen?",a="Er will verhindern, dass die Piraten ihr Gebiet weiter ins Landesinnere ausdehnen.",al={"warum die piraten aufhalten","piraten im landesinneren","warum gegen die ostsee-piraten kämpfen"}}},fp="19,188,18.241.0,46.66.0,27.87.0,29.91.0,44.68.0"}
P.entries["quest:95123"] = {n="A Blast Ye Scurvy Dogs!",s="Wharfmaster Whizzbuzz braucht Schwarzpulver, um die Schiffe der Eastsea-Piraten zu zerstören.",h="Wharfmaster Whizzbuzz braucht Schwarzpulver, um die Schiffe der Eastsea-Piraten zu zerstören.",kw={"eastsea-piraten","schwarzpulver","piratenschiffe","pulverfässer","wharfmaster whizzbuzz","winstead"},sec={{t="Pulver für Wharfmaster Whizzbuzz",b="Nach den Eastsea-Piraten selbst sind ihre Schiffe Whizzbuzz' nächstes Anliegen. Er glaubt, dass sie nahe dem frisch zerstörten Winstead im Norden Schwarzpulver gelagert haben könnten. Ihr sollt die Pulverfässer finden; seinen Plan erklärt er später."}},faq={{q="Wer verlangt nach dem Pulver?",a="Wharfmaster Whizzbuzz braucht Schwarzpulver für einen Plan gegen die Schiffe der Eastsea-Piraten.",al={"wer will die fässer","whizzbuzz pulver","wer hat mich geschickt"}},{q="Warum will Whizzbuzz Schwarzpulver?",a="Er will die Schiffe der Eastsea-Piraten ausschalten, damit sie nicht fliehen und Verstärkung holen können.",al={"warum pulver","wofür ist das pulver","plan gegen eastsea-schiffe"}},{q="Wo könnten die Piraten das Pulver gelagert haben?",a="Whizzbuzz glaubt, dass die Piraten nahe dem frisch zerstörten Winstead im Norden Schwarzpulver gelagert haben könnten.",al={"pulverfundort","wo sind die fässer","winstead pulver"}},{q="Was ist Whizzbuzz' Plan?",a="Whizzbuzz sagt, dass er seinen Plan später erklärt; zunächst sollt Ihr das Pulver finden.",al={"was ist sein plan","whizzbuzz plan","was wird geschehen"}}},fp="23,137,26.241.0,29.75.0,34.78.0,47.105.0,25.88.0"}
P.entries["quest:95125"] = {n="Otts Meisterwerk",s="Ott ist bereit, aus edlen Materialien eine Klinge für Euch zu schmieden. Ihr dürft ihm bei der Arbeit zusehen.",h="Ott ist bereit, aus edlen Materialien eine Klinge für Euch zu schmieden.",kw={"schmied","klinge","schmieden","meisterwerk","materialien","ott"},sec={{t="An der Schmiede",b="Ott schätzt die edlen Materialien und hofft, dass seine Arbeit Euren Erwartungen entspricht. Er schmiedet eine Klinge für Euch und bietet sie Euch dann für Eure Reisen an."}},faq={{q="Wer fertigt meine Klinge?",a="Ott schmiedet Eure Klinge aus den edlen Materialien, die Ihr bereitgestellt habt.",al={"wer schmiedet sie","otts klinge","ott schmied"}},{q="Kann ich Ott beim Schmieden zusehen?",a="Ott bittet Euch, zurückzutreten, während er mit dem Schmieden beginnt. Ihr werdet gebeten, ihm bei der Arbeit zuzusehen.",al={"ott beim schmieden zusehen","entstehung der klinge ansehen","schmiedevorgang"}},{q="Was sagt Ott, wenn die Klinge fertig ist?",a="Ott nennt die Klinge sein bestes Werk und hofft, dass sie Euch auf Euren Reisen gute Dienste leistet.",al={"ott fertigstellung","was sagt ott","klinge fertig"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Im Silberwald erwartet Trevan Rol die Klinge, die seine Arbeit vollenden wird, bevor er sich einem Biest stellt.",h="Im Silberwald erwartet Trevan Rol die Klinge, die seine Arbeit vollenden wird, bevor er sich einem Biest...",kw={"biest","lumina","mondsilberklinge","ott","ott's masterwork","silberwald","trevan rol"},sec={{t="Die Klinge",b="Ott dankt Euch für die Gelegenheit zu helfen und bittet Euch, Trevan seinen Dank auszurichten. Ihr bringt Ott's Masterwork zurück zu Trevan Rol im Silberwald."},{t="Trevans Zustimmung",b="Trevan Rol begutachtet die Klinge und ist mit Otts Arbeit zufrieden. Nur das Biest bleibt noch. Wenn Ihr bereit seid, weist er Euch an, mit Lumina zu sprechen."}},faq={{q="Wer hat Ott's Masterwork gefertigt?",a="Ott hat Ott's Masterwork gefertigt und es Euch für Trevan Rol mitgegeben.",al={"wer hat die klinge gefertigt","ott klinge","meisterwerk hersteller"}},{q="Wer ist Trevan Rol?",a="Trevan Rol nimmt Ott's Masterwork im Silberwald entgegen und begutachtet es.",al={"wer ist trevan","trevan klinge","trevan rol"}},{q="Wohin soll ich die Klinge bringen?",a="Bringt Ott's Masterwork zu Trevan Rol im Silberwald.",al={"wohin mit der klinge","ott's masterwork wohin bringen","klinge ziel"}},{q="Was hält Trevan von der Klinge?",a="Trevan Rol begutachtet die Klinge und sagt, sie werde gute Dienste leisten.",al={"gefällt trevan die klinge","ist otts klinge gut","trevans zustimmung"}},{q="Mit wem soll ich nach Trevan sprechen?",a="Wenn Ihr bereit seid, weist Trevan Rol Euch an, mit Lumina zu sprechen.",al={"was als nächstes","wer ist lumina","mit lumina sprechen"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger schickt Euch mit der Mondsilberklinge auf die Jagd nach Old Fire-Eye im Silberwald. Die Windformer erwarten seinen Tod, und Lumina hofft, dass die Klinge Euch gut leiten wird.",h="Lumina Windsinger schickt Euch mit der Mondsilberklinge auf die Jagd nach Old Fire-Eye im Silberwald.",kw={"banon","gilneas","lumina windsinger","mondsilberklinge","old fire-eye","silberwald","windformer"},sec={{t="Der Zweck einer Klinge",b="Die Windformer haben Euch die Mondsilberklinge gegeben. Die Einheimischen sagen, Old Fire-Eye jage in einem weitläufigen Gebiet südlich von hier, meist nahe den Toren von Gilneas. Lumina bittet Euch, ihn zu finden und mit der Klinge zu töten. Die Dankbarkeit der Windformer hängt von seinem Tod ab."},{t="Nach der Jagd",b="Als Ihr zurückkehrt, dankt Lumina Euch und sagt, Banon könne in Frieden ruhen. Dann legt sie einen kleinen Teil der Magie ihres Volkes auf die blutbefleckte Klinge und hofft, dass die Winde sie gut leiten werden."}},faq={{q="Wer bittet mich, Old Fire-Eye zu jagen?",a="Lumina Windsinger bittet Euch, Old Fire-Eye mit der Mondsilberklinge zu jagen.",al={"wer hat mich geschickt","luminas auftrag","windsinger"}},{q="Wo kann ich Old Fire-Eye finden?",a="Die Einheimischen sagen, Old Fire-Eye jage in einem weitläufigen Gebiet südlich von Lumina, meist nahe den Toren von Gilneas.",al={"fire eye fundort","wo ist old fire-eye","tore von gilneas"}},{q="Was sollte ich gegen Old Fire-Eye einsetzen?",a="Lumina bittet Euch, Old Fire-Eye mit der Mondsilberklinge zu töten.",al={"klinge für fire-eye","mondsilberwaffe","welche waffe"}},{q="Warum will Lumina, dass Old Fire-Eye getötet wird?",a="Lumina sagt, die Windformer werden dankbar sein, wenn Old Fire-Eye tot ist.",al={"warum fire-eye töten","warum ihn jagen","fire-eye grund"}},{q="Wer ist Banon?",a="Lumina sagt, Banon könne in Frieden ruhen, nachdem Old Fire-Eye getötet wurde.",al={"banon wer","banon frieden","wer ist banon"}},{q="Was macht Lumina mit der Klinge?",a="Lumina legt einen kleinen Teil der Magie ihres Volkes auf die blutbefleckte Mondsilberklinge.",al={"klingenmagie","lumina verzaubert klinge","windmagie"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="Ein Orc schickt Euch nach Rog'mar, einem Außenposten in den umkämpften Flusslanden. Meldet Euch bei Krom'rosh, dessen Erfahrung dem Außenposten geholfen hat, wiederholten Angriffen standzuhalten.",h="Ein Orc schickt Euch nach Rog'mar, einem Außenposten in den umkämpften Flusslanden.",kw={"angriffe","ostküste","krom'rosh","außenposten","flusslande","rog'mar","steinard"},sec={{t="Ein Außenposten hält stand",b="Die Flusslande liegen nordöstlich von Steinard an der Ostküste. Viele haben versucht, das Land für sich zu beanspruchen, doch nur wenigen ist es gelungen. Rog'mar ist ein kleiner Außenposten, der zahllose Angriffe überstanden hat. Ihr werdet dorthin geschickt, um Euch bei Krom'rosh zu melden, einem alten Verbündeten, dessen Kampferfahrung dem Außenposten geholfen hat, standzuhalten."}},faq={{q="Wo liegt Rog'mar?",a="Rog'mar liegt in den Flusslanden, nordöstlich von Steinard an der Ostküste.",al={"rog'mar lage","wo liegt rogmar","rog'mar außenposten"}},{q="Bei wem soll ich mich melden?",a="Ihr sollt Euch bei Krom'rosh im Außenposten Rog'mar melden.",al={"bei wem melden","wer ist krom'rosh","kromrosh"}},{q="Was ist Rog'mar?",a="Rog'mar ist ein kleiner Außenposten in den Flusslanden, der zahllosen Angriffen standgehalten hat.",al={"was ist rogmar","flusslande außenposten","kleiner außenposten"}},{q="Warum ist Krom'rosh in Rog'mar?",a="Krom'roshs Erfahrung im Kampf gegen Feinde hat dem Außenposten geholfen, standzuhalten.",al={"warum ist kromrosh dort","krom'rosh rolle","wer leitet rogmar"}},{q="Was für ein Land sind die Flusslande?",a="Die Flusslande sind ein umkämpftes Land an der Ostküste, nordöstlich von Steinard.",al={"flusslande","wie sind die flusslande","umkämpftes land"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="Ein Reisender bittet Euch, seinen Bruder Tan'jani zu finden. Nachrichten verorten ihn südlich von Loch Modan. Die jüngste weist auf Rog'mar in den Flusslanden hin.",h="Ein Reisender bittet Euch, seinen Bruder Tan'jani zu finden.",kw={"blutbefleckter brief","loch modan","vermisster bruder","flusslande","rog'mar","tan jani","tan'jani"},sec={{t="Ein Bruder fehlt",b="Der Bruder eines Reisenden, Tan'jani, ist aufgebrochen, um nach etwas Unbekanntem zu suchen. Eine Nachricht verortet ihn irgendwo südlich von Loch Modan. Ein blutbefleckter Brief erwähnt die Flusslande und das weiter südlich gelegene Rog'mar. Der Reisende bittet Euch, ihn dort zu finden."}},faq={{q="Wer ist Tan'jani?",a="Tan'jani ist der Bruder des Reisenden, der Euch bittet, ihn zu finden.",al={"tan'jani","tan jani","vermisster bruder"}},{q="Wo wurde Tan'jani zuletzt erwähnt?",a="Ein blutbefleckter Brief erwähnt die Flusslande und Rog'mar, weiter südlich als Loch Modan.",al={"wo ist tan'jani","tan'janis aufenthaltsort","rog'mar"}},{q="Wonach suchte Tan'jani?",a="Tan'jani war immer auf der Suche nach etwas, doch sein Bruder weiß nicht, wonach.",al={"wonach hat er gesucht","tan'jani auf der suche","warum ist er fortgegangen"}},{q="Was steht in den Nachrichten?",a="Ein Reisender berichtete, Tan'jani irgendwo südlich von Loch Modan getroffen zu haben. Ein blutbefleckter Brief erwähnt die Flusslande und Rog'mar, doch der größte Teil ist unleserlich.",al={"nachrichten über tan'jani","blutbefleckter brief","was geschah mit dem brief"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble bittet Euch, eine versiegelte Kiste über das Meer zu Friz Frazzlespark in den Flusslanden zu bringen. Ihr Inhalt soll bis zur Ankunft am Hafen von Powderfuse geheim bleiben.",h="Fizzgrimble bittet Euch, eine versiegelte Kiste über das Meer zu Friz Frazzlespark in den Flusslanden zu...",kw={"fizzgrimble","friz frazzlespark","geheimnisvolle kiste","überseeische lieferung","hafen von powderfuse","flusslande","dampfdruckpier"},sec={{t="Eine vorsichtige Überfahrt",b="Fizzgrimble schickt Euch nach Osten zum Dampfdruckpier, wo meist ein Schiff über das Meer fährt. Die Kiste ist für Friz Frazzlespark am Hafen von Powderfuse in den Flusslanden bestimmt. Geht unterwegs behutsam damit um; Fizzgrimble warnt davor, sie zu öffnen oder zu erschüttern."}},faq={{q="Für wen ist das Paket?",a="Friz Frazzlespark wartet am Hafen von Powderfuse in den Flusslanden auf die Kiste.",al={"wer bekommt die kiste","paket für friz frazzlespark"}},{q="Wohin soll ich die Kiste bringen?",a="Bringt sie zu Friz Frazzlespark am Hafen von Powderfuse in den Flusslanden.",al={"ziel der kiste","wo ist der hafen von powderfuse"}},{q="Wo finde ich eine Überfahrt über das Meer?",a="Fizzgrimble empfiehlt Euch, nach Osten zum Dampfdruckpier zu reisen, wo ein Schiff meist eine sichere Überfahrt bietet.",al={"wie überquere ich das meer","schiff am dampfdruckpier"}},{q="Wie soll ich unterwegs mit der Kiste umgehen?",a="Haltet die Kiste geschlossen und vermeidet es, sie zu kippen, zu schütteln oder abrupt zu bewegen.",al={"kiste transportieren","darf ich das paket öffnen"}},{q="Was ist in der Kiste?",a="Friz Frazzlespark bittet Euch, Euch umzudrehen, während Friz hineinsieht, damit der Inhalt eine Überraschung bleibt.",al={"inhalt der kiste","was ist die überraschung"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95156"] = {n="Stuff 'Em and Stick 'Em",s="Ember braucht Heu von Wheelers Bauernhof, um abgenutzte Übungspuppen zu reparieren. Die Rekruten brauchen intakte Ziele für ihr Kampftraining.",h="Ember braucht Heu von Wheelers Bauernhof, um abgenutzte Übungspuppen zu reparieren.",kw={"ember","bauernhof","heu","rekruten","stopft sie aus und spießt sie auf","übungspuppen","übungsgelände","wheeler"},sec={{t="Abgenutzte Zielpuppen",b="Auf dem Übungsgelände braucht Ember Heu, um die von den Rekruten genutzten Puppen zu flicken. Durch ihre Abnutzung könnten die Rekruten unvorbereitet in den Kampf ziehen. Ein Bauernhof außerhalb des Bergfrieds gehört Wheeler, der vielleicht Heu entbehren kann. Ember bietet ihm eine Entschädigung für alle Vorräte an, die er abgeben kann."},{t="Frische Zielpuppen",b="Ember erwartet, mehrere Ziele wieder instand zu setzen, sobald das Heu eintrifft. Das Training der Rekruten hängt von Puppen ab, die ihren Übungen standhalten."}},faq={{q="Warum braucht Ember Heu?",a="Ember braucht Heu, um abgenutzte Übungspuppen auf dem Übungsgelände zu reparieren.",al={"heu für ember","warum heu","heu für übungspuppen"}},{q="Wer ist Wheeler?",a="Wheeler betreibt den kleinen Bauernhof außerhalb des Bergfrieds, von dem Ember hofft, dass er Heu entbehren kann.",al={"wheelers bauernhof","wer hat heu","bauer"}},{q="Warum werden die Puppen repariert?",a="Die Puppen sind abgenutzt, und Ember befürchtet, dass die Rekruten ohne Reparaturen unvorbereitet in den Kampf ziehen könnten.",al={"abgenutzte puppen","übungspuppen kaputt","warum ziele reparieren"}},{q="Wird Wheeler für das Heu bezahlt?",a="Ember sagt, Wheeler werde entschädigt, wenn er Vorräte entbehren kann.",al={"wird wheeler bezahlt","entschädigung für heu","bezahlung für bündel"}},{q="Was wird Ember mit dem Heu machen?",a="Ember will das Heu sofort nutzen, um mehrere Übungsziele zu reparieren.",al={"wofür ist heu","ziele reparieren","zweck des heus"}}},fp="23,134,12.279.0,13.157.1,24.72.0,15.102.0,35.106.0,33.64.0,32.73.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="In Sturmwind wartet ein blutbefleckter Brief auf die Zustellung an Jeremy Heartweaver, der nun bei seiner Adoptivmutter Avette Fellwood im Dämmerwald lebt.",h="In Sturmwind wartet ein blutbefleckter Brief auf die Zustellung an Jeremy Heartweaver, der nun bei seiner...",kw={"avette fellwood","blutbefleckter brief","dämmerwald","jeremy heartweaver","remember that i love you","sturmwind","waisenhaus von sturmwind"},ang={["faction:Alliance"]="Für die Allianz zeugen Andenken gefallener oder verschwundener Angehöriger, die adoptierten Waisenkindern überbracht werden, vom persönlichen Leid, das die Wirren des Königreichs verursachen.",["race:Human"]="Als Mensch aus Sturmwind zieht Ihr aus dem vergleichsweise sicheren Kernland des Reiches in die heimgesuchten, vergessenen Siedlungen des Dämmerwalds."},sec={{t="Eine Botschaft für ein Waisenkind",b="Krieg, Entbehrungen und die Wirren des Königreichs haben viele Kinder im Waisenhaus von Sturmwind ihrer Familien beraubt. Jeremy Heartweaver gehörte zu ihnen, bis Avette Fellwood ihn adoptierte und zu sich in den Dämmerwald holte. Dort bringen düstere Wälder Gefahren und harte Arbeit mit sich. Die Betreuer glaubten, eine Familie könne ihm mehr bieten als das Leben im städtischen Waisenhaus."},{t="Ein düsteres Zeichen",b="Der Blutbefleckte Brief ist für Jeremy Heartweaver bestimmt, der in Avette Fellwoods Obhut lebt. Seine Spur führt nach Süden, am Wald von Elwynn vorbei und in den Dämmerwald. Welche Tragödie folgte Jeremy über die Tore von Sturmwind hinaus, und warum trägt der Brief ein so düsteres Zeichen?"}},faq={{q="Wer ist Jeremy Heartweaver?",a="Jeremy Heartweaver ist ein kleiner Junge, der im Waisenhaus von Sturmwind aufgewachsen ist. Avette Fellwood hat ihn kürzlich adoptiert, und nun lebt und arbeitet er im Dämmerwald.",al={"jeremy","wer ist jeremy","waisenkind jeremy"}},{q="Wer ist Avette Fellwood?",a="Avette Fellwood ist Jeremys Adoptivmutter und lebt im Dämmerwald. Die Waisenmatronen von Sturmwind halten sie für eine liebenswerte Frau, die Jeremy vermutlich aufnahm, um bei ihrer täglichen Arbeit ein weiteres Paar Hände zu haben.",al={"avette","wer ist avette","adoptivmutter"}},{q="Was ist der Blutbefleckte Brief?",a="Der Blutbefleckte Brief ist für Jeremy Heartweaver bestimmt und wird seiner Adoptivmutter Avette Fellwood überbracht. Er lässt Gewalt oder eine Tragödie erahnen.",al={"blutbefleckter brief","der brief","was ist der brief"}},{q="Wo finde ich Avette Fellwood?",a="Avette Fellwood lebt im Dämmerwald, dem finsteren Wald direkt südlich des Walds von Elwynn, auf der anderen Seite des Flusses.",al={"avette fellwood aufenthaltsort","wo ist avette","avette finden"}},{q="Warum wurde Jeremy in den Dämmerwald geschickt?",a="Jeremy wurde aus dem Waisenhaus von Sturmwind adoptiert. Seine Betreuer glaubten, eine Familie und ehrliche Arbeit im gefährlichen Dämmerwald seien besser als ein Leben als Waise im Waisenhaus.",al={"warum dämmerwald","warum verließ jeremy sturmwind","waisenhaus dämmerwald"}},{q="Welche Fraktion kann diese Quest annehmen?",a="Nur die Allianz kann diesen Auftrag annehmen. Er beginnt in Sturmwind, der Hauptstadt der Menschen, und führt in den von der Allianz gehaltenen Dämmerwald.",al={"ist das für die allianz","nur allianz","horde quest"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok bittet Euch, in der Nähe von Bolder'ok Paletuskfleisch zu sammeln. Die Ranch versorgt nahegelegene Oger und beliefert Rog'mar, während der Krieg voranschreitet.",h="Na'zok bittet Euch, in der Nähe von Bolder'ok Paletuskfleisch zu sammeln.",kw={"wildschweinfleisch","bolder'ok","na'zok","oger","paletusk","paletusk sammeln","ranch","rog'mar"},sec={{t="Fleisch für die Ranch",b="Na'zok braucht mehr Fleisch auf der Ranch in der Nähe von Bolder'ok. Dort lassen die Oger Na'zok bleiben, solange das Fleisch weiter geliefert wird. Während der Krieg voranschreitet, wächst der Hunger, und die Oger beginnen, Na'zok als ihre nächste Mahlzeit ins Auge zu fassen. Ihr sollt für die hungrigen Oger und Rog'mar Stücke Paletuskfleisch sammeln."}},faq={{q="Wer bittet um Fleisch?",a="Na'zok bittet Euch, in der Nähe von Bolder'ok Wildschweinfleisch für die Oger und Rog'mar zu sammeln.",al={"wer braucht fleisch","na'zoks bitte","wer ist na'zok"}},{q="Warum braucht Na'zok das Fleisch?",a="Die Ranch ist eine der wenigen Nahrungsquellen für Na'zok. Die Oger lassen Na'zok bleiben, solange weiterhin Fleisch geliefert wird.",al={"warum fleisch","warum wildschweine sammeln","hungrige oger"}},{q="Wer ist Rog'mar?",a="Rog'mar ist eine Siedlung, keine Person. Na'zok möchte genügend Fleisch übrig haben, um sie zu versorgen.",al={"rog'mars fleisch","fleisch für rog'mar"}},{q="Wo ist Na'zok?",a="Na'zok ist in der Nähe von Bolder'ok.",al={"na'zoks aufenthaltsort","wo ist die ranch"}},{q="Welches Fleisch wird gebraucht?",a="Na'zok bittet um Stücke Paletuskfleisch.",al={"wildschweinfleisch","paletuskfleisch","fleischstücke"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.87.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok bittet Euch, entlaufene Young Paletusks zu seinem Hof nahe Bolder'ok zurückzubringen. Die Ferkel haben den Fluss überquert, und sie müssen zurück in ihre Gehege.",h="Na'zok bittet Euch, entlaufene Young Paletusks zu seinem Hof nahe Bolder'ok zurückzubringen.",kw={"bolder'ok","entlaufene ferkel","hof","gorgegut","na'zok","paletusk","schweine","young paletusks"},sec={{t="Die entlaufenen Ferkel",b="Auf Na'zoks Hof nahe Bolder'ok laufen mehr Schweine frei im Tal herum, als in den Gehegen stehen. Gorgegut war kein idealer Knecht, hält aber Menschen fern. Einige der Young Paletusks haben den Fluss überquert und sind zu klein, um draußen geschlachtet zu werden. Na'zok gibt Euch einen Stock, damit Ihr sie zurück in ihre Gehege treiben könnt."}},faq={{q="Warum sind die Ferkel aus ihren Gehegen entlaufen?",a="Einige Young Paletusks sind über den Fluss von Na'zoks Hof entlaufen.",al={"entlaufene ferkel","freilaufende schweine","warum schweine draußen"}},{q="Wer ist Gorgegut?",a="Gorgegut ist Na'zoks Knecht, auch wenn Na'zok sagt, dass er nicht gerade ideal ist.",al={"gorgegut knecht","wer ist gorgegut","typ vom schweinehof"}},{q="Warum sollen die Young Paletusks zurückgebracht werden?",a="Die Young Paletusks sind zu klein, um draußen geschlachtet zu werden, deshalb will Na'zok sie zurück auf den Hof bringen lassen.",al={"ferkel zurückbringen","warum schweine zurückbringen","young paletusk"}},{q="Wo liegt Na'zoks Hof?",a="Na'zoks Hof liegt nahe Bolder'ok.",al={"lage von na'zoks hof","hof nahe bolder'ok","wo liegt der schweinehof"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95165"] = {n="See Ya, Scallywags!",s="Der Hafenmeister hat einen Plan für die drei Boote der Eastsea. Ihr sollt Zeitzünder in ihren Rümpfen anbringen und ihn dann die Ladungen zünden lassen.",h="Der Hafenmeister hat einen Plan für die drei Boote der Eastsea.",kw={"boote","kanonen","eastsea","schießpulver","ferngesteuerte sprengladung","macht's gut, ihr schurken","zeitzünder","hafenmeister"},sec={{t="Ladungen an Bord",b="Der Hafenmeister verwendet das gestohlene Schießpulver, um Zeitzünder für die Boote der Eastsea zu bauen. Ihr sollt in den Rumpf jedes Schiffs eine Ladung nahe den Kanonen einsetzen. Sobald alle angebracht sind, bringt Euch in Sicherheit, damit er die Sprengladungen zünden kann."}},faq={{q="Was soll ich für den Hafenmeister tun?",a="Bringt in den Rumpf jedes der drei Boote der Eastsea eine ferngesteuerte Sprengladung nahe den Kanonen an.",al={"was soll ich tun","aufgabe mit eastsea booten"}},{q="Warum soll das gestohlene Schießpulver verwendet werden?",a="Der Hafenmeister verwendet das Schießpulver, um Zeitzünder für die Boote zu bauen.",al={"gestohlenes schießpulver","wozu ist das pulver"}},{q="Warum sollen die Ladungen nahe den Kanonen angebracht werden?",a="Der Hafenmeister sagt, das Schießpulver lasse die Sprengladungen nahe den Kanonen stärker werden.",al={"ladung nahe kanonen","wohin mit den ladungen"}},{q="Wie viele Boote sind beteiligt?",a="Ihr sollt Ladungen an jedem der drei Boote der Eastsea anbringen.",al={"wie viele schiffe","drei boote"}},{q="Was weiß der Hafenmeister über Sprengstoffe?",a="Er sagt, er habe früher seinen Lebensunterhalt auf weniger ehrliche Weise verdient.",al={"sprengstoffe des hafenmeisters","warum kann er bomben bauen"}}},fp="19,136,14.230.0,40.101.0,30.71.0,39.91.0,28.64.0,48.45.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Hamur in Bolder'ok braucht gute Steine aus dem nahen Fluss, um eine winzige Waffe für ein winziges Wesen zu schmieden.",h="Hamur in Bolder'ok braucht gute Steine aus dem nahen Fluss, um eine winzige Waffe für ein winziges Wesen zu...",kw={"bolder'ok","gute steine","hamur","ogerwaffe","fluss","winzige waffe"},sec={{t="Hamurs Bitte",b="Hamur in Bolder'ok meint, Ihr seid zu klein, um eine gute Ogerwaffe zu führen. Er bietet an, Euch eine winzige Waffe zu schmieden, wenn Ihr ihm gute Steine bringt. Er möchte Steine aus dem Fluss außerhalb von Bolder'ok, denn nur die besten Steine taugen dafür."}},faq={{q="Wer ist Hamur?",a="Hamur ist in Bolder'ok und bietet an, Euch eine winzige Waffe zu schmieden, wenn Ihr ihm gute Steine bringt.",al={"wer ist hamur","wer möchte steine"}},{q="Wo finde ich die Steine?",a="Hamur bittet um gute Steine aus dem Fluss außerhalb von Bolder'ok.",al={"fundort der steine","wo sind steine"}},{q="Warum möchte Hamur Steine?",a="Hamur sagt, er wird die guten Steine verwenden, um eine winzige Waffe für ein winziges Wesen zu schmieden.",al={"warum steine","wofür steine"}},{q="Welche Art von Steinen möchte Hamur?",a="Hamur möchte gute Steine aus dem Fluss außerhalb von Bolder'ok. Er sagt, nicht jeder Stein eigne sich dafür.",al={"gute steine","welche steine"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95184"] = {n="The Sharpest of Blades",s="Ember Bladewhisper möchte Schleifsteine für die Rekruten von Farholde. Eine erfahrene Klinge kann den Unterschied zwischen Sieg und Tod bedeuten.",h="Ember Bladewhisper möchte Schleifsteine für die Rekruten von Farholde.",kw={"ember bladewhisper","farholde","rekruten","schleifsteine","solid sharpening stones","trainingsgelände"},sec={{t="Klingen für Rekruten",b="Auf dem Trainingsgelände von Farholde merkt Ember Bladewhisper, dass die Rekruten kaum den Unterschied zwischen einem Übungsschwert und der gut gepflegten Klinge eines Veteranen kennen. Ihr sollt ihr Schleifsteine bringen, damit die Rekruten lernen, was eine scharfe Schneide bedeutet."}},faq={{q="Wer braucht Schleifsteine?",a="Ember Bladewhisper bittet auf dem Trainingsgelände von Farholde um Schleifsteine.",al={"wer möchte steine","ember bladewhisper steine"}},{q="Warum möchte Ember die Steine?",a="Sie möchte, dass die Rekruten verstehen, worin sich eine geschärfte Klinge von einem Übungsschwert unterscheidet.",al={"warum schleifsteine","wozu sind steine"}},{q="Wohin soll ich die Steine bringen?",a="Bringt die Schleifsteine zu Ember Bladewhisper auf dem Trainingsgelände von Farholde.",al={"wohin mit steinen","farholde steine"}},{q="Welche Art Steine braucht Ember?",a="Ember bittet um Solid Sharpening Stones.",al={"welche steine","steinart"}}},fp="22,137,19.258.0,28.79.0,31.89.0,32.83.0,36.39.0"}
P.entries["quest:95189"] = {n="Wappen von Lordaeron",s="In den Ruinen von Capital City überdauert ein verwittertes Wappen von Lordaeron aus dem gefallenen nördlichen Königreich. Solche Relikte sind selten, und Lady Dena Kennedy in Sturmwind möchte unbedingt eines erwerben.",h="In den Ruinen von Capital City überdauert ein verwittertes Wappen von Lordaeron aus dem gefallenen nördlichen...",kw={"wappen von lordaeron","heraldik","lady dena kennedy","lordaeron","relikt","ruinen von lordaeron","sturmwind","tirisfal"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Lordaerons Emblem als Zeichen der Gründung der Allianz betrachten. Seine Bergung hindert die Geißel und die Verlassenen daran, dieses Symbol auszulöschen.",["race:Human"]="Als Mensch erinnert Euch das Wappen an das große Königreich, das einst die Allianz anführte, besonders wenn Eure Familie aus dem Norden stammt."},sec={{t="Ein zerschlagenes Erbe",b="Die Geißel hinterließ Lordaerons Paläste und Archive als Ruinen im Schatten der Unterstadt. Seine stolzen Insignien wurden zerstört oder dem Verfall überlassen, sodass nur wenige Relikte mit dem königlichen Wappen erhalten sind. Ein verwittertes Wappen aus den nördlichen Ruinen bewahrt ein Stück Menschheitsgeschichte."},{t="Zuflucht im Süden",b="Nach dem Dritten Krieg flohen Tausende Flüchtlinge aus Lordaeron nach Süden in Richtung des Königreichs Sturmwind. Sie trugen Erinnerungen an ihre Heimat mit sich. In Sturmwind sucht Lady Dena Kennedy nach Überresten ihrer Heimat. Für jene, die den Norden hinter sich ließen, ist ein solches Wappen eine kostbare Verbindung zu Lordaeron."}},faq={{q="Was ist das Wappen von Lordaeron?",a="Das Wappen von Lordaeron ist ein verwittertes Emblem mit dem offiziellen Zeichen des Königreichs. Es überstand Lordaerons Untergang durch die Geißel und bleibt ein historisches Relikt für die überlebenden Menschen.",al={"wappen von lordaeron","was ist das wappen von lordaeron","lordaeron wappen gegenstand"}},{q="Wer möchte das Wappen von Lordaeron haben?",a="Lady Dena Kennedy in Sturmwind möchte das Wappen haben. Sie sammelt und bewahrt seltene Artefakte aus Lordaeron.",al={"wer nimmt das wappen","wohin mit dem wappen von lordaeron","wappen abgeben"}},{q="Wo wurde das Wappen gefunden?",a="Das Wappen wurde aus den Ruinen von Lordaeron in Tirisfal geborgen. Die zerstörte Hauptstadt liegt über der Unterstadt, der Hochburg der Verlassenen.",al={"wappen fundort","ruinen wappen","wo gibt es das wappen"}},{q="Warum sind Artefakte aus Lordaeron so selten?",a="Nur wenige Artefakte aus Lordaeron überstanden den raschen Untergang des Königreichs während des Dritten Krieges. Die Geißel metzelte seine Bewohner nieder und verwüstete seine Ländereien, während sich im Norden die Verlassenen erhoben.",al={"warum sind lordaerons relikte selten","lordaeron artefakte seltenheit"}},{q="Warum sind Sturmwind die Relikte Lordaerons wichtig?",a="Sturmwind nahm Flüchtlinge, Ritter und Adlige auf, die vor der Verwüstung Lordaerons flohen. Seine Relikte zu bewahren, ehrt das gefallene nördliche Königreich und hält sein menschliches Erbe lebendig.",al={"warum ist es sturmwind wichtig","sturmwind lordaeron relikte"}},{q="Wer ist Lady Dena Kennedy?",a="Lady Dena Kennedy ist eine Adlige in Sturmwind, die Erbstücke und andere historische Überreste Lordaerons zu retten sucht.",al={"lady dena kennedy","wer ist dena kennedy"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95194"] = {n="Our Man in Theramore",s="SI:7 bittet Euch um Hilfe: Ein Mann wurde auf der Insel Theramore angespült und behauptet, Varian Wrynn zu sein. Trefft ihren Agenten Sully im Gasthaus und erfahrt, was als Nächstes geschieht.",h="SI:7 bittet Euch um Hilfe: Ein Mann wurde auf der Insel Theramore angespült und behauptet, Varian Wrynn zu...",kw={"jaina prachtmeer","unser mann in theramore","si:7","könig von sturmwind","sully","die insel theramore","varian wrynn","washed ashore"},sec={{t="Ein Anspruch auf Theramore",b="SI:7 hat erfahren, dass die Marines von Jaina Prachtmeer einen Mann auf der Insel Theramore an Land gebracht haben. Er sagt, er sei Varian Wrynn, der vermisste König von Sturmwind. Ihr Agent Sully wartet im Gasthaus, und SI:7 möchte, dass Ihr herausfindet, was vor sich geht."}},faq={{q="Warum braucht SI:7 Euch in Theramore?",a="Ein auf der Insel Theramore angespülter Mann behauptet, Varian Wrynn zu sein. SI:7 möchte, dass Ihr seinen Agenten Sully trefft und herausfindet, was vor sich geht.",al={"warum theramore","si7 theramore","was braucht si7"}},{q="Wer ist Sully?",a="Sully ist ein Zwerg und ein auf der Insel Theramore stationierter Agent von SI:7. Er wartet im Gasthaus auf Euch.",al={"wer ist sully","sully theramore","zwergenagent"}},{q="Wer brachte den Mann an Land?",a="Die Marines von Jaina Prachtmeer brachten den Mann nach Theramore, nachdem sie ihn am Ufer angespült gefunden hatten.",al={"angespülter mann","wer fand varian","marines theramore"}},{q="Was behauptet der angespülte Mann?",a="Er behauptet, Varian Wrynn zu sein, der König von Sturmwind.",al={"mann am ufer","varians behauptung","ist das varian"}},{q="Wo finde ich Sully?",a="Sully wartet im Gasthaus auf der Insel Theramore auf Euch.",al={"sullys aufenthaltsort","wo ist der agent","gasthaus theramore"}}},fp="20,151,20.235.0,35.141.0,13.97.0,27.99.0,34.52.0,23.46.0"}
P.entries["quest:95195"] = {n="Blutverschmiertes Insigne",s="In Lordaerons verseuchten Ruinen tragen blutverschmierte Insignien die alten Allianzwappen gefallener Verteidiger. Die Familien vieler Soldaten flohen während des Dritten Krieges nach Süden nach Sturmwind.",h="In Lordaerons verseuchten Ruinen tragen blutverschmierte Insignien die alten Allianzwappen gefallener...",kw={"allianz","blutverschmiertes insigne","lordaeron","marcus jonathan","flüchtlinge","ruinen von lordaeron","sturmwind","dritter krieg"},ang={["class:Paladin"]="Als Paladin ehrt Ihr die verlorenen Brüder und Schwestern der Ritter der Silbernen Hand, indem Ihr Orden jener bergt, die in der Hauptstadt an der Seite des Ordens kämpften.",["faction:Alliance"]="Für die Allianz ehrt die Rückgabe dieser Orden an General Marcus Jonathan die Soldaten, die bei der Verteidigung ihres Volkes starben.",["race:Human"]="Für die Menschen der Allianz erinnern diese Abzeichen an den Untergang des größten Menschenreiches und verbinden Sturmwinds Flüchtlinge mit ihren gefallenen Angehörigen im Norden."},sec={{t="Andenken der Gefallenen",b="Prinz Arthas kehrte mit der Geißel zurück und verwüstete Lordaeron. Die gewaltige Armee des Reiches wurde überwältigt, und zahllose Soldaten starben bei der Verteidigung der Hauptstadt und des Umlands. Verrostete Rüstungen und blutbeflecktes Messing sind alles, was von vielen Kämpfern geblieben ist.\n\nDie alten Insignien der Allianz gehörten jenen, die sich den Untoten entgegenstellten. In Erde und Schutt getreten, erinnern die Orden an Lordaerons letzte Verteidigung."},{t="Ein Bote für die Vertriebenen",b="Viele Überlebende flohen über das Meer nach Süden und ließen sich in Sturmwind nieder. Die Allianz und verwandtschaftliche Bande verbinden die beiden Menschenreiche, und Familien im Süden suchen noch immer Nachricht von Angehörigen, die im Norden verschollen sind.\n\nGeneral Marcus Jonathan befehligt Sturmwinds Stadtwache und nimmt die blutverschmierten Insignien in Verwahrung. Er bewahrt das Andenken der Verteidiger und hilft ihren hinterbliebenen Familien, von ihrem Schicksal zu erfahren."}},faq={{q="Was sind die blutverschmierten Insignien?",a="Es sind militärische Orden, die Soldaten Lordaerons trugen, als sie während des Dritten Krieges unter dem Banner der Allianz kämpften und starben.",al={"blutverschmiertes insigne gegenstand","was ist dieses insigne","insigne hintergrund"}},{q="Wo sind diese Insignien zu finden?",a="Sie sind überall in den Ruinen von Lordaeron in Tirisfal zu finden, wo die Verteidiger des Königreichs der Geißel ein letztes Mal standhielten.",al={"wo werden insignien erbeutet","insigne fundort","ruinen von lordaeron abzeichen"}},{q="Warum will General Marcus Jonathan sie haben?",a="General Marcus Jonathan befehligt die Stadtwache von Sturmwind, wo heute viele Flüchtlinge aus dem Norden leben. Er sammelt die Orden, um Lordaerons Gefallene zu ehren und ihren lebenden Angehörigen zu helfen, mit dem Verlust abzuschließen.",al={"wer ist marcus jonathan","warum nach sturmwind bringen","marcus jonathan insigne"}},{q="Warum trugen Lordaerons Soldaten Insignien der Allianz?",a="Die ursprüngliche Allianz wurde in Lordaeron unter König Terenas Menethil II geschmiedet, um die Old Horde zu besiegen. Lordaeron führte die Allianz von Lordaeron durch den Second War und den Dritten Krieg.",al={"lordaeron allianzwappen","allianz von lordaeron abzeichen"}},{q="Was geschah mit den Soldaten, die diese Orden trugen?",a="Sie wurden während des Dritten Krieges getötet, als Prinz Arthas Menethil das Reich verriet, seinen Vater tötete und die Geißel auf die Hauptstadt losließ.",al={"was tötete die soldaten","schicksal der soldaten lordaerons"}},{q="Gibt es noch lebende Angehörige dieser Soldaten?",a="Ja. Tausende Bürger und Soldaten flohen während der Seuche und der Invasionen der Geißel aus Lordaeron und fanden im Königreich Sturmwind Zuflucht.",al={"lordaeron flüchtlinge sturmwind","wer vermisst diese soldaten"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:95196"] = {n="Watch Yer Back",s="Sully McCleary bittet Euch, ihn bei einem Friedhof außerhalb der Stadt zu treffen. Er möchte Euch mehr über Euren Auftrag erzählen und dabei Verfolger abschütteln.",h="Sully McCleary bittet Euch, ihn bei einem Friedhof außerhalb der Stadt zu treffen.",kw={"düstermarschen","friedhof","auftrag","sully mccleary","turm","pass auf deinen rücken auf"},sec={{t="Ein heimliches Treffen",b="Sully McCleary will durch die Tür hinter Euch verschwinden. Sobald er fort ist, sollt Ihr ihn hinter dem Friedhof außerhalb der Stadt treffen und sicherstellen, dass Euch niemand folgt."},{t="Die nächste Anweisung",b="In den Düstermarschen trägt Sully McCleary Euch auf, einen Turm zu untersuchen und herauszufinden, was Ihr könnt. Nun hängt alles davon ab, was Ihr dort entdeckt."}},faq={{q="Wer bittet mich, ihn zu treffen?",a="Sully McCleary bittet Euch, ihn hinter dem Friedhof außerhalb der Stadt zu treffen.",al={"wer ist sully","sully mccleary","sully treffen"}},{q="Wo treffe ich Sully?",a="Trefft Sully hinter dem Friedhof außerhalb der Stadt, nachdem er durch die Tür hinter Euch gegangen ist.",al={"sullys aufenthaltsort","wo ihn treffen","treffen am friedhof"}},{q="Warum soll ich sicherstellen, dass mir niemand folgt?",a="Sully trägt Euch auf, sicherzustellen, dass Euch niemand folgt, bevor Ihr ihn trefft.",al={"verfolger abschütteln","warum niemand folgen darf","auf meinen rücken achten"}},{q="Was möchte Sully, dass ich als Nächstes tue?",a="Sully bittet Euch, Euch in einen Turm zu schleichen und herauszufinden, was Ihr könnt.",al={"auftrag im turm","welcher auftrag","was sully verlangt"}}},fp="14,132,15.159.0,13.135.1,29.70.0,22.91.0,38.66.0,35.63.0"}
P.entries["quest:95198"] = {n="The Return of the King?",s="Ein Kontakt schickt Euch verkleidet in den Magierturm von Theramore, um nach dem Mann vom Strand zu forschen.",h="Ein Kontakt schickt Euch verkleidet in den Magierturm von Theramore, um nach dem Mann vom Strand zu forschen.",kw={"alcaz","defias","verkleidung","magische verhüllung","jaina","könig","marine von kul tiras","magierturm","theramore"},sec={{t="Im Magierturm",b="Ein Kontakt übergibt Euch eine magische Verkleidung, die Magier daheim angefertigt haben. Sie soll Euch wie einen Marine von Kul Tiras aussehen lassen. Im Magierturm von Theramore lauscht Ihr Jaina und ihrem engsten Kreis, um etwas über den Mann vom Strand zu erfahren. Jaina durchschaut die Verkleidung, also haltet Euch fern."},{t="Ein Gefängnis auf Alcaz",b="Der Mensch vom Strand ist nicht der Gesuchte. Doch die Kunde von einem Gefängnis auf Alcaz und der Beteiligung der Defias lässt den Kontakt vermuten, dass der König dort festgehalten worden sein könnte. Der Kontakt will handeln und den König nach Sturmwind zurückbringen."}},faq={{q="Wer gibt mir die Verkleidung?",a="Ein Kontakt übergibt Euch eine magische Verkleidung, die Magier daheim angefertigt haben. Sie lässt Euch wie einen Marine von Kul Tiras aussehen.",al={"wer gibt die verkleidung","geber der verkleidung"}},{q="Wo soll ich lauschen?",a="Ihr sollt im Magierturm von Theramore Jaina und ihrem engsten Kreis belauschen.",al={"wo lauschen","magierturm"}},{q="Wem sollte ich nicht zu nahe kommen?",a="Haltet Euch von Jaina fern. Sie kann die Verkleidung durchschauen.",al={"jaina meiden","jainas verkleidung"}},{q="Wie soll die Verkleidung aussehen?",a="Die magische Verkleidung soll Euch wie einen Marine von Kul Tiras aussehen lassen.",al={"marine-verkleidung","kul-tiras-verkleidung"}}},fp="23,172,17.269.0,17.241.1,26.97.0,30.81.0,36.64.0,40.62.0"}
P.entries["quest:952"] = {n="Der Hain der Uralten",s="Eine dringende Depesche führt Euch von Darnassus zur Dunkelküste, wo Onu im Hain der Uralten wartet. Erzdruide Fandral Hirschhaupt schickt Euch mit einer Nachricht für den Ancient of Lore, der südlich von Auberdine lebt, über das Meer.",h="Eine dringende Depesche führt Euch von Darnassus zur Dunkelküste, wo Onu im Hain der Uralten wartet.",kw={"ancient of lore","auberdine","zirkel des cenarius","dunkelküste","darnassus","fandral hirschhaupt","der hain der uralten","onu","die lichtung des orakels"},ang={["class:Druid"]="Als Druide überbringt Ihr eine Nachricht zwischen dem Erzdruiden von Darnassus und Onu. Ihre unterschiedlichen Gemüter stellen Hirschhaupts Tatendrang der stillen Geduld eines Ancient of Lore gegenüber.",["faction:Alliance"]="Als Streiter der Allianz lasst Ihr Eure Angelegenheiten in Darnassus hinter Euch und habt Anlass, Hippogryphenrouten zu sichern und die Küste der Dunkelküste zu erkunden.",["race:NightElf"]="Als Nachtelf verlasst Ihr die geschützte Wiege Teldrassils und zieht in die weite Wildnis auf Kalimdors Festland. Die Reise zeigt den Gegensatz zwischen Fandral Hirschhaupt und den Lehren Malfurion Sturmgrimms."},sec={{t="Abschied von den Ästen",b="Nachdem Ihr auf der Lichtung des Orakels hoch oben auf Teldrassil geholfen habt, ruft Erzdruide Fandral Hirschhaupt Euch zu einer weiteren Aufgabe. Er schickt Euch mit einer dringenden Depesche für Onu über das Meer zur Dunkelküste. Von Darnassus aus könnt Ihr einen Hippogryphenflug nehmen."},{t="Ein Gegensatz in Geduld",b="Südlich von Auberdine erreicht Ihr den Hain der Uralten und überbringt Onu die Nachricht. Der hoch aufragende Ancient of Lore nimmt sie still entgegen und bemerkt Hirschhaupts Ungeduld. Onu und die uralten Hüter des Waldes glauben, dass sich alles zu seiner Zeit entfaltet. Shan'do Malfurion Sturmgrimm verkörperte diese geduldige Weisheit, während sie Hirschhaupt fehlt."}},faq={{q="Wer vergibt die Quest „Der Hain der Uralten“?",a="Erzdruide Fandral Hirschhaupt schickt Euch aus der Enklave des Cenarius in Darnassus los, nachdem Ihr seinen vorherigen Auftrag auf der Lichtung des Orakels erledigt habt.",al={"questgeber hain der uralten","wer vergibt hain der uralten","fandral hirschhaupt quest"}},{q="Wo liegt der Hain der Uralten?",a="Der Hain der Uralten liegt auf dem Festland an der Dunkelküste, direkt südlich des Küstenhafens Auberdine.",al={"hain der uralten standort","wo ist der hain der uralten","onu standort"}},{q="Wer ist Onu?",a="Onu ist ein weiser und ehrwürdiger Ancient of Lore an der Dunkelküste. Er bewahrt das Wissen der Natur und zeichnet es auf, und er empfängt Schreiben von der druidischen Führung in Darnassus.",al={"wer ist onu","onu dunkelküste","ancient of lore onu"}},{q="Wie gelangt Ihr von Teldrassil zur Dunkelküste?",a="Reist von Darnassus nach Rut'theran und nehmt einen Hippogryphen über das Wasser nach Auberdine, der Hafensiedlung an der Dunkelküste.",al={"wie zur dunkelküste gelangen","reise nach auberdine","hippogryph zur dunkelküste"}},{q="Warum erwähnt Onu Shan'do Sturmgrimm?",a="Nach Erhalt der Nachricht bemerkt Onu die rastlose Hast von Erzdruide Hirschhaupt. Er sagt, der Wald folge seinem eigenen Tempo, mit einer Geduld, die Shan'do Malfurion Sturmgrimm verstand und achtete.",al={"onu malfurion bemerkung","shan'do sturmgrimm erwähnung","warum shando erwähnen"}},{q="Welche Quests gehen dieser voraus?",a="Dies ist der letzte Teil einer kurzen Folge von drei Quests. Sie beginnt mit The Enchanted Glade, geht mit Teldrassil weiter und schickt Euch dann zur Dunkelküste.",al={"voraussetzungen hain der uralten","hain der uralten questreihe","quests vor onu"}}},fx={["00893f03"]={q="Warum möchte Erzdruide Fandral Hirschhaupt, dass diese Nachricht an Onu übermittelt wird?",a="Fandral Hirschhaupt ist bestrebt, eine enge Kommunikation mit den alten Beschützern auf der anderen Seite des Meeres in Kalimdor aufrechtzuerhalten. Onu, ein Ältester der Lehren, verwurzelt an der Dunkelküste, hat auf Nachricht vom Erzdruiden bezüglich der Angelegenheiten auf Teldrassil gewartet. Nun, da Fandral die neuesten Berichte aus Die Lichtung des Orakels erhalten hat, ist er ungeduldig, seine Erkenntnisse und Anweisungen unverzüglich weiterzuleiten, um seine Pläne für die Nachtelfen voranzutreiben.",al={"warum nachricht an onu schicken","fandral beweggrund grove of the ancients","warum muss fandral das übermitteln"}},["658e120a"]={q="Warum wählt Fandral Hirschhaupt Euch aus, um seine Nachricht zu überbringen?",a="Nachdem er gesehen hat, wie Ihr die Nachricht aus Die Lichtung des Orakels nach Darnassus gebracht habt, denkt Fandral, dass Ihr bereits in der Lage seid, sensible Besorgungen über Entfernungen hinweg zu erledigen. Anstatt erfahrene Emissäre des Zirkels des Cenarius oder Schildwachen von ihren Pflichten abzuziehen, setzt er einfach einen bewährten Boten ein, um sein Schreiben an die Dunkelküste zu befördern.",al={"warum ich für fandrals nachricht","warum spieler zu onu schicken","warum keine schildwache schicken"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Wappen von Lordaeron",s="Die Verlassenen bewahren in Unterstadt, was von Lordaeron noch übrig ist. Ein verwittertes Wappen trägt das Emblem des gefallenen Königreichs, eine seltene Verbindung zu seiner Vergangenheit.",h="Die Verlassenen bewahren in Unterstadt, was von Lordaeron noch übrig ist.",kw={"crest of lordaeron","verlassene","lordaeron","oran snakewrithe","relikt","unterstadt"},ang={["faction:Horde"]="Ihr helft den Archivaren der Verlassenen in Unterstadt, Lordaerons Erbe inmitten der von der Geißel hinterlassenen Ruinen zu bewahren.",["race:Undead"]="Als ehemaliger Bürger Lordaerons schätzt Ihr Relikte des gefallenen Königreichs als seltene Überreste Eurer Vergangenheit und Eures Erbes."},sec={{t="Ein überdauerndes Symbol des gefallenen Königreichs",b="Der Dritte Krieg zerschmetterte Lordaeron. Asche, Ruinen und die Verwüstung der Geißel verschlangen weite Teile des Königreichs und ließen nur wenige Embleme zurück. Für die Verlassenen unter den Ruinen der Capital City sind die erhaltenen Stücke kostbare Verbindungen zu der Zivilisation, der sie einst angehörten."},{t="Das Erbe der Verlassenen bewahren",b="Das verwitterte Wappen wird aus der weiten Welt zu Oran Snakewrithe in Unterstadt gebracht. Oran prüft das Metall mit einem Biss und bestätigt dann, dass es echt und weitgehend unversehrt ist. Für Oran und die Archivare der Verlassenen hilft jedes geborgene Stück, eine Geschichte wiederherzustellen, die die Geißel auszulöschen suchte."}},faq={{q="Was ist das Crest of Lordaeron?",a="Das Crest of Lordaeron ist ein verwittertes Emblem des gefallenen Menschenkönigreichs. Nur wenige gegenständliche Relikte überstanden die Zerstörung durch die Geißel, daher bewahrt es ein seltenes Stück von Lordaerons Vergangenheit.",al={"was ist crest of lordaeron","lordaeron wappen quest","wappen gegenstand"}},{q="Wer möchte das Wappen in Unterstadt haben?",a="Oran Snakewrithe in Unterstadt nimmt das Wappen entgegen. Oran untersucht und verwahrt Artefakte, die mit dem alten Königreich verbunden sind.",al={"wer bekommt das wappen","wo das wappen abgeben","wappen abgeben unterstadt"}},{q="Warum beißt Oran Snakewrithe in das Wappen?",a="Oran Snakewrithe beißt in das Wappen, um sein Metall zu prüfen und seine Echtheit festzustellen. Oran bestätigt, dass es ein weitgehend unversehrtes Relikt aus Lordaeron ist.",al={"warum in das wappen beißen","oran beißt ins wappen"}},{q="Warum schätzen die Verlassenen Relikte aus Lordaeron?",a="Die Verlassenen sind die untoten Überreste der einstigen Bevölkerung Lordaerons. Relikte ihrer zerstörten Heimat bleiben greifbare Verbindungen zu ihrer Geschichte und Identität.",al={"warum ist lordaeron den verlassenen wichtig","relikte der verlassenen"}},{q="Was geschieht mit dem Wappen nach seiner Abgabe?",a="Oran Snakewrithe nimmt das Wappen in seine Obhut und bewahrt es sicher auf. Es hilft den Verlassenen, das Erbe ihres Königreichs zu bewahren und in Erinnerung zu behalten.",al={"was geschieht mit dem wappen","wappen bewahren"}},{q="Wie selten sind erhaltene Relikte aus Lordaeron?",a="Erhaltene Embleme und Relikte aus der Zeit vor dem Dritten Krieg sind außerordentlich selten. Die Invasion der Geißel ließ nur wenige gegenständliche Zeugnisse Lordaerons zurück.",al={"ist das wappen selten","wie viele wappen sind übrig"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Auf dem Gehöft Bernruh bereiten Tierführer Widder für die Expedition der Allianz in Alterac vor. Sie brauchen makellose Bergleopardenbälge, um warme Sättel für die Tiere herzustellen, damit Reittiere und Reiter dem beißenden Frost der nördlichen Berge trotzen können.",h="Auf dem Gehöft Bernruh bereiten Tierführer Widder für die Expedition der Allianz in Alterac vor.",kw={"alterac","alterac-expedition","gehöft bernruh","dun morogh","leopardenbälge","never saddle on quality","makellose leopardenbälge","widder","sättel"},ang={["class:Hunter"]="Erfahrene Fährtenleser und Jäger werden gebraucht, um Dun Moroghs wildeste Bergleoparden aufzuspüren und makellose Bälge zu beschaffen.",["faction:Alliance"]="Das Gehöft Bernruh züchtet Widder, um die Streitkräfte der Allianz in Alteracs eisigen Höhen zu verstärken.",["race:Dwarf"]="Dun Moroghs zähe Bergwidder sind typische zwergische Reittiere. Ihre Züchter auf dem Gehöft Bernruh weigern sich, sie mit minderwertiger Ausrüstung auszustatten."},sec={{t="Reittiere für die Expedition",b="Die Tierführer des Gehöfts Bernruh in Dun Morogh bereiten kräftige Bergwidder für Alterac vor. Doch die Arbeit stockt: Ihnen fehlt das Material, um strapazierfähige, kältefeste Sättel für die Widder herzustellen."},{t="Wärme für die Hochpässe",b="Die Reittiere der Expedition brauchen eine dicke Isolierung, um der eisigen Kälte des Alteracgebirges standzuhalten. Jäger werden zu den östlichen Klüften geschickt, um die größten und wildesten Bergleoparden in Dun Morogh aufzuspüren und makellose Bälge zurückzubringen. Die Streitkräfte der Allianz brauchen Ausrüstung, die den Bedingungen auf den Hochpässen standhält."}},faq={{q="Was ist Never Saddle on Quality?",a="Auf dem Gehöft Bernruh in Dun Morogh braucht ein Züchter hochwertige Leopardenbälge für warme, robuste Sättel. Die Sättel sind für eine Gruppe Widder bestimmt, die als Verstärkung für die Alterac-Expedition vorbereitet wird.",al={"was ist diese quest","never saddle on quality quest","was ist never saddle on quality"}},{q="Warum werden Leopardenbälge benötigt?",a="Leopardenbälge liefern das dichte Fell, das für strapazierfähige, warme Sättel für die Reittiere der Expedition benötigt wird. Die Isolierung schützt Reiter und Tiere vor der beißenden Bergkälte Alteracs.",al={"warum leopardenbälge","wofür sind die bälge","warum makellose bälge"}},{q="Wohin werden die Widder geschickt?",a="Die Reittiere sind für die Streitkräfte der Allianz in der Alterac-Expedition bestimmt. Gut ausgerüstete Reitwidder sind bei dem rauen Wetter und den laufenden Einsätzen auf den Hochpässen eine unverzichtbare Unterstützung.",al={"wohin kommen die widder","wer bekommt die widder","verstärkung für alterac"}},{q="Welche Rolle spielt das Gehöft Bernruh dabei?",a="Das Gehöft Bernruh liegt in Dun Morogh, östlich von Kharanos. Es ist die wichtigste Zucht- und Ausbildungsstätte für zwergische Bergwidder.",al={"wo liegt das gehöft bernruh","gehöft bernruh standort"}},{q="Wo streifen die Leoparden umher?",a="Die Leoparden streifen über die verschneiten Bergrücken und durch die östlichen Klüfte Dun Moroghs, östlich des Gehöfts Bernruh. Jäger suchen dort nach den größten Tieren, um deren makellose Bälge zu erbeuten.",al={"wo leoparden finden","wo sind leoparden in dun morogh"}},{q="Warum ist Kälteschutz für die Expedition so wichtig?",a="Alteracs Königreich und Gipfel sind eisig und windgepeitscht. Ohne dickes, hochwertiges Sattelmaterial drohen Reittieren und Reitern in den Bergen Erfrierungen und Erschöpfung.",al={"ist alterac kalt","warum warme sättel"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Gestohlenes Sprengpulver",s="Nahe dem Steinbruch Gol'Bolar ist bei Troggs ein leeres Fass für gefährliches Sprengpulver aufgetaucht. Seine Rückgabe an Steinbruchmeister Thesten offenbart eine Sicherheitslücke im Steinbruch und seinen Sprengstofflagern.",h="Nahe dem Steinbruch Gol'Bolar ist bei Troggs ein leeres Fass für gefährliches Sprengpulver aufgetaucht.",kw={"sprengpulver","dun morogh","leeres pulverfass","steinbruch gol'bolar","pulverfass","steinbruchmeister thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Für die Allianz ist es entscheidend, Dun Moroghs Nachschubwege und Bergbauaußenposten vor Troggangriffen zu sichern, um Einsätze in ganz Khaz Modan zu ermöglichen.",["profession:Engineering"]="Sprengpulver ist leicht entzündlich und gefährlich. Als Ingenieur wisst Ihr, welche Verwüstung Troggs mit nicht genehmigtem Sprengstoff anrichten könnten.",["profession:Mining"]="Die Arbeit im Steinbruch ist auf kontrollierte Sprengungen angewiesen, um Stein zu gewinnen. Fehlende Pulverfässer weisen auf große Gefahr in den Abbaugruben hin.",["race:Dwarf"]="Der Steinbruch Gol'Bolar liefert Stein und Rohstoffe, die für Eisenschmiede lebenswichtig sind. Für einen Zwerg ist die Sicherung des dortigen Bergbausprengstoffs ein dringendes Anliegen."},sec={{t="Eine gefährliche Entdeckung",b="Im Steinbruch Gol'Bolar zeigt ein Warnhinweis auf einem leeren Fass, dass gefährliches Sprengpulver in unbefugte Hände geraten ist. Der Sprengstoff ist kontrollierten Abbauarbeiten mit ausdrücklicher Genehmigung des Steinbruchmeisters vorbehalten. Das Fass wurde bei feindseligen Troggs gefunden, was auf eine Bedrohung hindeutet, die über gewöhnliche Schwierigkeiten für die Bergleute hinausgeht."},{t="Die Sorge des Steinbruchmeisters",b="Als das leere Fass Steinbruchmeister Thesten erreicht, bestätigen sich die schlimmsten Befürchtungen der zwergischen Aufseher. Thesten erblasst: Das Sprengpulver ist verschwunden, und unterirdische Troggs, die in der Gegend wimmeln, haben es in Händen gehabt. Nun muss die Steinbruchleitung herausfinden, was die Kreaturen als Nächstes sprengen wollen."}},faq={{q="Was ist Stolen Blasting Powder?",a="Stolen Blasting Powder handelt von einem leeren Fass mit aufgestempelten Gefahrenhinweisen, das bei Troggs nahe dem Steinbruch Gol'Bolar gefunden wurde. Es macht Steinbruchmeister Thesten auf den Diebstahl leicht entzündlicher Bergbauvorräte aufmerksam.",al={"was ist stolen blasting powder","pulverfass quest","leeres pulverfass hintergrund"}},{q="Wer soll das leere Pulverfass erhalten?",a="Bringt das leere Pulverfass direkt zu Steinbruchmeister Thesten, der die Arbeiten im Steinbruch Gol'Bolar in Dun Morogh beaufsichtigt.",al={"wohin das fass bringen","wer ist thesten","steinbruchmeister standort"}},{q="Warum ist das gestohlene Sprengpulver gefährlich?",a="Das Fass trägt Warnhinweise zur erforderlichen Genehmigung des Steinbruchmeisters und enthielt gefährliches Sprengpulver. Troggs mit schwerem Sprengstoff bedrohen die Abbauarbeiten im Steinbruch und die nahe gelegenen Siedlungen.",al={"warum ist pulver gefährlich","troggs mit sprengstoff","warum haben troggs pulver"}},{q="Was ist der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar ist eine zwergische Abbaustätte in Dun Morogh, die Stein und Mineralien für Eisenschmiede fördert.",al={"wo ist gol bolar","steinbruch standort","golbolar dun morogh"}},{q="Warum erblasst Steinbruchmeister Thesten?",a="Steinbruchmeister Thesten erblasst beim Anblick des leeren Fasses und fragt, wo es gefunden wurde. Er weiß, dass sein gefährlicher Inhalt bereits in die Hände feindseliger Troggs gefallen ist.",al={"warum erblasst thesten","thestens reaktion","was sagt thesten"}},{q="Was treiben Troggs nahe dem Steinbruch Gol'Bolar?",a="Troggs haben die tieferen Bereiche und die Randgebiete des Steinbruchs Gol'Bolar befallen. Sie behindern die zwergischen Bergleute und plündern Ausrüstung und Sprengpulver von der Abbaustätte.",al={"sind troggs im steinbruch","troggbefall dun morogh","warum nehmen troggs pulver"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Gestohlenes Sprengpulver",s="Im Steinbruch Gol'Bolar ist Stolen Blasting Powder mit den Troggs nach Osten verschwunden. Quarrymaster Thesten braucht Hilfe, um die vermisste Munition zurückzuholen, bevor die Unholde sie versehentlich zünden.",h="Im Steinbruch Gol'Bolar ist Stolen Blasting Powder mit den Troggs nach Osten verschwunden.",kw={"sprengpulver","dun morogh","sprengstoff","steinbruch gol'bolar","eisenschmiede","könig magni","quarrymaster thesten","thesten","troggs"},ang={["faction:Alliance"]="Dun Moroghs Versorgungswege und Steinbrüche sind für die Bergfestung der Allianz von Bedeutung. Gefährliche Munition zu bewachen hilft, den nahen High Seat in Eisenschmiede zu schützen.",["profession:Mining"]="Sprengpulver räumt Gestein aus dem Weg und legt Adern in tiefen Grabungen frei, doch der Umgang damit verlangt Disziplin. Große Pulverfässer an wilde Höhlenbewohner zu verlieren, ist der Albtraum jedes Steinbruchmeisters.",["race:Dwarf"]="Der Steinbruch Gol'Bolar unterstützt Eisenschmiedes Steinmetzkunst und Grabungsarbeiten. Troggs so nahe vor König Magnis Haustür Bergbausprengstoff als Waffe nutzen zu lassen, ist ein demütigendes Versagen für einen zwergischen Aufseher."},sec={{t="Ein verschwundener Vorrat",b="Im Steinbruch Gol'Bolar in Dun Morogh nutzen Zwerge schwere Sprengladungen, um Gestein zu brechen und tiefe Adern freizulegen. Doch primitive Troggs aus den nahen Felsen haben eine Großlieferung hochwertigen Sprengpulvers gestohlen. Quarrymaster Thesten braucht fähige Hände, bevor die Bande eine versehentliche Explosion auslöst."},{t="Ein Pulverfass in den Felsen",b="Das vermisste Fass birgt genug Sprengkraft, um König Magni Bronzebarts prächtigen Thronsaal in einen offenen Innenhof zu verwandeln. Die Troggs brachten das Pulver nach Osten in ihre primitiven Lager in den Ausläufern der Hügel. Sich selbst überlassen, könnten sie bald das Feuer entdecken oder Stein gegen Funken schlagen."},{t="Eine diskrete Lösung",b="Sobald die gestohlenen Sprengladungen von den Troggs zurückgeholt und ins Steinbruchlager gebracht wurden, kann Quarrymaster Thesten aufatmen. Er belohnt Euch und bittet Euch dann leise, niemandem von dem Vorfall zu erzählen."}},faq={{q="Wer ist Quarrymaster Thesten?",a="Quarrymaster Thesten leitet die Grabungen im Steinbruch Gol'Bolar in Dun Morogh. Nachdem unter seiner Aufsicht ein großer Vorrat industriellen Sprengpulvers verschwunden ist, braucht er Hilfe, um ihn zurückzuholen.",al={"wer ist thesten","quarrymaster thesten","wer vergibt diese quest"}},{q="Wo ist das gestohlene Sprengpulver zu finden?",a="Die Troggs haben das Pulver zu den Felsen und Höhlen unmittelbar östlich des Steinbruchs Gol'Bolar gebracht. Ihr werdet losgeschickt, um die hochexplosiven Fässer und Säcke zurückzuholen, bevor eine Katastrophe geschieht.",al={"wo ist stolen blasting powder","troggs fundort","pulver fundort"}},{q="Warum haben die Troggs das Sprengpulver gestohlen?",a="Der Eintrag nennt keinen Grund für den Diebstahl der Troggs. Sie ließen die Pulverfässer bei den Steinbrucharbeitern mitgehen, und Quarrymaster Thesten fürchtet, dass sie den Sprengstoff bei ungeschickten Experimenten entzünden könnten.",al={"warum stehlen troggs pulver","was wollen troggs mit pulver"}},{q="Wie gefährlich ist das gestohlene Sprengpulver?",a="Quarrymaster Thesten sagt, das vermisste Fass könnte König Magnis Thronsaal in einen offenen Innenhof sprengen. Sollte es im umschlossenen Steinbruch oder in den Höhlen explodieren, wäre die Wucht verheerend.",al={"wie stark ist das pulver","magni thronsaal pulver","ist das pulver gefährlich"}},{q="Warum will Quarrymaster Thesten den Vorfall geheim halten?",a="Wenn Ihr das Pulver zurückbringt, bezahlt Euch Quarrymaster Thesten und bittet Euch, den Vorfall geheim zu halten. Er nennt keinen Grund, doch dass so viel Sprengstoff an die Troggs verloren ging, würde er lieber verheimlichen.",al={"warum geheim halten","thesten geheimnis","vorfall nicht erwähnen"}},{q="Was ist der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar ist eine zwergische Ausgrabungsstätte im Osten von Dun Morogh. Er liefert Stein für Bauvorhaben und Ingenieursarbeiten im ganzen Reich, während Troggs aus dem Gestein in seine tiefen Gruben vordringen.",al={"was ist gol'bolar","steinbruch gol'bolar","wo ist gol'bolar"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="In Unterstadt studiert Theodore Griffs Berichte über eine tödliche Kreatur in den Ruinen darüber. Ihr Gift zersetzt selbst untotes Fleisch, und er will herausfinden, wie ihre Toxine wirken.",h="In Unterstadt studiert Theodore Griffs Berichte über eine tödliche Kreatur in den Ruinen darüber.",kw={"das apothekarium","ichor","ruinen von lordaeron","the new plague","theodore griffs","giftiger erregerstamm","unterstadt","witherfang"},ang={["faction:Horde"]="Die Horde akzeptiert die Verlassenen als Verbündete in den Östlichen Königreichen, doch die düsteren Experimente des Apothekariums beunruhigen oft ihre ehrenhafteren Mitglieder.",["race:Undead"]="Die Royal Apothecary Society sucht nach Toxinen, die Lebenden und Toten schaden können. Sie strebt nach der Vorherrschaft der Verlassenen und dem Schutz ihrer jungen Nation."},sec={{t="Der Ehrgeiz des Apothekers",b="Die Royal Apothecary Society sammelt gefährliche Substanzen aus ganz Azeroth. Theodore Griffs ist einer ihrer Forscher. Er spürt seltsame Bestien und tödliche Schadstoffe auf, um die Alchemie der Verlassenen voranzutreiben. Nun berichten Gerüchte von einer giftigen Kreatur im zerborstenen Gestein darüber, also schickt Griffs Euch los, eine Probe zu beschaffen, bevor die Gelegenheit verstreicht."},{t="Ein fleischzersetzendes Toxin",b="Witherfang ist der giftige Arthropode, der durch die oberirdischen Ruinen von Lordaeron streift. Sein Gift zersetzt lebendes Gewebe ebenso wie totes, konserviertes Fleisch. Griffs will herausfinden, wie es die Widerstandskraft toten Fleisches überwindet, denn dieses Wissen könnte helfen, biologische Waffen zu verfeinern und das Königreich der Verlassenen zu schützen."},{t="Nachkonstruktion des Ichors",b="Theodore Griffs ist frustriert, dass Witherfang getötet statt lebend gefangen wurde. Dennoch liefert ihm das gesammelte Ichor genug Material für seine Forschung. Durch die Analyse der Körperflüssigkeiten der Kreatur hofft er zu verstehen, wie ihr Gift wirkt, und das wachsende chemische Wissen von Unterstadt zu erweitern."}},faq={{q="Wer ist Theodore Griffs?",a="Theodore Griffs ist ein Forscher der Royal Apothecary Society im Apothekarium von Unterstadt. Er untersucht starke Toxine und seltsame Exemplare, um Verbindungen für die Verlassenen herzustellen, und hat wenig Geduld mit jenen, die sorgfältige alchemistische Arbeit nicht schätzen.",al={"wer vergibt the new plague","theodore griffs","wer ist theodore griffs"}},{q="Was ist Witherfang?",a="Witherfang ist ein giftiger Arthropode in den Ruinen von Lordaeron über Unterstadt. Sein Toxin kann selbst widerstandsfähiges untotes Fleisch auflösen.",al={"was ist witherfang","wo ist witherfang","arthropode in den ruinen von lordaeron"}},{q="Warum will Theodore Griffs Witherfangs Gift?",a="Theodore Griffs will herausfinden, wie sich Witherfangs Gift durch untotes Fleisch frisst. Er hofft, seine Wirkung für das alchemistische Arsenal der Verlassenen nachzubilden.",al={"was will theodore mit witherfang","warum den hochgiftigen erregerstamm sammeln"}},{q="Warum ist Theodore Griffs bei Eurer Rückkehr verärgert?",a="Theodore Griffs hatte gehofft, Ihr würdet Witherfang unversehrt lassen oder sein Gift sorgfältig sammeln. Er ist verärgert, dass die Kreatur getötet wurde, konnte aber genug Ichor aus ihren Überresten für seine Forschung gewinnen.",al={"warum war theodore wütend","habe ich die probe ruiniert"}},{q="Welchem Zweck dient das Apothekarium?",a="Das Apothekarium ist das Forschungszentrum der Royal Apothecary Society unter Lordaeron. Dort testen ihre Mitglieder gefährliche Erregerstämme, stellen alchemistische Waffen her und experimentieren an seltsamen Kreaturen. Es ist das wichtigste Viertel von Unterstadt.",al={"zweck des apothekariums","warum ist das apothekarium wichtig"}},{q="Wie lassen sich virulente Erregerstämme nach Theodores Ansicht am besten übertragen?",a="Theodore Griffs glaubt, dass sich ein starker Erregerstamm am zuverlässigsten verbreiten lässt, indem man ihn direkt in die Blutbahn einbringt.",al={"wie wird das gift übertragen","übertragungsmethode"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="Im Steinbruch braucht The Quarry's Smith, Frast Dokner, Metall und Leder für Reparaturen im Lager. Da eine Nachschublieferung verspätet ist, bittet er Reisende, die Materialien zu beschaffen. Im Gegenzug bietet Dokner praktische Schmiedetechniken an.",h="Im Steinbruch braucht The Quarry's Smith, Frast Dokner, Metall und Leder für Reparaturen im Lager.",kw={"schmiedekunst","kupferbarren","dun morogh","zwerg","frast dokner","steinbruch gol'bolar","eisenschmiede","the quarry's smith","gehärtete eberhäute"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, den abgelegenen zwergischen Steinbruch im verschneiten Hochland am Laufen und seine Ausrüstung einsatzbereit zu halten.",["profession:Blacksmithing"]="Als Schmied könnt Ihr von Frast Dokner lernen, einem Lehrmeister für Schmiedelehrlinge im Felde. Er gibt seine mühsam erlernten Schmiedetechniken an jeden weiter, der das Rohmetall und Leder liefert, die seinen Amboss heiß halten.",["profession:Mining"]="Als Bergmann, der die umliegenden Vorkommen abbaut, habt Ihr einen Abnehmer für Eure verhütteten Kupferbarren ganz in der Nähe. Sie dienen der praktischen Ausbildung und Reparaturen im Lager.",["race:Dwarf"]="Als Zwerg könnt Ihr im Steinbruch Gol'Bolar das Handwerk des Bronzebeard-Klans erleben, wo zwergische Entschlossenheit die Schmiedefeuer am Brennen hält, wenn Nachschubkarawanen sich verspäten."},sec={{t="Engpässe im Steinbruch",b="Eine Ausgrabung braucht ständige Pflege. Spitzhacken müssen geschärft, verschlissene Halterungen ersetzt und Lagerausrüstung verstärkt werden. Wenn eine unverzichtbare Lieferung nicht rechtzeitig eintrifft, kommt die Arbeit allmählich zum Erliegen. Ohne frischen Nachschub über die großen Handelsstraßen müssen die Handwerker improvisieren und durchreisende Reisende um Hilfe bitten.\n\nFrast Dokner arbeitet trotz dieser Verzögerungen an der Schmiede. Er bittet alle, die einfache Metalle und Häute sammeln wollen, dabei zu helfen, das Lager am Laufen zu halten, statt auf womöglich stark verspätete Transportwagen zu warten."},{t="Ein Handel für Lehrlinge",b="Zwergische Schmiedegilden schätzen Disziplin und hüten ihre Methoden, und nur selten teilen sie Berufsgeheimnisse mit zufälligen Wanderern. Dokner wägt diesen Brauch gegen die unmittelbaren Bedürfnisse des Lagers ab. Ihm fehlen verarbeitbares Kupfer und strapazierfähiges Leder zum Ausbessern von Werkzeugen und Lagerausrüstung.\n\nBringt die Rohstoffe zu seinem Amboss, und er wird Euch seine persönlichen Schmiedetechniken beibringen. Bei diesem Handel wird nützliches Handwerkswissen gegen Materialien getauscht, die das Lager zum Fortbestehen und zur Instandhaltung seiner Ausrüstung braucht."}},faq={{q="Wer ist Frast Dokner?",a="Frast Dokner ist ein erfahrener Schmied in einem Steinbruchlager. Er hält Werkzeuge, Baubeschläge und Ausrüstung für die dortigen Arbeiter instand. Wenn Verzögerungen seinen regelmäßigen Nachschub unterbrechen, bittet er durchreisende Reisende, die benötigten Rohstoffe zu sammeln.",al={"frast dokner hintergrundgeschichte","wer ist der steinbruchschmied","steinbruchschmied"}},{q="Warum braucht der Steinbruch Kupferbarren und Eberhäute?",a="Die Arbeit im Steinbruch und die Instandhaltung des Lagers verbrauchen große Mengen robuster Materialien. Kupfer ist ein leicht verfügbares, gut verarbeitbares Metall für Ersatzbeschläge, Nägel, Befestigungen und Bänder, die zerbrochene Werkzeuge verstärken. Eberhäute liefern zähes Leder für Blasebälge, Werkzeugumwicklungen, Riemen und Schürzen zum Schutz vor Funken und der zermürbenden Arbeit.",al={"warum kupferbarren und eberhäute","benötigte materialien steinbruchschmied","reparaturmaterialien steinbruch"}},{q="Warum ist die Nachschublieferung verspätet?",a="Frast Dokner erklärt nicht, warum die Lieferung verspätet ist. Überlandrouten über verschneite Felsgrate und Gebirgspässe sind oft Schneestürmen, umherstreifenden Wildtieren und Überfällen feindlicher Troggs oder Banditen ausgesetzt. Abgelegene Bergbaulager und Steinbrüche spüren die Folgen zuerst, wenn Transportwagen sich verspäten.",al={"verspätete nachschublieferung","was ist mit den vorräten passiert","warum verspätet sich der nachschub"}},{q="Was bietet Frast Dokner im Tausch gegen die Materialien an?",a="Frast Dokner bietet mehr als Münzen: Er verspricht, jedem seine persönlichen Schmiedetechniken beizubringen, der die benötigten Vorräte sammelt. Angehende Handwerker können bei einem erfahrenen Handwerker im Felde praktische Metallbearbeitung und Ausrüstungspflege lernen, wie sie städtische Gildenhallen Neulingen nur selten vermitteln.",al={"steinbruchschmied belohnung hintergrundgeschichte","was lehrt frast","schmiedetechniken frast"}},{q="Wo liegt dieser Steinbruch?",a="Frast Dokner arbeitet im Steinbruch Gol'Bolar in Dun Morogh, südlich von Kharanos. Die zwergische Ausgrabungsstätte liegt in verschneiten Vorbergen und ist hartem Winterwetter und aggressiven unterirdischen Troggs ausgesetzt, die Bergleute bedrängen und Handelskonvois aus Eisenschmiede stören.",al={"welcher steinbruch ist das","wo ist frast dokner","steinbruchschmied standort"}},{q="Gehört Frast Dokner zu Eisenschmiede?",a="Frast Dokner und das Steinbruchlager unterstehen dem Bronzebeard-Klan und dem Königreich Eisenschmiede. Steinabbau und Erzbergbau in Dun Morogh unterstützen die Bauvorhaben und Verteidigungsanlagen des Königreichs. Schmiede wie Dokner helfen, Eisenschmiedes Industrie am Laufen zu halten.",al={"frast dokner eisenschmiede","gehört der steinbruch zu eisenschmiede","steinbruch zwerg zugehörigkeit"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95219"] = {n="From Port to Port",s="Ein Hafenverkäufer schickt Euch mit einem sorgfältig verpackten Fass zur Mondfederfeste. Die lange Reise erfordert Vorsicht.",h="Ein Hafenverkäufer schickt Euch mit einem sorgfältig verpackten Fass zur Mondfederfeste.",kw={"fass","lieferung","mondfederfeste","feralas","von hafen zu hafen","mardrack greenwell","hafen von powderfuse"},sec={{t="Ein ferner Kunde",b="Ein Verkäufer hat einen Kunden in der Mondfederfeste in Feralas, und Ihr bringt ihm ein Fass Hafen von Powderfuse. Der Verkäufer sagt, es sei luftdicht verpackt, warnt aber, dass etwas es zur Explosion bringen könnte. Behandelt das Fass auf dem Weg zu Mardrack Greenwell vorsichtig."}},faq={{q="Was liefere ich aus?",a="Ihr bringt ein Fass Hafen von Powderfuse zu Mardrack Greenwell in der Mondfederfeste.",al={"was ist im fass","lieferung von powderfuse port","hafenfass"}},{q="Wohin bringe ich das Fass?",a="Das Fass ist für Mardrack Greenwell in der Mondfederfeste in Feralas bestimmt.",al={"wohin damit","lieferung zur mondfederfeste","fass in feralas"}},{q="Warum soll ich vorsichtig damit umgehen?",a="Der Verkäufer warnt, dass etwas das luftdicht verpackte Fass zur Explosion bringen könnte.",al={"ist das fass gefährlich","warum vorsichtig","was könnte es zur explosion bringen"}},{q="Wer hat das Fass verpackt?",a="Einer der Männer des Verkäufers hat das Fass luftdicht verpackt.",al={"wer hat den hafenwein verpackt","luftdichte verpackung","mann des verkäufers"}}},fp="17,112,18.250.0,21.91.0,27.78.0,33.71.0,20.49.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="An Lordaerons gefallener Hauptstadt wartet Captain Truman besorgt auf Verstärkung und Nachricht von seinem vermissten Kommandanten. Er glaubt, der verehrte Großmarschall kämpfe noch in den nahen Ruinen, und bittet einen fähigen Reisenden, ihn zu finden. Die Suche offenbart das grausame Schicksal der Verteidiger und die tiefe Feindseligkeit unter den Loyalisten.",h="An Lordaerons gefallener Hauptstadt wartet Captain Truman besorgt auf Verstärkung und Nachricht von seinem...",kw={"abominable creatures","captain truman","großmarschall","kopf des barons","lordaeron","ruinen von lordaeron","der baron","wahre söhne lordaerons"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie gefährdet und isoliert die verbliebenen Loyalisten in den verseuchten Ruinen im Norden Lordaerons sind. Ihre Trupps kämpfen mit schwindender Hoffnung und der Belastung durch den Kampf gegen überwältigende Monstrositäten.",["race:Human"]="Als Mensch seht Ihr, wie Lordaerons gefallene Führung ein grausames Schicksal ereilt: Selbst ein angesehener Großmarschall ist zu einem grotesken untoten Schrecken geworden. Captain Trumans Trauer und nationalistischer Eifer spiegeln das Trauma menschlicher Überlebender wider, die verzweifelt ihre angestammte Heimat zurückerobern wollen.",["race:Undead"]="Als Verlassene seht Ihr in der grotesken Verwandlung des Barons eine Erinnerung daran, wie die Geißel Lordaerons beste Verteidiger zu monströsen Abscheulichkeiten verstümmelte. Captain Trumans Worte offenbaren die Feindseligkeit der lebenden Loyalisten gegenüber den Bewohnern von Unterstadt."},sec={{t="Verzweifeltes Wachen",b="Captain Truman hält vor Lordaeron Wache und wartet besorgt auf längst überfällige Verstärkung. Er beschreibt seinen Vorgesetzten als berühmten Großmarschall, hochgewachsen und stattlich, und hält ihn für einen beeindruckenden Kämpfer. Truman erhielt den Befehl, die Stellung zu halten, während sein Kommandant in die Schlacht stürmte, und bleibt seiner Pflicht verbunden.\n\nEr misstraut Außenstehenden und verachtet jene, die er minderwertige Rassen nennt, und weigert sich, auf örtliche Freischärler zu vertrauen. Als ein fähiger Reisender eintrifft, bittet er Euch, die Ruinen zu betreten, nach dem Wohlergehen seines Herrn zu sehen und den Schlachtverlauf zu erkunden."},{t="Die Ruinen von Lordaeron",b="Die Suche führt Euch in die Ruinen von Lordaeron, die zerstörte Hauptstadt, die während des Dritten Krieges an die Geißel fiel. Captain Truman erwartet, dass sein ruhmreicher Anführer triumphierend über den Gefallenen steht, doch die verseuchte Stadt erzählt eine düsterere Geschichte.\n\nSchrecken, verbliebene Untote und Abscheulichkeiten streifen über ihre zertrümmerten Steinplätze. Die verwüsteten Straßen zeigen, was aus den Verteidigern wurde, die in die Stadt zogen. Kein makelloser Ritter hält die Stellung; der Kommandant fand unter den Monstrositäten in den Höfen ein tragisches, entstelltes Ende."},{t="Eine entsetzliche Enthüllung",b="Der vermisste Kommandant, den Captain Truman den Baron nennt, ist zu einer grotesken untoten Monstrosität geworden. Ihr erschlagt die Kreatur und bringt den Kopf des Barons zu Captain Truman zurück. Der abgetrennte Kopf seines einstigen Herrn lässt Truman erschüttert und entsetzt zurück, von Abscheu überwältigt.\n\nUnfähig, das Schicksal seines Kommandanten zu akzeptieren, wendet er sich in bitterer Empörung gegen Euch und beschuldigt Euch, auf der Seite der Monster zu stehen. Er erklärt, die wahren Söhne Lordaerons würden ihr Land zurückerobern und von allen Bestien säubern."}},faq={{q="Wer vergibt die Quest Abominable Creatures?",a="Captain Truman, ein menschlicher Loyalist, äußert die Bitte von seinem Posten vor dem gefallenen Königreich aus. Er wartet besorgt auf Verstärkung und Nachricht von seinem Kommandanten, einem verehrten Großmarschall, der in die nahen Ruinen von Lordaeron stürmte.",al={"wer vergibt abominable creatures","abominable creatures questgeber","wo beginnt abominable creatures"}},{q="Wo spielt die Quest Abominable Creatures?",a="Die Suche führt Euch in die Ruinen von Lordaeron, die zerstörte Hauptstadt, die von Schrecken der Geißel und verbliebenen Untoten überrannt wurde. Captain Truman hält vor der verseuchten Stadt Wache und bittet Reisende, dort seinen vermissten Vorgesetzten zu finden.",al={"abominable creatures ort","wo wird abominable creatures abgeschlossen","abominable creatures gebiet"}},{q="Wer ist Captain Trumans Herr?",a="Captain Truman nennt seinen Herrn den Großmarschall und preist ihn als hochgewachsenen, stattlichen Kriegshelden. Der Vermisste wird auch der Baron genannt, ein hochrangiger Adeliger und Heerführer, der die Verteidigung des Reiches anführt.",al={"wer ist trumans kommandant","großmarschall identität truman","wer ist der baron"}},{q="Was geschah mit dem Großmarschall in den Ruinen von Lordaeron?",a="Der Großmarschall wurde in den Ruinen von Lordaeron getötet und in eine monströse untote Kreatur verwandelt. Ihr findet eine Abscheulichkeit namens Baron, erschlagt ihn und nehmt seinen abgetrennten Kopf mit.",al={"was geschah mit dem baron","großmarschall schicksal","ist der großmarschall tot"}},{q="Warum wird Captain Truman wütend, wenn Ihr die Quest abgebt?",a="Captain Truman erwartet, dass sein stattlicher Kommandant lebt und siegreich ist. Der groteske, entstellte Kopf des Barons erfüllt ihn mit Entsetzen und Abscheu. Wütend beschuldigt er Euch, einen kranken Scherz zu treiben und mit abscheulichen Bestien zu verkehren.",al={"warum ist truman wütend","truman reaktion abominable creatures","warum schreit truman reisende an"}},{q="Was meint Captain Truman mit den „wahren Söhnen Lordaerons“?",a="Mit den „wahren Söhnen Lordaerons“ meint Captain Truman die rechtmäßigen menschlichen Überlebenden, die ihre verwüstete Heimat zurückerobern und von allen Bestien säubern wollen. Der Ausdruck offenbart seinen Glauben, dass das Land diesen menschlichen Überlebenden gehört.",al={"wahre söhne lordaerons bedeutung","wer sind die wahren söhne lordaerons","truman wahre söhne"}},{q="Warum weigert sich Captain Truman, „Mischlingen“ zu vertrauen?",a="Captain Truman misstraut nichtmenschlichen Völkern und irregulären Verbündeten und nennt sie unzuverlässige Mischlinge und Abschaum. Seine Verachtung hindert ihn daran, sich jemandem anzuvertrauen, den er nicht für einen würdigen Vertreter des Reiches hält.",al={"truman mischlinge","warum ist captain truman rassistisch","truman fremdenfeindlichkeit"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz will Trapclaws Schere, denn die riesige Krabbe stiehlt unter den Docks Köder und durchtrennt Angelschnüre. Bringt sie ihm, verspricht er Euch eine Mahlzeit mit seiner geheimen Gewürzmischung.",h="Fimbo Greasemitz will Trapclaws Schere, denn die riesige Krabbe stiehlt unter den Docks Köder und durchtrennt...",kw={"köder","krabbe","krabbenfleisch","docks","fimbo greasemitz","angelschnüre","schere","trapclaw"},sec={{t="Unter den Docks",b="Fimbo Greasemitz möchte Krabbenfleisch, und Trapclaw kriecht unter den Docks umher. Die große Krabbe stiehlt Köder und durchtrennt Angelschnüre. Fimbo bittet Euch, ihm Trapclaws Schere zu bringen, die er für eine Mahlzeit verwenden will."}},faq={{q="Wer möchte Trapclaws Schere haben?",a="Fimbo Greasemitz möchte Trapclaws Schere wegen des Krabbenfleischs.",al={"wer möchte die schere","fimbo greasemitz bitte"}},{q="Was tut Trapclaw?",a="Trapclaw kriecht unter den Docks umher, stiehlt Köder und durchtrennt Angelschnüre.",al={"warum trapclaw","krabbe unter den docks"}},{q="Warum möchte Fimbo die Schere?",a="Fimbo möchte Krabbenfleisch und bittet Euch um Trapclaws Schere.",al={"wofür ist die schere","bitte um krabbenfleisch"}},{q="Was verspricht Fimbo zuzubereiten?",a="Fimbo sagt, er werde ein Gericht mit Butter und seiner geheimen Gewürzmischung zubereiten.",al={"welche mahlzeit","fimbos gericht"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:95260"] = {n="Terrors From the Deep",s="Im Hafen von Powderfuse sucht Ihr einen Seemann, der ein auf eine Haut gemaltes Seemonster erkennen kann. Das seltsame Bild könnte auf ein Tier in diesen Gewässern hindeuten.",h="Im Hafen von Powderfuse sucht Ihr einen Seemann, der ein auf eine Haut gemaltes Seemonster erkennen kann.",kw={"fischinnereien","bemalte haut","hafen von powderfuse","seemann","seemonster","tintenfischtinte","schrecken aus der tiefe"},sec={{t="Ein gemaltes Ungeheuer",b="Eine bemalte Haut führt Euch zum Hafen von Powderfuse, wo ein Seemann das Ungeheuer vielleicht erkennt. Fischinnereien und Tintenfisch-Tinte bilden die Gestalt eines langhalsigen Wesens, das sich aus den Wellen erhebt. Gehört es zu einem echten Ungeheuer in diesen Gewässern, könnte jemand, der hier zur See fährt, es kennen."}},faq={{q="Was ist auf die Haut gemalt?",a="Die Haut zeigt ein langhalsiges Seemonster, das sich aus den Wellen erhebt, gemalt mit Fischinnereien und Tintenfisch-Tinte.",al={"was ist auf der haut","bild eines seemonsters"}},{q="Wo kann jemand das Ungeheuer erkennen?",a="Der Hafen von Powderfuse ist der nächstgelegene Hafen, und ein Seemann dort erkennt das Wesen vielleicht.",al={"wohin soll ich gehen","seemann im hafen von powderfuse"}},{q="Ist das Seemonster echt?",a="Das Gemälde wirft die Möglichkeit auf, dass ein Seemonster in diesen Gewässern lauert, doch Ihr sucht einen Seemann, der es erkennen kann.",al={"echtes meerestier","monster echt?"}}},fp="21,143,15.242.0,28.101.0,39.83.0,24.131.0"}
P.entries["quest:95261"] = {n="It Takes Guts",s="Argo Brinewhistle bittet Euch um Bestieneingeweide und Rotflesh-Pilze als Köder für ein langhalsiges Wesen, das er nahe den Inseln gesehen hat. Er hofft, dass der Fang andere von seiner Geschichte überzeugt.",h="Argo Brinewhistle bittet Euch um Bestieneingeweide und Rotflesh-Pilze als Köder für ein langhalsiges Wesen...",kw={"argo brinewhistle","köder","bestieneingeweide","inseln","es braucht mut","langhalsiges monster","rotflesh-pilze","windstead"},sec={{t="Argos Köder",b="Argo Brinewhistle sagt, er habe bei einer Bootsfahrt ein langhalsiges Monster bei den Inseln gesehen. Er möchte, dass Ihr Bestieneingeweide und Rotflesh-Pilze als Köder sammelt. Die Pilze wachsen in einer Höhle bei Windstead, und Argo hofft, das Wesen zu fangen."}},faq={{q="Wer ist Argo Brinewhistle?",a="Argo Brinewhistle ist ein Fischer, der behauptet, bei den Inseln ein langhalsiges Monster gesehen zu haben.",al={"wer ist argo","argo der fischer","argos hintergrundgeschichte"}},{q="Was möchte Argo als Köder?",a="Argo bittet Euch, ihm Bestieneingeweide und Rotflesh-Pilze zu bringen.",al={"welchen köder braucht argo","argos eingeweide","übel riechender köder"}},{q="Wo wachsen Rotflesh-Pilze?",a="Rotflesh-Pilze wachsen in einer Höhle bei Windstead.",al={"rotflesh fundort","wo pilze wachsen","höhle bei windstead"}},{q="Warum braucht Argo den Köder?",a="Argo möchte mit dem Köder das langhalsige Wesen fangen, das er nahe den Inseln gesehen haben will.",al={"warum der köder","was fängt argo","langhalsiges monster"}},{q="Warum glaubt niemand Argo?",a="Argo sagt, die Leute würden seine Geschichte abtun, weil sie ihn für einen trinkenden Fischer halten.",al={"warum sie argo anzweifeln","argo der trunkenbold","wer glaubt argo"}}},fp="13,187,11.250.0,25.95.0,29.65.0,33.47.0,28.94.0,32.80.0"}
P.entries["quest:95262"] = {n="The Secret Prison",s="Sully bittet Euch, Alcaz Prison zu betreten und herauszufinden, was aus dem König von Sturmwind geworden ist. Sein Schicksal lastet schwer auf Sturmwind.",h="Sully bittet Euch, Alcaz Prison zu betreten und herauszufinden, was aus dem König von Sturmwind geworden ist.",kw={"alcaz","alcaz prison","könig von sturmwind","sturmwind","sully","das geheime gefängnis"},sec={{t="Eine Suche in Alcaz",b="Sully schickt Euch nach Alcaz, einem Außenposten, der seit dem Dritten Krieg als verlassen gilt. Niemand, den er kennt, hat je von einem Gefängnis dort gesprochen. Doch vielleicht ist der König von Sturmwind dort, und Sully muss wissen, was aus ihm geworden ist."},{t="Was Ihr findet",b="In Alcaz Prison erfahrt Ihr, dass der König von Sturmwind tot ist. Außerdem entdeckt Ihr, dass eine größere Macht hinter dem kleineren Drachen, den Ihr erschlagen habt, die Fäden zieht. Sully muss erfahren, was Ihr herausgefunden habt."}},faq={{q="Wohin schickt Sully mich?",a="Sully schickt Euch nach Alcaz Prison, zu einem Außenposten, der seit dem Dritten Krieg als verlassen gilt.",al={"wo soll ich hin","alcaz prison","wo ist das gefängnis"}},{q="Was soll ich herausfinden?",a="Sully möchte, dass Ihr herausfindet, was aus dem König von Sturmwind geworden ist.",al={"wonach suche ich","könig von sturmwind","den könig finden"}},{q="Was soll Alcaz sein?",a="Alcaz gilt als verlassener Außenposten aus dem Dritten Krieg.",al={"was ist alcaz","außenposten alcaz","verlassener ort"}},{q="Warum schickt Sully mich nach Alcaz?",a="Sully schickt Euch, weil der König von Sturmwind vielleicht dort ist.",al={"warum alcaz","warum dorthin gehen","sullys grund"}}},fp="17,130,17.235.0,13.198.2,25.91.0,33.62.0,29.63.0,32.77.0"}
P.entries["quest:95263"] = {n="Somber News",s="Sully McCleary erwartet Euch in den Düstermarschen mit Neuigkeiten über den König. Sein Tod hat Sturmwind erschüttert, und Sully muss erfahren, was Ihr herausgefunden habt.",h="Sully McCleary erwartet Euch in den Düstermarschen mit Neuigkeiten über den König.",kw={"düstermarschen","fluchtversuch","könig","naga","notiz","niederschmetternde nachricht","sturmwind","sully mccleary"},sec={{t="Neuigkeiten für Sully",b="In den Düstermarschen wartet Sully McCleary auf das, was Ihr herausgefunden habt. Der König ist tot, und Sturmwind steht vor einer niederschmetternden Nachricht. Ihr bringt Sully eine Notiz; während er sie liest, verdüstert sich sein Gesicht."}},faq={{q="Wer wartet auf mich?",a="Sully McCleary wartet in den Düstermarschen darauf, zu erfahren, was Ihr herausgefunden habt.",al={"wer wartet auf die neuigkeiten","wer ist sully","wohin soll ich gehen"}},{q="Was ist dem König zugestoßen?",a="Der König starb bei einem Fluchtversuch, kurz bevor die Naga angriffen.",al={"könig tot","was ist dem könig zugestoßen","wer hat den könig getötet"}},{q="Was bringe ich Sully?",a="Ihr bringt Sully eine Notiz mit dem, was Ihr herausgefunden habt.",al={"notiz für sully","was gebe ich ihm","notiz überbringen"}},{q="Wie reagiert Sully?",a="Sullys Gesicht verdüstert sich, als er die Notiz liest, und er nennt die Nachricht schrecklich.",al={"sullys reaktion","ist sully bestürzt","was sagt er"}}},fp="11,141,14.188.0,22.71.0,26.73.0,22.45.0,21.80.0"}
P.entries["quest:95264"] = {n="Shaw Needs To Know",s="Matthias Shaw braucht Euch dringend, um ihm in Sturmwind eine wichtige Nachricht zu überbringen. Er warnt, dass der Umgang damit die Bewohner der Stadt betreffen könnte.",h="Matthias Shaw braucht Euch dringend, um ihm in Sturmwind eine wichtige Nachricht zu überbringen.",kw={"matthias shaw","nachricht","geheimhaltung","si:7","sturmwind","dringende nachricht"},sec={{t="Zurück zu Shaw",b="In Sturmwind liest Matthias Shaw die Nachricht, die Ihr ihm bringt, und bittet Euch, sie für Euch zu behalten. Er sagt, sie müsse zum Wohl der Bewohner der Stadt mit Bedacht behandelt werden."}},faq={{q="Wer braucht die Nachricht?",a="Matthias Shaw in Sturmwind braucht Euch, um ihm die Nachricht zu überbringen.",al={"wem soll ich die nachricht bringen","shaw nachricht","wer ist shaw"}},{q="Warum soll ich sie für mich behalten?",a="Shaw sagt, dass es den Bewohnern von Sturmwind schlecht ergehen wird, wenn sich die Nachricht herumspricht, bevor sie bereit sind.",al={"warum geheimhaltung","es geheim halten","wem darf ich es sagen"}},{q="Was macht Shaw mit der Nachricht?",a="Shaw liest die Worte auf der Seite und sagt, dass er sich von nun an darum kümmert.",al={"was geschieht mit der nachricht","shaw liest sie","was sagt er"}},{q="Worum geht es in der Nachricht?",a="Die Nachricht wird als potenziell verheerend für Sturmwind beschrieben, doch ihr Inhalt wird hier nicht genannt.",al={"welche nachricht","was ist geschehen","was ist die katastrophe"}}},fp="18,123,12.170.0,19.59.0,29.100.0,32.69.0,23.100.0"}
P.entries["quest:95267"] = {n="The Monster Surfaces",s="Argo Brinewhistle möchte, dass Ihr mit einem Köderball ein Seeungeheuer aus den Gewässern nahe den Murlocinseln lockt. Er bittet Euch, seinen Kopf für das Boot zurückzubringen.",h="Argo Brinewhistle möchte, dass Ihr mit einem Köderball ein Seeungeheuer aus den Gewässern nahe den...",kw={"argo brinewhistle","big ball o' bait","bootsdekoration","ungeheuerkopf","murlocinseln","seeungeheuer","wrackteile"},sec={{t="Wrackteile im Wasser",b="Argo Brinewhistle weist Euch zu den Murlocinseln, wo Ihr eine Zeichnung gefunden habt. Dort markieren frische Wrackteile im Wasser die Stelle, an der Ihr den Köder auswerfen sollt. Das Seeungeheuer ist die Gefahr, die Argo hervorlocken will, und sein Kopf ist für das Boot bestimmt."}},faq={{q="Was möchte Argo, dass ich tue?",a="Argo möchte, dass Ihr nahe frischen Wrackteilen im Wasser bei den Murlocinseln den Big Ball o' Bait benutzt und ihm anschließend den Kopf des Ungeheuers bringt.",al={"argo-köderquest","seeungeheuerköder","quest das monster taucht auf"}},{q="Wo soll ich den Köder auswerfen?",a="Argo weist Euch zu frischen Wrackteilen im Wasser nahe den Murlocinseln, wo Ihr eine Zeichnung gefunden habt.",al={"wo köder auswerfen","köder bei den murlocinseln","frische wrackteile"}},{q="Warum möchte Argo den Kopf des Ungeheuers?",a="Argo möchte den Kopf der Kreatur als Dekoration für das Boot verwenden.",al={"warum der kopf des ungeheuers","bootsdekoration","kopf fürs boot"}},{q="Wie heißt der Köder?",a="Er heißt Big Ball o' Bait.",al={"großer köderball","kugel aus gedärmen","ködername"}}},fp="20,161,21.241.0,29.136.0,26.98.0,38.68.0,24.34.0"}
P.entries["quest:95278"] = {n="It Is Time, Brother...",s="Eine Botschaft muss Krom'rosh in Rog'mar erreichen, während die Gefahr wächst. Da'groshs Warnung erinnert an eine alte Hoffnung für das Dorf und die Horde.",h="Eine Botschaft muss Krom'rosh in Rog'mar erreichen, während die Gefahr wächst.",kw={"da'grosh","horde","krom'rosh","botschaft","rog'mar","dorf","warnung","krieger"},ang={["class:Warrior"]="Als Krieger werdet Ihr in Da'groshs Hoffnung erwähnt, dass die Verwandten im Dorf zu großen Kriegern der Horde werden.",["faction:Horde"]="Als Mitglied der Horde hört Ihr von Da'groshs Kindheitshoffnung, dass die Verwandten im Dorf zu Kriegern werden könnten, die ihr Volk retten."},sec={{t="Eine Warnung für Rog'mar",b="Die Bedrohung ist größer geworden als zunächst angenommen, und Rog'mar muss gewarnt werden. Ihr bringt Krom'rosh eine Botschaft, ohne unterwegs für jemanden anzuhalten."},{t="Eine alte Hoffnung",b="Da'grosh drängte einst die Verwandten im Dorf, zu großen Kriegern der Horde zu werden und ihr Volk vor Gefahren zu schützen. Krom'rosh sieht nun eine Gelegenheit, diese Hoffnung auf die Probe zu stellen."}},faq={{q="Wer muss gewarnt werden?",a="Rog'mar muss gewarnt werden, weil die Bedrohung größer ist als zunächst angenommen.",al={"wer muss gewarnt werden","wen warnen"}},{q="Wer erhält die Botschaft?",a="Krom'rosh in Rog'mar erhält die Botschaft.",al={"wem die botschaft überbringen","wer erhält den brief"}},{q="Warum kann ich unterwegs nicht anhalten?",a="Die Botschaft muss Krom'rosh erreichen, und die Warnung lautet, unterwegs für niemanden anzuhalten.",al={"warum nicht anhalten","kann nicht anhalten"}},{q="Was erzählte Da'grosh als Kind dem Dorf?",a="Da'grosh drängte die Verwandten im Dorf, zu großen Kriegern der Horde zu werden und ihr Volk vor Gefahren zu retten.",al={"da'groshs kindheit","was sagte da'grosh"}}},fp="22,132,21.159.0,11.169.1,23.72.0,25.42.0,31.90.0,46.105.0"}
P.entries["quest:95283"] = {n="The Missing Kor'kron",s="Ein Kontingent Kor'kron Elite in den Düstermarschen hat sich nicht gemeldet. Ihr sollt Nazeer Bloodspike in Brackenwall fragen, was er weiß.",h="Ein Kontingent Kor'kron Elite in den Düstermarschen hat sich nicht gemeldet.",kw={"brackenwall","meldetermin","düstermarschen","kor'kron elite","vermisste kor'kron","nazeer bloodspike","besondere mission"},sec={{t="Nachricht aus den Düstermarschen",b="Das Schweigen des Kontingents lässt seine Mission ungeklärt. In Brackenwall weiß Nazeer Bloodspike besser als jeder andere, wie es in den Düstermarschen steht. Ihr sollt herausfinden, was er Euch über die vermissten Kor'kron Elite berichten kann."}},faq={{q="Wer schickte die Kor'kron Elite in die Düstermarschen?",a="Etrigg, der Euch zu Nazeer schickt, sagt, dass seine Seite sie vor einiger Zeit auf eine besondere Mission entsandt hat.",al={"wer entsandte die kor'kron","wer schickte sie"}},{q="Warum werden die Kor'kron Elite vermisst?",a="Der vereinbarte Meldetermin ist verstrichen, und es gibt kein Lebenszeichen von ihnen.",al={"warum kor'kron vermisst","was ist ihnen zugestoßen"}},{q="Wohin wurden die Kor'kron geschickt?",a="Ein Kontingent Kor'kron Elite wurde zu einer besonderen Mission in die Düstermarschen geschickt.",al={"wo sind die kor'kron","standort der kor'kron"}},{q="Mit wem sollte ich in Brackenwall sprechen?",a="Sprecht mit Nazeer Bloodspike, einem Orc, der weiß, wie es in den Düstermarschen steht.",al={"wer ist nazeer","nazeer bloodspike"}}},fp="20,153,20.230.0,48.99.0,35.68.0,29.81.0,47.77.0"}
P.entries["quest:95284"] = {n="The Elite of the Elite",s="Ein Lieferant nahe der Küste bittet Euch, eine vermisste Truppe Kor’kron-Elitekrieger zu finden. Ihre Spur führt zur Insel Alcaz, wo etwas schiefgegangen sein könnte.",h="Ein Lieferant nahe der Küste bittet Euch, eine vermisste Truppe Kor’kron-Elitekrieger zu finden.",kw={"insel alcaz","küste","elitekrieger","insel","kor'kron","vermisste kor'kron","lieferant"},ang={["faction:Horde"]="Als Mitglied der Horde sollt Ihr eine vermisste Truppe Kor’kron-Soldaten finden."},sec={{t="Eine beunruhigende Spur",b="Vor einigen Tagen machten Kor’kron-Soldaten hier Halt, um Vorräte zu kaufen und sich auszuruhen, bevor sie weiterzogen. Der Lieferant hörte einen von ihnen von einer Insel sprechen, und Insel Alcaz liegt direkt vor der Küste. Nun sollt Ihr die vermissten Elitekrieger finden und herausfinden, was ihnen zugestoßen ist."}},faq={{q="Wer sind die vermissten Kor’kron?",a="Sie sind eine kleine Truppe Kor’kron-Soldaten, die hier Halt machte, um Vorräte zu kaufen und sich auszuruhen, bevor sie weiterzog.",al={"kor'kron-elitekrieger","vermisste soldaten","kor kron vermisst"}},{q="Wohin könnten die Kor’kron gegangen sein?",a="Einer der Soldaten erwähnte eine Insel, und der Lieferant vermutet, dass es Insel Alcaz vor der Küste ist.",al={"welche insel","kor'kron-insel","wo sind sie hingegangen"}},{q="Warum ist der Lieferant besorgt?",a="Die Kor’kron zogen nach ihrer Rast weiter, doch der Lieferant glaubt, dass etwas schiefgegangen ist.",al={"was ist schiefgegangen","warum nach kor'kron suchen","elitekrieger vermisst"}},{q="Wie ist Insel Alcaz?",a="Der Lieferant beschreibt Alcaz als einen wirklich üblen Ort.",al={"insel alcaz","ist alcaz gefährlich","üble insel"}}},fp="22,157,16.250.0,31.102.0,37.94.0,28.83.0,26.53.0"}
P.entries["quest:95285"] = {n="Right Place, Wrong Time",s="Sergeant Ulka bittet Euch, Euch über die Lage auf Alcaz Isle zu informieren. Die übrigen Missionsdetails bleiben denen vorbehalten, die sie kennen müssen.",h="Sergeant Ulka bittet Euch, Euch über die Lage auf Alcaz Isle zu informieren.",kw={"alcaz isle","einweisung","mission","richtiger ort falsche zeit","sergeant ulka","kriegshäuptling"},ang={["faction:Horde"]="Als Mitglied der Horde fragt Sergeant Ulka, ob Ihr bereit seid, Eure Pflicht gegenüber dem Kriegshäuptling zu erfüllen."},sec={{t="Ulkas Einweisung",b="Sergeant Ulka müht sich, sich aufzusetzen, als sie auf Alcaz Isle mit Euch spricht. Ihr bietet ihr eine Hand, doch sie schlägt sie weg. Sie sagt, sie werde Euch auf den neuesten Stand bringen, hält aber die übrigen Missionsdetails unter Verschluss. Eure Pflicht gegenüber dem Kriegshäuptling wartet."}},faq={{q="Wer bittet mich, mich auf den neuesten Stand zu bringen?",a="Sergeant Ulka müht sich, sich aufzusetzen, während sie mit Euch spricht.",al={"wer ist ulka","sergeant ulka"}},{q="Was geschieht auf Alcaz Isle?",a="Sergeant Ulka sagt, sie werde Euch über die Lage auf Alcaz Isle informieren.",al={"lage auf alcaz","was geht hier vor"}},{q="Warum teilt Ulka nicht alle Missionsdetails mit?",a="Sergeant Ulka sagt, die übrigen Missionsdetails sind nur für diejenigen bestimmt, die sie kennen müssen.",al={"warum vertraulich","was sind die details"}},{q="Was bittet Ulka mich zu tun?",a="Sprecht mit Sergeant Ulka, um mehr über die Lage auf Alcaz Isle zu erfahren.",al={"was soll ich tun","mit ulka sprechen"}},{q="Was fragt Ulka zu meiner Pflicht?",a="Sergeant Ulka fragt, ob Ihr bereit seid, Eure Pflicht gegenüber dem Kriegshäuptling zu erfüllen.",al={"bereit für den kriegshäuptling","frage zur pflicht"}}},fp="23,138,15.245.0,29.57.0,32.72.0,45.66.0,25.73.0,33.73.0"}
P.entries["quest:95288"] = {n="Smuggler's Paradise",s="Am Hafen von Powderfuse schickt Friz Frazzlespark Euch hinter Eastsea pirates her, die ihre gestohlenen Waren genommen haben. Sie nennt es Eure erste Lektion im Umgang mit Verrätern.",h="Am Hafen von Powderfuse schickt Friz Frazzlespark Euch hinter Eastsea pirates her, die ihre gestohlenen Waren...",kw={"eastsea-piraten","friz frazzlespark","goblin","hafen von powderfuse","geschmuggelte waren","paradies der schmuggler","gestohlene waren"},sec={{t="Friz' Lektion",b="Friz Frazzlespark am Hafen von Powderfuse möchte, dass Ihr Waren zurückholt, die Eastsea pirates genommen haben. Sie sagt, sie habe sie zuerst gestohlen, und nennt das Zurückholen Eure erste Lektion als ihre Handlangerin."},{t="Eine erste Lektion",b="Friz sagt, Ihr hättet Eure erste Lektion gut gelernt. Sie bietet Euch ihre Weisheit kostenlos an und weist Euch dann einen weiteren Auftrag zu."}},faq={{q="Wer ist Friz Frazzlespark?",a="Friz Frazzlespark ist die Goblin, die Euch bittet, ihre gestohlenen Waren von Eastsea pirates zurückzuholen.",al={"friz","wer ist friz","goblin am hafen von powderfuse"}},{q="Was haben die Eastsea-Piraten erbeutet?",a="Eastsea pirates haben eine Warenlieferung genommen, die Friz zufolge sie zuerst gestohlen hatte.",al={"waren der piraten","was wurde gestohlen","geschmuggelte waren"}},{q="Wohin sollen die Waren zurückgebracht werden?",a="Friz bittet Euch, die Waren für sie am Hafen von Powderfuse einzusammeln.",al={"wo ist friz","hafen von powderfuse","wohin mit den waren"}},{q="Warum will Friz die Waren zurück?",a="Friz sagt, Eastsea pirates hätten Waren genommen, die sie zuerst gestohlen hatte, und nennt das Zurückholen eine Lektion im Umgang mit Verrätern.",al={"warum die waren zurückholen","warum sind friz die waren wichtig","grund für den verrat"}}},fp="19,157,13.180.0,14.131.1,25.94.0,34.81.0,40.62.0,34.120.0"}
P.entries["quest:95293"] = {n="Smuggler's Special",s="Friz schickt Euch mit einer Kiste namens The Friz Special zu Captain Bentcoin an der Eastwind Shore. Die Lieferung ist ihre Antwort auf seinen Versuch, sich in ihr Revier einzumischen.",h="Friz schickt Euch mit einer Kiste namens The Friz Special zu Captain Bentcoin an der Eastwind Shore.",kw={"captain bentcoin","kiste","eastsea-piraten","eastwind shore","friz","schmugglerspezial","the friz special","handelskrieg"},sec={{t="Friz' Antwort",b="Captain Bentcoin droht Euch, als Ihr sein Schiff betretet. Friz hat Euch mit einer Kiste namens The Friz Special zum Captain an der Eastwind Shore geschickt. Ihre Waren sollten direkt zu ihr gelangen, und sie glaubt, Bentcoin wolle sich in ihr Revier einmischen. Sie nennt dies ihre zweite Lektion und präsentiert die Kiste als passende Antwort auf seine Feilscherei."},{t="Die Kiste",b="Als Bentcoin die Kiste von Friz erhält, nimmt er an, dass sie weiß, dass sie geschlagen wurde. Dann hört er ein Ticken."}},faq={{q="Wer ist Friz?",a="Friz schickte Euch mit einer Kiste namens The Friz Special zu Captain Bentcoin, nachdem für sie bestimmte Waren umgeleitet worden waren.",al={"friz","wer schickte mich","geber von friz special"}},{q="Wer ist Captain Bentcoin?",a="Captain Bentcoin ist der Captain, zu dem Friz Euch auf seinem Schiff an der Eastwind Shore schickt.",al={"bentcoin","captain typ","eastwind captain"}},{q="Was liefere ich aus?",a="Ihr tragt The Friz Special bei Euch, eine Kiste, die Friz für Captain Bentcoin angefertigt hat.",al={"friz special","die kiste","was bringe ich"}},{q="Warum schickt Friz ein Geschenk?",a="Friz sagt, Waren, die Ihr von den Eastsea-Piraten beschafft habt, hätten direkt an sie geliefert werden sollen. Sie glaubt, Bentcoin wolle sich in ihr Revier einmischen.",al={"warum bentcoin ein geschenk","friz lieferung","handelskrieg"}},{q="Wo finde ich Captain Bentcoin?",a="Captain Bentcoin befindet sich auf seinem Schiff an der Eastwind Shore.",al={"bentcoins aufenthaltsort","wo ist der captain","eastwind shore"}},{q="Was sagt Bentcoin, wenn ich ankomme?",a="Bentcoin droht Euch mit dem Kielholen, weil Ihr sein Schiff betreten habt, und verlangt einen Grund, Euch zu verschonen.",al={"bentcoins reaktion","was sagt der captain","schiff betreten"}}},fp="18,158,13.362.0,9.132.1,12.111.0,24.88.0,21.74.0,27.157.0,33.53.0,37.98.0"}
P.entries["quest:95294"] = {n="Smuggler's Bargain",s="Ein Eastsea-Pirat bietet Friz Frazzlespark einen Handel an, wenn sie ihn sein Geschäft machen lässt. Ihr überbringt ihr seine Botschaft im Hafen von Powderfuse.",h="Ein Eastsea-Pirat bietet Friz Frazzlespark einen Handel an, wenn sie ihn sein Geschäft machen lässt.",kw={"kapitän","eastsea-piraten","friz frazzlespark","goblin","pirat","hafen von powderfuse","schmugglerabkommen"},sec={{t="Das Angebot eines Kapitäns",b="Friz Frazzlespark hat die Aufmerksamkeit der Eastsea-Piraten auf sich gezogen, und einer von ihnen bietet an, seine Mannschaft von ihrem Geschäft fernzuhalten. Im Gegenzug schlägt er eine gewinnbringende Abmachung vor. Ihr überbringt Friz seine Botschaft im Hafen von Powderfuse, wo sie erfahren wird, wer das Kommando beansprucht."},{t="Friz' Lektion",b="Friz beantwortet das Angebot des Piraten mit einer Warnung vor den Folgen, sich mit ihr anzulegen. Ihre Worte lassen die Bedingungen des Handels offen."}},faq={{q="Was bietet der Pirat Friz an?",a="Ein Eastsea-Pirat bietet an, seine Mannschaft von Friz' Geschäft fernzuhalten, und schlägt eine gewinnbringende Abmachung vor.",al={"angebot des eastsea-piraten","friz' handel"}},{q="Wem soll ich Bericht erstatten?",a="Ihr kehrt zu Friz Frazzlespark im Hafen von Powderfuse zurück.",al={"wohin zurückkehren","wer erhält die botschaft"}},{q="Welche Botschaft überbringt der Kapitän?",a="Er möchte Friz wissen lassen, dass ein neuer Kapitän das Kommando übernommen hat und eine gewinnbringende Beziehung erwartet.",al={"botschaft des kapitäns","was friz sagen"}},{q="Wer ist der neue Kapitän?",a="Friz fragt, wer der Kapitän ist, doch in der Botschaft wird er nicht genannt.",al={"wer ist der kapitän","piratenboss"}}},fp="18,135,17.279.0,13.124.1,32.118.0,24.51.0,35.93.0,23.69.0"}
P.entries["quest:95295"] = {n="I Know a Guy",s="Friz schickt Euch nach Beutebucht, um ihre Kontaktperson Ruzzgot zu treffen. Er erhält Waren von den örtlichen Freibeutern und erklärt Euch, wie es weitergeht.",h="Friz schickt Euch nach Beutebucht, um ihre Kontaktperson Ruzzgot zu treffen.",kw={"beutebucht","kontakt","freibeuter","friz","waren","ich kenne jemanden","piraten","ruzzgot"},sec={{t="Ein Kontakt in Beutebucht",b="Friz sagt, ihre Kontaktperson sei Ruzzgot, der in Beutebucht wartet. Er erhält Waren von den Piraten dort, die Friz Freibeuter nennt. Findet Ruzzgot, und er erklärt Euch den Rest."}},faq={{q="Wer ist Friz' Kontakt?",a="Friz nennt Ruzzgot als seinen Kontakt in Beutebucht.",al={"friz' kontakt","wer ist ruzzgot","kontakt in beutebucht"}},{q="Wohin schickt Friz mich?",a="Friz schickt Euch nach Beutebucht, um Ruzzgot zu treffen.",al={"wohin gehen","wo ist ruzzgot","beutebucht"}},{q="Was macht Ruzzgot?",a="Ruzzgot erhält Waren von den örtlichen Piraten in Beutebucht.",al={"was macht der kontakt","ruzzgots waren","piratenbeute"}},{q="Warum nennt Friz die Piraten Freibeuter?",a="Friz sagt, manche nennen Piraten Freibeuter, und scherzt, das Wort enthalte „freie Beute“.",al={"bedeutung von freibeuter","piraten oder freibeuter","warum freibeuter"}}},fp="12,141,22.166.0,22.47.0,24.44.0,21.55.0,43.98.0"}
P.entries["quest:95296"] = {n="Shipping and Handling",s="Euer Auftraggeber bittet Euch, eine Kiste zum Dampfdruckpier zu bringen. Dort soll ein Goblin seine Abgaben zahlen.",h="Euer Auftraggeber bittet Euch, eine Kiste zum Dampfdruckpier zu bringen.",kw={"kiste","lieferung","abgaben","goblin","transport und abwicklung","dampfdruckpier","tanaris","wharfmaster steamfizzle"},sec={{t="Eine Kiste ausliefern",b="Eure Auftraggeberin verhandelt gerade in der Stadt und gibt Euch daher eine Kiste für ihren Geschäftspartner. Sie erwartet, dass Ihr ein Schiff von den Docks zum Dampfdruckpier in Tanaris nehmt. Dort müsst Ihr mit Wharfmaster Steamfizzle sprechen, denn die Abgaben eines Goblins stehen auf dem Spiel."}},faq={{q="Wer hat mir die Kiste gegeben?",a="Eure Auftraggeberin übergibt Euch die Kiste, während sie in der Stadt Verhandlungen führt.",al={"kiste ausliefern","wer hat mich geschickt","transportauftrag"}},{q="Wohin soll die Kiste gebracht werden?",a="Die Kiste ist für den Geschäftspartner Eures Auftraggebers am Dampfdruckpier in Tanaris bestimmt.",al={"zielort der kiste","wohin liefern","lieferung zum dampfdruckpier"}},{q="Mit wem soll ich am Dampfdruckpier sprechen?",a="Am Dampfdruckpier ist Wharfmaster Steamfizzle der genannte Ansprechpartner.",al={"kaiwart","steamfizzle","ansprechpartner am hafen"}},{q="Warum trage ich eine Kiste?",a="Eure Auftraggeberin bittet Euch, die Kiste auszuliefern, weil sie in der Stadt mit Verhandlungen beschäftigt ist.",al={"warum eine kiste","was ist in der kiste","grund der lieferung"}},{q="Was soll der Goblin tun?",a="Euer Auftraggeber erwartet, dass ein Goblin am Dampfdruckpier seine Abgaben zahlt.",al={"abgaben des goblins","seine abgaben zahlen","warum der goblin"}}},fp="21,105,18.256.0,22.73.0,24.81.0,41.67.0,26.84.0,34.68.0"}
P.entries["quest:953"] = {n="Der Untergang von Ameth'Aran",s="In Ameth'Aran in Dunkelküste durchsucht Ihr die Ruinen und lest ihre uralten Steintafeln für Schildwache Tysha Mondklinge. Ihre Worte berichten, wie die Stadt der Hochgeborenen bei der Zerschlagung unterging, und bewahren für den Circle of Ancients in Auberdine Geschichte, die im Krieg der Ahnen größtenteils verloren ging.",h="In Ameth'Aran in Dunkelküste durchsucht Ihr die Ruinen und lest ihre uralten Steintafeln für Schildwache...",kw={"ameth'aran","auberdine","azshara","circle of ancients","dunkelküste","hochgeborene","zerschlagung","tafeln","tysha mondklinge"},ang={["class:Mage"]="Als Magier könnt Ihr beim Lesen der Tafeln einen Einblick in die Blütezeit elfischer Zauberkunst vor der Zerschlagung gewinnen. Sie berichten auch von der Verwüstung, die folgte, als diese Macht außer Kontrolle geriet.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr den Sentinels, die Geschichte von Dunkelküste für die Nachtelfenanführer zu bewahren, die die Allianz auf Kalimdor leiten.",["race:NightElf"]="Als Nachtelf seht Ihr in den Ruinen von Ameth'Aran eine düstere Mahnung an die Hybris Eurer Vorfahren unter Königin Azshara. Ungezügelte arkane Zauberei hatte katastrophale Folgen."},sec={{t="Echos der Hochgeborenen",b="Ameth'Aran war die Heimat von Königin Azsharas elitären Zauberern, die mächtige arkane Magie beherrschten. Als der Brunnen der Ewigkeit vor zehntausend Jahren zerstört wurde, zerfiel die Stadt zu zerbrochenem Marmor und rissigen Säulen. Die Hochgeborenen, die dort starben, suchen die Ruinen noch immer als rastlose, gequälte Geister heim."},{t="Verlorene Chroniken aufspüren",b="Nur wenige schriftliche Berichte überstanden die Große Zerschlagung unbeschadet. Der Krieg der Ahnen zwang die Nachtelfen in einen Überlebenskampf, und ein Großteil ihrer Geschichte ging verloren. Schildwache Tysha Mondklinge erkundete Ameth'Aran und fand zwei große Tafeln mit eingravierten Inschriften, die Lay of Ameth'Aran und den Untergang von Ameth'Aran.\n\nGeisterhafte Erscheinungen der Hochgeborenen vertrieben Tysha aus den Ruinen. Das Lesen ihrer Inschriften kann den Gelehrten des Circle of Ancients in Auberdine die Geschichte der Katastrophe übermitteln."}},faq={{q="Was ist Ameth'Aran?",a="Ameth'Aran ist eine uralte Nachtelfenruine im Zentrum von Dunkelküste. Vor zehntausend Jahren war es eine Stadt, in der Königin Azsharas hochgeborener Adel mächtige arkane Magie beherrschte und erforschte. Die Große Zerschlagung brachte ihren Untergang.",al={"ameth'aran hintergrundgeschichte","was war ameth'aran","wer lebte in ameth'aran"}},{q="Warum gibt es Geister in Ameth'Aran?",a="Die Geister von Ameth'Aran sind die Seelen der Hochgeborenen, die dort lebten und starben. Die plötzliche Katastrophe zerstörte den Brunnen der Ewigkeit und zerriss Kalimdor, wodurch sie in ewiger Qual an die Ruinen gebunden wurden.",al={"warum gibt es geister in ameth'aran","ameth'aran geister","rastlose hochgeborene"}},{q="Wer ist Schildwache Tysha Mondklinge?",a="Schildwache Tysha Mondklinge ist eine Nachtelfenschildwache, die an der Straße in Dunkelküste stationiert ist. Sie erkundet uralte Stätten und birgt verlorene historische Aufzeichnungen für den Circle of Ancients in Auberdine.",al={"tysha mondklinge","wer vergibt der untergang von ameth'aran"}},{q="Warum möchte der Circle of Ancients die Tafeln lesen lassen?",a="Der Circle of Ancients möchte die Tafeln lesen lassen, weil die Zerstörung des Brunnens der Ewigkeit Kalimdor in gewaltige Umwälzungen stürzte. Unzählige Bibliotheken und Denkmäler wurden vernichtet, und nur wenige schriftliche Aufzeichnungen überstanden den Krieg der Ahnen. Die Tafeln bewahren seltene Berichte der Hochgeborenen, die die Zerschlagung selbst erlebten.",al={"warum die tafeln lesen","circle of ancients tafeln","lay of ameth'aran bedeutung"}},{q="Wo befinden sich die Tafeln?",a="Die Lay of Ameth'Aran und der Untergang von Ameth'Aran sind in zwei große, aufrecht stehende Steinmonumente in den verfallenen Innenhöfen von Ameth'Aran eingraviert. Die umherwandernden Geister der einstigen Stadtbewohner umgeben sie.",al={"wo sind die tafeln von ameth'aran","fundorte der tafeln","wie ameth'aran lesen"}},{q="Was geschah mit den Hochgeborenen von Ameth'Aran während der Zerschlagung?",a="Als der Brunnen der Ewigkeit auf dem Höhepunkt des Krieges der Ahnen implodierte, rissen gewaltige Erschütterungen und arkane Rückschläge Kalimdor auseinander. Ameth'Aran stürzte ein, begrub seine Bewohner und hinterließ ihre Geister in den Trümmern.",al={"wie ging ameth'aran unter","ameth'aran zerstörung"}}},fx={["4f4506ec"]={q="Warum möchte Schildwache Tysha Mondklinge, dass dies getan wird?",a="Schildwache Tysha Mondklinge wurde im Namen des Zirkels der Ältesten ausgesandt, um die alten Ruinen zu vermessen. Aufzeichnungen aus der Ära des Krieges der Ahnen und der Teilung sind aufgrund der Kataklysmen jener Zeit äußerst selten. Das Sammeln der in die Tafeln gemeißelten Geschichte ermöglicht es ihr, den Druiden und Ältesten in Auberdine einen vollständigen Bericht zu erstatten.",al={"tysha mondklinge beweggrund","warum braucht tysha das","warum ameth'aran tafeln studieren"}},["2329a43d"]={q="Warum benötigt Schildwache Tysha Mondklinge Eure Hilfe?",a="Tysha wagte sich zuvor in Ameth'Aran, um die Tafeln selbst zu untersuchen, wurde jedoch aus dem Hinterhalt angegriffen und von den rachsüchtigen Geistern der Hochelfen, die in den Ruinen spuken, vertrieben. Da sie die Inschriften unter ständigem spektralem Angriff nicht sicher selbst transkribieren konnte, benötigt sie einen fähigen Abenteurer, der in die Ruinen eindringt und den Text an ihrer Stelle entziffert.",al={"warum kann tysha die tafeln nicht lesen","warum braucht tysha mich","warum geht tysha nicht selbst"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95309"] = {n="No Orc Left Behind",s="Ihr werdet in Alcaz Prison geschickt, um Commander Folkar zu finden und zu erfahren, was unter der Festung geschieht. In den Kerkern wartet ein Heer, und man warnt Euch davor, allein zu gehen.",h="Ihr werdet in Alcaz Prison geschickt, um Commander Folkar zu finden und zu erfahren, was unter der Festung...",kw={"alcaz prison","commander folkar","kerker","festung","kor'kron","kein orc bleibt zurück","ulka"},sec={{t="Unter der Festung",b="Commander Folkar befindet sich irgendwo in den Kerkern unter der Festung, und Ihr werdet losgeschickt, um ihn zu finden. Wenn er noch lebt, sollt Ihr ihn befreien und herausfinden, was dort geschieht. Unten wartet ein Heer, deshalb warnt man Euch, dass Ihr Verbündete braucht, um zu überleben."},{t="Die Suche",b="Ulka schickte Euch los, Commander Folkar zu finden, nachdem sie eine tödliche Begegnung überlebt hatte. Folkar lobt ihren Dienst für die Kor’kron und sagt, er werde dafür sorgen, dass sie eine Beförderung im Feld erhält. Doch er sagt, der Auftrag sei noch nicht abgeschlossen, und Ihr könnt Alcaz Prison nicht verlassen."}},faq={{q="Wohin werde ich geschickt?",a="Ihr werdet nach Alcaz Prison geschickt, in die Kerker unter der Festung.",al={"wohin gehen","alcaz prison ort","unter der festung"}},{q="Wen soll ich suchen?",a="Ihr sollt Commander Folkar in Alcaz Prison suchen.",al={"wen finden","commander folkar","aufenthaltsort von folkar"}},{q="Was soll ich herausfinden?",a="Ihr sollt herausfinden, was in den Kerkern unter der Festung geschieht.",al={"was geht vor sich","herausfinden, was geschah","lage im gefängnis"}},{q="Warum werde ich gewarnt, Verbündete mitzubringen?",a="In den Kerkern wartet ein Heer, und man warnt Euch, dass Ihr dort allein nicht überleben werdet.",al={"brauche verbündete","allein gehen?","heer unten"}}},fp="18,166,14.259.0,10.253.1,22.65.0,21.53.0,28.74.0,32.88.0"}
P.entries["quest:95312"] = {n="Coming to Collect",s="Friz’ Schuldner hat ihr Geld in der Arena von Gadgetzan auf Slugjaw gesetzt und sagt, die Gewinne seien abholbereit. Ihr sollt mit Fizbuz Mithril sprechen.",h="Friz’ Schuldner hat ihr Geld in der Arena von Gadgetzan auf Slugjaw gesetzt und sagt, die Gewinne seien...",kw={"arena","zum abholen","fizbuz mithril","friz","gadgetzan","glücksspiel","slugjaw","gewinne"},sec={{t="Friz’ Geld",b="Der Spieler, der Friz Geld schuldet, sagt, er habe ihr Geld in Fizbuz’ Arena in Gadgetzan auf Slugjaw gesetzt. Er behauptet, die Wette habe gewonnen, sagt aber, er habe die Gewinne noch nicht abgeholt. Da Ihr bereits für Friz unterwegs seid, bittet er Euch, mit Fizbuz Mithril in Gadgetzan zu sprechen."}},faq={{q="Wer schuldet Friz Geld?",a="Ein Spieler schuldet Friz Geld, nachdem er es in Fizbuz’ Arena auf Slugjaw gesetzt hat.",al={"friz’ geld","friz’ schuldner","wer schuldet friz"}},{q="Warum hat er ihr Geld gesetzt?",a="Er sagt, er habe gedacht, eine Wette auf Slugjaw sei eine sichere Anlage.",al={"warum ihr geld setzen","slugjaw-wette","wette des spielers"}},{q="Wer ist Slugjaw?",a="Slugjaw ist der Arenakämpfer, auf den der Spieler in Gadgetzan gesetzt hat.",al={"slugjaw","slugjaws arena","wer ist slugjaw"}},{q="Wo sind die Gewinne?",a="Der Spieler sagt, er habe die Gewinne noch nicht abgeholt, und schickt Euch zu Fizbuz Mithril nach Gadgetzan.",al={"friz’ gewinne","geld abholen","wo ist das geld"}},{q="Mit wem soll ich in Gadgetzan sprechen?",a="Sprecht wegen der Gewinne mit Fizbuz Mithril in Gadgetzan.",al={"fizbuz","arena von gadgetzan","friz’ erledigung"}}},fp="17,158,14.268.0,20.74.0,30.61.0,15.61.0,23.107.0,35.58.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="In Brill lockt That Shadowvale Green Elixir trotz des alten Verbots Käufer an. Die abgeschieden lebenden Bewohner von Schattental brauten einst Flüsterelixier aus heimischen Kräutern, und die Geißel hinterließ das Dorf in Trümmern.",h="In Brill lockt That Shadowvale Green Elixir trotz des alten Verbots Käufer an.",kw={"apotheker","brill","carolai anise","gift","schattental","tirisfal","flüsterelixier","der flüsternde wald"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass Giftmischer und Schurken Flüsterelixier schätzten, wenn sie sich den Blicken von Lordaerons einstigen Magistraten entzogen.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass das Elixier seine Wirkkraft aus seltenen Kräutern zieht, die nur unter dem unheimlichen Blätterdach des Flüsternden Waldes wachsen.",["race:Undead"]="Als Verlassener könnt Ihr mit der Bergung von Lordaerons vergessenen Gebräuen Gewinn machen und sie für Apothekerexperimente in der noch jungen Unterstadt nutzen."},sec={{t="Ein verbotenes Gebräu",b="Bevor die Geißel kam, brauten die Bewohner von Schattental Flüsterelixier aus seltenen Kräutern, die nur in Tirisfal wachsen. Der Trank wurde im gesamten nördlichen Lordaeron bekannt. Die Hauptstadt verbot ihn, doch Mystiker, Giftmischer und Apotheker begehrten weiterhin seine ungewöhnlichen Eigenschaften und widersetzten sich königlichen Dekreten."},{t="Ruinen im Flüsternden Wald",b="Schattental liegt tief im Flüsternden Wald im Westen von Tirisfal. Seine Bewohner waren verschlossen und misstrauisch und hießen Fremde selten willkommen. Die Invasion der Geißel hinterließ die Siedlung in Trümmern, doch zwischen den Trümmern lagern noch vergessene Vorräte gereiften grünen Elixiers.\n\nCarolai Anise arbeitet von Brill aus. Die Unterwelt begehrt das Gebräu noch immer, also bezahlt sie Abenteurer, die bereit sind, der beunruhigenden Stille des Waldes zu trotzen."},{t="Der flüsternde Fluch",b="Carolai Anise tut die Gerüchte als Aberglauben ab, doch der Flüsternde Wald hat einen finsteren Ruf. Örtlichen Überlieferungen zufolge verdirbt ein uralter Fluch seinen Boden und seine Wurzeln und dringt dann in die Pflanzen ein, die Schattentals Brauer ernteten. Welche Bosheit auch immer um den verlassenen Weiler lauert, ferne Käufer gieren noch immer nach seinen in Flaschen abgefüllten Überresten."}},faq={{q="Was ist Schattental?",a="Schattental war ein abgeschiedenes Dorf tief im Flüsternden Wald im Westen von Tirisfal. Bevor die Geißel die Region überrannte, destillierten seine verschwiegenen Bewohner seltene Gebräue aus heimischen Kräutern.",al={"wo liegt schattental","wer lebte in schattental","dorf schattental"}},{q="Was ist Flüsterelixier?",a="Flüsterelixier ist ein wirkmächtiger grüner Trank, gebraut aus Kräutern, die nur in Tirisfal wachsen. Mystiker, Giftmischer und Apotheker begehrten ihn, obwohl die Hauptstadt ihn vor dem Fall Lordaerons verboten hatte.",al={"was bewirkt das elixier","geschichte des grünen elixiers aus schattental","flüsterelixier"}},{q="Wer ist Carolai Anise?",a="Carolai Anise ist eine Verlassene, die in Brill lebt. Sie vermittelt wertvolle verbotene Kuriositäten, darunter Schattentals Elixier, an Käufer im ganzen Reich.",al={"carolai anise","wer vergibt die quest that shadowvale green elixir","questgeber in brill"}},{q="Warum wurde das Elixier in der Hauptstadt verboten?",a="Ein Grund für das Verbot wird nicht genannt. Carolai sagt nur, dass die Hauptstadt das Elixier verbot, obwohl Apotheker, Mystiker und Giftmischer es begehrten. Manche machen einen Fluch im Flüsternden Wald und seinen Wurzeln verantwortlich, doch Carolai tut das als Aberglauben ab und verbindet es nie mit dem Verbot.",al={"warum war flüsterelixier verboten","ist das elixier gift"}},{q="Warum gilt der Flüsternde Wald als gefährlich?",a="Der Flüsternde Wald westlich von Todesend gilt als unheimlich und verflucht. Wer sich dorthin wagt, berichtet von tiefer Bosheit und seltsamen Erscheinungen im Wald. Gerüchten zufolge verdarb der Waldboden die dort wachsenden Kräuter.",al={"ist der flüsternde wald verflucht","geschichte des flüsternden waldes"}},{q="Wer sind die Käufer, die dieses Elixier begehren?",a="Carolai Anise sagt, dass mehrere Käufer nach erhaltenen Flaschen aus der Zeit vor dem Krieg suchen, nennt jedoch keine Namen.",al={"wer kauft das elixier","carolai anises käufer"}}},fx={["4d019fa8"]={q="Warum möchte Carolai Anise, dass das Whispering Elixir gesammelt wird?",a="Carolai Anise agiert als Beschafferin seltener Güter in Brill, und die Nachfrage nach dem illegalen Gebräu ist nie wirklich versiegt. Da zahlreiche eifrige Käufer sie zu Lieferungen drängen, lässt sich mit den Flaschen, die unter den Ruinen intakt geblieben sind, beträchtlicher Profit erzielen.",al={"warum will carolai das elixier","carolai anise beweggrund","warum whispering elixir sammeln"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="Captain Nials schickt Euch mit Schreiben für Demar Brant nach Süden zur Burg Farholde. Ein Späher meldet, dass sich jenseits des Sumpflands eine feindliche Streitmacht sammelt, nahe einer Siedlung namens Farholde.",h="Captain Nials schickt Euch mit Schreiben für Demar Brant nach Süden zur Burg Farholde.",kw={"captain nials","schreiben","demar brant","farholde","burg farholde","bericht aus den flusslanden","späher","sumpfland"},sec={{t="Bericht eines Spähers",b="Captain Nials hat erfahren, dass sich weit südlich des Sumpflands eine große feindliche Streitmacht sammelt. Dort könnte eine Siedlung namens Farholde liegen, auch wenn ihm nur ihr Name bekannt ist. Er gibt Euch Schreiben für Demar Brant, der den Trupp auf Burg Farholde an der Südostküste der Flusslande anführt."}},faq={{q="Was hat der Späher berichtet?",a="Der Späher berichtete, dass sich weit im Süden, jenseits des Sumpflands, eine große feindliche Streitmacht sammelt.",al={"bericht des spä h ers","was geschieht im süden"}},{q="Zu wem schickt mich Captain Nials?",a="Ihr sollt Captain Nials' Schreiben zu Demar Brant auf Burg Farholde bringen.",al={"wer erhält den brief","demar brant"}},{q="Wo liegt Burg Farholde?",a="Burg Farholde liegt an der Südostküste der Flusslande.",al={"wo liegt farholde","lage der burg"}},{q="Was ist Farholde?",a="Captain Nials hat von einer Siedlung namens Farholde nahe der Streitmacht gehört.",al={"siedlung farholde","was ist farholde"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95321"] = {n="Tazzik's Dues",s="Tazzik schickte Euch nach Gadgetzan, um seinen Gewinn abzuholen, doch sein Arenachampion gewann nichts. Ihr müsst Tazzik wegen der unbezahlten Schuld zur Rede stellen.",h="Tazzik schickte Euch nach Gadgetzan, um seinen Gewinn abzuholen, doch sein Arenachampion gewann nichts.",kw={"arena","friz","dampfdruckpier","tanaris","tazzik","tazziks schulden","gewinne"},sec={{t="Zurück zum Pier",b="The Collector schickt Euch zurück nach Dampfdruckpier in Tanaris. Tazziks Champion verlor schnell in der Arena, daher gibt es keine Gewinne einzusammeln. Während Ihr mit The Collector sprecht, versucht Tazzik vielleicht, ein Schiff aus dem Hafen zu erwischen."},{t="Tazziks Antwort",b="Tazzik gibt zu, dass er alles, was er besaß, auf die Kämpfe setzte, um Friz zu bezahlen, und alles verlor. Er sagt, er könne ihre Besitztümer nicht zurückgeben, und bittet Euch um Hilfe."}},faq={{q="Was ist mit Tazziks Gewinnen geschehen?",a="Tazziks Champion verlor in der Arena, und The Collector sagt, der Kampf habe keinen Kupfer eingebracht.",al={"tazziks gewinne","wo ist tazziks geld"}},{q="Wohin möchte Tazzik, dass ich gehe?",a="The Collector schickt Euch zurück nach Dampfdruckpier in Tanaris, damit Ihr Tazzik zur Rede stellt.",al={"wo tazzik finden","tazziks aufenthaltsort"}},{q="Warum sollte ich schnell zum Pier zurückkehren?",a="The Collector glaubt, Tazzik könnte versuchen, das nächste Schiff aus Dampfdruckpier zu erwischen.",al={"tazzik auf der flucht","verlässt tazzik den hafen"}},{q="Wer ist Friz?",a="Friz ist diejenige, der Tazzik Geld schuldet. Er setzte ihr Geld auf einen Kampf in der Arena von Gadgetzan, und sein Champion verlor.",al={"friz und tazzik","tazzik und friz"}}},fp="13,143,16.233.0,15.152.1,35.87.0,32.80.0,36.90.0,12.103.0"}
P.entries["quest:95327"] = {n="All's Well That Ends Well",s="Die Venture Co. hat ihren Anteil an dem Geschäft bezahlt, und Friz hat ihre Beute erhalten. Ihr kehrt zu Friz Frazzlespark am Hafen von Powderfuse zurück, während Ruzzgot auf eine weitere Lieferung wartet.",h="Die Venture Co.",kw={"abmachung","friz frazzlespark","hafen von powderfuse","flusslande","lieferung","southsea pirates","venture co."},sec={{t="Eine weitere Lieferung",b="Eine neue Lieferung ist zu Ruzzgot unterwegs, und Friz Frazzlespark wartet am Hafen von Powderfuse. Ihr kehrt in den Flusslanden zu ihr zurück, nachdem die Venture Co. dafür büßen musste und Friz ihre Beute erhalten hat. Ruzzgot nennt das Geschäft reibungslos. Nun sollen die Southsea Pirates ihm die nächste Lieferung bringen."}},faq={{q="Wer ist Friz Frazzlespark?",a="Friz Frazzlespark erwartet Euch am Hafen von Powderfuse in den Flusslanden.",al={"wer ist friz","friz frazzlespark"}},{q="Was ist mit der Venture Co. geschehen?",a="Ruzzgot sagt, dass die Venture Co. dafür büßen musste.",al={"venture-co-abmachung","was ist mit der venture co"}},{q="Hat Friz ihre Beute bekommen?",a="Ja. Ruzzgot sagt, dass Friz ihre Beute bekommt.",al={"friz’ beute","hat sie sie bekommen"}},{q="Was kommt als Nächstes?",a="Ruzzgot erwartet eine weitere Lieferung von den Southsea Pirates.",al={"nächste lieferung","southsea pirates"}}},fp="25,185,16.312.0,25.75.0,33.49.0,22.37.0,20.59.0"}
P.entries["quest:95328"] = {n="Überreste des flüsternden Schreckens",s="Unter dem Flüsternden Wald wird Whispering Horror Residue zur Untersuchung nach Unterstadt gebracht. Vater Lankester erwartet es im War Quarter.",h="Unter dem Flüsternden Wald wird Whispering Horror Residue zur Untersuchung nach Unterstadt gebracht.",kw={"vater lankester","schatten","tirisfal","unterstadt","leere","war quarter","der flüsternde wald","whispering horror residue"},ang={["class:Priest"]="Als Priester unter den Verlassenen teilt Ihr vielleicht Vater Lankesters wissenschaftliches und religiöses Interesse an Exemplaren aus der Leere. Seltsame Überreste können Studienobjekte sein, statt bloße Abscheulichkeiten.",["faction:Horde"]="Als Abenteurer der Horde bergt Ihr beunruhigende Exemplare aus verborgenen Orten in Tirisfal, damit sie unter den Ruinen der Hauptstadt untersucht werden können.",["race:Undead"]="Als einer der Verlassenen wisst Ihr, dass die Bewohner von Unterstadt in ganz Lordaeron verbotene Magie und unnatürliche Verderbnis erforschen. Sie suchen nach Wegen, dunkle Mächte zu nutzen, um ihre Herrschaft über das Königreich zu festigen."},sec={{t="Eine beunruhigende Ernte",b="Unter dem Flüsternden Wald bergt Ihr die zuckenden Überreste einer seltsamen Bestie. Das beunruhigende Material wird nach Unterstadt gebracht, wo Forscher es untersuchen können."},{t="Studien des Schattens",b="Im War Quarter von Unterstadt nimmt Vater Lankester die Überreste entgegen. Er sagt, der Flüsternde Wald sei seit Langem von der Leere berührt. Ihre physischen Spuren könnten ihm helfen, die Geheimnisse des Schattens zu erforschen."}},faq={{q="Was ist Whispering Horror Residue?",a="Der Rückstand besteht aus den sich windenden Überresten einer seltsamen Bestie, die unter dem Flüsternden Wald besiegt wurde. Schattengelehrte schätzen ihn für arkane und okkulte Studien.",al={"was ist der rückstand","was ist whispering horror residue","rückstand gegenstand"}},{q="Wer möchte Whispering Horror Residue haben?",a="Vater Lankester, ein Verlassener im War Quarter von Unterstadt, möchte den Rückstand haben. Er begrüßt die Gelegenheit, Schatten und von der Leere berührte Phänomene zu untersuchen.",al={"wer nimmt den rückstand","wer ist vater lankester","wo rückstand abgeben"}},{q="Woher stammt dieses Exemplar?",a="Das Exemplar stammt aus den Tiefen unter dem Flüsternden Wald, westlich von Todesend in Tirisfal. Vater Lankester sagt, das Gebiet sei von der Leere berührt.",al={"woher kommt der schrecken","geschichte des flüsternden waldes","unter dem flüsternden wald"}},{q="Warum möchte Vater Lankester den Rückstand haben?",a="Vater Lankester möchte Schatten und die Leere erforschen. Physische Überreste von Kreaturen, die von der Leere berührt wurden, liefern Anwendern verbotener Künste Material für ihre Studien.",al={"warum will lankester das","schattenforschung in unterstadt","warum rückstand untersuchen"}},{q="Wo ist Vater Lankester zu finden?",a="Vater Lankester ist im War Quarter von Unterstadt zu finden, unter den Ruinen der Hauptstadt Lordaerons. Krieger, Gelehrte und Militärplaner der Verlassenen versammeln sich dort.",al={"wo ist war quarter","wo befindet sich lankester","lankesters standort in unterstadt"}},{q="Ist der Flüsternde Wald von der Leere berührt?",a="Vater Lankester sagt, der Flüsternde Wald sei seit Langem von der Leere berührt. Der Wald und die Räume darunter sind für diese Verderbnis bekannt.",al={"ist der flüsternde wald verflucht","leerenverderbnis im flüsternden wald","was berührt den flüsternden wald"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95329"] = {n="Out in the Field",s="Ein Beobachter bei Terral's Watch hält die Ebenen im Auge, um Bewegungen der Horde zu verfolgen. Ihr sollt seinen Statusbericht holen.",h="Ein Beobachter bei Terral's Watch hält die Ebenen im Auge, um Bewegungen der Horde zu verfolgen.",kw={"cornelius","horde","beobachtungsturm","draußen im feld","statusbericht","terral's watch","beobachter"},sec={{t="Ein abgelegener Beobachtungsposten",b="Ein Turm überblickt von Terral's Watch aus die nördlichen Ebenen. Beobachter Cornelius ist dort allein stationiert, um die Bewegungen der Streitkräfte der Horde zu verfolgen. Sein Posten liegt abgelegen, und man kennt ihn als schweigsam. Ihr sollt mit ihm sprechen und einen Statusbericht zurückbringen."}},faq={{q="Wer ist Cornelius?",a="Cornelius ist der allein bei Terral's Watch stationierte Beobachter. Dort hält er die Ebenen im Auge, um Bewegungen der Horde zu verfolgen.",al={"beobachter cornelius","wer ist der beobachter","cornelius' bericht"}},{q="Was ist Terral's Watch?",a="Terral's Watch ist ein Beobachtungsposten über den nördlichen Ebenen, von dem aus die Bewegungen der Streitkräfte der Horde verfolgt werden.",al={"terral's watch","beobachtungsturm","turm im norden"}},{q="Welchen Bericht soll ich holen?",a="Ihr sollt bei Terral's Watch mit Beobachter Cornelius sprechen und einen Statusbericht holen.",al={"statusbericht","was braucht cornelius","cornelius' aufgabe"}},{q="Warum ist Cornelius allein stationiert?",a="Cornelius ist allein auf dem abgelegenen Beobachtungsposten stationiert. Er gilt als schweigsam, und das wird als Grund für seine Zuweisung dorthin genannt.",al={"warum ist er allein","cornelius' posten","warum wurde er dorthin versetzt"}}},fp="16,115,14.265.0,17.115.0,23.116.0,30.88.0,33.140.0"}
P.entries["quest:95330"] = {n="Love Thy Neighbor",s="Cassandra Wheeler bittet Euch, die überschüssigen Erzeugnisse ihres Hofs zu Halligan Turner in Turner's Logging Camp zu bringen. Sie hofft, dass die Arbeiter so etwas Abwechslung auf den Teller bekommen.",h="Cassandra Wheeler bittet Euch, die überschüssigen Erzeugnisse ihres Hofs zu Halligan Turner in Turner's...",kw={"cassandra wheeler","farholde","hofwaren","obst","halligan turner","liebe deinen nächsten","turner's logging camp","gemüse"},sec={{t="Ein Geschenk für den Nachbarn",b="Cassandra Wheeler bewirtschaftet nördlich von Farholde einen Hof und verkauft dort ihre Ernte. Was übrig bleibt, hebt sie für Menschen auf, die etwas Aufmunterung gebrauchen können. Das Holzfällerlager liegt nördlich ihres Hofs am Fluss, und sie glaubt, dass die Arbeiter etwas Obst und Gemüse gebrauchen könnten. Ihr bringt den Überschuss zu Halligan Turner, dem Lageraufseher."},{t="Im Lager",b="Halligan Turner nimmt die Waren dankbar entgegen. Die Arbeiter haben kaum etwas anderes als Fleisch und Brot, deshalb will er die Erzeugnisse unter ihnen aufteilen. Er hofft, Cassandras Freundlichkeit eines Tages erwidern zu können."}},faq={{q="Wer bittet um die Lieferung?",a="Cassandra Wheeler bittet Euch, die überschüssigen Erzeugnisse ihres Hofs zu Halligan Turner zu bringen.",al={"wer möchte das","cassandras bitte","quest mit hofwaren"}},{q="Wer ist Halligan Turner?",a="Halligan Turner ist der Aufseher von Turner's Logging Camp.",al={"wer ist halligan","vorarbeiter im holzfällerlager","der typ turner"}},{q="Wo liegt das Holzfällerlager?",a="Turner's Logging Camp liegt nördlich von Cassandras Hof am Fluss.",al={"wo liegt turner's camp","lagerstandort","holzfällerlager"}},{q="Welche Waren schickt Cassandra?",a="Sie schickt überschüssiges Obst und Gemüse von ihrem Hof.",al={"was soll ich bringen","hofprodukte","cassandras waren"}},{q="Warum hebt Cassandra Erzeugnisse vom Hof auf?",a="Nach der Ernte hebt Cassandra auf, was sie nicht verkauft, um es Menschen zu geben, die etwas Aufmunterung gebrauchen können.",al={"warum essen verschenken","cassandras grund","nachbarn helfen"}},{q="Was essen die Arbeiter im Holzfällerlager gewöhnlich?",a="Halligan sagt, die Arbeiter äßen kaum etwas anderes als Fleisch und Brot.",al={"was essen holzfäller","essen der lagerarbeiter","fleisch und brot"}}},fp="17,168,17.318.0,11.191.1,31.82.0,23.56.0,26.69.0,31.53.0,40.93.0,45.60.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Von Zephras aus erreichen die Windformer des Irdenen Rings Azeroth als Vorhut. Nachdem Kultaktivitäten den Rest in Valanaar aufhalten, gehen sie vor der Loge an Bord eines Himmelssegler-Schiffs und landen in Mulgore, um Alaana Stormwalker zu treffen und sich an eine weite, gefährliche Welt zu gewöhnen.",h="Von Zephras aus erreichen die Windformer des Irdenen Rings Azeroth als Vorhut.",kw={"alaana stormwalker","banu-alah","kult","mulgore","himmelssegler-schiff","der irdene ring","valanaar","windformer","zephras"},ang={["class:Shaman"]="Als Schamane teilt Ihr die Ehrfurcht der Windformer vor den Elementen und ihr Vertrauen auf die Winde, die ihre Überfahrt leiten. Eure Ankunft im Zeichen des Irdenen Rings verbindet Euch mit elementaren Traditionen, die in Mulgore Wurzeln schlagen.",["race:Skyborne"]="Als Skyborne-Abenteurer verlasst Ihr Valanaar und unternehmt die historische Reise nach Azeroth als Teil der Vorhut. Ihr lasst die Unruhen durch den Kult hinter Euch und betretet die Ebenen von Mulgore.",["race:Tauren"]="Als in Mulgore heimischer Tauren erlebt Ihr, wie Reisende aus Zephras auf die Ebenen Eurer Ahnen herabkommen. Diese Besucher willkommen zu heißen, schafft eine frühe Verbindung zu Verbündeten, die in Euren Landen Fuß fassen wollen."},sec={{t="Aufbruch aus Valanaar",b="Kultaktivitäten in Valanaar haben die Pläne der Windformer für ihre Reise nach Azeroth durchkreuzt. Ihre obersten Anführer bleiben in der Loge zurück, um dringende Angelegenheiten zu erledigen und die Bedrohung einzudämmen, während eine kleine Vorhut vorauszieht. An den Docks direkt vor der Loge gehen die Pioniere an Bord eines Himmelssegler-Schiffs, das sie durch die Lüfte tragen soll.\n\nIhre Kommandanten versprechen, bald zu ihnen zu stoßen. Bis dahin muss die Vorhut eine Präsenz aufbauen, bevor der Rest folgen kann."},{t="Ankunft in Mulgore",b="In Mulgore heißt Alaana Stormwalker die eintreffenden Abenteurer aus Zephras willkommen. Auf Azeroth Fuß zu fassen, wird Zeit brauchen, daher werden Neuankömmlinge ermutigt, das umliegende Gebiet auszukundschaften und sich damit vertraut zu machen.\n\nDie Winde sind der Expedition hold, doch Azeroth ist fremd und voller Gefahren. Reisende sollten das örtliche Gelände, die Tierwelt und die benachbarten Bewohner kennenlernen, bevor jene aus Valanaar eintreffen, die sich ihnen noch anschließen werden."}},faq={{q="Warum reisen die Windformer nach Azeroth?",a="Die Windformer schicken eine Vorhut voraus, um eine Präsenz auf Azeroth aufzubauen, während ihre Anführer in Valanaar bleiben. Dortige Kultaktivitäten haben die ursprünglichen Pläne durchkreuzt und den Rest der Gruppe aufgehalten, weshalb die Vorhut allein reist, bis Verstärkung folgen kann.",al={"warum nach azeroth reisen","auftrag der windformer","warum sind die windformer in mulgore"}},{q="Wer ist Alaana Stormwalker?",a="Alaana Stormwalker heißt die aus Zephras eintreffenden Windformer in Mulgore willkommen. Sie sagt, dass es Zeit brauchen wird, in diesen neuen Landen sicher Fuß zu fassen, und rät Neuankömmlingen, die umliegende Region zu erkunden und sich auf Azeroths Gefahren vorzubereiten.",al={"wer ist alaana","rolle von alaana stormwalker","wo ist alaana stormwalker"}},{q="Warum wurde der Hauptaufbruch verzögert?",a="Kultaktivitäten in Valanaar haben den Hauptaufbruch verzögert. Die Expeditionsleiter bleiben in der Loge zurück, um die Unruhen beizulegen, während eine kleine Vorhut ein Himmelssegler-Schiff besteigt und nach Azeroth vorausreist.",al={"warum die verzögerung","welcher kult verzögerte die reise","warum in valanaar bleiben"}},{q="Wie reisen die Reisenden von Valanaar nach Mulgore?",a="Reisende gehen an den Docks direkt vor der Loge in Valanaar an Bord eines Himmelssegler-Schiffs. Es trägt die Vorhut durch die Lüfte nach Mulgore und verbindet Zephras während der ersten Expedition mit Azeroth.",al={"wie nach mulgore gelangen","wo ist das schiff","wie nach azeroth reisen"}},{q="Was ist Zephras?",a="Zephras ist die Heimat der Abenteurer, die an Bord des Himmelssegler-Schiffs eintreffen. In Mulgore heißt Alaana Stormwalker Neuankömmlinge aus Zephras willkommen und sagt, günstige Winde hätten ihre Überfahrt ins fremde, gefährliche Azeroth geleitet.",al={"wo ist zephras","was ist zephras","geschichte von zephras"}},{q="Was sollten Abenteurer nach ihrer Ankunft in Mulgore tun?",a="Neuankömmlinge werden ermutigt, die umliegenden Lande von Mulgore auszukundschaften. Das nahe Gelände, die Kreaturen und die örtlichen Bedrohungen kennenzulernen, wird ihnen helfen, in dieser fremden, gefährlichen Welt Fuß zu fassen.",al={"was in mulgore tun","nächste schritte nach der ankunft","was als nächstes tun"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="In Kalimdor suchen die Windformer jenseits ihrer abgeschiedenen Heimat nach Verbündeten. Geleitet von ihren Banden zum Irdenen Ring reist ein Abgesandter von Donnerfels nach Orgrimmar, um Kriegshäuptling Thrall zu treffen.",h="In Kalimdor suchen die Windformer jenseits ihrer abgeschiedenen Heimat nach Verbündeten.",kw={"der irdene ring","horde","orgrimmar","thrall","donnerfels","tal der weisheit","welcome to azeroth","windformer"},ang={["class:Shaman"]="Unter der Führung des Irdenen Rings und mit dem Segen der Winde verbindet Ihr spirituelle Verwandte mit der schamanischen Führung im Tal der Weisheit.",["faction:Horde"]="Diese diplomatische Reise besiegelt die Beziehungen zur Horde und führt Neuankömmlinge als Verbündete in Kalimdors Überlebenskampf vor Kriegshäuptling Thrall.",["race:Skyborne"]="Ihr verlasst die luftigen Höhen und begebt Euch in die Oberflächenwelt darunter, um aus den Reihen der Skyborne Windformer Kontakt zu Donnerfels und Orgrimmar zu knüpfen und einen Platz unter neuen Verbündeten zu suchen."},sec={{t="Verbündete in einer weiteren Welt",b="Die Windformer blicken über ihre abgeschiedenen Ursprünge hinaus auf die Völker von Kalimdor. Sie wissen, dass Abgeschiedenheit sie nicht vor Azeroths Bedrohungen schützen kann, und suchen deshalb Gefährten, um der Wildnis gemeinsam zu begegnen. Ihre Suche führt sie zur benachbarten Taurenstadt Donnerfels und zu den orkischen Bastionen im Osten."},{t="Eine Audienz beim Kriegshäuptling",b="Die Gesandten reisen zunächst zu den hoch aufragenden Türmen von Donnerfels, dann durch das Brachland nach Orgrimmar, der Hauptstadt der Horde. Kriegshäuptling Thrall wartet im friedlichen Tal der Weisheit. Eine Audienz bei ihm führt die Windformer in Kalimdors politisches und spirituelles Leben und verbindet sie durch gemeinsame Ziele und Ehrfurcht vor den Elementen mit der Horde."}},faq={{q="Welchen Zweck hat die Quest Welcome to Azeroth?",a="Ein Abgesandter reist im Namen der Windformer nach Orgrimmar, um Kriegshäuptling Thrall zu treffen. Das Treffen macht sie mit der größeren Gemeinschaft der Horde und Kalimdors Oberflächenwelt vertraut.",al={"was ist diese quest","welcome to azeroth quest","zweck von welcome to azeroth"}},{q="Wer sind die Windformer?",a="Die Windformer suchen von oben aus Kontakt zu Verbündeten an der Oberfläche, um durch Gemeinschaft mit dem Irdenen Ring und der Horde zu überleben. Sie entsenden Reisende, die in Durotar direkt mit der Führung der Horde sprechen sollen.",al={"wer sind die windformer","was sind die windformer"}},{q="Warum werdet Ihr ausgesandt, um mit Thrall zu sprechen?",a="Thrall ist der Kriegshäuptling der Horde und ein verehrter schamanischer Anführer, der vom Tal der Weisheit aus die wichtigen Bündnisse der Koalition betreut. Das Treffen mit ihm besiegelt die Beziehungen zwischen den Windformern und der Horde.",al={"warum thrall besuchen","mit thrall in orgrimmar sprechen","warum nach orgrimmar reisen"}},{q="Wie reist Ihr von Donnerfels nach Orgrimmar?",a="Reisende brechen mithilfe des Flugmeisters vom zentralen Flugplatz in Donnerfels auf und überqueren Kalimdors Ebenen ostwärts zur Schluchtenfestung Orgrimmar.",al={"wie nach orgrimmar gelangen","flugmeister in donnerfels","von donnerfels nach orgrimmar gelangen"}},{q="Welche Rolle spielt der Irdene Ring bei dieser Mission?",a="Der Irdene Ring steht der Koalition gleichgesinnter Völker der Horde nahe. Er hilft dabei, schamanische Gruppierungen mit den Nationen Kalimdors zu verbinden.",al={"rolle des irdenen rings in der horde","gehört der irdene ring zur horde"}},{q="Wo befindet sich Thrall in Orgrimmar?",a="Kriegshäuptling Thrall residiert im Tal der Weisheit, einem ruhigen spirituellen Zufluchtsort im Westen Orgrimmars, wo sich Schamanen und Stammesberater versammeln.",al={"wo ist thrall","thralls standort im tal der weisheit"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:95383"] = {n="Shipping and Handling",s="Hafenmeister Steamfizzle schickt Euch mit Friz’s Secret Stash zu Tazzik. Die Zollabfertigung der Lieferung wirft Fragen auf.",h="Hafenmeister Steamfizzle schickt Euch mit Friz’s Secret Stash zu Tazzik.",kw={"zoll","friz","friz’s secret stash","hafen von powderfuse","versand und abfertigung","dampfdruckpier","tazzik","hafenmeister steamfizzle"},sec={{t="Am Kai",b="Tazzik wartet am Kai im Dampfdruckpier auf die Kiste, die Ihr bei Euch habt. Hafenmeister Steamfizzle schickt Euch zu ihm, behauptet aber, nichts von der Lieferung zu wissen. Er drängt zur Eile und warnt Euch davor, die falsche Aufmerksamkeit auf Euch zu ziehen. Die Lieferung stammt aus dem Hafen von Powderfuse, und es ist unklar, ob sie den Zoll passiert hat."}},faq={{q="Wer beauftragt mich, die Kiste auszuliefern?",a="Hafenmeister Steamfizzle schickt Euch mit Friz’s Secret Stash zu Tazzik.",al={"wer hat mich geschickt","wer hat mir das paket gegeben"}},{q="Wem soll ich Friz’s Secret Stash liefern?",a="Ihr sollt Friz’s Secret Stash an Tazzik im Dampfdruckpier liefern.",al={"wohin kommt die kiste","wem soll ich das versteck liefern"}},{q="Was ist Friz’s Secret Stash?",a="Es ist eine Lieferung, die Friz für Tazzik geschickt hat. Im Abschlusstext wird ihre Qualität gelobt.",al={"was ist in der kiste","friz paket"}},{q="Woher stammt die Lieferung?",a="Tazzik sagt, er könne den Hafen von Powderfuse an Euch riechen.",al={"herkunft der kiste","powderfuse paket"}},{q="Warum sagt Steamfizzle mir, ich soll mich beeilen?",a="Steamfizzle warnt Euch davor, die falsche Aufmerksamkeit auf Euch zu ziehen.",al={"warum beeilen","falsche aufmerksamkeit"}},{q="Wurde die Lieferung vom Zoll abgefertigt?",a="Tazzik sagt, die Lieferung sei vom Zoll abgefertigt worden, deutet aber an, dass Friz’ Geld ein Problem sein könnte.",al={"vom zoll abgefertigt","ist das legal"}}},fp="21,141,11.327.0,38.73.0,45.72.0,30.79.0,33.48.0,38.54.0,36.99.0"}
P.entries["quest:95384"] = {n="Partial Mystical Notes",s="Eine seltsame magische Schriftrolle trägt Symbole, die Ihr nicht lesen könnt, doch keine Kräfte, die Ihr als unberechenbar wahrnehmt. Ihr bringt sie zu Dudd Fizzlescroll nach Beutebucht, wo er Potenzial in ihrer Magie erkennt.",h="Eine seltsame magische Schriftrolle trägt Symbole, die Ihr nicht lesen könnt, doch keine Kräfte, die Ihr als...",kw={"beutebucht","dudd fizzlescroll","magische schriftrolle","mystische magie","partial mystical notes","unvollständige schriftrolle","seltsame symbole"},sec={{t="Unlesbare Symbole",b="Ihr findet eine magische Schriftrolle voller seltsamer Symbole, doch die Sprache ist Euch unbekannt. Ihre Magie wirkt harmlos genug, also bringt Ihr die unvollständige Schriftrolle zu Dudd Fizzlescroll nach Beutebucht. Er erkennt ihre mächtige Magie und will sie für seine Aufzeichnungen übersetzen."}},faq={{q="Was steht auf der Schriftrolle?",a="Die magische Schriftrolle trägt seltsame Symbole in einer Sprache, die Ihr nicht sprecht.",al={"welche symbole","schrift auf der schriftrolle","mystische notizen"}},{q="Scheint die Schriftrolle gefährlich?",a="Ihr spürt keine besonders unberechenbaren Kräfte in der Schriftrolle.",al={"ist sie unberechenbar","ist die schriftrolle gefährlich","ungefährliche magie"}},{q="Wer möchte die Schriftrolle?",a="Dudd Fizzlescroll in Beutebucht erkennt die Magie der Schriftrolle und will sie für seine Aufzeichnungen übersetzen.",al={"wer nimmt sie","dudd fizzlescroll","schriftrollensammler"}},{q="Wohin soll ich die unvollständige Schriftrolle bringen?",a="Ihr bringt die unvollständige Schriftrolle zu Dudd Fizzlescroll nach Beutebucht.",al={"wohin mit der schriftrolle","schriftrolle aus beutebucht","ziel der schriftrolle"}}},fp="22,180,14.261.0,22.72.0,31.60.0,21.105.0,36.63.0"}
P.entries["quest:95385"] = {n="Torn Mystical Scroll",s="Eine zerrissene Schriftrolle trägt schwache Magie und unbekannte Runen. Ihr bringt sie zu Dudd Fizzlescroll nach Beutebucht, wo er vielversprechende Ansätze in ihrer Schrift erkennt.",h="Eine zerrissene Schriftrolle trägt schwache Magie und unbekannte Runen.",kw={"beutebucht","dudd fizzlescroll","ingenieurskunst","schwache magie","unvollständige schriftrolle","runen","zerrissene mystische schriftrolle"},ang={["profession:Engineering"]="Dudd Fizzlescroll plant, die Runen in seine Arbeit zu übertragen, und spricht davon, ein legendärer Ingenieur zu werden."},sec={{t="Ein rätselhafter Fetzen",b="Schwache Magie haftet an der zerrissenen Schriftrolle, und ihre Runen sind Euch fremd. Ihr spürt keine Gefahr, obwohl die meisten das Pergament für nutzlos halten würden. Dudd Fizzlescroll in Beutebucht findet vielleicht Verwendung für den Fetzen."},{t="Dudds Werk",b="Dudd Fizzlescroll möchte die Runen unbedingt in seine Arbeit übertragen. Er spricht davon, ein legendärer Ingenieur zu werden, und warnt Euch dann, Abstand zu halten, damit Ihr nicht verletzt werdet."}},faq={{q="Was ist die zerrissene Schriftrolle?",a="Es ist ein Pergamentfetzen mit schwacher Magie und unbekannten Runen. Ihr spürt, dass er nicht gefährlich ist.",al={"zerrissene schriftrolle","mystische schriftrolle","was ist das für eine schriftrolle"}},{q="Wer will die Schriftrolle?",a="Dudd Fizzlescroll aus Beutebucht interessiert sich für die unvollständige Schriftrolle.",al={"wer will sie","schriftrollensammler","dudd schriftrolle"}},{q="Warum sollt Ihr sie zu Dudd bringen?",a="Dudd findet vielleicht Verwendung für die unbekannten Runen auf dem Pergament.",al={"warum dudd","wohin mit der schriftrolle","zweck der schriftrolle"}},{q="Ist die Schriftrolle gefährlich?",a="Die Schriftrolle verströmt schwache Magie, doch Ihr ahnt, dass sie nicht gefährlich ist.",al={"schriftrolle sicher","gefährliche schriftrolle","ist sie magisch"}}},fp="20,139,15.208.0,11.157.1,24.104.0,21.67.0,21.62.0,24.74.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="Eine unheimliche blaue Aura brennt über einem Schrein in Bashal'Aran, den Satyrn und Grells meiden. Thundris Windwirker, der Älteste von Auberdine, bittet Euch, ihren Ursprung zu finden.",h="Eine unheimliche blaue Aura brennt über einem Schrein in Bashal'Aran, den Satyrn und Grells meiden.",kw={"asterion","bashal'aran","blaue aura","dunkelküste","grell","ruinen der kaldorei","satyr","thundris windweaver"},ang={["faction:Alliance"]="Als Wanderer der Allianz helft Ihr Auberdines Spähern, in die umkämpften Ruinen der Dunkelküste vorzudringen und dämonische Bedrohungen von der Küste fernzuhalten.",["race:NightElf"]="Als Nachtelf erinnert Euch Bashal'Aran daran, was Eure Vorfahren im Sundering verloren haben. Ihre verbliebenen Schemen halten einsame Wache, während die dämonische Verderbnis vordringt."},sec={{t="Ein Leuchtfeuer in den Ruinen",b="Bashal'Aran blühte einst unter dem uralten Reich der Kaldorei. Heute erfüllt dämonische Verderbnis seine zerbrochenen Marmorhallen und überwucherten Torbögen. Entstellte Satyrn und verderbte Grells zehren von der verbliebenen Magie der Ruinen und werden mit jedem Tag bösartiger. Doch Thundris Windwirker in Auberdine hat etwas Rätselhaftes bemerkt: Auf einer westlichen Anhöhe leuchtet eine blaue Aura über einem Schrein, dem sich kein Dämon nähert."},{t="Der verwundete Schemen",b="Am erhöht gelegenen Schrein findet Ihr Asterion, einen uralten Geist, im Herzen des blauen Lichts. Der Schemen hält seit Jahrhunderten einsame Wache. Zwischen heulenden Bestien und abscheulichen Unholden bringt selbst ein reisender Fremder etwas Erleichterung nach Jahrzehnten der Einsamkeit."}},faq={{q="Wo befindet sich die blaue Aura?",a="Die blaue Aura leuchtet über einem Schrein auf einer kleinen Anhöhe am Westrand von Bashal'Aran, unmittelbar östlich von Auberdine an der Dunkelküste. Der Schrein erhebt sich ein wenig über die zerfallenden Mauern ringsum.",al={"blaue aura finden","wo ist asterion","schrein in bashal'aran finden"}},{q="Warum meiden die Satyrn den Schrein?",a="Niemand weiß, warum die Satyrn und Grells den Schrein meiden. Eine seltsame blaue Aura erfüllt den Ort, und Thundris Windwirker schickt Euch los, um ihren Ursprung zu finden.",al={"warum haben dämonen angst","warum bleiben satyrn fern"}},{q="Wer schickt Euch auf diese Quest?",a="Thundris Windwirker, ein Nachtelfendruide und der Älteste von Auberdine, schickt Euch los, nachdem er unnatürliche Bewegungen der Dämonen in den östlichen Ruinen bemerkt hat.",al={"wer gibt die quest","questgeber","thundris windweaver finden"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran ist eine uralte Ruinenstätte der Kaldorei in den Wäldern der Dunkelküste, die während des uralten Sundering geplündert wurde. Heute wird sie von Grells und Satyrn heimgesucht, angelockt von ihren schlummernden Leykräften.",al={"was geschah mit bashal'aran","geschichte von bashal'aran"}}},fx={["2cba9e48"]={q="Warum möchte Thundris Windwirker, dass ich Bashal'Aran untersuche?",a="Thundris Windwirker beobachtet die alten Ruinen von Bashal'Aran mit wachsender Sorge. Verderbte Sprites und Satyrn wimmeln auf dem Gelände und nutzen verbleibende arane Energien, um ihre dämonische Macht zu vergrößern. Doch inmitten dieses Befalls bleibt ein einziger Schrein, der von einer seltsamen blauen Aura umgeben ist, völlig unberührt von den Dämonen. Thundris muss verstehen, welche Macht sie in Schach hält – und ob dies der Schlüssel sein könnte, um die Verderbnis zurückzudrängen, die an der Dunkelküste überhandnimmt.",al={"warum bashal'aran untersuchen","thundris beweggrund","warum mich nach bashal'aran schicken"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe bittet Euch, nach Ogern zu suchen, die aus den Höhlen unter Sonnengrund verschwunden sind. Einige kehren verändert zurück, und er will wissen, warum.",h="Clubtoe bittet Euch, nach Ogern zu suchen, die aus den Höhlen unter Sonnengrund verschwunden sind.",kw={"höhlen","clubtoe","dunkle runen","vermisste oger","oger","lila","sonnengrund","die lila gekleideten","twilight hammer"},sec={{t="Clubtoes Sorge",b="Clubtoe hat beobachtet, wie Freunde in die Höhlen unter Sonnengrund gingen und nicht zurückkehrten. Einige kommen lila zurück und verhalten sich nicht mehr wie seine Freunde. Er bittet Euch, in den Höhlen nach den vermissten Ogern zu suchen, obwohl er fürchtet, dass auch Ihr verändert zurückkehren könntet."},{t="In den Höhlen",b="Unter Sonnengrund findet Ihr einen Oger, tot zwischen dunklen Runen. Die Kräfte des Rituals des Twilight Hammer haben ihn überwältigt."}},faq={{q="Wer ist Clubtoe?",a="Clubtoe ist ein Oger, dessen Freunde in den Höhlen unter Sonnengrund verschwunden sind.",al={"clubtoe","wer ist clubtoe"}},{q="Warum bittet Clubtoe mich, die Höhlen zu durchsuchen?",a="Einige von Clubtoes Freunden kehren nicht aus den Höhlen zurück, und einige, die wiederkommen, sind lila und verhalten sich anders.",al={"vermisste oger","clubtoes freunde finden","höhlenoger"}},{q="Wo sind die vermissten Oger?",a="Clubtoe bittet Euch, in den Höhlen unter Sonnengrund nach den vermissten Ogern zu suchen.",al={"wohin die oger gehen","höhle bei sonnengrund","vermisste oger"}},{q="Was ist seltsam an den Ogern, die zurückkehren?",a="Einige kehren lila zurück und verhalten sich nicht mehr wie Clubtoes Freunde.",al={"lila oger","warum lila","oger verhalten sich seltsam"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Clubtoe bittet Euch, Chogg'Zacs Kopf nach Rog'mar zu Tran'gul zu bringen, nachdem er den Twilight's Hammer verlassen hat. Die Nachricht von seinem Überlaufen könnte weitere Oger des Kults zur Flucht bewegen.",h="Clubtoe bittet Euch, Chogg'Zacs Kopf nach Rog'mar zu Tran'gul zu bringen, nachdem er den Twilight's Hammer...",kw={"chogg'zac","clubtoe","clugfist","überlaufen der oger","rog'mar","die nachricht verbreiten","tran'gul","twilight's hammer"},sec={{t="Eine Nachricht für Tran'gul",b="Chogg'Zacs Kopf soll zu Euren Freunden zurückgebracht werden, und Tran'gul in Rog'mar soll ihn entgegennehmen. Clubtoe sagt, er habe mit dem Twilight's Hammer abgeschlossen und wolle sich Clugfist anschließen, dem größten Oger, den er kennt, zusammen mit vielen anderen. Clubtoe will bleiben, wo er ist, bis die Luft rein ist. Nun muss Tran'gul erfahren, wofür Clubtoe sich entschieden hat."},{t="Neuigkeiten aus der Höhle",b="Tran'gul erfährt, dass die Höhle noch eine Überraschung bereithielt. Ihr habt einen der Oger des Twilight's Hammer zum Überlaufen bewegt, und er sprach von weiteren seiner Art. Tran'gul sagt, sie müssten sofort handeln."}},faq={{q="Wer ist Clubtoe?",a="Clubtoe ist ein Oger, der sagt, er habe genug vom Twilight's Hammer und wolle sich den freien Ogern anschließen.",al={"clubtoe","clubtoe oger","wer ist clubtoe"}},{q="Wer ist Clugfist?",a="Clugfist ist der größte Oger, den Clubtoe kennt. Clubtoe sagt, er habe den Twilight's Hammer mit vielen Freunden verlassen.",al={"clugfist","clugfist oger","größter oger"}},{q="Was soll ich mitbringen?",a="Clubtoe bittet Euch, Chogg'Zacs Kopf zu seinen Freunden zurückzubringen.",al={"chogg kopf","chogg'zac kopf","was mitbringen"}},{q="Wohin soll ich Chogg'Zacs Kopf bringen?",a="Ihr sollt Chogg'Zacs Kopf zu Tran'gul nach Rog'mar bringen.",al={"wohin mit dem kopf","tran'gul","rog'mar"}},{q="Warum ist Tran'gul besorgt?",a="Tran'gul erfährt, dass ein Oger des Twilight's Hammer übergelaufen ist und weitere seiner Art erwähnt hat.",al={"tran'guls reaktion","twilight höhle","warum jetzt handeln"}}},fp="15,178,22.329.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95420"] = {n="Land of Giants",s="Ein Orc bittet Euch, Chogg’s Kopf in eine Ogerstadt in den nördlichen Hügeln zu bringen. Die Gabe könnte den Weg ebnen, ein altes Bündnis mit den Ogern zu erneuern.",h="Ein Orc bittet Euch, Chogg’s Kopf in eine Ogerstadt in den nördlichen Hügeln zu bringen.",kw={"chogg","chogg’zac","clugfist","land der riesen","nördliche hügel","ogerstadt","oger","bündnis der orcs"},ang={["race:Orc"]="Als Orc tragt Ihr ein Angebot über, das in der ehrwürdigen Geschichte des gemeinsamen Kampfes von Orcs und Ogern wurzelt."},sec={{t="Ein altes Bündnis",b="Die Orcs sehen eine Chance, ihr altes Bündnis mit den Ogern zu erneuern. Berichten zufolge liegt die Heimat des Clans in einer Festung zwischen den nördlichen Hügeln, und Chogg’s Kopf soll für Euch sprechen. Bringt ihn zur Ogerstadt und bietet ihn als Zeichen der Freundschaft dar. Vielleicht hört der Clan Euren Vorschlag an, sofern er Euch nicht zuerst zertrampelt."},{t="Vor Clugfists Tür",b="In der Ogerstadt überreicht Ihr Clugfist Chogg’s Kopf. Er erkennt, dass Ihr Chogg’Zac besiegt habt, und fragt, was Ihr von ihm wollt. Das Freundschaftsangebot hat Euch die Gelegenheit eröffnet, mit dem Anführer des Clans zu sprechen."}},faq={{q="Warum bringe ich Chogg’s Kopf zu den Ogern?",a="Die Orcs hoffen, dass Chogg’s Kopf als Zeichen der Freundschaft dient und ihnen hilft, ihr altes Bündnis mit den Ogern zu erneuern.",al={"chogg kopf","warum choggs kopf mitnehmen","oger kopf als gabe"}},{q="Wo ist die Heimat des Ogerclans?",a="Berichten zufolge liegt die Festung des Clans in den weit nördlich gelegenen Hügeln.",al={"standort der ogerstadt","wo sind die oger","oger in den nördlichen hügeln"}},{q="Wer ist Clugfist?",a="Clugfist ist der riesige Oger, dem Ihr in der Ogerstadt begegnet. Er fragt, was Ihr von ihm wollt.",al={"wer ist clugfist","ogeranführer","clug fist"}},{q="Wer ist Chogg’Zac?",a="Chogg’Zac ist der Oger, von dem Clugfist sagt, dass Ihr ihn besiegt habt.",al={"chogg zac","hintergrund zu chogg","wer ist chogg"}},{q="Was wollen die Orcs von den Ogern?",a="Die Orcs hoffen, sich auf ihr altes Bündnis mit den Ogern berufen und dem Clan einen Vorschlag unterbreiten zu können.",al={"bündnis zwischen orcs und og ern","was wollen die orcs","freundschaft mit ogern"}}},fp="14,143,11.313.0,20.218.1,46.114.0,32.68.0,16.87.0,19.56.0,37.92.0"}
P.entries["quest:95424"] = {n="Might Makes Right",s="Clugfist fordert Euch heraus, Eure Stärke in Bolder'ok zu beweisen. Die Oger von Twilight's Hammer stellen Euch auf die Probe.",h="Clugfist fordert Euch heraus, Eure Stärke in Bolder'ok zu beweisen.",kw={"bolder'ok","clugfist","macht macht recht","oger","skyborne","twilight firecallers","twilight maulers","twilight's hammer"},sec={{t="Clugfists Prüfung",b="Clugfist beurteilt Stärke nach Blut und schickt Euch in Bolder'ok gegen die Twilight Maulers und Twilight Firecallers. Er zweifelt an Eurer Größe, gibt Euch aber die Chance, Euer Können zu zeigen. Bei der Herausforderung messt Ihr Eure Stärke mit den Twilight-Ogern."}},faq={{q="Wer ist Clugfist?",a="Clugfist ist der Oger in Bolder'ok, der Euch herausfordert, Eure Stärke zu beweisen.",al={"clugfist","wer ist clugfist","oger"}},{q="Was will Clugfist von mir?",a="Clugfist fordert Euch auf, Twilight Maulers und Twilight Firecallers in Bolder'ok zu töten.",al={"was will clugfist","aufgabe von clugfist","was soll ich töten"}},{q="Warum zweifelt Clugfist an mir?",a="Clugfist nennt Euch winzig und bezweifelt, dass Ihr stark seid.",al={"warum zweifelt er an mir","zu winzig","clugfist hält mich für schwach"}},{q="Wie ist es in Bolder'ok?",a="In Bolder'ok zählen laut Clugfist Stärke und Blut für die Oger.",al={"bolderok","oger in bolder'ok","was passiert hier"}}},fp="17,98,15.248.0,16.76.0,33.81.0,27.61.0,23.64.0"}
P.entries["quest:95425"] = {n="Unworthy Champion",s="Clugfist in Bolder'ok möchte, dass Ihr Skullbasher von Klunk zurückholt. Er hält Klunk nicht länger für würdig, die Waffe zu führen.",h="Clugfist in Bolder'ok möchte, dass Ihr Skullbasher von Klunk zurückholt.",kw={"bolder'ok","höhle","clugfist","klunk","ogerchampion","skullbasher","twilight's hammer"},sec={{t="Clugfists Forderung",b="Clugfist schickt Euch hinter Klunk her, der Bolder'ok verließ und Oger mitnahm, um in einer Höhle östlich des Wassers zu leben. Er will seine Waffe zurück und nennt Klunk schwach. In Clugfists Augen ist Skullbasher das Zeichen eines Champions, und er will einen anderen auswählen."}},faq={{q="Wer ist Klunk?",a="Klunk war einst Clugfists Champion, doch Clugfist nennt ihn nun schwach.",al={"wer ist klunk","klunks hintergrundgeschichte"}},{q="Wer ist Clugfist?",a="Clugfist ist der Oger, der Klunk eine mächtige Waffe gab und sie nun zurückhaben will.",al={"wer ist clugfist","oger clugfist"}},{q="Warum will Clugfist Skullbasher?",a="Clugfist sagt, Skullbasher gehöre ihm, und nennt Klunk unwürdig, sie zu führen.",al={"warum skullbasher nehmen","clugfists waffe"}},{q="Wohin ist Klunk gegangen?",a="Klunk verließ Bolder'ok mit Ogern und zog zu einer Höhle östlich des Wassers.",al={"klunks aufenthaltsort","wohin ging klunk"}},{q="Was ist Skullbasher?",a="Skullbasher ist die mächtige Waffe, die Clugfist Klunk gab.",al={"waffe skullbasher","klunks waffe"}},{q="Was plant Clugfist als Nächstes?",a="Clugfist sagt, dass er eines Tages einen neuen Champion auswählen wird.",al={"neuer champion","clugfists pläne"}}},fp="17,117,17.240.0,13.68.0,16.74.0,35.72.0,19.69.0,20.53.0,35.52.0"}
P.entries["quest:95426"] = {n="Rog'mar Supplies",s="Ein örtlicher Kontakt bittet Euch, Rog'mar zu behindern, indem Ihr Versorgungslieferungen aus dessen Übungsgebieten im Norden abfangt. Die Verzögerung könnte dazu führen, dass die Streitkräfte der Horde weniger kampfbereit sind.",h="Ein örtlicher Kontakt bittet Euch, Rog'mar zu behindern, indem Ihr Versorgungslieferungen aus dessen...",kw={"horde","rog'mar","lieferung","vorräte","vorratslieferung","übungslager"},sec={{t="Ein Mangel an Vorräten",b="Ein Kontakt in der Nähe von Rog'mar sieht eine Möglichkeit, das Wachstum der Orcs zu bremsen. Ihr sollt ihre Vorratslieferungen aus den Übungsstätten nördlich von Rog'mar entwenden. Die Versorgung ist hier schwierig, und der Diebstahl soll die Kriegsvorbereitungen der Horde verzögern."}},faq={{q="Was soll ich tun?",a="Ihr sollt Vorratslieferungen der Horde aus den Übungslagern nördlich von Rog'mar entwenden.",al={"rog'mars vorräte","lieferungen stehlen","vorratsdiebstahl"}},{q="Warum soll ich die Vorräte stehlen?",a="Der Diebstahl soll Rog'mars Wachstum bremsen und verhindern, dass die Streitkräfte der Horde kampfbereit sind.",al={"warum vorräte stehlen","rog'mar bremsen","vorräte der horde"}},{q="Wo befinden sich die Lieferungen?",a="Die Vorratslieferungen der Horde befinden sich in den Übungslagern nördlich von Rog'mar.",al={"wo sind vorräte","übungslager","nördlich von rog'mar"}}},fp="16,167,17.258.0,28.86.0,22.101.0,24.70.0"}
P.entries["quest:95427"] = {n="Twilight No More!",s="Clubtoe bittet Euch, Chogg'Zac in der Höhle von Sonnengrund entgegenzutreten. Er gibt ihnen die Schuld am Tod seiner Freunde und an ihrem Versprechen, Oger stark zu machen.",h="Clubtoe bittet Euch, Chogg'Zac in der Höhle von Sonnengrund entgegenzutreten.",kw={"höhle","chogg'zac","clubtoe","freunde","oger","sonnengrund","zwielicht"},sec={{t="Clubtoes Flehen",b="Clubtoe sagt, seine Freunde seien tot, und gibt Chogg'Zac die Schuld. Sie hätten versprochen, Oger stark zu machen, doch er sagt, sie hätten gelogen. Deshalb bittet er Euch, ihm dabei zu helfen, sich in der Höhle von Sonnengrund gegen sie zu wenden. Er will ihre Köpfe und wird keine Felsen mehr für sie zerschmettern."},{t="Ein neuer Name",b="Nachdem Chogg'Zac sterben, schreit Clubtoe triumphierend auf. Er sagt, er sei es leid, für Winzlinge Felsen zu zerschmettern und Freunde zu verlieren. Er nennt sich fortan „Twilight no more“."}},faq={{q="Wer ist Clubtoe?",a="Clubtoe ist ein Oger, der sagt, Chogg'Zac hätten versprochen, Oger stark zu machen. Er gibt ihnen die Schuld am Tod seiner Freunde.",al={"clubtoe","wer ist clubtoe","clubtoes hintergrundgeschichte"}},{q="Warum will Clubtoe Chogg'Zac tot sehen?",a="Clubtoe sagt, Chogg'Zac hätten bei ihrem Versprechen gelogen, Oger stark zu machen, und gibt ihnen die Schuld am Tod seiner Freunde.",al={"warum chogg'zac töten","grund für chogg zac","chogg'zac quest"}},{q="Wo sind Chogg'Zac?",a="Chogg'Zac sind in der Höhle von Sonnengrund.",al={"chogg'zac ort","wo chogg zac","höhle von sonnengrund"}},{q="Was will Clubtoe von Euch?",a="Clubtoe bittet Euch, Chogg'Zac zu töten und ihre Köpfe zu sammeln.",al={"was will clubtoe","was für clubtoe besorgen","clubtoes köpfe"}}},fp="17,141,14.247.0,10.155.1,15.108.0,37.94.0,20.37.0,32.59.0"}
P.entries["quest:95428"] = {n="Clugfist's Decree",s="Clugfist gestattet Euch vorerst, in Bolder'ok zu bleiben, nachdem die Skyborne den Twilight's Hammer besiegt haben. Er bittet Euch, den anderen auszurichten, dass der Clan bald wieder kämpfen wird.",h="Clugfist gestattet Euch vorerst, in Bolder'ok zu bleiben, nachdem die Skyborne den Twilight's Hammer besiegt...",kw={"bolder'ok","clugfist","erlass","horde","krom'rosh","rog'mar","skyborne","twilight's hammer"},ang={["faction:Horde"]="Als Mitglied der Horde könnten die Bolder'ok mächtige Verbündete werden, wenn Euer Volk sich weiterhin ihr Vertrauen verdient."},sec={{t="Nachricht für Rog'mar",b="Krom'rosh in Rog'mar wartet auf Eure Nachricht. Clugfist lässt Euch vorerst in Bolder'ok bleiben und bittet Euch, den anderen Skyborne die Nachricht zu überbringen. Der Clan rechnet bald wieder mit Blutvergießen."},{t="Vertrauen und Bündnisse",b="Krom'rosh sieht im Clan von Bolder'ok einen möglichen Verbündeten für die Horde. Ihr jüngster Kampf um die Freiheit vom Twilight's Hammer erinnert an die blutige Geschichte der Horde. Euer Bericht könnte der Horde helfen, sich ihr Vertrauen weiter zu verdienen."}},faq={{q="Was soll ich ausrichten?",a="Clugfist bittet Euch, den anderen Skyborne auszurichten, dass der Clan von Bolder'ok damit rechnet, bald wieder zu kämpfen.",al={"clugfists erlass","was soll ich berichten","clugfists befehle"}},{q="Wo soll ich Bericht erstatten?",a="Clugfist schickt Euch zu Krom'rosh nach Rog'mar, um Bericht zu erstatten.",al={"bericht an krom'rosh","wo ist krom'rosh","bericht nach rog'mar"}},{q="Kann ich in Bolder'ok bleiben?",a="Clugfist gestattet Euch, vorerst in Bolder'ok zu bleiben.",al={"in bolder'ok bleiben","clugfist lässt mich bleiben","erlaubnis für bolder'ok"}},{q="Wer sind die Bolder'ok?",a="Die Bolder'ok sind ein Clan, der vor Kurzem um die Freiheit vom Twilight's Hammer gekämpft hat.",al={"clan bolder'ok","wer ist clugfist","clugfists leute"}},{q="Warum interessiert sich die Horde für die Bolder'ok?",a="Krom'rosh glaubt, dass die Bolder'ok mächtige Verbündete werden könnten, wenn die Horde sich weiterhin ihr Vertrauen verdient.",al={"horde und bolder'ok","verbündete aus bolder'ok","warum interessiert sich krom'rosh dafür"}}},fp="17,168,16.182.0,19.225.1,33.97.0,18.55.0,24.52.0,22.85.0,44.105.0"}
P.entries["quest:95432"] = {n="Rise Up!",s="Crag'rog bittet Euch, Oger aus dem Zwielicht zu befreien. Er will sie zum Eintopf nach Hause bringen.",h="Crag'rog bittet Euch, Oger aus dem Zwielicht zu befreien.",kw={"crag'rog","oger befreien","ogerbergleute","oger","erhebt euch","eintopf","zwielicht"},sec={{t="Oger und das Zwielicht",b="Crag'rog will Oger aus dem Zwielicht befreien und freut sich über Eure Hilfe. Gemeinsam werbt Ihr Ogerbergleute für den Kampf an. Crag'rog sagt, danach können die Oger zum Eintopf nach Hause gehen."},{t="Crag'rogs Zählung",b="Crag'rog sagt, viele Oger seien frei und die schwachen, feigen Oger seien tot. Er zählt nur noch einen feigen Oger."}},faq={{q="Wer ist Crag'rog?",a="Crag'rog ist ein Oger, der Oger aus dem Zwielicht befreien will.",al={"crag'rog","wer ist crag'rog"}},{q="Warum will Crag'rog Oger befreien?",a="Er hat gehört, dass Ihr Oger befreit, und nun will er sie ebenfalls befreien.",al={"warum oger befreien","freiheit der oger"}},{q="An wessen Seite kämpft Crag'rog?",a="Crag'rog kämpft an Eurer Seite gegen das Zwielicht.",al={"wer hilft crag'rog","winzige klasse"}},{q="Wen sollt Ihr laut Crag'rog anwerben?",a="Crag'rog bittet Euch, Ogerbergleute anzuwerben.",al={"oger anwerben","ogerbergleute"}},{q="Was sagt Crag'rog danach über die Oger?",a="Crag'rog sagt, viele Oger seien frei und nur noch ein feiger Oger sei übrig.",al={"was geschah mit den ogern","crag'rogs abschluss"}}},fp="8,89,18.176.0,16.112.1,16.60.0,37.67.0,34.43.0,38.41.0,49.70.0"}
P.entries["quest:95433"] = {n="Death to the Executioner",s="Clugfist bittet Euch, Euch Morg zu stellen, dem Oger, der den Weg aus Twilight bewacht. Er will Morgs Streitkolben zurück nach Bolder’ok bringen lassen.",h="Clugfist bittet Euch, Euch Morg zu stellen, dem Oger, der den Weg aus Twilight bewacht.",kw={"bolder'ok","clugfist","crag'rog","henker morg","executioner's mace","morg","twilight shroud","twilight's hammer"},ang={["race:Tauren"]="Als Tauren nennt Clugfist Euch nach Morgs Tod einen winzigen Tauren voller Tricks."},sec={{t="Ein Weg hinaus",b="Clugfist aus Bolder’ok bittet Euch, Euch Morg im Twilight Shroud zu stellen. Der Henker ist beinahe so groß wie Clugfist, und Clugfist sagt, er verlasse sich zu seinem Schutz auf kleinere Verbündete. Bringt ihm den Streitkolben zurück, und Twilight’s Hammer wird wissen, dass die Oger sie nicht länger herausfordern."},{t="Bolder’oks Antwort",b="Crag’rog sagt, Ihr hättet Euch ihm im Kampf angeschlossen, und Clugfist fragt, was Ihr mitbringt. Morg ist tot, und Clugfist lobt Eure Tricks. Er sagt, Twilight’s Hammer sei unter Bolder’oks Macht zusammengebrochen und die Oger seien frei."}},faq={{q="Wer ist Morg?",a="Morg ist ein Henker im Twilight Shroud, ein Oger, der beinahe so groß ist wie Clugfist.",al={"wer ist morg","henker morg","twilight oger"}},{q="Warum will Clugfist Morg tot sehen?",a="Clugfist sagt, Morg stehe ihm im Weg, während er Twilight verlässt, und verlasse sich zu seinem Schutz auf kleinere Verbündete.",al={"warum morg töten","clugfist will morg","morgs problem"}},{q="Was möchte Clugfist zurückhaben?",a="Clugfist möchte, dass Ihr ihm Morg’s Executioner’s Mace nach Bolder’ok zurückbringt.",al={"morgs streitkolben","was zurückbringen","executioner's mace"}},{q="Wo ist Morg?",a="Morg befindet sich im Twilight Shroud.",al={"morgs ort","wo ist der henker","twilight shroud"}}},fp="24,122,9.288.0,22.227.1,12.83.0,33.114.0,42.76.0,14.31.0"}
P.entries["quest:95454"] = {n="The Honor of the Kor'kron",s="Die Kor’kron von Commander Folkar wurden nach Alcaz Prison geschickt, um Varian Wrynn lebend zu befreien. Da der Commander verletzt und seine Elitetruppen tot sind, liegt die Suche nun bei Euch.",h="Die Kor’kron von Commander Folkar wurden nach Alcaz Prison geschickt, um Varian Wrynn lebend zu befreien.",kw={"alcaz prison","schwarze drachen","commander folkar","ehre","kor'kron","orgrimmar","varian wrynn"},ang={["faction:Horde"]="Als Mitglied der Horde führt Ihr den Befehl des Kriegshäuptlings aus, Varian Wrynn lebend nach Orgrimmar zu bringen."},sec={{t="Ein König in Alcaz",b="Die Kor’kron kamen nach Alcaz Prison, um Varian Wrynn, den König von Sturmwind, zu finden. Ihr Kriegshäuptling befahl ihnen, ihn lebend nach Orgrimmar zu bringen. Nun ist der Axtarm ihres Commanders gebrochen und die meisten seiner Elitetruppen sind tot. Ihr setzt die Suche fort, während er zurückbleibt."},{t="Die Suche",b="Schwarze Drachen erschweren den Kor’kron die Suche nach Varian. Nachdem Ihr einen niederen Drachen erschlagen habt, scheint eine größere Macht die Fäden zu ziehen. Es ist an der Zeit, Commander Folkar zu berichten, was Ihr erfahren habt."}},faq={{q="Warum sind die Kor’kron in Alcaz Prison?",a="Auf Befehl des Kriegshäuptlings wurden sie geschickt, um Varian Wrynn zu befreien und ihn lebend nach Orgrimmar zu bringen.",al={"kor kron in alcaz","warum sind sie hier"}},{q="Wen suchen die Kor’kron?",a="Sie durchsuchen Alcaz Prison nach Varian Wrynn, dem König von Sturmwind.",al={"suche nach varian","wen suchen sie"}},{q="Warum liegt die Suche nun bei mir?",a="Der Axtarm des Commanders ist gebrochen und die meisten seiner Elitetruppen sind tot. Deshalb bittet er Euch, die Suche fortzusetzen.",al={"commander verletzt","kor kron elitetruppen"}},{q="Was erschwert den Kor’kron die Suche?",a="Die Anwesenheit schwarzer Drachen erschwert ihre Suche nach Varian.",al={"schwarze drachen alcaz","drachenproblem"}}},fp="25,161,15.258.0,10.201.1,39.99.0,35.68.0,31.108.0,43.70.0"}
P.entries["quest:95483"] = {n="Thrall Needs to Know",s="Thrall braucht Nachricht über Varian Wrynns Schicksal in Orgrimmar. Diese Nachricht ist für die Stellung der Horde in Azeroth von Bedeutung.",h="Thrall braucht Nachricht über Varian Wrynns Schicksal in Orgrimmar.",kw={"folkar","horde","kor'kron","orgrimmar","thrall","ulka","varian wrynn","kriegshäuptling"},ang={["faction:Horde"]="Als Mitglied der Horde überbringt Ihr Thrall eine Nachricht, die seiner Aussage nach helfen kann, die Stellungen der Horde in Azeroth zu stärken."},sec={{t="Nachricht für Thrall",b="Kommandant Folkar bittet Euch, Thrall in Orgrimmar eine Nachricht zu überbringen. Er wird dorthin zurückkehren, nachdem er sich vergewissert hat, dass Ulka reisefähig ist. Man vertraut Euch an, dem Kriegshäuptling mitzuteilen, welches Schicksal Varian Wrynn ereilt hat."},{t="Die Antwort des Kriegshäuptlings",b="Thrall erfährt, dass die meisten Kor'kron Folkars verloren gingen, als sie ihm die Nachricht überbrachten. Er sagt, die Horde werde dieses Wissen nutzen, um ihre Stellungen in Azeroth zu stärken. Varian Wrynns Tod feiert er nicht, doch sieht er einen Vorteil für die Horde in allem, was die Allianz schwächt."}},faq={{q="Was muss Thrall wissen?",a="Thrall braucht Nachricht über Varian Wrynns Schicksal.",al={"thrall muss es wissen","was mit varian geschah","varians schicksal"}},{q="Wohin soll ich die Nachricht bringen?",a="Die Nachricht soll Thrall in Orgrimmar überbracht werden.",al={"wo ist thrall","thrall nachricht überbringen","orgrimmar thrall"}},{q="Wer bittet mich, die Nachricht zu überbringen?",a="Kommandant Folkar bittet Euch, die Informationen an seiner Stelle zu Thrall zu bringen. Er nennt Euch einen Soldaten der Horde.",al={"wer schickte mich","wer will die nachricht","der soldat"}},{q="Warum kehrt der Soldat nach Orgrimmar zurück?",a="Folkar wird sich zuerst mit Ulka treffen und dafür sorgen, dass Ulka reisefähig ist. Erst dann wird er nach Orgrimmar zurückkehren.",al={"was ist mit ulka","warum verspätet sich der soldat","ulka reise"}},{q="Was sagt Thrall über die Kor'kron?",a="Thrall sagt, dass die meisten Kor'kron Folkars verloren gingen, als sie ihm die Informationen überbrachten.",al={"folkars kor'kron","verluste der kor'kron","was mit den kor'kron geschah"}},{q="Wie wird die Horde die Informationen nutzen?",a="Thrall sagt, die Horde werde dieses Wissen nutzen, um ihre Stellungen in Azeroth zu stärken.",al={"pläne der horde","stellungen stärken","was thrall tun wird"}}},fp="20,132,15.193.0,20.287.1,30.41.0,26.49.0,30.111.0,42.108.0,40.83.0,39.88.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="Eine Verletzung hindert einen Jäger oder Händler daran, Löwenhäute für einen örtlichen Gerber zu sammeln. Er wendet sich an Euch, um seine Handelsvereinbarung einzuhalten und seinen beruflichen Ruf zu wahren.",h="Eine Verletzung hindert einen Jäger oder Händler daran, Löwenhäute für einen örtlichen Gerber zu sammeln.",kw={"bruised pride and lion hides","jagd","lederwaren","löwenhäute","gerber","handel"},sec={{t="Das Dilemma eines Jägers",b="Ein Jäger oder Händler wurde verletzt und kann wilden Bestien nicht gefahrlos nachstellen. Seine Verpflichtung gegenüber einem Handwerker aus der Nachbarschaft bleibt bestehen, also heuert er Euch an, wilde Löwen zu jagen und ihre Felle zu sammeln."},{t="Die Abmachung einhalten",b="Die rohen Häute gehen an einen örtlichen Gerber, der sie gegen fertige Lederwaren eintauscht, die der Auftraggeber für seinen Lebensunterhalt braucht. Hilfe zu benötigen, kränkt den Stolz des Auftraggebers, doch die Einhaltung der Abmachung wahrt seinen beruflichen Ruf."}},faq={{q="Worum geht es bei dieser Quest?",a="Ein verwundeter Jäger oder Händler braucht Löwenhäute, um einen örtlichen Gerber zu beliefern. Im Gegenzug erhält der Auftraggeber fertige Lederwaren, die für seinen Lebensunterhalt unerlässlich sind.",al={"was ist bruised pride and lion hides","questziel","wofür sind die löwenhäute"}},{q="Warum braucht der Questgeber Hilfe beim Sammeln der Häute?",a="Eine Verletzung hindert den Auftraggeber daran, selbst Löwen zu jagen. Er verlässt sich auf Euch, um eine langjährige Vereinbarung mit einem örtlichen Gerber einzuhalten.",al={"warum hilfe nötig","warum kann der auftraggeber nicht jagen"}},{q="Wer erhält die Löwenhäute?",a="Ein örtlicher Gerber erhält die rohen Häute und verarbeitet sie zu fertigen Lederwaren, die der Auftraggeber für seinen regelmäßigen Handel und seine Arbeit braucht.",al={"wer bekommt die löwenhäute","wohin gehen die häute"}},{q="Was bedeutet der Name „Bruised Pride and Lion Hides“?",a="Der Name bezieht sich sowohl auf ein Löwenrudel, das gejagt werden soll, als auch auf den gekränkten Stolz des verletzten Jägers. Der Jäger hat bisher jeden Auftrag erfüllt, doch seine Verletzung schränkt ihn nun ein.",al={"bedeutung von bruised pride","warum heißt es bruised pride"}},{q="War die Abmachung mit dem Gerber gefährdet?",a="Ja. Die Verletzung gefährdet die nächste Lieferung des Auftraggebers. Das Sammeln der Löwenhäute ermöglicht es ihm, seine Abmachung einzuhalten und die vollständige Lieferung zu erbringen.",al={"wird die abmachung mit dem gerber eingehalten","handelsabkommen gebrochen"}},{q="Wie wurde der Questgeber verletzt?",a="Der Auftraggeber erlitt eine Verletzung, die ihn daran hindert, Löwen in freier Wildbahn zu jagen. Ihre genaue Ursache wird nicht genannt, und die Lieferung der Häute ermöglicht es ihm, seinen Ruf zu wahren.",al={"verletzung des questgebers","was ist dem jäger passiert"}}},fp="28,174,18.195.0,24.236.0,25.157.0,51.130.0,28.128.0,55.170.0,44.136.0,32.171.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="Ihr tragt rohe Häute durch das Brachland zum Hermit Tanner, der oberhalb der Trockenen Hügel lebt. Vrang schafft den Aufstieg nicht, also schickt er Euch zu seinem abgeschieden lebenden Handelspartner.",h="Ihr tragt rohe Häute durch das Brachland zum Hermit Tanner, der oberhalb der Trockenen Hügel lebt.",kw={"brachland","bündel mit bälgen","die trockenen hügel","hermit tanner","bergrücken","gerber","vrang"},ang={["faction:Horde"]="Im Brachland könnt Ihr Händlern wie Vrang helfen, Waren durch die zerklüftete Savanne zu tragen."},sec={{t="Ein Bergrücken im Brachland",b="Im Brachland handelt Vrang mit einem Gerber, der auf einem Bergrücken oberhalb der Trockenen Hügel lebt. Der steile, felsige Aufstieg ist für Vrang zu beschwerlich, also bittet er vorbeiziehende Reisende, rohe Häute zum Gehöft seines Partners zu bringen."},{t="Ein ungewöhnlicher Handwerker",b="Vrang warnt Euch, dass das ungewöhnliche Aussehen des einsamen Gerbers Euch erschrecken könnte, sagt aber, dass er für Besucher keine Gefahr darstellt. Als Ihr die Häute auf den Bergrücken bringt, heißt der Einsiedler Euch herzlich willkommen. Er bedauert, dass Vrang nicht selbst kommen konnte, denn er hatte gehofft, etwas mit dem Händler zu besprechen."}},faq={{q="Wer schickt Euch auf diese Lieferung?",a="Vrang schickt Euch mit einem Bündel roher Häute zu seinem Handelspartner auf dem Bergrücken oberhalb der Trockenen Hügel.",al={"wer vergibt hermit tanner","wo beginnt die quest","vrangs lieferung"}},{q="Wo lebt der einsiedlerische Gerber?",a="Der einsiedlerische Gerber lebt allein auf einem abgelegenen Gehöft auf einem Bergrücken mit Blick auf die Trockenen Hügel im Brachland.",al={"einsiedlerischer gerber standort","wo ist der einsiedlerische gerber","einsiedler auf dem bergrücken"}},{q="Warum warnt Vrang Euch vor dem Aussehen des Gerbers?",a="Vrang warnt Euch, dass das ungewöhnliche Aussehen des Gerbers Euch erschrecken könnte, versichert Euch aber, dass er für Besucher keine Gefahr darstellt.",al={"aussehen des einsiedlers","warum ist der einsiedler unheimlich","erscheinung des einsiedlers"}},{q="Warum konnte Vrang den Aufstieg nicht selbst bewältigen?",a="Der steile, felsige Aufstieg ist für Vrang zu anstrengend, also bittet er einen vorbeiziehenden Reisenden, die Häute hinaufzubringen.",al={"warum ist eine lieferung nötig","warum kann vrang nicht gehen"}},{q="Welche Gegenstände werden auf den Bergrücken geliefert?",a="Ihr tragt ein Bündel roher Häute für das Gerbereigeschäft, das der Einsiedler und Vrang gemeinsam betreiben.",al={"was ist das bündel mit bälgen","gelieferte questgegenstände"}},{q="Was möchte der einsiedlerische Gerber mit Vrang besprechen?",a="Der Einsiedler bedauert, dass Vrang nicht persönlich kommen konnte, und sagt, dass er etwas mit ihm zu besprechen hat.",al={"was will der gerber von vrang","geschäfte des gerbers mit vrang"}}},fp="17,169,22.210.0,27.293.0,31.100.0,34.108.0,54.122.0,42.107.0,44.89.0,55.101.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="Noch immer bindet Magie Asterion unter den zerbrochenen Steinen von Bashal'Aran. Der uralte Nachtelf sucht Erlösung von seiner Geistergestalt und vermutet, dass die Grells das Siegel berührt haben, das ihn festhält. Er bittet Reisende, ihre Ohrringe zu sammeln und der daran haftenden Magie nachzuspüren.",h="Noch immer bindet Magie Asterion unter den zerbrochenen Steinen von Bashal'Aran.",kw={"asterion","bashal'aran","bindung","dunkelküste","geist","grell","grellohrring","siegel"},ang={["class:Mage"]="Als Magier erkennt Ihr in Asterions Einsatz verzauberter Schmuckstücke zum Aufspüren verbliebener Magie womöglich eine uralte Praxis arkaner Weissagung der Hochgeborenen.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, die gefährlichen nördlichen Gebiete der Dunkelküste zu befrieden, indem Ihr die chaotischen Grells um Bashal'Aran beseitigt.",["race:NightElf"]="Als Kaldorei seht Ihr in Asterion vielleicht eine Erinnerung an die in der Sundering verlorene uralte Zivilisation und an Seelen, die seit Jahrtausenden in Ruinen gebunden sind."},sec={{t="Jahrhunderte der Qual",b="Seit Jahrhunderten wartet Asterion zwischen den zerborstenen Marmortrümmern von Bashal'Aran. Der uralte Nachtelfengeist bleibt unter dem Blätterdach der Dunkelküste zwischen Leben und wahrem Tod gefangen. Arkane Kunst bindet ihn an die verfallene Siedlung, und allein kann er sich nicht befreien. Einsamkeit und Verzweiflung haben seinen Verstand zermürbt."},{t="Spuren in der Wildnis",b="Asterion glaubt, dass ein uraltes, in den Ruinen verborgenes Siegel den Schlüssel zu seiner Befreiung bergen könnte. Er kann das Dickicht und die herabgestürzten Steine nicht selbst durchsuchen. Die wilden Grells von Bashal'Aran suchen dort nach Nahrung und stehlen kleine Schmuckstücke, weshalb er Reisende bittet, ihre Ohrringe zu sammeln. Er hofft, dass die daran haftende Magie ihn zu dem Siegel führt, das seine Seele quält."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein uralter Nachtelfengeist, der an die Ruinen von Bashal'Aran in der Dunkelküste gebunden ist. Ein mystisches Siegel hält ihn seit Jahrhunderten in Qualen gefangen, und er sehnt sich nach Erlösung von seinem geisterhaften Dasein.",al={"asterions geschichte","wer ist der geist in bashal'aran","asterion questgeber"}},{q="Warum will Asterion Grellohrringe?",a="Asterion glaubt, dass die Grells das Siegel berührt haben, das ihn bindet. Ihre Ohrringe könnten Spuren seiner Magie tragen und ihm helfen, es zu finden.",al={"warum grellohrringe","zweck des grellohrrings","ohrringquest dunkelküste"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran liegt an der bewaldeten Küste der Dunkelküste, eine uralte Nachtelfenruine aus der Zeit vor der Great Sundering. Wilde Grells, Satyrn und geisterhafte Überreste der verstorbenen Bewohner streifen dort umher.",al={"was ist bashal'aran","bashal'arans geschichte","ruinen von bashal'aran"}},{q="Was geschieht nach dem Sammeln der Ohrringe?",a="Nachdem Reisende die Ohrringe gesammelt haben, untersucht Asterion sie. Er spürt, dass die Grells das Siegel vor einer für seine Begriffe kurzen Zeit gestreift haben, es aber nicht bei sich tragen. Dadurch kann er dessen Lage in den Ruinen eingrenzen.",al={"was zeigen die ohrringe","hatten die grells das siegel","grellohrring ergebnis"}},{q="Warum ist Asterion hier gefangen?",a="Ein uraltes magisches Siegel band Asterion vor Jahrhunderten an Bashal'Aran. Es verankert seinen Geist in den Ruinen und hindert ihn daran, friedliche Ruhe zu finden.",al={"wer hat asterion gebunden","wie ist asterion gebunden","asterions siegel"}},{q="Was sind Grells?",a="Grells sind kleine, bösartige Waldwesen, die in Kalimdors Wäldern heimisch sind. Sie haben scharfe Klauen, lieben Schmuckstücke, nisten sich oft in alten Ruinen ein und greifen Reisende an.",al={"was ist ein grell","geschichte der grells","grells der dunkelküste"}}},fx={["99bf1a9e"]={q="Warum möchte Asterion, dass dies getan wird?",a="Asterion ist in einer qualvollen spektralen Form gefangen, die durch ein altes magisches Siegel an die Ruinen von Bashal'Aran gebunden ist. Die jahrhundertelange Gefangenschaft hat seinen Verstand langsam zersetzt, und er sehnt sich nach Erlösung von dieser Qual. Durch die Untersuchung der Ohrringe, die die lokalen Kreaturen tragen, hofft er, den genauen Ort des Schutzzaubers, der ihn bindet, magisch auszukundschaften, damit er letztendlich zerstört werden kann.",al={"asterion beweggrund","warum asterion helfen","warum will asterion ohrringe"}},a8a71265={q="Warum benötigt Asterion Eure Hilfe, anstatt selbst zu handeln?",a="Asterion ist ein körperloser Geist, der durch mächtige Zauberei direkt an die Ruinen gebunden ist. Da er nicht in der Lage ist, sich weit über seinen unmittelbaren Ruheplatz hinaus zu wagen oder physisch gegen die Grells und Sprites zu kämpfen, verlässt er sich vollständig auf vorbeiziehende Sterbliche, die die Kreaturen jagen und ihre Schmuckstücke für seine Weissagungen sammeln.",al={"warum braucht asterion mich","warum kann asterion die ohrringe nicht holen","warum kann asterion nicht weg"}}},fp="11,257,23.299.0,18.346.0,16.183.0,38.133.0,20.187.0,43.223.1,29.145.0,16.164.0"}
P.entries["quest:95507"] = {n="Vrang's Game",s="Vrang schickt Euch durch ein Tal im Brachland, um seine Fallen zu überprüfen. Das Kleinwild, das sie fangen, kann ihm helfen, doch andere Wildtiere machen die Gegend gefährlich.",h="Vrang schickt Euch durch ein Tal im Brachland, um seine Fallen zu überprüfen.",kw={"brachland","kleinwild","gefangenes wild","fallen","tal","vrang","wildtiere"},sec={{t="Vrangs Fallen",b="Vrang hat Fallen über das ganze Tal verteilt und möchte, dass Ihr ihm alles Kleinwild bringt, das sie gefangen haben. Achtet auch auf die Wildtiere, denn sie können die Gegend gefährlich machen."}},faq={{q="Was möchte Vrang?",a="Vrang möchte, dass Ihr seine Fallen überprüft und ihm alles Kleinwild bringt, das sie gefangen haben.",al={"vrang fallen","vrang wild","was braucht vrang"}},{q="Wo sind Vrangs Fallen?",a="Vrangs Fallen sind über ein Tal im Brachland verteilt.",al={"wo sind die fallen","fallenstandort","brachland fallen"}},{q="Was ist in der Nähe der Fallen gefährlich?",a="Andere Wildtiere in der Nähe der Fallen können gefährlich sein, wenn Ihr nicht aufpasst.",al={"gefahr in der nähe","andere tiere","gefahr durch wildtiere"}}},fp="12,154,13.185.0,21.82.0,24.59.0,35.81.0"}
P.entries["quest:95508"] = {n="Unwelcome Guests",s="Ihr habt jemandem geholfen, eine Begegnung mit ungebetenen Gästen zu überleben, und diese Person ist Euch dankbar. Was Euch zusammengeführt hat, bleibt unklar.",h="Ihr habt jemandem geholfen, eine Begegnung mit ungebetenen Gästen zu überleben, und diese Person ist Euch...",kw={"schuld","hilfe","überleben","dank","unwelcome guests"},faq={{q="Was ist hier geschehen?",a="Ihr habt dem Sprecher geholfen, eine Begegnung zu überleben, doch er nennt keine Einzelheiten dazu.",al={"was ist geschehen","unwelcome guests","ärger mit gästen"}},{q="Wer dankt mir?",a="Der Sprecher, der Euch dankt, wird nicht namentlich genannt.",al={"wer ist das","wer hat mir gedankt","questgeber"}},{q="Warum steht er in meiner Schuld?",a="Der Sprecher sagt, dass Ihr ihm geholfen habt zu überleben, erklärt aber nicht, was geschehen ist.",al={"warum mir danken","warum steht er in meiner schuld","ihm geholfen"}}},fp="16,128,19.82.0,19.40.0,24.77.0"}
P.entries["quest:95534"] = {n="Strahnbrad Mystery",s="Ein angesengter Zettel bittet Euch, seltsame Vorgänge am alten Blasebalg in Strahnbrad zu untersuchen. Berichtet in Hillsbrad, was Ihr herausfindet.",h="Ein angesengter Zettel bittet Euch, seltsame Vorgänge am alten Blasebalg in Strahnbrad zu untersuchen.",kw={"feuerelementar","feuermagie","hillsbrad","alter blasebalg","angesengter zettel","strahnbrad","strahnbrad rätsel"},sec={{t="Der angesengte Zettel",b="Ein in Strahnbrad gefundener Zettel warnt, dass der alte Blasebalg sich offenbar bewegt, wenn niemand hinsieht. Wer ihn schrieb, tut die Geschichte als Geistermärchen ab, besteht aber darauf, dass Ihr vor seiner Rückkehr die Wahrheit aufdeckt. Der Verfasser glaubt, dass große Macht in Strahnbrad liegt, und Feuermagie hat den Rest der Nachricht verbrannt."},{t="Eure Erkenntnisse",b="In Hillsbrad hören die Stadtbewohner Euren Bericht über den alten Blasebalg in Strahnbrad. Ein Feuerelementar lebte darin, doch wie er dorthin gelangte, bleibt ein Rätsel."}},faq={{q="Was ist seltsam an dem alten Blasebalg?",a="Ein angesengter Zettel behauptet, der alte Blasebalg in Strahnbrad erwache zum Leben, wenn niemand hinsieht.",al={"rätsel um alten blasebalg","blasebalg bewegt sich","strahnbrad blasebalg"}},{q="Wer hat den Zettel hinterlassen?",a="Der Zettel nennt seinen Verfasser nicht beim Namen; darin steht, dass er zurückkehren wird.",al={"wer schrieb den zettel","verfasser des angesengten zettels","rätselhafter zettel"}},{q="Was sagt der Zettel über Strahnbrad?",a="Der Verfasser glaubt, dass große Macht in Strahnbrad liegt.",al={"strahnbrad macht","große macht dort","was ist in strahnbrad"}},{q="Wo berichte ich, was ich herausfinde?",a="Ihr werdet gebeten, Eure Erkenntnisse in der Stadt in Hillsbrad zu melden.",al={"wo erkenntnisse melden","hillsbrad bericht","in der stadt berichten"}}},fp="18,128,15.291.0,13.167.1,38.90.0,18.60.0,40.51.0,30.59.0"}
P.entries["quest:95561"] = {n="Apple of My Eye",s="In Burg Farholde bittet Tessa Dawnbright Euch, Äpfel für die wählerische Baby Emma zu suchen. Sie möchte dem Kind einen Brei machen.",h="In Burg Farholde bittet Tessa Dawnbright Euch, Äpfel für die wählerische Baby Emma zu suchen.",kw={"apfelbrei","mein augenstern","baby","emma","burg farholde","frische äpfel","tessa dawnbright"},sec={{t="Ein wählerisches Kind",b="Tessa Dawnbright kümmert sich in Burg Farholde um Baby Emma, deren Schreie durch die Burg hallen. Tessa sagt, sie habe alle Hände voll zu tun, während ihr Mann Vorräte sammelt. Sie bittet Euch, frische Äpfel zu suchen, damit sie Emma einen Brei machen kann."}},faq={{q="Wer bittet um Äpfel?",a="Tessa Dawnbright bittet Euch, in Burg Farholde Äpfel für Baby Emma zu suchen.",al={"äpfel für tessa","wer braucht äpfel","auftraggeberin für äpfel"}},{q="Warum braucht Tessa Äpfel?",a="Tessa möchte der wählerischen Baby Emma einen Brei machen.",al={"warum äpfel","äpfel fürs baby","wofür sind äpfel"}},{q="Wo braucht Tessa Hilfe?",a="Tessa bittet in Burg Farholde um Hilfe.",al={"wo ist tessa","äpfel in burg farholde","fundort der äpfel"}},{q="Warum kann Tessa die Vorräte nicht selbst holen?",a="Tessa sagt, sie habe alle Hände voll damit zu tun, sich um Emma zu kümmern, während ihr Mann Vorräte besorgt.",al={"tessas mann","wo ist ihr mann","warum kann sie nicht gehen"}}},fp="15,115,13.244.0,25.72.0,27.47.0,27.37.0,41.88.0"}
P.entries["quest:95562"] = {n="Cut Off the Heads",s="Lehrling Claire bittet Euch, die Bedrohung unter Sonnengrund zu beenden. Der Herr der Höhle ist Chogg'Zac, und Claire will, dass Ihr seine Köpfe zurückbringt.",h="Lehrling Claire bittet Euch, die Bedrohung unter Sonnengrund zu beenden.",kw={"lehrling claire","höhlen","chogg'zac","köpfe abschlagen","lady amberhall","oger","sonnengrund"},sec={{t="Claires Bitte",b="Bevor Ihr die Höhlen unter Sonnengrund betretet, erzählt Euch Lehrling Claire, warum sie gekommen ist. Lady Amberhall schickte sie, um Proben zu sammeln, doch Claire kehrte zurück, weil Sonnengrund einst ihre Heimat war. Monster verseuchen den Ort noch immer, und sie will, dass Ihr ihren Herrn erschlagt. Chogg'Zac wartet tief unten, und Claire bittet Euch, die Köpfe zurückzubringen."},{t="Nach dem Kampf",b="Als Ihr zurückkehrt, fragt Claire, ob Chogg'Zac und die Oger tot sind. Sie heißt Eure Tat gut und drängt Euch, mit ihr aufzubrechen."}},faq={{q="Wer schickt mich unter Sonnengrund?",a="Lehrling Claire bittet Euch, Chogg'Zac in den Höhlen unter Sonnengrund zu töten und die Köpfe zurückzuholen.",al={"wer schickte mich","claires auftrag","lehrling claire"}},{q="Warum kam Claire nach Sonnengrund?",a="Sonnengrund war Claires Heimat, bevor der Krieg sie ihr nahm, und sie konnte nicht ruhen, solange dort noch Monster waren.",al={"warum claire hier","claires heimat","hintergrund zu sonnengrund"}},{q="Wer ist Chogg'Zac?",a="Chogg'Zac ist der Herr der Höhlen unter Sonnengrund.",al={"chogg zac","höhlenherr","ogreboss"}},{q="Was möchte Claire, dass ich zurückbringe?",a="Claire bittet Euch, die Köpfe zurückzuholen, nachdem Ihr Chogg'Zac getötet habt.",al={"was zurückbringen","köpfe für claire","was zurückholen"}}},fp="17,139,13.330.0,15.134.1,42.100.0,34.115.0,17.56.0,39.62.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Zwischen den verfallenen Säulen von Bashal'Aran sucht Asterion Befreiung aus seinem Gefängnis. Er hat die bindende Magie zu den Satyrn zurückverfolgt, die den Grells befehlen. Nun bittet er Reisende, das Alte Mondsteinsiegel zu bergen.",h="Zwischen den verfallenen Säulen von Bashal'Aran sucht Asterion Befreiung aus seinem Gefängnis.",kw={"altes mondsteinsiegel","asterion","bashal'aran","dunkelküste","grell","kaldorei","nachtelfengeist","satyr"},ang={["class:Druid"]="Als Druide wisst Ihr, dass der Einfluss der Satyrn die Tierwelt der Dunkelküste noch immer verdirbt. Er stört auch uralte Geister, die friedlich im Kreislauf der Natur ruhen sollten.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Kalimdors Nordküste zu sichern, indem Ihr die Ruinen der Dunkelküste von der Verderbnis der Satyrn reinigt. Diese Arbeit hilft auch den Kaldorei, ihre tragische Vergangenheit ruhen zu lassen.",["race:NightElf"]="Als Nachtelf erinnert Euch Bashal'Aran an die uralte Vergangenheit Eures Volkes. Verbliebene Ahnen werden von Satyrn an die Erde gekettet, deren Art den dämonischen Verrat des Sundering verkörpert."},sec={{t="Ein Gefängnis aus uraltem Stein",b="Seit mehr als tausend Jahren ist Asterion in den Ruinen von Bashal'Aran gebunden. Die Marmorsäulen markieren die Grenzen seines Gefängnisses. Weder seine Kraft noch seine uralte Magie können ihn über sie hinaustragen. Ein verfluchtes Relikt hält ihn dort fest.\n\nÜber die Jahrhunderte hat Asterion das Blätterdach der Dunkelküste betrachtet. Er fragt sich, ob der verwitterte Stein um ihn herum ihn jemals freigeben könnte."},{t="Satyrn und das Mondsteinsiegel",b="Grells in der Nähe trugen Spuren der Magie, die Asterion bindet. Daraus schloss er, dass das Alte Mondsteinsiegel die Quelle der Verzauberung war. Die Satyrn, die den Grells befehlen, besitzen das Siegel nun. Diese dämonischen Nachtelfen durchstreifen die uralten Haine und bewachen das Relikt. Asterion braucht Reisende, die das Siegel bergen, damit seine bindende Macht gebrochen werden kann."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein uralter Nachtelfengeist, der zwischen den verfallenen Säulen von Bashal'Aran gefangen ist. Uralte Magie bindet ihn seit mehr als tausend Jahren und hindert ihn daran, sein steinernes Gefängnis zu verlassen oder ins Jenseits einzugehen.",al={"wer ist asterion","asterion hintergrundgeschichte","geist in bashal aran"}},{q="Warum haben die Satyrn das Alte Mondsteinsiegel?",a="Die Satyrn befehligen die wilden Grells im Norden der Dunkelküste. Asterion spürte in den Grells Spuren der Magie, die ihn bindet, und schloss daraus, dass die Satyrn das Alte Mondsteinsiegel besaßen, die Quelle seiner Gefangenschaft.",al={"warum haben satyrn das siegel","satyr mondsteinsiegel","altes mondsteinsiegel"}},{q="Was geschieht, sobald das Siegel geborgen ist?",a="Wenn Asterion das geborgene Alte Mondsteinsiegel erhält, das Relikt, das ihn jahrhundertelang gebunden hat, kann es zerbrochen werden. Dann wird er wieder frei durch die Wälder wandeln können.",al={"was bewirkt das siegel","das siegel bergen"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran ist eine uralte Nachtelfenruine an den nebligen Ufern im Norden der Dunkelküste. Einst eine prächtige Siedlung oder heilige Enklave, liegt sie nun in Trümmern, heimgesucht von Grells, Satyrn und gefangenen Geistern aus einer früheren Zeit.",al={"bashal aran hintergrundgeschichte","was ist bashal aran"}},{q="Wie lange ist Asterion hier schon gefangen?",a="Asterion ist seit mehr als tausend Jahren gefangen. Weder Kraft noch Magie können die Grenze durchbrechen, und über die Jahrhunderte hat er sich gefragt, ob er jemals frei sein wird.",al={"wie alt ist asterion","wie lange gefangen"}},{q="Kann Asterion den Schrein einfach verlassen?",a="Nein. Das Alte Mondsteinsiegel hält eine Barriere um den Schrein aufrecht, und die Steinsäulen hindern Asterions Geist daran, über sie hinauszugelangen.",al={"kann asterion fortgehen","warum ist der geist gefangen"}}},fx={["31aed888"]={q="Warum möchte Asterion, dass das Siegel geborgen wird?",a="Asterion verzweifelt nach Freiheit. Das alte Relikt dient als bindender Anker seines ewigen Gefängnisses und hält seinen Geist im zerstörten Schrein gefangen. Seit über tausend Jahren starrt er an den Steinsäulen vorbei, unfähig, ihren Halt durch Stärke oder Zauberei zu brechen. Die Bergung des Artefakts ist der einzige Weg, es zu zerstören und es ihm endlich zu ermöglichen, wieder frei durch die Wälder zu wandeln.",al={"warum will asterion das erledigt haben","asterion beweggrund","warum asterion helfen"}},["5f1ff286"]={q="Was ist das Alte Mondsteinsiegel?",a="Das Alte Mondsteinsiegel ist ein magisches Relikt, das als Schlüssel zu Asterions Gefangenschaft dient. Es erschafft eine immaterielle Barriere zwischen den Säulen von Bashal'Aran, die wie eine ewige Zelle funktioniert, die kein Zauber oder seine physische Stärke durchbrechen kann. Solange das Siegel in den Händen der nahegelegenen verderbten Kräfte besteht, bleibt Asterion an den Schrein gebunden.",al={"was ist das alte mondsteinsiegel","was bewirkt das mondsteinsiegel","zweck des alten mondsteinsiegels"}},c7650517={q="Warum werdet Ihr gegen die örtlichen Satyrn ausgesandt?",a="Die Satyrn befehligen die abscheulichen Grells, die in den Ruinen von Bashal'Aran wimmeln. Da die niederen Grells Spuren der Verzauberung des Siegels trugen, folgerte Asterion, dass ihre Meister das Artefakt selbst in Besitz genommen haben müssen. Die Satyrn sind verderbt und von alten magischen Relikten angezogen, weshalb sie das Siegel in ihrem Lager halten und zu Eurem Ziel machen.",al={"wer sind die satyrn in bashal'aran","warum die satyrn bekämpfen","wer hat das siegel"}},["341831b6"]={q="Warum kann Asterion das Siegel nicht selbst zurückholen?",a="Asterion kann die Grenzen des Schreins nicht verlassen. Die Magie des Siegels hält ihn völlig innerhalb seines Umkreises gebunden und behandelt die Steinsäulen als unüberwindbare Gitter. Er besitzt weder die Stärke noch die Zauberei, um seine Gefangenschaft zu durchbrechen, was ihn völlig abhängig von einem Außenstehenden macht, der in seinem Namen in die Lager der Satyrn eindringt.",al={"warum braucht asterion mich","warum kann asterion das siegel nicht holen","warum ich für asterion"}}},fp="11,211,25.361.0,29.356.0,16.200.0,50.207.0,40.163.1,20.218.0,40.178.0,46.141.0"}
P.entries["quest:95601"] = {n="The Purple Ones",s="Clubtoe bittet Euch, die Rituale von Twilight's Hammer in Sonnengrund zu beenden. Die Riten stärken einige Oger und töten andere.",h="Clubtoe bittet Euch, die Rituale von Twilight's Hammer in Sonnengrund zu beenden.",kw={"clubtoe","empowered brutes","oger","sonnengrund","die purple ones","twilight ritualists","twilight's hammer"},sec={{t="Riten in Sonnengrund",b="In Sonnengrund schickt Clubtoe Euch gegen die Twilight Ritualists und Empowered Brutes. Ein toter Oger scheint einer der Freunde zu sein, nach denen Clubtoe gesucht hat. Die Rituale stärken einige Mitglieder und töten noch mehr. Deshalb will Clubtoe die Ritualists und ihre Schöpfungen aufhalten, bevor sie sich ausbreiten."}},faq={{q="Wer ist Clubtoe?",a="Clubtoe bittet Euch, die Twilight Ritualists in Sonnengrund aufzuhalten.",al={"clubtoe","wer ist clubtoe"}},{q="Was tun die Purple Ones?",a="Die Twilight Ritualists vollziehen Riten an ihren Mitgliedern. Einige werden gestärkt, während noch mehr getötet werden.",al={"purple ones","was tun die purple ones"}},{q="Warum will Clubtoe die Rituale aufhalten?",a="Clubtoe fürchtet, dass sich die Ritualists und ihre Monstrositäten ausbreiten.",al={"warum die riten aufhalten","warum ritualisten töten"}},{q="Was ist mit Clubtoes Freunden geschehen?",a="Ein toter Oger scheint einer der Freunde zu sein, nach denen Clubtoe gesucht hat.",al={"clubtoes freunde","wo sind die freunde"}},{q="Wo ist Clubtoe?",a="Clubtoe ist in Sonnengrund.",al={"clubtoes ort","clubtoe in sonnengrund"}}},fp="15,111,19.274.0,15.76.0,31.98.0,42.65.0,35.71.0,17.25.0"}
P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe bittet Euch, die leuchtenden Ritualkreise unter Sonnengrund zu zerschlagen. Das Licht macht ihn krank, und er fürchtet Chogg'Zacs Zorn, wenn er allein handelt.",h="Clubtoe bittet Euch, die leuchtenden Ritualkreise unter Sonnengrund zu zerschlagen.",kw={"höhlen","chogg'zac","clubtoe","licht","glänzende bilder","krank machende lichter","sonnengrund","zwielicht-ritualkreise"},sec={{t="Ein krank machendes Leuchten",b="Clubtoe arbeitet in den Höhlen unter Sonnengrund und zerschlägt Gestein für Chogg'Zac. Er entdeckt leuchtende Lichter im Stein, und die anderen malen Bilder damit. Das Leuchten macht Clubtoe krank, doch er fürchtet, Chogg'Zac werde ihn bestrafen, wenn er die Bilder zerstört. Ihr sollt die Twilight Ritual Circles zerstören, und Clubtoe hofft, dass ihn das Licht dann nicht mehr plagt."}},faq={{q="Wer bittet mich, die Kreise zu zerstören?",a="Clubtoe bittet Euch, die Twilight Ritual Circles unter Sonnengrund zu zerstören.",al={"wer ist clubtoe","clubtoe-quest","wer will die lichter zerschlagen"}},{q="Warum will Clubtoe die Lichter zerschlagen?",a="Das Licht macht Clubtoe krank, und er will die leuchtenden Bilder zerschlagen.",al={"warum die lichter zerschlagen","lichter machen clubtoe krank","clubtoe hasst licht"}},{q="Wer ist Chogg'Zac?",a="Chogg'Zac ist Clubtoes Boss, und Clubtoe fürchtet, er werde wütend, wenn die Kreise zerstört werden.",al={"chogg zac","clubtoes boss","großer boss"}},{q="Was sind die glänzenden Bilder?",a="Es sind Twilight Ritual Circles, die überall in den Höhlen unter Sonnengrund zu finden sind. Clubtoe nennt sie leuchtende Bilder.",al={"glänzende bilder","zwielichtkreise","was sind die lichter"}},{q="Was tut Clubtoe in den Höhlen?",a="Clubtoe zerschlägt Gestein für Chogg'Zac und hat leuchtendes Licht im Stein entdeckt.",al={"clubtoes arbeit","gestein zerschlagen","was macht clubtoe"}},{q="Geht es Clubtoe besser, nachdem die Kreise zerschlagen sind?",a="Nachdem Ihr die Kreise zerschlagen habt, sagt Clubtoe, dass es ihm schon besser geht.",al={"clubtoe abschließen","hat das zerschlagen geholfen","lichter machen ihn gesund"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95603"] = {n="Bats in the Belfry",s="Sister Rowland bittet Euch, die Fledermäuse aus Farholde Cathedral zu vertreiben. Sie hofft, dass die Kirche nach dem Ende der Kämpfe wieder dem Licht dienen wird.",h="Sister Rowland bittet Euch, die Fledermäuse aus Farholde Cathedral zu vertreiben.",kw={"fledermäuse im glockenturm","brother lowley","kirche","farholde cathedral","licht","nistende dämmerungsfledermäuse","sister rowland"},sec={{t="Die Kathedrale",b="Sister Rowland bittet Euch um Hilfe in Farholde Cathedral, wo Dämmerungsfledermäuse in den oberen Stockwerken nisten. Sie und brother Lowley dienen Farholde nun in einer weltlicheren Funktion, und die Kirche ist verfallen. Rowland möchte sie in Schuss halten, fürchtet jedoch, dass die Kämpfe noch lange andauern könnten."}},faq={{q="Warum gibt es Fledermäuse in der Kathedrale?",a="Eine Fledermauskolonie hat sich in den oberen Stockwerken von Farholde Cathedral eingenistet.",al={"fledermäuse in der kathedrale","fledermäuse im glockenturm","warum fledermäuse"}},{q="Wer bittet mich, die Fledermäuse zu vertreiben?",a="Sister Rowland bittet Euch, die nistenden Fledermäuse aus Farholde Cathedral zu vertreiben.",al={"wer hat das gegeben","sister rowland","rowland fledermäuse"}},{q="Warum möchte Sister Rowland die Kirche in Schuss halten?",a="Sister Rowland hofft, dass das Licht nach dem Ende der Kämpfe in die Kirche zurückkehren kann.",al={"warum die kirche erhalten","kirche instand halten","rowland kirche"}},{q="Was ist mit der Kirche geschehen?",a="Die Kirche ist verfallen, seit Sister Rowland und brother Lowley Farholde in einer weltlicheren Funktion dienen.",al={"verlassene kirche","warum ungenutzt","farholde kirche"}}},fp="18,134,13.305.0,36.79.0,30.76.0,62.79.0,28.124.0"}
P.entries["quest:95613"] = {n="Keeping the Light On",s="Sister Rowland bittet Euch, Holy Candles zur Burg Farholde zu bringen. In der Kirchenkrypta hält sie die Kerzen für die Gefallenen brennend, damit ihre Opfer in Erinnerung bleiben.",h="Sister Rowland bittet Euch, Holy Candles zur Burg Farholde zu bringen.",kw={"kirche","krypta","gefallene","burg farholde","heilige kerzen","das licht brennen lassen","marla","sister rowland"},sec={{t="Kerzen für die Gefallenen",b="Sister Rowland auf Burg Farholde bittet Euch um Holy Candles. Obwohl in der Kirche keine Gottesdienste mehr stattfinden, hält sie Kerzen auf den Gräbern der Gefallenen in ihrer Krypta brennend. Ihre Flammen zeigen, dass man der Toten gedenkt und ihre Opfer nicht vergebens waren. Marla, eine Freundin von Sister Rowland, hat vielleicht Kerzen übrig. Sie wohnt im Haus direkt neben der Kirche."}},faq={{q="Warum hält Sister Rowland Kerzen brennend?",a="Sister Rowland hält Kerzen auf den Gräbern in der Kirchenkrypta brennend, damit man der Gefallenen gedenkt und ihre Opfer nicht vergebens waren.",al={"warum kerzen","kerzen in der krypta","kerzen für die toten"}},{q="Wohin möchte Sister Rowland die Kerzen gebracht haben?",a="Sister Rowland bittet Euch, ihr die Holy Candles auf Burg Farholde zu bringen.",al={"wohin kerzen bringen","kerzen liefern","rowlands kerzen"}},{q="Wer ist Marla?",a="Marla ist eine Freundin von Sister Rowland. Sie wohnt im Haus direkt neben der Kirche und hat vielleicht Kerzen übrig.",al={"marlas kerzen","wer hat kerzen","kerzenquelle"}},{q="Finden in der Kirche noch Gottesdienste statt?",a="In der Kirche finden keine Gottesdienste mehr statt, doch Sister Rowland hält weiterhin Kerzen in ihrer Krypta brennend.",al={"gottesdienst in der kirche","kirche geschlossen","kein gottesdienst"}}},fp="20,158,22.365.0,41.133.0,51.70.0,13.113.0,37.107.0"}
P.entries["quest:95615"] = {n="In Memoriam",s="Sister Rowland bittet Euch, die Gedenkkerzen in Burg Farholde wieder anzuzünden. Diese kleine Tat ehrt die Toten und hilft, die Kirche am Leben zu erhalten.",h="Sister Rowland bittet Euch, die Gedenkkerzen in Burg Farholde wieder anzuzünden.",kw={"friedhof der kapelle","kirche","burg farholde","gräber","zum gedenken","anzünden","gedenkkerzen","sister rowland"},sec={{t="Kerzen für die Gefallenen",b="In Burg Farholde bittet Euch Sister Rowland, den Friedhof der Kapelle zu pflegen. Stellt frische Kerzen auf drei Gräber, deren alte Flammen erloschen sind, und gedenkt still der Gefallenen."}},faq={{q="Wer bittet mich, die Kerzen anzuzünden?",a="Sister Rowland in Burg Farholde bittet Euch, Gedenkkerzen auf dem Friedhof der Kapelle anzuzünden.",al={"wer ist sister rowland","sister rowland kerzen"}},{q="Wohin kommen die Kerzen?",a="Stellt die Gedenkkerzen auf Gräber auf dem Friedhof der Kapelle in Burg Farholde.",al={"kerzenstandort","wo sind die gräber"}},{q="Auf wie vielen Gräbern müssen Kerzen stehen?",a="Sister Rowland bittet Euch, drei Gedenkkerzen auf Gräber zu stellen.",al={"anzahl der kerzen","wie viele kerzen"}},{q="Warum sollen die Kerzen angezündet werden?",a="Die Kerzen ehren die Verstorbenen und helfen, die Kirche am Leben zu erhalten.",al={"warum kerzen","wofür ist das"}}},fp="11,132,22.184.0,33.91.0,24.78.0,29.66.0,22.69.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Ein Trupp Soldaten der Kul Tiraner durchsucht das Tal, und sein Ziel ist unbekannt. Sie haben nahe einer zerstörten Karawane im Süden ihr Lager aufgeschlagen und damit die Aufmerksamkeit örtlicher Späher erregt.",h="Ein Trupp Soldaten der Kul Tiraner durchsucht das Tal, und sein Ziel ist unbekannt.",kw={"karawane","kul tiras","soldaten","trouble in the valley","tal","zerstörte karawane"},ang={["race:Human"]="Als Mensch erkennt Ihr vielleicht das Meergrün und die Ankerfarben von Kul Tiras. Soldaten aus dieser zurückgezogen lebenden Seefahrernation sind im Tal ein seltener und unerwarteter Anblick."},sec={{t="Verdächtige Aktivitäten im Tal",b="Ein Schütze, der das Tiefland beobachtete, entdeckte menschliche Soldaten, die den Talboden durchsuchten. Durch sein Zielfernrohr erkannte er die Wappen und Uniformen von Kul Tiras. Bewaffnete Fremde gehen hier selten so offen vor, und ihre Anwesenheit hat Alarm ausgelöst."},{t="Die zerstörte Karawane",b="Die Soldaten haben nahe einer zerstörten Karawane im Süden ihr Lager aufgeschlagen. Was sie zwischen den Trümmern suchen, bleibt unbekannt. Örtliche Beobachter betrachten ihre bewaffnete Anwesenheit als unmittelbare Bedrohung, weshalb Ermittler entsandt werden, um sie auszuschalten und den Zweck ihrer Suche aufzudecken."}},faq={{q="Was machen Soldaten der Kul Tiraner im Tal?",a="Ein Scharfschütze entdeckte Soldaten der Kul Tiraner, die das Tal unter ihm durchsuchten. Sie schlugen nahe einer zerstörten Karawane im Süden ihr Lager auf, und örtliche Späher werden entsandt, um ihr Ziel zu ergründen.",al={"warum kul tiraner hier","soldaten von kul tiras im tal","was machen kul tiraner"}},{q="Wo befindet sich das Lager der Kul Tiraner?",a="Die Soldaten der Kul Tiraner lagern nahe einer zerstörten Karawane südlich des Aussichtspunkts über dem Tal.",al={"standort der zerstörten karawane","wo ist das lager von kul tiras","standort der karawane"}},{q="Wie wurde die Anwesenheit der Kul Tiraner entdeckt?",a="Ein Späher, der das Tal beobachtete, betrachtete die Menschengruppe durch ein Gewehrzielfernrohr und erkannte Kul Tiras an ihren Uniformen und Abzeichen.",al={"wie wurden sie identifiziert","uniformen von kul tiras"}},{q="Was ist das Ziel der Untersuchung des Lagers?",a="Ihr werdet nach Süden zur zerstörten Karawane geschickt, um die Soldaten der Kul Tiraner zu stellen und herauszufinden, weshalb sie das Gebiet durchsuchen.",al={"was ist das ziel","trouble in the valley ziele"}},{q="Warum werden die Soldaten der Kul Tiraner als Feinde behandelt?",a="Die Soldaten sind bewaffnete Fremde, die ohne Erklärung das Land um eine zerstörte Karawane durchsuchen. Späher sehen in ihnen eine Bedrohung, die bezwungen werden muss, damit ihre Absichten aufgedeckt werden können.",al={"warum gegen kul tiras kämpfen","sind kul tiraner feindselig"}},{q="Wer entdeckte die Soldaten im Tal?",a="Walton, der einsiedlerische Gerber, der das Tal beobachtet, entdeckte die Soldaten durch sein Gewehrzielfernrohr. Er heuerte einen Abenteurer an, um sie auszuschalten und herauszufinden, warum sie dort waren.",al={"wer entdeckte die soldaten","wer gab die quest"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95642"] = {n="Abominable Magics",s="Lehrling Claire bittet Euch, Proben der Magie von Twilight's Hammer aus einer Höhle unter Sonnengrund zu sammeln. Farholde braucht die Proben, damit sie die Hexerei des Kults untersuchen kann.",h="Lehrling Claire bittet Euch, Proben der Magie von Twilight's Hammer aus einer Höhle unter Sonnengrund zu...",kw={"abscheuliche magie","lehrling claire","ashe amberhall","crystal catalyst","farholde","flusslande","sonnengrund","twilight's hammer","hexerei"},sec={{t="Claires Bitte",b="Ashe Amberhall schickte Claire in die Flusslande, um Twilight's Hammer zu untersuchen, wo Kultisten nach etwas graben. Claire braucht eine Probe ihrer Hexerei, um sie zu verstehen. Ihr tragt einen Crystal Catalyst, der verzaubert wurde, um die Macht des Kults aus Runen oder von Kultisten aufzunehmen. Claire sagt, Farholde brauche dringend, was er sammelt."},{t="Eine mächtige Probe",b="Als Ihr zurückkehrt, berührt Claire den Kristall und zuckt zurück, als die Magie darin knistert. Die gesammelte Macht ist stärker, als sie befürchtet hatte, und sie sagt, man müsse vorsichtig damit umgehen."}},faq={{q="Wer bittet um die Proben?",a="Lehrling Claire bittet Euch, für sie Proben der Magie von Twilight's Hammer zu sammeln.",al={"wer will proben","claires bitte um proben"}},{q="Warum braucht Claire die Proben?",a="Claire möchte die Hexerei des Kults untersuchen und sagt, Farholde brauche die Proben dringend.",al={"warum proben","wofür sind die proben"}},{q="Wo graben die Kultisten?",a="Twilight's Hammer gräbt in den Flusslanden nach etwas.",al={"wo gräbt twilight's hammer","kult gräbt"}},{q="Was bewirkt der Crystal Catalyst?",a="Der verzauberte Crystal Catalyst nimmt die Macht der Magie von Twilight's Hammer aus Runen oder von Kultisten auf.",al={"kristallding","zweck des catalysts"}},{q="Wer schickte Claire zur Untersuchung?",a="Ashe Amberhall schickte Claire, um Twilight's Hammer zu untersuchen.",al={"wer schickte claire","amberhall"}}},fp="17,168,16.318.0,15.181.1,30.80.0,33.94.0,31.66.0,34.99.0,31.60.0"}
P.entries["quest:95643"] = {n="Indiscriminate Purge",s="Eine Lehrling von Lady Amberhall bittet Euch, die von Leere durchdrungenen Oger unter Sonnengrund zu bekämpfen. Der Hammer des Zwielichts wird die Verluste spüren.",h="Eine Lehrling von Lady Amberhall bittet Euch, die von Leere durchdrungenen Oger unter Sonnengrund zu...",kw={"lehrling","empowered brutes","wahllose säuberung","lady amberhall","sonnengrund","twilight ritualists","hammer des zwielichts","von leere durchdrungene oger"},sec={{t="Unter Sonnengrund",b="Oger und ihre Meister nahmen Lady Amberhalls Lehrling in den Höhlen unter Sonnengrund gefangen. Sie bittet Euch, dort die Twilight Ritualists und Empowered Brutes zu erledigen. Die Verluste werden den Hammer des Zwielichts treffen."}},faq={{q="Wer bittet unter Sonnengrund um Hilfe?",a="Lady Amberhalls Lehrling bittet Euch, die Oger in den Höhlen unter Sonnengrund zu töten.",al={"lehrling von amberhall","wer bittet um hilfe","quest von lady amberhall"}},{q="Was befindet sich in den Höhlen?",a="In den Höhlen unter Sonnengrund hausen von Leere durchdrungene Oger und ihre Meister.",al={"höhle von sonnengrund","welche oger","feinde in der höhle"}},{q="Wer sind die Meister der Oger?",a="Die Lehrling bezeichnet die Meister der Oger als Twilight Ritualists.",al={"meister der oger","twilight ritualists","wer kontrolliert die oger"}},{q="Welche Oger nennt die Lehrling?",a="Sie nennt Empowered Brutes unter den Bestien in den Höhlen.",al={"empowered brutes","welche oger töten","ogernamen"}},{q="Warum bittet die Lehrling Euch, sie zu töten?",a="Sie sagt, dass von Fanatikern mit einem Ziel nichts Gutes ausgeht, ob sie nun gestärkt sind oder nicht.",al={"warum die oger töten","warum die säuberung","warum amberhall helfen"}},{q="Was sagt die Lehrling über ihre eigenen Fähigkeiten?",a="Sie sagt, dass sie die Dinge normalerweise allein bewältigen kann, doch die Oger nahmen sie gefangen.",al={"lehrling gefangen","fähige amberhall-lehrling","was ist ihr zugestoßen"}}},fp="20,133,16.224.0,37.89.0,21.71.0,29.70.0,37.57.0,45.86.0,53.90.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel der Sumpfhüter spürt Verderbnis, die durch eine Bergschlucht ins Süßwasser des Sumpflands fließt. Er schickt Euch zu den Ausgrabungsstätten im Hochland, um den Root Core eines Highland Horrors zu holen, und warnt dann, dass die Grabungen eine uralte Energie aufrütteln und die ganze Region gefährden.",h="Rethiel der Sumpfhüter spürt Verderbnis, die durch eine Bergschlucht ins Süßwasser des Sumpflands fließt.",kw={"verderbnis","ausgrabungsstätten","highland horror","horrors in the highland","rethiel","rethiel der sumpfhüter","root core","sumpfland"},ang={["class:Druid"]="Als Druide könnt Ihr spüren, wie sich das natürliche Gleichgewicht durch Wurzeln und Wasserläufe hindurch verschiebt. Ihr erkennt womöglich, wie plötzlich uralte Verderbnis das Leben im Süßwasser bedroht.",["faction:Alliance"]="Als Forscher der Allianz wisst Ihr, dass die Erzsucher an den Ausgrabungsstätten in den Bergen Gefahr laufen, uralte Kräfte unter der Erde aufzurütteln.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Grabungen im Hochland mehr als nur uralte Relikte aufgestört haben. Rethiel drängt die Ausgräber, aufzuhören, bevor schlimmere Übel erwachen."},sec={{t="Verderbnis in der Schlucht",b="Rethiel der Sumpfhüter spürt tief im Sumpfland, wie sich das Land verändert. Durch eine Bergschlucht gelangt üble Verderbnis ins Hochland und befällt die dortigen Süßwasserkreaturen. Das Leben im Tiefland wurde vom Brackwasser geprägt, doch diese Kreaturen haben das schützende Salz des Meeres nie kennengelernt. Rethiel fürchtet, dass sie dem sich ausbreitenden Übel nicht standhalten können. Er bittet Euch, zu den Ausgrabungsstätten hinaufzusteigen, einen Highland Horror zu erschlagen und seinen Root Core zurückzubringen."},{t="Eine uralte Regung",b="Als Ihr Rethiel den Root Core des Highland Horrors bringt, bestätigt er seine Befürchtungen: Eine uralte Energie hat begonnen, sich zu regen. Die Kreaturen des Hochlands leiden an keiner gewöhnlichen Krankheit. Die jüngsten Grabungen haben das Leiden ausgelöst. Rethiel warnt die Ausgräber, sofort aufzuhören. Ihre Neugier könnte etwas weit Schlimmeres auf das Sumpfland loslassen und alle in der Region gefährden."}},faq={{q="Wer bietet die Quest Horrors in the Highland an?",a="Rethiel der Sumpfhüter, ein uralter Beschützer des Sumpflands, bietet die Aufgabe an, nachdem er Verderbnis gespürt hat, die durch eine nahe Bergschlucht sickert.",al={"wer vergibt horrors in the highland","horrors in the highland questgeber","rethiel quest"}},{q="Wo sind Highland Horrors zu finden?",a="Highland Horrors leben an den Ausgrabungsstätten im höher gelegenen Gelände oberhalb des Tieflands, nahe der Bergschlucht, durch die Verderbnis sickert.",al={"wo sind highland horrors","highland horror fundort","wo highland horror finden"}},{q="Warum sind die Kreaturen des Hochlands so anfällig für Verderbnis?",a="Die Süßwasserkreaturen des Hochlands haben das schützende Salz des Meeres nie kennengelernt und sind der sich ausbreitenden Verderbnis daher wehrlos ausgeliefert.",al={"warum sind die kreaturen verderbt","warum sind hochlandkreaturen verderbt","ungesalzenes wasser verderbnis"}},{q="Was ist der Root Core eines Highland Horrors?",a="Der Root Core eines Highland Horrors ist das Herz der verderbten Kreatur. Rethiel braucht ihn, um die unnatürliche Macht zu untersuchen, die sich durch die Wasserläufe ausbreitet, und das Wesen der Verderbnis zu ergründen.",al={"was ist der root core","highland horror root core","warum den root core mitnehmen"}},{q="Was entdeckt Rethiel, wenn Ihr den Root Core zurückbringt?",a="Als Ihr den Root Core zurückbringt, entdeckt Rethiel, dass sich tief in der Erde eine uralte Energie zu regen beginnt, vermutlich durch die Grabungen an den Ausgrabungsstätten aufgerüttelt.",al={"was entdeckt rethiel","uralte energie sumpfland","gefahr durch ausgrabungen"}},{q="Warum will Rethiel, dass die Ausgräber ihre Grabungen einstellen?",a="Rethiel warnt die Ausgräber, zu ihrer eigenen Sicherheit sofort mit den Grabungen aufzuhören. Ihre Arbeit droht gefährliche uralte Kräfte freizusetzen.",al={"grabungen einstellen rethiel","was sollen die ausgräber tun","zwerg ausgrabungsstätte warnung"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="Ardin Grassman wird nahe einer Ausgrabungsstätte vermisst, nachdem er Berichten über hoch aufragende Gräser gefolgt war. Seine Frau, eine Alchemistin, bittet Reisende, ihn zu finden, da gefährliche Wildtiere die Mannschaft angegriffen haben.",h="Ardin Grassman wird nahe einer Ausgrabungsstätte vermisst, nachdem er Berichten über hoch aufragende Gräser...",kw={"alchemie","ardin","ardin grassman","ausgrabungsstätten","kräuterkunde","lost in the thicket things","spinnen","hoch aufragende gräser"},ang={["class:Druid"]="Als Druide erkennt Ihr vielleicht Ardins Gabe, Pflanzen zu erspüren. Die Wildtiere nahe den Ausgrabungsstätten sind in Aufruhr geraten und stören das Gleichgewicht der Wildnis.",["profession:Herbalism"]="Als Kräuterkundiger erkennt Ihr vielleicht Ardin Grassmans Gabe, Pflanzen und Kräuter zu erspüren. Er klettert oft durch schwieriges Gelände, um seltene Pflanzen für die Alchemie zu sammeln."},sec={{t="Die Berufung eines Sammlers",b="Ardin Grassmans Frau, eine Alchemistin, bittet Euch, ihren vermissten Mann zu finden. Er hat ein feines Gespür für die Natur und wagt sich oft an Klippen und in entlegene Wildnis, um Kräuter und Pflanzen für ihre Arbeit zu sammeln. Als eine Ausgrabungsmannschaft von hoch aufragenden Gräsern berichtete, wie sie noch niemand von ihnen gesehen hatte, zog Ardins Neugier ihn zur Ausgrabungsstätte."},{t="Hinterhalt an der Ausgrabungsstätte",b="Ardin erreichte die Ausgrabungsstätte und fand die Mannschaft in Gefahr vor. Das umliegende Land hatte die heimischen Wildtiere in Aufruhr versetzt, und feindselige Spinnen fielen in Scharen über die Ausgrabungsmannschaft her. Ardin und die Mannschaft waren von den angreifenden Bestien eingeschlossen, bis Reisende ihnen zu Hilfe kamen."}},faq={{q="Wer ist Ardin Grassman?",a="Ardin Grassman sammelt Kräuter und besitzt ein seltenes Gespür für Pflanzen. Er sucht oft an Klippen und auf Gipfeln nach Wildpflanzen, um seine Frau für ihre Alchemie zu versorgen. Gerüchte über hoch aufragende Gräser zogen ihn zu einer Ausgrabungsstätte.",al={"wer ist ardin","ardin grassman geschichte","wer ist ardin grassman"}},{q="Warum zog Ardin in die Wildnis?",a="Ardin hörte eine Ausgrabungsmannschaft hoch aufragende Gräser beschreiben, wie sie noch niemand von ihnen gesehen hatte. Sein Gespür für ungewöhnliche Pflanzen trieb ihn hinaus, um sie zu sehen, und er kehrte nicht nach Hause zurück.",al={"warum ging ardin fort","warum wird ardin vermisst","wonach suchte ardin"}},{q="Wohin ging Ardin?",a="Ardin machte sich zu den nahe gelegenen Excavation Sites auf, nachdem er den Bericht einer vorbeiziehenden Mannschaft gehört hatte. Durchsucht die Ausgrabungsstätten, an denen die Mannschaft ihr Lager aufgeschlagen hat.",al={"wo ist ardin","ardin aufenthaltsort","wo ist ardin grassman zu finden"}},{q="Was geschah mit Ardin an der Ausgrabungsstätte?",a="Ardin erreichte das Ausgrabungslager, als die heimischen Wildtiere aggressiv wurden. Riesige Spinnen und andere Bestien überfielen die Mannschaft und schlossen Ardin mit ihr ein, bis Reisende eintrafen, um zu helfen.",al={"was geschah mit ardin","ist ardin tot","was griff ardin an"}},{q="Wer sucht nach Ardin?",a="Ardins Frau, eine Alchemistin, sucht nach ihm. Er sammelte Kräuter für ihre Vorräte, kehrte aber nicht zurück, nachdem er Berichten über seltsames Gras nachgegangen war. Also bat sie Reisende, ihn zu finden.",al={"wer vergibt lost in the thicket things","wer hat diese quest begonnen","ardins frau"}},{q="Warum griffen die Wildtiere die Ausgrabungsmannschaft an?",a="Die Ursache für die plötzliche Unruhe der Wildtiere nahe den Ausgrabungsstätten ist unbekannt. Aggressive Kreaturen, besonders Spinnen, fielen in Scharen über die Ausgrabungsmannschaft her und überwältigten sie.",al={"warum greifen spinnen an","was hat die tiere aufgebracht","warum sind die bestien wütend"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="Die Todespirscher suchen genauere Kunde über die Magie der Dragonmaw, von der im Sumpfland Gerüchte umgehen. Ihr werdet entsandt, um ihre Agentin in den Hügeln oberhalb des Clanlagers zu treffen.",h="Die Todespirscher suchen genauere Kunde über die Magie der Dragonmaw, von der im Sumpfland Gerüchte umgehen.",kw={"zerbrochene symbole","deathstalker agentin","deathstalkers","drachenbindung","dragonmaw","lager der dragonmaw","gerüchte über dragonmaw","sumpfland"},sec={{t="Gerüchte im Sumpfland",b="Ein Deathstalker im Sumpfland braucht Eure Hilfe, während sich Gerüchte um den Clan der Dragonmaw mehren. Sie sollen über Magie gebieten, die Drachen bindet, und angeblich bereiten sie eine Vorführung dieser Macht vor. Zerbrochene Symbole lieferten keine eindeutigen Beweise, also werdet Ihr entsandt, um eine Agentin in den Hügeln oberhalb ihres Lagers zu treffen."}},faq={{q="Was haben die Dragonmaw den Gerüchten zufolge vor?",a="Dem Gerücht zufolge bereiten die Dragonmaw eine Vorführung von Magie vor, die mächtig genug ist, Drachen zum Dienen zu zwingen.",al={"gerüchte über dragonmaw","was planen die dragonmaw","magie der dragonmaw"}},{q="Warum brauchen die Todespirscher Hilfe?",a="Die Todespirscher haben nur zerbrochene Symbole und vage Gerüchte über die Dragonmaw, daher braucht eine Agentin in den Hügeln oberhalb des Clanlagers Unterstützung.",al={"deathstalker braucht hilfe","warum den deathstalkers helfen","was brauchen sie"}},{q="Wo ist die Agentin der Todespirscher?",a="Die Agentin befindet sich in den Hügeln oberhalb des Lagers der Dragonmaw im Sumpfland.",al={"aufenthaltsort der agentin","wo die agentin treffen","deathstalker agentin hügel"}},{q="Was verrieten die zerbrochenen Symbole?",a="Die zerbrochenen Symbole lieferten nur vage Hinweise auf eine angeblich geplante Magievorführung der Dragonmaw.",al={"zerbrochene symbole","was die symbole zeigten","symbole dragonmaw"}},{q="Was geschieht, wenn Ihr die Agentin trefft?",a="Die Agentin der Todespirscher wird Euch die nächsten Schritte offenbaren, wenn Ihr sie in den Hügeln oberhalb des Lagers der Dragonmaw trefft.",al={"die agentin treffen","nächste schritte","was sagt die agentin"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="Ein seltsames Relikt der Titanen streut Licht wie ein lebendes Prisma, doch seine Natur bleibt ungewiss. Ihr bringt es zur Anhöhe der Ältesten in Donnerfels, um jemanden zu suchen, der seine uralte Macht erklären kann.",h="Ein seltsames Relikt der Titanen streut Licht wie ein lebendes Prisma, doch seine Natur bleibt ungewiss.",kw={"uralte macht","zusammengesetzter splitter","elder knowledge","die anhöhe der ältesten","lebendes prisma","donnerfels","relikt der titanen"},sec={{t="Ein Splitter aus Licht",b="Der ungewöhnliche zusammengesetzte Splitter in Eurem Besitz streut Licht wie ein lebendes Prisma. Seine Natur ist ungewiss, doch seine Macht wirkt uralt. Ihr bringt das Relikt der Titanen zur Anhöhe der Ältesten in Donnerfels und sucht jemanden, der Euch mehr darüber erzählen kann."}},faq={{q="Was ist das Relikt der Titanen?",a="Es ist ein ungewöhnlicher zusammengesetzter Splitter, der Licht wie ein lebendes Prisma streut. Seine Natur ist ungewiss, doch seine Macht wirkt uralt.",al={"relikt der titanen","was ist das relikt","prismensplitter"}},{q="Wohin bringe ich das Relikt der Titanen?",a="Bringt das Relikt der Titanen zur Anhöhe der Ältesten in Donnerfels und sucht jemanden, der es erklären kann.",al={"wohin mit dem relikt","anhöhe der ältesten relikt","donnerfels splitter"}},{q="Warum trage ich den Splitter bei mir?",a="Ihr sucht auf der Anhöhe der Ältesten jemanden, der Euch mehr über das Relikt der Titanen erzählen kann.",al={"warum dieses relikt","was mit dem splitter tun","elder knowledge quest"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="Ein Deathstalker Agent bittet Euch, die Dragonmaw aus den Excavation Sites zu vertreiben und alles Bemerkenswerte zurückzubringen. Der Klan sucht womöglich einen Weg zurück zur Macht.",h="Ein Deathstalker Agent bittet Euch, die Dragonmaw aus den Excavation Sites zu vertreiben und alles...",kw={"dark lady","deathstalker agent","dragonmaw","excavation site","verlassene","orkische kritzelei","rend"},sec={{t="Ein unauffälliges Vorgehen",b="Ein Deathstalker Agent außerhalb der Excavation Site will die Streitkräfte der Dragonmaw vertreiben lassen. Die Überreste des Klans, der einst Drachen bändigte, glauben, etwas gefunden zu haben, das ihre frühere Macht wiederherstellen könnte. Ihr zusammengewürfelter Haufen muss verschwinden, damit die Todespirscher unbemerkt eindringen können. Bringt alles Bemerkenswerte zurück, das Ihr findet, und behaltet die Angelegenheit zwischen dem Agenten und der königlichen Führung."},{t="Die geborgene Kritzelei",b="Der Deathstalker Agent erkennt die orkische Schrift unter den geborgenen Gegenständen. Sie zeigt, dass die Dragonmaw hoffen, Rend, ihren falschen Kriegshäuptling, zu besänftigen. Der Agent nennt das Unterfangen aussichtslos, doch das Wissen ist für die Dark Lady wertvoll. Der Agent überlässt Euch die geborgenen Gegenstände und warnt Euch, nichts über die Mission zu sagen."}},faq={{q="Wer hat mich zur Excavation Site geschickt?",a="Ein Deathstalker Agent außerhalb der Excavation Site bittet Euch, die Dragonmaw zu vertreiben und alles Bemerkenswerte zurückzubringen.",al={"wer will die dragonmaw vertreiben","auftrag des deathstalker agent","wer hat mich geschickt"}},{q="Was hoffen die Dragonmaw zu erreichen?",a="Die Überreste der Dragonmaw glauben, etwas gefunden zu haben, das ihre frühere Macht wiederherstellen könnte.",al={"plan der dragonmaw","warum sind die dragonmaw hier","dragonmaw zurück zur macht"}},{q="Warum wollen die Todespirscher das Gelände räumen lassen?",a="Sie wollen unbemerkt in die Excavation Site eindringen.",al={"warum excavation site räumen","deathstalkers rücken ein","was brauchen sie"}},{q="Was soll ich zurückbringen?",a="Bringt dem Deathstalker Agent alles Bemerkenswerte, das Ihr bei den Dragonmaw findet.",al={"was bergen","gegenstände der dragonmaw","was will der agent"}},{q="Wer ist die Dark Lady?",a="Der Agent verwendet diesen Titel für Sylvanas, die die Verlassenen anführt.",al={"bedeutung von dark lady","wer ist die dark lady","sylvanas titel"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Ein neues Gericht bei Borstan's Firepit könnte Reisende nach Orgrimmar locken. Zamjas Rat und Geschichten über riesige Raptorkrallen bringen Borstan dazu, Dickichtraptorfleisch aus dem Sumpfland jenseits des Meeres zu suchen.",h="Ein neues Gericht bei Borstan's Firepit könnte Reisende nach Orgrimmar locken.",kw={"borstan","borstan's firepit","changing tastes","ausgrabungsstätten","orgrimmar","dickichtraptor","dickichtraptorfleisch","sumpfland","zamja"},ang={["faction:Horde"]="Wer Borstan's Firepit beliefert, muss über das Meer ins umkämpfte Sumpfland reisen, um exotisches Fleisch nach Orgrimmar zurückzubringen.",["profession:Cooking"]="Borstan hofft, rustikale Mahlzeiten für die Hauptstadt der Horde zu veredeln, während sich Geschmack und Wirtshausspeisekarten über die üblichen Dorfgerichte hinausentwickeln."},sec={{t="Gehobene Küche der Hauptstadt",b="Borstan's Firepit in Orgrimmar möchte seine Speisekarte erweitern. Zamja empfiehlt Raptorgerichte nach Hausmacherart für Reisende, die die vertrauten Mahlzeiten ihrer Heimatdörfer vermissen. Borstan gefällt der Gedanke, mit Raptorfleisch neue Gäste anzulocken, doch einfache Dorfkost erscheint ihm für die große Hauptstadt der Horde zu bescheiden. Er möchte eine gewagtere Variante des altbekannten Grundgerichts."},{t="Die Jagd im Sumpfland",b="Ein Jäger kehrt mit einer gewaltigen Kralle eines Dickichtraptors von den Ausgrabungsstätten im Sumpfland nach Orgrimmar zurück. Die Größe und Qualität des Tieres wecken Borstans Interesse. Er lässt Abenteurer über das Meer in die Östlichen Königreiche reisen, den Gefahren der Ausgrabungsstätten trotzen und erstklassiges Dickichtraptorfleisch für seine Feuer zurückbringen."}},faq={{q="Was ist die Quest Changing Tastes?",a="Changing Tastes ist eine kulinarische Aufgabe in Orgrimmar. Borstan, der Besitzer von Borstan's Firepit, sucht Dickichtraptorfleisch aus dem fernen Sumpfland, um seine Speisekarte über einfache Dorfküche hinauszuheben.",al={"was ist changing tastes","changing tastes quest"}},{q="Wer ist Zamja?",a="Zamja ist eine Bekannte und Berufskollegin, die Raptorgerichte nach Hausmacherart für Borstan's Firepit vorschlägt und damit Gäste anlocken möchte, die sonst nicht dort einkehren.",al={"wer ist zamja","zamja kochen"}},{q="Was ist Borstan's Firepit?",a="Borstan's Firepit ist eine Gaststätte in Orgrimmar, der Hauptstadt der Horde. Sie serviert Einheimischen wie Reisenden gleichermaßen herzhafte Fleischgerichte.",al={"borstan's firepit","wo ist borstan"}},{q="Warum möchte Borstan Dickichtraptorfleisch?",a="Borstan möchte vertraute Aromen auf großartigere Weise darbieten als mit Zamjas Raptorgerichten nach Hausmacherart. Die Erzählung eines Jägers über riesige Krallen bringt ihn dazu, Dickichtraptorfleisch aus dem Sumpfland zu suchen.",al={"warum raptorfleisch","warum dickichtraptor"}},{q="Wo leben die Dickichtraptoren?",a="Dickichtraptoren leben an Ausgrabungsstätten im Sumpfland, einer der Allianz zugeneigten Region jenseits des großen Meeres in den Östlichen Königreichen.",al={"wo gibt es dickichtraptoren","sumpfland ausgrabungsstätten raptor"}},{q="Wer vergibt die Quest Changing Tastes?",a="Borstan, der Wirt von Borstan's Firepit in Orgrimmar, bietet Changing Tastes an, nachdem Zamjas Rat und die mitgebrachte Trophäe eines abenteuerlustigen Jägers ihn inspirieren.",al={"wer vergibt changing tastes","borstan questgeber"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="In Bashal'Aran ist Asterions Geist noch immer durch ein uraltes Siegel gebunden. Ihr tragt das Siegel nach Süden nach Ameth'Aran, wo eine alte Flamme seine Fesseln brechen könnte.",h="In Bashal'Aran ist Asterions Geist noch immer durch ein uraltes Siegel gebunden.",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","dunkelküste","hochgeborene","mondsteinsiegel"},ang={["class:Mage"]="Als Magier erahnt Ihr die rohe arkane Macht der uralten Zauberer der Highborne in den Verzauberungen, die Asterion binden, und den Flammen, die in Ameth'Aran fortbestehen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, uralte Flüche in der Dunkelküste zu bannen und die Grenzen für neue Nachtelfensiedlungen zu sichern, die sich von Auberdine aus ausbreiten.",["race:NightElf"]="Für die Nachtelfen des modernen Kalimdor ist die Befreiung Asterions eine ernüchternde Begegnung mit der Vergangenheit ihres Volkes vor der Zerschlagung und dem fortwirkenden Verderben des Adels der Hochgeborenen von Königin Azshara."},sec={{t="Ein Kerker uralter Zauberei",b="Das Alte Mondsteinsiegel wurde vor der Zerschlagung von Zauberern der Hochgeborenen geschmiedet, und keine gewöhnliche Kraft kann seine Macht brechen."},{t="Zwillingsruinen der Dunkelküste",b="Bashal'Aran und Ameth'Aran waren Schwestersiedlungen der kaldorei unter Königin Azshara, als der Brunnen der Ewigkeit ihrem Reich Halt gab. Heute sind beide überwucherte, heimgesuchte Ruinen, in denen Geister verweilen und arkane Macht unberechenbar bleibt. In Ameth'Aran brennt ein mystisches Kohlenbecken mit cyanblauem Feuer in einem steinernen Pavillon; dies ist die einzige Flamme, die das Alte Mondsteinsiegel verzehren kann."},{t="Die Rache erwacht",b="Nachdem das Siegel zerstört ist, ist Asterion endlich befreit und blickt auf ein zerschlagenes Kalimdor, das sich gegenüber dem goldenen Zeitalter seiner Erinnerung grundlegend gewandelt hat. Doch seine Freiheit bringt ihm keinen Frieden. Als er spürt, dass sein einstiger Meister und Kerkermeister, der Hochgeborene Athrikus, noch immer fortbesteht, wandelt sich Asterions uralte Verzweiflung rasch in einen kalten, brennenden Hunger nach Rache."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein Nachtelfengeist, der in den Ruinen von Bashal'Aran gefangen ist. Seine Geschichte reicht zehntausend Jahre bis in die Herrschaft von Königin Azshara zurück, und er ist durch ein Siegel an die Ruinen gebunden, das von einem der mächtigsten der Hochgeborenen gefertigt wurde.",al={"asterion","wer ist der geist","nsc asterion"}},{q="Wo zerstöre ich das Alte Mondsteinsiegel?",a="Das Siegel muss nach Süden nach Ameth'Aran gebracht werden, der Zwillingsruine von Bashal'Aran. Haltet Ausschau nach einem steinernen Pavillon, der eine große kubische Feuerschale beherbergt, in der ein uraltes, grünlich-blaues magisches Feuer brennt.",al={"wo ist die flamme","standort der uralten flamme","siegel zerstoeren"}},{q="In welcher Beziehung stehen Bashal'Aran und Ameth'Aran zueinander?",a="Sie waren Schwesterstädte des uralten Nachtelfenreiches vor der Zerschlagung. Beide fielen vor zehntausend Jahren der Verwüstung anheim und hinterließen heimgesuchte Steinsäulen, arkane Restenergien und rastlose Geister.",al={"zwillingsruinen","verbindung zu ametharan","bashalaran ametharan"}},{q="Wer kerkerte Asterion ein?",a="Asterion berichtet, dass einer der mächtigsten Hochgeborenen das Siegel schuf, das ihn bindet. Mehr über seinen einstigen Meister wird im Verlauf der Questreihe enthüllt.",al={"wer kerkerte asterion ein","wer ist athrikus","meister von asterion"}},{q="An welches Zeitalter erinnert sich Asterion?",a="Asterion wandelte zuletzt auf der Welt, als der ursprüngliche Brunnen der Ewigkeit noch existierte, Königin Azshara das Reich regierte und der Adel der Hochgeborenen vor der Zerschlagung seine majestätischen Höfe abhielt.",al={"vergangenheit von asterion","aera des brunnens der ewigkeit","wie alt ist asterion"}},{q="Findet Asterions Geist durch seine Befreiung Ruhe?",a="Die Zerstörung des Siegels soll Asterions Gefängnis aufheben. Seine Reaktion auf die Freiheit offenbart sich, wenn Ihr zu ihm zurückkehrt.",al={"findet asterion frieden","was geschieht mit asterion","asterion nach der befreiung"}}},fx={["8275c861"]={q="Warum möchte Asterion, dass das Alte Mondsteinsiegel zerstört wird?",a="Das Alte Mondsteinsiegel ist der Anker, der Asterions Geist in den Ruinen von Bashal'Aran in Qualen bindet. Vor Jahrtausenden durch mächtige Hochgeborenen-Zauberei erschaffen, hält es ihn gefangen und blind für die Welt da draußen. Es im mystischen alten Feuer von Ameth'Aran zu zerstören, ist der einzige Weg, seine ätherischen Ketten zu sprengen, was ihm Freiheit und die Klarheit gewährt, zu sehen, was aus Kalimdor geworden ist.",al={"warum mondsteinsiegel zerstören","asterion beweggrund","warum will asterion das siegel brechen"}},["51df5ddd"]={q="Warum benötigt Asterion Euch, um das Siegel nach Ameth'Aran zu bringen?",a="Gebunden durch die alte Hochgeborenen-Magie, die ihn an Bashal'Aran verankert, kann Asterion die unmittelbaren Ruinen nicht verlassen, geschweige denn nach Süden nach Ameth'Aran reisen. Er benötigt einen Reisenden, der das Siegel in das alte Feuer trägt.",al={"warum kann asterion das siegel nicht selbst zerstören","warum braucht asterion mich","warum einen abenteurer zur zerstörung des siegels schicken"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="Eine Alchemistin wartet auf Nachricht über ein seltenes Gras. Sie bittet Euch, Caitlin Grassman im Hafen von Menethil zu finden, deren Mann sich von einer Ausgrabung noch nicht zurückgemeldet hat.",h="Eine Alchemistin wartet auf Nachricht über ein seltenes Gras.",kw={"alchemistin","caitlin grassman","ausgrabung","grassamen","hafen von menethil","urgras","seeking caitlin","sumpfland"},ang={["profession:Herbalism"]="Als Kräuterkundiger werdet Ihr gebeten, nach Caitlin zu sehen, nachdem das Team ihres Mannes Spuren eines seltenen Urgrases gefunden hat."},sec={{t="Ein ausstehender Bericht",b="Die Alchemistin hat von Caitlin erfahren, dass das Ausgrabungsteam ihres Mannes Spuren eines Urgrases gefunden hat. Caitlin weiß nicht, wie viel sie gefunden haben oder ob es erreichbar ist.\n\nNun bittet Euch die Alchemistin, mit Caitlin im Hafen von Menethil zu sprechen. Beide Frauen warten darauf zu erfahren, was aus den versprochenen Samen geworden ist."}},faq={{q="Wer ist Caitlin Grassman?",a="Caitlin Grassman ist eine Alchemistin im Hafen von Menethil. Ihr Mann schloss sich einem Ausgrabungsteam an, das Spuren eines Urgrases gefunden hat.",al={"caitlin","wer ist caitlin","caitlin grassman"}},{q="Was soll ich für die Alchemistin tun?",a="Die Alchemistin bittet Euch, mit Caitlin Grassman im Hafen von Menethil zu sprechen.",al={"caitlin finden","mit caitlin sprechen","caitlins quest"}},{q="Was hat das Ausgrabungsteam gefunden?",a="Das Team hat Spuren eines lange verschollenen Urgrases gefunden. Wie viel davon vorhanden ist und ob es erreichbar ist, bleibt unbekannt.",al={"urgras","seltenes gras","ausgrabungsfund"}},{q="Warum sind sie besorgt?",a="Caitlin versprach der Alchemistin, dass ihr Mann Grassamen mitbringen würde, doch bislang sind keine eingetroffen. Beide Frauen vermuten Schwierigkeiten an der Ausgrabungsstätte.",al={"wo sind die samen","fehlende grassamen","warum besorgt"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="Ein Trollgelehrter sucht eine Abreibung einer uralten Tafel nördlich des Finsteren Riffs. Ihre Legende könnte die Größe des verlorenen I'lalai verdeutlichen.",h="Ein Trollgelehrter sucht eine Abreibung einer uralten Tafel nördlich des Finsteren Riffs.",kw={"uralte ruine","gurubashi","i'lalai","legende","abreibung","tafel","troll","das finstere riff"},ang={["race:Troll"]="Als Troll werdet Ihr gebeten, einem Gelehrten beim Studium von Legenden über eine verlorene Trollstadt zu helfen."},sec={{t="Eine Tafel an der Küste",b="Der Gelehrte vergleicht ein Tafelfragment, das Ihr gebracht habt, mit den Ruinen vor dem Finsteren Riff. Diese Ruinen wirken zu klein für die weitläufige Zivilisation, die der Text beschreibt. Deshalb bittet Euch der Gelehrte, eine Abreibung einer Tafel in einer uralten Trollruine auf den Küstenhügeln im Norden anzufertigen."},{t="Eine alte Erinnerung",b="Der Gelehrte nimmt die Abreibung erfreut entgegen und sagt, die Tafel sei ihm aus seiner Jugend vertraut. Viele Monde sind vergangen, seit er sie zuletzt gelesen hat, und seine Erinnerung ist verblasst."}},faq={{q="Was möchte der Gelehrte?",a="Der Gelehrte möchte eine Abreibung einer Tafel mit Legenden über die verlorene Trollstadt I'lalai.",al={"tafelabreibung","was braucht er","bitte um abreibung"}},{q="Wo ist die Tafel?",a="Sie befindet sich in einer uralten Trollruine auf den Küstenhügeln nördlich des Finsteren Riffs.",al={"fundort der tafel","wo ist die tafel","nördlich des riffs"}},{q="Warum möchte der Gelehrte eine Abreibung?",a="Ein Tafelfragment, das Ihr gebracht habt, beschreibt I'lalai als weitläufige Zivilisation, während die Ruinen vor dem Finsteren Riff dafür zu klein wirken.",al={"warum eine abreibung","i'lalai tafel","legende der verlorenen stadt"}},{q="Was ist I'lalai?",a="I'lalai wird im Tafelfragment als verlorene Trollstadt und weitläufige Zivilisation beschrieben.",al={"i'lalai stadt","verlorene trollstadt","ilalai"}},{q="Was sagt der Gelehrte über die Tafel?",a="Der Gelehrte hat die Tafel schon in seiner Jugend gelesen, sagt aber, dass viele Monde vergangen seien und seine Erinnerung verblasst sei.",al={"erinnerung des gelehrten","tafel schon einmal gelesen","alte trolllegende"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="Kin'weelay bittet Euch, im Finsteren Riff nach einer Höhle zu suchen, die mit der verlorenen Stadt verbunden ist. Die Naga, die sich dort sammeln, könnten etwas gefunden haben, das eine Untersuchung wert ist.",h="Kin'weelay bittet Euch, im Finsteren Riff nach einer Höhle zu suchen, die mit der verlorenen Stadt verbunden...",kw={"höhle","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","naga","das finstere riff"},sec={{t="Eine Höhle im Riff",b="Kin'weelay erinnert sich daran, zwischen den Ruinen des Finsteren Riffs getaucht zu sein, bevor sich dort Murlocs niederließen. Er erinnert sich an eine Höhle und bittet Euch, das Riff nach ihrem Eingang abzusuchen. Nun sammeln sich Naga in der Gegend, und er möchte wissen, was sie dorthin gelockt hat."},{t="Eine mögliche Entdeckung",b="Als Ihr zurückkehrt, hört sich Kin'weelay an, was Ihr gesehen habt. Die Naga gehen in der Höhlenruine ein und aus, doch ihre Absichten bleiben unklar. Er fragt sich, ob sie mit I'lalai und der Lost City zusammenhängt, die unter Trollen lange als Mythos galt. Nun möchte er der Sache nachgehen."}},faq={{q="Wer bittet mich, das Finstere Riff abzusuchen?",a="Kin'weelay bittet Euch, das Finstere Riff zu erkunden und nach einem Höhleneingang zu suchen.",al={"wer hat mich geschickt","kin weelays bitte","wer will das"}},{q="Warum suche ich nach einer Höhle?",a="Kin'weelay erinnert sich an eine Höhle zwischen den Ruinen des Finsteren Riffs und vermutet, dass sie helfen könnte, die Lost City zu finden.",al={"warum höhle","hinweis auf lost city","wonach suche ich"}},{q="Warum sammeln sich die Naga dort?",a="Kin'weelay hat gehört, dass sich Naga in der Gegend sammeln, doch der Grund dafür ist unbekannt.",al={"naga am riff","warum naga","grund für naga"}},{q="Was ist mit den Ruinen des Finsteren Riffs geschehen?",a="Murlocs ließen sich zwischen den Ruinen des Finsteren Riffs nieder, nachdem Kin'weelay in seinen jüngeren Jahren dort getaucht war.",al={"ruinen des finsteren riffs","murlocs dort","wer besiedelte das riff"}},{q="Wo ist der Höhleneingang?",a="Der Höhleneingang liegt im Finsteren Riff. Kin'weelay bittet Euch, das Riff danach abzusuchen.",al={"lage der höhle","eingang finden","wo ist die höhle"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="Dorin Songblade wartet auf Nachricht von seinem Bruder Daewyn im Sumpfland. Daewyn schloss sich einem archäologischen Trupp aus Loch Modan an, um in unerforschten Hügeln zu graben, doch sein Schweigen ist untypisch.",h="Dorin Songblade wartet auf Nachricht von seinem Bruder Daewyn im Sumpfland.",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Als Reisender der Allianz kommt Ihr auf dem Weg zwischen Loch Modan und dem Hafen von Menethil womöglich an Ausgrabungsstätten vorbei. Dort könnt Ihr festsitzenden zwergischen Prospektoren und Handwerkern helfen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Expeditionstrupps und archäologische Ausgrabungen in ganz Khaz Modan üblich sind. Das Sumpfland jenseits von Loch Modan ist gefährlich, und Reisen dorthin bringen Angehörige in Gefahr."},sec={{t="Die Sorge eines Bruders",b="Dorin Songblade arbeitet in seiner Werkstatt, überhäuft mit Aufträgen zum Ändern von Gürteln. Sein Bruder Daewyn ist mit einem zwergischen Ausgrabungstrupp aus Loch Modan nach Norden gezogen. Die Hügel im Sumpfland, die sie aufsuchen wollen, hat noch nie eine zwergische Spitzhacke berührt. Daewyn schreibt gewöhnlich gleich nach seiner Ankunft, doch Dorin hat keine Nachricht erhalten, und das Schweigen beunruhigt ihn."},{t="Die Ausgrabung im Sumpfland",b="Daewyn Songblade gräbt an Whelgars Ausgrabungsstätte im Sumpfland. Er sieht seinem Bruder Dorin sehr ähnlich und trägt ein Gewehr, in dessen Holzschaft DLS eingeritzt ist. An diesen Initialen lässt sich Daewyn im abgelegenen Ausgrabungslager in den Marschen erkennen."}},faq={{q="Wer vergibt die Quest Songblade Search?",a="Dorin Songblade bittet Reisende, nach seinem Bruder zu sehen. Der Handwerker hat mit dem Ändern von Gürteln alle Hände voll zu tun, weshalb er sich Daewyns archäologischer Ausgrabung nicht anschließen konnte.",al={"wer vergibt songblade search","songblade search questgeber","dorin songblade"}},{q="Wer ist Daewyn Songblade?",a="Daewyn Songblade ist der Bruder von Dorin Songblade. Er brach mit einem Ausgrabungstrupp aus Loch Modan zu den Hügeln des Sumpflands auf, hat aber nicht wie üblich Nachricht geschickt.",al={"wer ist dorins bruder","vermisster songblade-zwerg","daewyn songblade"}},{q="Wo ist Daewyn zu finden?",a="Daewyn ist an Whelgars Ausgrabungsstätte im Sumpfland. Er ist an seiner Ähnlichkeit mit Dorin und den in den Holzschaft seines Gewehrs eingeritzten Initialen DLS zu erkennen.",al={"wo ist daewyn","wo ist daewyn songblade zu finden","songblade search ort"}},{q="Warum reiste Daewyn ins Sumpfland?",a="Daewyn reiste mit einer zwergischen Ausgrabungsexpedition aus Loch Modan ins Sumpfland, um in unerforschten Hügeln zu graben.",al={"warum ging daewyn ins sumpfland","zweck von whelgars ausgrabungsstätte","warum gingen die zwerge ins sumpfland"}},{q="Was bedeuten die eingeritzten Initialen am Gewehr?",a="Die in den Gewehrschaft eingeritzten Initialen DLS gehören zu Daewyn Songblade. Sie weisen den Zwerg an der Ausgrabungsstätte als Dorins vermissten Bruder aus.",al={"wofür steht dls","dls eingeritzt am gewehr","dls initialen"}},{q="Warum sorgte sich Dorin um seinen Bruder?",a="Dorin sorgt sich, weil Daewyn gewöhnlich kurz nach seinem Aufbruch schreibt. Seit Daewyn ins Sumpfland aufgebrochen ist, sind keine Briefe eingetroffen, und Dorin fürchtet, dass etwas schiefgegangen ist.",al={"warum ist dorin besorgt","warum nach daewyn suchen","songblade search grund"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="Naga sammeln sich bei alten Trollruinen vor der Küste, während Angriffe auf ihre Karawanen die Horde bereits bedrängen. Ihr sollt dieser Bedrohung entgegentreten und zeigen, dass Ihr Euch bewährt.",h="Naga sammeln sich bei alten Trollruinen vor der Küste, während Angriffe auf ihre Karawanen die Horde bereits...",kw={"bloodscalp","brinescale","feinde im wasser","grom'gol","horde","naga","oger","dreizacke","trollruinen"},ang={["faction:Horde"]="Die Horde will ihre Karawanen schützen und zugleich nach einem möglichen Angriff vom Meer Ausschau halten."},sec={{t="Berichte von der Küste",b="Die Horde hat Berichte erhalten, dass sich Naga bei alten Trollruinen unter dem Meer sammeln. Angriffe der Bloodscalp und der Oger beanspruchen ihre Verteidigung bereits stark, sodass eine Bedrohung aus dem Wasser kaum Aufschub duldet. Ihr sollt Euch den Plänklern der Brinescale stellen und ihre Dreizacke als Beweis zurückbringen."},{t="Eine Botschaft bei Grom’gol",b="Die Dreizacke, die Ihr zurückbringt, sollen vor den Toren von Grom’gol aufgestellt werden. Sie sollen als Warnung dienen, dass mit der Horde nicht zu spaßen ist, und Eure Arbeit bringt Euch das Lob des Kommandanten ein."}},faq={{q="Warum sind die Naga nahe der Küste?",a="Berichten zufolge sammeln sich die Naga um alte Trollruinen unter dem Meer.",al={"naga küste","naga im wasser","warum naga hier"}},{q="Wer sind die Feinde hier?",a="Die Bedrohung geht von den Plänklern der Brinescale aus, einer Gruppe von Naga, die nahe der Küste gemeldet wurde.",al={"feinde im wasser","wer sind die naga","brinescale"}},{q="Warum will die Horde gegen die Naga vorgehen?",a="Die Verteidigung ihrer Karawanen gegen Angriffe der Bloodscalp und der Oger bringt die Horde bereits an ihre Grenzen, und sie fürchtet einen Überraschungsangriff vom Meer.",al={"warum naga töten","horde naga problem","angriff vom meer"}},{q="Welcher Beweis wird verlangt?",a="Ihr sollt Dreizacke der Brinescale als Beweis für Euren Erfolg zurückbringen.",al={"dreizack als beweis","was zurückbringen","dreizacke der brinescale"}},{q="Was geschieht mit den Dreizacken?",a="Sie werden vor den Toren von Grom’gol aufgestellt, als Warnung, dass mit der Horde nicht zu spaßen ist.",al={"botschaft der dreizacke","dreizacke aufstellen","gromgol dreizacke"}},{q="Wie beweise ich damit meinen Wert?",a="Der Kommandant lobt Eure Arbeit und sagt, dass Ihr Euch bei der Horde rasch bewährt.",al={"wert beweisen","anerkennung der horde","warum bin ich hier"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="Mankrik trauert um Olgra und bereitet ein Denkmal vor, um ihren Namen lebendig zu halten. Er bittet Euch, bei den nahegelegenen Razormane-Räubern nach ihren verschwundenen Knochenverzierungen zu suchen.",h="Mankrik trauert um Olgra und bereitet ein Denkmal vor, um ihren Namen lebendig zu halten.",kw={"verzierungen","mankrik","denkmal","olgra","polierter knochen","stacheleber","razormane-räuber"},sec={{t="Die Gefallenen ehren",b="Ein Heiler rettete Mankrik, doch Olgra erlag auf dem Schlachtfeld ihren Wunden. In seiner Trauer bereitet Mankrik eine dauerhafte Ehrung vor, damit ihr Name und ihr Opfer in Erinnerung bleiben."},{t="Verlorene Andenken",b="Olgra trug geliebte Schmuckstücke aus poliertem Knochen, doch sie fehlen an ihrer Ruhestätte. Mankrik bittet Euch, sie von den nahegelegenen Razormane-Räubern zurückzuholen, damit sie neben dem Denkmal ruhen können, das er für sie errichtet."}},faq={{q="Wer ist Olgra?",a="Olgra fiel im Kampf gegen die Stacheleber. Der Heiler, der Mankrik rettete, konnte sie nicht retten, und Mankrik will ihr Andenken für immer ehren.",al={"wer ist olgra","mankriks frau","wer ist gestorben"}},{q="Was sind Olgras Verzierungen?",a="Olgras Verzierungen sind geliebte Schmuckstücke aus poliertem Knochen. Sie trug sie, bevor sie getötet wurde.",al={"was sind olgras verzierungen","olgras schmuck","woraus bestehen die verzierungen"}},{q="Warum werden die Razormane-Räuber gejagt?",a="Die Razormane-Räuber haben Olgras Schmuckstücke. Mankrik schickt Euch los, um sie von den Räubern nahe dem Ort zurückzuholen, an dem sie starb.",al={"warum razormane-räuber töten","wer hat olgras verzierungen gestohlen","wo sind die verzierungen"}},{q="Was wird Mankrik mit den zurückgeholten Verzierungen tun?",a="Mankrik plant, den zurückgeholten Knochenschmuck neben das Denkmal zu legen, das er für Olgra errichtet, damit ihr Andenken fortbesteht.",al={"mankriks denkmal","was wird mankrik mit den verzierungen tun","warum will mankrik die verzierungen"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="Eine gelehrte Person bittet Euch, von Naga bewachte Ruinen zu untersuchen und die Ritzungen ihrer Tafeln abzuzeichnen. Die Stadt könnte I’lalai sein, reich an verlorener Geschichte.",h="Eine gelehrte Person bittet Euch, von Naga bewachte Ruinen zu untersuchen und die Ritzungen ihrer Tafeln...",kw={"holzkohle","versunkene stadt","fell","i'lalai","verlorene geschichte","naga","abreibungen","ruinen","tafeln"},sec={{t="Jenseits der Höhle",b="Die gelehrte Person ist zu alt, um die Ruinen zu betreten, und bittet Euch deshalb, an ihrer Stelle hineinzugehen. Jenseits der von Naga bewachten Höhle vermutet sie die Ruinen von I’lalai. Die verlorene Stadt könnte einen reichen Schatz an historischem Wissen bergen. Fertigt Abreibungen aller Tafeln an, die Ihr findet, und bringt sie zurück."}},faq={{q="Was ist die Drowned City?",a="Laut der gelehrten Person, die Euch geschickt hat, könnten die Ruinen die verlorene Stadt I’lalai sein.",al={"versunkene stadt","um welche stadt geht es","ruinen von i'lalai"}},{q="Wer möchte, dass ich die Ruinen erkunde?",a="Eine gelehrte Person bittet Euch, die Ruinen zu erkunden, weil sie selbst zu alt dafür ist.",al={"wer hat mich geschickt","wer möchte abreibungen","auftrag der gelehrten person"}},{q="Warum werde ich dorthin geschickt?",a="Die gelehrte Person hofft, dass die Ruinen einen großen Schatz an verlorenem historischem Wissen bergen.",al={"warum erkunden","warum tafeln","verlorene geschichte"}},{q="Was soll ich zurückbringen?",a="Fertigt mit Fell und Holzkohle Abreibungen aller Tafeln an, die Ihr findet, und kehrt dann zur gelehrten Person zurück.",al={"was zurückbringen","tafelabreibungen","auftrag für abreibungen"}},{q="Wo befinden sich die Ruinen?",a="Die Ruinen liegen auf der anderen Seite der von Naga bewachten Höhle.",al={"wo liegt die versunkene stadt","naga-höhle","lage der ruinen"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="Naga in den Küstengewässern lassen eine größere Bedrohung befürchten. Ihr sollt ihren Anführer in der Drowned City finden.",h="Naga in den Küstengewässern lassen eine größere Bedrohung befürchten.",kw={"brinescale","küste","drowned city","infiltration","kin'weelay","naga","var'taka"},sec={{t="Eine Gefahr vor der Küste",b="Die Naga an der Küste sind erschlagen, doch ihre Zahl deutet auf eine größere Gefahr hin. Kin'weelay glaubt, dass die Brinescale-Naga in die Ruinen der Drowned City eindringen. Ihre Anwesenheit dort lässt vermuten, dass sie etwas suchen, das die Küste gefährden könnte. Ihr sollt ihren Anführer Var'Taka erschlagen."},{t="Die Rückkehr",b="Als Ihr zurückkehrt, nimmt Euer Auftraggeber Eure Ankunft als Zeichen dafür, dass Var'Taka tot ist. Ohne den Anführer der Naga droht der Küste eine Gefahr weniger."}},faq={{q="Warum sind die Brinescale-Naga in der Drowned City?",a="Kin'weelay glaubt, dass die Brinescale-Naga in der Drowned City nach etwas suchen, doch was sie suchen, ist unbekannt.",al={"warum sind naga dort","ziel der brinescale","wonach suchen die naga"}},{q="Wer ist Kin'weelay?",a="Kin'weelay glaubt, dass die Brinescale-Naga in die Drowned City eindringen.",al={"kin'weelay","wer ist kin'weelay","kin"}},{q="Wer ist Var'Taka?",a="Var'Taka ist der Anführer der Brinescale-Naga in der Drowned City.",al={"var taka","naga anführer","brinescale anführer"}},{q="Was soll ich tun?",a="Ihr sollt Var'Taka in der Drowned City erschlagen.",al={"was soll ich tun","was ist der auftrag","wen töten"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95786"] = {n="An Acquaintance in Southshore",s="Bruder Nimetz schickt Euch mit einem Bericht für Meister der Lehren Dibbs nach Süderstade. Aufgewühlte Trolle und das Wort „I'lalai“ könnten mit Colonel Kurzons Verderbnis zusammenhängen.",h="Bruder Nimetz schickt Euch mit einem Bericht für Meister der Lehren Dibbs nach Süderstade.",kw={"bruder nimetz","colonel kurzen","verderbnis","fetische","i'lalai","meister der lehren dibbs","späherbericht","süderstade","schlingendorntal","trolllegenden"},sec={{t="Ein Wort im Bericht",b="Bruder Nimetz schickt Euch mit einer Sammlung von Trolllegenden, Fetischen und dem Bericht eines Spähers aus Schlingendorntal nach Süderstade. Die örtlichen Trolle sind aufgewühlt und sprechen von „I'lalai“. Nimetz hofft, Meister der Lehren Dibbs könne feststellen, ob dies mit Colonel Kurzons verdorbenem Geist zusammenhängt."},{t="In Süderstade",b="Meister der Lehren Dibbs empfängt Euch in Süderstade und bemerkt die lange Reise aus Schlingendorntal. Mit Nimetz' Bericht und den Materialien in der Hand fragt er, was Euch hergeführt hat."}},faq={{q="Wer schickte mich nach Süderstade?",a="Bruder Nimetz schickte Euch aus Schlingendorntal, um mit Meister der Lehren Dibbs zu sprechen.",al={"wer schickte mich","nimetz süderstade","bruder nimetz"}},{q="Warum reise ich nach Süderstade?",a="Nimetz möchte, dass Meister der Lehren Dibbs Trolllegenden, Fetische und einen Späherbericht auf einen möglichen Zusammenhang mit Colonel Kurzons Verderbnis untersucht.",al={"warum süderstade","dibbs bericht","was nehme ich mit"}},{q="Wer ist Meister der Lehren Dibbs?",a="Meister der Lehren Dibbs ist Nimetz' Freund im Vorgebirge des Hügellands, wo er Trolllegenden und böse Magie erforscht.",al={"wer ist dibbs","dibbs süderstade","meister der lehren"}},{q="Was steht im Bericht des Spähers?",a="Dem Bericht zufolge sind die örtlichen Trolle aufgewühlt und haben „I'lalai“ erwähnt.",al={"späherbericht","trolle aufgewühlt","was ist ilalai"}},{q="Wo finde ich Meister der Lehren Dibbs?",a="Meister der Lehren Dibbs ist in Süderstade.",al={"dibbs aufenthaltsort","dibbs finden","süderstade"}}},fp="29,161,20.281.0,13.171.0,26.74.0,29.144.0,24.110.0,33.79.0,33.34.0"}
P.entries["quest:95787"] = {n="Take Two With Water",s="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln, in der er die verlorene Trollstadt I’lalai wieder aufgetaucht glaubt. Er nennt sie möglicherweise die archäologische Entdeckung des Jahrhunderts.",h="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln, in der er die verlorene...",kw={"drowned city","i’lalai","loa","meister der lehren dibbs","tafelabriebe","gezeiten","trolllegenden","zandali"},sec={{t="Dibbs’ Entdeckung",b="Meister der Lehren Dibbs hat einen Kundschafterbericht und Trolllegenden gelesen, die darauf hindeuten, dass I’lalai, eine verlorene Trollstadt, vor der Küste des Schlingendorntals wieder aufgetaucht ist. Er bittet Euch, Legenden aus der Drowned City mitzubringen. Diese Entdeckung könnte das Wissen über die uralten Ruinen verändern."},{t="Die Tafeln",b="Dibbs heißt Euch aus den Trollruinen willkommen und möchte unbedingt erfahren, was Ihr gefunden habt. Vier Tafeln offenbaren neue Legenden, doch sein uraltes Zandali ist eingerostet. Er glaubt, ihre Worte könnten einen unbekannten Loa nennen, der mit den Gezeiten verbunden ist."}},faq={{q="Wer bittet um diese Legenden?",a="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln.",al={"wer ist dibbs","meister der lehren dibbs","dibbs’ bitte"}},{q="Was ist die Drowned City?",a="Dibbs glaubt, sie könnte die verlorene Trollstadt I’lalai sein, die vor der Küste des Schlingendorntals wieder aufgetaucht ist.",al={"drowned city","welche stadt","unterwasser-trollstadt"}},{q="Was soll ich Dibbs mitbringen?",a="Er bittet Euch, Kohleabriebe von Tafeln aus der Drowned City anzufertigen und die Legenden mitzubringen.",al={"was soll ich sammeln","tafelabriebe","auftrag in der drowned city"}},{q="Warum möchte Dibbs die Legenden?",a="Er glaubt, dass der Kundschafterbericht und die Trolllegenden auf die verlorene Stadt I’lalai hindeuten könnten.",al={"warum legenden","dibbs’ forschung","was erforscht er"}},{q="Wo könnte I’lalai liegen?",a="Dibbs glaubt, I’lalai sei direkt vor der Küste des Schlingendorntals wieder aufgetaucht.",al={"wo liegt ilalai","ilalai ort","verlorene trollstadt"}}},fp="19,194,19.263.0,11.226.1,32.67.0,25.93.0,38.102.0,32.90.0,25.71.0"}
P.entries["quest:95788"] = {n="Magics of the Drowned City",s="Ein Gelehrter bittet Euch, Trollfetische aus I'lalai zum Studium zu bringen. Ihr seltsames Design könnte mit der Magie zusammenhängen, die die versunkene Stadt emporhob.",h="Ein Gelehrter bittet Euch, Trollfetische aus I'lalai zum Studium zu bringen.",kw={"bruder nimetz","dunkle magie","versunkene stadt","fetische","i'lalai","naga","piraten","seeschlange","troll","untoter"},sec={{t="Fetische zum Studium",b="Der Gelehrte, der Bruder Nimetz' Schädelspalter-Fetische untersucht hat, bittet Euch, weitere aus I'lalai zu sammeln. Gerüchten zufolge ist die verlorene Trollstadt unter dem Wasser emporgehoben worden, und dunkle Magie könnte dabei eine Rolle gespielt haben. Der Gelehrte möchte ihre Fetische mit den bereits untersuchten vergleichen."},{t="Viele Arten von Magie",b="Nach Eurer Rückkehr stellt der Gelehrte fest, dass sich die Fetische aus I'lalai deutlich unterscheiden: Sie sind kunstvoll und zugleich schlicht gearbeitet und zeigen eine gewaltige Seeschlange. Euer Bericht beschreibt Untote, Piraten, Blutrituale und Naga, die sich in den Ruinen versammeln. Die Stadt zieht nun viele Arten von Magie an, und der Gelehrte sieht Anlass für weitere Studien."}},faq={{q="Wer bittet um die Fetische?",a="Der Gelehrte, der Bruder Nimetz' Schädelspalter-Fetische untersucht hat, bittet Euch, Trollfetische aus I'lalai zu bringen.",al={"wer will fetische","gelehrter fetische"}},{q="Warum werden die Fetische gesammelt?",a="Der Gelehrte möchte untersuchen, ob I'lalais Fetische mit der dunklen Magie zusammenhängen, die die Stadt Gerüchten zufolge emporgehoben hat.",al={"warum fetische sammeln","fetische studieren"}},{q="Was ist I'lalai?",a="I'lalai ist eine verlorene Trollstadt, die Gerüchten zufolge unter dem Wasser emporgehoben wurde.",al={"versunkene stadt","trollstadt"}},{q="Was fällt an den Fetischen aus I'lalai auf?",a="Sie zeigen eine gewaltige Seeschlange. Ihre Machart ist in mancher Hinsicht kunstvoller und in anderer schlichter als die der zuvor untersuchten Fetische.",al={"fetisch-design","seeschlangenfetisch"}},{q="Welche Mächte versammeln sich in I'lalai?",a="Euer Bericht beschreibt umherstreifende Untote, einfallende Piraten, Blutrituale und Naga in den Ruinen.",al={"wer ist in ilalai","untote piraten naga"}}},fp="26,142,18.273.0,11.331.1,26.111.0,36.115.0,16.74.0,43.148.0,38.104.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="Eine Kontaktperson von Baron Revilgaz schickt Euch auf der Suche nach den Saltseers in die Drowned City, Piraten, die magische Artefakte sammeln. Ihre gestohlenen Waren haben Aufmerksamkeit erregt, seit die versunkene Trollruine wieder aufgetaucht ist.",h="Eine Kontaktperson von Baron Revilgaz schickt Euch auf der Suche nach den Saltseers in die Drowned City...",kw={"baron revilgaz","drowned city","magische artefakte","piraten","saltseers","shady saltseers","trollruine","voodoo infused artifacts"},sec={{t="Die Bitte eines Barons",b="Eine Kontaktperson von Baron Revilgaz bittet Euch, Artefakte von den Saltseers in der Drowned City zurückzuholen. Die Piraten sammeln magische Gegenstände, und seit die Ruine wieder aufgetaucht ist, gibt es dort Waren zu holen. Ihre gestohlenen Artefakte sind es, die Revilgaz’ Kontaktperson sucht."}},faq={{q="Wer will die Artefakte der Saltseers?",a="Eine Kontaktperson von Baron Revilgaz bittet Euch, die Artefakte zurückzuholen.",al={"wer hat mich geschickt","kontaktperson von baron revilgaz","wer will artefakte"}},{q="Wer sind die Saltseers?",a="Die Saltseers sind Piraten, die magische Artefakte sammeln.",al={"saltseer-piraten","wer sind saltseers","saltseers"}},{q="Wo sind die Saltseers?",a="Sie sind in der Drowned City, einer versunkenen Trollruine, die wieder aufgetaucht ist.",al={"wo ist drowned city","aufenthaltsort der saltseers","drowned city"}},{q="Nach welchen Artefakten suche ich?",a="Ihr sollt Voodoo Infused Artifacts zurückholen, die von den Saltseers gestohlen wurden.",al={"was sammeln","voodoo-artefakte","gestohlene waren"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="Ein rivalisierender Jäger will Captain Dreadrise und seine Saltseer Coroners aus der Drowned City loswerden. Ihre Mannschaft sammelt ständig die magischen Artefakte, die er sucht.",h="Ein rivalisierender Jäger will Captain Dreadrise und seine Saltseer Coroners aus der Drowned City loswerden.",kw={"captain dreadrise","drowned city","magische artefakte","piraten","saltseer","saltseer coroners"},sec={{t="Ein Rivale in der Stadt",b="Ein rivalisierender Jäger sucht Eure Hilfe in der Drowned City, wo ihm die Saltseer-Piraten ein Dorn im Auge sind. Captain Dreadrise und seine Saltseer Coroners sammeln die magischen Artefakte, die er haben will. Er bittet Euch, den Kapitän und drei seiner Mannschaftsmitglieder aus dem Weg zu räumen."}},faq={{q="Wer ist Captain Dreadrise?",a="Captain Dreadrise führt die Saltseer-Piraten in der Drowned City an.",al={"dreadrise","saltseer-kapitän","kapitän typ"}},{q="Wer sind die Saltseer Coroners?",a="Die Saltseer Coroners sind Mannschaftsmitglieder, mit denen Captain Dreadrise beim Sammeln magischer Artefakte zusammenarbeitet.",al={"saltseer-mannschaft","coroners","dreadrises mannschaft"}},{q="Warum will der Auftraggeber Dreadrise loswerden?",a="Captain Dreadrise und seine Mannschaft sammeln ständig magische Artefakte, nach denen der Auftraggeber sucht, und er hat die Konkurrenz satt.",al={"warum dreadrise töten","warum kapitän beseitigen","dreadrises rivale"}},{q="Wo sind Captain Dreadrise und die Saltseers?",a="Captain Dreadrise und die Saltseer-Piraten sind in der Drowned City.",al={"wo ist dreadrise","saltseer aufenthaltsort","piraten der drowned city"}},{q="Was soll ich für den Auftraggeber tun?",a="Der Auftraggeber bittet Euch, Captain Dreadrise und drei Saltseer Coroners in der Drowned City zu töten.",al={"was ist zu tun","dreadrise quest","saltseer aufgabe"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95792"] = {n="Clear 'em Out",s="Gelinda Coppergleam will die Drachen aus einer Höhle mit reichen Mineralvorkommen vertreiben. Sie bietet eine Belohnung und eine Gewinnbeteiligung, falls ihr Bergbauvorhaben Gewinn abwirft.",h="Gelinda Coppergleam will die Drachen aus einer Höhle mit reichen Mineralvorkommen vertreiben.",kw={"höhle","cinderscale-krieger","cinderscale-welpen","vertreibt sie","gelinda coppergleam","mineralvorkommen","bergbau"},sec={{t="Ein Höhlenvorhaben",b="Gelinda Coppergleam hat in der Höhle hinter sich Mineralvorkommen entdeckt, doch Cinderscale-Drachen versperren den Weg. Sie bittet Euch, sie zu vertreiben, damit sie ein Bergbauteam holen kann. Dafür bietet sie Euch eine Belohnung und verspricht Euch einen Anteil, falls das Vorhaben Gewinn abwirft."}},faq={{q="Wer ist Gelinda Coppergleam?",a="Gelinda Coppergleam plant ein Bergbauvorhaben in einer Höhle mit reichen Mineralvorkommen.",al={"gelinda","wer ist gelinda","coppergleam"}},{q="Was soll Gelinda aus der Höhle vertreiben lassen?",a="Gelinda bittet Euch, die Cinderscale-Welpen und -Krieger aus der Höhle zu vertreiben.",al={"vertreibt sie","was ist in der höhle","drachenproblem"}},{q="Was befindet sich in der Höhle?",a="Die Höhle birgt unerschlossene Mineralvorkommen sowie Cinderscale-Welpen und -Krieger.",al={"höhlenmineralien","mineralvorkommen","was ist hinter gelinda"}},{q="Was bietet Gelinda an?",a="Gelinda bietet eine Belohnung und verspricht Euch einen Anteil, sobald ihr Bergbauvorhaben Gewinn abwirft.",al={"was ist die belohnung","gelindas angebot","anteil am bergbaugewinn"}}},fp="13,153,14.261.0,27.86.0,35.76.0,20.83.0,24.88.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Bei der Ausgrabung hinterlässt ein gefallener Zwerg eine düstere Nachricht für seinen Bruder in Seenhain. Dorin Songblade erfährt, was seinem Bruder widerfahren ist, und steht vor den Geschenken, die er nicht rechtzeitig vollenden konnte.",h="Bei der Ausgrabung hinterlässt ein gefallener Zwerg eine düstere Nachricht für seinen Bruder in Seenhain.",kw={"schmied","dorin","dorin songblade","zwerg","ausgrabung","ausgrabungsstätten","fallen in the fen","seenhain","songblade"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr einem trauernden Handwerker im Rotkammgebirge Trost spenden. Ein Bewohner der Stadt sucht in unruhigen Zeiten für das Königreich nach Gewissheit.",["profession:Blacksmithing"]="Als Schmied versteht Ihr, mit welcher Sorgfalt Dorin die Waffen fertigte, die seinen Bruder überraschen sollten. Nun erinnert die Ausrüstung an den frühen Tod seines Bruders.",["race:Dwarf"]="Als Zwerg kennt Ihr die Trauer, einen Bruder an uralte Ausgrabungsstätten und ungezähmte Wildnis zu verlieren. Ihr wisst, dass geschmiedetes Metall die Hand überdauern kann, die es halten sollte."},sec={{t="Tragödie bei der Ausgrabung",b="An den Ausgrabungsstätten liegt ein abenteuerlustiger Zwerg tot am Boden. Ihr bedeckt seine sterblichen Überreste mit seinem eigenen Umhang, bringt dann die düstere Nachricht nach Seenhain und sucht seine Angehörigen auf."},{t="Die Trauer eines Bruders",b="Dorin Songblade ist ein zwergischer Handwerker in Seenhain. Als er vom Schicksal seines Bruders erfährt, überwältigt ihn die Trauer. Wochenlang arbeitete er an seiner Schmiede an einer Ausrüstung als Überraschung, doch vor der Expedition seines Bruders wurde sie nicht fertig. Er bereut, ihn nicht begleitet zu haben.\n\nDorin bringt es nicht über das Herz, das mit eigenen Händen Geschaffene umzuschmieden, zu verkaufen oder zu behalten. Also gibt er die fertigen Stücke demjenigen, der ihm Gewissheit gebracht hat."}},faq={{q="Was ist Fallen in the Fen?",a="An den Ausgrabungsstätten findet Ihr einen gefallenen Zwerg und bedeckt seinen Leichnam mit seinem eigenen Umhang. Dann überbringt Ihr seinem trauernden Bruder, Dorin Songblade, in Seenhain die Nachricht von seinem Schicksal.",al={"was ist fallen in the fen","fallen in the fen quest"}},{q="Wer ist Dorin Songblade?",a="Dorin Songblade ist ein zwergischer Schmied in Seenhain. Er hatte an einer Ausrüstung als Überraschung für seinen Bruder geschmiedet, als er von dessen Tod an den Ausgrabungsstätten erfuhr.",al={"wer ist dorin songblade","dorin in seenhain","dorin songblade rolle"}},{q="Wer ist der gefallene Zwerg, der bei der Ausgrabung gefunden wurde?",a="Der gefallene Zwerg war Dorin Songblades Bruder. Vor seiner Expedition kam er durch Seenhain, um Vorräte zu beschaffen, und fand dann draußen den Tod.",al={"wer starb im morast","toter zwerg ausgrabung","wessen leichnam liegt in der ausgrabung"}},{q="Wo ist Dorin Songblade zu finden?",a="Dorin Songblade lebt in Seenhain, der wichtigsten Siedlung im Rotkammgebirge. Er arbeitet dort an der Schmiede.",al={"wo ist dorin songblade","dorin songblade aufenthaltsort"}},{q="Was schmiedete Dorin für seinen Bruder?",a="Dorin schmiedete Ausrüstung als Überraschungsgeschenk für seinen Bruder. Die Arbeit war noch nicht vollendet, als sein Bruder zu seiner Expedition aufbrach. Dorin bringt es nicht über das Herz, die Ausrüstung zu behalten, umzuschmieden oder zu verkaufen.",al={"was schmiedete dorin","dorin überraschungsgeschenk"}},{q="Warum verschenkt Dorin die Gegenstände, die er gefertigt hat?",a="Dorin bereut, seinen Bruder nicht begleitet zu haben, und bringt es nicht über das Herz, seine geschmiedeten Waffen zu behalten, umzuschmieden oder zu verkaufen. Er gibt die fertigen Stücke dem Reisenden, der ihm Nachricht von seinem Bruder gebracht hat.",al={"warum verschenkte dorin die ausrüstung","warum erhält man von dorin ausrüstung"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95798"] = {n="The Web of Magic",s="Ein Freund bittet Euch, das I'lalai Fetish zu Abra Cadabra nach Dalaran zu bringen. Sie interessiert sich für Trollmagie und möchte es untersuchen.",h="Ein Freund bittet Euch, das I'lalai Fetish zu Abra Cadabra nach Dalaran zu bringen.",kw={"abra cadabra","widersprüchliche magien","dalaran","i'lalai fetish","kirin tor","meister der lehren dibbs","trollmagie"},sec={{t="Ein Fetisch für Abra",b="Das I'lalai Fetish ist für Abra Cadabra in Dalaran bestimmt, wo sie es untersuchen kann. Ihr sollt es dorthin bringen, obwohl der Kirin Tor bei Besuchern seiner Stadt wählerisch sein könnte."},{t="Abrаs Erkenntnisse",b="Abra Cadabra entdeckt mehrere verschiedene Magien, die am Fetisch zerren, von denen einige miteinander im Konflikt stehen. Sie warnt, dass er in unvorsichtigen Händen gefährlich sein könnte, und sagt, sie werde ihre Erkenntnisse an Meister der Lehren Dibbs schicken."}},faq={{q="Wer ist Abra Cadabra?",a="Abra Cadabra ist eine Freundin der Person, die Euch bittet, ihr das I'lalai Fetish zu bringen. Sie interessiert sich für Trollbräuche und Magie.",al={"wer ist abra","abra cadabra","abra"}},{q="Was ist das I'lalai Fetish?",a="Das I'lalai Fetish ist ein Gegenstand, den Abra Cadabra wegen seiner verschiedenen und miteinander in Konflikt stehenden Magien untersucht.",al={"was ist das fetish","i'lalai ding","fetisch"}},{q="Warum möchte Abra es untersuchen?",a="Abra interessiert sich besonders für Trollbräuche und Magie, und das Fetisch ist ein Fund, den sie untersuchen kann.",al={"warum abra es will","abra interessiert","trollmagie"}},{q="Wohin soll das Fetisch gebracht werden?",a="Ihr sollt das I'lalai Fetish zu Abra Cadabra nach Dalaran bringen.",al={"wohin mit dem fetisch","lieferung nach dalaran","abras aufenthaltsort"}},{q="Warum könnte es schwierig sein, nach Dalaran zu gelangen?",a="Der Kirin Tor kann wählerisch sein, wen er nach Dalaran lässt, und Ihr müsst Euch vielleicht erst seine Gunst verdienen.",al={"nach dalaran gelangen","einlass beim kirin tor","zugang zu dalaran"}}},fp="16,131,17.184.0,15.204.1,20.132.0,27.95.0,33.108.0,33.69.0,38.110.0"}
P.entries["quest:95799"] = {n="Findings for the Explorer's League",s="Meister der Lehren Dibbs bittet Euch, seine Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in Eisenschmiede zu bringen. Karnik sieht die Entdeckung als Grund, ein Team in Richtung der verlorenen Stadt zu schicken.",h="Meister der Lehren Dibbs bittet Euch, seine Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in...",kw={"explorer's league","funde für die explorer's league","historiker karnik","i'lalai","eisenschmiede","meister der lehren dibbs","tafeln","übersetzungen","trolle"},sec={{t="Ein Brief nach Eisenschmiede",b="Historiker Karnik ist der Kollege von Meister der Lehren Dibbs bei der Explorer's League in Eisenschmiede. Dibbs hat eine Entdeckung gemacht, die er für geschichtlich bedeutsam hält, und bittet Euch, seinen Brief und eine Abschrift seiner Übersetzungen der I'lalai-Tafeln zu Karnik zu bringen."},{t="Karniks Antwort",b="Karnik begrüßt Dibbs' Übersetzungen und sagt, er werde ein Team zusammenstellen, um die verlorene Stadt I'lalai zu suchen. Seine eigenen Studien betreffen andere Themen, doch er respektiert Dibbs' Interesse an Trollen."}},faq={{q="Wer bittet mich, den Brief zu überbringen?",a="Meister der Lehren Dibbs bittet Euch, seinen Brief und eine Abschrift seiner Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in Eisenschmiede zu bringen.",al={"wer hat mir das gegeben","dibbs brief","wer ist meister der lehren dibbs"}},{q="Wer ist Historiker Karnik?",a="Historiker Karnik ist der Kollege von Meister der Lehren Dibbs bei der Explorer's League in Eisenschmiede, der Dibbs' Brief und Übersetzungen entgegennimmt.",al={"wer ist karnik","karnik eisenschmiede","historiker"}},{q="Was sind die I'lalai-Übersetzungen?",a="Es sind Meister der Lehren Dibbs' Übersetzungen von Tafeln, die mit I'lalai in Verbindung stehen.",al={"ilalai-übersetzungen","tafeln übersetzungen","dibbs tafeln"}},{q="Warum möchte Dibbs, dass ich den Brief überbringe?",a="Dibbs sagt, die Entdeckung sei von großer geschichtlicher Bedeutung, und möchte, dass sein Kollege in Eisenschmiede umgehend davon erfährt.",al={"warum den brief überbringen","warum eisenschmiede","was braucht dibbs"}}},fp="34,175,21.244.0,17.183.1,37.124.0,24.120.0,34.72.0,42.114.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha schickt Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen. Die Übergabe soll den Verlassenen zeigen, dass Euer Volk sich ihrem Wohlergehen verschrieben hat.",h="Danitha schickt Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",kw={"a token of good faith","danitha","dark lady","verlassene","licht","rudolph gelhardt","sylvanas windläufer","unterstadt"},sec={{t="Ein Zeichen der Treue",b="Danitha sagt, Sylvanas misstraue Eurem Volk und verunglimpfe es offen. Sie bittet Euch, Rudolph Gelhardts Kopf als Beweis zu bringen, dass Ihr vor der eigenen Haustür kehrt und an der Seite der Verlassenen steht."},{t="Die Antwort der Dark Lady",b="Sylvanas bezweifelt, dass Danithas Orden verhindern kann, dass weitere seiner Mitglieder das Licht gegen ihr eigenes Volk wenden. Sie warnt, dass sie den Orden vielleicht nicht länger dulden wird, wenn er nicht mehr den Interessen der Verlassenen dient. Der Orden wird beobachtet werden."}},faq={{q="Wer bittet mich, Rudolph Gelhardts Kopf zu Sylvanas zu bringen?",a="Danitha bittet Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",al={"wer schickt mich zu sylvanas","danitha kopfübergabe","kopf zur dark lady"}},{q="Warum will Danitha, dass ich den Kopf zu Sylvanas bringe?",a="Danitha will mit der Übergabe Sylvanas zeigen, dass Euer Volk vor der eigenen Haustür kehrt und sich dem Wohlergehen der Verlassenen verschrieben hat.",al={"warum rudolphs kopf bringen","wozu dient diese übergabe","treue beweisen"}},{q="Warum misstraut Sylvanas Danithas Volk?",a="Danitha sagt, Sylvanas misstraue Eurem Volk zutiefst und verunglimpfe es beinahe offen.",al={"warum sylvanas uns misstraut","misstrauen der dark lady","warum verunglimpft sie uns"}},{q="Wohin bringe ich Rudolph Gelhardts Kopf?",a="Ihr werdet gebeten, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",al={"wo ist sylvanas","ort der kopfübergabe","in die unterstadt bringen"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Auf der Hochwolkenebene werden An'she und Mu'sha als Augen der Erdenmutter geehrt. Ihr tragt glimmendes Räucherwerk zu einem Schrein in den südöstlichen Hügeln, wo sein Rauch zu Sonne und Mond aufsteigt, die den Ebenen Wärme, Leben und Orientierung schenken.",h="Auf der Hochwolkenebene werden An'she und Mu'sha als Augen der Erdenmutter geehrt.",kw={"an'she","erdenmutter","mond","mu'sha","mulgore","die hochwolkenebene","schrein","glimmendes räucherwerk","sonne","tauren"},ang={["class:Druid"]="Als Druide der Tauren seht Ihr im ewigen Tanz von Sonne und Mond das ursprüngliche Gleichgewicht der Natur, das Euer Verständnis ihrer kosmischen Rhythmen leitet.",["class:Shaman"]="Als Schamane der Tauren sprecht Ihr mit den Geistern von Erde, Feuer, Wasser und Luft und ehrt gleichermaßen die himmlischen Zwillinge, deren Licht die Lebensenergie erhält.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr die heiligen Riten auf der Hochwolkenebene und die naturverbundenen Bräuche, die die nomadischen Tauren ihren Verbündeten nahebringen.",["race:Tauren"]="Als Tauren lernt Ihr, dass das Leben Euch dazu aufruft, An'she und Mu'sha ebenso treu wie die Erdenmutter zu ehren. Ihre Verehrung bildet den Kern der spirituellen Identität der Tauren und erinnert junge Krieger an ihre Pflicht."},sec={{t="Die Augen der Erdenmutter",b="Die Tauren ehren An'she und Mu'sha als Sonne und Mond, die Zwillingsaugen der Erdenmutter. Elementargeister wohnen in Azeroths Steinen, Winden und Gewässern, während die himmlischen Zwillinge aus den Höhen des Himmels wachen. Auf ihrem Weg über den Himmel bestimmen sie Tag und Nacht und schenken Lebewesen Wärme, Orientierung und Hoffnung. Für die Tauren ist es eine spirituelle Pflicht, sie zu ehren. Das Gleichgewicht verlangt Ehrfurcht vor dem Land unter Euren Füßen und dem Licht darüber."},{t="Eine Opfergabe auf den Höhen",b="Tragt glimmendes Räucherwerk in die südöstlichen Hügel mit Blick auf die Hochwolkenebene, unmittelbar südlich der stacheligen Borstennackengebiete. Legt den Weg zügig und achtsam zurück. Haltet die Glut trocken und erreicht den Schrein, bevor sie zu kalter Asche verglimmt. Werft sie am hoch gelegenen Schrein in das Sacred Fire. Ihr duftender Rauch trägt Eure Ehrerbietung himmelwärts, zu Sonne und Mond."}},faq={{q="Wer sind An'she und Mu'sha?",a="Im Glauben der Tauren sind An'she und Mu'sha Sonne und Mond und werden als Zwillingsaugen der Erdenmutter geehrt. Sie leuchten von oben, anders als die Geister, die in Azeroths Erde, Luft, Feuer und Wasser wohnen. An'she bringt Wärme und Leben, während Mu'sha durch die Nacht hindurch Orientierung und Trost spendet.",al={"wer sind anshe und musha","geschichte von anshe und musha","sonnen- und mondgötter der tauren"}},{q="Warum bringen die Tauren Sonne und Mond Opfergaben dar?",a="Die Lehren der Tauren besagen, dass Gleichgewicht für das Dasein unerlässlich ist. An'she und Mu'sha schenken Lebewesen Kraft, Sehkraft und Hoffnung. Indem Tauren an einem hoch gelegenen Ort Räucherwerk darbringen, erweisen sie beiden Himmelslichtern Respekt, von deren beständigem Wohlwollen das Leben der Sterblichen abhängt.",al={"warum sonne und mond verehren","verehrung der himmelslichter bei den tauren","warum anshe und musha ehren"}},{q="Wo befindet sich der Schrein von An'she und Mu'sha?",a="Der Schrein liegt in den hohen Hügeln südöstlich der Hochwolkenebene, mit Blick auf die Ebenen und unmittelbar südlich der dornigen Borstennackengebiete. Seine Höhe bietet einen klaren, ungehinderten Blick auf den offenen Himmel, zu dem der Rauch aufsteigen kann.",al={"wo ist der schrein von anshe","standort des schreins in mulgore","wie den räucherwerkschrein finden"}},{q="Welche Bedeutung hat das glimmende Räucherwerk?",a="Glimmendes Räucherwerk trägt das Gebet und die Ehrerbietung eines Reisenden zu Sonne und Mond. Sein duftender Rauch steigt aus der brennenden Glut auf. Werft sie in das Feuer des Schreins, um den Ritus zu vollenden und dem Pilger ein friedvolles Gefühl spiritueller Erfüllung zu schenken.",al={"was bewirkt das räucherwerk","bedeutung des räucheropfers","warum glimmendes räucherwerk verbrennen"}},{q="Warum muss das Räucherwerk schnell überbracht und trocken gehalten werden?",a="Das Räucherwerk muss noch glimmen, wenn es das Feuer des Schreins erreicht, daher verlangt der Weg Wachsamkeit, Schnelligkeit und Sorgfalt. Erreicht das Ziel, bevor die Glut zu kalter Asche verglimmt, und schützt sie vor Wasser, das sie löschen und die Opfergabe verderben würde.",al={"warum zeitlimit beim räucherwerk","vor nässe schützen","räucherwerk verglimmt"}},{q="Bedrohen die Borstennacken die Pilgerreise zum Schrein?",a="Borstennackenstämme besetzen befestigte Dornenbaue in den Hügeln unmittelbar nördlich des Schreins. Der Schrein liegt an einem ruhigen Aussichtspunkt südlich ihrer Gebiete, doch Reisende müssen die Dornengestrüppe der Borstennacken meiden, wo ein Angriff die Reise verzögern oder unterbrechen könnte.",al={"borstennacken nahe dem schrein","bedrohen borstennacken die pilger","borstennacken südlich der hochebene"}},{q="Wie unterscheidet sich Mu'sha von den Mondvorstellungen anderer Kulturen?",a="Die Tauren nennen den Mond Mu'sha, das liebevolle linke Auge der Erdenmutter, das auf das Leben der Sterblichen herabblickt. Nachtelfen verehren denselben leuchtend weißen Mond als Elune, während die Tradition der Tauren Mu'sha mit ihrem Sonnenzwilling An'she verbindet.",al={"ist musha elune","mond der tauren und elune im vergleich","musha und die nachtelfen"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Im Sumpfland hat Ardin Grassman die Gefahren der Marschen überlebt und schickt Nachricht zum Hafen von Menethil. Ein Reisender bringt Caitlin Grassman ein Schilfherz.",h="Im Sumpfland hat Ardin Grassman die Gefahren der Marschen überlebt und schickt Nachricht zum Hafen von...",kw={"caitlin grassman","grassman","heartwoven","hafen von menethil","schilfherz","schilf","sumpfland"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr helfen, die gefährlichen Sumpfwege rund um den Hafen von Menethil für die Zivilisten zu sichern, die auf sie angewiesen sind.",["profession:Cooking"]="Als Caitlin erfährt, dass ihr Partner überlebt hat, macht sie sich daran, eine warme, herzhafte Mahlzeit vorzubereiten, um ihn zu Hause willkommen zu heißen."},sec={{t="Ein Zeichen aus den Marschen",b="Ardin Grassman wollte die seltsamen Gräser an den Ausgrabungsstätten im Sumpfland sehen, saß dann aber inmitten der Gefahren der Marschen fest. Ihr bahnt einen Weg durch die Wildnis und verschafft ihm so Zeit, sich auszuruhen und seine Ernte einzubringen. Müde, aber entschlossen bereitet Ardin sich darauf vor, in die Sicherheit des Hafens zurückzukehren."},{t="Zeichen für Menethil",b="Bevor Ardin den Heimweg antritt, nimmt er Sumpfschilf aus seinem Rucksack und flicht daraus ein Herz. Er gibt Euch dieses Zeichen, damit Ihr es Caitlin Grassman im Hafen von Menethil bringt. Sie wartet voller Sorge. Die Nachricht, dass Ardin überlebt hat und bald zurückkehrt, bringt Erleichterung, zusammen mit dem Schilfherz und dem Versprechen einer warmen Mahlzeit."}},faq={{q="Was ist die Quest Heartwoven?",a="Ein Reisender hilft Ardin Grassman, nachdem dieser an den Ausgrabungsstätten im Sumpfland gestrandet ist. Ardin fertigt ein Schilfherz an, um Caitlin Grassman, die im Hafen von Menethil wartet, von seinem Überleben und seiner Zuneigung zu künden.",al={"heartwoven quest","was ist heartwoven","sumpfland heartwoven"}},{q="Wer ist Caitlin Grassman?",a="Caitlin Grassman wartet im Hafen von Menethil voller Sorge auf ihren Mann Ardin. Seit er zu den Ausgrabungsstätten im Sumpfland aufgebrochen ist, fürchtet sie um sein Leben und ist erleichtert, als Ihr ihr von seinem Überleben berichtet.",al={"wer ist caitlin grassman","caitlin hafen von menethil","caitlin grassman"}},{q="Was ist das aus Schilf geflochtene Herz?",a="Das aus Schilf geflochtene Herz ist ein Zeichen, das Ardin aus dem Sumpfschilf in seinem Rucksack anfertigt. Er gibt es Euch mit, um Caitlin zu versichern, dass er lebt und bald nach Hause zurückkehrt.",al={"was ist das schilfherz","herz aus schilf geflochten","schilfgeflochtenes herz"}},{q="Wo wird Heartwoven abgegeben?",a="Ihr bringt Caitlin Grassman das Schilfherz im Hafen von Menethil, der Hafenstadt der Allianz an der Westküste des Sumpflands.",al={"wo heartwoven abgeben","heartwoven abgabeort","wo ist caitlin grassman"}},{q="Wer gibt Euch die Quest Heartwoven?",a="Ardin Grassman gibt Euch das Herz, damit Ihr es seiner Frau Caitlin bringt. Nachdem Ihr einen sicheren Weg durch das Sumpfland gebahnt habt, ruht er sich aus, sammelt seine Bündel ein und schickt Euch mit dem Zeichen voraus.",al={"wer vergibt heartwoven","wer fertigt das herz","der überlebende heartwoven"}},{q="Was ist dem gestrandeten Sammler widerfahren?",a="Ardin ging zu den Ausgrabungsstätten, um seltsame, hoch aufragende Gräser zu sehen, doch aufgescheuchte Wildtiere, vor allem Spinnen, überwältigten das Ausgrabungsteam. Ihr bahnt einen Weg durch die Gefahren ringsum, sodass Ardin überleben, seine Bündel einsammeln und zum Hafen von Menethil zurückkehren kann.",al={"was ist dem sammler widerfahren","lebt er noch","heartwoven überlebender"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Ihr tragt ein zerbrochenes Felsmech-Relikt durch das Sumpfland zu Ausgrabungsleiter Whelgar. Sein seltsames Material erregt die Aufmerksamkeit zwergischer Forscher.",h="Ihr tragt ein zerbrochenes Felsmech-Relikt durch das Sumpfland zu Ausgrabungsleiter Whelgar.",kw={"automat","ausgrabungsstätte","explorers league","lost relic carry","ausgrabungsleiter whelgar","felsmech","relikt der titanen","sumpfland"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie das Verbundmaterial und die komplexe Bauweise des Felsmechs auf mechanische Prinzipien hinweisen, die über die übliche Ingenieurskunst der Sterblichen hinausgehen.",["race:Dwarf"]="Als Zwerg teilt Ihr den Drang Eures Volkes, uralte Relikte seiner Schöpfer auszugraben. Dieses Bruchstück ist ein geschätzter Fund für das zwergische Erbe."},sec={{t="Ein Bruchstück uralter Handwerkskunst",b="Ein Felsmech hat ein zerbrochenes Stück seiner uralten Handwerkskunst hinterlassen. Sein unbekanntes Verbundmaterial weist es als Teil eines ausgeklügelten Mechanismus aus, der mit den Titanen verbunden ist."},{t="Lieferung zur Ausgrabung",b="Ausgrabungsleiter Whelgar untersucht uralte Überreste an der Ausgrabungsstätte im Sumpfland. Bringt ihm das Relikt sicher, und zwergische Gelehrte erhalten handfeste Beweise für ihre Erforschung ihres uralten Erbes."}},faq={{q="Was ist das Relikt der Titanen?",a="Das Relikt der Titanen ist ein zerbrochenes Stück eines uralten Felsmech-Automaten. Sein unbekanntes Verbundmaterial war Teil einer komplexen mechanischen Vorrichtung.",al={"was ist das relikt","was ist der gegenstand","felsmech-bauteil"}},{q="Wer ist Ausgrabungsleiter Whelgar?",a="Ausgrabungsleiter Whelgar ist ein zwergischer Forscher, der die Ausgrabungsstätte im Sumpfland leitet. Er untersucht uralte irdene Überreste und Relikte, die überall in der Region freigelegt werden.",al={"wer ist whelgar","whelgars geschichte","ausgrabungsleiter"}},{q="Wohin muss das Relikt gebracht werden?",a="Bringt das Relikt zu Ausgrabungsleiter Whelgar an seiner Ausgrabungsstätte im Sumpfland. Dort untersuchen zwergische Ausgräber uralte Ruinen.",al={"wohin bringen","wo abgeben","whelgars standort"}},{q="Was hat den Felsmech-Automaten erschaffen?",a="Das Bruchstück wird als Relikt der Titanen identifiziert. Zwergische Überlieferungen verbinden uralte mechanische Konstrukte und steinerne Automaten mit den rätselhaften Titanen, die die Welt formten.",al={"wer hat den felsmech erschaffen","ursprung des automaten","verbindung zu den titanen"}},{q="Warum behandelt Ausgrabungsleiter Whelgar das Relikt mit Ehrfurcht?",a="Whelgar weiß um die Gefahren des Weges in die Tiefen, in denen diese Automaten liegen. Er sagt, wer den Abstieg überlebt und mit einem unversehrten Stück zurückkehrt, verdient aufrichtigen Respekt.",al={"warum ist whelgar beeindruckt","gefährlicher abstieg"}},{q="Was ist am Material des Automaten ungewöhnlich?",a="Das Material des Automaten ist ein unbekannter Verbundstoff, der sich von gewöhnlichem Stein oder geschmiedetem Metall unterscheidet. Es zeugt von der ausgefeilten Handwerkskunst uralter Titanenkonstrukte.",al={"was ist das material","seltsamer verbundstoff"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
P.entries["quest:95882"] = {n="WANTED: Scoutmaster Vargas",s="Neza Bloodsnout will Scoutmaster Vargas aufhalten lassen, nachdem seine Kundschafterei die Horde behindert hat. Sein Auge soll beweisen, dass er fort ist.",h="Neza Bloodsnout will Scoutmaster Vargas aufhalten lassen, nachdem seine Kundschafterei die Horde behindert...",kw={"kundschafter der allianz","neza bloodsnout","flusslande","rog'mar","kundschaftergruppe","scoutmaster vargas","auge des spähermeisters"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr Neza, einen Kundschaftermeister der Allianz auszuschalten, dessen Spähgänge die Bewegungen der Horde behindert haben."},sec={{t="Nezas Jagd",b="Neza Bloodsnout hat Scoutmaster Vargas bereits ein Auge genommen, doch der Mensch konnte entkommen. Seine Kundschafterei erschwert es der Horde, die Bewegungen der Allianz zu verfolgen. Nun bittet Neza Euch, Vargas’ anderes Auge zurückzubringen, als Beweis, dass der Spähermeister nicht mehr ist."},{t="Der Bericht",b="Neza hört, dass Vargas tot ist, und sagt, die Flusslande seien nun sicherer für die Horde. Sie bedauert, dass er nach allem, was er gesehen hat, nicht blind weitergelebt hat."}},faq={{q="Wer ist Scoutmaster Vargas?",a="Scoutmaster Vargas ist ein Mensch, der eine Kundschaftergruppe der Allianz auf einer kleinen Insel nordöstlich von Rog'mar anführt.",al={"vargas","wer ist vargas"}},{q="Warum will Neza Vargas tot sehen?",a="Vargas’ Kundschafterei hat es der Horde erschwert, die Bewegungen des Feindes zu verfolgen, und Neza sagt, er wisse, dass sie ihn jagt.",al={"warum vargas töten","neza vargas"}},{q="Wo wurde Vargas gesichtet?",a="Eine von Vargas angeführte Kundschaftergruppe der Allianz wurde auf einer kleinen Insel nordöstlich von Rog'mar gesichtet.",al={"vargas insel","wo ist der spähermeister"}},{q="Was soll ich Neza zurückbringen?",a="Neza bittet Euch, ihr Scoutmaster Vargas’ anderes Auge als Beweis dafür zurückzubringen, dass er fort ist.",al={"vargas auge","welcher beweis"}},{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist in Rog'mar und will einen Beweis, dass Scoutmaster Vargas nicht mehr ist.",al={"neza","wer will vargas töten"}},{q="Was sagt Neza nach Vargas’ Tod?",a="Neza nimmt Vargas’ Tod hin und sagt, die Flusslande seien nun sicherer für die Horde.",al={"vargas ende","was geschieht danach"}}},fp="26,137,14.255.0,10.142.1,26.104.0,31.119.0,22.89.0,36.83.0,23.81.0,37.82.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="Bei Berens List im Silberwald wartet ein dunkler Ritus auf seine Vollendung. Eine zurückgelassene Notiz nennt die letzten benötigten Opfergaben: Blut und eine von Leid gezeichnete Seele.",h="Bei Berens List im Silberwald wartet ein dunkler Ritus auf seine Vollendung.",kw={"berens list","üble energie","blutopfer","opferstein","ritual","silberwald","die gequälte seele"},ang={["class:Priest"]="Der Ritus schöpft üble Energie aus leidenden Geistern und steht damit im scharfen Gegensatz zu den heilenden Grundsätzen des Heiligen Lichts.",["class:Warlock"]="Das Kanalisieren gepeinigter Seelen und das Vorbereiten dunkler Riten an uralten Opfersteinen spiegeln das finstere, manipulative Wesen dämonischer Magie und von Shadow Magic wider.",["race:Undead"]="Der Silberwald ist das Gebiet der Verlassenen, wo dunkle Magie und anhaltendes Leid die Grenzen Lordaerons bedrohen."},sec={{t="Ein hastiger Ritus",b="Bei Berens List im Silberwald birgt ein Altar die Überreste eines hastig vorbereiteten dunklen Ritus. Zwischen den verstreuten Materialien liegt eine gekritzelte Notiz. Die meisten Zutaten sind bereits beisammen, doch der Ritus verlangt noch nach Blut und einer Gequälten Seele."},{t="Unheilvolle Energien entfesselt",b="Die Kreaturen zwischen den zerklüfteten Felsen von Berens List erleiden große Qualen und eignen sich daher als Quellen der benötigten Essenz. Bringt diese Seele zum unheilvollen Opferstein, und üble magische Energie strömt daraus hervor. Der Ritus rückt seiner Vollendung näher."}},faq={{q="Was ist die Gequälte Seele?",a="Die Gequälte Seele erzählt von einem unvollendeten dunklen Ritus bei Berens List im Silberwald. Ein Opferstein wartet auf Blut und die Seele einer gepeinigten Kreatur.",al={"was ist die quest die gequälte seele","gequälte seele silberwald","berens list quest"}},{q="Wo findet dieses Ritual statt?",a="Der Ritualaltar und sein Opferstein befinden sich bei Berens List, einer gefährlichen Gebirgsenklave im Silberwald.",al={"wo ist das ritual","wo ist berens list","opferstein standort"}},{q="Welche Bestandteile werden für das Ritual benötigt?",a="Ein Notizzettel am Altar besagt, dass fast alle Materialien beisammen sind. Es fehlen nur noch Blut und eine Gequälte Seele.",al={"was wird für das ritual benötigt","ritualbestandteile berens list"}},{q="Wo findet Ihr die Gequälte Seele?",a="Die Kreaturen in den nahen Felsen von Berens List erleiden genug Qualen, um die vom Opferstein benötigte Essenz zu liefern.",al={"woher bekommt man die gequälte seele","wer hat die seele"}},{q="Was geschieht, wenn die Gequälte Seele zum Altar gebracht wird?",a="Die gequälte Seele zum Opferstein zu bringen, setzt üble Energie frei und bringt den dunklen Ritus seiner Vollendung näher.",al={"was geschieht beim bringen der seele","gequälte seele abgeben"}},{q="Wer hat das Ritual bei Berens List erschaffen?",a="Es wird kein Urheber genannt. Die Notiz und die eilig gesammelten Materialien deuten darauf hin, dass jemand den Altar hastig zwischen den feindseligen Bewohnern von Berens List errichtete.",al={"wer hat das ritual erschaffen","wer hat die notiz geschrieben"}}},fp="17,163,12.253.0,23.250.1,26.158.0,34.114.0,44.129.0,36.120.0,60.116.0,40.147.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="In Berens List wird am Offering Stone eine rituelle Opfergabe vorbereitet. Fragmente einer verwitterten Notiz weisen Reisenden den Weg zum Altar im Silberwald.",h="In Berens List wird am Offering Stone eine rituelle Opfergabe vorbereitet.",kw={"berens list","gerätschaften","offering stone","ritual","notizfetzen","silberwald","the offering stone"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr die finsteren Gerätschaften auf dem Opferstein als Zeichen ritueller Praktiken deuten, die ein eingehendes Studium lohnen.",["faction:Horde"]="Als Abenteurer der Horde im Silberwald solltet Ihr in den schattigen Felsklüften von Berens List nach verdächtigen Ritualen und Kultistenaktivitäten Ausschau halten."},sec={{t="Eine Zerfledderte Notiz",b="Ein verwitterter Papierfetzen aus dem Silberwald enthält Bruchstücke über ein Ritual und einen Opferstein in der Nähe. Zeit und Feuchtigkeit haben die meisten seiner Worte unleserlich gemacht. Folgt Ihr den Hinweisen nach Berens List, könnt Ihr den groben Altar in der Wildnis finden."},{t="Die Ritualstätte",b="In Berens List liegen seltsame Gerätschaften und bizarre Gegenstände über den rauen Stein verstreut. Jemand hat die Stätte genutzt, um fernab neugieriger Blicke eine Opfergabe oder einen finsteren Ritus vorzubereiten."}},faq={{q="Was ist der Offering Stone?",a="Der Offering Stone ist ein grober Altar in Berens List im Silberwald. Seltsame Gerätschaften und Gegenstände, die darauf verstreut liegen, deuten auf Vorbereitungen für eine Opfergabe oder einen finsteren Ritus hin.",al={"was ist der offering stone","offering stone silberwald","was ist dieser stein"}},{q="Wo ist der Offering Stone zu finden?",a="Ihr findet den Offering Stone in Berens List im südlichen Silberwald.",al={"wo ist der offering stone","offering stone standort","offering stone finden"}},{q="Wer hat den Offering Stone geschaffen oder nutzt ihn?",a="Die beschädigte Notiz nennt die Ritualisten nicht beim Namen. Auf dem Stein zurückgelassene Werkzeuge und Gegenstände zeigen, dass jemand in der Nähe eine Opfergabe oder einen finsteren Ritus vorbereitete.",al={"wer hat den offering stone geschaffen","wer nutzt den offering stone","wer vollzieht das ritual"}},{q="Was steht in der geheimnisvollen Notiz?",a="Der größte Teil der Notiz ist verwittert und unleserlich. Die erhaltenen Fragmente erwähnen Vorbereitungen für ein Ritual und weisen auf einen Opferstein in der Nähe hin.",al={"welche notiz","notizfetzen silberwald","was steht in der notiz"}},{q="Was liegt auf dem Offering Stone?",a="Seltsame Werkzeuge, Ritualgerätschaften und andere Gegenstände liegen über den rauen Stein verstreut, bestimmt für eine Opfergabe.",al={"welche gegenstände liegen auf dem stein","welche gerätschaften liegen auf dem stein","offering stone gegenstände"}},{q="Was für ein Ritual wird hier vollzogen?",a="Die Notiz beschreibt den Ritus nicht vollständig. Der Stein ist als Altar hergerichtet, auf dem Gegenstände oder Opfer für ein Ritual ausgelegt werden.",al={"welches ritual am offering stone","warum ein opferstein","welche opfergabe im silberwald"}}},fp="18,157,15.246.0,15.183.0,27.173.0,38.80.0,39.145.0,34.141.0,36.110.0,44.129.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="In Berens List verlangt der Zettelfetzen nach Blut am Offering Stone. Ihr bringt eine Gequälte Seele, um der Aufforderung zu folgen.",h="In Berens List verlangt der Zettelfetzen nach Blut am Offering Stone.",kw={"berens list","blutritual","offering of blood","offering stone","opfer","silberwald","the offering of blood","gequälte seele"},ang={["class:Priest"]="Als Priester mag Euch der Einsatz einer gequälten Seele in einem unheilvollen Blutritus beunruhigen, welches Schicksal sie auch erwartet.",["class:Warlock"]="Als Hexenmeister kennt Ihr dunkle Riten und den Handel mit Seelen. Selbst ein erfahrener Anwender der Teufelsmagie mag erschaudern, wenn er einem uralten, unbekannten Stein Blut darbietet."},sec={{t="Der letzte Ritus",b="Tief in Berens List wartet der Offering Stone auf eine letzte Opfergabe. Notizfetzen verlangen nach einem willigen Opfer und führen Euch dazu, Blut zum Altar zu bringen. Als Ihr Euch mit der ruhelosen Essenz nähert, ergreift Euch Grauen."},{t="Der Stein zerbricht",b="Die Gequälte Seele entzieht dem Stein seine verbliebene Macht. Der Ritus zehrt die Macht des uralten Monuments auf, statt einen größeren Schrecken zu wecken. Seine raue Oberfläche bekommt Risse, dann zerfällt es zu Schutt. Etwas Glitzerndes liegt zwischen den zerborstenen Bruchstücken."}},faq={{q="Wo findet dieses Ritual statt?",a="Der Ritus findet am Offering Stone in Berens List im Silberwald statt. Gefahren und finstere Magie suchen die Gegend heim.",al={"wo ist diese quest","wo ist offering of blood","berens list quest"}},{q="Was ist der Offering Stone?",a="Der Offering Stone ist ein uraltes Monument in Berens List. Er verlangt nach dem Blut eines willigen Opfers, um die Macht in seinem Inneren freizusetzen oder aufzuzehren.",al={"was ist der offering stone","offering stone berens list","altar in berens list"}},{q="Wofür wird die Gequälte Seele verwendet?",a="Eine Gequälte Seele wird am Offering Stone dargebracht, um der Forderung des Zettelfetzens nach einem willigen Opfer nachzukommen.",al={"wer ist die gequälte seele","was ist die gequälte seele","welches opfer wird benötigt"}},{q="Was geschieht, wenn die Opfergabe dargebracht ist?",a="Der Ritus zehrt die Macht auf, die den Offering Stone belebt. Der raue Stein bekommt Risse und zerbröckelt, wobei etwas Glitzerndes zwischen seinen Überresten zurückbleibt.",al={"was geschieht mit dem stein","zerbricht der stein","was geschieht nach dem ritual"}},{q="Wer hat den Stein erschaffen und warum?",a="Niemand weiß, wer den Offering Stone erschaffen hat oder warum. Der Ritus zehrt seine Macht auf und zerstört ihn, doch die Absicht seines Schöpfers bleibt unbekannt.",al={"wer hat den offering stone errichtet","zweck von offering of blood","warum wurde der stein erschaffen"}},{q="Was ist Berens List?",a="Berens List ist eine felsige Landmarke im Silberwald, wo wilde Tiere und verborgene Gefahren lauern. Auch dunkle Riten und ruhelose Seelen haben dort ihre Spuren hinterlassen.",al={"was ist berens list","berens list hintergrundgeschichte","warum heißt es berens list"}}},fp="21,114,14.216.0,18.241.1,34.127.0,27.140.0,35.106.0,44.144.0,30.132.0,22.161.0"}
P.entries["quest:959"] = {n="Ärger auf den Docks",s="In Ratschet gefährdet eine gestohlene Flasche Bigglefuzz' Arbeitsplatz. Mad Magglish floh mit einem 99 Jahre alten Portwein, einem Geschenk von Baron Revilgaz an Gazlowe, landeinwärts und versteckt sich nun in den Höhlen des Wehklagens.",h="In Ratschet gefährdet eine gestohlene Flasche Bigglefuzz' Arbeitsplatz.",kw={"bigglefuzz","beutebucht","gazlowe","magglish","portwein","ratschet","revilgaz","die höhlen des wehklagens"},ang={["class:Rogue"]="Als Schurke könnt Ihr Mad Magglishs nachlässige Tarnung in den Höhlennischen durchschauen, wo der Dieb sich mit einfachen Mitteln tarnt, um unbemerkt zu bleiben.",["faction:Alliance"]="Als Mitglied der Allianz reist Ihr tief ins von der Horde beherrschte Brachland, wo gute Beziehungen zu den Hafenbetreibern von Steamwheedle zur sicheren Durchfahrt durch neutrale Gewässer beitragen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr Ratschets Hafenarbeitern, den reibungslosen Betrieb des wichtigsten neutralen Hafens zwischen Kalimdor und den Östlichen Königreichen zu gewährleisten."},sec={{t="Ein ungeschicktes Missgeschick",b="Über Ratschets Docks läuft der Seehandel mit Beutebucht über das große Meer. Eines Morgens traf eine gewaltige Lieferung ein, und Kranführer Moppelfuzz überlud seinen Kran, um sie schneller zu entladen. Der Kran ließ die gesamte Ladung über die Docks fallen. Im Durcheinander schnappte sich Mad Magglish, ein örtlicher Unruhestifter, eine wertvolle Flasche Alkohol und floh landeinwärts."},{t="Ein diplomatischer Jahrgang",b="Die Flasche enthält einen 99 Jahre alten Portwein, ein persönliches diplomatisches Geschenk von Baron Revilgaz, Beutebuchts Herrscher, an Gazlowe, Ratschets Chefingenieur und Vorsteher. Ihr Verlust könnte Bigglefuzz demütigen und beide Handelsoberhäupter erzürnen. Aus Angst um seinen Arbeitsplatz oder vor Schlimmerem folgte Bigglefuzz dem Dieb bis zum Eingang der Höhlen des Wehklagens. Doch die Furcht hielt ihn davon ab, hineinzugehen."},{t="Das Höhlenversteck",b="Mad Magglish versteckt sich in feuchten Naturtunneln außerhalb des inneren Zugangs der Höhlen des Wehklagens, nicht tief in der verdorbenen Traumwelt. Der Dieb verlässt sich auf ungeschickte Tarnung und dunkle Nischen und hofft, dass seine Verfolger aufgeben. Findet Magglish in den äußeren Höhlen, bevor der Portwein entkorkt oder zerstört wird."}},faq={{q="Warum ist diese Flasche Portwein so wichtig?",a="Der 99 Jahre alte Portwein ist ein kostbares persönliches Geschenk von Baron Revilgaz aus Beutebucht an Gazlowe, Ratschets Oberhaupt. Sein Verlust könnte Ratschets Führung erzürnen und Kranführer Moppelfuzz seine Lebensgrundlage kosten.",al={"warum ist bigglefuzz das wichtig","was ist der 99 jahre alte portwein","warum ist der wein wichtig"}},{q="Wer ist Mad Magglish?",a="Mad Magglish ist ein Dieb und Unruhestifter, der sich in Ratschet herumtreibt. Als Bigglefuzz eine gewaltige Frachtladung auf die Docks fallen ließ, schnappte sich Magglish den seltenen Portwein und floh in die nahe gelegenen Höhlen des Wehklagens.",al={"wer ist magglish","wer hat den portwein gestohlen","mad magglish geschichte"}},{q="Muss ich den Dungeon der Höhlen des Wehklagens betreten, um den Dieb zu finden?",a="Nein. Mad Magglish versteckt sich in den gewundenen Höhlengängen außerhalb des Instanzportals und tarnt sich schlecht in den oberen Seitentunneln oder nahe den überfluteten Kammern am Haupteingang.",al={"ist magglish in der instanz","wo ist mad magglish","magglish finden"}},{q="Wie kam es zu dem Missgeschick mit der Fracht?",a="Eine gewaltige Frachtlieferung aus Beutebucht traf ein, und Kranführer Moppelfuzz versuchte, mehr Kisten auf einmal zu entladen, als seine Ausrüstung bewältigen konnte. Der überladene Kran ließ die Ladung über Ratschets Docks fallen.",al={"warum fielen die kisten herunter","was hat bigglefuzz getan","kranmissgeschick ratschet"}},{q="Welche Beziehung besteht zwischen Ratschet und Beutebucht?",a="Ratschet und Beutebucht sind Hafenstädte des Steamwheedle Cartel, verbunden durch Handel und Freibeuterflotten. Regelmäßige Lieferungen und förmliche Höflichkeiten zwischen Baron Revilgaz im Süden und Gazlowe im Brachland erhalten ihr gemeinsames Handelsimperium aufrecht.",al={"verbindung zwischen ratschet und beutebucht","steamwheedle häfen","revilgaz und gazlowe"}},{q="Warum hat Bigglefuzz die Flasche nicht selbst zurückgeholt?",a="Bigglefuzz folgte dem Dieb bis zum Eingang der Höhlen des Wehklagens, doch der unheimliche Ruf des unterirdischen Labyrinths und seine monströsen Bewohner ließen ihn an der Schwelle haltmachen.",al={"warum hat der goblin ihn nicht geholt","warum gab bigglefuzz die verfolgung auf"}}},fx={b908c2b9={q="Warum braucht Kranführer Moppelfuzz diesen Hafen zurück?",a="Moppelfuzz' Arbeit steht auf dem Spiel. Als er versuchte, mehr Kisten abzuladen, als sein Kran bewältigen konnte, stürzte die gesamte morgendliche Lieferung aus Beutebucht ab. In dem Chaos ging die wertvolle Flasche mit neunundneunzigjährigem Hafenwein verloren, und der Hafenmeister sitzt ihm seither im Nacken. Da der Jahrgang ein persönliches Geschenk für Ratschets Chefingenieur, Gazlowe, war, bedeutet das Versäumnis, ihn wiederzubekommen, dass Moppelfuzz kurz vor der Entlassung steht.",al={"warum will moppelfuzz den hafenwein","moppelfuzz motiv","warum moppelfuzz helfen"}}},fp="20,185,15.333.0,18.354.0,18.284.0,40.201.0,20.201.0,65.176.0,31.206.0,55.245.0,50.185.0"}
P.entries["quest:95912"] = {n="WANTED: Blademaster Kaijo",s="Ember Bladewhisper sucht Blademaster Kaijo in einem Ausbildungslager nördlich des Außenpostens der Horde. Sein Banner soll die Moral der Orcs schwächen und den Kampfeswillen von Embers Auszubildenden stärken.",h="Ember Bladewhisper sucht Blademaster Kaijo in einem Ausbildungslager nördlich des Außenpostens der Horde.",kw={"blademaster kaijo","blademaster’s banner","ember bladewhisper","burg farholde","außenposten der horde","kaijo","orc-auszubildende","ausbildungslager"},sec={{t="Ein Kampf gerät ins Wanken",b="Ember Bladewhisper fürchtet, dass jeder gefallene Orc durch einen fähigeren Soldaten ersetzt wird. Sie glaubt, ein Blademaster bilde sie aus, und sagt, Kaijo halte sich wahrscheinlich im Ausbildungslager nördlich des Außenpostens der Horde auf. Ihr sollt sein Banner zur Burg Farholde bringen."},{t="Der Zweck eines Banners",b="Ember sagt, die Bedrohung durch die Orcs scheine endlos, und der Kampfeswille ihrer Soldaten schwinde. Sie hofft, Kaijos Banner werde ihren Auszubildenden zeigen, dass die Horde nichts zu fürchten ist."}},faq={{q="Wer ist Blademaster Kaijo?",a="Ember Bladewhisper beschreibt Kaijo als Blademaster, der wahrscheinlich Orcs in einem Ausbildungslager nördlich des Außenpostens der Horde ausbildet.",al={"wer ist kaijo","kaijos hintergrund"}},{q="Warum will Ember Kaijo finden?",a="Ember glaubt, Kaijo bilde eine neue Generation fähiger Orc-Soldaten aus, und fürchtet, ihre Zahl werde wieder anwachsen.",al={"warum kaijo finden","grund für kaijos gesuchtmeldung"}},{q="Wo glaubt Ember, dass Kaijo ist?",a="Ember sagt, Kaijo halte sich wahrscheinlich im Ausbildungslager nördlich des Außenpostens der Horde auf.",al={"wo ist kaijo","kaijos aufenthaltsort"}},{q="Was soll zur Burg Farholde gebracht werden?",a="Ember bittet Euch, ihr das Blademaster’s Banner zur Burg Farholde zu bringen.",al={"kaijos banner","was nach farholde bringen"}},{q="Warum will Ember das Banner?",a="Ember hofft, das Banner werde die Moral der Orcs schwächen und ihren Auszubildenden versichern, dass die Horde nichts zu fürchten ist.",al={"zweck des banners","warum kaijos banner holen"}},{q="Was beunruhigt Ember am Kampf?",a="Ember fürchtet, die Bedrohung durch die Orcs sei endlos und der Kampfeswille ihrer Soldaten schwinde.",al={"ember ist besorgt","bedrohung durch orcs"}}},fp="25,187,17.254.0,18.164.0,25.126.0,32.111.0,32.74.0,46.75.0,31.106.0,35.84.0"}
P.entries["quest:95913"] = {n="Fit for a Princess",s="Tessa Dawnbright braucht warme Kojotenfelle für die Wiege ihrer Tochter Emma auf Burg Farholde. Sie hofft, dass weichere Laken dem Baby beim Schlafen helfen und Ruhe nach Burg Farholde bringen.",h="Tessa Dawnbright braucht warme Kojotenfelle für die Wiege ihrer Tochter Emma auf Burg Farholde.",kw={"baby","wiege","decken","kojotenfelle","emma","burg farholde","tessa dawnbright"},sec={{t="Die Bitte einer Mutter",b="Tessa wiegt Emma auf Burg Farholde und hofft, ihre weinende Tochter zu beruhigen. Ihr Mann hat eine Wiege gebaut, doch Tessa macht sich Sorgen, dass die Decken zu alt sind. Sie bittet Euch, Kojotenfelle zu bringen, um Emmas Bett damit auszulegen, und hofft, dass die wärmere Unterlage sie beruhigt."},{t="Willkommen zurück",b="Tessa begrüßt Euch, als Ihr mit den Fellen zurückkehrt. Sie findet sie warm und weich und sagt, dass sie für Emma sind. Tessa sieht müde aus, während sie sich um ihr Baby kümmert."}},faq={{q="Wer ist Tessa Dawnbright?",a="Tessa Dawnbright ist Emmas Mutter auf Burg Farholde.",al={"wer ist tessa","tessa dawnbright"}},{q="Wer ist Emma?",a="Emma ist die Tochter von Tessa Dawnbright.",al={"tessas baby","baby emma"}},{q="Warum braucht Tessa Kojotenfelle?",a="Tessa möchte Emmas Wiege mit warmen, weichen Fellen auslegen, weil sie befürchtet, dass die Decken zu alt sind.",al={"warum felle","kojotenfelle für tessa"}},{q="Wo lebt Tessa?",a="Tessa ist auf Burg Farholde.",al={"wo ist tessa","tessa auf burg farholde"}},{q="Was fehlt Emma?",a="Emma weint, und Tessa versucht, ihr beim Einschlafen zu helfen.",al={"warum weint das baby","emma weint"}}},fp="18,172,18.245.0,16.151.0,24.53.0,12.38.0,33.105.0,22.26.0,24.54.0"}
P.entries["quest:95934"] = {n="Proof of Profit",s="Gelinda Coppergleam hat in den Höhlen Hinweise auf cubic draconia gefunden, braucht aber einen Kristall als Beweis. Sie bittet Euch, ihr einen zu bringen, damit sie anderen seinen Wert zeigen kann.",h="Gelinda Coppergleam hat in den Höhlen Hinweise auf cubic draconia gefunden, braucht aber einen Kristall als...",kw={"höhlen","kristall","cubic draconia","dynamit","gelinda coppergleam","mineral","beweis des gewinns","vermessungsgeräte"},ang={["profession:Mining"]="Als Bergarbeiter könnt Ihr Gelinda Coppergleam einen cubic-draconia-Kristall bringen, um zu beweisen, dass es das Mineral gibt."},sec={{t="Ein Kristall als Beweis",b="Gelinda Coppergleams Vermessungsgeräte zeigen Hinweise auf ein neues Mineral in den Höhlen, das sie cubic draconia nennt. Messwerte allein werden die Leute nicht überzeugen, deshalb bittet sie Euch, einen Kristall als Beweis mitzubringen. In den Höhlen gibt es Drachen, und Gelinda sagt, dass Kristalle möglicherweise aus dem Erdreich herausragen."}},faq={{q="Wer ist Gelinda Coppergleam?",a="Gelinda Coppergleam hat mit ihren Vermessungsgeräten Hinweise auf cubic draconia in den Höhlen gefunden.",al={"gelinda","wer ist gelinda","coppergleam"}},{q="Was ist cubic draconia?",a="Cubic draconia ist ein Mineral, das Gelinda ihrer Ansicht nach in den Höhlen gefunden hat.",al={"cubic draconia","neues mineral","welches mineral"}},{q="Warum möchte Gelinda einen Kristall?",a="Gelinda möchte einen Kristall als Beweis dafür, dass es cubic draconia gibt, denn die Leute sehen lieber einen Kristall, als ihre Messwerte zu prüfen.",al={"warum ein kristall","beweis des gewinns","was ist der beweis"}},{q="Wo finde ich cubic draconia?",a="Gelinda sagt, dass Kristalle möglicherweise in den Höhlen aus dem Erdreich herausragen.",al={"wo ist draconia","fundort des kristalls","cubic draconia finden"}},{q="Gibt es Drachen in den Höhlen?",a="Ja. Gelinda warnt Euch, dass sich Drachen in den Höhlen aufhalten.",al={"drachenhöhle","gefahr in der höhle","drachen"}},{q="Was, wenn ich keinen Kristall herausbekomme?",a="Gelinda bietet an, Euch Dynamit zu leihen, falls Ihr Schwierigkeiten habt, cubic draconia aus dem Boden zu lösen.",al={"lässt sich nicht ausgraben","dynamit nötig","kristall steckt fest"}}},fp="15,171,19.293.0,27.93.0,23.72.0,32.125.0,32.73.0,31.49.0,34.97.0"}
P.entries["quest:95935"] = {n="Hail the Dragonslayer",s="Ihr bringt Scaldarons Kopf zu Cedric Dalton an der Southern Watch. Die Bedrohung durch den Drachen ist vorüber, und die Wachen sollten erfahren, was geschehen ist.",h="Ihr bringt Scaldarons Kopf zu Cedric Dalton an der Southern Watch.",kw={"cedric dalton","drache","gnolle","head of scaldaron","scaldaron","wachen","southern watch"},sec={{t="Neuigkeiten an der Southern Watch",b="Scaldarons Kopf ist ein grausiges Zeichen für die vergangene Gefahr. An der Southern Watch erfährt Cedric Dalton, was geschehen ist, wenn Ihr ihm den Kopf bringt. Die Wachen dort hatten geglaubt, Gnolle in den Hügeln seien ihre einzige Sorge."}},faq={{q="Wer bittet um den Head of Scaldaron?",a="Niemand schickt Euch dafür los. Mit dem Nehmen des Drachenkopfs beginnt dieser Auftrag, und Cedric Dalton nimmt ihn entgegen.",al={"wer will den drachenkopf","cedric daltons bitte"}},{q="Wohin soll ich den Head of Scaldaron bringen?",a="Bringt den Head of Scaldaron zu Cedric Dalton an der Southern Watch.",al={"wohin den kopf bringen","fundort des drachenkopfs"}},{q="Wer war Scaldaron?",a="Scaldaron war ein Drache, von dem keine Bedrohung mehr ausgeht.",al={"scaldaron drache","was ist scaldaron"}},{q="Warum sollten die Wachen erfahren, was geschehen ist?",a="Die Wachen an der Southern Watch sollten wissen, was nach dem Ende von Scaldarons Bedrohung geschehen ist.",al={"warum die wachen informieren","neuigkeiten an der southern watch"}}},fp="21,143,17.226.0,37.115.0,42.66.0,18.48.0,43.87.0"}
P.entries["quest:95943"] = {n="Foreman's Plight",s="Bertrand Ironbrow in Burg Farholde bittet Euch, die Kiste des Vorarbeiters zu finden und zurückzubringen. Er möchte sie wiederhaben.",h="Bertrand Ironbrow in Burg Farholde bittet Euch, die Kiste des Vorarbeiters zu finden und zurückzubringen.",kw={"bertrand ironbrow","kiste","burg farholde","kiste des vorarbeiters","missgeschick des vorarbeiters"},sec={{t="Eine vermisste Kiste",b="In Burg Farholde sucht Bertrand Ironbrow nach der Kiste des Vorarbeiters. Ihr sollt sie finden und zu ihm zurückbringen."}},faq={{q="Wer möchte die Kiste?",a="Bertrand Ironbrow in Burg Farholde bittet Euch, die Kiste des Vorarbeiters zu finden und zu ihm zurückzubringen.",al={"wer hat darum gebeten","bertrand ironbrow kiste"}},{q="Wonach suche ich?",a="Ihr sucht nach der Kiste des Vorarbeiters.",al={"welche kiste","kiste des vorarbeiters"}},{q="Wohin soll ich sie bringen?",a="Bringt die Kiste des Vorarbeiters zu Bertrand Ironbrow in Burg Farholde zurück.",al={"wohin kiste zurückbringen","kiste bringen"}}},fp="16,119,15.124.0,20.93.0,22.40.0,20.69.0"}
P.entries["quest:95951"] = {n="Fetch 'n' Fletch",s="Tan’jani bietet Euch an, beizubringen, wie Ihr Speere für die Kopfjäger der Horde herstellt. Ihr sollt Holz im Turner's Logging Camp holen, um daraus Speere zu schnitzen.",h="Tan’jani bietet Euch an, beizubringen, wie Ihr Speere für die Kopfjäger der Horde herstellt.",kw={"fetch 'n' fletch","kopfjäger","horde","behelfsmäßige speere","tan’jani","turner's logging camp","holzbündel"},sec={{t="Holz für Speere",b="Tan’jani, ein Kopfjäger, bittet Euch, Holz im Turner's Logging Camp zu sammeln, dem Menschenlager im Westen. Mit einem Messer könnt Ihr das Holz zu Speeren zuspitzen, um Menschen aufzuspießen, bevor sie Euch kommen sehen. Tan’jani möchte, dass Ihr die Speere zurückbringt."}},faq={{q="Wer ist Tan’jani?",a="Tan’jani ist ein Kopfjäger, der Euch anbietet, beizubringen, Speere herzustellen.",al={"tan’jani wer","wer ist tanjani"}},{q="Was möchte Tan’jani, dass ich hole?",a="Tan’jani bittet Euch, Holz von den Holzstapeln der Bauern im Turner's Logging Camp zu sammeln und daraus behelfsmäßige Speere herzustellen.",al={"welches holz","speere holen"}},{q="Wo ist das Holz?",a="Das Holz liegt auf den Holzstapeln der Bauern im Turner's Logging Camp, dem Menschenlager im Westen.",al={"fundort des holzes","wo ist das holz"}},{q="Warum möchte Tan’jani Speere?",a="Tan’jani sagt, Kopfjäger verwenden Speere, um Menschen zu treffen, bevor sie sie kommen sehen.",al={"warum speere","speere der kopfjäger"}}},fp="16,149,15.251.0,18.66.0,36.118.0,18.86.0,32.84.0"}
P.entries["quest:95955"] = {n="Stick 'Em",s="Tan'jani in Rog'mar bringt Euch in den Flusslanden das Speerwerfen bei. Freshwater Crocolisks dienen ihm als Ziele, und er hofft, Euch zu einem Kopfjäger auszubilden.",h="Tan'jani in Rog'mar bringt Euch in den Flusslanden das Speerwerfen bei.",kw={"freshwater crocolisk","kopfjäger","flusslande","rog'mar","speerwerfen","speere","spieß sie auf","tan'jani","tran'jani"},sec={{t="Ein Crocolisk als Ziel",b="Tan'jani in Rog'mar hat Speere für Euch und möchte, dass Ihr lernt, sie zu werfen. Die Flusslande sind voller Freshwater Crocolisks, die er für gefährlich hält. Er stellt sie als Ziele für Eure Übungen auf."},{t="Das Versprechen eines Kopfjägers",b="Nach Eurem Training lobt Tan'jani Eure Arbeit und sagt, Ihr habt das Zeug zu einem echten Kopfjäger. Er bittet Euch, an ihn zu denken, wenn Ihr berühmt werdet."}},faq={{q="Wer ist Tan'jani?",a="Tan'jani gibt Euch in Rog'mar Speere und bringt Euch bei, sie zu werfen.",al={"tran'jani","wer ist tran'jani","alter troll"}},{q="Warum schickt Tan'jani mich hinter Krokolisk her?",a="Tan'jani nutzt die Freshwater Crocolisks der Flusslande als Ziele für Speerwurfübungen.",al={"warum crocolisks","crocolisk-training","krokos aufspießen"}},{q="Was möchte Tan'jani, dass ich tue?",a="Tan'jani möchte, dass Ihr in den Flusslanden das Werfen von Speeren auf Freshwater Crocolisks übt.",al={"was soll ich tun","spieß sie auf","speerwurfziele"}},{q="Wo geschieht das?",a="Tan'jani gibt Euch in Rog'mar die Speere und weist Euch für das Training den Weg in die Flusslande.",al={"wo ist tran'jani","quest in den flusslanden","rog'mar"}},{q="Was sagt Tan'jani über die Krokolisken?",a="Tan'jani warnt, dass die Freshwater Crocolisks gefährlich sind und Euch schnappen können, wenn Ihr nicht schnell seid.",al={"sind krokos gefährlich","gefahr durch crocolisks","dich schnappen"}}},fp="9,179,18.199.0,22.153.1,16.82.0,43.98.0,33.91.0,24.92.0,44.101.0"}
P.entries["quest:95961"] = {n="Stepped Out",s="Tessa bittet Euch, Gray am Hafen von Powderfuse zu suchen. Er ist länger fort, als erwartet, und sie möchte ihn bei sich und Emma zu Hause haben.",h="Tessa bittet Euch, Gray am Hafen von Powderfuse zu suchen.",kw={"emma","familie","gray dawnbright","vermisster ehemann","hafen von powderfuse","kurz weggegangen","tessa"},sec={{t="Tessas Bitte",b="Tessas Baby Emma weint, als Tessa Euch bittet, nach Gray zu suchen. Er ist vor einer Weile aufgebrochen und nicht zurückgekehrt. Sie sagt, er gehe oft zum Hafen von Powderfuse, wo er mit seinem strahlenden Aussehen leicht zu erkennen sein sollte."}},faq={{q="Nach wem sucht Tessa?",a="Tessa bittet Euch, Gray, den Vater von Emma, am Hafen von Powderfuse zu suchen.",al={"wer ist gray","tessas mann finden","wo ist tessa gray"}},{q="Warum möchte Tessa, dass Gray nach Hause kommt?",a="Tessa sagt, Emma strahlt, wenn sie ihren Vater sieht, und sie möchte wissen, warum er nicht zurückgekommen ist.",al={"warum macht sich tessa sorgen","warum sie gray braucht","emmas vater"}},{q="Wohin ist Gray Tessa zufolge gegangen?",a="Tessa sagt, Gray scheint oft zum Hafen von Powderfuse zu gehen.",al={"grays aufenthaltsort","wo ist gray","hafen von powderfuse"}},{q="Woran kann ich Gray erkennen?",a="Tessa sagt, Gray strahlt so hell wie die Sonne.",al={"wie sieht gray aus","grays aussehen","wer strahlt hell"}}},fp="11,128,15.214.0,25.63.0,30.99.0,33.53.0,25.46.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Schattenpriester Allister schickt die Verlassenen gegen Patrouillen der Kirin Tor nahe Mühlenbern. Seit Dalarans Barriere gefallen ist, bewachen ihre Zauberer und Wachposten die Straßen in den Silberwald und bringen dabei magische Güter ins Gebiet der Verlassenen.",h="Schattenpriester Allister schickt die Verlassenen gegen Patrouillen der Kirin Tor nahe Mühlenbern.",kw={"mühlenbern","dalaran watcher","dalaran wizard","kirin tor","anhänger","relikte","das grabmal","schattenpriester allister","silberwald","watching the roads"},ang={["class:Mage"]="Als Magier steht Ihr Dalarans Zauberern und Wachposten gegenüber, die mit magischen Relikten und Patrouillen die Wege sichern. Ihre Arbeit macht sie zu Zielen rivalisierender Zauberwirker.",["class:Priest"]="Als Priester seht Ihr, wie Schattenpriester Allister die Offensive vom Grabmal aus leitet, wo Geistliche der Verlassenen aktiv an der Grenzverteidigung mitwirken.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Dalarans Versorgungslinien nahe Mühlenbern zu unterbrechen und die Region gegen feindliche Enklaven der Menschen zu halten.",["race:Undead"]="Als Untoter helft Ihr, die Straßen des Silberwalds zu sichern und die Grenzen der Verlassenen gegen Dalarans magische Vorstöße zu verteidigen."},sec={{t="Spannungen an der Straße nach Mühlenbern",b="Nahe Mühlenbern überwachen Zauberer und Wachen der Kirin Tor die Straßen in den Silberwald. Seit die Barriere um Dalaran gefallen ist, haben sie ihre Kontrolle über den Grenzverkehr verschärft. Vom Grabmal aus sehen die Verlassenen, wie die menschlichen Magier diese Straßen nutzen, um gefährliche Relikte und verzauberte Anhänger in umkämpfte Gebiete zu bringen."},{t="Die Versorgungslinie durchtrennen",b="Schattenpriester Allister will den Zustrom magischer Güter aus Dalaran an der Quelle stoppen. Er schickt Agenten gegen die Begleittruppen der Kirin Tor auf den Straßen nahe Mühlenbern. Durch Angriffe auf Dalaran Wizards und Dalaran Watchers wollen die Verlassenen die Kontrolle der Kirin Tor über den regionalen Reiseverkehr brechen und ihre Ostgrenze vor arkaner Einmischung von außen schützen."}},faq={{q="Wer vergibt die Quest Watching the Roads?",a="Schattenpriester Allister erteilt den Auftrag vom Grabmal im Silberwald aus. Er schickt Streiter gegen Patrouillen der Kirin Tor auf den örtlichen Straßen.",al={"wer vergibt watching the roads","questgeber watching the roads","wo watching the roads abgeben"}},{q="Warum greifen die Verlassenen Dalarans Patrouillen nahe Mühlenbern an?",a="Schattenpriester Allister will verhindern, dass magische Relikte und Anhänger aus Dalaran in den Silberwald gelangen. Angriffe auf die Zauberer und Wachposten nahe Mühlenbern unterbinden ihren Weg über die Grenzen der Verlassenen.",al={"warum dalaran wizards töten","warum straßen um mühlenbern angreifen","absichten der kirin tor im silberwald"}},{q="Wie steht es um die Barriere um Dalaran?",a="Die Barriere um Dalaran ist gefallen. Die Kirin Tor haben ihre Überwachung der nahen Straßen verstärkt und patrouillieren misstrauisch in der Gegend um Mühlenbern.",al={"was geschah mit dalarans barriere","dalarans kuppel gefallen","barriere gefallen dalaran"}},{q="Wo sind die Zauberer und Wächter von Dalaran zu finden?",a="Dalaran Wizards und Dalaran Watchers patrouillieren auf den Straßen rund um Mühlenbern im Silberwald. Sie überwachen den Reiseverkehr und bewachen Angehörige der Kirin Tor sowie verzauberte Gegenstände.",al={"wo sind dalaran watchers","patrouillenstandorte mühlenbern","wo dalaran wizards finden"}},{q="Welche Gegenstände transportiert Dalaran auf diesen Straßen?",a="Die Kirin Tor bringen verzauberte Anhänger und andere magische Relikte aus Dalaran in den Silberwald. Allister will sie aufhalten, bevor sich die Artefakte weiter im Gebiet verbreiten.",al={"welche relikte transportiert dalaran","was sind die anhänger","anhänger mühlenbern"}},{q="Warum sind die Kirin Tor auf den Straßen um Mühlenbern so wachsam?",a="Die Kirin Tor überwachen die Straßen in den Silberwald genau, seit Dalarans magische Barriere gefallen ist. Allister sieht ihr Misstrauen und ihre Wachsamkeit, doch die Verlassenen im Grabmal kennen ihre genauen Beweggründe nicht.",al={"warum sind die kirin tor paranoid","warum patrouillieren dalarans wachen","straßenkontrolle der kirin tor"}}},fp="18,228,33.326.0,24.339.0,39.144.0,62.207.0,54.143.0,52.161.0,57.187.0,60.210.0"}
P.entries["quest:95982"] = {n="Not My Circus",s="Jasper Geartoggle bittet Euch, verlassene Tiere im Hafen von Powderfuse mit Futter zu versorgen. Er braucht Briny Seafood Stew, bevor die hungrigen Tiere Ärger machen.",h="Jasper Geartoggle bittet Euch, verlassene Tiere im Hafen von Powderfuse mit Futter zu versorgen.",kw={"briny seafood stew","pferde","hungrige tiere","jasper geartoggle","nicht mein zirkus","hafen von powderfuse","wölfe"},sec={{t="Hungrige Tiere",b="Im Hafen von Powderfuse bittet Jasper Geartoggle Euch um Hilfe mit den Tieren, die man ihm anvertraut hat. Ihre Besitzer geben ihm die Schuld, wenn ein Pferd, ein Wolf oder ein anderes Tier stirbt oder davonläuft. Er braucht Briny Seafood Stew, um sie im Zaum zu halten, bevor der Hunger sie zu einer Stampede treibt."}},faq={{q="Wer bittet um Hilfe?",a="Jasper Geartoggle bittet Euch, die Tiere zu füttern, die man seiner Obhut überlassen hat.",al={"wer braucht hilfe","wer ist jasper","jasper geartoggle"}},{q="Was braucht Jasper?",a="Jasper braucht Briny Seafood Stew für die Tiere in seiner Obhut.",al={"welches futter will er","welcher eintopf","briny stew"}},{q="Warum braucht Jasper Eintopf?",a="Jasper sagt, die Tiere seien hungrig und er brauche Futter, um sie im Zaum zu halten.",al={"warum eintopf","hungrige tiere","tiere in not"}},{q="Wohin soll ich den Eintopf bringen?",a="Bringt den Briny Seafood Stew zu Jasper Geartoggle in den Hafen von Powderfuse.",al={"wo ist jasper","wohin eintopf bringen","hafen von powderfuse"}},{q="Warum werden Tiere bei Jasper gelassen?",a="Die Leute lassen Jasper immer wieder ihre Pferde, Wölfe und anderen Tiere da.",al={"verlassene tiere","wer hat die tiere dagelassen","warum sind die tiere hier"}}},fp="13,149,13.261.0,23.69.0,22.60.0,26.75.0,30.69.0,39.72.0"}
P.entries["quest:95984"] = {n="Song of the Strider",s="Watcher Cornelius fand nahe Terral’s Watch Spuren eines ungewöhnlich großen Löwen. Er braucht einen Tallstrider-Schnabel für eine Pfeife, die das Tier herauslocken soll.",h="Watcher Cornelius fand nahe Terral’s Watch Spuren eines ungewöhnlich großen Löwen.",kw={"demar","löwe","lied des tallstriders","tallstrider schnabel","terral’s watch","watcher cornelius","pfeife"},sec={{t="Die Spuren eines Löwen",b="Watcher Cornelius deutet die Spuren als die eines Löwen, vermutlich des Anführers eines Rudels in der Nähe. Er fürchtet Demars Zorn, falls sich herumspricht, dass unter seiner Aufsicht ein Menschenfresser umherstreift. Deshalb will er den Löwen mit einer Pfeife herauslocken, die wie der Ruf eines verwundeten Tallstriders klingt. Ihr sollt ihm einen unversehrten Schnabel für den Ruf bringen."}},faq={{q="Was hat Cornelius gefunden?",a="Watcher Cornelius fand Spuren, die seiner Meinung nach von einem besonders großen Löwen stammen, vermutlich dem Anführer eines Rudels in der Nähe.",al={"löwenspuren","welche spuren"}},{q="Warum braucht Cornelius einen Tallstrider-Schnabel?",a="Cornelius braucht einen Tallstrider-Schnabel, um eine Pfeife herzustellen, die den Ruf eines verwundeten Tallstriders nachahmt.",al={"wofür schnabel","pfeifenschnabel"}},{q="Was hat Cornelius mit der Pfeife vor?",a="Cornelius will die Pfeife benutzen, um den großen Löwen herauszulocken.",al={"löwen herauslocken","pfeifenplan"}},{q="Wer könnte wütend werden, wenn sich Gerüchte verbreiten?",a="Cornelius fürchtet, Demar werde wütend, wenn sich Gerüchte über einen menschenfressenden Löwen verbreiten, der unter seiner Aufsicht umherstreift.",al={"wer ist demar","demar wütend"}}},fp="19,158,17.319.0,24.117.0,43.99.0,48.62.0,36.101.0"}
P.entries["quest:95991"] = {n="WANTED: Ghostmaw",s="Wheatley fürchtet, dass ein Phantom-Krokilisk namens Ghostmaw seine preisgekrönten Ponys an den Flüssen reißt. Er wartet auf Burg Farholde, bis ihm jemand den Fang der Bestie bringt.",h="Wheatley fürchtet, dass ein Phantom-Krokilisk namens Ghostmaw seine preisgekrönten Ponys an den Flüssen reißt.",kw={"krokilisk","fang","burg farholde","ghostmaw","lichtungen","ponys","flüsse","wheatley"},sec={{t="Wheatleys Sorge",b="Wheatley lässt seine Pferde wegen Berichten über Ghostmaw an den Flüssen nicht mehr durch die Lichtungen treiben. Der Krokilisk soll dreimal so groß und doppelt so bösartig wie ein gewöhnlicher sein. Bringt Wheatley Ghostmaws Fang, damit er weiß, dass die Reise wieder sicher ist."}},faq={{q="Wer ist Ghostmaw?",a="Ghostmaw ist ein geheimnisvoller Phantom-Krokilisk, von dem an den Flüssen berichtet wird. Er soll viel größer und bösartiger als ein gewöhnlicher Krokilisk sein.",al={"ghostmaw","ghostmaw krokilisk","phantom-krokilisk"}},{q="Warum lässt Wheatley seine Pferde nicht mehr weiterziehen?",a="Wheatley fürchtet, dass Ghostmaw seine preisgekrönten Ponys verschlingt, und bleibt deshalb, wo er ist, bis die Bestie erledigt ist.",al={"warum wheatley aufgehört hat","pferde ziehen nicht weiter","wheatley hat angst"}},{q="Was möchte Wheatley gebracht bekommen?",a="Wheatley bittet um Ghostmaws Fang als Beweis dafür, dass der Krokilisk keine Gefahr mehr für Reisende darstellt.",al={"ghostmaws fang","was wheatley bringen","fang"}},{q="Wohin soll ich Ghostmaws Fang bringen?",a="Bringt Ghostmaws Fang zu Wheatley auf Burg Farholde.",al={"wo ist wheatley","burg farholde","fundort des fangs"}}},fp="16,167,20.269.0,16.130.0,43.106.0,39.96.0,39.53.0"}
P.entries["quest:95992"] = {n="WANTED: Ghostmaw",s="Tan'jani veranstaltet einen Wettkampf um Ghostmaw, einen weißen Krokilisk, der die Flüsse heimsucht. Bringt seinen Fang zu Rog'mar und sichert Euch den Preis.",h="Tan'jani veranstaltet einen Wettkampf um Ghostmaw, einen weißen Krokilisk, der die Flüsse heimsucht.",kw={"krokilisk","fang","ghostmaw","kopfjäger","flüsse","rog'mar","tan'jani"},sec={{t="Wettkampf am Fluss",b="Tan'jani in Rog'mar veranstaltet einen Wettkampf für Euch. Ein weißer Krokilisk namens Ghostmaw heimsucht die Flüsse, und selbst die Kopfjäger haben ihn noch nicht gefangen. Bringt Ghostmaw's Fang zu Tan'jani. Der Gewinner erhält den Preis."}},faq={{q="Wer ist Ghostmaw?",a="Ghostmaw ist ein weißer Krokilisk, der die Flüsse heimsucht.",al={"ghostmaw","weißer krokilisk","ghostmaw-krokilisk"}},{q="Wer will Ghostmaw's Fang?",a="Tan'jani in Rog'mar bittet Euch, Ghostmaw's Fang zu bringen.",al={"tan'janis fang","wer will den fang","fang für wen"}},{q="Was soll ich Tan'jani bringen?",a="Tan'jani möchte Ghostmaw's Fang.",al={"ghostmaw's fang","was soll ich bringen","fang"}},{q="Worum geht es bei dem Wettkampf?",a="Tan'jani sagt, dass der Gewinner des Wettkampfs, Ghostmaw zu fangen, den Preis erhält.",al={"tan'janis wettkampf","der preis","warum ghostmaw fangen"}}},fp="16,136,17.206.0,16.53.0,26.54.0,36.31.0,30.77.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="An Sams Feuer lernen Reisende, zu rasten und die Strapazen des Weges zu überstehen. Dann können sie sich Handwerksberufen und der Arbeit in der Wildnis widmen.",h="An Sams Feuer lernen Reisende, zu rasten und die Strapazen des Weges zu überstehen.",kw={"einfaches lagerfeuer","boosted rest","lagervorrichtung","lagerfertigkeiten","wildniskundiger","sam","the great outdoors","handwerksberuf"},ang={["class:Hunter"]="Als Jäger seid Ihr vielleicht damit vertraut, Euch aus der Natur zu versorgen und an einem offenen Feuer zu rasten. Selbst erfahrene Späher profitieren davon, die Kunst des Lagerlebens zu erlernen.",["profession:Cooking"]="Als Koch schafft Ihr Euch mit dem Erlernen des Lagerbaus eine Grundlage für die Zubereitung von Mahlzeiten unter freiem Himmel."},sec={{t="Lektionen am Feuer",b="Sam heißt rastlose Reisende willkommen, die Azeroth auf der Suche nach Glück, Gefahr und Ruhm durchqueren. Ehrgeiz allein kann einen Neuling weder wärmen noch die Mühen des Weges lindern. An seinem Feuer lernt Ihr, wann Ihr rasten solltet, wie Ihr ein Feuer entfacht und wie Ihr Kraft für die Reise sammelt."},{t="Wildnisfertigkeiten und Handwerk",b="Ein Lagerfeuer spendet Wärme gegen die nächtliche Kälte und bietet Gelegenheit zu erholsamerer Rast. Wer die Wildnis kennt, weiß, dass Ausdauer durch Ruhe zwischen den Reisen entsteht. Sobald Ihr diese Grundlagen erlernt habt, könnt Ihr Euch Handwerksberufen widmen. Handwerker und Sammler können lernen, Lagervorrichtungen herzustellen, die sich für ihre Arbeit im Gelände eignen."}},faq={{q="Wer ist Sam?",a="Sam ist ein erfahrener Wildniskundiger und Reisender, der Neulingen beibringt, in der Wildnis zu bestehen. Er lädt sie ein, an seinem Feuer zu sitzen und praktische Wege zu erlernen, die Strapazen der Reise zu meistern.",al={"wer ist sam","sam lagerfeuerquest","questgeber"}},{q="Wozu dient das Sitzen am Lagerfeuer?",a="Boosted Rest ist die Erholung, die das Rasten an einem richtigen Lagerfeuer in der Wildnis bietet. Seine Wärme und Behaglichkeit helfen müden Reisenden, sich zu erholen und ihre Reise fortzusetzen.",al={"was ist boosted rest","boosted rest verstärkung","am feuer rasten"}},{q="Warum sind Wildnisfertigkeiten für Abenteurer wichtig?",a="Wildnisfertigkeiten helfen Reisenden, den Gefahren und langen Wegstrecken jenseits der Siedlungsmauern standzuhalten. Mit diesen Fertigkeiten können sie sich selbst versorgen, ohne der Erschöpfung zu erliegen.",al={"warum wildnisfertigkeiten lernen","warum in der wildnis gedeihen","überlebensfertigkeiten"}},{q="Was haben Handwerksberufe mit dem Lagern in der Wildnis zu tun?",a="Nachdem Ihr gelernt habt, ein einfaches Lager zu errichten, können Berufslehrer Euch beibringen, Lagervorrichtungen herzustellen, die sich für Eure Arbeit im Gelände eignen.",al={"handwerksberufe und lagern","lagervorrichtungen","berufe danach"}},{q="Was sollte ein Abenteurer nach Abschluss dieser Lektion tun?",a="Nachdem Ihr an Sams Feuer gerastet und die Grundlagen des Lagerlebens erlernt habt, könnt Ihr Berufslehrer aufsuchen. Ein praktisches Handwerk ermöglicht es Euch, Arbeitsstationen im Gelände zu errichten, die zu Eurem Beruf passen.",al={"nächste schritte","was nach great outdoors","nach der lagerfeuerquest"}},{q="Wer kann The Great Outdoors angehen?",a="Jeder Reisende, der in die weite Welt aufbricht, kann diese Lektionen erlernen, unabhängig von Herkunft oder Zugehörigkeit.",al={"kann das jeder machen","wer kann great outdoors annehmen","ist diese quest allgemein"}}},fp="18,117,19.257.0,20.322.0,11.166.0,47.169.0,52.162.0,48.128.0,58.167.0,37.111.0"}
P.entries["quest:95999"] = {n="WANTED: Incinerator Gar'im",s="In Seenhain setzt Magistrat Solomon ein Kopfgeld auf Verbrenner Gar'im aus, dessen Truppen die Stadt bedrohen. Der feindliche Orkkommandant hält Renders Tal mit Schattenzauberern und soll mit dem Schwarzfelsklan auf Burg Steinwacht zusammenarbeiten.",h="In Seenhain setzt Magistrat Solomon ein Kopfgeld auf Verbrenner Gar'im aus, dessen Truppen die Stadt bedrohen.",kw={"schwarzfels","kopfgeld","gar'im","verbrenner","seenhain","renders tal","schattenzauberer","solomon"},ang={["class:Mage"]="Als Magier stellt Ihr Euch Gar'im und seinen Schattenzauberern, die eine verderbte Form von offensiver Arkanmagie und Shadow Magic wirken. Antwortet ihnen rasch mit Gegenzaubern.",["faction:Alliance"]="Als Kämpfer der Allianz schützt Ihr Seenhains verwundbare Bürger vor dem Anführer eines orkischen Einfalls und seinen gefährlichen Schattenzauberern, wenn Ihr Verbrenner Gar'im besiegt."},sec={{t="Ein Feuer in Renders Tal",b="Schwarzfelsorcs rücken aus ihren Gebirgsfestungen vor und machen das Rotkammgebirge gefährlicher. In Renders Tal führt Gar'im mit treuen Schattenzauberern und dunkler Magie einen Einfall an. Seenhains Wache ist überlastet, und die Armeen der Krone sind weitgehend abwesend. Deshalb ruft Magistrat Solomon unabhängige Kämpfer dazu auf, Gar'im auszuschalten, der mit den Schwarzfelsorcs auf Burg Steinwacht zusammenarbeiten soll."},{t="Beweise des Ablebens",b="Gar'im ist für zerstörerische Magie und seinen Befehl über schattenwebende Zauberer bekannt. Um die Belohnung der Stadt zu erhalten, dringen Jäger in feindlich besetztes Gebiet ein und besiegen ihn. Sie müssen seinen zertrümmerten Stab zum Rathaus von Seenhain zurückbringen, als Beweis dafür, dass die Bedrohung beendet ist."}},faq={{q="Wer ist Verbrenner Gar'im?",a="Verbrenner Gar'im ist ein orkischer Kriegsherr und Zauberwirker, der einen Einfall in Renders Tal anführt. Er soll mit den Schwarzfelsorcs von Burg Steinwacht zusammenarbeiten und befehligt gefährliche Schattenzauberer.",al={"wer ist gar'im","garim","verbrenner garim"}},{q="Wo ist Verbrenner Gar'im zu finden?",a="Gar'im lagert unter feindlichen Orktruppen in Renders Tal im südöstlichen Rotkammgebirge.",al={"gar'im fundort","wo ist garim","renders tal lage"}},{q="Wer hat das Kopfgeld auf Gar'im ausgesetzt?",a="Magistrat Solomon setzt das Kopfgeld im Namen Seenhains aus, um die orkischen Vorstöße gegen die umkämpfte Stadt einzudämmen.",al={"wer hat das kopfgeld ausgesetzt","solomon kopfgeld"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Magistrat Solomon verlangt den Zerbrochenen Stab von Verbrenner Gar'im als Beweis für den Tod des Zauberwirkers, bevor er die Belohnung auszahlt.",al={"garim beweis","zerbrochener stab questgegenstand"}},{q="Welche Bedrohung geht von Gar'im und seinen Anhängern aus?",a="Gar'im wirkt tödliche zerstörerische Magie und wird von Schattenzauberern flankiert. Gemeinsam festigen sie die Kontrolle des Schwarzfelsklans im Rotkammgebirge und drohen Seenhain zu überrennen, wenn ihnen niemand Einhalt gebietet.",al={"gar'im fähigkeiten","schattenzauberer rotkammgebirge"}},{q="Warum verlässt sich Seenhain auf Kopfgelder statt auf die Armee von Sturmwind?",a="Angesichts politischer Zwistigkeiten und Truppenmangels hat Sturmwind das Rotkammgebirge bei seiner Verteidigung weitgehend sich selbst überlassen. Magistrat Solomon musste bereitwillige Kämpfer anheuern, um feindliche Anführer zu töten.",al={"warum kopfgelder seenhain","wo ist die armee von sturmwind"}}},fp="26,235,25.404.0,15.259.0,26.193.0,38.97.0,33.128.0,43.128.0,45.190.0,68.170.0"}
P.entries["quest:96"] = {n="Ruf des Wassers",s="Ihr bringt Islen Wasserdeuter den Wassersplitter an die Küste des Brachlands. Diese Rückkehr zeigt Euren Einklang mit wiederherstellenden Energien und bringt Euch ein Wassertotem ein.",h="Ihr bringt Islen Wasserdeuter den Wassersplitter an die Küste des Brachlands.",kw={"ruf des wassers","islen wasserdeuter","schwache wassermanifestation","wassersplitter","silberwald","brachland","wassertotem"},ang={["class:Shaman"]="Als Schamane erhaltet Ihr Euer Wassertotem und gewinnt Zugang zu wiederherstellenden Quellen und reinigenden Brunnen, die für Eure Rolle als spiritueller Heiler entscheidend sind.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr Mitverantwortung für die Geister des Landes. Junge Schamanen werden dazu aufgerufen, verseuchte Gebiete in Kalimdor und den Östlichen Königreichen zu reinigen."},sec={{t="Ein langer Heimweg",b="Ihr tragt ein Geschenk der Schwachen Wassermanifestation über das Meer zurück. Um es zu verdienen, habt Ihr Kontinente überquert und seid an den verseuchten Ufern des Silberwalds der Verderbnis entgegengetreten. Wasser spendet Leben, passt sich an und heilt, doch seine nachgiebige Natur macht es anfällig für Verseuchung und dunkle Magie.\n\nVor der Schwachen Wassermanifestation habt Ihr reinen elementaren Willen erlebt und den Wassersplitter erhalten. Nun kehrt Ihr ins sonnenverbrannte Brachland zurück, wo Euch der Splitter daran erinnert, dass Wasser ferne Winkel der Welt verbindet."},{t="Das Wassertotem",b="Wenn Ihr Islen Wasserdeuter den Splitter übergebt, beurteilt sie mehr als den Beweis Eurer Reise. Sie prüft, ob Ihr das Gleichgewicht zwischen Bewahrung und Erneuerung erlernt habt. Die sich ausbreitende Fäulnis Lordaerons kann kleine Siege verbergen, doch selbst die Reinigung einer einzigen Quelle bedeutet den Geistern viel. Islen nimmt Eure Gabe an und gibt Euch ein Wassertotem. Durch dieses könnt Ihr reinigende, heilende und manawiederherstellende Ströme in die Welt der Sterblichen leiten, was Euch an die Gezeiten bindet."}},faq={{q="Was ist der Wassersplitter?",a="Der Wassersplitter ist ein elementares Überbleibsel, das Euch die Schwache Wassermanifestation überreicht hat. Er zeigt, dass Ihr die lebensspendende Kraft des Wassers versteht und Euch der Verderbnis entgegengestellt habt, die elementare Ströme bedroht.",al={"wassersplitter","was ist der splitter"}},{q="Wohin bringe ich den Wassersplitter?",a="Bringt den Wassersplitter zu Islen Wasserdeuter in ihrem abgelegenen Lager an der Ostküste des Brachlands, südlich von Ratschet.",al={"wo abgeben","wer bekommt den splitter","abgabeort"}},{q="Was erhalte ich für den Abschluss dieser Prüfung?",a="Ihr erhaltet ein Wassertotem, einen Fokus, den Schamanen benötigen, um elementare Wassertotems für Heilung und wiederherstellende Magie zu rufen.",al={"questbelohnung","totembelohnung","was bekomme ich"}},{q="Warum fand die Prüfung im Silberwald statt?",a="Die Gewässer des Silberwalds sind durch Seuche und Shadow Magic stark verdorben. Dort habt Ihr die Verletzlichkeit des Wassers erlebt und seine natürliche Reinheit gegen den Verfall verteidigt.",al={"warum silberwald","warum östliche königreiche","wasser im silberwald"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Taurenschamanin an der Ostküste des Brachlands. Sie leitet die schamanischen Wasserprüfungen und lehrt Initiaten, mit fließenden Geistern Zwiesprache zu halten und wiederherstellende Künste zu meistern.",al={"islen","wer ist islen wasserdeuter"}}},fx={["352084e3"]={q="Warum schickt Euch die Schwache Wassermanifestation zurück zu Islen?",a="Die elementare Manifestation dient als lebendige Stimme des reinen Wassers, geprüft und beschworen durch Eure Rituale. Indem sie Euch den Wassersplitter gewährt, vertraut sie Euch die grundlegende Wahrheit ihres Wesens an: Wasser bringt Leben, während Verderbnis es auslöscht. Sie schickt Euch zurück zu Islen Wasserdeuter, damit der Schamane Eure Verbindung mit den Geistern bestätigen, Euren Erfolg bei der Konfrontation mit der Verderbnis anerkennen und Euch das Wassertotem gewähren kann, das zu führen Ihr Euch als würdig erwiesen habt.",al={"motiv der wassermanifestation","warum den splitter zu islen bringen","warum will die wassermanifestation das"}}},fp="13,155,19.504.0,15.455.0,27.198.0,35.113.0,44.121.0,43.166.0,23.188.0"}
P.entries["quest:960"] = {n="Onu meditiert",s="An der Meistergleve im Süden der Dunkelküste fällt Onu in tiefe Trance, während eine Bedrohung wächst. Der Uralte der Lehren sinnt über das Bündnis und die Beweggründe des Schattenhammerkults und der Naga nach. Falls Ihr Eure Wahrsagephiole verliert, sprecht mit ihm, um eine neue zu erhalten.",h="An der Meistergleve im Süden der Dunkelküste fällt Onu in tiefe Trance, während eine Bedrohung wächst.",kw={"dunkelküste","der hain der uralten","die meistergleve","meditieren","onu","wahrsagephiole","wahrsageschale","schattenhammer"},ang={["class:Druid"]="Als Druide teilt Ihr eine tiefe Verbundenheit mit der Natur und den Uralten der Lehren. Wahrsagerituale spiegeln die Art wider, wie der Zirkel des Cenarius verdorbenes Land aus der Ferne erkundet.",["faction:Alliance"]="Als Reisender der Allianz ist es für Euch auf dem Weg zwischen Teldrassil und dem Eschental wichtig, die Dunkelküste vor Kultisten und Eindringlingen aus dem Wasser zu sichern.",["race:NightElf"]="Als Nachtelf verehrt Ihr Uralte der Lehren wie Onu, die das Gleichgewicht Kalimdors hüten. Ihre zeitlose Weisheit hilft Euch, Störungen in der Wildnis der Dunkelküste zu verstehen."},sec={{t="Ein Geist in tiefer Betrachtung",b="Im Hain der Uralten bewahrt Onu die Geschichte Kalimdors in seinem uralten Gedächtnis. Unheilvolle Berichte über finstere Ausgrabungen an der Meistergleve lenken sein gewaltiges Bewusstsein nach innen. Er sinnt darüber nach, was die fanatischen Kultisten des Schattenhammers und die Naga zu den versteinerten Überresten eines uralten Ungetüms führt. Während Ihr seine Erkundung durchführt, bleibt Onu erreichbar und kann eine in der Wildnis verlorene Wahrsagephiole ersetzen."},{t="Ein Blick in die Tiefe",b="Onu nutzt naturverbundene Weissagung, um die Ruinen zu beobachten, ohne sich körperlich dorthin zu wagen. Er vertraut Euch eine Wahrsagephiole an, die an der Ausgrabungsstätte eine Wahrsageschale herbeiruft und ihm ermöglicht, aus der Ferne mit Euch zu kommunizieren. Die Reise nach Süden durch die Dunkelküste ist wegen feindseliger Wildtiere und Kultistenpatrouillen gefährlich, sodass Missgeschicke geschehen können.\n\nOnus Trance ist eine aufmerksame Wache, kein ununterbrochener Schlaf. Er bietet bereitwillig eine weitere Phiole mit heiligem Wasser an, damit Ihr die Untersuchung der Meistergleve fortsetzen könnt."}},faq={{q="Warum meditiert Onu?",a="Onu meditiert über die beunruhigende Anwesenheit des Schattenhammerkults und der Naga an der Meistergleve. Er versucht, ihre Beweggründe zu ergründen und Euch bei der Untersuchung des Ortes anzuleiten.",al={"warum meditiert onu","onu trance","was macht onu"}},{q="Welchen Zweck hat diese Interaktion?",a="Diese Interaktion ist eine Absicherung für Abenteurer an der Meistergleve. Falls Ihr Eure Wahrsagephiole verliert, erhaltet Ihr im Gespräch mit Onu Ersatz, damit Ihr das Ritual abschließen könnt.",al={"wahrsagephiole verloren","neue phiole erhalten","onu ersatzquest"}},{q="Wo befindet sich Onu?",a="Onu ist im Hain der Uralten im mittleren Süden der Dunkelküste verwurzelt, gleich neben der Hauptstraße.",al={"onu standort","wo ist onu zu finden"}},{q="Was mache ich mit der Wahrsagephiole?",a="Bringt die Phiole zur Meistergleve und benutzt sie, um eine Wahrsageschale zu erschaffen. Onu kann dann durch die Schale mit Euch sprechen.",al={"wie wird die wahrsagephiole benutzt","wahrsageschale dunkelküste","wahrsagephiole zweck"}},{q="Was ist die Meistergleve?",a="Die Meistergleve ist eine uralte Ausgrabungsstätte im Süden der Dunkelküste. Dort liegt der gewaltige versteinerte Schädel eines vergessenen Wesens, durchbohrt von einer gigantischen Klinge. Kultisten und Naga haben sich dort zu unbekannten, finsteren Zwecken versammelt.",al={"was ist die meistergleve","monument im süden der dunkelküste"}},{q="Können Spieler der Horde hier mit Onu interagieren?",a="Onu ist ausschließlich mit den Nachtelfen und der Allianz verbündet. Abenteurer der Horde werden nahe dem Hain der Uralten feststellen, dass er und seine Beschützer feindselig oder wenig hilfsbereit sind.",al={"ist onu nur für die allianz","horde onu meditiert"}}},fx={["72a6a09e"]={q="Warum braucht Onu Eure Hilfe, anstatt selbst zu ermitteln?",a="Onu bleibt im Grove of the Ancients, um über den Schattenhammer und die Naga zu meditieren. Er verlässt sich auf Reisende, um den The Master's Glaive zu untersuchen und ihn durch eine Schale des Schauens zu kontaktieren.",al={"warum mich schicken","warum geht onu nicht selbst","warum braucht onu euch"}}},fp="17,243,28.421.0,18.499.0,22.187.0,40.184.0,21.97.0,39.127.0,28.238.0,41.169.0"}
P.entries["quest:96009"] = {n="High Stakes",s="Bertrand Ironbrow braucht Holzbündel aus Turner's Logging Camp für die Burg Farholde. Das Holz soll helfen, das Tor fertigzustellen, während die Orcs immer aufsässiger werden.",h="Bertrand Ironbrow braucht Holzbündel aus Turner's Logging Camp für die Burg Farholde.",kw={"bertrand ironbrow","burg farholde","tor","hoher einsatz","bauholz","murlocs","turner's logging camp","holzbündel"},sec={{t="Holz für die Burg",b="Bertrand Ironbrow braucht Bauholz für die Burg Farholde, wo die Leute mitten in einem Kriegsgebiet voller Orcs und Kultisten bauen. Ihr sollt Bündel aus Turner's Logging Camp holen, da gefährliche Wege die Lieferungen verzögert haben. Das Tor der Burg wird noch gebaut, und die Orcs werden immer aufsässiger."}},faq={{q="Wer braucht das Holz?",a="Bertrand Ironbrow braucht das Holz auf Burg Farholde.",al={"wer braucht holz","bertrand bauholz","für wen sind holzbündel"}},{q="Woher kommen die Bündel?",a="Die Bündel kommen aus Turner's Logging Camp, nordwestlich der Burg Farholde.",al={"wo ist das bauholz","holz aus turner's logging camp","holzlager"}},{q="Warum kommt das Bauholz zu spät?",a="Gefährliche Wege haben die Bauholzlieferungen aus dem Sägewerk im Nordwesten verzögert.",al={"warum verzögerte lieferungen","gefährliche wege","bauholz verspätung"}},{q="Wofür ist das Holz bestimmt?",a="Das Holz ist für Burg Farholde bestimmt und könnte helfen, das Tor fertigzustellen.",al={"warum wird holz gebraucht","bauholz fürs tor","burg im bau"}},{q="Was macht die Wege gefährlich?",a="Auf dem Weg von der Burg zum Sägewerk lauern Krokiliske und Murlocs.",al={"krokiliske und murlocs","was lauert am weg","gefahr auf dem weg"}}},fp="11,161,17.306.0,19.50.0,31.72.0,27.80.0,21.65.0,31.67.0"}
P.entries["quest:96010"] = {n="Fragments of the Pylons",s="Mordent Evenshade bittet Euch, Pylonfragmente aus den Dörfern der Magram und Gelkis in Shen'dralas zu bergen. Er braucht die Stücke für seine Arbeit an den beschädigten Pylonen.",h="Mordent Evenshade bittet Euch, Pylonfragmente aus den Dörfern der Magram und Gelkis in Shen'dralas zu bergen.",kw={"zentaur","kristalle","fragmente der pylonen","gelkis","magram","mana","mordent evenshade","pylon","splitter","shen'dralas"},sec={{t="Zerbrochene Pylonen",b="Mordent Evenshade glaubt, dass die Überfälle der Zentauren beide Pylonen in Shen'dralas beschädigt haben. Er vermutet, dass die Magram und Gelkis die verstreuten Splitter als Trophäen in ihre Dörfer gebracht haben. Ihr sollt die dort bewachten Fragmente bergen und zu ihm bringen."},{t="Die Kristalle",b="Mordent nimmt die Fragmente entgegen und sagt, die Kristalle seien stärker zerbrochen, als er erwartet hatte. Vorerst behält er sie. Euer nächster Schritt ist es, formbares Mana zu sammeln, das die Stücke verbinden und Leylinienenergie durch sie fließen lassen kann."}},faq={{q="Wer bittet um die Pylonfragmente?",a="Mordent Evenshade bittet Euch, Splitter und Fragmente aus den Dörfern der Magram und Gelkis zu bergen und zu ihm zurückzubringen.",al={"wer ist mordent","mordent evenshade","wer will die kristalle"}},{q="Wo befinden sich die Pylonfragmente?",a="Mordent glaubt, dass die Magram und Gelkis die Pylonfragmente in ihre Dörfer in Shen'dralas gebracht haben.",al={"wo sind die splitter","fundort der pylonstücke","fragmente finden"}},{q="Warum sind die Pylonen beschädigt?",a="Mordent glaubt, dass das rücksichtslose Treiben der Zentauren beide Pylonen beschädigt hat.",al={"was hat die pylonen zerbrochen","schäden durch zentauren","warum ist der pylon zerbrochen"}},{q="Was hat Mordent mit den Fragmenten vor?",a="Mordent will die zerbrochenen Stücke mit formbarem Mana verbinden und dieses Mana als Leiter für die Leylinien nutzen.",al={"wofür sind die kristalle","wie lassen sich pylonen reparieren","mordents plan"}}},fp="23,163,13.254.0,12.222.1,33.118.0,30.97.0,27.63.0,48.106.0"}
P.entries["quest:96018"] = {n="Powering the Pylons",s="Mordent Evenshade bittet Euch, die beschädigten Pylonen in Shen'dralas wiederherzustellen. Dort ist schwebendes Mana aufgetaucht, das er gesammelt und zu den Pylonen zurückgebracht haben muss.",h="Mordent Evenshade bittet Euch, die beschädigten Pylonen in Shen'dralas wiederherzustellen.",kw={"ancient mana crystals","schwebendes mana","mana sieve","mordent evenshade","pylonen","shen'dralas"},sec={{t="Mana sammeln",b="Im Tempel von Shen'dralas sucht Ihr nach dem Mana Sieve, einem Artefakt, dessen Ausleihe den Bewohnern missfallen könnte. Mordent Evenshade muss das verstreute Mana in halbkristallisierter Form sammeln lassen. Mit genügend Ancient Mana Crystals könnt Ihr die beschädigten Pylonen mit Energie versorgen und ihm die Arbeit des Siebs zurückbringen."},{t="Die Pylonen",b="Mordent Evenshade sieht, dass die Pylonen wiederhergestellt sind, und deutet zum Himmel. Als er sich wieder Euch zuwendet, bemerkt er Eure verhaltene Reaktion."}},faq={{q="Warum braucht Mordent Mana?",a="Mordent braucht gesammeltes Mana in Form von Ancient Mana Crystals, um die beschädigten Pylonen in Shen'dralas mit Energie zu versorgen.",al={"warum mana","mordent mana"}},{q="Wo finde ich das Mana Sieve?",a="Das Mana Sieve befindet sich im Tempel von Shen'dralas.",al={"mana sieve fundort","wo ist das mana sieve"}},{q="Was geschieht mit dem Mana in Shen'dralas?",a="Um Shen'dralas sind schwebende Man funken aufgetaucht, vermutlich weil die Pylonen beschädigt wurden.",al={"schwebendes mana","mana kugeln"}},{q="Was bewirkt das Mana Sieve?",a="Mit dem Mana Sieve sammelt Ihr schwebendes Mana als Ancient Mana Crystals.",al={"zweck des mana sieve","mana sammeln"}},{q="Wer bittet darum, die Pylonen mit Energie zu versorgen?",a="Mordent Evenshade bittet Euch, Mana zu sammeln und die Pylonen mit Energie zu versorgen.",al={"wer ist mordent","mordent evenshade"}}},fp="19,159,14.294.0,10.129.1,27.98.0,31.51.0,45.105.0,28.72.0,45.65.0"}
P.entries["quest:96026"] = {n="Step Two: More Rock",s="Hamur in Bolder'ok möchte Heavy Weightstones, um eine Waffe zu stärken. Er sagt, Stein mache Stein stärker, und bittet Euch, mehr zu bringen.",h="Hamur in Bolder'ok möchte Heavy Weightstones, um eine Waffe zu stärken.",kw={"bolder'ok","hamur","heavy weightstones","mehr stein","stein","waffe","weightstones"},sec={{t="Hamurs Bitte",b="Hamur in Bolder'ok sagt, einer Waffe fehle noch der letzte Schliff: mehr Stein. Er hat kleine Leute Heavy Weightstones herstellen sehen und bittet Euch, sie zu bringen, damit er die Waffe stärken kann."}},faq={{q="Wer möchte die Heavy Weightstones?",a="Hamur in Bolder'ok bittet Euch, Heavy Weightstones zu bringen.",al={"wer braucht heavy weightstones","hamurs bitte"}},{q="Wofür möchte Hamur sie verwenden?",a="Hamur sagt, er werde die Heavy Weightstones verwenden, um eine Waffe zu stärken.",al={"warum heavy weightstones","wofür sind sie"}},{q="Was macht laut Hamur Stein stärker?",a="Hamur sagt, nur Stein könne Stein stärker machen.",al={"wie wird stein stärker","mehr stein"}}},fp="19,129,15.176.0,33.56.0,30.69.0,40.49.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="In einem Lager in der Wildnis nutzen Lederverarbeiter gegerbte Bälge und fertigen ihren eigenen Unterschlupf. Ein guter Lagerplatz braucht ein aufgeschlagenes Zelt und ein Feuer, dessen Entzünden Kochkunstlehrer vermitteln.",h="In einem Lager in der Wildnis nutzen Lederverarbeiter gegerbte Bälge und fertigen ihren eigenen Unterschlupf.",kw={"lagerzelt","lagerfeuer","zelten","kochkunst","lederverarbeitung","unterschlupf","zelt","wildnis"},ang={["profession:Cooking"]="Ein Lagerfeuer ist das Herz eines Lagerplatzes in der Wildnis. Die Grundlagen der Kochkunst lehren Euch, eine Flamme zu entzünden und ein Lager in der Wildnis zu unterhalten."},sec={{t="Unterschlupf in der Wildnis",b="Für Handwerker, die mit Bälgen und Leder arbeiten, ist die Herstellung eines eigenen Unterschlupfs ein wesentlicher Meilenstein. Ein stabiles Lederzelt schützt Reisende auf offenem Gelände vor rauem Wetter, Wind und der Kälte der Nacht. Stadtbewohner sehen Zelte auf belebten Straßen oder Marktplätzen ungern, also müsst Ihr durch die Stadttore hinaus in die Wildnis ziehen, um ein Lager aufzuschlagen."},{t="Die Wärme eines Lagerfeuers",b="Ein aufgeschlagenes Zelt ist nur ein halbes Lager. Ein ordentliches Feuer hält Dunkelheit und kalte Winde fern und bietet Euch eine Feuerstelle in gefährlichen Landen. Da das Kochen im Freien mit dem Entfachen und Unterhalten eines Feuers beginnt, sucht Unterweisung bei Meistern der Kochkunst und Kochkunstlehrern. Sie lehren Euch, ein Lagerfeuer zu entzünden, bevor Ihr ein Lager errichtet."}},faq={{q="Wo könnt Ihr ein Lagerzelt aufschlagen?",a="Stadtbewohner sehen Zelte auf Straßen oder Stadtplätzen ungern, also bringt Euer Zelt durch die Stadttore hinaus in die Wildnis.",al={"lagerzelt verwenden","wo zelt aufschlagen","zelten in der stadt erlaubt"}},{q="Was braucht Ihr außer einem Zelt, um ein Lager aufzuschlagen?",a="Ein Zelt allein ist noch kein vollständiges Lager. Daneben muss auch ein Lagerfeuer brennen.",al={"feuer fürs lager nötig","voraussetzungen fürs lager","wie ein lager aufschlagen"}},{q="Wo lernen Abenteurer, ein Lagerfeuer zu entfachen?",a="Meister der Kochkunst und Kochkunstlehrer lehren Euch im Rahmen der Speisenzubereitung, ein Lagerfeuer zu entzünden. Sucht einen Kochkunstlehrer auf, um die Grundlagen zu erlernen.",al={"lagerfeuer erlernen","wer lehrt lagerfeuer","kochfeuer"}},{q="Wie hängt Lederverarbeitung mit der Herstellung von Lagerzelten zusammen?",a="Lederverarbeiter verbinden gegerbte Bälge und Felle mit festen Nähten zu Zeltplanen, die den rauen Bedingungen der Wildnis standhalten. Dieses Handwerk verschafft Wanderern einen verlässlichen Unterschlupf aus Tierhäuten.",al={"camping 101 leatherworking","lagerzelt aus leder","zeltherstellung lederverarbeitung"}},{q="Warum errichten Abenteurer Lager in der Wildnis?",a="Lager in der Wildnis bieten Reisenden einen sicheren Zufluchtsort zum Ausruhen und Erholen, wenn sie fern von bewohnten Außenposten, Gasthäusern und Siedlungen sind. Ein tragbarer Unterschlupf und ein warmes Feuer helfen gegen die Unbilden der Natur und die Gefahren des Geländes.",al={"warum draußen lagern","zweck des zeltens","überleben in der wildnis lager"}},{q="Warum lehnen Stadtbewohner das Aufstellen von Zelten innerhalb der Stadt ab?",a="Stadtbewohner lehnen Zelte auf öffentlichen Straßen ab, weil sie Verkehrswege versperren und für Unruhe sorgen. Siedlungen haben Gasthäuser und private Unterkünfte für Reisende, daher erwarten die Einheimischen, dass Lager in der Wildnis bleiben.",al={"regeln fürs zelten in der stadt","keine zelte in der stadt","warum kein zelt in der stadt aufschlagen"}}},fp="27,193,28.361.0,24.324.0,32.125.0,53.76.0,47.139.0,54.205.0,53.213.0,56.202.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Schmiede, die in die Wildnis aufbrechen, werden nach Kharanos geschickt, um von Tognus Flintfire zu lernen. Er lehrt sie, einen tragbaren Schleifstein herzustellen, mit dem sie Waffen im Lager scharf halten können.",h="Schmiede, die in die Wildnis aufbrechen, werden nach Kharanos geschickt, um von Tognus Flintfire zu lernen.",kw={"schmiedekunst","klingen","lager","camping 101","dun morogh","kharanos","schleifstein","tognus flintfire","waffen"},ang={["class:Rogue"]="Ein scharfer Dolch ist für Euer Handwerk unerlässlich, daher ist ein Schleifstein im Lager zwischen Aufträgen in der Wildnis willkommen.",["class:Warrior"]="Scharfe Waffen sind im Kampf wichtig, und ein Schleifstein im Lager hilft Euch, sie auf einer Expedition scharf zu halten.",["profession:Blacksmithing"]="Ihr könnt lernen, Werkzeuge für unterwegs wie den Schleifstein herzustellen, und Euer Handwerk fern der Stadtschmieden einsetzen, um Verbündeten in der Wildnis zu helfen.",["race:Dwarf"]="Als Zwerg findet Ihr Kharanos in den verschneiten Ausläufern der Berge von Dun Morogh. Seine Schmiede halten kalten Stahl für die Reise scharf."},sec={{t="Waffenpflege auf Reisen",b="Ihr werdet nach Kharanos geschickt, um zu lernen, wie ein Schmied fern einer Stadtschmiede helfen kann. Dort verwandeln geschickte Hände rohes Metall in Werkzeuge fürs Lager. Eine scharf gehaltene Klinge ist für den langen Weg bereit."},{t="Der Meister von Kharanos",b="In Kharanos lehrt Tognus Flintfire fähige Schmiede, einen Schleifstein herzustellen. Stellt einen neben Eurem Lagerplatz auf, damit Krieger und Schurken vor dem nächsten Marsch Scharten aus ihren Waffen schleifen und stumpfe Schneiden schärfen können."}},faq={{q="Wer ist Tognus Flintfire?",a="Tognus Flintfire lehrt Schmiedekunst in Kharanos, in Dun Morogh. Er bildet Schmiede aus, die ihr handwerkliches Können bewiesen haben, und lehrt sie, Ausrüstung für Lagerplätze herzustellen.",al={"wer ist tognus flintfire","wo ist tognus","tognus flintfire standort"}},{q="Was ist ein Schleifstein?",a="Ein Schleifstein ist ein tragbares Werkzeug, das von Schmieden hergestellt wird. Im Lager bietet er Kriegern, Schurken und anderen Waffenträgern eine Möglichkeit, ihre Klingen unterwegs zu schärfen.",al={"was bewirkt der schleifstein","schleifstein lager","schleifstein zweck"}},{q="Warum ist der Schleifstein für Krieger und Schurken wichtig?",a="Krieger und Schurken sind im Kampf auf scharfe Waffen angewiesen. Mit einem Schleifstein können sie ihre Klingen, Äxte und Dolche pflegen, während sie fern der Stadtschmieden unterwegs sind.",al={"wer braucht einen schleifstein","krieger schleifstein","schurken schleifstein"}},{q="Wo liegt Kharanos?",a="Kharanos liegt südwestlich von Eisenschmiede in den verschneiten Gipfeln von Dun Morogh. Reisende, Bergleute und Handwerker nutzen die Siedlung als Rastplatz, wenn sie die Gebirgspässe überqueren.",al={"wo liegt kharanos","kharanos lage","kharanos finden"}},{q="Was ist erforderlich, um die Herstellung dieses Lagergegenstands zu erlernen?",a="Beweist grundlegendes Geschick am Amboss, und Tognus Flintfire lehrt Euch, Ausrüstung für Lagerplätze herzustellen. Dann könnt Ihr lernen, den tragbaren Schleifstein zu schmieden.",al={"camping 101 blacksmithing voraussetzung","wann ist schleifstein erlernbar","schmiedekunst lagerausbildung"}},{q="Warum stellen Schmiede Lagergegenstände her?",a="Schmiede fertigen Lagerwerkzeuge, um Abenteurergruppen fern der Ortschaften zu unterstützen. Mit einem tragbaren Schleifstein können Gefährten ihre Waffen unter freiem Himmel pflegen, ohne zu einer Stadtschmiede zurückzukehren.",al={"warum lagergegenstände herstellen","schmiedekunst lagergegenstände","nutzen der schmiedekunst in der wildnis"}}},fp="26,170,35.181.0,22.211.0,24.162.0,27.161.0,59.157.0,18.177.0,44.137.0,39.202.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="In Eisenschmiede zeigt Vosur Brakthel Alchemisten, wie sie sich auf Reisen vorbereiten. Mit einem Manabrunnen können sie Zauberkundigen und Heilern unterwegs einen Ort zur Erholung bieten.",h="In Eisenschmiede zeigt Vosur Brakthel Alchemisten, wie sie sich auf Reisen vorbereiten.",kw={"alchemie","lagerfeuer","lagern","camping 101: alchemy","eisenschmiede","manabrunnen","vosur brakthel"},ang={["faction:Alliance"]="In Eisenschmiede können Alchemisten bei Vosur Brakthel Rat suchen, um erholsame Mixturen für ihre Reisen zuzubereiten.",["profession:Cooking"]="Ein Lagerplatz braucht ein Lagerfeuer, und Kochkunstlehrer in allen Reichen vermitteln die praktische Fertigkeit, eines zu entfachen."},sec={{t="Brauen für die Reise",b="Vosur Brakthel lehrt Alchemisten in Eisenschmiede, ihr Handwerk auch jenseits der Stadt auszuüben. Phiolen in einem ruhigen Labor zu brauen, ist nur ein Teil der Arbeit. In Azeroths Wildnis können Alchemisten mit ihrem Wissen einen Manabrunnen für ein Lager erschaffen, der Gefährten hilft, die Reise durchzustehen."},{t="Lager in der Wildnis",b="Ein Manabrunnen kann Heiler und Zauberkundige erfrischen, doch er gehört in ein Lager in der Wildnis, nicht auf eine Straße in Eisenschmiede. Stadtbewohner sehen es ungern, wenn innerhalb ihrer Mauern Zelte aufgeschlagen werden. Ein richtiges Lager braucht auch ein Feuer, also sucht Rat bei einem Kochkunstlehrer, bevor Ihr in die Wildnis aufbrecht."}},faq={{q="Wer ist Vosur Brakthel?",a="Vosur Brakthel ist ein Alchemielehrer in Eisenschmiede. Er lehrt Alchemisten, mit ihrem Handwerk einen Manabrunnen für Gefährten im Feld zu erschaffen.",al={"wer lehrt camping 101: alchemy","vosur brakthels aufgabe","wer ist vosur brakthel"}},{q="Was ist ein Manabrunnen?",a="Ein Manabrunnen ist eine alchemistische Einrichtung für ein Lager in der Wildnis. Er hilft Zauberkundigen und Heilern, sich unterwegs zu erholen.",al={"was bewirkt ein manabrunnen","zweck des manabrunnens","warum einen manabrunnen erschaffen"}},{q="Könnt Ihr innerhalb von Eisenschmiede ein Lager aufschlagen?",a="Nein. Stadtbewohner sehen Lager in Eisenschmiedes Straßen ungern, also bringt Euren Manabrunnen aus der Stadt hinaus in die Wildnis.",al={"lagern in eisenschmiede erlaubt","lagern in der stadt","wo manabrunnen aufstellen"}},{q="Was braucht Ihr noch, um ein Lager aufzuschlagen?",a="Ein Lager braucht auch ein Lagerfeuer. Wenn Ihr nicht wisst, wie Ihr eines entfacht, sucht vor dem Aufbruch einen Kochkunstlehrer auf.",al={"lagerfeuer als voraussetzung","kochkunst zum lagern nötig","wie ein lager aufschlagen"}},{q="Wann kann ein Alchemist lernen, einen Manabrunnen zu erschaffen?",a="Vosur Brakthel unterrichtet Alchemisten, die den Beruf ergriffen und bereits etwas Fertigkeit darin bewiesen haben. Mit dieser Erfahrung können sie lernen, einen Manabrunnen zu erschaffen.",al={"wann manabrunnen erlernen","voraussetzungen für manabrunnen","voraussetzungen für camping 101"}},{q="Wer profitiert am meisten von einem Manabrunnen im Lager?",a="Zauberkundige und Heiler profitieren am meisten von einem Manabrunnen. Er hilft ihnen, ihr Mana aufzufüllen, wenn sie fern von städtischen Gasthäusern und Ruhesteinen unterwegs sind.",al={"wer profitiert vom manabrunnen","klassen für manabrunnen","wer nutzt manabrunnen"}}},fp="20,167,20.280.0,20.267.0,22.140.0,20.117.0,39.118.0,37.108.0,48.152.0,43.146.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Fern der bewachten Straßen lernen Bergleute, einen Lodestein für ein Lager in der Wildnis herzustellen. Dazu braucht es Wissen über Gestein und die Feuerkunst, die das Leben im Freien erfordert.",h="Fern der bewachten Straßen lernen Bergleute, einen Lodestein für ein Lager in der Wildnis herzustellen.",kw={"lagerfeuer","camping","camping 101: mining","lagerplatz","kochkunst","magnetstein","bergbau","wildnis"},ang={["profession:Cooking"]="Als Koch lernt Ihr bei Kochlehrern die Feuerkunst, die ein Lager braucht.",["profession:Mining"]="Als Bergmann lernt Ihr, Erde und Erz zu einem Lodestein zu formen, der einem Lager in der Wildnis Halt gibt."},sec={{t="Feldfertigkeiten für Bergleute",b="Fern der bewachten Straßen muss ein Bergmann sich auf sein Wissen über das Leben im Freien verlassen. Mineralienkenntnis ermöglicht es Euch, einen Lodestein zu formen, der einem Lager in der Wildnis Halt gibt."},{t="Regeln der Wildnis",b="Ein Lager gehört außerhalb der Stadtgrenzen, wo Reisende ihre Unterkünfte aufschlagen können, ohne die Bewohner zu stören. Wählt einen Platz in der offenen Wildnis. Ein Lager braucht auch ein Feuer, das die nächtliche Kälte vertreibt. Zu lernen, wie man eines entfacht, gehört ebenso zum Wissen über das Leben im Freien wie die Arbeit mit Gestein."}},faq={{q="Wozu wird ein Magnetstein verwendet?",a="Ein Lodestein gibt einem Lager in der Wildnis Halt.",al={"verwendungszweck des magnetsteins","wozu dient ein magnetstein","warum magnetstein herstellen"}},{q="Kann ich in einer Ortschaft oder Stadt ein Lager aufschlagen?",a="Die Stadtbewohner und die Behörden missbilligen Zelte auf öffentlichen Plätzen und Straßen. Schlagt Euer Lager außerhalb der Stadtgrenzen auf.",al={"kann ich in einer stadt zelten","zelten in der stadt","lager innerhalb einer siedlung"}},{q="Was ist erforderlich, bevor man ein Lager aufschlägt?",a="Zu einem Lager gehört ein warmes, nahes Feuer.",al={"brauche ich ein lagerfeuer","wie man ein lager aufschlaegt","voraussetzungen fuer ein lager"}},{q="Wo lerne ich, wie man ein Lagerfeuer macht?",a="Kochlehrer und Köche überall in Azeroth vermitteln die grundlegenden Fertigkeiten zum Entfachen eines Kochfeuers.",al={"wo lagerfeuer lernen","wer lehrt lagerfeuer","lagerfeuer-lehrer"}},{q="Wie hängt Bergbau mit der Herstellung eines Magnetsteins zusammen?",a="Beim Bergbau lernt Ihr, die Mineralien und das Gestein zu bearbeiten, die Ihr für einen Lodestein benötigt.",al={"warum bergleute zelten","bergbau verbindung zu magnetstein","magnetstein herstellen"}},{q="Wohin sollte ich gehen, um mein neues Lager zu testen?",a="Geht durch die Stadttore hinaus in die offene Wildnis, wo Ihr fern der Stadtbewohner Platz zum Lagern findet.",al={"wo lager testen","magnetstein testen","im freien lagern"}}},fp="19,163,21.153.0,17.270.0,29.49.0,40.120.0,42.40.0,41.98.0,48.77.0,38.103.0"}
P.entries["quest:96047"] = {n="Grundlagen des Zeltens: Erste Hilfe",s="In Kharanos lehrt Euch Thamner Pol, Verbandtaschen für Lager in Dun Morogh zusammenzustellen. Mit diesen Vorräten können Reisende im Feld am Leben bleiben.",h="In Kharanos lehrt Euch Thamner Pol, Verbandtaschen für Lager in Dun Morogh zusammenzustellen.",kw={"verbände","grundlagen des zeltens","dun morogh","erste hilfe","verbandtasche","kharanos","überleben","thamner pol"},ang={["faction:Alliance"]="Als Rekrut der Allianz, der im eisigen Herzen von Khaz Modan ausgebildet wird, lernt Ihr, dass Eigenständigkeit und Feldmedizin für Militärverbände und Forschergruppen wichtig sind.",["race:Dwarf"]="Als Zwerg verlasst Ihr Euch auf robuste, praktische Ausrüstung, während Ihr auf den hohen, verschneiten Pässen von Dun Morogh patrouilliert. Eine Verbandtasche fürs Lager ist ein nützlicher Teil Eurer Vorräte.",["race:Gnome"]="Als geflüchteter oder umherziehender Gnom in Kharanos könnt Ihr Euch auf Feldmedizin verlassen, während Ihr außerhalb der verlorenen Hallen von Gnomeregan überlebt."},sec={{t="Wundversorgung in der Wildnis",b="Ihr könnt Eure grundlegenden Fertigkeiten im Verbinden von Wunden erweitern, indem Ihr lernt, Vorräte für einen Rastplatz zusammenzustellen. Thamner Pol zeigt Euch, wie aus medizinischen Grundmaterialien vollständige Taschen werden, einsatzbereit im Lager, wenn Reisende fernab jeder Zuflucht Versorgung benötigen."},{t="Die Lehren von Kharanos",b="Thamner Pol lehrt Euch praktische Methoden, um Expeditionslager mit Notfallvorräten auszustatten. Mit einer ordentlichen Verbandtasche kann eine Gruppe gemeinsam am Feuer Wunden verbinden und neue Kraft schöpfen, bevor sie wieder in die Kälte aufbricht."}},faq={{q="Welchen Zweck hat diese Aufgabe?",a="Frisch ausgebildete Sanitäter suchen Thamner Pol in Kharanos auf, um zu lernen, wie man Verbandtaschen für die Lagerplätze von Abenteurern herstellt.",al={"warum grundlagen des zeltens erste hilfe","was bewirkt diese quest","grundlagen des zeltens ziel"}},{q="Wer ist Thamner Pol?",a="Thamner Pol bildet in Kharanos in Dun Morogh Leute darin aus, Ausrüstung für Lager in der Wildnis herzustellen.",al={"wer ist thamner pol","thamner pol standort","wo ist thamner pol"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung findet in Kharanos statt, der wichtigsten Siedlung im Zentrum von Dun Morogh, südlich von Eisenschmiede.",al={"wohin gehen","grundlagen des zeltens standort","kharanos erste hilfe"}},{q="Warum ist eine Verbandtasche im Lager wichtig?",a="Eine Verbandtasche im Lager versorgt verletzte Reisende mit Vorräten, um ihre Wunden zu verbinden und sich zwischen Kämpfen sicher zu erholen.",al={"was bewirkt eine verbandtasche","warum eine verbandtasche herstellen","nutzen von erster hilfe im lager"}},{q="Braucht Ihr medizinische Vorkenntnisse, bevor Ihr Thamner Pol aufsucht?",a="Ja. Abenteurer sollten die Grundlagen der Ersten Hilfe kennen und etwas Geschick beweisen, bevor Thamner Pol ihnen fortgeschrittene Rezepte für die Lagerausstattung beibringt.",al={"voraussetzungen für grundlagen des zeltens","erforderliche fertigkeit in erster hilfe","erste hilfe als voraussetzung"}},{q="Steht diese Tätigkeit jedem Abenteurer offen?",a="Jeder Abenteurer kann Erste Hilfe erlernen, unabhängig von seiner Berufung, was sie zu einer nützlichen Fertigkeit für Reisende in Dun Morogh macht.",al={"kann das jeder machen","klassenvoraussetzungen","wer kann erste hilfe fürs lager erlernen"}}},fp="22,147,26.230.0,23.212.0,33.112.0,19.85.0,36.100.0,38.110.0,62.130.0,39.113.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Ihr bereitet Euch mit einem Fischglas und einem Lagerfeuer auf das Angeln in der Wildnis vor. Lernt, wo Ihr Euer Lager aufschlagen könnt und was einen Rastplatz behaglich macht.",h="Ihr bereitet Euch mit einem Fischglas und einem Lagerfeuer auf das Angeln in der Wildnis vor.",kw={"lager","lagerfeuer","lagern","kochkunst","fischglas","angeln","wildnis"},ang={["profession:Cooking"]="Lernt die Grundlagen der Kochkunst, bevor Ihr Euer Lager aufschlagt. Kochkunstlehrer bringen Reisenden bei, das Lagerfeuer zu entfachen, das ein Lagerplatz braucht."},sec={{t="Benimmregeln in der Wildnis",b="Reisen durch Azeroth erfordern ein wenig Wissen über die Wildnis. Wenn Ihr einen Rastplatz braucht, haltet Euer Zelt und Eure Ausrüstung außerhalb der Stadtgrenzen. Stadtbewohner und Wachen sehen es ungern, wenn Reisende ihre Habseligkeiten in Siedlungen ausbreiten. Bringt Eure Vorräte stattdessen in die offene Wildnis."},{t="Die Annehmlichkeiten des Lagers",b="Ein ordentlicher Lagerplatz braucht ein paar Annehmlichkeiten. Beginnt mit einem wärmenden Lagerfeuer; ein Kochkunstlehrer kann Euch beibringen, wie Ihr eines entfacht. Sobald das Feuer bereit ist, stellt ein handgefertigtes Fischglas auf. Dann ist Euer Rastplatz für einen Angler geeignet."}},faq={{q="Was lernt Ihr in Camping 101: Fishing?",a="Ihr lernt, ein Fischglas herzustellen und einen Rastplatz zum Angeln in der Wildnis vorzubereiten. Schlagt Euer Lager abseits von Siedlungen auf.",al={"was lehrt diese quest","fischglas herstellen","lagern angeln belohnung"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Schlagt Euer Lager in der Wildnis außerhalb der Stadtgrenzen auf. Stadtbewohner nehmen Anstoß daran, wenn Reisende ihre Ausrüstung auf öffentlichen Durchgangswegen ausbreiten.",al={"wo lager aufschlagen","lagern in der stadt erlaubt","regeln für lagerplätze"}},{q="Was braucht Ihr, bevor Ihr ein Lager aufschlagt?",a="Haltet ein Lagerfeuer bereit, das Euch wärmt. Ein Lagerplatz braucht eines, um vollständig zu sein.",al={"wie lager errichten","ist ein lagerfeuer nötig","voraussetzungen fürs lager"}},{q="Wie lernt Ihr, ein Lagerfeuer zu entfachen?",a="Kochkunstlehrer bringen Euch bei, wie Ihr ein Lagerfeuer entfacht. Wenn Ihr die Grundlagen der Kochkunst noch nicht gelernt habt, sucht einen Koch auf, der Euch unterweist.",al={"wie lagerfeuer entfachen","wo lagerfeuer lernen","wer lehrt feuermachen"}},{q="Wozu dient das Fischglas?",a="Das Fischglas schmückt einen Lagerplatz im Freien und passt zu einem Angler, der am Wasser rastet.",al={"wozu dient das fischglas","fischglas im lager verwenden","fischglas hintergrund"}},{q="Warum erhalten Abenteurer Unterricht im Lagern?",a="Lehrmeister der Wildnis vermitteln praktische Fertigkeiten für das Grenzland, darunter das Feuermachen und das Achten von Siedlungsgrenzen, bevor Ihr in die Wildnis aufbrecht.",al={"wer bietet camping 101 an","warum unterricht im lagern","überlebensratgeber fürs lagern"}}},fp="20,140,20.280.0,20.210.0,44.111.0,28.126.0,40.70.0,37.126.0,37.85.0,46.142.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="In Eisenschmiede können Kräuterkundige lernen, Räucherkerzen für das Lagerleben herzustellen. Reyna Stonebranch lehrt das Handwerk Sammlern, die bereit sind, wilde Kräuter praktisch zu nutzen.",h="In Eisenschmiede können Kräuterkundige lernen, Räucherkerzen für das Lagerleben herzustellen.",kw={"lager","camping 101","kräuterkunde","kräuter","räucherkerze","eisenschmiede","reyna stonebranch"},ang={["faction:Alliance"]="Als Kräuterkundiger der Allianz könnt Ihr Reyna Stonebranch in Eisenschmiede aufsuchen und Unterricht in der Feldkunde erhalten.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr aus gesammelten wilden Kräutern Räucherkerzen herstellen, um Zauberwirkern im Lager zu helfen.",["race:Dwarf"]="Als Zwerg findet Ihr die Kräuterkundelehrerin Reyna Stonebranch in Eisenschmiede, wo sie lehrt, Räucherkerzen herzustellen."},sec={{t="Praktische Feldbotanik",b="Das Sammeln wilder Kräuter kann einem Lager ebenso dienen wie einer Reisegruppe. Mit Geschick machen Kräuterkundige aus ihrer Ernte nützliche Hilfsmittel für das Leben im Freien."},{t="Aromastoffe für das Lagerfeuer",b="In Eisenschmiede können erfahrene Kräuterkundige bei Reyna Stonebranch Unterricht suchen. Sobald sie ihr Können bewiesen haben, lehrt sie sie, eine Räucherkerze herzustellen. Ihr beruhigender Duft hebt im Lager die Stimmung und schenkt Zauberwirkern und Heilern auf langen Expeditionen Ruhe."}},faq={{q="Was ist Camping 101: Herbalism?",a="Kräuterkundige lernen, wilde Pflanzen im Lager praktisch zu nutzen. Reyna Stonebranch lehrt das Handwerk in Eisenschmiede.",al={"was ist camping 101 herbalism","kräuterkunde camping quest","kräuterkunde lager guide"}},{q="Wer ist Reyna Stonebranch?",a="Reyna Stonebranch lehrt erfahrene Kräuterkundige in Eisenschmiede, wie sie Räucherkerzen für das Lager herstellen.",al={"wer lehrt räucherkerze","wo ist reyna stonebranch","reyna stonebranch aufenthaltsort"}},{q="Was bewirkt eine Räucherkerze?",a="Eine Räucherkerze erfüllt das Lager mit beruhigendem Duft und hebt die Stimmung der Reisenden.",al={"was macht eine räucherkerze","räucherkerze camping","räucherkerze zweck"}},{q="Warum sind Räucherkerzen für Zauberwirker nützlich?",a="Ihr beruhigender Duft hilft Zauberwirkern und Heilern, auf langen Expeditionen zur Ruhe zu kommen.",al={"wer profitiert von räucherkerze","ist die räucherkerze für zauberwirker"}},{q="Wohin müssen Kräuterkundige für diese Unterweisung reisen?",a="Kräuterkundige reisen nach Eisenschmiede, um Reyna Stonebranch aufzusuchen, nachdem sie ihr Können beim Kräutersammeln bewiesen haben.",al={"wohin für camping kräuterkunde","welche stadt für camping 101 herbalism"}},{q="Was ist erforderlich, bevor man das Herstellen der Kerze erlernen kann?",a="Kräuterkundige müssen ihr Können beim Kräutersammeln beweisen, bevor Reyna Stonebranch ihnen beibringt, Räucherkerzen herzustellen.",al={"wann kann man räucherkerze lernen","kräuterkunde camping voraussetzung"}}},fp="22,167,22.148.0,24.263.0,31.111.0,25.98.0,31.85.0,47.94.0,50.102.0,53.115.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="In Eisenschmiede lernen geübte Kürschner, aus Tierhäuten einen Lagerstuhl herzustellen. Balthus Stoneflayer lehrt sie das Handwerk, nachdem sie ihr Können bewiesen haben.",h="In Eisenschmiede lernen geübte Kürschner, aus Tierhäuten einen Lagerstuhl herzustellen.",kw={"balthus stoneflayer","lagerstuhl","camping","camping 101: skinning","bälge","eisenschmiede","kürschnerei"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Beute in der Wildnis häuten und einen Lagerstuhl herstellen, um Euch zwischen langen Fährtensuchen auszuruhen.",["faction:Alliance"]="Euer Weg zur Herstellung eines Lagerstuhls führt nach Eisenschmiede, der Bergstadt der Zwerge und Hauptstadt der Allianz.",["race:Dwarf"]="Als Zwerg könnt Ihr Balthus Stoneflayer in Eisenschmiede finden und lernen, wie geübte Kürschner aus Häuten Annehmlichkeiten fürs Lager herstellen."},sec={{t="Die Ausbeute der Wildnis",b="Das Häuten erlegter Wildtiere liefert Rüstungsschmieden und Handwerkern Leder für ihre Arbeit. Häute von Katzen, Bären und anderen Wildtieren sind auch unterwegs von Nutzen. Ihr werdet ausgesandt, diese Materialien in etwas Nützliches fürs Lager zu verwandeln, statt sie zu verkaufen."},{t="Der Handwerker von Eisenschmiede",b="Balthus Stoneflayer lehrt Kürschner in Eisenschmiede, aus vorbereiteten Pelzen einen Lagerstuhl herzustellen. Zuerst müsst Ihr ihm zeigen, dass Ihr Wildtiere häuten könnt. Erst dann wird er seine Herstellungsmethoden mit Euch teilen."},{t="Rast und Bereitschaft",b="Ein Lagerstuhl bietet Euch auf Reisen einen Platz, um am Feuer zu sitzen und auszuspannen. Ruht Euch dort aus, und Ihr könnt der nächsten Gefahr mit wachen Sinnen und neuer Kraft begegnen."}},faq={{q="Was ist Camping 101: Skinning?",a="Geübte Kürschner reisen nach Eisenschmiede, um zu lernen, wie man aus Tierhäuten einen Lagerstuhl herstellt.",al={"was ist camping 101 skinning","quest-zweck","camping 101 skinning quest"}},{q="Wer bringt Euch bei, den Campinggegenstand herzustellen?",a="Balthus Stoneflayer lehrt Euch in Eisenschmiede, einen Lagerstuhl herzustellen. Zeigt ihm zuerst, dass Ihr Wildtiere häuten könnt.",al={"mit wem sprechen","wer lehrt lagerstuhl","wer ist balthus stoneflayer"}},{q="Wohin müsst Ihr reisen, um diese Quest abzuschließen?",a="Begebt Euch nach Eisenschmiede, der Zwergenhauptstadt in den verschneiten Gipfeln von Dun Morogh. Balthus Stoneflayer unterrichtet dort Kürschner, die ihr Können beweisen.",al={"wohin gehen","standort von balthus","lehrer in eisenschmiede"}},{q="Welchen Gegenstand lernen Kürschner für ihr Lager herzustellen?",a="Ihr lernt, aus Tierhäuten einen Lagerstuhl herzustellen, der Euch unterwegs zwischen den Gefahren einen Platz zum Ausruhen bietet.",al={"was stellt man her","zweck des lagerstuhls","kürschner-lagerhandwerk"}},{q="Warum ist die Herstellung eines Lagerstuhls für einen Abenteurer nützlich?",a="Ein Lagerstuhl bietet Euch auf langen Wanderungen durch die Wildnis einen Platz zum Ausruhen, um Eure Konzentration wiederzufinden, bevor Euch die Gefahr ereilt.",al={"warum einen stuhl herstellen","was bringt lagerstuhl","vorteil von lagerstuhl"}},{q="Welche Fertigkeit ist erforderlich, bevor Balthus Euch unterrichtet?",a="Balthus Stoneflayer unterrichtet Euch, nachdem Ihr Euer Können beim Häuten von Wildtieren bewiesen habt.",al={"anforderungen","wann kann ich lernen","benötigte fertigkeit"}}},fp="21,144,20.234.0,24.194.0,18.173.0,30.85.0,42.103.0,47.136.0,52.106.0,54.111.0,59.78.0"}
P.entries["quest:96057"] = {n="Camping 101: Tailoring",s="Ein Schneider kann bei Uthrar Threx in Eisenschmiede lernen, wie man ein Rallying Banner für ein Lager herstellt. Das Banner soll die Moral stärken, und ein Lagerfeuer wird benötigt, um ein Lager aufzuschlagen.",h="Ein Schneider kann bei Uthrar Threx in Eisenschmiede lernen, wie man ein Rallying Banner für ein Lager...",kw={"lager","lagerfeuer","camping 101","eisenschmiede","moral","rallying banner","schneiderei","uthrar threx"},ang={["profession:Cooking"]="Ein Koch kann Euch beibringen, das Lagerfeuer zu entzünden, das Ihr braucht, bevor Ihr Euer Lager aufschlagt.",["profession:Tailoring"]="Als Schneider könnt Ihr lernen, ein Rallying Banner für Euer Lager herzustellen, sobald Ihr Euer Können in Eurem Handwerk bewiesen habt."},sec={{t="Ein Banner fürs Lager",b="Ein Lehrer in Eisenschmiede kann Euch zeigen, wie Ihr ein Banner für Euer Lager herstellt, sobald Ihr Euer Können in der Schneiderei bewiesen habt. Das Banner heißt Rallying Banner. Es kann Euch helfen, voller Tatkraft zu bleiben, und Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt."}},faq={{q="Wer lehrt Schneiderei fürs Lagerleben?",a="Uthrar Threx in Eisenschmiede kann Euch beibringen, einen Gegenstand fürs Lagerleben herzustellen, sobald Ihr Euer Können in der Schneiderei bewiesen habt.",al={"wer lehrt das","schneidereilehrer","uthrar threx"}},{q="Was kann ich mit Schneiderei herstellen?",a="Ihr könnt lernen, ein Rallying Banner für Euer Lager herzustellen.",al={"lagergegenstand aus schneiderei","welches banner","banner herstellen"}},{q="Was bewirkt das Rallying Banner?",a="Ein ermutigendes Banner kann Euch helfen, voller Tatkraft zu bleiben, und Moral ist wichtig für den Erfolg auf dem Schlachtfeld.",al={"zweck des banners","warum ein banner","rally banner"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Ein Koch kann Euch beibringen, eines zu entzünden.",al={"lagerfeuer benötigt","wie lager aufschlagen","voraussetzungen fürs lager"}}},fp="22,172,17.238.0,34.109.0,31.55.0,33.105.0,38.77.0"}
P.entries["quest:96058"] = {n="Camping 101: Engineering",s="Ein Ingenieur in Kharanos kann lernen, einen Reagent Bot für ein Lager herzustellen. Der Bot hilft, Euch mit Materialien für Zauber zu versorgen.",h="Ein Ingenieur in Kharanos kann lernen, einen Reagent Bot für ein Lager herzustellen.",kw={"bronk guzzlegear","lager","lagerfeuer","camping 101","ingenieurskunst","kharanos","reagent bot","zaubermaterialien"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, das für ein Lager benötigte Lagerfeuer zu entfachen.",["profession:Engineering"]="Als Ingenieur könnt Ihr bei Bronk Guzzlegear lernen, einen Reagent Bot für Euer Lager herzustellen."},sec={{t="Vorräte für ein Lager",b="Ein Ingenieur kann bei Bronk Guzzlegear in Kharanos lernen, wie man einen Reagent Bot herstellt. Ihr müsst Euer Können in der Ingenieurskunst beweisen, bevor er Euch unterrichtet. Der Bot hilft, Euch und Eure Verbündeten mit Materialien zu versorgen, die Ihr für Zauber benötigt."},{t="Bereit für die Wildnis",b="Ihr könnt jetzt einen Reagent Bot herstellen. Um ihn zu testen, verlasst den Ort und begebt Euch in die Wildnis, wo Ihr ein Lager aufschlagen könnt. Bringt auch ein Lagerfeuer mit; Köche können Euch beibringen, wie man eines entfacht."}},faq={{q="Wer bringt mir bei, einen Reagent Bot herzustellen?",a="Bronk Guzzlegear in Kharanos kann Euch beibringen, einen Reagent Bot herzustellen, sobald Ihr Euer Können in der Ingenieurskunst beweist.",al={"bronk bot unterricht","wer ist bronk guzzlegear","reagent bot lehrer"}},{q="Was macht ein Reagent Bot?",a="Ein Reagent Bot hilft, Euch und Eure Verbündeten mit Materialien zu versorgen, die für Zauber benötigt werden.",al={"wozu dient reagent bot","bot zaubermaterialien","lager bot"}},{q="Was brauche ich, bevor ich das lernen kann?",a="Ihr müsst Euer Können in der Ingenieurskunst beweisen, bevor Bronk Guzzlegear Euch beibringt, einen Reagent Bot herzustellen.",al={"können in der ingenieurskunst","wie reagent bot erlernen","camping 101 ingenieurskunst"}},{q="Wo kann ich den Reagent Bot ausprobieren?",a="Ihr könnt den Reagent Bot in der Wildnis testen, da die meisten Leute keine Lager mitten im Ort haben wollen.",al={"wo bot testen","lagerplatz","reagent bot wildnis"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Ein Lager braucht ein Lagerfeuer, und die meisten Köche können Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","wie lagerfeuer entfachen","kochen im lager"}}},fp="24,127,17.233.0,19.175.1,37.107.0,27.87.0,39.114.0,36.111.0,21.71.0"}
P.entries["quest:96059"] = {n="Camping 101: Enchanting",s="Ein Verzauberer in Eisenschmiede kann nach einem Fertigkeitsnachweis lernen, eine Verzauberte Laute fürs Lager herzustellen. Ihre Magie sorgt bei Rastpausen unterwegs für Unterhaltung.",h="Ein Verzauberer in Eisenschmiede kann nach einem Fertigkeitsnachweis lernen, eine Verzauberte Laute fürs...",kw={"lagergegenstand","camping für anfänger","verzauberte laute","verzauberkunst","eisenschmiede","thonys pillarstone"},ang={["profession:Engineering"]="Als Verzauberer könnt Ihr von Thonys Pillarstone lernen, eine Verzauberte Laute fürs Lager herzustellen, sobald Ihr Euer Können bewiesen habt."},sec={{t="Eine Laute fürs Lager",b="Eure nächste Lektion handelt von einer Melodie für unterwegs. In Eisenschmiede kann Thonys Pillarstone Euch beibringen, eine Verzauberte Laute herzustellen, sobald Ihr Euer Können in der Verzauberkunst bewiesen habt. Die Magie bietet Euch Unterhaltung in Ruhepausen, bevor Ihr Euch wieder auf den Weg macht."}},faq={{q="Wer kann mir beibringen, eine Verzauberte Laute herzustellen?",a="Thonys Pillarstone in Eisenschmiede kann Euch beibringen, eine Verzauberte Laute herzustellen, nachdem Ihr Euer Können in der Verzauberkunst bewiesen habt.",al={"thonys pillarstone","wer lehrt verzauberkunst-lagergegenstand"}},{q="Wozu dient die Verzauberte Laute?",a="Die Verzauberte Laute ist ein Lagergegenstand, der in Ruhepausen für Unterhaltung sorgen soll.",al={"zweck der laute","verzauberte laute lager"}},{q="Warum brauche ich Fertigkeit in der Verzauberkunst?",a="Ihr könnt lernen, den Lagergegenstand herzustellen, sobald Ihr Euer Können in der Verzauberkunst bewiesen habt.",al={"können in der verzauberkunst","laute herstellen lernen"}}},fp="23,149,15.267.0,43.114.0,31.84.0,31.86.0"}
P.entries["quest:96063"] = {n="Gaseous Gold",s="Sleebo Fizzlespout möchte Sumpfgas aus den Teichen südwestlich von hier. Er hofft, damit einen neuen Motor anzutreiben.",h="Sleebo Fizzlespout möchte Sumpfgas aus den Teichen südwestlich von hier.",kw={"motor","gasphiolen","gasförmiges gold","industrie","sumpfgas","wissenschaft","sleebo fizzlespout","öffnungen"},sec={{t="Ein neuer Treibstoff",b="Sleebo Fizzlespout sieht Gas aus Öffnungen nahe dem Wasser in den sumpfigen Teichen im Südwesten aufsteigen. Er entwickelt einen Motor, der mit dem Gas läuft, und bittet Euch, Sumpfgasphiolen für ihn zu sammeln. Diese Arbeit könnte helfen, den Treibstoff in Wissenschaft und Industrie einzusetzen."}},faq={{q="Wer bittet um Sumpfgas?",a="Sleebo Fizzlespout bittet Euch, Sumpfgasphiolen für ihn zu sammeln.",al={"wer möchte gas","sleebo fizzlespout"}},{q="Warum möchte Sleebo das Gas?",a="Sleebo entwickelt eine neue Art von Motor, der mit Sumpfgas läuft.",al={"wofür ist das gas","gasmotor"}},{q="Woher kommt das Sumpfgas?",a="Das Gas steigt aus Öffnungen nahe dem Wasser in sumpfigen Teichen südwestlich von Sleebo auf.",al={"wo ist das gas","gasöffnungen"}},{q="Wofür wird Sumpfgas verwendet?",a="Sleebo hofft, Sumpfgas als Treibstoff für seinen neuen Motor zu verwenden.",al={"verwendung von sumpfgas","gastreibstoff"}}},fp="12,109,10.260.0,28.62.0,29.65.0,35.76.0,27.57.0"}
P.entries["quest:96067"] = {n="Rock 'em and Sock 'em",s="Sleebo bittet Euch, G45-B4G zu testen, den Prototyp seines gasbetriebenen Motors. Der Versuch liefert ihm Hinweise für Reparaturen und Änderungen.",h="Sleebo bittet Euch, G45-B4G zu testen, den Prototyp seines gasbetriebenen Motors.",kw={"g45-b4g","gas","gasbetriebener motor","mechanischer gefährte","prototyp","sleebo","belastungstest"},sec={{t="Ein mechanischer Test",b="Sleebo hat einen funktionierenden Prototyp seines gasbetriebenen Motors, der sich in G45-B4Gs Truhe aus Sackleinen befindet. Mit gesammeltem Gas kann er den mechanischen Gefährten antreiben. Ihr sollt die Maschine in einem Kampf testen, damit Sleebo ihre Leistung beurteilen kann."},{t="Sleebos Notizen",b="Nach dem Test ist Sleebo von dem Spektakel und den gesammelten Notizen begeistert. Er will G45-B4G reparieren und den Motor vor dem nächsten Test anpassen."}},faq={{q="Wer ist G45-B4G?",a="G45-B4G ist Sleebos mechanischer Gefährte. In einer Truhe aus Sackleinen befindet sich der funktionierende Prototyp seines gasbetriebenen Motors.",al={"g45-b4g","wer ist g45","mechanischer gefährte"}},{q="Was will Sleebo testen lassen?",a="Sleebo möchte, dass Ihr G45-B4G, den funktionierenden Prototyp seines gasbetriebenen Motors, in einem Kampf testet.",al={"sleebos test","den motor testen","was teste ich"}},{q="Was treibt G45-B4G an?",a="Sleebo kann G45-B4G mit Gas antreiben, das Ihr gesammelt habt.",al={"gasbetriebener roboter","motorkraftstoff","was treibt g45 an"}},{q="Kann G45-B4G Schmerzen fühlen?",a="Nein. Sleebo sagt, G45-B4G könne nichts fühlen.",al={"fühlt g45 etwas","maschine verletzen","roboterschmerz"}},{q="Warum testet Sleebo seine Erfindung?",a="Sleebo möchte den Prototyp des gasbetriebenen Motors einem Belastungstest unterziehen und notieren, wie er sich schlägt.",al={"warum g45 testen","motorbelastungstest","sleebos erfindung"}}},fp="21,121,18.240.0,14.150.1,15.118.0,29.94.0,20.53.0,22.45.0,36.97.0"}
P.entries["quest:96078"] = {n="A Tale Spun Around the Fire",s="Kin'weelay bittet Euch, die Tafeleinritzungen zu Meister Gadrin nach Sen'jin zu bringen. Die Dunkelspeer bewahren ihre Traditionen durch Geschichten, und Gadrin möchte diese hören.",h="Kin'weelay bittet Euch, die Tafeleinritzungen zu Meister Gadrin nach Sen'jin zu bringen.",kw={"dunkelspeer","gurubashi","i'lalai","kin'weelay","meister gadrin","mündliches erzählen","sen'jin","tafeleinritzungen"},ang={["race:Troll"]="Als Troll bringt Ihr Meister Gadrin eine Geschichte über die Tradition der Dunkelspeer, dem es wichtig ist, das Erbe der Vorfahren zu bewahren und zu entdecken."},sec={{t="Eine geteilte Geschichte",b="Kin'weelay hat eine weitere Abschrift der Geschichte vorbereitet, falls Eure verloren geht. Die Geschichten der Dunkelspeer geben Legenden an die Jungen weiter und lehren durch gesprochene Worte Lektionen und Vorsicht. Bringt die Einritzungen zu Meister Gadrin, dem spirituellen Anführer der Dunkelspeer in Sen'jin, damit er die Geschichte hören kann."},{t="Gadrins Dank",b="Nachdem Ihr erklärt habt, wie die Einritzungen der I'lalai-Tafel in Eure Hände gelangt sind, hört Meister Gadrin aufmerksam zu. Er freut sich, dass Kin'weelay daran liegt, das über die Jahrhunderte verlorene Erbe der Dunkelspeer zu bewahren und wiederzuentdecken. Gadrin merkt an, dass sich die Dunkelspeer im großen Lauf der Geschichte erst vor Kurzem von den Gurubashi getrennt haben, und gibt Euch dann etwas, das Kin'weelay Euch als Dank zukommen lassen wollte."}},faq={{q="Wer möchte die Einritzungen?",a="Kin'weelay bittet Euch, die Tafeleinritzungen zu Meister Gadrin nach Sen'jin zu bringen.",al={"wer hat mich geschickt","kin'weelays geschichte","kin'weelay"}},{q="Warum soll ich sie zu Meister Gadrin bringen?",a="Meister Gadrin ist der spirituelle Anführer der Dunkelspeer, und Kin'weelay sagt, dass er die Geschichte hören möchte.",al={"warum gadrin","wohin mit den einritzungen","tafeleinritzungen"}},{q="Wie bewahren die Dunkelspeer ihre Traditionen?",a="Die Dunkelspeer geben Legenden durch mündliches Erzählen an die nächste Generation weiter und vermitteln dabei Lehren und warnende Geschichten.",al={"geschichten der dunkelspeer","mündliche überlieferung","trollgeschichten"}},{q="Woher stammen die Einritzungen?",a="Es sind Einritzungen von der I'lalai-Tafel.",al={"i'lalai-tafel","i'lalai","tafelgeschichte"}},{q="Wo ist Meister Gadrin?",a="Meister Gadrin befindet sich in Sen'jin in Durotar.",al={"gadrins aufenthaltsort","sen'jin","wo ist gadrin"}}},fp="27,168,13.283.0,15.381.1,23.84.0,31.99.0,41.115.0,27.42.0,23.47.0"}
P.entries["quest:96081"] = {n="Wound Dressings",s="Bruder Lowley auf Burg Farholde braucht Stoff für Verbände. Farholde kann Stoff nicht verlässlich herstellen, und der Vorrat geht zur Neige.",h="Bruder Lowley auf Burg Farholde braucht Stoff für Verbände.",kw={"verbände","brother lowley","stoff","farholde","burg farholde","goblins","mageweave cloth","orcs"},sec={{t="Ein knapper Vorrat",b="Auf Burg Farholde bittet Bruder Lowley Euch um Hilfe, denn guter Stoff wird knapp. Die Burg ist auf Importe von Goblins oder Stoff angewiesen, den sie Orcs abnimmt. Ohne Nachschub muss Lowley vielleicht aus alten Hemden Verbände machen, obwohl das Heer sie braucht, um Leben zu retten."}},faq={{q="Warum braucht Bruder Lowley Stoff?",a="Farholde braucht Stoff für Verbände, und der Vorrat an gutem Stoff geht zur Neige.",al={"warum stoff","lowleys verbände","stoffbedarf"}},{q="Warum kann Farholde keinen eigenen Stoff herstellen?",a="Farholde kann Stoff nicht verlässlich herstellen und ist daher auf Importe von Goblins oder Stoff angewiesen, den es Orcs abnimmt.",al={"stoffvorrat von farholde","stoffherstellung unmöglich","stoffherkunft"}},{q="Was geschieht, wenn der Stoff ausgeht?",a="Bruder Lowley muss vielleicht aus alten Hemden Verbände machen.",al={"keine verbände","alte hemden","stoffmangel"}},{q="Wer bittet um den Stoff?",a="Bruder Lowley auf Burg Farholde bittet Euch, Magiestoff zu sammeln.",al={"wer braucht stoff","brother lowley","stoffanforderung"}}},fp="15,130,14.261.0,35.86.0,38.114.0,35.57.0,23.67.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="Raan heißt neue Wanderer willkommen und zeigt ihnen, wie sie in der Wildnis bestehen. Ruht Euch an seinem einfachen Lagerfeuer aus, um Boosted Rest zu erhalten, und besucht dann nahegelegene Berufslehrer, um praktische Berufe zu erlernen.",h="Raan heißt neue Wanderer willkommen und zeigt ihnen, wie sie in der Wildnis bestehen.",kw={"einfaches lagerfeuer","boosted rest","lagereinrichtung","lagerfeuer","raan","the great outdoors","beruf","überleben in der wildnis"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Lagerfertigkeiten für Fährtenleser und Waldläufer, die unter freiem Himmel leben, unerlässlich sind.",["profession:Cooking"]="Als Koch wisst Ihr, dass ein einfaches Lagerfeuer einer Reisegruppe hilft, in der Wildnis zu ruhen und sich zu erholen."},sec={{t="Lehren der Wildnis",b="Raan hat die Wildnis bereist und lehrt andere, wie sie jenseits der Siedlungsmauern überleben. Ehrgeiz und Stahl allein bringen Euch nicht durch raues Wetter; praktische Lagerfertigkeiten sind entscheidend. Er heißt jene willkommen, die Glück und Ruhm suchen, und bietet allen Anleitung, die bereit sind zu lernen."},{t="Die Wärme des Herdfeuers",b="Raan bittet Euch, Euch an sein einfaches Lagerfeuer zu setzen und zu ruhen, bis Ihr Boosted Rest erhaltet. In Azeroths Wildnis kann das Wissen, wann man innehält, ein Lager aufschlägt und sich erholt, den Unterschied zwischen Leben und Tod bedeuten.\n\nNach der Lektion schickt Raan Euch zu nahegelegenen Dorflehrern. Dort könnt Ihr einen Beruf erlernen und spezialisierte Einrichtungen für Euer Lager herstellen."}},faq={{q="Wer vergibt die Quest The Great Outdoors?",a="Raan, ein erfahrener Reisender, lehrt umherziehende Abenteurer, wie sie in der offenen Wildnis überleben.",al={"wer bietet the great outdoors an","questgeber the great outdoors","raan lagerfeuerquest"}},{q="Was ist der Zweck von The Great Outdoors?",a="Die Lektion vermittelt das Überleben in der Wildnis. Ruht Euch vor gefährlichen Reisen an einem einfachen Lagerfeuer aus, um Boosted Rest zu erhalten.",al={"was lehrt the great outdoors","the great outdoors zweck","was lernt man von raan"}},{q="Wie wird die Quest abgeschlossen?",a="Setzt Euch an Raans einfaches Lagerfeuer und ruht Euch aus, bis Ihr Boosted Rest erhaltet.",al={"wie the great outdoors abschließen","raan lagerfeuer questziel","boosted rest questziel"}},{q="Was empfiehlt Raan nach Abschluss der Quest?",a="Nach der Lektion am Lagerfeuer ermutigt Raan Euch, nahegelegene Dorflehrer zu besuchen und einen praktischen Beruf zu erlernen. Handwerker können Lagereinrichtungen herstellen, die zu ihrem Handwerk passen.",al={"was rät raan als nächstes","wohin nach the great outdoors","nach abschluss von the great outdoors"}},{q="Was ist Boosted Rest?",a="Boosted Rest ist ein erholsamer Effekt, den man durch das Ausruhen an einem eingerichteten Lagerfeuer erhält. Er hilft Reisenden, sich zu erholen, während sie den Elementen trotzen.",al={"was ist boosted rest","lagerfeuer boosted rest stärkungszauber"}},{q="Können Abenteurer mithilfe von Berufen Lagereinrichtungen herstellen?",a="Ja. Örtliche Berufslehrer können Euch beibringen, nützliche Lagereinrichtungen passend zu Eurem Handwerk herzustellen, damit Ihr im Freien ein spezialisiertes Lager unterhalten könnt.",al={"können berufe lagerfeuer herstellen","berufe lagereinrichtungen","handwerk lagergegenstände"}}},fp="18,180,19.275.0,24.350.0,39.99.0,42.116.0,27.70.0,56.166.0,21.141.0,60.144.0"}
P.entries["quest:96102"] = {n="Camping 101: Tailoring",s="In der Schneidereiausbildung lernt Ihr, ein Aufmarschbanner herzustellen. Sein Test gehört in die Wildnis, wo ein Lager ein Lagerfeuer braucht.",h="In der Schneidereiausbildung lernt Ihr, ein Aufmarschbanner herzustellen.",kw={"lagerfeuer","lagern","kochkunst","aufmarschbanner","schneiderei","wildnis"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, ein Lagerfeuer zu machen.",["profession:Tailoring"]="Als Schneider könnt Ihr ein Aufmarschbanner für ein Lager herstellen."},sec={{t="Zuerst ein Lagerfeuer",b="Ihr könnt jetzt ein Aufmarschbanner herstellen, und der Abschlusshinweis verlangt einen Test in der Wildnis. Ein Lager braucht ein Lagerfeuer, bevor Ihr es aufschlagt. Die meisten Köche können Euch beibringen, eines zu machen, also fragt einen Kochlehrer nach den Grundlagen, falls Ihr sie noch nicht gelernt habt."}},faq={{q="Was kann ich danach herstellen?",a="In der Schneidereiausbildung lernt Ihr, Euer eigenes Aufmarschbanner herzustellen.",al={"was stelle ich her","bannerrezept","schneiderei banner"}},{q="Wo sollte ich das Banner testen?",a="Testet Euer Aufmarschbanner in der Wildnis. Laut Abschlusshinweis halten Stadtbewohner im Allgemeinen wenig von Lagern mitten in der Stadt.",al={"wo testen","wo lagern","banner testen"}},{q="Was braucht ein Lager?",a="Bevor Ihr ein Lager aufschlagt, braucht Ihr ein Lagerfeuer.",al={"was braucht ein lager","lagerfeuer benötigt","grundlagen des lagerns"}},{q="Wer kann mir beibringen, ein Lagerfeuer zu machen?",a="Die meisten Köche können Euch beibringen, ein Feuer zu machen. Ein Kochlehrer kann Euch die Grundlagen beibringen.",al={"lagerfeuer lehrer","wer lehrt feuermachen","kochfeuer"}}},fp="22,124,16.243.0,27.65.0,31.134.0,22.46.0,36.84.0"}
P.entries["quest:96103"] = {n="A Feast for Buzzards",s="Ein zerschlagenes Skelett in den Ebenen trägt Spuren, die einem Jäger verraten könnten, was geschehen ist. Ihr bringt seinen Schädel zu Neza Bloodsnout nach Rog'mar, damit sie ihr Urteil fällt.",h="Ein zerschlagenes Skelett in den Ebenen trägt Spuren, die einem Jäger verraten könnten, was geschehen ist.",kw={"ein festmahl für aasgeier","klauenspuren","angenagter schädel","neza bloodsnout","rog'mar","skelett","zahnspuren"},sec={{t="Ein Schädel in den Ebenen",b="Die Knochen liegen zerschlagen unter der Sonne, ihre blasse Oberfläche von Formen wie Zähnen und Klauen gezeichnet. Die Schäden lassen das Opfer unbekannt. Ihr bringt den Schädel zu Neza Bloodsnout nach Rog'mar, wo eine Jägerin vielleicht erkennt, was die Spuren offenbaren."}},faq={{q="Was ist mit dem Skelett geschehen?",a="Seine Gliedmaßen tragen Spuren, die Zähnen und Klauen ähneln, doch der Angreifer bleibt unklar.",al={"skelett in den ebenen","woran es starb"}},{q="Warum bringt Ihr den Schädel zu Neza?",a="Neza ist eine Jägerin in Rog'mar, die vielleicht erkennt, was die Spuren bedeuten.",al={"warum der schädel zu neza","neza bloodsnout"}},{q="Wer war das Opfer?",a="Das Skelett ist schwer beschädigt, und seine Identität ist unbekannt, bevor Neza den Schädel untersucht.",al={"wessen skelett","wer ist der tote"}},{q="Wo befindet sich Neza Bloodsnout?",a="Neza Bloodsnout befindet sich in Rog'mar.",al={"nezas aufenthaltsort","wo liegt rog'mar"}}},fp="20,151,21.235.0,30.82.0,28.69.0,19.90.0,25.30.0"}
P.entries["quest:96104"] = {n="Song of the Strider",s="Neza Bloodsnout entdeckt nahe Rog'mar die Spuren eines großen Löwen und bietet an, ihn herauszulocken. Ihr bringt ihr einen tallstrider-Schnabel, damit sie daraus eine Jagdpfeife fertigen kann.",h="Neza Bloodsnout entdeckt nahe Rog'mar die Spuren eines großen Löwen und bietet an, ihn herauszulocken.",kw={"schnabel","löwe","neza bloodsnout","rog'mar","lied des tallstriders","tallstrider","pfeife"},sec={{t="Eine Jagdpfeife",b="Bei Rog'mar deutet Neza Bloodsnout die Spuren als die eines Löwen, wahrscheinlich des Anführers eines Rudels in der Nähe. Sie überlässt Euch die erste Beute und hilft dabei, das Tier herauszulocken. Dafür braucht sie einen tallstrider-Schnabel, um eine Pfeife zu fertigen, die wie der Ruf eines verwundeten tallstrider klingt."}},faq={{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist eine Jägerin bei Rog'mar, die Pfeifen und Tierlaute herstellen kann.",al={"neza","wer ist neza","neza bloodsnout"}},{q="Was glaubt Neza, hat die Markierungen verursacht?",a="Neza glaubt, dass die Markierungen von einem Löwen stammen, wahrscheinlich dem Anführer eines Rudels in der Nähe.",al={"was verursachte diese markierungen","löwenspuren","markierungen bei rog'mar"}},{q="Warum braucht Neza einen tallstrider-Schnabel?",a="Neza braucht einen tallstrider-Schnabel, um eine Pfeife zu fertigen, die den Ruf eines verwundeten tallstrider nachahmt.",al={"wofür der schnabel","wofür tallstrider-schnabel","schnabel für pfeife"}},{q="Wozu dient die Pfeife?",a="Die Pfeife soll den Löwen herauslocken, indem sie wie der Ruf eines verwundeten tallstrider klingt.",al={"was bewirkt die pfeife","löwen herauslocken","löwenpfeife"}},{q="Wohin bittet Neza Euch, den Schnabel zu bringen?",a="Bringt den unversehrten tallstrider-Schnabel zu Neza Bloodsnout bei Rog'mar.",al={"wohin den schnabel bringen","nezas ort","schnabel abgeben"}}},fp="19,157,18.271.0,23.78.0,39.79.0,38.90.0,24.81.0,42.64.0"}
P.entries["quest:96105"] = {n="King of the Wild Plains",s="Neza Bloodsnout bei Rog'mar schickt Euch los, um den Anführer eines Löwenrudels zu jagen. Ein Tallstrider Call wird das Tier auf dem Hügel im Süden herbeirufen, wo die Löwen leben.",h="Neza Bloodsnout bei Rog'mar schickt Euch los, um den Anführer eines Löwenrudels zu jagen.",kw={"fell","hügel","könig der wilden ebenen","anführer","löwenrudel","neza bloodsnout","rog'mar","tallstrider call"},sec={{t="Der Ruf",b="Neza Bloodsnout bei Rog'mar hat einen Tallstrider Call für Euch bereit. Bringt ihn auf die Spitze des Hügels im Süden, wo die Löwen leben, und benutzt ihn, wenn Ihr bereit seid, Euch dem Anführer des Rudels zu stellen. Neza bittet Euch, das Fell des Tieres zurückzubringen, und die Jagd wird Eure Stärke auf diesen Ebenen auf die Probe stellen."}},faq={{q="Wer will das Löwenfell?",a="Neza Bloodsnout bei Rog'mar bittet Euch, das Fell des Anführers des Löwenrudels zurückzubringen.",al={"wer hat mich geschickt","neza bloodsnout","fell für neza"}},{q="Was bewirkt der Tallstrider Call?",a="Der Tallstrider Call ruft bei Benutzung den Anführer des Löwenrudels herbei.",al={"wozu ist die pfeife","rufpfeife","löwen herbeirufen"}},{q="Wo soll ich den Tallstrider Call benutzen?",a="Benutzt den Tallstrider Call auf der Spitze des Hügels im Süden, wo die Löwen leben.",al={"wo ist der hügel","löwenhügel","wo soll ich es rufen"}},{q="Was jage ich?",a="Ihr jagt den Anführer des Löwenrudels.",al={"welches tier","könig der wilden ebenen","löwenanführer"}}},fp="23,159,8.293.0,26.86.0,34.68.0,40.83.0,18.45.0"}
P.entries["quest:96107"] = {n="Feathers for Fletching",s="Neza Bloodsnout in Rog'mar stellt ihre Pfeile selbst her und bittet um Plains Buzzard Feathers. Ihre grobe Struktur macht sie für die Befiederung nützlich.",h="Neza Bloodsnout in Rog'mar stellt ihre Pfeile selbst her und bittet um Plains Buzzard Feathers.",kw={"pfeile","federn","befiederung","jäger","neza bloodsnout","plains buzzard","rog'mar"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Ihr regelmäßig Pfeile braucht. Neza stellt ihre selbst her und vertraut auf ihr handwerkliches Können."},sec={{t="Nezas Pfeile",b="In Rog'mar bittet Neza Bloodsnout Euch, Federn von den Bussarden in der Nähe zu sammeln. Sie fertigt ihre Pfeile von Hand und vertraut auf ihre eigene Arbeit. Die groben Federn eignen sich zur Befiederung, den Federn, die einem Pfeil zu einem geraden Flug verhelfen."}},faq={{q="Warum möchte Neza Bussardfedern?",a="Neza verwendet die groben Plains Buzzard Feathers zur Befiederung der Pfeile, die sie von Hand herstellt.",al={"grund für bussardfedern","warum federn","neza federn"}},{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist eine Pfeilmacherin in Rog'mar, die ihre Pfeile am liebsten von Hand herstellt.",al={"wer ist neza","neza bloodsnout","neza in rog'mar"}},{q="Wo finde ich Neza?",a="Neza Bloodsnout ist in Rog'mar.",al={"wo ist neza","nezas standort","rog'mar neza"}}},fp="22,139,13.215.0,36.91.0,23.84.0,22.30.0"}
P.entries["quest:96108"] = {n="Poison Tips",s="Neza Bloodsnout möchte das Gift der Glade Vipers aus den Tümpeln südlich von Rog'mar. Sie will Pfeile damit bestreichen, obwohl das Gift das Fleisch verdirbt.",h="Neza Bloodsnout möchte das Gift der Glade Vipers aus den Tümpeln südlich von Rog'mar.",kw={"glade viper","neza bloodsnout","giftpfeile","giftspitzen","rog'mar","vipergift"},sec={{t="Ein tödlicher Überzug",b="Gift kann einen Pfeil wirksamer machen, doch es verdirbt das Fleisch. Neza Bloodsnout bei Rog'mar glaubt, dass Ihr das Gift der Vipern an den Tümpeln im Süden sammeln könnt. Ihr Gift ist gefährlich im Umgang, daher ist beim Sammeln Vorsicht geboten."}},faq={{q="Wer möchte das Vipergift?",a="Neza Bloodsnout bei Rog'mar möchte das Gift der Glade Vipers.",al={"wer bat um gift","neza bloodsnout gift","wer ist neza"}},{q="Wofür ist das Gift gedacht?",a="Neza will das Gift als Überzug für Pfeile verwenden.",al={"wozu das gift","giftpfeile","wofür wird es verwendet"}},{q="Woher stammt das Gift?",a="Die Glade Vipers an den Tümpeln im Süden erzeugen das Gift.",al={"wo sind die vipern","fundort des vipergifts","vipern an den tümpeln"}},{q="Warum Pfeile mit Gift bestreichen?",a="Giftüberzüge machen Pfeile gegen Beute wirksamer, verderben aber das Fleisch.",al={"warum giftpfeile","warum giftspitzen","pfeile verstärken"}},{q="Ist das Sammeln des Gifts der Glade Vipers gefährlich?",a="Ja. Neza warnt, dass Ihr beim Sammeln dem Gift der Vipern erliegen könntet.",al={"kann mich das gift verletzen","gefahr durch vipergift","giftwarnung"}}},fp="11,140,16.235.0,26.51.0,22.59.0,31.61.0,28.72.0,41.79.0"}
P.entries["quest:96109"] = {n="A Hunter's Quiver",s="Neza Bloodsnout bei Rog'mar braucht Löwenfelle für einen Jägerköcher. Ihr sammelt Felle von den Löwen auf dem südlichen Hügel.",h="Neza Bloodsnout bei Rog'mar braucht Löwenfelle für einen Jägerköcher.",kw={"pfeile","jäger","jägerköcher","löwenfelle","löwen","neza bloodsnout","begehrte löwenfelle","rog'mar"},ang={["class:Hunter"]="Als Jäger braucht Ihr einen Köcher, der viele Pfeile fasst, ohne Euch zu behindern."},sec={{t="Ausrüstung eines Jägers",b="Die Waffen eines Jägers brauchen einen Köcher, der viele Pfeile fasst, ohne seinen Träger zu behindern. Neza Bloodsnout bei Rog'mar bittet Euch, dafür begehrte Löwenfelle zu sammeln. Die Löwen jagen in Rudeln, daher warnt Neza Euch davor, Euch umzingeln zu lassen."}},faq={{q="Wer braucht die Löwenfelle?",a="Neza Bloodsnout bei Rog'mar braucht begehrte Löwenfelle für einen Jägerköcher.",al={"wer die felle möchte","neza bloodsnout felle"}},{q="Wofür sind die Felle?",a="Die Löwenfelle sind das Material für einen robusten Köcher, der eng anliegt und viele Pfeile fasst, ohne seinen Träger zu behindern.",al={"wofür löwenfelle","köcherfelle"}},{q="Wo sind die Löwen?",a="Die Löwen halten sich auf einem Hügel im Süden auf, der von Rog'mar aus zu sehen ist.",al={"löwenhügel","wo löwen"}},{q="Warum möchte Neza Löwenfelle?",a="Neza sagt, Löwenfelle eignen sich gut für das Leben als Jäger in der Steppe.",al={"warum löwenfelle","löwen für köcher"}},{q="Wovor warnt Neza?",a="Neza warnt, dass die Löwen in Rudeln jagen und Euch umzingeln könnten.",al={"warnung vor löwen","rudel"}}},fp="17,120,15.230.0,25.73.0,23.118.0,20.62.0,30.71.0,28.61.0"}
P.entries["quest:96125"] = {n="In Need of Relief",s="Einem Wächter südlich von Bolder'ok fehlt Ablösung, nachdem Löwenfelle gesammelt und orkische Wilderer ausgeschaltet wurden. Dunston Willis ist nicht aus der Ogersiedlung zurückgekehrt, und Ihr sollt ihn finden.",h="Einem Wächter südlich von Bolder'ok fehlt Ablösung, nachdem Löwenfelle gesammelt und orkische Wilderer...",kw={"bolder'ok","demar","dunston willis","braucht ablösung","löwenfelle","oger","orcische wilderer","wache"},sec={{t="Eine fehlende Ablösung",b="Die Wache wartet noch immer auf die versprochene Ablösung. Dunston Willis, ein Entdecker, brach vor einigen Tagen auf, um die Ogersiedlung im Norden zu untersuchen, und sollte zurückkehren, um den Posten zu übernehmen. Der Wächter bittet Euch, ihn unter den Ogern zu suchen. Wenn Dunston noch lebt, bringt ihn zurück; andernfalls bringt einen Beweis, damit Demar jemand anderen schicken kann."}},faq={{q="Wer ist Dunston Willis?",a="Dunston Willis ist ein Entdecker, der aufbrach, um Bolder'ok, die Ogersiedlung im Norden, zu untersuchen.",al={"dunston","wer ist dunston","entdecker willis"}},{q="Warum sucht der Wachposten nach Dunston?",a="Dunston sollte zurückkehren und den Posten des Wachpostens übernehmen, ist aber nicht zurückgekommen.",al={"warum dunston suchen","fehlende ablösung","wachposten braucht hilfe"}},{q="Wohin ist Dunston gegangen?",a="Dunston ging, um die Ogersiedlung bei Bolder'ok zu untersuchen.",al={"dunstons aufenthaltsort","wo ist willis","ogersiedlung"}},{q="Was soll ich tun?",a="Ihr sollt Dunston unter den Ogern suchen. Wenn er noch lebt, bringt ihn zurück. Andernfalls bringt einen Beweis, damit Demar einen weiteren Wachposten schicken kann.",al={"was soll ich tun","dunston finden","ablösung gesucht"}},{q="Was geschah, bevor Dunston verschwand?",a="Die Löwenfelle wurden gesammelt und die orcischen Wilderer getötet, bevor der Wachposten erwartete, dass Dunston die Wache ablöst.",al={"löwenfelle","wilderer getötet","was geschah zuerst"}}},fp="17,194,16.325.0,22.98.0,37.88.0,21.61.0,33.134.0,42.121.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Nahe den Baumbeständen westlich des Stonebullsees bedroht Chakuyak Reisende, die Mulgore durchqueren. Die einheimischen Stammesangehörigen haben die wilde Wölfin zur Jagd freigegeben, und ihr Balg wird in Ehren gehalten werden.",h="Nahe den Baumbeständen westlich des Stonebullsees bedroht Chakuyak Reisende, die Mulgore durchqueren.",kw={"chakuyak","mulgore","präriewolf","stonebullsee","taurenjagd","reisende","wolfsbalg"},ang={["class:Hunter"]="Als Jäger braucht Ihr Geduld und scharfe Sinne, um einen wilden, einzelgängerischen Alphawolf durch bewaldete Hügel zu verfolgen. Begegnet dem Raubtier mit Respekt.",["race:Tauren"]="Als Tauren kennt Ihr das Gleichgewicht zwischen der Ehrfurcht vor der Natur und der Pflicht, Euren Stamm zu schützen. Den Balg eines erlegten Tieres zu nutzen, ehrt es."},sec={{t="Der Schatten des Stonebullsees",b="Chakuyak durchstreift die Baumbestände westlich des Stonebullsees, wo Präriewölfe über Mulgores grasbewachsene Hochebenen und sanfte Hügel ziehen. Dieses wilde Alphaweibchen ist zur Gefahr für Reisende aus der Ferne geworden, weshalb einheimische Jäger sie zum Abschuss freigegeben haben, bevor weitere Wanderer zu Schaden kommen."},{t="Ehrfurcht und Notwendigkeit",b="Für die einheimischen Stämme verlangt das Töten Chakuyaks nach ernster Ehrfurcht, nicht nach Prahlerei. Sie sehen es als notwendig an, um Reisende und Dorfbewohner zu schützen. Ihr dichter Balg wird gegerbt und genutzt, um die Wölfin zu ehren und sicherzustellen, dass ihr Opfer nicht vergebens ist."}},faq={{q="Wer oder was ist Chakuyak?",a="Chakuyak ist eine große, ungewöhnlich aggressive Präriewölfin, die Reisende in Mulgore bedroht.",al={"was ist chakuyak","wer ist chakuyak","ist chakuyak ein wolf"}},{q="Wo befindet sich Chakuyak?",a="Chakuyak durchstreift die Baumbestände westlich des Stonebullsees, inmitten der bewaldeten Hügel.",al={"wo chakuyak finden","chakuyak fundort","wo streift chakuyak umher"}},{q="Warum muss Chakuyak zur Strecke gebracht werden?",a="Chakuyak ist kühn und aggressiv geworden und stellt damit eine Gefahr für Reisende aus der Ferne dar.",al={"warum chakuyak töten","chakuyak bedrohung"}},{q="Was geschieht nach der Jagd mit Chakuyaks Balg?",a="Ihr Balg wird haltbar gemacht und genutzt, damit nichts verschwendet wird.",al={"was geschieht mit chakuyaks balg","chakuyaks fell"}},{q="Brauche ich eine Gruppe, um Chakuyak zu jagen?",a="Chakuyak ist außergewöhnlich wild. Reisende schließen sich oft zu kleinen Jagdgruppen zusammen, um sie sicher aufzuspüren und zu erlegen.",al={"gruppe für chakuyak sinnvoll","ist chakuyak allein schwer zu besiegen"}},{q="Wer würdigt Euren Sieg über Chakuyak?",a="Der Jäger, der die Jagd ausgerufen hat, verspricht, Eure Tat vor dem Stammeshäuptling zu preisen, wenn Ihr mit Chakuyaks Balg zurückkehrt.",al={"wer belohnt die jagd auf chakuyak","chakuyak häuptling"}}},fp="8,179,28.287.0,23.239.0,24.90.0,26.79.0,33.94.0,47.59.0,35.112.0,44.119.0"}
P.entries["quest:96137"] = {n="Ira's Dagger",s="Sirra Von'Indi bittet Euch, mehr über Iras Dolch und die Worgs herauszufinden, die noch immer Reisenden zusetzen. Iras Geist hat im Wald womöglich noch etwas zu erledigen.",h="Sirra Von'Indi bittet Euch, mehr über Iras Dolch und die Worgs herauszufinden, die noch immer Reisenden...",kw={"black ravager","dunkelhain","ira","iras dolch","waldläuferin","sirra von'indi","geist","worg","young black ravager"},sec={{t="Der Dolch einer Waldläuferin",b="Sirra Von'Indi in Dunkelhain bittet Euch, Euch um die Worgs zu kümmern, die im Wald weiterhin Opfer fordern. Ira war eine selbst ernannte Waldläuferin, die den Wald sicherte, indem sie Bestien davon abhielt, Reisende anzugreifen. Ihr Geist wandert noch immer dort umher, und der Dolch gehörte ihr. Sirra sucht weitere Informationen über die Klinge."}},faq={{q="Wer war Ira?",a="Ira war eine selbst ernannte Waldläuferin, die den Wald sicherte, indem sie Bestien davon abhielt, Reisende anzugreifen.",al={"iras hintergrundgeschichte","wer ist ira"}},{q="Warum wandert Iras Geist durch den Wald?",a="Iras Geist wandert noch immer durch den Wald, und womöglich hat sie dort noch etwas zu erledigen.",al={"iras geist warum","warum ist ira ein geist"}},{q="Was ist Iras Dolch?",a="Es ist ein kleiner Dolch, der Ira gehörte.",al={"iras dolch","geschichte des dolchs"}},{q="Warum kümmert Ihr Euch um die Worgs?",a="Die Worgs fordern weiterhin im ganzen Wald Opfer, und womöglich besteht Iras unerledigte Aufgabe darin, sie zu vertreiben.",al={"worgs im wald","ira worg quest"}},{q="Wer erkundigt sich nach dem Dolch?",a="Sirra Von'Indi in Dunkelhain bittet Euch, mit dem Dolch zu ihr zurückzukehren, um mehr zu erfahren.",al={"sirra dolch","wer will iras dolch"}}},fp="12,145,17.316.0,12.103.0,40.81.0,21.42.0,31.114.0,26.91.0"}
P.entries["quest:96138"] = {n="Merrick's Bow",s="Sirra Von'Indi bittet Euch, den Ogern nachzugehen, die Merrick Valors Geist nahe Rabenflucht beunruhigen. Merricks Bogen könnte helfen, die Geschichte des Ortes zu erhellen.",h="Sirra Von'Indi bittet Euch, den Ogern nachzugehen, die Merrick Valors Geist nahe Rabenflucht beunruhigen.",kw={"dunkelhain","merrick valor","merricks bogen","oger","rabenflucht","sirra von'indi","splinter fist","wächter"},sec={{t="Die Sorge eines Geistes",b="Nahe Rabenflucht wandert Merrick Valors Geist noch immer über die Straßen. Ihr habt einen Bogen, den er zurückgelassen hat, und seine unerledigten Angelegenheiten könnten mit den Ogern südlich des Ortes zusammenhängen. Sirra Von'Indi in Dunkelhain kann Euch mehr über den Bogen und Merricks Vergangenheit erzählen."},{t="Merricks Vergangenheit",b="Sirra Von'Indi sagt, Merrick habe sich immer beweisen wollen und ihm und seiner Familie sei etwas zugestoßen. Sie dankt Euch dafür, dass Ihr den Bogen gebracht habt, und hofft, dass er mehr Licht auf Rabenfluchts Geschichte werfen wird."}},faq={{q="Wer war Merrick Valor?",a="Merrick Valor war ein berühmter Wächter, der stolz darauf war, die Straßen vor vordringenden Feinden zu schützen.",al={"merrick","merrick valor"}},{q="Warum wandert Merricks Geist umher?",a="Merricks Geist wandert noch immer über die Straßen. Seine unerledigten Angelegenheiten könnten mit den Ogern südlich von Rabenflucht zusammenhängen.",al={"merricks geist","warum wandert der geist umher"}},{q="Was hat Merricks Bogen mit Rabenflucht zu tun?",a="Sirra Von'Indi hofft, dass Merricks Bogen mehr Licht auf Rabenfluchts Geschichte werfen kann.",al={"merricks bogen","bogen rabenflucht"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist in Dunkelhain und kann Euch mehr über Merricks Bogen erzählen.",al={"sirra","sirra von indi"}},{q="Was ist Merrick und seiner Familie zugestoßen?",a="Sirra Von'Indi sagt, Merrick und seiner Familie sei etwas zugestoßen, nennt aber keine weiteren Einzelheiten.",al={"merricks familie","was geschah mit merrick"}}},fp="13,154,18.240.0,14.205.1,22.96.0,34.111.0,51.79.0,22.73.0,40.95.0"}
P.entries["quest:96139"] = {n="The Valor Family",s="In Dunkelhain sucht Sirra Von'Indi Aufzeichnungen über die verschollenen Bewohner von Rabenflucht. Das Dorf erinnert sich an ihren Mut, doch ihre Bibliothek bewahrt nur wenig von Rabenfluchts Geschichte.",h="In Dunkelhain sucht Sirra Von'Indi Aufzeichnungen über die verschollenen Bewohner von Rabenflucht.",kw={"dunkelhain","dämmerwald","geschichte","lady althea","rabenflucht","sirra von'indi","foliant","familie valor"},sec={{t="Eine verlorene Geschichte",b="Sirra Von'Indi sagt, mutige Menschen hätten Dunkelhain geholfen, zu bestehen. Lady Althea gehörte zu ihnen, ebenso wie jene, die in Rabenflucht starben. Ihr werdet gebeten, nach allem zu suchen, was die Erinnerung an sie bewahren könnte."},{t="Der Foliant",b="Das Buch, das Ihr zurückbringt, erzählt von der Familie Valor. Sirra bietet an, es abzuschreiben, und freut sich über jedes weitere Material über sie."}},faq={{q="Wer bittet mich, Rabenflucht zu durchsuchen?",a="Sirra Von'Indi, deren Bibliothek in Dunkelhain liegt, bittet Euch, Rabenflucht nach Material über seine Bewohner zu durchsuchen.",al={"wer will das buch","sirra rabenflucht","wer ist sirra"}},{q="Warum will Sirra Aufzeichnungen aus Rabenflucht?",a="Sirra möchte, dass Rabenfluchts Geschichte in Erinnerung bleibt. Sie ging mit den Menschen verloren, die dort lebten.",al={"warum rabenflucht durchsuchen","rabenfluchts geschichte","erinnerung an rabenflucht"}},{q="Wer half laut Sirra dabei, Dunkelhain zu erhalten?",a="Sirra nennt Lady Althea und jene, die in Rabenflucht ihr Leben verloren, als mutige Menschen, deren Taten Dunkelhain halfen, zu bestehen.",al={"dunkelhains helden","lady althea","wer rettete dunkelhain"}},{q="Wie steht es um Rabenfluchts Geschichte?",a="Sirra sagt, Rabenfluchts Geschichte sei mit seinen Bewohnern verloren gegangen. Ihre Bibliothek enthält nur wenig darüber.",al={"was geschah mit rabenflucht","rabenfluchts vergangenheit","rabenflucht verloren"}}},fp="16,162,14.194.0,8.118.1,38.107.0,44.95.0,50.123.0,34.98.0"}
P.entries["quest:962"] = {n="Schlangenflaum",s="Tief in den Höhlen des Wehklagens weckt Schlangenflaum die Aufmerksamkeit von Apothekerin Zamah. Sie sucht weitere Exemplare für die Forschung der Königlichen Apothekervereinigung und die Verlassenen.",h="Tief in den Höhlen des Wehklagens weckt Schlangenflaum die Aufmerksamkeit von Apothekerin Zamah.",kw={"apotheker","brachland","königliche apothekervereinigung","schlangenflaum","die anhöhe der geister","donnerfels","unterstadt","die höhlen des wehklagens","zamah"},ang={["faction:Horde"]="Diese Arbeit stärkt das frühe Bündnis zwischen Unterstadt und den Stämmen Kalimdors. Sie teilen Ressourcen und seltene Reagenzien über den Ozean hinweg.",["profession:Herbalism"]="Die entstellten Höhlen des Wehklagens lassen Pflanzen gedeihen, die nirgendwo sonst auf der sonnenverbrannten Oberfläche des Brachlands zu finden sind.",["race:Tauren"]="Als Tauren seht Ihr die Gastfreundschaft der Horde im Empfang der Apotheker der Verlassenen unter der Anhöhe der Geister. Ihre tödlichen Mixturen stehen im Gegensatz zur traditionellen Heilung durch die Erde.",["race:Undead"]="Das Sammeln von Schlangenflaum unterstützt die alchemistische Arbeit der Königlichen Apothekervereinigung in Lordaeron im Auftrag der Dark Lady."},sec={{t="Die Augen der Apothekerin",b="Apothekerin Zamah wacht über die Teiche der Visionen unter der Anhöhe der Geister in Donnerfels. Sie kam als Gesandte der Königlichen Apothekervereinigung aus Unterstadt. Ihre Gastgeber, die Tauren, kümmern sich um das spirituelle Gleichgewicht und das verwundete Land, während Zamah seltene und virulente Stoffe untersucht. Sie hat eine Probe Schlangenflaum isoliert und sucht weitere für Fürstin Sylvanas Windläufer und die Forschung der Verlassenen."},{t="Die Tiefen der Höhlen",b="Schlangenflaum wächst in den feuchten, verwinkelten Grotten der Höhlen des Wehklagens, fern der offenen Sonne des Brachlands. Die verdorbenen Druiden des Giftzahns haben diese feuchten Tiefen entstellt, in denen schlangenartige Bewohner die Pflanze bewachen. Viele von Zamah entsandte Späher kehrten nicht zurück. Nun sucht sie zähe Abenteurer, die mehr davon sammeln."}},faq={{q="Wer ist Apothekerin Zamah?",a="Apothekerin Zamah ist eine Forscherin und Gesandte der Königlichen Apothekervereinigung aus Unterstadt. Sie wacht über die Teiche der Visionen unter der Anhöhe der Geister in Donnerfels und verbindet die Alchemisten der Verlassenen mit dem übrigen Kalimdor.",al={"zamah","apothecary zamah hintergrund","wer vergibt schlangenflaum"}},{q="Warum will die Königliche Apothekervereinigung Schlangenflaum?",a="Zamah glaubt, dass Schlangenflaum chemisches Potenzial birgt, wenn er in großen Mengen veredelt wird. Die Vereinigung sucht in ganz Kalimdor nach seltenen, wirkungskräftigen Pflanzen, um die alchemistischen Experimente der Verlassenen zu unterstützen.",al={"warum schlangenflaum","kräuterforschung der verlassenen","zweck von schlangenflaum"}},{q="Wo wächst Schlangenflaum?",a="Schlangenflaum wächst in feuchten Höhlen unter dem nördlichen Brachland, in den felsigen Gängen und Passagen der Höhlen des Wehklagens.",al={"wo ist schlangenflaum","schlangenflaum fundort"}},{q="Warum sind frühere Späher nicht zurückgekehrt?",a="Die Höhlen des Wehklagens werden von zurückentwickelten Bestien, Raptoren und den verdorbenen Druiden des Giftzahns überrannt. Unerfahrene Sammler wurden in den gewundenen Tunneln rasch von Raubtieren und giftigen Verteidigern überwältigt.",al={"vermisste späher","zamahs späher","sind die höhlen des wehklagens gefährlich"}},{q="Billigen die Tauren Zamahs Forschung?",a="Die Tauren von Donnerfels gewährten den Verlassenen aus Mitgefühl und dem Wunsch, sie zu heilen, Zuflucht. Die Alchemie der Königlichen Apothekervereinigung kann an unnatürliche Experimente grenzen, was traditionelle Schamanen und Druiden beunruhigt.",al={"reaktion der tauren","apotheker auf der anhöhe der geister"}},{q="Braucht man Kräuterkundekenntnisse, um Schlangenflaum zu ernten?",a="Nein. Jeder Abenteurer, der sich in die Höhlen des Wehklagens wagt, kann Schlangenflaum ohne Ausbildung in Kräuterkunde vom Höhlenboden pflücken.",al={"ist kräuterkunde nötig","schlangenflaum sammeln beruf"}}},fx={["962715c8"]={q="Warum möchte Apothekerin Zamah, dass Schlangenflaum gesammelt wird?",a="Apothekerin Zamah wurde von der Königlichen Apothekervereinigung mit einem speziellen Auftrag nach Donnerfels entsandt, um die Interessen der Verlassenen und der Dunklen Fürstin, Fürstin Sylvanas Windläufer, zu fördern. Nachdem sie eine seltene Probe von Schlangenflaum analysiert hat, sieht Zamah ein enormes Potenzial in dessen Eigenschaften, wenn er in beträchtlichen Mengen beschafft wird. Die Sicherung von genügend Exemplaren ermöglicht es ihrer Forschung, die wissenschaftlichen und alchemistischen Ambitionen der Unterstadt voranzutreiben.",al={"apothecary zamah motiv","warum braucht zamah schlangenflaum","warum schlangenflaum sammeln"}},["92b49307"]={q="Warum schickt Apothekerin Zamah einen Abenteurer, anstatt Schlangenflaum selbst zu sammeln?",a="Zamah kann ihren Posten in Donnerfels nicht ohne Weiteres verlassen, und das Ernten des Krauts erfordert das Vordringen in die tückischen, verdorbenen Tiefen der Höhlen des Wehklagens. Sie hat bereits mehrere Späher und Agenten in ihr Höhlensystem entsandt, aber keiner von ihnen kehrte lebend zurück. Sie braucht erfahrene, fähige Abenteurer, die bereit sind, jenen dunklen Winkeln zu trotzen, an denen gewöhnliche Späher gescheitert sind.",al={"warum mich für schlangenflaum schicken","warum besorgt zamah den schlangenflaum nicht","warum abenteurer für schlangenflaum"}}},fp="12,168,22.387.0,25.307.0,24.232.0,56.188.0,29.123.0,37.206.0,42.221.0,54.126.0"}
P.entries["quest:96204"] = {n="The Windshaper's Wrath",s="Lumina Windsinger bittet Euch, ihr bei der Flucht aus Burg Fenris zu helfen. Eure Hilfe gibt ihr Grund, Paladinen zu vertrauen.",h="Lumina Windsinger bittet Euch, ihr bei der Flucht aus Burg Fenris zu helfen.",kw={"flucht","burg fenris","lumina windsinger","paladin","trevan","windformer"},ang={["class:Paladin"]="Lumina hat Unfreundliches über Euresgleichen als Paladine gehört, doch Eure Hilfe gibt ihr Anlass, Euch als Freund willkommen zu heißen."},sec={{t="Ein Weg hinaus",b="Lumina Windsinger ist innerhalb von Burg Fenris frei, doch sie will mit Euch fortgehen. Die Kreaturen, die sie gefangen hielten, sollen bereuen, sich mit einer Windformerin angelegt zu haben. Bleibt bei ihr, während sie flieht."},{t="Ein neuer Freund",b="In Burg Fenris erzählt Euch Lumina, dass sie Trevan getroffen und erfahren hat, dass er Euch geschickt hat, um sie zu finden. Sie hat Unfreundliches über Paladine gehört, doch Eure Hilfe hat ihre Ansicht geändert. Die Windformer zählen Euch und Euresgleichen zu ihren Freunden."}},faq={{q="Wer ist Lumina Windsinger?",a="Lumina Windsinger ist eine Windformerin, die in Burg Fenris gefangen gehalten wurde und Eure Hilfe bei der Flucht sucht.",al={"lumina","wer ist lumina","windsinger"}},{q="Von wo versucht Lumina zu fliehen?",a="Lumina Windsinger versucht, aus Burg Fenris zu fliehen.",al={"lumina flucht","burg fenris","lumina herausholen"}},{q="Wer hat mich geschickt, um Lumina zu finden?",a="Lumina sagt, Trevan habe Euch auf ihre Spur geschickt.",al={"wer hat mich geschickt","trevan","luminas spur"}},{q="Warum erwähnt Lumina Paladine?",a="Lumina hat Unfreundliches über Paladine gehört, sagt aber, dass sich diese Behauptungen nach Eurer Hilfe als unbegründet erwiesen haben.",al={"paladinsache","lumina paladine","vertraut sie paladinen"}},{q="Was hält Lumina von mir?",a="Lumina sagt, Ihr und Euresgleichen habt eine Freundin unter den Windformern.",al={"lumina mag mich","windformer freund","was sagt lumina"}}},fp="22,103,9.192.0,12.220.1,25.91.0,38.50.0,27.44.0,33.102.0,29.66.0"}
P.entries["quest:96222"] = {n="Khan Hratha",s="Umarak will den Maraudine Key Fragment von Khan Hratha als Druckmittel für Verhandlungen. Ihr sollt Hratha auf dem höchsten Gipfel im Tal der Speere herausfordern.",h="Umarak will den Maraudine Key Fragment von Khan Hratha als Druckmittel für Verhandlungen.",kw={"zentauren","desolace","schlüsselfragment","khan hratha","maraudine","umarak","das tal der speere","kriegshorn"},sec={{t="Umaraks Besorgnis",b="Der Krieg hält Desolace im Griff, doch die Maraudine-Zentauren bleiben im Tal der Speere unbehelligt. Umarak fürchtet, dass die Untätigkeit der anderen Clans sie kühner macht und weitere Unruhen auslöst. Er will das Fragment, das Khan Hratha bei sich trägt, als Verhandlungsmasse und bittet Euch, es zurückzubringen."}},faq={{q="Wer will den Maraudine Key Fragment?",a="Umarak will Khan Hrathas Maraudine Key Fragment als Druckmittel für Verhandlungen.",al={"wer will das schlüsselfragment","umarak fragment"}},{q="Wo sind die Maraudine-Zentauren?",a="Die Maraudine-Zentauren bleiben im Tal der Speere in Desolace unbehelligt.",al={"wo sind die maraudine","zentauren tal"}},{q="Warum will Umarak das Fragment?",a="Umarak will den Maraudine Key Fragment als Druckmittel für Verhandlungen.",al={"warum schlüsselfragment","wofür ist es"}},{q="Wovor fürchtet sich Umarak?",a="Umarak fürchtet, dass die Maraudine dreister werden und weitere Unruhen auslösen könnten, wenn die anderen Clans ihre Anwesenheit weiter ignorieren.",al={"warum sorgen wegen der maraudine","welche unruhen"}},{q="Was trägt Khan Hratha bei sich?",a="Khan Hratha besitzt einen Maraudine Key Fragment.",al={"hrathas gegenstand","was hat khan bei sich"}},{q="Was bittet Umarak Euch zurückzubringen?",a="Umarak bittet Euch, ihm den Maraudine Key Fragment zu bringen.",al={"was soll umarak gebracht werden","fragmentanfrage"}}},fp="11,164,18.276.0,45.76.0,32.78.0,34.70.0,22.116.0,29.47.0,39.56.0"}
P.entries["quest:96241"] = {n="Talkin' bout Toxins, Mon",s="Mazu'kon möchte, dass Ihr Giftproben von den Gnawed Corpses auf der Düsteranhöhe sammelt. Die seltsamen Giftstoffe haben seine Neugier geweckt.",h="Mazu'kon möchte, dass Ihr Giftproben von den Gnawed Corpses auf der Düsteranhöhe sammelt.",kw={"extraktor","düsteranhöhe","düsteranhöhe giftproben","gnawed corpses","mazu'kon","toxin","gift"},sec={{t="Auf der Düsteranhöhe",b="Mazu'kon hat von seltsamen neuen Kreaturen gehört, die auf der Düsteranhöhe umherkriechen. Ihr Gift könnte ungewöhnliche Eigenschaften haben, weshalb er Euch bittet, mit seinem Extraktor Proben von den Gnawed Corpses zu sammeln. Er möchte herausfinden, was dieses Gift anders macht."},{t="Die Proben",b="Mazu'kon dankt Euch dafür, dass Ihr die Giftproben von der Düsteranhöhe gebracht habt. Er sagt, die ungewöhnlichen Eigenschaften des Gifts seien kein Scherz gewesen, und stellt fest, dass Ihr unversehrt zu sein scheint."}},faq={{q="Wer bittet um die Toxinproben?",a="Mazu'kon bittet Euch, Giftproben von den Gnawed Corpses auf der Düsteranhöhe zu sammeln.",al={"wer will toxine","mazu'kon toxin"}},{q="Warum möchte Mazu'kon das Gift haben?",a="Er hat gehört, dass das Gift der Kreaturen ungewöhnliche Eigenschaften haben könnte, und das hat seine Neugier geweckt.",al={"warum toxine","worauf ist er neugierig"}},{q="Wo bekomme ich die Proben?",a="Die Proben stammen von den Gnawed Corpses auf der Düsteranhöhe.",al={"toxinproben wo","düsteranhöhe leichen"}},{q="Was gibt Euch Mazu'kon?",a="Mazu'kon gibt Euch einen Extraktor, um das Gift zu sammeln.",al={"extraktor","wie toxin sammeln"}},{q="Wie viele Toxinproben braucht er?",a="Mazu'kon bittet um fünf Gloomrise Toxin Samples.",al={"probenanzahl","wie viele toxine"}}},fp="24,127,12.244.0,11.153.1,36.80.0,33.91.0,27.50.0,28.52.0,36.47.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Im Coldridgetal schickt Call of Earth einen Initianden zu Teo Hammerstorm nach Ambossar. Dort beginnt die Zwiesprache eines Schamanen mit den Geistern des Steins.",h="Im Coldridgetal schickt Call of Earth einen Initianden zu Teo Hammerstorm nach Ambossar.",kw={"ambossar","call of earth","das coldridgetal","dun morogh","erdtotem","elemente","schamane","teo hammerstorm"},ang={["class:Shaman"]="Als Schamane beginnt Euer Weg damit, dem Ruf der Erde zu folgen, der Euch an tiefes Gestein und die standhaften Geister des Landes bindet.",["faction:Alliance"]="Als Schamane der Allianz in Dun Morogh beginnt Ihr Eure Reise mit den Elementen in Ambossar, der altehrwürdigen Zwergenfeste.",["race:Dwarf"]="Als Zwerg kann Eure Verbindung zu Stein und Erde die Zwiesprache mit diesen Geistern in den tiefen Gewölben von Dun Morogh natürlich erscheinen lassen."},sec={{t="Die Stimme des Steins",b="Die erste Zwiesprache eines Initianden mit den Elementen beginnt, wenn die Erde ruft. Andere elementare Energien mögen sich bereits regen, doch das Gespräch mit dem Stein bringt Gleichgewicht. Die Erde lehrt den Initianden, eine Kraft zu finden, die nicht nachgibt. Fester Halt entsteht unter seinen Stiefeln und in seinem Geist."},{t="Die Feste Ambossar",b="In den verschneiten Weiten von Dun Morogh finden Initianden in Ambossar Schutz und Unterweisung. Die Feste liegt im Coldridgetal, geschmiedet durch Hammer, Feuer und Willenskraft. Teo Hammerstorm wartet im Inneren und lehrt angehende Schamanen, auf die grollende Erde zu hören und ihre elementaren Pflichten aufzunehmen."}},faq={{q="Was ist Call of Earth?",a="Call of Earth ruft einen angehenden Schamanen dazu auf, die Zwiesprache mit den Erdgeistern zu beginnen. Die Aufforderung weist den Initianden an, Führung zu suchen und in der Kraft des lebendigen Steins Halt zu finden.",al={"was ist call of earth","call of earth quest","was ist diese quest"}},{q="Wer ist Teo Hammerstorm?",a="Teo Hammerstorm unterweist Initianden in Ambossar, der Zwergenfeste im Coldridgetal. Er leitet sie dabei an, Zwiesprache mit der Erde zu halten und ihre beständige Kraft kennenzulernen.",al={"wer ist teo hammerstorm","wo ist teo hammerstorm","teo hammerstorm standort"}},{q="Was ist Ambossar?",a="Ambossar ist eine Zwergenfeste im Coldridgetal, in den verschneiten Weiten von Dun Morogh. Geschmiedet durch Hammer, Feuer und Willenskraft, ist sie ein Bollwerk, in dem junge Helden ausgebildet werden.",al={"wo ist ambossar","was ist ambossar","ambossar standort"}},{q="Warum muss ein Schamane dem Ruf der Erde folgen?",a="Ein Schamane folgt dem Ruf der Erde, um seinen Geist zu erden und festen Halt unter seinen Sohlen zu finden. Die Zwiesprache mit dem Stein macht dessen beständige Kraft zugänglich.",al={"warum mit der erde sprechen","zweck von call of earth","verbindung zwischen schamane und erde"}},{q="Wer folgt dieser Aufforderung?",a="Die Aufforderung richtet sich an Schamanen, die ihren Weg in Dun Morogh beginnen. Sie weist ihnen den Weg zu erfahrenen Lehrern der Elemente, die ihre Verbindung zu den Geistern lenken können.",al={"wer erteilt call of earth","wer nimmt call of earth an","wer macht diese quest"}},{q="Wohin führt diese Quest?",a="Die Reise führt nach Ambossar im Coldridgetal, im verschneiten Dun Morogh. Initianden betreten die Feste, um ihren Mentor zu finden.",al={"wo findet call of earth statt","call of earth gebiet","wohin gehen"}}},fp="13,156,18.294.0,24.275.0,22.177.0,23.171.0,17.163.0,41.157.0,28.155.0,27.130.0"}
P.entries["quest:96259"] = {n="Defending the Dead",s="Bei Gloomrise bedrohen Spinnen die Bewohner Mulg ores und eine uralte Begräbnisstätte der Tauren. Ihr werdet gebeten, den Befall einzudämmen.",h="Bei Gloomrise bedrohen Spinnen die Bewohner Mulg ores und eine uralte Begräbnisstätte der Tauren.",kw={"defending the dead","gloomrise","jungtiere","mulgore","soldaten","spinnen","begräbnisstätte der tauren"},ang={["race:Tauren"]="Für Euch als Tauren ist Gloomrise eine bedeutende uralte Begräbnisstätte, die vielen Eures Volkes heilig ist."},sec={{t="Die Begräbnisstätte",b="Ein Lager bittet Euch, Gloomrise zu schützen, eine uralte Begräbnisstätte der Tauren nordwestlich des Lagers. Bösartige Spinnen haben den Ort befallen, bedrohen die Bewohner Mulg ores und beschädigen eine Stätte, die vielen Tauren heilig ist."},{t="Ein erster Stützpunkt",b="Eure Bemühungen helfen den Bewohnern Mulg ores, einen Stützpunkt gegen die Spinnen zu errichten. Den Befall vollständig zu beseitigen, könnte Zeit brauchen, weshalb die Begräbnisstätte weiterhin gefährdet ist."}},faq={{q="Was ist Gloomrise?",a="Gloomrise ist eine uralte Begräbnisstätte der Tauren nordwestlich des Lagers.",al={"gloomrise begräbnisstätte","wo ist gloomrise"}},{q="Warum ist Gloomrise in Gefahr?",a="Bösartige Spinnen haben Gloomrise befallen, bedrohen die Bewohner Mulg ores und beschädigen die heilige Begräbnisstätte.",al={"spinnen bei gloomrise","warum die toten verteidigen"}},{q="Warum ist die Begräbnisstätte heilig?",a="Viele Tauren betrachten Gloomrise als heilig.",al={"heilige stätte der tauren","warum begräbnisstätte der tauren"}},{q="Wer bittet um Hilfe?",a="Ein Lager bittet Euch, Gloomrise vor dem Spinnenbefall zu schützen.",al={"wer braucht hilfe","wer hat das gegeben"}},{q="Wurde der Befall beseitigt?",a="Nein. Eure Bemühungen schaffen einen Stützpunkt, doch den Befall vollständig zu beseitigen, könnte Zeit brauchen.",al={"sind die spinnen weg","gloomrise befall"}}},fp="18,133,17.202.0,10.170.1,18.67.0,27.103.0,32.38.0,18.70.0,33.90.0"}
P.entries["quest:96260"] = {n="Stronger than Steel",s="Auf der Düsteranhöhe sucht ein Forscher kristalline Seide von den sich ausbreitenden Riesenspinnen. Aus der Seide könnte ein leichter Stoff entstehen, der starken Schutz bietet.",h="Auf der Düsteranhöhe sucht ein Forscher kristalline Seide von den sich ausbreitenden Riesenspinnen.",kw={"umhang","stoff","kristalline seide","düsteranhöhe","spinnen","stärker als stahl","gift"},sec={{t="Seide für die Forschung",b="Ein Forscher bittet Euch um mehr kristalline Seide, nachdem ein Späher von der Düsteranhöhe zurückkehrte und über und über damit bedeckt war. Riesenspinnen haben sich auf dem Gräberfeld ausgebreitet, und ihr Gift soll die Toten erwecken. Die Widerstandsfähigkeit der Seide könnte sie für Stoff mit schützenden Eigenschaften nützlich machen."},{t="Ein neues Gewebe",b="Die Proben reichen für die Bedürfnisse des Forschers aus. Euch wird ein Umhang aus bereits vorhandener Seide angeboten, in der Hoffnung, dass er Euch auf Euren Reisen hilft."}},faq={{q="Was möchte der Forscher?",a="Der Forscher möchte mehr kristalline Seide von den Spinnen der Düsteranhöhe, um sie zu untersuchen.",al={"seidenproben","kristalline seide","welche seide"}},{q="Wo findet man die Seide?",a="Die kristalline Seide stammt von Riesenspinnen auf der Düsteranhöhe.",al={"wo seide","düsteranhöhe seide","spinnenseide fundort"}},{q="Warum wird die Seide untersucht?",a="Aus der Seide könnte leichter, strapazierfähiger Stoff mit schützenden Eigenschaften hergestellt werden.",al={"seide verwendung","was kann seide","warum seide"}},{q="Was erzählt man sich über das Gift der Spinnen?",a="Das Gift der Spinnen soll stark genug sein, um die Toten zu erwecken.",al={"spinnengift","tote erwecken","gift gerücht"}},{q="Was brachte der Späher mit zurück?",a="Ein Späher kehrte von der Erkundung der Düsteranhöhe zurück und war über und über mit widerstandsfähiger, kristalliner Spinnenseide bedeckt.",al={"späherbericht","späher seide","was geschah dem späher"}}},fp="19,138,14.273.0,11.152.1,30.80.0,24.59.0,19.79.0,41.67.0,30.94.0"}
P.entries["quest:96261"] = {n="The Broodmother",s="Auf der Düsteranhöhe bittet Euch der Irdene Ring, die Spinnenplage aufzuhalten, indem Ihr Euch ihrer Brutmutter stellt. Die Bedrohung gefährdet die Bewohner Mulg ores.",h="Auf der Düsteranhöhe bittet Euch der Irdene Ring, die Spinnenplage aufzuhalten, indem Ihr Euch ihrer...",kw={"brutmutter","der irdene ring","düsteranhöhe","plage","mulgore","nachtelfische gestalt","spinnen","valraxx"},sec={{t="Das Nest der Düsteranhöhe",b="Der Irdene Ring glaubt, dass eine mächtige Matriarchin die Spinnenplage auf der Düsteranhöhe vorantreibt. Ihr sollt Broodmother Valraxx aufspüren und vernichten. Die Spinnen scheinen keine gewöhnlichen Spinnen zu sein, also warnt Euch der Ring, auf alles gefasst zu sein."},{t="Beunruhigende Zeichen",b="Danach berichtet der Irdene Ring von wiederbelebten Toten und einer Brutmutter mit nachtelfischer Gestalt. Diese Entdeckungen beunruhigen seine Mitglieder, doch sie lassen die Frage nach deren Bedeutung vorerst ruhen. Sie danken Euch, dass Ihr dem Ring und den Bewohnern Mulg ores geholfen habt."}},faq={{q="Was geschieht auf der Düsteranhöhe?",a="Auf der Düsteranhöhe breitet sich eine Spinnenplage aus, und der Irdene Ring glaubt, dass eine mächtige Matriarchin sie anführt.",al={"düsteranhöhe spinnen","spinnenplage","was ist auf der düsteranhöhe"}},{q="Wer ist Broodmother Valraxx?",a="Broodmother Valraxx ist die Brutmutter auf der Düsteranhöhe, die Ihr im Auftrag des Irdenen Rings vernichten sollt.",al={"valraxx","brutmutter","spinnenmatriarchin"}},{q="Warum will der Irdene Ring die Brutmutter beseitigen?",a="Der Ring glaubt, dass die Brutmutter die Ausbreitung der feindseligen Spinnen vorantreibt.",al={"warum brutmutter töten","warum valraxx","spinnen aufhalten"}},{q="Wo ist die Brutmutter?",a="Broodmother Valraxx befindet sich auf der Düsteranhöhe.",al={"valraxx aufenthaltsort","wo ist die brutmutter","wo liegt die düsteranhöhe"}},{q="Was sagt der Irdene Ring über diese Spinnen?",a="Der Irdene Ring sagt, dass dies keine gewöhnlichen Spinnen zu sein scheinen.",al={"seltsame spinnen","gewöhnliche spinnen","spinnen seltsam"}}},fp="15,149,18.247.0,15.238.1,31.113.0,27.94.0,52.85.0,25.36.0,51.59.0"}
P.entries["quest:96264"] = {n="Elemental Aid",s="Ein Schamane soll die Versammlung der Stacheleber im Kral der Klingenhauer untersuchen. Die Erde warnt vor einem Ritual, und die Elemente brauchen Hilfe gegen jene, die ihre Macht missbrauchen.",h="Ein Schamane soll die Versammlung der Stacheleber im Kral der Klingenhauer untersuchen.",kw={"charlga klingenflanke","erde","elementare hilfe","elemente","stacheleber","kral der klingenhauer","ritual","schamane"},ang={["class:Shaman"]="Als Schamane beherrscht Ihr die Elemente, und diese Bitte fordert Euch auf, ihre Hilfe zu erwidern."},sec={{t="Die Warnung der Erde",b="Die Erde überbringt einem Schamanen eine Warnung: Die Stacheleber versammeln sich im Kral der Klingenhauer zu einem Ritual von schrecklicher Macht. Eure Aufgabe ist es, ihren Kral zu erkunden und mit Informationen über ihre Pläne zurückzukehren. Die Elemente gewähren Euch ihre Hilfe, und nun brauchen sie Eure."}},faq={{q="Wovor warnt die Erde?",a="Die Erde warnt davor, dass die Stacheleber sich für ein Ritual von schrecklicher Macht versammeln.",al={"warnung der erde","was grollt","ritual der stacheleber"}},{q="Wo versammeln sich die Stacheleber?",a="Die Stacheleber versammeln sich im Kral der Klingenhauer.",al={"wo nachforschen","aufenthaltsort der stacheleber","lage des krals"}},{q="Warum muss der Schamane den Elementen helfen?",a="Die Elemente helfen dem Schamanen, und er soll diese Hilfe erwidern, indem er ihnen gegen jene beisteht, die ihre Macht missbrauchen.",al={"den elementen helfen","elemental aid grund","warum den elementen helfen"}},{q="Welche Informationen werden benötigt?",a="Ihr sollt den Kral der Klingenhauer untersuchen und Informationen über die Pläne der Stacheleber zurückbringen.",al={"was finden","pläne der stacheleber","benötigte informationen"}},{q="Von wem stammt die Bitte?",a="Die Bitte stammt von jemandem, der Euch als Schamanen anspricht und sagt, dass die Elemente Hilfe brauchen.",al={"wer bittet","questgeber","wer braucht hilfe"}}},fp="13,166,21.259.0,31.79.0,33.45.0,46.124.0,27.95.0,22.88.0"}
P.entries["quest:96294"] = {n="A Darker Truth",s="Muln Earthfury bittet Euch, ihm einen auf der Düsteranhöhe gefundenen Brief zu bringen. Er könnte Aufschluss über die dortigen Spinnen geben.",h="Muln Earthfury bittet Euch, ihm einen auf der Düsteranhöhe gefundenen Brief zu bringen.",kw={"a darker truth","broodmother valraxx","zirkel des cenarius","düsteranhöhe","muln earthfury","nachtelfendruide","pact","himmelsschauerplateau","spinnen","wild king"},sec={{t="Ein Brief auf der Düsteranhöhe",b="Auf der Düsteranhöhe habt Ihr herausgefunden, dass die Broodmother eine Nachtelfendruidin in einer entstellten Tiergestalt war. Fragen über die Spinnen und ihren Zweck bleiben offen. Eine Notiz aus ihrer Robe könnte Antworten enthalten, also bringt Ihr sie zu Muln Earthfury auf dem Himmelsschauerplateau."},{t="Mulns Sorge",b="Muln Earthfury findet den Brief beunruhigend. Er spricht von einem „Wild King“ und einem „Pact“, doch Muln weiß nicht, wer oder was sie sind. Er will den Zirkel des Cenarius zu Rate ziehen, findet aber Trost darin, dass diejenige, die die Spinnen kontrollierte, verschwunden ist."}},faq={{q="Wer war die Broodmother?",a="Die Broodmother war eine Nachtelfendruidin, die eine entstellte Tiergestalt angenommen hatte.",al={"broodmother identität","wer ist valraxx","spinne elfe?"}},{q="Was bringe ich Muln Earthfury?",a="Ihr bringt Muln Earthfury den Brief, der aus der Robe von Broodmother Valraxx geborgen wurde.",al={"welcher brief","muln brief","was bringen?"}},{q="Wohin bringe ich den Brief?",a="Ihr bringt den Brief zu Muln Earthfury auf dem Himmelsschauerplateau.",al={"muln aufenthaltsort","wo ist das himmelsschauerplateau","brief ziel"}},{q="Was hält Muln von dem Brief?",a="Muln findet ihn beunruhigend und fragt sich, was die Erwähnungen eines „Wild King“ und eines „Pact“ bedeuten.",al={"mulns reaktion","warum beunruhigend","was steht im brief"}},{q="Wen wird Muln zu Rate ziehen?",a="Muln will mit den Druiden des Zirkels des Cenarius sprechen.",al={"zirkel des cenarius brief","wen wird er fragen","druidenrat?"}}},fp="14,109,21.247.0,14.246.1,24.74.0,34.78.0,27.60.0,34.96.0,22.59.0"}
P.entries["quest:963"] = {n="In ewiger Liebe",s="In Auberdine bittet Cerellean Weißklaue Euch, Anaya Dawnrunners Qualen in Ameth'Aran zu lindern. Seine Trauer währt seit dem Fall der Stadt.",h="In Auberdine bittet Cerellean Weißklaue Euch, Anaya Dawnrunners Qualen in Ameth'Aran zu lindern.",kw={"ameth'aran","anaya dawnrunner","anayas anhänger","auberdine","cerellean weißklaue","dunkelküste","in ewiger liebe","sundering"},ang={["class:Druid"]="Als Druide seht Ihr, welchen persönlichen Preis jene zahlten, die Jahrtausende an der Seite von Shan'do Sturmgrimm schliefen. Cerellean erwachte in einer Welt, die noch immer von uralten Verlusten gezeichnet war.",["faction:Alliance"]="Als Held der Allianz seht Ihr, wie Eure nachtelfischen Verbündeten ihre Trauer über Jahrtausende hinweg tragen, während sie sich an die wache Welt gewöhnen.",["race:NightElf"]="Als Nachtelf der Dunkelküste seht Ihr in Cerelleans Geschichte die bleibenden Narben des Great Sundering und des Falls Eurer uralten Städte."},sec={{t="Ein Schlummer voller Trauer",b="Vor zehntausend Jahren riss der Krieg der Ahnen Kalimdor rund um den Brunnen der Ewigkeit auseinander. Ameth'Aran fiel, und Anaya Dawnrunner ging Cerellean Weißklaue verloren. Von Trauer überwältigt, schloss sich Cerellean Shan'do Malfurion Sturmgrimm im langen Winterschlaf der Druiden an. Er hoffte, die Zeitalter im Smaragdgrünen Traum würden sein Herz beruhigen, doch seine Trauer blieb."},{t="Der Geist von Ameth'Aran",b="Als er erwachte, wanderte Cerellean wie betäubt durch die Dunkelküste. Schließlich gelangte er zu den schwermütigen Ruinen von Ameth'Aran, wo er Anayas gequälten Geist sah. Er kann keine Waffe gegen die Frau erheben, die er liebte. Deshalb bittet er vorbeiziehende Reisende, ihre gepeinigte Gestalt zu vernichten, ihren Anhänger zu bergen und ihrer ruhelosen Seele Frieden zu bringen."},{t="Abschied jenseits des Schleiers",b="Als Anayas Anhänger Auberdine erreicht, erscheint ihr geisterhafter Überrest ein letztes Mal vor Cerellean. Befreit von der Pein, die sie an die Ruinen band, verabschiedet sich Anaya kurz von ihm und verblasst. Am Meer weint der trauernde Druide, findet jedoch bittersüßen Trost."}},faq={{q="Wer ist Cerellean Weißklaue?",a="Cerellean Weißklaue ist ein Nachtelfendruide, der in Auberdine ruht. Nachdem er Anaya vor zehntausend Jahren beim Sundering verloren hatte, begab er sich mit Shan'do Malfurion Sturmgrimm in den langen Winterschlaf der Druiden. Seine Trauer überdauerte die Zeitalter.",al={"cerellean weißklaue","wer vergibt in ewiger liebe","cerelleans geschichte"}},{q="Wer war Anaya Dawnrunner?",a="Anaya Dawnrunner war eine Nachtelfe, die vor dem Great Sundering in Ameth'Aran lebte. Sie starb, als die Stadt nach dem Krieg der Ahnen fiel. Ihr Geist bleibt in den Ruinen gefangen.",al={"anaya dawnrunner","wer ist anaya","anaya dunkelküste"}},{q="Wo befindet sich Anayas Geist?",a="Anayas Geist wandert durch die uralten, von Geistern heimgesuchten Ruinen von Ameth'Aran im Süden der Dunkelküste, östlich der Hauptstraße.",al={"anayas standort","wo ist anaya dawnrunner","anayas anhänger fundort"}},{q="Warum konnte Cerellean Anaya nicht selbst befreien?",a="Cerellean erträgt es nicht, seine Hand gegen Anayas Erscheinung zu erheben oder einen Zauber gegen sie zu wirken. Zehntausend Jahre sind vergangen, doch er kann sie nicht angreifen, während sie leidet.",al={"warum tötet cerellean anaya nicht","warum bittet cerellean um hilfe"}},{q="Was geschah mit Ameth'Aran?",a="Ameth'Aran war eine uralte Siedlung der Nachtelfen, die beim Sundering nach dem Krieg der Ahnen zerstört wurde. In ihren Ruinen an der Dunkelküste verweilen noch immer Geister und arkane Echos.",al={"ameth'arans geschichte","fall von ameth'aran","was ist ameth'aran"}},{q="Was geschieht, wenn Ihr Anayas Anhänger zurückbringt?",a="Ihr bringt Anayas Anhänger zu Cerellean in Auberdine, nachdem Ihr ihren ruhelosen Geist befreit habt. Was darauf folgt, offenbart sich bei Eurer Rückkehr.",al={"anaya quest abgeben","cerelleans ende","in ewiger liebe ende"}}},fx={dc23d6a3={q="Warum möchte Cerellean Weißklaue Anayas Geist befreit wissen?",a="Cerellean glaubte, seine Liebe, Anaya, sei vor Jahrtausenden umgekommen, als Ameth'Aran während des Großen Bruchs zerstört wurde. Die Entdeckung ihres ruhelosen, gequälten Geistes, der durch die Ruinen wandert, brach ihm das Herz. Da er weiß, dass sie an dieses Reich gebunden leidet, erträgt er den Gedanken nicht, dass sie in Qual bleibt, doch er bringt es nicht über sich, selbst Hand an sie zu legen.",al={"warum möchte cerellean das erledigt haben","cerellean motiv","warum anayas geist vernichten"}},ed60ea9d={q="Wozu dient Anayas Anhänger?",a="Anayas Anhänger ist das Andenken, das Cerellean Euch bittet zurückzubringen, nachdem Ihr ihren gequälten Geist in Ameth'Aran befreit habt.",al={"verwendung von anayas anhänger","was bewirkt anayas anhänger","zweck von anayas anhänger"}}},fp="16,134,23.358.0,23.321.0,23.274.1,27.233.0,25.183.0,32.116.0,42.162.0,28.184.0,45.128.1"}
P.entries["quest:96332"] = {n="A Little Payback",s="Sergeant Ulka bittet Euch, Euch an den Naga in Alcaz Prison zu rächen. Beim Rückzug fielen Kor'kron-Kämpfer, und Ulka will, dass die Naga dafür bezahlen.",h="Sergeant Ulka bittet Euch, Euch an den Naga in Alcaz Prison zu rächen.",kw={"ein wenig vergeltung","alcaz prison","kor'kron","naga","sergeant ulka","strashasz soldiers","strashaz enchantresses","tidemistress ca'zass"},sec={{t="Ulkas Forderung",b="Die Kor'kron zogen sich zurück, als eine weitere Welle Naga sich Alcaz Prison näherte. Sergeant Ulka glaubt, dass die Kämpfe im Inneren weitergehen. Ihr sollt die Naga töten, denen Ihr begegnet, auch die Zauberin, die Ulka für ihre Anführerin hält. Die Kor'kron verloren viele Orcs, und Ulka will Gleiches mit Gleichem vergelten."}},faq={{q="Wer will Vergeltung?",a="Sergeant Ulka, eine Kor'kron, bittet Euch, die Naga in Alcaz Prison zu töten.",al={"wer will vergeltung","sergeant ulka","ulkas bitte"}},{q="Warum will Ulka die Naga töten lassen?",a="Die Kor'kron verloren beim Rückzug vor einer zweiten Welle Naga viele Orcs, und Ulka will Gleiches mit Gleichem vergelten.",al={"warum naga töten","vergeltung an den naga","warum ulka rache will"}},{q="Wo wird gekämpft?",a="Sergeant Ulka vermutet, dass die Schlacht in Alcaz Prison noch immer tobt.",al={"wo sind die naga","kampf in alcaz prison","naga im bergfried"}},{q="Wer führt laut Ulka die Naga an?",a="Ulka sah eine Zauberin unter den Naga und vermutet, dass sie ihre Anführerin ist.",al={"anführer der naga","zauberin als anführerin","wer führt sie an"}},{q="Was soll ich zurückbringen?",a="Ulka bittet Euch, den Kopf von Tidemistress Ca'zass zurückzubringen.",al={"was zurückbringen","kopf der tidemistress","ulkas gewünschte gegenstände"}}},fp="16,149,13.292.0,26.69.0,35.113.0,22.70.0,35.69.0,36.61.0"}
P.entries["quest:96334"] = {n="Blood Red Bandanas",s="Ihr werdet losgeschickt, um die roten Masken der menschlichen Wachen im Alcaz Prison zu Etrigg zu bringen, der sie identifizieren kann. Ihre Zeichen könnten eine Verbindung zwischen dem Gefängnis und der Bruderschaft der Defias herstellen.",h="Ihr werdet losgeschickt, um die roten Masken der menschlichen Wachen im Alcaz Prison zu Etrigg zu bringen...",kw={"alcaz prison","blutrote bandanas","bruderschaft der defias","etrigg","menschliche wachen","orgrimmar","rote masken"},sec={{t="Eine Frage an Etrigg",b="Etrigg kann in Orgrimmar feststellen, ob die menschlichen Wachen im Alcaz Prison Masken der Defias tragen. Die Bruderschaft der Defias ist für ihre roten Masken bekannt, doch niemand weiß, warum ihre Mitglieder in Kalimdor aktiv sind. Ihr bringt ihm die Bandanas, damit er ihre Zeichen beurteilen kann."},{t="Etriggs Erkenntnis",b="Die Bandanas lassen Etrigg keinen Zweifel: Es sind Masken der Bruderschaft der Defias. Er sagt, dies bestätige ihren Verdacht, dass die Bruderschaft das Gefängnis betreibt, und er werde Thrall informieren."}},faq={{q="Wer bittet mich, die Bandanas zu bringen?",a="Eine Person, die bei Alcaz gekämpft hat, schickt Euch, um die roten Masken zu Etrigg nach Orgrimmar zu bringen, damit er sie identifizieren kann.",al={"wer will bandanas","etrigg bandanas"}},{q="Woher stammen die roten Bandanas?",a="Die menschlichen Wachen im Alcaz Prison tragen die blutroten Bandanas.",al={"bandana herkunft","wo bandanas"}},{q="Warum will Etrigg die Masken?",a="Etrigg möchte herausfinden, ob die roten Bandanas Masken der Bruderschaft der Defias sind.",al={"warum masken","wozu bandanas"}},{q="Wofür ist die Bruderschaft der Defias bekannt?",a="Die Bruderschaft der Defias ist für ihre roten Masken bekannt.",al={"was sind die defias","defias masken"}},{q="Warum sind die Defias auf Kalimdor?",a="Noch weiß es niemand. Die Person, die Euch schickt, hat nur von der Bruderschaft der Defias in den Östlichen Königreichen gehört.",al={"defias auf kalimdor","warum defias hier"}}},fp="18,176,22.261.0,17.185.1,34.115.0,32.61.0,32.88.0,41.50.0,31.105.0"}
P.entries["quest:96335"] = {n="The Man in the Iron Chains",s="Ein Mann in Alcaz Prison bittet Euch, The Questioner den Schlüssel zu seinen Fesseln abzunehmen. Für seine Freiheit verspricht er Euch eine Belohnung.",h="Ein Mann in Alcaz Prison bittet Euch, The Questioner den Schlüssel zu seinen Fesseln abzunehmen.",kw={"alcaz prison","alcaz shackle key","drache","gefangener","fesseln","the questioner"},sec={{t="In Alcaz Prison",b="Ein Gefangener in Alcaz Prison lobt Euch dafür, dass Ihr einen Drachen besiegt habt, und bittet Euch dann, ihn von seiner Kugel und Kette zu befreien. The Questioner könnte den Schlüssel noch haben, falls er nicht geflohen oder getötet worden ist. Die Freiheit des Gefangenen hängt von diesem Schlüssel ab."},{t="Nach den Fesseln",b="Als die Fesseln ab sind, sagt der Mann, er wolle ein Gasthaus, eine Dusche, eine Rasur und einen Anzug. Er überlegt auch, sich die Haare schneiden zu lassen."}},faq={{q="Wer bittet um Hilfe?",a="Ein Mann in Alcaz Prison bittet Euch, ihn von seinen Fesseln zu befreien.",al={"wer ist angekettet","gefangener in alcaz"}},{q="Wo ist der Gefangene?",a="Der Mann wird in Alcaz Prison festgehalten.",al={"wo ist der angekettete mann","alcaz gefangener"}},{q="Wer hat den Schlüssel?",a="The Questioner sollte den Alcaz Shackle Key haben, falls er nicht geflohen oder getötet worden ist.",al={"schlüsselinhaber","wer hat den fesselschlüssel"}},{q="Welchen Schlüssel braucht er?",a="Er braucht den Alcaz Shackle Key, um befreit zu werden.",al={"alcaz schlüssel","fesselschlüssel"}}},fp="26,122,15.226.0,18.119.1,23.66.0,22.32.0,16.83.0,22.43.0"}
P.entries["quest:96337"] = {n="More Valuable Than Gold",s="Mason Connery gibt Euch nach seiner Befreiung eine Notiz, die zu einem verborgenen Schatz führen soll. Er sagt, er könnte mehr wert sein als Gold.",h="Mason Connery gibt Euch nach seiner Befreiung eine Notiz, die zu einem verborgenen Schatz führen soll.",kw={"truhe","dokumente","verborgener schatz","kalidar","kalimdor","lordaeron","karten","mason connery","notiz","vermessungsbericht"},sec={{t="Ein verborgenes Versteck",b="Nachdem Ihr Mason Connery befreit habt, gibt er Euch eine Notiz und sagt, sie könne Euch zu einem Schatz führen. Gold hat er nicht anzubieten, bittet Euch aber, zu sagen, er sei gestorben, falls jemand nach der Herkunft der Notiz fragt. Mit ihrer Hilfe findet Ihr eine kleine Truhe, die in einem flachen Erdloch vergraben liegt. Darin befinden sich Dokumente, Karten und amtlich wirkende Siegel, doch das meiste ergibt für Euch kaum einen Sinn."},{t="Seltsame Papiere",b="Unter den Papieren befinden sich Abzeichen aus Sturmwind, Gilneas, Lordaeron und unbekannten Herrschaftsgebieten. Eine Karte nennt einen Ort namens Kalidar, während ein verschwommenes Gemälde offenbar eine Ogerin zeigt. Ein teilweise verbrannter Vermessungsbericht trägt die Beschriftung „A. Crater; Kalimdor.“ Dennoch vermutet Ihr, dass die Papiere jemandem etwas wert sein könnten."}},faq={{q="Was gibt Mason mir?",a="Mason Connery gibt Euch eine Notiz, die Euch helfen soll, seinen verborgenen Schatz zu finden.",al={"notiz von mason","was hat connery mir gegeben"}},{q="Wo ist der Schatz?",a="Ihr findet die Schatztruhe in einem flachen Erdloch vergraben.",al={"fundort von masons schatz","wo ist die truhe"}},{q="Was ist in der Truhe?",a="In der Truhe befinden sich Dokumente, Karten und amtlich wirkende Siegel.",al={"truhe inhalt","was ist in masons truhe"}},{q="Warum sagt Mason, ich soll anderen erzählen, er sei gestorben?",a="Mason bittet Euch zu sagen, die Person, die Euch die Notiz gab, sei gestorben, von Drachenfeuer vaporisiert und aufs Meer hinausgeweht worden.",al={"masons todesgeschichte","warum sagen, er sei gestorben"}}},fp="23,125,14.337.0,14.332.1,24.74.0,22.67.0,20.60.0,42.106.0"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Eisenschmiede Air Rifle",s="Ein an Euch adressiertes Paket wartete bei einem Verwalter, bis Ihr kamt, um es abzuholen. Darin lag eine Replik des Eisenschmiede-Luftgewehrs, hinterlassen von einem Boten, dessen Name unbekannt ist.",h="Ein an Euch adressiertes Paket wartete bei einem Verwalter, bis Ihr kamt, um es abzuholen.",kw={"luftgewehr","eisenschmiede","luftgewehr aus eisenschmiede","vermächtnisbelohnung","geheimnisvolles paket","replik des ironforge-luftgewehrs"},ang={["profession:Engineering"]="Tüftler und Büchsenmacher dürften das aufwendig gearbeitete Schusswaffenmodell zu schätzen wissen. Ein gleichgültiger Bote brachte es, und beinahe wäre es auf dem Meeresgrund gelandet.",["race:Dwarf"]="Das Paket enthält die Replik eines Luftgewehrs aus Eisenschmiede, die den berühmten Schusswaffen und der mechanischen Handwerkskunst von Khaz Modan Ehre erweist."},sec={{t="Ein Paket wartet auf Abholung",b="Der Verwalter lagerte nichts ein und wollte das Paket nicht aufbewahren. Der Bote bestand darauf, dass Ihr es abholen würdet, und eilte davon, bevor der Verwalter ablehnen konnte. Ihr traft kurz bevor die Kiste mit dem Unrat des Abends ins Meer geworfen werden sollte ein."},{t="Zwergische Ingenieurskunst im Kleinformat",b="Im Paket liegt eine Replik des Eisenschmiede-Luftgewehrs, eine Würdigung der Schusswaffenkunst der Zwergenhauptstadt. Zwergische Gebirgsjäger und Scharfschützen tragen tödliche Waffen durch Dun Morogh. Repliken wie diese erinnern an die kunstvoll gearbeiteten Läufe und pneumatischen Mechanismen, die Handwerker aus Eisenschmiede perfektioniert haben."}},faq={{q="Wer hat dieses Paket geschickt?",a="Weder der Bote noch der ursprüngliche Absender hinterließen einen Namen oder eine Erklärung. Laut dem Verwalter hinterließ jemand ein an Euch adressiertes Paket, bestand darauf, dass Ihr es abholen würdet, und verschwand, bevor Fragen gestellt werden konnten.",al={"wer hat das paket geschickt","absender des luftgewehrs","wer hat das gewehr hinterlassen"}},{q="Was wäre beinahe mit dem Paket geschehen?",a="Das Paket wäre beinahe mit dem nächtlichen Müll ins Meer geworfen worden. Der Verwalter sagte, dass er nichts einlagert und unerwünschten Kram regelmäßig ins Meer wirft.",al={"was sollte mit dem paket geschehen","müll im meer","paket weggeworfen"}},{q="Was befindet sich im Paket?",a="Das Paket enthält eine Replik des Eisenschmiede-Luftgewehrs, die für Euch als Würdigung zwergischer Schusswaffenkonstruktion hinterlassen wurde.",al={"was ist im paket","gewehrreplik paketinhalt","paketbelohnung"}},{q="Warum bewahrte der Verwalter das Paket auf?",a="Der Verwalter bewahrt weder Post noch Pakete auf. Der Bote eilte davon, bevor sich eine Gelegenheit bot, die Annahme zu verweigern.",al={"warum wurde es aufbewahrt","post aufbewahren","werden hier pakete aufbewahrt"}},{q="Warum gilt dies als Vermächtnisbelohnung?",a="Ein geheimnisvoller Wohltäter hinterließ an einem Außenposten ein besonderes Paket für einen erfahrenen Abenteurer, wo es bis zu dessen Ankunft auf Abholung wartete.",al={"warum heißt es vermächtnisbelohnung","geschichte der vermächtnisbelohnung","was bedeutet vermächtnis hier"}},{q="Ist die Gewehrreplik eine funktionsfähige Waffe?",a="Das Gewehr ist eine Replik eines Luftgewehrs aus Eisenschmiede, nach dem Vorbild ausgefeilter zwergischer Fernkampfwaffen und weniger eines Kampfgewehrs für die Front.",al={"ist das gewehr eine echte waffe","kann man damit schießen","funktion der replik"}}},fp="42,168,29.255.0,32.291.0,22.195.0,36.168.0,26.103.0,42.125.0,39.132.0,41.142.0"}
P.entries["quest:96369"] = {n="Bad News for Folkar",s="Commander Folkar muss nach dem Angriff der Naga die Nachrichten zusammentragen. Ihr überbringt ihm die Nachricht vom Tod von King Wrynn, ein Bericht mit schwerwiegender Bedeutung für die Allianz.",h="Commander Folkar muss nach dem Angriff der Naga die Nachrichten zusammentragen.",kw={"allianz","schlechte nachricht für folkar","commander folkar","horde","king wrynn","kor'kron","naga","sergeant ulka"},ang={["faction:Horde"]="Als Mitglied der Horde überbringt Ihr Commander Folkar eine Nachricht, die ihm wertvolle Erkenntnisse über die Allianz zu liefern scheint."},sec={{t="Nachricht für Folkar",b="Viele Kor'kron starben, um herauszufinden, was vor dem Angriff der Naga geschehen war. Ihr kehrt mit der Nachricht zu Commander Folkar zurück, und die Stärke der Allianz könnte davon abhängen, was er erfährt."},{t="Folkar antwortet",b="Commander Folkar erfährt, dass King Wrynn tot ist. Er trauert um die gefallenen Kor'kron, glaubt aber, dass ihr Tod wertvolle Erkenntnisse gebracht hat. Er sagt, Sturmwind und die Allianz seien verwundbar, dankt Euch für Euren Dienst an der Horde und plant aufzubrechen, um Sergeant Ulka zu finden."}},faq={{q="Welche Nachricht überbringe ich Commander Folkar?",a="Ihr sagt Commander Folkar, dass King Wrynn tot ist und während eines Fluchtversuchs vor dem Angriff der Naga getötet wurde.",al={"nachricht von folkar","was mit dem könig geschah"}},{q="Wer starb, um das herauszufinden?",a="Viele Kor'kron starben, um herauszufinden, dass King Wrynn tot war.",al={"tode der kor'kron","wer starb"}},{q="Warum ist diese Nachricht für die Allianz wichtig?",a="Commander Folkar glaubt, dass das Wissen um King Wrynns Tod die Allianz erschüttern könnte. Seiner Ansicht nach war sie noch nie so verwundbar.",al={"allianz verwundbar","warum schlecht für die allianz"}},{q="Was hat Folkar vor?",a="Commander Folkar sagt, er werde sich selbst einen Weg nach draußen bahnen und nach Sergeant Ulka sehen.",al={"was folkar als nächstes tut","wo folkar hingeht"}}},fp="19,161,15.172.0,14.263.1,38.108.0,23.53.0,42.129.0,28.83.0"}
P.entries["quest:96377"] = {n="State Secrets",s="Shaws rechte Hand, ein Goblin, kann vielleicht die in Westfall geborgenen Dokumente entziffern. Ihr bringt ihm die Kiste zum Durchsehen.",h="Shaws rechte Hand, ein Goblin, kann vielleicht die in Westfall geborgenen Dokumente entziffern.",kw={"dokumente","goblin","renzik","shaw","staatsgeheimnisse","westfall"},sec={{t="Die Dokumente",b="Ihr habt eine Schachtel mit Dokumenten in Westfall geborgen und zurückgebracht. Als Ihr sagt, sie stamme von unter einigen Dielen, glaubt Renzik Euch offensichtlich nicht. Jetzt untersucht Shaws rechte Hand, ein Goblin, die Schachtel. Seine Reaktion lässt vermuten, dass die Papiere wichtig sind, doch was sie enthalten, bleibt unklar."}},faq={{q="Wer sieht sich die Dokumente an?",a="Shaws rechte Hand, Renzik, untersucht die Kiste mit den Dokumenten.",al={"wer prüft die papiere","shaws goblin","wer ist der goblin"}},{q="Woher stammen die Dokumente?",a="Ihr habt sie in Westfall geborgen. Renzik tut die Geschichte, sie seien unter einigen Dielen gefunden worden, als lächerlich ab.",al={"wo papiere gefunden","fundort der dokumente","westfall-papiere"}},{q="Was hält Renzik von den Dokumenten?",a="Renzik reißt die Augen auf, als Ihr ihm die Kiste zeigt, doch seine Worte verraten nicht, was die Dokumente bedeuten.",al={"renziks reaktion","erkennt er sie wieder","papiere entziffern"}},{q="Was fragt Renzik Euch?",a="Renzik fragt, wo Ihr die Dokumente gefunden habt.",al={"was sagt er","renziks frage","was habt ihr ihm gesagt"}}},fp="13,125,13.283.0,27.66.0,34.103.0,40.102.0,25.42.0"}
P.entries["quest:96381"] = {n="A Bit of Wet Work",s="Sully McCleary sah Naga auf der Insel Alcaz an Land stürmen und fürchtet, dass die Insel angegriffen wird. Er bittet Euch, die Naga und ihre Anführerin anzugreifen.",h="Sully McCleary sah Naga auf der Insel Alcaz an Land stürmen und fürchtet, dass die Insel angegriffen wird.",kw={"insel alcaz","gefängnis von alcaz","lady proudmoore","naga","strashaz enchantresses","strashaz soldiers","sully mccleary","tidemistress ca'zass"},sec={{t="Naga auf Alcaz",b="Sully McCleary beobachtete die Küste der Insel Alcaz, während Ihr Lady Proudmoore belauschtet. Er glaubt, dass Naga die Insel angreifen, nachdem er viele von ihnen an Land stürmen sah. Ihre Anführerin, eine Zauberwirkerin, scheint sie zu lenken. Sully bittet Euch daher, die Naga niederzustrecken und ihm ihren Kopf zu bringen."}},faq={{q="Wer bittet um Hilfe?",a="Sully McCleary bittet Euch, die Naga anzugreifen, die er auf die Insel Alcaz stürmen sah.",al={"wer hat mich geschickt","wer ist sully","sully mccleary"}},{q="Was geschieht auf Alcaz?",a="Sully glaubt, dass die Insel Alcaz angegriffen werden könnte, weil er viele Naga an Land stürmen sah.",al={"naga auf alcaz","naga-angriff","was ist hier geschehen"}},{q="Wer ist die Anführerin der Naga?",a="Sully sah eine Zauberwirkerin, die den Naga Befehle zubrüllte. Ihr erfahrt, dass sie Tidemistress Ca'zass heißt.",al={"naga-boss","anführerin der naga","tidemistress"}},{q="Warum soll ich gegen die Naga vorgehen?",a="Sully sagt, dass die Naga niemandem freundlich gesinnt sind, und bittet Euch, ihm zu helfen, indem Ihr sie angreift.",al={"warum naga töten","warum gegen sie kämpfen","grund für die naga"}},{q="Wo sind die Naga?",a="Sully schickt Euch ins Gefängnis von Alcaz, um Euch den Naga entgegenzustellen.",al={"aufenthaltsort der naga","wo liegt alcaz","alcaz prison"}}},fp="17,145,13.292.0,23.77.0,27.85.0,23.95.0,30.83.0,19.55.0"}
P.entries["quest:96390"] = {n="Nip 'Em in the Bud",s="Dunkeleisenspione durchstreifen Dun Morogh, und Erdseher Farsen ruft um Hilfe. Nahe Eisenbands Truppenlager bedroht ihre Anwesenheit die Heimat der Bronzebärte.",h="Dunkeleisenspione durchstreifen Dun Morogh, und Erdseher Farsen ruft um Hilfe.",kw={"dunkeleisenkarte","dunkeleisenspion","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","nip 'em in the bud","underground map"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr beim Aufhalten feindlicher Späher in Dun Morogh, Eisenschmiedes Versorgungslinien und nahe Außenposten vor Sabotage zu schützen.",["race:Dwarf"]="Als Zwerg der Bronzebärte verteidigt Ihr Eure Heimat und begegnet alten Clanfehden, indem Ihr Dunkeleisenspione aus den Bergen Eurer Ahnen vertreibt."},sec={{t="Augen in der Kälte",b="Dunkeleisenspione haben die hohen Pässe und verschneiten Klippen von Dun Morogh überquert. Sie verstecken sich nahe Siedlungen und Ausgrabungen, wo schon wenige Beobachter einen Angriff ankündigen könnten. Erdseher Farsen erkennt die Gefahr und ruft Verteidiger der Allianz auf, sie aufzuspüren, bevor ihre Pläne voranschreiten."},{t="Bedrohung nahe Eisenbands Truppenlager",b="Die Spione sammeln sich nahe Eisenbands Truppenlager im östlichen Dun Morogh. Erdseher Farsen kennt ihre Absichten zunächst nicht. Beim Durchsuchen der Späher findet sich eine Underground Map, die beweist, dass sie mehr vorbereiten als die Beobachtung des Gebiets. Ihre Pläne erstrecken sich auf uralte Geheimnisse unter der Erde, darunter die Halle der Thanen."}},faq={{q="Wer vergibt die Quest Nip 'Em in the Bud?",a="Nachdem Ihr Farsen's Watch abgeschlossen habt, bittet Erdseher Farsen um Hilfe gegen Eindringlinge in Dun Morogh.",al={"questgeber nip 'em in the bud","wer startet nip 'em in the bud","farsen quest"}},{q="Warum sind Dunkeleisenspione in Dun Morogh?",a="Der Dunkeleisenclan schmiedet Pläne gegen seine Vettern, die Bronzebärte. Seine Spione beobachten Siedlungen im östlichen Dun Morogh und graben oder erkunden möglicherweise verschüttete Durchgänge nahe Eisenbands Truppenlager.",al={"warum dunkeleisenspione hier","was machen dunkeleisenzwerge in dun morogh","eisenband dunkeleisenspione"}},{q="Wo befinden sich die Dunkeleisenspione?",a="Die Spione sammeln sich nahe Eisenbands Truppenlager im östlichen Dun Morogh und beobachten es vom verschneiten Randgebiet aus.",al={"standort der spione","wo sind dunkeleisenspione","wo spione finden"}},{q="Was führt zu dieser Aufgabe?",a="Ihr kommt hierher, nachdem Ihr Euch für Farsen's Watch gemeldet habt. Die Verteidigung geht von der Ausschau nach Eindringlingen zur Jagd auf sie über.",al={"vorausgesetzte quest","was kommt vor nip 'em in the bud","nip 'em in the bud vorquest"}},{q="Was wird bei der Jagd auf diese Spione aufgedeckt?",a="Die gefallenen Spione tragen eine Dunkeleisenkarte bei sich. Sie zeigt, dass ihre Pläne unter die Erde reichen, zu Geheimnissen, die mit der Halle der Thanen verbunden sind.",al={"was hinterlassen spione","dunkeleisenkarte beute","folgequest nach nip 'em in the bud"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Zwerg in Dun Morogh, der ungewöhnliche seismische Aktivitäten und Bewegungen feindlicher Clans in den Bergen beobachtet.",al={"wer ist farsen","erdseher farsen hintergrundgeschichte"}}},fx={bdd12e65={q="Warum möchte Erdenrufer Farsen, dass sich um die Dunkeleisenspione gekümmert wird?",a="Erdenrufer Farsen weiß, dass jeder Stützpunkt der Dunkeleisenzwerge in Dun Morogh Gefahr für Eisenschmiede und die umliegenden Lande bedeutet. Obwohl ihre genauen Motive für ihn unklar bleiben, lädt das ungehinderte Agieren von Infiltratoren zu größerer Sabotage oder einem offenen Angriff ein. Er will ihre Präsenz sofort zerschlagen, bevor irgendein Plan, den sie vorbereiten, Fuß fassen kann.",al={"warum will farsen die spione tot sehen","erdenrufer farsen motiv","warum im keim ersticken"}}},fp="18,154,16.267.0,31.310.1,40.98.0,38.177.0,38.99.0,26.113.0,44.122.1,24.127.0"}
P.entries["quest:96391"] = {n="Underground Map",s="Nahe Eisenbands Truppenlager weist die Underground Map auf Kammern unter Eisenschmiede hin. Die von Dunkeleisenspionen erbeutete Karte zeigt mit ihren Runen einen verborgenen Weg, der zu uralten Hallen unter dem Berg vordringt. Ihr bringt sie zu Erdseher Farsen, um zu erkunden, was darunter liegt.",h="Nahe Eisenbands Truppenlager weist die Underground Map auf Kammern unter Eisenschmiede hin.",kw={"dunkeleisenkarte","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","eisenschmiede","underground map"},ang={["class:Shaman"]="Als Schamane könnt Ihr den Windstoß, der Euch zu Erdseher Farsen führt, als Warnung der Elementargeister vernehmen. Sie spüren unnatürliche Grabungen unter Dun Morogh.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass dieser unterirdische Weg unterbunden werden muss, um Eisenschmiede und den nördlichen Stützpfeiler der Allianz zu sichern.",["race:Dwarf"]="Als Zwerg der Bronzebeärte wisst Ihr, dass Dunkeleisentunnel direkt zum Fundament von Eisenschmiede eine schwerwiegende Verletzung der Grenzen der Hauptstadt darstellen."},sec={{t="Ein Plan zur Infiltration",b="Ihr findet das Pergament nahe Eisenbands Truppenlager, nachdem Ihr Euch um die Dunkeleisenspione gekümmert habt. Seine Zeichnungen zeigen ein verschlungenes Labyrinth von Straßen unter der Erde. Raue, gezackte Runen markieren Gänge, die tief unter der Erde verlaufen und unter Eisenschmiede zusammenlaufen. Ihr Verlauf deutet auf eine mögliche Bedrohung unter der Hauptstadt der Bronzebeärte hin, doch die Dunkeleisen-Anmerkungen bleiben unklar."},{t="Flüstern im Wind",b="Als Ihr die grobe Karte studiert, trägt ein unnatürlicher Windstoß das leise Murmeln einer Zwergenstimme heran. Sie drängt zu raschem Handeln und weist Euch zu Erdseher Farsen. Ihr überbringt ihm diese Warnung, wo sie frühe Bewegungen zu uralten, tief unter der Stadt versiegelten Hallen aufdecken und die Zuflucht des Bergkönigreichs bedrohen könnte."}},faq={{q="Woher stammt diese unterirdische Karte?",a="Dunkeleisenspione trugen die Karte bei sich, während sie die Umgebung von Eisenbands Truppenlager in Dun Morogh auskundschafteten. Ihr findet sie bei ihren Spähern in den Ausläufern der Berge.",al={"kartenbeute","wo karte finden","wie underground map erhalten"}},{q="Was zeigt die Karte?",a="Die Karte zeigt ein komplexes Netz unterirdischer Hauptstraßen und Tunnel, die sich durch die Erde schlängeln. Sie laufen unter Eisenschmiede zusammen.",al={"was zeigt die karte","kartendetails","zweck der dunkeleisenkarte"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein zwergischer Erdseher vom Nistgipfel, der mit dem tiefen Gestein und den Berggeistern verbunden ist. Er spürt unnatürliche Bewegungen unter der Erde und braucht die Karte, um den Durchbruch unter Eisenschmiede einzuschätzen.",al={"wo ist farsen","wer ist farsen","erdseher"}},{q="Warum graben die Dunkeleisenzwerge Tunnel unter Eisenschmiede?",a="Die Karte deutet auf einen möglichen Weg unter Eisenschmiede hin, doch ihre Dunkeleisen-Anmerkungen sind noch nicht entziffert. Erdseher Farsen muss sie untersuchen, bevor sich ihr Plan ermitteln lässt.",al={"warum graben dunkeleisenzwerge tunnel","dunkeleisenkomplott dun morogh"}},{q="Wozu führt diese Quest?",a="Die Übergabe der Karte an Erdseher Farsen setzt die Erkundung der Tiefen unter der Stadt in Gang. Sie führt zur Old Eisenschmiede Incursion und öffnet einen Weg zur Halle der Thanen.",al={"fortsetzung von underground map","nächste quest nach underground map"}},{q="In welcher Sprache sind die Runen der Karte verfasst?",a="Die Karte trägt die gezackte Runenschrift der Dunkeleisenzwerge. Wer sie findet, kann nicht sicher sein, was die Anmerkungen besagen.",al={"kartenrunen","sprache der dunkeleisenzwerge"}}},fx={["1c73103d"]={q="Warum muss die Dunkeleisenkarte zu Erdenrufer Farsen gebracht werden?",a="Die Karte zeigt ein alarmierendes Netzwerk von unterirdischen Tunneln und Wegen, die alle direkt unter Eisenschmiede zusammenlaufen. Ihre gezackten Dunkeleisenrunen erfordern eine Übersetzung, und die unheimliche Zwergenstimme, die auf dem Wind getragen wird, macht deutlich, dass Erdenrufer Farsen die mögliche unterirdische Bedrohung sofort untersuchen muss, um das Bergkönigreich vor der Gefahr aus dem Untergrund zu warnen.",al={"warum die karte zu farsen bringen","motiv der dunkeleisenkarte","warum die karte überbringen"}}},fp="15,270,27.360.0,20.309.1,41.148.0,23.127.0,24.205.0,49.168.0,29.182.1,45.115.0"}
P.entries["quest:96392"] = {n="Farsens Wacht",s="Nahe dem Steinbruch Gol'Bolar hält Erdseher Farsen nach Dunkeleisenbewegungen bei Eisenschmiede Ausschau. Der Wildhammer-Schamane leiht Euch seine Weitsicht und offenbart eine Bedrohung, die rasches Handeln erfordert.",h="Nahe dem Steinbruch Gol'Bolar hält Erdseher Farsen nach Dunkeleisenbewegungen bei Eisenschmiede Ausschau.",kw={"nistgipfel","dunkeleisen","dun morogh","erdseher","farsen","weitsicht","gol'bolar","die halle der thanen","wildhammer"},ang={["class:Shaman"]="Als Schamane erlebt Ihr die erdverbundene und spirituelle Sichtweise der Wildhammer-Tradition, die in den zerklüfteten Höhen von Nistgipfel wurzelt.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Dunkeleisenpläne in Dun Morogh aufzudecken und Eisenschmiede sowie die umliegenden Gebirgspässe zu schützen.",["race:Dwarf"]="Als Verteidiger der Bronzebeard hört Ihr eine Warnung von einem Vetter aus Nistgipfel. Sie zeigt, wie unverhohlen die Dunkeleisenzwerge inzwischen in Eurer Heimat auftreten."},sec={{t="Blick über den Kamm",b="Von seinem Posten über dem Steinbruch Gol'Bolar aus beobachtet Farsen die tieferen Lagen von Dun Morogh. Er kam von den zerklüfteten Höhen von Nistgipfel nach Süden und brachte das spirituelle Gespür eines Wildhammers mit. Die alten Künste seines Clans lassen ihn unterirdische Erschütterungen spüren und plötzliche Bewegungen an den Berghängen erkennen."},{t="Eine geliehene Vision",b="Farsen leiht Euch seine Weitsicht, eine schamanische Gabe, die den Blick über große Entfernungen trägt. Durch sie erkennt Ihr Gefahren jenseits von Troggs und wilden Bestien. Dunkeleisenzwerge sind nahe an das Industriezentrum von Eisenschmiede herangerückt und verschanzen sich dort. Ihrem Brückenkopf muss Einhalt geboten werden, bevor er sich festigt."}},faq={{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Wildhammer-Zwerg aus Nistgipfel im Hinterland, der Dun Morogh besucht. Seine schamanische Gabe lässt ihn Störungen im Land spüren und Bedrohungen aus der Ferne beobachten.",al={"erdseher farsen","wer ist farsen","farsen wildhammer"}},{q="Wo findet diese Wache statt?",a="Farsen hält oberhalb des Steinbruchs Gol'Bolar Wache, einer Bergbau-Ausgrabungsstätte der Bronzebeard im Osten von Dun Morogh.",al={"farsen standort","wo ist farsen","aussichtspunkt über dem steinbruch"}},{q="Welche Bedrohung enthüllt Farsen?",a="Farsens Weitsicht enthüllt einen nahen Brückenkopf feindlicher Dunkeleisenzwerge, eine akute Gefahr für die Region.",al={"was zeigt die weitsicht","dunkeleisenbedrohung","farsens vision"}},{q="Wie hängt dies mit der Halle der Thanen zusammen?",a="Die Untersuchung der Dunkeleisenpräsenz, die während Farsens Wache sichtbar wird, beginnt die Aufgabenreihe für jene, die Einlass in die Halle der Thanen suchen.",al={"zugang zur halle der thanen","questreihe der halle der thanen"}},{q="Warum beteiligt sich ein Wildhammer-Zwerg an der Verteidigung von Dun Morogh?",a="Die Wildhammer sind im Hinterland beheimatet, doch Verwandtschaft und ihre gemeinsame Feindschaft gegenüber den Dunkeleisenzwergen führen Reisende wie Farsen bisweilen in die angestammten Bronzebeard-Lande von Dun Morogh.",al={"warum ist ein wildhammer hier","nistgipfel zwerg dun morogh"}},{q="Was folgt unmittelbar auf den Abschluss von Farsen's Watch?",a="Nachdem Ihr durch Farsens Vision die Infiltration der Dunkeleisenzwerge gesehen habt, drängt er Euch mit 'Nip 'Em in the Bud', den vorrückenden Feind zurückzuschlagen.",al={"nächste quest","was folgt auf farsen's watch","nip em in the bud"}}},fx={["73fc96dc"]={q="Warum möchte Erdenrufer Farsen, dass dies getan wird?",a="Während er von Nistgipfel durch Dun Morogh reiste, entdeckte Erdenrufer Farsen Anzeichen von Aggressionen der Dunkeleisenzwerge, die nahe dem Steinbruch Gol'Bolar überhandnahmen. Bevor er handelt oder Alarm schlägt, möchte der Schamane, dass Ihr die aufkeimende Gefahr aus erster Hand durch seine hellseherische Magie miterlebt, um sicherzustellen, dass die Verteidiger von Eisenschmiede das wahre Ausmaß der feindlichen Infiltration erfassen, bevor sie außer Kontrolle gerät.",al={"warum farsens wache","farsens motiv","warum will farsen, dass ich nachsehe"}}},fp="14,184,21.288.0,17.291.0,24.181.0,33.98.0,31.105.0,44.136.0,59.184.0,52.143.0"}
P.entries["quest:96393"] = {n="Old Eisenschmiede Incursion",s="Unter Eisenschmiede schickt Euch Earthseer Farsen zum letzten Teil der Untersuchung in die Halle der Thanen. Dort stellt Ihr Euch der Bedrohung durch die Dunkeleisen und erstattet König Magni Bronzebart Bericht.",h="Unter Eisenschmiede schickt Euch Earthseer Farsen zum letzten Teil der Untersuchung in die Halle der Thanen.",kw={"dunkeleisen","dirgehammer","farsen","vorstoß","eisenschmiede","kharanos","magni","thanen"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, einen Vorstoß aufzuhalten, der einen verheerenden Überraschungsangriff auf die wichtigste Festung Eurer Fraktion in den Östlichen Königreichen androht.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Dunkeleiseneindringlinge in den vergessenen Gewölben unter dem High Seat in Eure angestammte Festung eingedrungen sind."},sec={{t="Vorstoß in die Gewölbe",b="Die unterirdische Karte offenbart die Bewegungen der Dunkeleisen, und Earthseer Farsen erkennt den Drahtzieher hinter dem Eindringen. Der Eingang zur Halle der Thanen liegt tief in den uralten steinernen Hallen der Altstadt von Eisenschmiede. Während sich die Oberstadt um Angelegenheiten an der Oberfläche kümmert, schleichen Truppen der Dunkeleisen in ruhende Höhlen unter dem Königreich."},{t="Befehlshaber Durgen Dirgehammer",b="Earthseer Farsen übersetzt erbeutete Dokumente der Dunkeleisen und nennt den Befehlshaber: Durgen Dirgehammer. Tief in den unteren Gewölben bedroht Durgen das Herz des Bergkönigreichs der Bronzebeard. Erreicht ihn, streckt ihn nieder und bringt seinen abgetrennten Kopf hinauf zu König Magni Bronzebart."},{t="Audienz beim König",b="Durgen Dirgehammers Kopf bestätigt König Magni Bronzebart die Bedrohung durch die Dunkeleisen unter den uralten Wurzeln der Stadt. Ihr bringt einen Beweis des Sieges und einen persönlichen Gruß von Farsen, Magnis altem Freund. Die Untersuchung endet damit, dass Magni weiß, was in der Tiefe lauert."}},faq={{q="Was ist Old Eisenschmiede Incursion?",a="Earthseer Farsen schickt Euch in die Halle der Thanen unter der Altstadt von Eisenschmiede, um Euch dem Dunkeleisenbefehlshaber Durgen Dirgehammer zu stellen. Dies ist der letzte Abschnitt einer Untersuchung der Aktivitäten der Dunkeleisen unter Dun Morogh.",al={"old ironforge incursion quest","durgen dirgehammer quest"}},{q="Wo findet diese Quest statt?",a="Ihr betretet die Halle der Thanen, eine uralte Kammer tief im Grundgestein unter der Altstadt von Eisenschmiede und der Berghauptstadt.",al={"wo ist die halle der thanen","halle der thanen standort"}},{q="Wer ist Durgen Dirgehammer?",a="Durgen Dirgehammer befehligt den Vorstoß der Dunkeleisen in die Halle der Thanen unter der Altstadt von Eisenschmiede. Earthseer Farsen erfuhr seinen Namen aus geborgenen Dokumenten der Dunkeleisen.",al={"wer ist dirgehammer","durgen dirgehammer"}},{q="Wer vergibt die Quest, und bei wem wird sie abgegeben?",a="Nachdem Ihr die Underground Map geborgen habt, schickt Euch Earthseer Farsen zu König Magni Bronzebart in Eisenschmiede.",al={"questgeber old ironforge incursion","wer gibt old ironforge incursion ab"}},{q="Wie beginne ich die Questreihe, die hierherführt?",a="Beginnt mit A Visitor to Dun Morogh, angeboten von Beldin Stahlrost außerhalb von Kharanos in Dun Morogh.",al={"wie beginnt die quest zur halle der thanen","visitor to dun morogh start"}},{q="Welche Verbindung besteht zwischen Earthseer Farsen und König Magni?",a="Earthseer Farsen betrachtet sich als alten Freund von König Magni Bronzebart. Er bittet Euch, seine persönlichen Grüße auszurichten, wenn Ihr Durgen Dirgehammers Kopf im Thronsaal vorzeigt.",al={"farsen und magni","earthseer farsen hintergrundgeschichte"}}},fx={bdae81a8={q="Warum möchte Erdenrufer Farsen, dass Durgen Dirgehammer getötet wird?",a="Farsen deckte feindliche Bewegungen unter dem Berg auf und entschlüsselte Befehle, die Durgen Dirgehammer als den Kommandanten auswiesen, der den Einfall in die Altstadt von Eisenschmiede anführt. Die Präsenz der Dunkeleisen in der Halle der Thanen bedroht die Zwergenhauptstadt direkt von unten. Indem er Euch schickt, um ihren Anführer niederzustrecken, zielt Farsen darauf ab, den Angriff zu zerschlagen, bevor die Dunkeleisen sich verschanzen können, während er gleichzeitig einen unbestreitbaren Beweis für die Bedrohung direkt an König Magni Bronzebart sendet.",al={"farsens motiv","warum durgen dirgehammer töten","warum schickt euch farsen"}},["664606f0"]={q="Wozu dient Durgen Dirgehammers Kopf?",a="Ihr benötigt Durgen Dirgehammers Kopf als absoluten Beweis für König Magni Bronzebart, dass der Kommandant des unterirdischen Angriffs unschädlich gemacht wurde. Die direkte Übergabe der grausamen Trophäe an den Thronsaal bestätigt, dass die feindliche Dunkeleisen-Angriffstruppe in der Halle der Thanen ihren Anführer verloren hat, und überbringt Erdenrufer Farsens persönliche Warnung an den König.",al={"nutzen von durgen dirgehammers kopf","warum durgens kopf mitnehmen","kopf von durgen dirgehammer"}}},fp="23,182,20.333.0,18.279.1,22.260.1,32.210.0,33.116.0,26.168.0,41.105.0,50.96.0,63.179.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="Unter der Halle der Thanen beunruhigen rastlose Geister die Krypten, in denen Generationen verstorbener Zwerge ruhen. Die Pfleger fürchten sich, die Gewölbe zu betreten, und die Unruhe hat den Geist von Ambossar erreicht.",h="Unter der Halle der Thanen beunruhigen rastlose Geister die Krypten, in denen Generationen verstorbener...",kw={"ambossar","zwergengräber","zwergengeister","enraged apparitions","geister","die halle der thanen","geist von ambossar","the restless dead","tormented souls"},ang={["class:Priest"]="Als Priester seid Ihr dazu berufen, mit Seelen Zwiesprache zu halten und rastlose Tote zu friedlicher Ruhe zu führen, wenn Geister in Qual oder Zorn verharren.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Ahnengruften unter Eisenschmiede zu sichern, damit die Pfleger ihre heiligen Pflichten ohne Furcht vor rachsüchtigen Erscheinungen erfüllen können.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass in der Halle der Thanen die geehrten Toten und Ahnen Eures Volkes ruhen. Ihr plötzliches und heftiges Erwachen erschüttert das Herz des zwergischen Erbes."},sec={{t="Unruhe in den tiefen Gewölben",b="Generationen geehrter Zwerge ruhen in den Ahnengruften unter der Halle der Thanen. Ihre Geister schlafen gewöhnlich friedlich, doch etwas Unsichtbares hat sie heftig aufgewühlt. Seltsame Geräusche steigen aus den unteren Gewölben auf und verängstigen die Pfleger. Sie weigern sich, diese Kammern zu betreten oder ihren Pflichten nachzukommen, bis die Ordnung wiederhergestellt ist. Nun werden Abenteurer gerufen, um die aufgewühlten Seelen zu besänftigen."},{t="Die Ahnen besänftigen",b="Die Geister in der Halle der Thanen haben einen leichten Schlaf. Was auch immer die unteren Grüfte störte, weckte Enraged Apparitions und Tormented Souls und verwandelte heiligen Boden in einen gefährlichen Spukort. Auch der verehrte Geist von Ambossar ist erwacht. Eine respektvolle, doch feste Hand muss den Zorn der Ahnen bezwingen und den Frieden in den Katakomben wiederherstellen."}},faq={{q="Worum geht es in der Quest The Restless Dead?",a="Eine unbekannte Störung hat die Geister in den Krypten unter der Halle der Thanen aufgewühlt. Die Pfleger fürchten sich, sie zu betreten, solange die Erscheinungen aufgebracht sind.",al={"was ist the restless dead","was ist diese quest","questüberblick restless dead"}},{q="Warum sind die Geister erwacht?",a="Eine unbekannte Störung in den tiefen Gewölben hat die dort bestatteten Toten geweckt. Die Geister in der Halle der Thanen haben einen leichten Schlaf, und was auch immer in den Grüften geschah, versetzte sie in Zorn und Qual.",al={"warum sind die geister zornig","wer hat die grüfte gestört","warum sind die erscheinungen wach"}},{q="Wo ereignet sich diese Störung?",a="Die Störung ereignet sich in den Krypten und Gewölben unter der Halle der Thanen in Eisenschmiede, einer Ruhestätte der Ahnen, in der uralte Zwergengeister bestattet sind.",al={"wo ist die halle der thanen","wo erscheinen ruhelose tote","halle der thanen standort"}},{q="Wer ist der Geist von Ambossar?",a="Ambossar ist ein uralter und bedeutender Geist, der in den tiefen Grüften der Halle der Thanen ruht. Dieser große Geist erwachte zusammen mit geringeren Erscheinungen und muss zu friedlicher Ruhe zurückfinden.",al={"wer ist der geist von ambossar","geist von ambossar hintergrundgeschichte","wer ist ambossars geist"}},{q="Warum brauchen die Pfleger die Hilfe eines Abenteurers?",a="Die Pfleger kümmern sich um die Krypten und verrichten ihre regelmäßigen Pflichten in der Halle der Thanen. Zornige Geister durchstreifen die Hallen, weshalb die Pfleger sich weigern, die unteren Gewölbe zu betreten, bis die Gefahr vorüber ist.",al={"wer sind die pfleger","warum brauchen die pfleger hilfe","pfleger halle der thanen"}},{q="Welche Geister suchen die Halle der Thanen heim?",a="Enraged Apparitions, Tormented Souls und der große Geist von Ambossar suchen die aufgewühlten Gewölbe heim. Sie alle wurden aufgeschreckt und halten nun angriffslustig Wache in den Grabkammern.",al={"welche arten von geistern sind dort unten","erscheinungen in der halle der thanen","arten ruheloser toter"}}},fp="17,207,30.381.0,22.328.1,38.153.0,30.187.0,39.152.0,30.182.0,45.190.0,38.169.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="In der Halle der Thanen wird Faldrim Ambossars Geist noch immer von einem alten Groll geplagt. Sein geisterhafter Diener bittet Reisende, ihm Frieden zu bringen.",h="In der Halle der Thanen wird Faldrim Ambossars Geist noch immer von einem alten Groll geplagt.",kw={"an ancient grudge","ambossar","zwergengeist","faldrim anvilmar","geisterhafter diener","die halle der thanen","rastloser geist","thane"},ang={["class:Paladin"]="Als Paladin übernehmt Ihr die ernste Pflicht, den leidenden Toten Frieden zu bringen.",["class:Priest"]="Als Priester wisst Ihr, dass anhaltender Groll und ungesühnter Kummer einen Geist an die stoffliche Welt binden können, lange nachdem der Körper zu Staub zerfallen ist.",["race:Dwarf"]="Als Zwerg seht Ihr eine ernüchternde Mahnung, dass ein uralter Groll selbst den Tod überdauern kann."},sec={{t="Eine Bitte aus dem Grab",b="Ein geisterhafter Diener verweilt in der Halle der Thanen, wo Faldrim Anvilmar einst herrschte. Der Geist kann kaum durch den Schleier zwischen den Lebenden und den Toten sprechen. Er bittet Euch, den rastlosen Geist seines Herrn zu besänftigen. Er sucht Frieden für ihn, nicht Freiheit für sich selbst."},{t="Die Last der Vergangenheit",b="Faldrim Anvilmar bleibt durch einen uralten Groll an die stoffliche Welt gebunden. Sein Geist ist aufgewühlt und feindselig. Er kann keine Ruhe finden, bis ihm jemand gewaltsam Erlösung verschafft."}},faq={{q="Wer ist Faldrim Anvilmar?",a="Faldrim Anvilmar war ein Zwergenthane, dessen rastloser Geist die Halle der Thanen heimsucht. Sein Geisterhafter Diener sagt, ein uralter Groll verzehre ihn und lasse ihn keine Ruhe finden.",al={"faldrim anvilmar hintergrund","wer ist faldrim","thane ambossar"}},{q="Wo befindet sich die Halle der Thanen?",a="Die Halle der Thanen liegt in Höhlen unter der Altstadt von Eisenschmiede, innerhalb der Zwergenhauptstadt Eisenschmiede.",al={"halle der thanen standort","wo ist die halle der thanen","halle der thanen eingang"}},{q="Warum ist der Geist von Faldrim Anvilmar feindselig?",a="Faldrim Ambossars Geist ist feindselig, weil ihn ein uralter Groll verzehrt. Der Geisterhafte Diener sagt, dieser Groll lasse den ehemaligen Thanen keine Ruhe finden.",al={"warum ist faldrim zornig","warum greift der thane an","an ancient grudge erklärung"}},{q="Wer vergibt die Quest An Ancient Grudge?",a="Ein Geisterhafter Diener in der Halle der Thanen bittet Euch, seinem ehemaligen Herrn Frieden zu bringen.",al={"wer startet an ancient grudge","geisterhafter diener quest","questgeber"}},{q="Was müsst Ihr tun, um die Quest abzuschließen?",a="Ihr stellt Euch Faldrim Ambossars Geist in der Halle der Thanen und besiegt ihn im Kampf, um ihn von seinen Qualen zu erlösen. Dann erstattet Ihr dem Geisterhaften Diener Bericht.",al={"wie an ancient grudge abschließen","faldrim zur ruhe betten","an ancient grudge questziel"}},{q="Hat Faldrim eine Verbindung zum Ort Ambossar?",a="Niemand weiß, ob Faldrim Anvilmar eine Verbindung zum Ort Ambossar im Coldridgetal hat. Sie teilen einen Namen, doch seine Familie und jede Verbindung zum Ort sind unbekannt.",al={"stammt faldrim aus ambossar","ambossar coldridgetal verbindung","familie ambossar"}}},fp="17,147,21.261.0,22.169.1,24.167.0,36.98.0,45.151.0,38.91.0,39.160.0,43.164.0"}
